INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:2.10','Śaṅkarācārya','gita.2.10','hi','translation','।।2.10।।यहाँ दृष्ट्वा तु पाण्डवानीकम् इस श्लोकसे लेकर न योत्स्य इति गोविन्दमुक्त्वा तूष्णीं बभूव ह इस श्लोकतकके ग्रन्थकी व्याख्या यों कर लेनी चाहिये कि यह प्रकरण प्राणियोंके शोक मोह आदि जो संसारके बीजभूत दोष है उनकी उत्पत्तिका कारण दिखलानेके लिये है। क्योंकि कथं भीष्ममहं संख्ये इत्यादि श्लोकोंद्वारा अर्जुनने इसी तरह राज्य गुरु पुत्र मित्र सुहृद स्वजन सम्बन्धी और बान्धवोंके विषयमें यह मेरे हैं मैं इनका हूँ इस प्रकार अज्ञानजनित स्नेहविच्छेद आदि कारणोंसे होनेवाले अपने शोक और मोह दिखाये हैं। यद्यपि ( वह अर्जुन ) स्वयं ही पहले क्षात्रधर्मरूप युद्धमें प्रवृत्त हुआ था तो भी शोकमोहके द्वारा विवेकविज्ञानके दब जानेपर ( वह ) उस युद्धसे रुक गया और भिक्षाद्वारा जीवननिर्वाह करना आदि दूसरोंके धर्मका आचरण करनेके लिये प्रवृत्त हो गया। इसी तरह शोकमोह आदि दोषोंसे जिनका चित्त घिरा हुआ हो ऐसे सभी प्राणियोंसे स्वधर्मका त्याग और निषिद्ध धर्मका सेवन स्वाभाविक ही होता है। यदि वे स्वधर्मपालनमें लगे हुए हों तो भी उनके मन वाणी और शरीरादिकी प्रवृत्ति फलाकांक्षापूर्वक और अहंकारसहित ही होती है। ऐसा होनेसे पुण्यपाप दोनों बढ़ते रहनेके कारण अच्छेबुरे जन्म और सुखदुःखोंकी प्राप्तिरूप संसार निवृत्त नहीं हो पाता अतः शोक और मोह यह दोनों संसारके बीजरूप हैं। इन दोनोंकी निवृत्ति सर्वकर्मसंन्यासपूर्वक आत्मज्ञानके अतिरिक्त अन्य उपायसे नहीं हो सकती। अतः उसका ( आत्मज्ञानका ) उपदेश करने की इच्छावाले भगवान् वासुदेव सब लोगोंपर अनुग्रह करने के लिये अर्जुनको निमित्त बनाकर कहने लगे अशोच्यान् इत्यादि। इसपर कितने ही टीकाकार कहते हैं कि केवल सर्वकर्मसंन्यासपूर्वक आत्मज्ञाननिष्ठामात्रसे ही कैवल्यकी ( मोक्षकी ) प्राप्ति नहीं हो सकती किंतु अग्निहोत्रादि श्रौतस्मार्तकर्मोंसहित ज्ञानसे मोक्षकी प्राप्ति होती है यही सारी गीताका निश्चित अभिप्राय है। इस अर्थमें वे प्रमाण भी बतलाते हैं जैसे अथ चेत्त्वमिमं धम्यं सङ्ग्रामं न करिष्यसि कर्मण्येवाधिकारस्ते कुरु कर्मैव तस्मात्त्वम् इत्यादि। ( वे यह भी कहते हैं कि ) हिंसा आदिसे युक्त होनेके कारण वैदिक कर्म अधर्मका कारण है ऐसी शंका भी नहीं करनी चाहिये क्योंकि गुरु भ्राता और पुत्रादिकी हिंसा ही जिसका स्वरूप है ऐसा अत्यन्त क्रूर युद्धरूप क्षात्रकर्म भी स्वधर्म माना जानेके कारण अधर्मका हेतु नहीं है ऐसा कहनेवाले तथा उसके न करनेमें ततः स्वधर्म कीर्तिं च हित्वा पापमवाप्स्यसि इस प्रकार दोष बतलानेवाले भगवान्का यह कथन तो पहले ही सुनिश्चित हो जाता है कि जीवनपर्यन्त कर्म करें इत्यादि श्रुतिवाक्योंद्वारा वर्णित पशु आदिकी हिंसारूप कर्मोंको करना अधर्म नहीं है। परंतु वह ( उन लोगोंका कहना ) ठीक नहीं है क्योंकि भिन्नभिन्न दो बुद्धियोंके आश्रित रहनेवाली ज्ञाननिष्ठा और कर्मनिष्ठाका अलगअलग वर्णन है। अशोच्यान् इस श्लोकसे लेकर स्वधर्ममपि चावेक्ष्य इस श्लोकके पहलेके प्रकरणसे भगवान्ने जिस परमार्थआत्मतत्त्वका निरूपण किया है वह सांख्य है तद्विषयक जो बुद्धि है अर्थात् आत्मामें जन्मादि छहों विकारोंका अभाव होनेके कारण आत्मा अकर्ता है इस प्रकारका जो निश्चय उक्त प्रकरणके अर्थका विवेचन करनेसे उत्पन्न होता है वह सांख्यबुद्धि है वह जिन ज्ञानियोंके लिये उचित होती है ( जो उसके अधिकारी हैं ) वे सांख्ययोगी हैं। इस ( उपर्युक्त ) बुद्धिके उत्पन्न होनेसे पहलेपहले आत्माका देहादिसे पृथक्पन कर्तापन और भोक्तापन माननेकी अपेक्षा रखनेवाला जो धर्मअधर्मके विवेकसे युक्त मार्ग है मोक्षसाधनोंका अनुष्ठान करनेके लिये चेष्टा करना ही जिसका स्वरूप है उसका नाम योग है और तद्विषयक जो बुद्धि है वह योगबुद्धि है वह जिन कर्मियोंके लिये उचित होती है ( जो उसके अधिकारी हैं ) वे योगी हैं। इसी प्रकार भगवान्ने एषा तेऽभिहिता सांख्ये बुद्धिर्योगे त्विमां श्रृणु इस श्लोकसे अलगअलग दो बुद्धियाँ दिखलायी हैं। उन दोनों बुद्धियोंमेंसे सांख्यबुद्धिके आश्रित रहनेवाली सांख्ययोगियोंकी ज्ञानयोगसे ( होनेवाली ) निष्ठाको पुरा वेदात्मना मया प्रोक्ता इत्यादि वचनोंसे अलग कहेंगे। तथा योगबुद्धिके आश्रित रहनेवाली कर्मयोगसे ( होनेवाली ) निष्ठाको कर्मयोगेन योगिनाम् इत्यादि वचनोंसे अलग कहेंगे। कर्तापनअकर्तापन और एकताअनेकताजैसी भिन्नभिन्न बुद्धिके आश्रित रहनेवाले जो ज्ञान और कर्म हैं उन दोनोंका एक पुरुषमें होना असम्भव माननेवाले भगवान्ने ही स्वयं उपर्युक्त प्रकारसे सांख्यबुद्धि और योगबुद्धिका आश्रय लेकर अलगअलग दो निष्टाएँ कही हैं। जिस प्रकार ( गीताशास्त्रमें ) इन दोनों निष्ठाओंका अलगअलग वर्णन है वैसे ही शतपथ ब्राह्मणमें भी दिखलाया गया है। ( वहाँ ) इस आत्मलोकको ही चाहनेवाले वैराग्यशील ब्राह्मण संन्यास लेते हैं इस प्रकार सर्वकर्मसंन्यासका विधान करके उसी वाक्यके शेष वाक्यसे कहा है कि जिन हमलोगोंका यह आत्मा ही लोक है ( वे हम ) सन्ततिसे क्या ( सिद्ध ) करेंगे। वहीं यह भी कहा है कि प्राकृत आत्मा अर्थात् अज्ञानी मनुष्य धर्मजिज्ञासाके बाद और विवाहसे पहले तीनों लोकोंकी प्राप्तिके साधनरूप पुत्रकी तथा दैव और मानुष ऐसे दो प्रकारके धनकी इच्छा करने लगा। इनमें पितृलोककी प्राप्तिका साधनरूप कर्म तो मानुष धन है और देवलोककी प्राप्तिका साधनरूप विद्या देवधन है। इस तरह ( उपर्युक्त श्रुतिमें ) अविद्या और कामनावाले पुरुषके लिये ही श्रौतादि सम्पूर्ण कर्म बताये गये हैं।उन सब ( कर्मों ) से निवृत्त होकर संन्यास ग्रहण करते हैं इस कथनसे केवल आत्मलोकको चाहनेवाले निष्कामी पुरुषके लिये संन्यासका ही विधान किया है। यदि ( इसपर भी यह बात मानी जायगी कि ) भगवान्को श्रौतकर्म और ज्ञानका समुच्चय इष्ट है तो यह उपर्युक्त विभक्त विवेचन अयोग्य ठहरेगा। तथा ( ऐसा मान लेनेसे ) ज्यायसी चेत्कर्मणस्ते इत्यादि जो अर्जुन का प्रश्न है वह भी नहीं बन सकता। यदि ज्ञान और कर्मका एक पुरुषद्वारा एक साथ किया जाना असम्भव और कर्मकी अपेक्षा ज्ञानका श्रेष्ठत्व भगवान्ने पहले न कहा होता तो इस तरह अर्जुन बिना सुनी हुई बातका झूठे ही भगवान्में अध्यारोप कैसे करता कि ज्यायसी चेत्कर्मणस्ते मता बुद्धिः। यदि सभीके लिये ज्ञान और कर्मका समुच्चय कहा होता तो अर्जुनके लिये भी वह कहा ही गया था फिर दोनोंका समुचित उपदेश होते हुए यच्छ्रेय एतयोरेकं तन्मे ब्रूहि सुनिश्चितम् इस प्रकार दोनोंमेंसे एकके ही सम्बन्धमें प्रश्न कैसे होता क्योंकि पित्तकी शान्ति चाहनेवालेको वैद्यके द्वारा यह उपदेश दिया जानेपर कि मधुर और शीत पदार्थ सेवन करना चाहिये रोगोका यह प्रश्न नहीं बन सकता कि उन दोनोंमेंसे किसी एकको ही पित्तकी शान्तिका उपाय बतलाइये। यदि ऐसी कल्पना की जाय कि भगवान्द्वारा कहे हुए वचन न समझनेके कारण अर्जुनने प्रश्न किया है तो फिर भगवान्को प्रश्नके अनुरूप ही यह उत्तर देना चाहिये था कि मैंने तो ज्ञान और कर्मका समुच्चय बतलाया है तू ऐसा भ्रान्त क्यों हो रहा है परंतु प्रश्नसे विपरीत दूसरा ही उत्तर देना कि मैंने दो निष्ठाएँ पहले कही हैं ( उपर्युक्त कल्पनाके ) उपयुक्त नहीं है। इसके सिवा यदि केवल स्मार्तकर्मके साथ ही ज्ञानका समुच्चय माना जाय तो भी विभक्त वर्णन आदि सब उपयुक्त नहीं ठहरते। तथा ऐसा माननेसे युद्धरूप स्मार्तकर्म क्षत्रियका स्वधर्म है यह जाननेवाले अर्जुनका इस प्रकार उलाहना देना भी नहीं बन सकता कि तत् किं कर्मणि घोरे मां नियोजयसि। सुतरां यह सिद्ध हुआ कि गीताशास्त्रमें किञ्चिन्मात्र भी श्रौत या स्मार्त किसी भी कर्मके साथ आत्मज्ञानका समुच्चय कोई भी नहीं दिखा सकता। अज्ञानसे या आसक्ित आदि दोषोंसे कर्ममें लगे हुए जिस पुरुषको यज्ञसे दानसे या तपसे अन्तःकरण शुद्ध होकर परमार्थतत्त्वविषयक ऐसा ज्ञान प्राप्त हो जाता है कि यह सब एक ब्रह्म ही है और वह अकर्ता है। उसके कर्ममें कर्म और फल दोनों ही यद्यपि निवृत्त हो चुकते हैं तो भी लोकसंग्रहके लिये पहलेकी भाँति यत्नपूर्वक कर्मोंमें लगे रहनेवाले पुरुषका जो प्रवृत्तिरूप कर्म दिखलायी देता है वह वास्तवमें कर्म नहीं है जिससे कि ज्ञानके साथ उसका समुच्चय हो सके। जैसे भगवान् वासुदेवद्वारा किये हुए क्षात्रकर्मोंका मोक्षकी सिद्धिके लिये ज्ञानके साथ समुच्चय नहीं होता वैसे ही फलेच्छा और अहंकारके अभावकी समानता होनेके कारण ज्ञानीके कर्मोंका भी ( ज्ञानके साथ समुच्चय नहीं होता )। क्योंकि आत्मज्ञानी न तो ऐसा ही मानता है कि मैं करता हूँ और न उन कर्मोंका फल ही चाहता है। इसके सिवा जैसे कामसाधनरूप अग्निहोत्रादि कर्मोंका अनुष्ठान करने के लिये सकाम अग्निहोत्रादिमें लगे हुए स्वर्गादिकी कामनावाले अग्निहोत्रीकी कामना यदि आधा कर्म कर चुकनेपर नष्ट हो जाय और फिर भी उसके द्वारा वही अग्निहोत्रादि कर्म होता रहे तो भी वह काम्यकर्म नहीं होता ( वैसे ही ज्ञानीके कर्म भी कर्म नहीं हैं )। कुर्वन्नपि न लिप्यते न करोति न लिप्यते इत्यादि वचनोंसे भगवान् भी जगहजगह यही बात दिखलाते हैं। इसके सिवा जो पूर्वैः पूर्वतरं कृतम् कर्मणैव हि संसिद्धिमास्थिता जनकादयः इत्यादि वचन हैं उनको विभागपूर्वक समझना चाहिये। पू0 वह किस प्रकार समझें उ0 यदि वे पूर्वमें होनेवाले जनकादि तत्त्ववेत्ता होकर भी लोकसंग्रहके लिये कर्मोंमें प्रवृत्त थे तब तो यह अर्थ समझना चाहिये कि गुण ही गुणोंमें बरत रहे हैं इस ज्ञानसे ही वे परम सिद्धिको प्राप्त हुए अर्थात् कर्मसंन्यासकी योग्यता प्राप्त होनेपर भी कर्मोंका त्याग नहीं किया कर्म करतेकरते ही परम सिद्धिको प्राप्त हो गये। यदि वे जनकादि तत्त्वज्ञानी नहीं थे तो ऐसी व्याख्या करनी चाहिये कि वे ईश्वरके समर्पण किये हुए साधनरूप कर्मोंद्वारा चित्तशुद्धिरूप सिद्धिको अथवा ज्ञानोत्पत्तिरूप सिद्धिको प्राप्त हुए। यही बात भगवान् कहेंगे कि ( योगी ) अन्तःकरणकी शुद्धिके लिये कर्म करते हैं। तथा स्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः ऐसा कहकर फिर उस सिद्धिप्राप्त पुरुषके लिये सिद्धिं प्राप्तो यथा ब्रह्म इत्यादि वचनोंसे ज्ञाननिष्ठा कहेंगे। सुतरां गीताशास्त्रमें निश्चय किया हुआ अर्थ यही है कि केवल तत्त्वज्ञानसे ही मुक्ित होती है कर्मसहित ज्ञानसे नहीं। जैसा यह भगवान्का अभिप्राय है वैसा ही प्रकरणके अनुसार विभागपूर्वक उनउन स्थानोंपर हम आगे दिखलायेंगे।'),
('shankaracharya-ht:source:2.11','Śaṅkarācārya','gita.2.11','hi','translation','।।2.11।।इस प्रकार धर्मके विषयमें जिसका चित्त मोहित हो रहा है और जो महान् शोकसागरमें डूब रहा है ऐसे अर्जुनका बिना आत्मज्ञानके उद्धार होना असम्भव समझकर उस शोकसमुद्रसे अर्जुनका उद्धार करनेकी इच्छावाले भगवान् वासुदेव आत्मज्ञानकी प्रस्तावना करते हुए बोले जो शोक करने योग्य नहीं होते उन्हें अशोच्य कहते हैं भीष्म द्रोण आदि सदाचारी और परमार्थरूपसे नित्य होनेके कारण अशोच्य हैं। उन न शोक करने योग्य भीष्मादिके निमित्त तू शोक करता है कि वे मेरे हाथों मारे जायँगे मैं उनसे रहित होकर राज्य और सुखादिका क्या करूँगा तथा तू प्रज्ञावानोंके अर्थात् बुद्धिमानोंके वचन भी बोलता है अभिप्राय यह है कि इस तरह तू उन्मतकी भाँति मूर्खता और बुद्धिमत्ता इन दोनों परस्परविरुद्ध भावोंको अपनेमें दिखलाता है। क्योंकि जिनके प्राण चले गये हैं जो मर गये हैं उनके लिये और जिनके प्राण नहीं गये जो जीते हैं उनके लिये भी पण्डित आत्मज्ञानी शोक नहीं करते। पाण्डित्यको सम्पादन करके इस श्रुतिवाक्यानुसार आत्मविषयक बुद्धिका नाम पण्डा है और वह बुद्धि जिनमें हो वे पण्डित हैं। परंतु परमार्थदृष्टिसे नित्य और अशोचनीय भीष्म आदि श्रेष्ठ पुरुषोंके लिये तू शोक करता है अतः तू मढ है। यह अभिप्राय है।'),
('shankaracharya-ht:source:2.12','Śaṅkarācārya','gita.2.12','hi','translation','।।2.12।।वे भीष्मादि अशोच्य क्यों है इसलिये कि वे नित्य हैं। नित्य कैसे हैं किसी कालमें मैं नहीं था ऐसा नहीं किंतु अवश्य था अर्थात् भूतपूर्व शरीरोंकी उत्पत्ति और विनाश होते हुए भी मैं सदा ही था। वैसे ही तू नहीं था सो नहीं किंतु अवश्य था ये राजागण नहीं थे सो नहीं किंतु ये भी अवश्य थे। इसके बाद अर्थात् इन शरीरोंका नाश होनेके बाद भी हम सब नहीं रहेंगे सो नहीं किन्तु अवश्य रहेंगे। अभिप्राय यह है कि तीनों कालोंमें ही आत्मरूपसे सब नित्य हैं। यहाँ बहुवचनका प्रयोग देहभेदके विचारसे किया गया है आत्मभेदके अभिप्रायसे नहीं।'),
('shankaracharya-ht:source:2.13','Śaṅkarācārya','gita.2.13','hi','translation','।।2.13।।आत्मा किसके सदृश नित्य है इसपर दृष्टान्त कहते हैं जिसका देह है वह देही है उस देहीकी अर्थात् शरीरधारी आत्माकी इस वर्तमान शरीरमें जैसे कौमार बाल्यावस्था यौवनतरुणावस्था और जरा वृद्धावस्था ये परस्पर विलक्षण तीनों अवस्थाएँ होती हैं। इनमें पहली अवस्थाके नाशसे आत्मका नाश नहीं होता और दूसरी अवस्थाकी उत्पत्तिसे आत्माकी उत्पत्ति नहीं होती तो फिर क्या होता है कि निर्विकार आत्माको ही दूसरी और तीसरी अवस्थाकी प्राप्ति होती हुई देखी गयी है। वैसे ही निर्विकार आत्माको ही देहान्तरकी प्राप्ति अर्थात् इस शरीरसे दूसरे शरीरका नाम देहान्तर है उसकी प्राप्ति होती है ( होती हुईसी दीखती है )। ऐसा होनेसे अर्थात् आत्माको निर्विकार और नित्य समझ लेनेके कारण धीर बुद्धिमान् इस विषयमें मोहित नहीं होता मोहको प्राप्त नहीं होता।'),
('shankaracharya-ht:source:2.14','Śaṅkarācārya','gita.2.14','hi','translation','।।2.14।।यद्यपि आत्मा नित्य है ऐसे जाननेवाले ज्ञानीको आत्मविनाशनिमित्तक मोह होना तो सम्भव नहीं तथापि शीतउष्ण और सुखदुःखप्राप्तिजनित लौकिक मोह तथा सुखवियोगजनित और दुःखसंयोगजनित शोक भी होता हुआ देखा जाता है ऐसे अर्जुनके वचनोंकी आशंका करके भगवान् कहते हैं मात्रा अर्थात् शब्दादि विषयोंको जिनसे जाना जाय ऐसी श्रोत्रादि इन्द्रियाँ और इन्द्रियोंके स्पर्श अर्थात् शब्दादि विषयोंके साथ उनके संयोग वे सब शीतउष्ण और सुखदुःख देने वाले हैं अर्थात् शीतउष्ण और सुखदुःख देते हैं। अथवा जिनका स्पर्श किया जाता है वे स्पर्श अर्थात् शब्दादि विषय ( इस व्युत्पत्तिके अनुसार यह अर्थ होगा कि ) मात्रा और स्पर्श यानी श्रोत्रादि इन्द्रियाँ और शब्दादि विषय ( ये सब ) शीतउष्ण और सुखदुःख देनेवाले हैं। शीत कभी सुखरूप होता है कभी दुःखरूप इसी तरह उष्ण भी अनिश्चितरूप है परंतु सुख और दुःख निश्चितरूप हैं क्योंकि उनमें व्यभिचार ( फेरफार ) नहीं होता। इसलिये सुखदुःखसे अलग शीत और उष्णका ग्रहण किया गया है।जिससे कि वे मात्रास्पर्शादि ( इन्द्रियाँ उनके विषय और उनके संयोग ) उत्पत्तिविनाशशील हैं इससे अनित्य हैं अतः उन शीतोष्णादिको तू सहन कर अर्थात् उनमें हर्ष और विषाद मत कर।'),
('shankaracharya-ht:source:2.15','Śaṅkarācārya','gita.2.15','hi','translation','।।2.15।।शीतउष्णादि सहन करनेवालेको क्या ( लाभ ) होता है सो सुन सुखदुःखको समान समझनेवाले अर्थात् जिसकी दृष्टिमें सुखदुःख समान हैं सुखदुःखकी प्राप्तिमें जो हर्षविषादसे रहित रहता है ऐसे जिस धीर बुद्धिमान् पुरुषको ये उपर्युक्त शीतोष्णादि व्यथा नहीं पहँचा सकते अर्थात् नित्य आत्मदर्शनसे विचलित नहीं कर सकते। वह नित्य आत्मदर्शननिष्ठ और शीतोष्णादि द्वन्द्वोंको सहन करनेवाला पुरुष मृत्युसे अतीत हो जानेके लिये यानी मोक्षके लिये समर्थ होता है।'),
('shankaracharya-ht:source:2.16','Śaṅkarācārya','gita.2.16','hi','translation','।।2.16।।इसलिये भी शोक और मोह न करके शीतोष्णादिको सहन करना उचित है जिससे कि वास्तवमें अविद्यमान शीतोष्णादिका और उनके कारणोंका भावहोनापन अर्थात् अस्तित्व है ही नहीं क्योंकि प्रमाणोंद्वारा निरूपण किये जानेपर शीतोष्णादि और उनके कारण कोई पदार्थ ही नहीं ठहरते क्योंकि वे शीतोष्णादि सब विकार हैं और विकार सदा बदलता रहता है। जैसे चक्षुद्वारा निरूपण किया जानेपर घटादिका आकार मिट्टीको छोड़कर और कुछ भी उपलब्ध नहीं होता इसलिये असत् है वैसे ही सभी विकार कारणके सिवा उपलब्ध न होनेसे असत् हैं। क्योंकि उत्पत्तिसे पूर्व और नाशके पश्चात् उन सबकी उपलब्धि नहीं है। पू0 मिट्टी आदि कारणकी और उसके भी कारणकी अपने कारणसे पृथक् उपलब्धि नहीं होनेसे उनका अभाव सिद्ध हुआ फिर इसी तरह उसका भी अभाव सिद्ध होनेसे सबके अभावका प्रसङ्ग आ जाता है। उ0 यह कहना ठीक नहीं क्योंकि सर्वत्र सत्बुद्धि और असत्बुद्धि ऐसी दो बुद्धियाँ उपलब्ध होती हैं। जिस पदार्थको विषय करनेवाली बुद्धि बदलती नहीं वह पदार्थ सत् है और जिसको विषय करनेवाली बुद्धि बदलती हो वह असत् है। इस प्रकार सत् और असत्का विभाग बुद्धिके अधीन है। सभी जगह समानाधिकरणमें ( एक ही अधिष्ठानमें ) सबको दो बुद्धियाँ उपलब्ध होती हैं। नील कमलके सदृश नहीं किन्तु घड़ा है कपड़ा है हाथी है इस तरह सब जगह दोदो बुद्धियाँ उपलब्ध होती हैं। उन दोनों बुद्धियोंसे घटादिको विषय करनेवाली बुद्धि बदलती है यह पहले दिखलाया जा चुका है परंतु सत्बुद्धि बदलती नहीं। अतः घटादि बुद्धिका विषय ( घटादि ) असत् है क्योंकि उसमें व्यभिचार ( परिवर्तन ) होता है। परंतु सत्बुद्धिका विषय ( अस्तित्व ) असत् नहीं है क्योंकि उसमें व्यभिचार ( परिवर्तन ) नहीं होता। पू0 घटका नाश हो जानेपर घटविषयक बुद्धिके नष्ट होते ही सत् बुद्धि भी तो नष्ट हो जाती है। उ0 यह कहना ठीक नहीं क्योंकि वस्त्रादि अन्य वस्तुओंमें भी सत्बुद्धि देखी जाती है। वह सत्बुद्धि केवल विशेषणको ही विषय करनेवाली है। पू0 सत्बुद्धिकी तरह घटबुद्धि भी तो दूसरे घटमें दीखती है। उ0 यह ठीक नहीं क्योंकि वस्त्रादिमें नहीं दीखती। पू0 घटका नाश हो जानेपर उसमें सत्बुद्धि भी तो नही दीखती। उ0 यह ठीक नहीं क्योंकि ( वहाँ ) घटरूप विशेष्यका अभाव है। सत्बुद्धि विशेषणको विषय करनेवाली है अतः जब घटरूप विशेष्यका अभाव हो गया तब बिना विशेष्यके विशेषणकी अनुपपत्ति होनसे वह ( सत्बुद्धि ) किसको विषय करे पर विषयका अभाव होनेसे सत्बुद्धिका अभाव नहीं होता। पू0 घटादि विशेष्यका अभाव होनेसे एकाधिकरणता ( दोनों बुद्धियोंका एक अधिष्ठानमें होना ) युक्तियुक्त नहीं होती। उ0 यह ठीक नहीं क्योंकि मृगतृष्णिकादिमें अधिष्ठानसे अतिरिक्त अन्य वस्तुका ( जलका ) अभाव है तो भी यह जल है ऐसी बुद्धि होनेसे समानाधिकरणता देखी जाती है। इसलिये असत् जो शरीरादि एवं शीतोष्णादि द्वन्द्व और उनके कारण हैं उनका किसीका भी भाव अस्तित्व नहीं है। वैसे ही सत् जो आत्मतत्व है उसका अभाव अर्थात् अविद्यमानता नहीं है क्योंकि वह सर्वत्र अटल है यह पहले कह आये हैं। इस प्रकार सत्आत्मा और असत्अनात्मा इन दोनोंका ही यह निर्णय तत्त्वदर्शियोंद्वारा देखा गया है अर्थात् प्रत्यक्ष किया जा चुका है कि सत् सत् ही है और असत् असत् ही है। तत् यह सर्वनाम है और सर्व ब्रह्म ही है। अतः उसका नाम तत् है उसके भावको अर्थात् ब्रह्मके यथार्थ स्वरूपको तत्त्व कहते हैं उस तत्त्वको देखना जिनका स्वभाव है वै तत्त्वदर्शी हैं उनके द्वारा उपर्युक्त निर्णय देखा गया है। तू भी तत्त्वदर्शी पुरुषोंकी बुद्धिका आश्रय लेकर शोक और मोहको छोड़कर तथा नियत और अनियतरूप शीतोष्णादि द्वन्द्वोंको इस प्रकार मनमें समझकर कि ये सब विकार है ये वास्तवमें न होते हुए ही मृगतृष्णाके जलकी भाँति मिथ्या प्रतीत हो रहे हैं ( इनको ) सहन कर। यह अभिप्राय है।'),
('shankaracharya-ht:source:2.17','Śaṅkarācārya','gita.2.17','hi','translation','।।2.17।।तो जो निस्सन्देह सत् है और सदैव रहता है वह क्या है इसपर कहा जाता है
नष्ट न होना जिसका स्वभाव है वह अविनाशी है। तु शब्द असत्से सत्की विशेषता दिखानेके लिये है।
उसको तू ( अविनाशी ) जान समझ किसको जिस सत् शब्दवाच्य ब्रह्मसे यह आकाशसहित सम्पूर्ण विश्व आकाशसे घटादिके सदृश व्याप्त है।
इस अव्ययका अर्थात् जिसका व्यय नहीं होता जो घटताबढ़ता नहीं उसे अव्यय कहते हैं उसका विनाशअभाव ( करनेके लिये कोई भी समर्थ नहीं है )।
क्योंकि यह सत् नामक ब्रह्म अवयवरहित होनेके कारण देहादिकी तरह अपने स्वरूपसे नष्ट नहीं होता अर्थात् इसका व्यय नहीं होता।
तथा इसका कोई निजी पदार्थ नहीं होनेके कारण निजी पदार्थोंके नाशसे भी इसका नाश नहीं होता जैसे देवदत्त अपने धनकी हानिसे हानिवाला होता है ऐसे ब्रह्म नहीं होता।
इसलिये कहते हैं कि इस अविनाशी ब्रह्मका विनाश करनेके लिये कोई भी समर्थ नहीं है। कोई भी अर्थात् ईश्वर भी अपने आपका नाश नहीं कर सकता।
क्योंकि आत्मा ही स्वयं ब्रह्म है और अपने आपमें क्रियाका विरोध है।'),
('shankaracharya-ht:source:2.18','Śaṅkarācārya','gita.2.18','hi','translation','।।2.18।।तो फिर वह असत् पदार्थ क्या है जो अपनी सत्ताको छो़ड़ देता है ( जिसकी स्थिति बदल जाती है ) इसपर कहते हैं जिनका अन्त होता है विनाश होता है वे सब अन्तवाले हैं। जैसे मृगतृष्णादिमें रहनेवाली जलविषयक सत्बुद्धि प्रमाणद्वारा निरूपण की जानेके बाद विच्छिन्न हो जाती है वही उसका अन्त है वैसे ही ये सब शरीर अन्तवान् हैं तथा स्वप्न और मायाके शरीरादिकी भाँति भी ये सब शरीर अन्तवाले हैं। इसलिये इस अविनाशी अप्रमेय शरीरधारी नित्य आत्माके ये सब शरीर विवेकी पुरुषोंद्वारा अन्तवाले कहे गये हैं। यह अभिप्राय है। नित्य और अविनाशी यह कहना पुनरुक्ति नहीं है क्योंकि संसारमें नित्यत्वके और नाशके दोदो भेद प्रसिद्ध हैं। जैसे शरीर जलकर भस्मीभूत हुआ अदृश्य होकर भी नष्ट हो गया कहलाता है और रोगादिसे युक्त हुआ विपरीत परिणामको प्राप्त होकर विद्यमान रहता हुआ भी नष्ट हो गया कहलाता है। अतः अविनाशी और नित्य इन दो विशेषणोंका यह अभिप्राय है कि इस आत्माका दोनों प्रकारके ही नाशसे सम्बन्ध नहीं है। ऐसे नहीं कहा जाता तो आत्माका नित्यत्व भी पृथ्वी आदि भूतोंके सदृश होता। परंतु ऐसा नहीं होना चाहिये इसलिये इसको अविनाशी और नित्य कहा है। प्रत्यक्षादि प्रमाणोंसे जिसका स्वरूप निश्चित नहीं किया जा सके वह अप्रमेय है। पू0 जब कि शास्त्रद्वारा आत्माका स्वरूप निश्चित किया जाता है तब प्रत्यक्षादि प्रमाणोंसे उसका जान लेना तो पहले ही सिद्ध हो चुका ( फिर वह अप्रमेय कैसे है ) । उ0 यह कहना ठीक नहीं क्योंकि आत्मा स्वतः सिद्ध है। प्रमातारूप आत्माके सिद्ध होनेके बाद ही जिज्ञासुकी प्रमाणविषयक खोज ( शुरू ) होती है। क्योंकि मै अमुक हूँ इस प्रकार पहले अपनेको बिना जाने ही अन्य जाननेयोग्य पदार्थको जाननेके लिये कोई प्रवृत्त नहीं होता। तथा अपना आपा किसीसे भी अप्रत्यक्ष ( अज्ञात ) नहीं होता है। शास्त्र जो कि अन्तिम प्रमाण है वह आत्मामें किये हुए अनात्मपदार्थोंके अध्यारोपको दूर करनेमात्रसे ही आत्माके विषयमें प्रमाणरूप होता है अज्ञात वस्तुका ज्ञान करवानेके निमित्तसे नहीं। ऐसे ही श्रुति भी कहती है कि जो साक्षात् अपरोक्ष है वही ब्रह्म है जो आत्मा सबके हृदयमें व्याप्त है इत्यादि। जिससे कि आत्मा इस प्रकार नित्य और निर्विकार सिद्ध हो चुका है इसलिये तू युद्ध कर अर्थात् युद्धसे उपराम न हो। यहाँ ( उपर्युक्त कथनसे ) युद्धकी कर्तव्यताका विधान नहीं है क्योंकि युद्धमें प्रवृत्त हुआ ही वह ( अर्जुन ) शोकमोहसे प्रतिबद्ध होकर चुप हो गया था उसके कर्तव्यके प्रतिबन्धमात्रको भगवान् हटाते हैं। इसलिये युद्ध कर यह कहना अनुमोदनमात्र है विधि ( आज्ञा ) नहीं है। गीताशास्त्र संसारके कारणरूप शोकमोह आदिको निवृत्त करनेवाला है प्रवर्तक नहीं है। इस अर्थकी साक्षिभूत दो ऋचाओंको भगवान् उद्धृत करते हैं।'),
('shankaracharya-ht:source:2.19','Śaṅkarācārya','gita.2.19','hi','translation','।।2.19।।जो तू मानता है कि मेरेद्वारा युद्धमें भीष्मादि मारे जायँगे मैं ही उनका मारनेवाला हूँ यह तेरी बुद्धि ( भावना ) सर्वथा मिथ्या है। कैसे जिसका वर्णन ऊपरसे आ रहा है इस आत्माको जो मारनेवाला समझता है अर्थात् हननक्रियाका कर्ता मानता है और जो दूसरा ( कोई ) इस आत्माको देहके नाशसे मैं नष्ट हो गया ऐसे नष्ट हुआ मानता है अर्थात् हननक्रियाका कर्म मानता है। वे दोनों ही अहंप्रत्ययके विषयभूत आत्माको अविवेकके कारण नहीं जानते। अभिप्राय यह कि जो शरीरके मरनेसे आत्माको मैं मारनेवाला हूँ मैं मारा गया हूँ इस प्रकार जानते हैं वे दोनों ही आत्मस्वरूपसे अनभिज्ञ हैं। क्योंकि यह आत्मा विकाररहित होनेके कारण न तो किसीको मारता है और न मारा जाता है अर्थात् न तो हननक्रियाका कर्ता होता है और न कर्म होता है।'),
('shankaracharya-ht:source:2.20','Śaṅkarācārya','gita.2.20','hi','translation','।।2.20।।आत्मा निर्विकार कैसे है इसपर दूसरा मन्त्र ( इस प्रकार है ) यह आत्मा उत्पन्न नहीं होता अर्थात् उत्पत्तिरूप वस्तुविकार आत्मामें नहीं होता और यह मरता भी नहीं। वा शब्द यहाँ च के अर्थमें है। मरता भी नहीं इस कथनसे विनाशरूप अन्तिम विकारका प्रतिषेध किया जाता है। कदाचित् शब्द सभी विकारोंके प्रतिषेधके साथ सम्बन्ध रखता है। जैसे यह आत्मा न कभी जन्मता है न कभी मरता है इत्यादि। जिससे कि यह आत्मा उत्पन्न होकर अर्थात् उत्पत्तिरूप विकारका अनुभव करके फिर अभावको प्राप्त होनेवाला नहीं है इसलिये मरता नहीं क्योंकि जो उत्पन्न होकर फिर नहीं रहता वह मरता है इस प्रकार लोकमें कहा जाता है। वा शब्दसे और न शब्दसे यह भी पाया जाता है कि यह आत्मा शरीरकी भाँति पहले न होकर फिर होनेवाला नहीं है इसलिये यह जन्मता नहीं क्योंकि जो न होकर फिर होता है वहीं जन्मता है यह कहा जाता है। आत्मा ऐसा नहीं है इसलिये नहीं जन्मता। ऐसा होनेके कारण आत्मा अज है और मरता नहीं इसलिये नित्य है। यद्यपि आदि और अन्तके दो विकारोंके प्रतिषेधसे ( बीचके ) सभी विकारोंका प्रतिषेध हो जाता है तो भी बीचमें होनेवाले विकारोंका भी उनउन विकारोंके प्रतिषेधार्थक खासखास शब्दोंद्वारा प्रतिषेध करना उचित है। इसलिये ऊपर न कहे हुए जो यौवनादि सब विकार हैं उनका भी जिस प्रकार प्रतिषेध हो ऐसे भावको शाश्वत इत्यादि शब्दोंसे कहते हैं सदा रहनेवालेका नाम शाश्वत है शाश्वत शब्दसे अपक्षय ( क्षय होना ) रूप विकारका प्रतिषेध किया जाता है क्योंकि आत्मा अवयवरहित है इस कारण स्वरूपसे उसका क्षय नहीं होता और निर्गुण होनेके कारण गुणोंके क्षयसे भी उसका क्षय नहीं होता। पुराण इस शब्दसे अपक्षयके विपरीत जो वृद्धिरूप विकार है उसका भी प्रतिषेध किया जाता है। जो पदार्थ किसी अवयवकी उत्पत्तिसे पुष्ट होता है। वह बढ़ता है नया हुआ है ऐसे कहा जाता है परंतु यह आत्मा तो अवयवरहित होनेके कारण पहले भी नया था अतः पुराण है अर्थात् बढ़ता नहीं। तथा शरीरका नाश होनेपर यानी विपरीत परिणामको प्राप्त हो जानेपर भी आत्मा नष्ट नहीं होता अर्थात् दुर्बलतादि अवस्थाको प्राप्त नहीं होता। यहाँ हन्ति क्रियाका अर्थ पुनरुक्तिदोषसे बचनेके लिये विपरीत परिणाम समझना चाहिये इसलिये यह अर्थ हुआ कि आत्मा अपने स्वरूपसे बदलता नहीं। इस मन्त्रमें लौकिक वस्तुओंमें होनेवाले छः भावविकारोंका आत्मामें अभाव दिखलाया जाता है। आत्मा सब प्रकारके विकारोंसे रहित है यह इस मन्त्रका वाक्यार्थ है। ऐसा होनेके कारण वे दोनों ही ( आत्मस्वरूपको ) नहीं जानते। इस प्रकार पूर्व मन्त्रसे इसका सम्बन्ध है।'),
('shankaracharya-ht:source:2.21','Śaṅkarācārya','gita.2.21','hi','translation','।।2.21।।य एनं वेत्ति हन्तारम् इस मन्त्रसे आत्मा हननक्रियाका कर्ता और कर्म नहीं है यह प्रतिज्ञा करके तथा न जायते इस मन्त्रसे आत्माकी निर्विकारताके हेतुको बतलाकर अब प्रतिज्ञापूर्वक कहे हुए अर्थका उपसंहार करते हैं पूर्व मन्त्रमें कहे हुए लक्षणोंसे युक्त इस आत्माको जो अविनाशी अन्तिम भावविकाररूप मरणसे रहित नित्य रोगादिजनित दुर्बलता क्षीणता आदि विकारोंसे रहित अज जन्मरहित और अव्यय अपक्षयरूप विकारसे रहित जानता है। वह आत्मतत्त्वका ज्ञाताअधिकारी पुरुष कैसे ( किसको ) मारता है और कैसे ( किसको ) मरवाता है अर्थात् वह कैसे तो हननरूप क्रिया कर सकता और कैसे किसी मारनेवालेको नियुक्त कर सकता है अभिप्राय यह कि वह न किसीको किसी प्रकार भी मारता है और न किसीको किसी प्रकार भी मरवाता है। इन दोनों बातोंमे किम् और कथम् शब्द आक्षेपके बोधक हैं क्योंकि प्रश्नके अर्थमें यहाँ इनका प्रयोग सम्भव नहीं। निर्विकारतारूप हेतुका तात्पर्य सभी कर्मोंका प्रतिषेध करनेमें समान है इससे इस प्रकरणका अर्थ भगवान्को यही इष्ट है कि आत्मवेत्ता किसी भी कर्मका करने करवानेवाला नहीं होता। अकेली हननक्रियाके विषयमें आक्षेप करना उदाहरणके रूपमें है। पू0 कर्म न हो सकनेमें कौनसे खास हेतुको देखकर ज्ञानीके लिये भगवान् कथं स पुरुषः इस कथनसे कर्मविषयक आक्षेप करते हैं उ0 पहले ही कह आये हैं कि आत्माकी निर्विकारता ही ( ज्ञानीकर्तृक ) सम्पूर्ण कर्मोंके न होनेका खास हेतु है। पू0 कहा है सही परंतु अविक्रिय आत्मासे उसको जाननेवाला भिन्न है इसलिये ( यह ऊपर बतलाया हुआ ) खास कारण उपयुक्त नहीं है क्योंकि स्थाणुको अविक्रिय जाननेवालेसे कर्म नहीं होते ऐसा नहीं ऐसी शङ्का करें तो उ0 यह कहना ठीक नहीं क्योंकि आत्मा स्वयं ही जाननेवाला है। देह आदि संघातमें ( जड होनेके कारण ) ज्ञातापन नहीं हो सकता इसलिये अन्तमें देहादि संघातसे भिन्न आत्मा ही अविक्रिय ठहरता है और वही जाननेवाला है। ऐसे उस ज्ञानीसे कर्म होना असम्भव है अतः कथं स पुरुष यह आक्षेप उचित ही है। जैसे ( वास्तवमें ) निर्विकार होनेपर भी आत्मा बुद्धिवृत्ति और आत्माका भेदज्ञान न रहनेके कारण अविद्याके सम्बन्धसे बुद्धि आदि इन्द्रियोंद्वारा ग्रहण किये हुए शब्दादि विषयोंका ग्रहण करनेवाला मान लिया जाता है। ऐसे ही आत्मअनात्मविषयक विवेकज्ञानरूप जो बुद्धिवृत्ति है जिसे विद्या कहते हैं वह यद्यपि असत्रूप है तो भी उसके सम्बन्धसे वास्तव में जो अविकारी है ऐसा आत्मा ही विद्वान् कहा जाता है। ज्ञानीके लिये सभी कर्म असम्भव बतलाये हैं इस कारण भगवान्का यह निश्चय समझा जाता है कि शास्त्रद्वारा जिन कर्मोंका विधान किया गया है वे सब अज्ञानियोंके लिये ही विहित हैं। पू0 विद्या भी अज्ञानीके लिये ही विहित है क्योंकि जिसने विद्याको जान लिया उसके लिये पिसेको पीसनेकी भाँति विद्याका विधान व्यर्थ है। अतः अज्ञानीके लिये कर्म कहे गये हैं ज्ञानीके लिये नहीं इस प्रकार विभाग करना नहीं बन सकता। उ0 यह कहना ठीक नहीं क्योंकि कर्तव्यके भाव और अभावसे भिन्नता सिद्ध होती है अभिप्राय यह कि अग्निहोत्रादि कर्मोंका विधान करनेवाले विधिवाक्योंके अर्थको जान लेनेके बाद अनेक साधन और उपसंहारके सहित अमुक अग्निहोत्रादि कर्म अनुष्ठान करनेके योग्य है मैं कर्ता हूँ मेरा अमुक कर्तव्य है इस प्रकार जाननेवाले अज्ञानीके लिये जैसे कर्तव्य बना रहता है वैसे न जायते इत्यादि आत्मस्वरूपका विधान करनेवाले वाक्योंके अर्थको जान लेनेके बाद उस ज्ञानीके लिये कुछ कर्तव्य शेष नहीं रहता। क्योंकि ( ज्ञानीको ) मैं न कर्ता हूँ न भोक्ता हूँ इत्यादि जो आत्माके एकत्व और अकर्तृत्व आदिविषयक ज्ञान है इससे अतिरिक्त अन्य किसी प्रकारका भी ज्ञान नहीं होता। इस प्रकार यह ( ज्ञानी और अज्ञानीके कर्तव्यका ) विभाग सिद्ध होता है। जो अपनेको ऐसा समझता है कि मैं कर्ता हूँ उसकी यह बुद्धि अवश्य ही होगी कि मेरा अमुक कर्तव्य है उस बुद्धिकी अपेक्षासे वह कर्मोंका अधिकारी होता है इसीसे उसके लिये कर्म हैं। और उभौ तौ न विजानीतः इस वचनके अनुसार वही अज्ञानी है। क्योंकि पूर्वोक्त विशेषणोंद्वारा वर्णित ज्ञानीके लिये तो कथं स पुरुषः इस प्रकार कर्मोंका निषेध करनेवाले वचन हैं। सुतरां ( यह सिद्ध हुआ कि ) आत्माको निर्विकार जाननेवाले विशिष्ट विद्वान्का और मुमुक्षुका भी सर्वकर्मसंन्यासमें ही अधिकार है। इसीलिये भगवान् नारायण ज्ञानयोगेन सांख्यानां कर्मयोगेन योगिनाम् इस कथनसे सांख्ययोगी ज्ञानियों और कर्मी अज्ञानियोंका विभाग करके अलगअलग दो निष्ठा ग्रहण करवाते हैं। ऐसे ही अपने पुत्रसे भगवान् वेदव्यासजी कहते हैं कि ये दो मार्ग हैं इत्यादि तथा यह भी कहते हैं कि पहले क्रियामार्ग और पीछे संन्यास। इसी विभागको बारंबार भगवान् दिखलायेंगे। जैसे अहंकारसे मोहित हुआ अज्ञानी मैं कर्ता हूँ ऐसे मानता है तत्त्ववेत्ता मैं नहीं करता ऐसे मानता है तथा सब कर्मोंका मनसे त्यागकर रहता है इत्यादि। इस विषयमें कितने ही अपनेको पण्डित समझनेवाले कहते हैं कि जन्मादि छः भावविकारोंसे रहित निर्विकार अकर्ता एक आत्मा मैं ही हूँ ऐसा ज्ञान किसीको होता ही नहीं कि जिसके होनेसे सर्वकर्मोंके संन्यासका उपदेश किया जा सके। यह कहना ठीक नहीं। क्योंकि ( ऐसा मान लेनेसे ) न जायते इत्यादि शास्त्रका उपदेश व्यर्थ होगा। उनसे यह पूछना चाहिये कि जैसे शास्त्रोपदेशकी सामर्थ्यसे कर्म करनेवाले मनुष्यको धर्मके अस्तित्वका ज्ञान और देहान्तरकी प्राप्तिका ज्ञान होता है उसी तरह उसी पुरुषको शास्त्रसे आत्माकी विर्विकारता अकर्तृत्व और एकत्व आदिका विज्ञान क्यों नहीं हो सकता यदि वे कहें कि ( मनबुद्धि आदि ) करणोंसे आत्मा अगोचर है इस कारण ( उसका ज्ञान नहीं हो सकता )। तो यह कहना ठीक नहीं। क्योंकि मनके द्वारा उस आत्माको देखना चाहिये यह श्रुति है अतः शास्त्र और आचार्यके उपदेशद्वारा एवं शम दम आदि साधनोंद्वारा शुद्ध किया हुआ मन आत्मदर्शनमें करण ( साधन ) है। इस प्रकार उस ज्ञानप्राप्तिके विषयमें अनुमान और आगमप्रमाणोंके रहते हुए भी यह कहना कि ज्ञान नहीं होता साहसमात्र है। यह तो मान ही लेना चाहिये कि उत्पन्न हुआ ज्ञान अपनेसे विपरीत अज्ञानको अवश्य नष्ट कर देता है। वह अज्ञान मैं मारनेवाला हूँ मैं मारा गया हूँ ऐसे मारनेवाले दोनों नहीं जानते इन वचनोंद्वारा पहले दिखलाया ही था फिर यहाँ भी यह बात दिखायी गयी है कि आत्मामें हननक्रियाका कर्तृत्व कर्मत्व और हेतुकर्तृत्व अज्ञानजनति है। आत्मा निर्विकार होनेके कारण कर्तृत्व आदि भावोंका अविद्यामूलक होना सभी क्रियाओंमे समान है। क्योंकि विकारवान् ही ( स्वयं ) कर्ता ( बनकर ) अपने कर्मरूप दूसरेको कर्ममें नियुक्त करता है कि तू अमुक कर्म कर। सुतरां ज्ञानीका कर्मोंमें अधिकार नहीं है यह दिखानेके लिये भगवान् वेदाविनाशिनम् कथं स पुरुषः इत्यादि वाक्योंसे सभी क्रियाओंमें समान भावसे विद्वान्के कर्ता और प्रयोजक कर्ता होनेका प्रतिषेध करते हैं। ज्ञानीका अधिकार किसमें है यह तो ज्ञानयोगेन सांख्यानाम् इत्यादि वचनोंद्वारा पहले ही बतलाया जा चुका है वैसे ही फिर भी सर्वकर्माणि मनसा इत्यादि वाक्योंसे सर्व कर्मोंका संन्यास ( भगवान् ) कहेंगे। पू0 ( उक्त श्लोकमें ) मनसा यह शब्द है इसलिये मानसिक कर्मोंका ही त्याग बतलाया है शरीर और वाणीसम्बन्धी कर्मोंका नहीं। उ0 यह कहना ठीक नहीं। क्योंकि सर्व कर्मोंको छोड़कर इस प्रकार कर्मोंके साथ सर्व विशेषण है। पू0 यदि मनसम्बन्धी सर्व कर्मोंका त्याग मान लिया जाय तो उ0 ठीक नहीं। क्योंकि वाणी और शरीरकी क्रिया मनोव्यापारपूर्वक ही होती है। मनोव्यापारके अभावमें उनकी क्रिया बन नहीं सकती। पू0 शास्त्रविहित कायिकवाचिक कर्मोंके कारणरूप मानसिक कर्मोंके सिवा अन्य सब कर्मोंका मनसे संन्यास करना चाहिये यह मान लिया जाय तो उ0 ठीक नहीं। क्योंकि न करता हुआ और न करवाता हुआ यह विशेषण साथमें है ( इसलिये तीनों तरह कर्मोंका संन्यास सिद्ध होता है। ) पू0 यह भगवान्द्वारा कहा हुआ सर्व कर्मोंका संन्यास तो मुमूर्षु के लिये है जीते हुएके लिये नहीं यह माना जाय तो उ0 ठीक नहीं। क्योंकि ऐसा मान लेनेसे नौ द्वारवाले शरीररूप पुरमें आत्मा रहता है इस विशेषणकी उपयोगिता नहीं रहती। कारण जो सर्वकर्मसंन्यास करके मर चुका है उसका न करते हुए और न करवाते हुए उस शरीरमें रहना सम्भव नहीं। पू0 उक्त वाक्यमें शरीरमें कर्मोंको रखकर इस तरह सम्बन्ध है शरीरमें रहता है इस प्रकार सम्बन्ध नहीं है ऐसा मानें तो उ0 ठीक नहीं है। क्योंकि सभी जगह आत्माको निर्विकार माना गया है। तथा आसन क्रियाको आधारकी अपेक्षा है और संन्यास को उसकी अपेक्षा नहीं है एवं स पूर्वक न्यास शब्दका अर्थ यहाँ त्यागना। है निक्षेप ( रख देना ) नहीं। सुतरां गीताशास्त्रमें आत्मज्ञानीका संन्यासमें ही अधिकार है कर्मोंमें नहीं। यही बात आगे चलकर आत्मज्ञानके प्रकरणमें हम जगहजगह दिखलायेंगे।'),
('shankaracharya-ht:source:2.22','Śaṅkarācārya','gita.2.22','hi','translation','।।2.22।।अब हम प्रकृत विषय वर्णन करेंगे। यहाँ ( प्रकरणमें ) आत्माके अविनाशित्वकी प्रतिज्ञा की गयी है वह किसके सदृश है सो कहा जाता है जैसे जगत्में मनुष्य पुरानेजीर्ण वस्त्रोंको त्याग कर अन्य नवीन वस्त्रोंको ग्रहण करते हैं वैसे ही जीवात्मा पुराने शरीरको छोड़कर अन्यान्य नवीन शरीरोंको प्राप्त करता है। अभिप्राय यह कि ( पुराने वस्त्रोंको छोड़कर नये धारण करनेवाले ) पुरुषकी भाँति जीवात्मा सदा निर्विकार ही रहता है।'),
('shankaracharya-ht:source:2.23','Śaṅkarācārya','gita.2.23','hi','translation','।।2.23।।आत्मा सदा निर्विकार किस कारणसे है सो कहते हैं इस उपर्युक्त आत्माको शस्त्र नहीं काटते अभिप्राय यह कि अवयवरहित होनेके कारण तलवार आदि शस्त्र इसके अङ्गोंके टुकड़े नहीं कर सकते। वैसे ही अग्नि इसको जला नहीं सकता अर्थात् अग्नि भी इसको भस्मीभूत नहीं कर सकता। जल इसको भिगो नहीं सकता क्योंकि सावयव वस्तुको ही भिगोकर उसके अङ्गोंको पृथक्पृथक् कर देनेमें जलकी सामर्थ्य है। निरवयव आत्मामें ऐसा होना सम्भव नहीं। उसी तरह वायु आर्द्र द्रव्यका गीलापन शोषण करके उसको नष्ट करता है अतः वह वायु भी इस स्वस्वरूप आत्माका शोषण नहीं कर सकता।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:2.24','Śaṅkarācārya','gita.2.24','hi','translation','।।2.24।।ऐसा होनेके कारण ( यह आत्मा न कटनेवाला न जलनेवाला न गलनेवाला और न सूखनेवाला है )। आपसमें एक दूसरेका नाश कर देनेवाले पञ्चभूत इस आत्माका नाश करनेके लिये समर्थ नहीं है। इसलिये यह नित्य है। नित्य होनेसे सर्वगत है। सर्वव्यापी होनेसे स्थाणु है अर्थात् स्थाणु ( ठूँठ ) की भाँति स्थिर है। स्थिर होनेसे यह आत्मा अचल है और इसीलिये सनातन है अर्थात् किसी कारणसे नया उत्पन्न नहीं हुआ है। पुराना है। इन श्लोकोंमें पुनरुक्तिके दोषका आरोप नहीं करना चाहिये क्योकि न जायते म्रियते वा इस एक श्लोकके द्वारा ही आत्माकी नित्यता और निर्विकारता तो कही गयी फिर आत्माके विषयमें जो भी कुछ कहा जाय वह इस श्लोकके अर्थसे अतिरिक्त नहीं है। कोई शब्दसे पुनरुक्त है और कोई अर्थसे ( पुनरुक्त है )। परंतु आत्मतत्त्व बड़ा दुर्बोध है सहज ही समझमें आनेवाला नहीं है इसलिये बारंबार प्रसंग उपस्थित करके दूसरेदूसरे शब्दोंसे भगवान् वासुदेव उसी तत्त्वका निरूपण करते हैं यह सोचकर कि किसी भी तरह वह अव्यक्त तत्त्व इन संसारी पुरुषोंके बुद्धिगोचर होकर संसारकी निवृत्तिका कारण हो।'),
('shankaracharya-ht:source:2.25','Śaṅkarācārya','gita.2.25','hi','translation','।।2.25।।तथा यह आत्मा बुद्धि आदि सब करणोंका विषय नहीं होनेके कारण व्यक्त नहीं होता ( जाना नहीं जा सकता ) इसलिये अव्यक्त है। इसीलिये यह अचिन्त्य है क्योंकि जो पदार्थ इन्द्रियगोचर होता है वही चिन्तनका विषय होता है। यह आत्मा इन्द्रियगोचर न होनेसे अचिन्त्य है। यह आत्मा अविकारी है अर्थात् जैसे दहीके जावन आदिसे दूध विकारी हो जाता है वैसे यह नहीं होता। तथा अवयवरहित ( निराकार ) होनेके कारण भी आत्मा अविक्रिय है क्योंकि कोई भी अवयवरहित ( निराकार ) पदार्थ विकारवान् नहीं देखा गया। अतः विकाररहित होनेके कारण यह आत्मा अविकारी कहा जाता है। सुतरां इस आत्माको उपर्युक्त प्रकारसे समझकर तुझे यह शोक नहीं करना चाहिये कि मैं इनका मारनेवाला हूँ मुझसे ये मारे जाते हैं इत्यादि।'),
('shankaracharya-ht:source:2.26','Śaṅkarācārya','gita.2.26','hi','translation','।।2.26।।औपचारिक रूपसे आत्माकी अनित्यता स्वीकार करके यह कहते हैं अथ च ये दोनों अव्यय औपचारिक स्वीकृतिके बोधक हैं। यदि तू इस आत्माको सदा जन्मनेवाला अर्थात् लोकप्रसिद्धिके अनुसार अनेक शरीरोंकी प्रत्येक उत्पत्तिके साथसाथ उत्पन्न हुआ माने तथा उनके प्रत्येक विनाशके साथसाथ सदा नष्ट हुआ माने। तो भी अर्थात् ऐसे नित्य जन्मने और नित्य मरनेवाले आत्माके निमित्त भी हे महाबाहो तुझे इस प्रकार शोक करना उचित नहीं है क्योंकि जन्मनेवालेका मरण और मरनेवालेका जन्म यह दोनों अवश्य ही होनेवाले हैं।'),
('shankaracharya-ht:source:2.27','Śaṅkarācārya','gita.2.27','hi','translation','।।2.27।।ऐसा होनेसे जिसने जन्म लिया है उसका मरण ध्रुव निश्चित है और जो मर गया है उसका जन्म ध्रुव निश्चित है इसलिये यह जन्ममरणरूप भाव अपरिहार्य है अर्थात् किसी प्रकार भी इसका प्रतिकार नहीं किया जा सकता इस अपरिहार्य विषयके निमित्त तुझे शोक करना उचित नहीं।'),
('shankaracharya-ht:source:2.28','Śaṅkarācārya','gita.2.28','hi','translation','।।2.28।।कार्यकरणके संघातरूप ही प्राणियोंको माने तो उनके उद्देश्यसे भी शोक करना उचित नहीं है क्योंकि अव्यक्त यानी न दीखना उपलब्ध न होना ही जिनकी आदि है ऐसे ये कार्यकरणके संघातरूप पुत्र मित्र आदि समस्त भूत अव्यक्तादि हैं अर्थात् जन्मसे पहले ये सब अदृश्य थे। उत्पन्न होकर मरणसे पहलेपहल बीचमें व्यक्त हैं दृश्य हैं। और पुनः अव्यक्तनिधन हैं अदृश्य होना ही जिनका निधन यानी मरण है उनको अव्यक्तनिधन कहते हैं अभिप्राय यह कि मरनेके बाद भी ये सब अदृश्य हो ही जाते हैं। ऐसे ही कहा भी है कि यह भूतसंघात अदर्शनसे आया और पुनः अदृश्य हो गया। न वह तेरा है और न तू उसका है व्यर्थ ही शोक किस लिये सुतरां इनके विषयमें अर्थात् बिना हुए ही दीखने और नष्ट होनेवाले भ्रान्तिरूप भूतोंके विषयमें चिन्ता ही क्या है रोनापीटना भी किस लिये है।'),
('shankaracharya-ht:source:2.29','Śaṅkarācārya','gita.2.29','hi','translation','।।2.29।।जिसका प्रकरण चल रहा है यह आत्मतत्त्व दुर्विज्ञेय है। सर्वसाधारणको भ्रान्ति करा देनेवाले विषयमें केवल एक तुझे ही क्या उलाहना दूँ यह आत्मा दुर्विज्ञेय कैसे है सो कहते हैं पहले जो नहीं देखा गया हो अकस्माद् दृष्टिगोचर हुआ हो ऐसे अद्भुत पदार्थका नाम आश्चर्य है उसके सदृशका नाम आश्चर्यवत् है इस आत्माको कोई ( महापुरुष ) ही आश्चर्यमय वस्तुकी भाँति देखता है। वैसे ही दूसरा ( कोई एक ) इसको आश्चर्यवत् कहता है अन्य ( कोई ) इसको आश्चर्यवत् सुनता है एवं कोई इस आत्माको सुनकर देखकर और कहकर भी नहीं जानता। अथवा जो इस आत्माको देखता है वह आश्चर्यके तुल्य है जो कहता है और जो सुनता है वह भी ( आश्चर्यके तुल्य है )। अभिप्राय यह कि अनेक सहस्रोंमेंसे कोई एक ही ऐसा होता है। इसलिये आत्मा बड़ा दुर्बोध है।'),
('shankaracharya-ht:source:2.30','Śaṅkarācārya','gita.2.30','hi','translation','।।2.30।।अब यहाँ प्रकरणके विषयका उपसंहार करते हुए कहते हैं यह जीवात्मा सर्वव्यापी होनेके कारण सबके स्थावरजंगम आदि शरीरोंमें स्थित है तो भी अवयवरहित और नित्य होनेके कारण सदा सब अवस्थाओंमें अवश्य ही है। जिससे कि सम्पूर्ण प्राणियोंके शरीरोंका नाश किये जानेपर भी इस आत्माका नाश नहीं किया जा सकता इसलिये भीष्मादि सब प्राणियोंके उद्देश्यसे तुझे शोक करना उचित नहीं है।'),
('shankaracharya-ht:source:2.31','Śaṅkarācārya','gita.2.31','hi','translation','।।2.31।।यहाँ यह कहा गया कि परमार्थतत्त्वकी अपेक्षासे शोक या मोह करना नहीं बन सकता। केवल इतना ही नहीं कि परमार्थतत्त्वकी अपेक्षासे शोक और मोह नहीं बन सकते किंतु क्षत्रियके लिये जो युद्धरूप स्वधर्म है उसे देखकर भी तुझे कम्पित होना उचित नहीं है अभिप्राय यह कि अपने स्वाभाविक धर्मसे विचलित होना ( हटना ) भी तुझे उचित नहीं है। क्योंकि वह युद्ध पृथ्वीविजयद्वारा धर्मपालन और प्रजारक्षणके लिये किया जाता है इसलिये धर्मसे ओतप्रोत परम धर्म्य है अतः उस धर्ममय युद्धके सिवा दूसरा कुछ क्षत्रियके लिये कल्याणप्रद नहीं है।'),
('shankaracharya-ht:source:2.32','Śaṅkarācārya','gita.2.32','hi','translation','।।2.32।।और भी वह युद्ध किसलिये कर्तव्य है सो कहते हैं हे पार्थ अनिच्छासे प्राप्त बिना माँगे मिले हुए ऐसे खुले हुए स्वर्गद्वाररूप युद्धको जो क्षत्रिय पाते हैं क्या वे सुखी नहीं हैं।'),
('shankaracharya-ht:source:2.33','Śaṅkarācārya','gita.2.33','hi','translation','।।2.33।।इस प्रकार कर्तव्यरूपसे प्राप्त होनेपर भी यदि तू यह धर्मयुक्त धर्मसे ओतप्रोत युद्ध नहीं करेगा तो उस युद्धके न करनेके कारण अपने धर्मको और महादेव आदिके साथ युद्ध करनेसे प्राप्त हुई कीर्तिको नष्ट करके केवल पापको ही प्राप्त होगा।'),
('shankaracharya-ht:source:2.34','Śaṅkarācārya','gita.2.34','hi','translation','।।2.34।।केवल स्वधर्म और कीर्तिका त्याग होगा इतना ही नहीं सब लोग तेरी बहुत दिनोंतक स्थायी रहनेवाली अपकीर्ति ( निन्दा ) भी किया करेंगे। धर्मात्मा शूरवीर इत्यादि गुणोंसे प्रतिष्ठा पाये हुए पुरुषके लिये अपकीर्ति मरणसे भी अधिक होती है। अभिप्राय यह है कि संभावित ( इज्जतदार ) पुरुषके लिये अपकीर्तिकी अपेक्षा मरना अच्छा है।'),
('shankaracharya-ht:source:2.35','Śaṅkarācārya','gita.2.35','hi','translation','।।2.35।।तथा जिन दुर्योधनादिके मतमें तू पहले बहुमत अर्थात् बहुत गुणोंसे युक्त माना जाकर अब लघुताको प्राप्त होगा वे दुर्योधन आदि महारथीगण तुझे कर्णादिके भयसे ही युद्धसे निवृत्त हुआ मानेंगे दया करके हट गया है ऐसा नहीं।'),
('shankaracharya-ht:source:2.36','Śaṅkarācārya','gita.2.36','hi','translation','।।2.36।।तथा वे तेरे शत्रुगण निवातकवचादिके साथ युद्ध करनेमें दिखलाये हुए तेरे सामर्थ्यकी निन्दा करते हुए बहुतसे अनेक प्रकारके न कहने योग्य वाक्य भी तुझे कहेंगे। उस निन्दाजनित दुःखसे अधिक बड़ा दुःख क्या है अर्थात् उससे अधिक कष्टकर कोई भी दुःख नहीं है।'),
('shankaracharya-ht:source:2.37','Śaṅkarācārya','gita.2.37','hi','translation','।।2.37।।पक्षान्तरमें कर्ण आदि शूरवीरोंके साथ युद्ध करने पर या तो उनके द्वारा मारा जाकर ( तू ) स्वर्गको प्राप्त करेगा अथवा कर्णादि शूरवीरोंको जीतकर पृथिवीका राज्य भोगेगा। अभिप्राय यह कि दोनों तरहसे तेरा लाभ ही है। जब कि यह बात है इसलिये हे कौन्तेय युद्धके लिये निश्चय करके खड़ा हो जा अर्थात् मैं या तो शत्रुओंको जीतूँगा या मर ही जाऊँगा ऐसा निश्चय करके खड़ा हो जा।'),
('shankaracharya-ht:source:2.38','Śaṅkarācārya','gita.2.38','hi','translation','।।2.38।।युद्ध स्वधर्म है यह मानकर युद्ध करनेवालेके लिये यह उपदेश है सुन सुखदुःखको समान तुल्य समझकर अर्थात् ( उनमें ) रागद्वेष न करके तथा लाभहानिको और जयपराजयको समान समझकर उसके बाद तू युद्धके लिये चेष्टा कर इस तरह युद्ध करता हुआ तू पापको प्राप्त नहीं होगा। यह प्रासङ्गिक उपदेश है। स्वधर्ममपि चावेक्ष्य इत्यादि श्लोकोंद्वारा शोक और मोहको दूर करनेके लिये लौकिक न्याय बतलाया गया है परंतु पारमार्थिक दृष्टिसे यह बात नहीं है। यहाँ प्रकरण परमार्थदर्शनका है जो कि पहले ( श्लोक 30 ) तक कहा गया है। अब शास्त्रके विषयका विभाग दिखलानेके लिये एषा तेऽभिहिता इस श्लोकद्वारा उस ( परमार्थदर्शन ) का उपसंहार करते हैं।'),
('shankaracharya-ht:source:2.39','Śaṅkarācārya','gita.2.39','hi','translation','।।2.39।।क्योंकि यहाँ शास्त्रके विषयका विभाग दिखलाया जानेसे यह होगा कि आगे चलकर ज्ञानयोगेन सांख्यानां कर्मयोगेन योगिनाम् इत्यादि जो दो निष्ठाओंको बतानेवाला शास्त्र है वह सुखपूर्वक समझाया जा सकेगा और श्रोतागण भी विषयविभागपूर्वक अनायास ही उसे ग्रहण कर सकेंगे। इसलिये कहते हैं मैंने तुझसे सांख्य अर्थात् परमार्थ वस्तुकी पहिचानके विषयमें यह बुद्धि यानी ज्ञान कह सुनाया। यह ज्ञान संसारके हेतु जो शोक मोह आदि दोष हैं उनकी निवृत्तिका साक्षात् कारण है। इसकी प्राप्तिके उपायरूप योगके विषयमें अर्थात् आसक्तिरहित होकर सुखदुःख आदि द्वन्द्वोंके त्यागपूर्वक ईश्वराराधनके लिये कर्म किये जानेवाले कर्मयोगके विषयमें और समाधियोगके विषयमें इस बुद्धिको जो कि अभी आगे कही जाती है सुन रुचि बढ़ानेके लिये उस बुद्धिकी स्तुति करते हैं हे अर्जुन जिस योगविषयक बुद्धिसे युक्त हुआ तू धर्माधर्म नामक कर्मरूप बन्धनको ईश्वरकृपासे होनेवाली ज्ञानप्राप्तिद्वारा नाश कर डालेगायह अभिप्राय है।'),
('shankaracharya-ht:source:2.40','Śaṅkarācārya','gita.2.40','hi','translation','।।2.40।।इसके सिवा और भी सुन आरम्भका नाम अभिक्रम है इस कर्मयोगरूप मोक्षमार्गमें अभिक्रमका यानी प्रारम्भका कृषि आदिके सदृश नाश नहीं होता। अभिप्राय यह कि योगविषयक प्रारम्भका फल अनैकान्तिक ( संशययुक्त ) नहीं है। तथा चिकित्सादिकी तरह ( इसमें ) प्रत्यवाय ( विपरीत फल ) भी नहीं होता है। तो क्या होता है इस कर्मयोगरूप धर्मका थोड़ासा भी अनुष्ठान ( साधन ) जन्ममरणरूप महान् संसारभयसे रक्षा किया करता है।'),
('shankaracharya-ht:source:2.41','Śaṅkarācārya','gita.2.41','hi','translation','।।2.41।।जो यह बुद्धि सांख्यके विषयमें कही गयी है और जो योगके विषयमें अब कही जानेवाली है वह हे कुरुनन्दन इस कल्याणमार्गमें व्यवसायात्मिका निश्चय स्वभाववाली बुद्धि एक ही है यानि यथार्थ प्रमाणजनित होनेके कारण अन्य विपरीत बुद्धियोंके शाखाभेदोंकी बाधक है। जो इतर ( दूसरी ) बुद्धियाँ हैं जिनके शाखाभेदके विस्तारसे संसार अनन्त अपार और अनुपरत होता है अर्थात् निरन्तर अत्यन्त विस्तृत होता है उन अनन्त भेदोंवाली बुद्धियोंका प्रमाणजनित विवेकबुद्धिके बलसे अन्त हो जानेपर संसारका भी अन्त हो जाता है। परंतु जो अव्यवसायी हैं जो प्रमाणजनित विवेकबुद्धिसे रहित हैं उनकी वे बुद्धियाँ बहुत शाखा अर्थात् बहुत भेदोंवाली और प्रतिशाखाभेदसे अनन्त होती हैं।'),
('shankaracharya-ht:source:2.42','Śaṅkarācārya','gita.2.42','hi','translation','।।2.42।।जिनमें निश्चयात्मिका बुद्धि नहीं है वे इस आगे कही जानेवाली पुष्पित वृक्षोंजैसी शोभित सुननेमें ही रमणीय जिस वाणीको कहा करते हैँ। कौन कहा करते हैं अज्ञानी अर्थात् अल्पबुद्धिवाले अविवेकी जो कि बहुत अर्थवाद और फलसाधनोंको प्रकाश करनेवाले वेदवाक्योंमें रत हैं। तथा हे पार्थ जो ऐसे भी कहनेवाले हैं कि स्वर्गप्राप्ति आदि फलके साधनरूप कर्मोंसे अतिरिक्त अन्य कुछ है ही नहीं।'),
('shankaracharya-ht:source:2.43','Śaṅkarācārya','gita.2.43','hi','translation','।।2.43।।तथा वे कामात्माजिन्होंने भोगकामनाको ही अपना स्वभाव बना लिया है ऐसे भोगपरायण और स्वर्गको प्रधान माननेवाले यानी स्वर्ग ही जिनका परम पुरुषार्थ है ऐसे पुरुष जन्मरूप कर्मफलको देनेवाली ही बातें किया करते हैं। कर्मके फलका नाम कर्मफल है जन्मरूप कर्मफल जन्मकर्मफल कहलाता है उसको देनेवाली वाणी जन्मकर्मफलप्रदा कही जाती है। ऐसी वाणी कहा करते हैं। इस प्रकार भोग और ऐश्वर्यकी प्राप्तिके लिये जो क्रियाओंके भेद हैं वे जिस वाणीमें बहुत हों अर्थात् स्वर्ग पशु पुत्र आदि अनेक पदार्थ जिस वाणीद्वारा अधिकतासे बतलाये जाते हों ऐसी बहुतसे क्रियाभेदोंको बतलानेवाली वाणीको बोलनेवाले वे मूढ़ बारंबार संसारचक्रमें भ्रमण करते हैं यह अभिप्राय है।'),
('shankaracharya-ht:source:2.44','Śaṅkarācārya','gita.2.44','hi','translation','।।2.44।।जो भोग और ऐश्वर्यमें आसक्त हैं अर्थात् भोग और ऐश्वर्य ही पुरषार्थ है ऐसे मानकर उनमें ही जिनका प्रेम हो गया है इस प्रकार जो तद्रूप हो रहे हैं तथा क्रियाभेदोंको विस्तारपूर्वक बतलानेवाली उस उपर्युक्त वाणीद्वारा जिनका चित्त हर लिया गया है अर्थात् ( जिनकी ) विवेकबुद्धि आच्छादित हो रही है उनकी समाधिमें सांख्यविषयक या योगविषयक निश्चयात्मिका बुद्धि ( नहीं ठहरती )। पुरुषके भोगके लिये जिसमें सब कुछ स्थापित किया जाता है उसका नाम समाधि है। इस व्युत्पत्तिके अनुसार समाधि अन्तःकरणका नाम है उसमें बुद्धि नहीं ठहरती अर्थात् उत्पन्न ही नहीं होती।'),
('shankaracharya-ht:source:2.45','Śaṅkarācārya','gita.2.45','hi','translation','।।2.45।।जो इस प्रकार विवेकबुद्धिसे रहित हैं उन कामपरायण पुरुषोंके वेद त्रैगुण्यविषयक हैं अर्थात् तीनों गुणोंके कार्यरूप संसारको ही प्रकाशित करनेवाले हैं। परंतु हे अर्जुन तू असंसारी हो निष्कामी हो। तथा निर्द्वन्द्व हो अर्थात् सुखदुःखके हेतु जो परस्पर विरोधी ( युग्म ) पदार्थ हैं उनका नाम द्वन्द्व है उनसे रहित हो और नित्य सत्त्वस्थ हो अर्थात् सदा सत्त्वगुणके आश्रित हो। तथा निर्योगक्षेम हो। अप्राप्त वस्तुको प्राप्त करनेका नाम योग है और प्राप्त वस्तुके रक्षणका नाम क्षेम है योगक्षेमको प्रधान माननेवालेकी कल्याणमार्गमें प्रवृत्ति होनी अत्यन्त कठिन है अतः तू योगक्षेमको न चाहनेवाला हो। तथा आत्मवान् हो अर्थात् ( आत्मविषयोंमें ) प्रमादरहित हो। तुझ स्वधर्मानुष्ठानमें लगे हुएके लिये यह उपदेश है।'),
('shankaracharya-ht:source:2.46','Śaṅkarācārya','gita.2.46','hi','translation','।।2.46।।सम्पूर्ण वेदोक्त कर्मोंके जो अनन्त फल हैं उन फलोंको यदि कोई न चाहता हो तो वह उन कर्मोंका अनुष्ठान ईश्वरके लिये क्यों करे इसपर कहते हैं सुन जैसे जगत्में कूप तालाब आदि अनेक छोटेछोटे जलाशयोंमें जितना स्नानपान आदि प्रयोजन सिद्ध होता है वह सब प्रयोजन सब ओरसे परिपूर्ण महान् जलाशयमें उतने ही परिमाणमें ( अनायास ) सिद्ध हो जाता है। अर्थात् उसमें उनका अन्तर्भाव है। इसी तरह सम्पूर्ण वेदोंमें यानी वेदोक्त कर्मोंसे जो प्रयोजन सिद्ध होता है अर्थात् जो कुछ उन कर्मोंका फल मिलता है वह समस्त प्रयोजन परमार्थतत्त्वको जाननेवाले ब्राह्मणका यानी संन्यासीका जो सब ओरसे परिपूर्ण महान् जलाशयस्थानीय विज्ञान आनन्दरूप फल है उसमें उतने ही परिमाणमें ( अनायास ) सिद्ध हो जाता है। अर्थात् उसमें उसका अन्तर्भाव है। श्रुतिमें भी कहा है कि जिसको वह ( रैक्व ) जानता है उस ( परब्रह्म ) को जो भी कोई जानता है वह उन सबके फलको पा जाता है कि जो कुछ प्रजा अच्छा कार्य करती है। आगे गीतामें भी कहेंगे कि सम्पूर्ण कर्म ज्ञानमें समाप्त हो जाते हैं। इत्यादि। सुतरां यद्यपि कूप तालाब आदि छोटे जलाशयोंकी भाँति कर्म अल्प फल देनेवाले हैं तो भी ज्ञाननिष्ठाका अधिकार मिलनेसे पहलेपहले कर्माधिकारीको कर्म करना चाहिये।'),
('shankaracharya-ht:source:2.47','Śaṅkarācārya','gita.2.47','hi','translation','।।2.47।।तेरा कर्ममें ही अधिकार है ज्ञाननिष्ठामें नहीं। वहाँ ( कर्ममार्गमें ) कर्म करते हुए तेरा फलमें कभी अधिकार न हो अर्थात् तुझे किसी भी अवस्थामें कर्मफलकी इच्छा नहीं होनी चाहिये। यदि कर्मफलमें तेरी तृष्णा होगी तो तू कर्मफलप्राप्तिका कारण होगा। अतः इस प्रकार कर्मफलप्राप्तिका कारण तू मत बन। क्योंकि जब मनुष्य कर्मफलकी कामनासे प्रेरित होकर कर्ममें प्रवृत्त होता है तब वह कर्मफलरूप पुनर्जन्मका हेतु बन ही जाता है। यदि कर्मफलकी इच्छा न करें तो दुःखरूप कर्म करनेकी क्या आवश्यकता है इस प्रकार कर्म न करनेमें भी तेरी आसक्तिप्रीति नहीं होनी चाहिये।'),
('shankaracharya-ht:source:2.48','Śaṅkarācārya','gita.2.48','hi','translation','।।2.48।।यदि कर्मफलसे प्रेरित होकर कर्म नहीं करने चाहिये तो फिर किस प्रकार करने चाहिये इसपर कहते हैं हे धनंजय योगमें स्थित होकर केवल ईश्वरके लिय कर्म कर। उनमें भी ईश्वर मुझपर प्रसन्न हों। इस आशारूप आसक्तिको भी छोड़कर कर। फलतृष्णारहित पुरुषद्वारा कर्म किये जानेपर अन्तःकरणकी शुद्धिसे उत्पन्न होनेवाली ज्ञानप्राप्ति तो सिद्धि है और उससे विपरीत ( ज्ञानप्राप्तिका न होना ) असिद्धि है ऐसी सिद्धि और असिद्धिमें भी सम होकर अर्थात् दोनोंको तुल्य समझकर कर्म कर। वह कौनसा योग है जिसमें स्थित होकर कर्म करनेके लिये कहा है यही जो सिद्धि और असिद्धिमें समत्व है इसीको योग कहते हैं।'),
('shankaracharya-ht:source:2.49','Śaṅkarācārya','gita.2.49','hi','translation','।।2.49।।जो समत्वबुद्धिसे ईश्वराराधनार्थ किये जानेवाले कर्म हैं उनकी अपेक्षा ( सकाम कर्म निकृष्ट हैं यह दिखलाते हैं ) हे धनंजय बुद्धियोगकी अपेक्षा अर्थात् समत्वबुद्धिसे युक्त होकर किये जानेवाले कर्मोंकी अपेक्षा कर्मफल चाहनेवाले सकामी मनुष्योंद्वारा किये हुए कर्म जन्ममरण आदिके हेतु होनेके कारण अत्यन्त ही निकृष्ट हैं। इसलिये तू योगविषयक बुद्धिमें या उसके परिपाकसे उत्पन्न होनेवाली सांख्यबुद्धिमें शरण आश्रय अर्थात् अभयप्राप्तिके हेतुको पानेकी इच्छा कर। अभिप्राय यह कि परमार्थज्ञानकी शरणमें जा। क्योंकि फलतृष्णासे प्रेरित होकर सकाम कर्म करनेवाले कृपण हैं दीन हैं। श्रुतिमें भी कहा है हे गार्गी जो इस अक्षर ब्रह्मको न जानकर इस लोकसे जाता है वह कृपण है।'),
('shankaracharya-ht:source:2.50','Śaṅkarācārya','gita.2.50','hi','translation','।।2.50।।समत्वबुद्धिसे युक्त होकर स्वधर्माचरण करनेवाला पुरुष जिस फलको पाता है वह सुन समत्वयोगविषयक बुद्धिसे युक्त हुआ पुरुष अन्तःकरणकी शुद्धिके और ज्ञानप्राप्तिके द्वारा सुकृतदुष्कृतको पुण्यपाप दोनोंको यहीं त्याग देता है इसी लोकमें कर्मबन्धनसे मुक्त हो जाता है। इसलिये तू समत्वबुद्धिरूप योगकी प्राप्तिके लिये यत्न कर चेष्टा कर। क्योंकि योग ही तो कर्मोंमें कुशलता है अर्थात् स्वधर्मरूप कर्ममें लगे हुए पुरुषका जो ईश्वरसमर्पित बुद्धिसे उत्पन्न हुआ सिद्धिअसिद्धिविषयक समत्वभाव है वही कुशलता है। यही इसमें कौशल है कि स्वभावसे ही बन्धन करनेवाले जो कर्म हैं वे भी समत्व बुद्धिके प्रभावसे अपने स्वभावको छोड़ देते हैं अतः तू समत्वबुद्धिसे युक्त हो।'),
('shankaracharya-ht:source:2.51','Śaṅkarācārya','gita.2.51','hi','translation','।।2.51।।क्योंकि कर्मजम् इस पदका फलं त्यक्त्वा इस अगले पदसे सम्बन्ध है। कर्मोंसे उत्पन्न होनेवाली जो इष्टानिष्टदेहप्राप्ति है वही कर्मज फल कहलाता है समत्वबुद्धियुक्त पुरुष उस कर्मफलको छोड़कर मनीषी अर्थात् ज्ञानी होकर जीवित अवस्थामें ही जन्मबन्धनसे निर्मुक्त होकर अर्थात् जन्म नामके बन्धनसे छूटकर विष्णुके मोक्ष नामक अनामय सर्वोपद्रवरहित परमपदको पा लेते हैं। अथवा ( यों समझो कि ) बुद्धियोगाद्धनंजय इस श्लोकसे लेकर ( यहाँतक बुद्धि शब्दसे ) कर्मयोगजनित सत्त्वशुद्धिसे उत्पन्न हुई जो सर्वतःसंप्लुतोदकस्थानीय परमार्थज्ञानरूपा बुद्धि है वही दिखलायी गयी है क्योंकि ( यहाँ ) यह बुद्धि पुण्यपापके नाशमें साक्षात् हेतुरूपसे वर्णित है।'),
('shankaracharya-ht:source:2.52','Śaṅkarācārya','gita.2.52','hi','translation','।।2.52।।योगानुष्ठानजनित सत्त्वशुद्धिसे उत्पन्न हुई बुद्धि कब प्राप्त होती है इसपर कहते हैं जब तेरी बुद्धि मोहकलिलको अर्थात् जिसके द्वारा आत्मानात्मके विवेकविज्ञानको कलुषित करके अन्तःकरण विषयोंमें प्रवृत्त किया जाता है उस मोहात्मक अविवेककालिमाको उल्लङ्घन कर जायगी अर्थात् जब तेरी बुद्धि बिल्कुल शुद्ध हो जायगी। तब उस समय तू सुननेयोग्यसे और सुने हुएसे वैराग्यको प्राप्त हो जायगा। अर्थात् तब तेरे लिये सुननेयोग्य और सुने हुए ( सब विषय ) निष्फल हो जायँगे यह अभिप्राय है।'),
('shankaracharya-ht:source:2.53','Śaṅkarācārya','gita.2.53','hi','translation','।।2.53।।यदि तू पूछे कि मोहरूप मलिनतासे पार होकर आत्मविवेकजन्य बुद्धिको प्राप्त हुआ मैं कर्मयोगके फलरूप परमार्थयोगको ( ज्ञानको ) कब पाऊँगा तो सुन अनेक साध्य साधन और उनका सम्बन्ध बतलानेवाली श्रुतियोंसे विप्रतिपन्न अर्थात् नाना भावोंको प्राप्त हुई विक्षिप्त हुई तेरी बुद्धि जब समाधिमें यानी जिसमें चित्तका समाधान किया जाय वह समाधि है इस व्युत्पत्तिसे आत्माका नाम समाधि है उसमें अचल और दृढ़ स्थिर हो जायगी यानी विक्षेपरूप चलनसे और विकल्पसे रहित होकर स्थिर हो जायगी। तब तू योगको प्राप्त होगा अर्थात् विवेकजनित बुद्धिरूप समाधिनिष्ठाको पावेगा।'),
('shankaracharya-ht:source:2.54','Śaṅkarācārya','gita.2.54','hi','translation','।।2.54।।प्रश्नके कारणको पाकर समाधिप्रज्ञाको प्राप्त हुए पुरुषके लक्षण जाननेकी इच्छासे अर्जुन बोला जिसकी बुद्धि इस प्रकार प्रतिष्ठित हो गयी है कि मैं परब्रह्म परमात्मा ही हूँ वह स्थितप्रज्ञ है। हे केशव ऐसे समाधिमें स्थित हुए स्थितप्रज्ञ पुरुषकी क्या भाषा होती है यानी वह अन्य पुरुषोंद्वारा किस प्रकार किन लक्षणोंसे बतलाया जाता है तथा वह स्थितप्रज्ञ पुरुष स्वयं किस तरह बोलता है कैसे बैठता है और कैसे चलता है अर्थात् उसका बैठना चलना किस तरहका होता है इस प्रकार इस श्लोकसे अर्जुन स्थितप्रज्ञ पुरुषके लक्षण पूछता है। जो पहलेसे ही कर्मोंको त्यागकर ज्ञाननिष्ठामें स्थित है और जो कर्मयोगसे ( ज्ञाननिष्ठाको प्राप्त हुआ है ) उन दोनों प्रकारके स्थितप्रज्ञोंके लक्षण और साधन प्रजहाति इत्यादि श्लोकसे लेकर अध्यायकी समाप्तिपर्यन्त कहे जाते हैं। अध्यात्मशास्त्रमें सभी जगह कृतार्थ पुरुषके जो लक्षण होते हैं वे ही यत्नद्वारा साध्य होनेके कारण ( दूसरोंके लिये ) साधनरूपसे उपदेश किये जाते हैं। जो यत्नसाध्य साधन होते हैं वे ही ( सिद्ध पुरुषके स्वाभाविक ) लक्षण होते हैं।'),
('shankaracharya-ht:source:2.55','Śaṅkarācārya','gita.2.55','hi','translation','।।2.55।।श्रीभगवान् बोले हे पार्थ जब मनुष्य मनमें स्थित हृदयमें प्रविष्ट सम्पूर्ण कामनाओंको सारे इच्छा भेदोंको भली प्रकार त्याग देता है छोड़ देता है। सारी कामनाओंका त्याग कर देनेपर तुष्टिके कारणोंका अभाव हो जाता है और शरीरधारणका हेतु जो प्रारब्ध है उसका अभाव होता नहीं अतः शरीरस्थितिके लिये उस मनुष्यकी उन्मत्तपूरे पागलके सदृश प्रवृत्ति होगी ऐसी शङ्का प्राप्त होनेपर कहते हैं तब वह अपने अन्तरात्मस्वरूपमें ही किसी बाह्य लाभकी अपेक्षा न रखकर अपनेआप संतुष्ट रहनेवाला अर्थात् परमार्थदर्शनरूप अमृतरसलाभसे तृप्त अन्य सब अनात्मपदार्थोंसे अलंबुद्धिवाला तृष्णारहित पुरुष स्थितप्रज्ञ कहलाता है अर्थात् जिसकी आत्मअनात्मके विवेकसे उत्पन्न हुई बुद्धि स्थित हो गयी है वह स्थितप्रज्ञ यानी ज्ञानी कहा जाता है। अभिप्राय यह कि पुत्र धन और लोककी समस्त तृष्णाओंको त्याग देनेवाला संन्यासी ही आत्माराम आत्मक्रीड और स्थितप्रज्ञ है।'),
('shankaracharya-ht:source:2.56','Śaṅkarācārya','gita.2.56','hi','translation','।।2.56।।तथा आध्यात्मिक आदि तीनों प्रकारके दुःखोंके प्राप्त होनेमें जिसका मन उद्विग्न नहीं होता अर्थात् क्षुभित नहीं होता उसे अनुद्विग्नमना कहते हैं। तथा सुखोंकी प्राप्तिमें जिसकी स्पृहातृष्णा नष्ट हो गयी है अर्थात् ईंधन डालनेसे जैसे अग्नि बढ़ती है वैसे ही सुखके साथसाथ जिसकी लालसा नहीं बढ़ती वह विगतस्पृह कहलाता है। एवं आसक्ति भय और क्रोध जिसके नष्ट हो गये हैं वह वीतरागभयक्रोध कहलाता है ऐसे गुणोंसे युक्त जब कोई हो जाता है तब वह स्थितधी यानी स्थितप्रज्ञ और मुनि यानी संन्यासी कहलाता है।'),
('shankaracharya-ht:source:2.57','Śaṅkarācārya','gita.2.57','hi','translation','।।2.57।।तथा जो मुनि सर्वत्र अर्थात् शरीर जीवन आदितकमें भी स्नेहसे रहित हो चुका है तथा उनउन शुभ या अशुभको पाकर न प्रसन्न होता है और न द्वेष ही करता है अर्थात् शुभको पाकर प्रसन्न नहीं होता और अशुभको पाकर उसमें द्वेष नहीं करता। जो इस प्रकार हर्ष विषादसे रहित हो चुका है उसकी विवेकजनित बुद्धि प्रतिष्ठित होती है।'),
('shankaracharya-ht:source:2.58','Śaṅkarācārya','gita.2.58','hi','translation','।।2.58।।तथा जब यह ज्ञाननिष्ठामें स्थित हुआ संन्यासी कछुएके अङ्गोंकी भाँति अर्थात् जैसे कछुआ भयके कारण सब ओरसे अपने अङ्गोंको संकुचित कर लेता है उसी तरह सम्पूर्ण विषयोंसे सब ओरसे इन्द्रियोंको खींच लेता है भलीभाँति रोक लेता है तब उसकी बुद्धि प्रतिष्ठित होती है। इस वाक्यका अर्थ पहले कहा हुआ है।'),
('shankaracharya-ht:source:2.59','Śaṅkarācārya','gita.2.59','hi','translation','।।2.59।।विषयोंका ग्रहण न करनेवाले रोगी मनुष्यकी भी इन्द्रियाँ तो विषयोंसे हट जाती हैं यानी कछुएके अङ्गोंकी भाँति संकुचित हो जाती हैं परन्तु विषयसम्बन्धी राग ( आसक्ति ) नष्ट नहीं होता। उसका नाश कैसे होता है सो कहते हैं यद्यपि विषयोंको ग्रहण न करनेवाले कष्टकर तपमें स्थित देहाभिमानी अज्ञानी पुरुषकी भी विषयशब्दवाच्य इन्द्रियाँ अथवा केवल शब्दादि विषय तो निवृत्त हो जाते हैं परंतु उन विषयोंमें रहनेवाला जो रस अर्थात् आसक्ति है उसको छोड़कर निवृत्त होते हैं अर्थात् उनमें रहनेवाली आसक्ति निवृत्त नहीं होती। रस शब्द राग ( आसक्ति ) का वाचक प्रसिद्ध है क्योंकि स्वरसेन प्रवृत्तो रसिको रसज्ञः इत्यादि वाक्य देखे जाते हैं। वह रागात्मक सूक्ष्म आसक्ति भी इस यतिकी परमार्थतत्त्वरूप ब्रह्मका प्रत्यक्ष दर्शन होनेपर निवृत्त हो जाती है अर्थात् मैं ही वह ब्रह्म हूँ इस प्रकारका भाव दृढ़ हो जानेपर उसका विषयविज्ञान निर्बीज हो जाता है। अभिप्राय यह कि यथार्थ ज्ञान हुए बिना रागका मूलोच्छेद नहीं होता अतः यथार्थ ज्ञानरूप बुद्धिकी स्थिरता कर लेनी चाहिये।'),
('shankaracharya-ht:source:2.60','Śaṅkarācārya','gita.2.60','hi','translation','।।2.60।।यथार्थ ज्ञानरूप बुद्धिकी स्थिरता चाहनेवाले पुरुषोंको पहले इन्द्रियोंको अपने वशमें कर लेना चाहिये क्योंकि उनको वशमें न करनेसे दोष बतलाते हैं हे कौन्तेय जिससे की प्रयत्न करनेवाले विचारशील बुद्धिमान् पुरुषकी भी प्रमथनशील इन्द्रियाँ उस विषयाभिमुख हुए पुरुषको क्षुब्ध कर देती हैं व्याकुल कर देती हैं और व्याकुल करके ( उस ) केवल प्रकाशको ही देखनेवाले विद्वान्के विवेकविज्ञानयुक्त मनको ( भी ) बलात्कारसे विचलित कर देती हैं।'),
('shankaracharya-ht:source:2.61','Śaṅkarācārya','gita.2.61','hi','translation','।।2.61।।जब कि यह बात है इसलिये उन सब इन्द्रियोंको रोककर यानी वशमें करके और युक्त समाहितचित्त हो मेरे परायण होकर बैठना चाहिये। अर्थात् सबका अन्तरात्मारूप मैं वासुदेव ही जिसका सबसे पर हूँ वह मत्पर है अर्थात् मैं उस परमात्मासे भिन्न नहीं हूँ। इस प्रकार मुझसे अपनेको अभिन्न माननेवाला होकर बैठना चाहिये। क्योंकि इस प्रकार बैठनेवाले जिस यतिकी इन्द्रियाँ अभ्यासबलसे ( उसके ) वशमें है उसकी प्रज्ञा प्रतिष्ठित है।'),
('shankaracharya-ht:source:2.62','Śaṅkarācārya','gita.2.62','hi','translation','।।2.62।।इतना कहनेके उपरान्त अब यह पतनाभिमुख पुरुषके समस्त अनर्थोंका कारण बतलाया जाता है विषयोंका ध्यान चिन्तन करनेवाले पुरुषकी अर्थात् शब्दादि विषयोंके भेदोंकी बारंबार आलोचना करनेवाले पुरुषकी उन विषयोंमें आसक्ति प्रीति उत्पन्न हो जाती है। आसक्तिसे कामना तृष्णा उत्पन्न होती है। कामसे अर्थात् किसी भी कारणवश विच्छिन्न हुई इच्छासे क्रोध उत्पन्न होता है।'),
('shankaracharya-ht:source:2.63','Śaṅkarācārya','gita.2.63','hi','translation','।।2.63।।क्रोधसे संमोह अर्थात् कर्तव्यअकर्तव्यविषयक अविवेक उत्पन्न होता है क्योंकि क्रोधी मनुष्य मोहित होकर गुरुको ( बड़ेको ) भी गोली दे दिया करता है। मोहसे स्मृतिका विभ्रम होता है अर्थात् शास्त्र और आचार्यद्वारा सुने हुए उपदेशके संस्कारोंसे जो स्मृति उत्पन्न होती है उसके प्रकट होनेका निमित्त प्राप्त होनेपर वह प्रकट नहीं होती। इस प्रकार स्मृतिविभ्रम होनेसे बुद्धिका नाश हो जाता है। अन्तःकरणमें कार्यअकार्यविषयक विवेचनकी योग्यताका न रहना बुद्धिका नाश कहा जाता है। बुद्धिका नाश होनेसे ( यह मनुष्य ) नष्ट हो जाता है क्योंकि वह तबतक ही मनुष्य है जबतक उसका अन्तःकरण कार्यअकार्यके विवेचनमें समर्थ है ऐसी योग्यता न रहनेपर मनुष्य नष्टप्राय ( मनुष्यतासे हीन ) हो जाता है। अतः उस अन्तःकरणकी ( विवेकशक्तिरूप ) बुद्धिका नाश होनेसे पुरुषका नाश हो जाता है। इस कथनका यह अभिप्राय है कि वह पुरुषार्थके अयोग्य हो जाता है।'),
('shankaracharya-ht:source:2.64','Śaṅkarācārya','gita.2.64','hi','translation','।।2.64।।विषयोंके चिन्तनको सब अनर्थोंका मूल बतलाया गया। अब यह मोक्षका साधन बतलाया जाता है आसक्ति और द्वेषको रागद्वेष कहते हैं इन दोनोंको लेकर ही इन्द्रियोंकी स्वाभाविक प्रवृत्ति हुआ करती है। परंतु जो मुमुक्षु होता है वह स्वाधीन अन्तःकरणवाला अर्थात् जिसका अन्तःकरण इच्छानुसार वशमें है ऐसा पुरुष रोगद्वेषसे रहित और अपने वशमें की हुई श्रोत्रादि इन्द्रियोंद्वारा अनिवार्य विषयोंको ग्रहण करता हुआ प्रसादको प्राप्त होता है। प्रसन्नता और स्वास्थ्यको प्रसाद कहते हैं।'),
('shankaracharya-ht:source:2.65','Śaṅkarācārya','gita.2.65','hi','translation','।।2.65।।प्रसन्नता होनेसे क्या होता है सो कहते हैं प्रसन्नता प्राप्त होनेपर इस यतिके आध्यात्मिकादि तीनों प्रकारके समस्त दुःखोंका नाश हो जाता है। क्योंकि ( उस ) प्रसन्नचित्तवालेकी अर्थात् स्वस्थ अन्तःकरणवाले पुरुषकी बुद्धि शीघ्र ही सब ओरसे आकाशकी भाँति स्थिर हो जाती है केवल आत्मरूपसे निश्चल हो जाती है। इस वाक्यका अभिप्राय यह है कि इस प्रकार प्रसन्नचित्त और स्थिरबुद्धिवाले पुरुषको कृतकृत्यता मिलती है इसलिये साधक पुरुषको चाहिये कि रागद्वेषसे रहित की हुई इन्द्रियोंद्वारा शास्त्रके अविरोधी अनिवार्य विषयोंका सेवन करे।'),
('shankaracharya-ht:source:2.66','Śaṅkarācārya','gita.2.66','hi','translation','।।2.66।।उस प्रसन्नताकी स्तुति की जाती है अयुक्त पुरुषमें अर्थात् जिसका अन्तःकरण समाहित नहीं है ऐसे पुरुषमें आत्मस्वरूपविषयक बुद्धि नहीं होती अर्थात् नहीं रहती और उस अयुक्त पुरुषमें भावना अर्थात् आत्मज्ञानमें प्रगाढ प्रवेश अतिशय प्रीति भी नहीं होती। तथा भावना न करनेवालेको अर्थात् आत्मज्ञानके साधनमें प्रीतिपूर्वक संलग्न न होनेवालेको शान्ति अर्थात् उपशमता भी नहीं मिलती। शान्तिरहित पुरुषको भला सुख कहाँ क्योंकि विषयसेवनसम्बन्धी तृष्णासे जो इन्द्रियोंका निवृत्त होना है वही सुख है विषयसम्बन्धी तृष्णा कदापि सुख नहीं है वह तो दुःख ही है। अभिप्राय यह कि तृष्णाके रहते हुए तो सुखकी गन्धमात्र भी नहीं मिलती।'),
('shankaracharya-ht:source:2.67','Śaṅkarācārya','gita.2.67','hi','translation','।।2.67।।अयुक्त पुरुषमें बुद्धि क्यों नहीं होती इसपर कहते हैं क्योंकि अपनेअपने विषयमें विचरनेवाली अर्थात् विषयोंमें प्रवृत्त हुई इन्द्रियोंमेंसे जिसके पीछेपीछे यह मन जाता है विषयोंमें प्रवृत्त होता है वह उस इन्द्रियके विषयको विभागपूर्वक ग्रहण करनेमें लगा हुआ मन इस साधककी आत्मअनात्मसम्बन्धी विवेकज्ञानसे उत्पन्न हुई बुद्धिको हर लेता है अर्थात् नष्ट कर देता है। कैसे जैसे जलमें नौकाको वायु हर लेता है वैसे ही अर्थात् जैसे जलमें चलनेकी इच्छावाले पुरुषोंकी नौकाको वायु गन्तव्य मार्गसे हटाकर उल्टे मार्गपर ले जाता है वैसे ही यह मन आत्मविषयक बुद्धिको विचलित करके विषयविषयक बना देता है।'),
('shankaracharya-ht:source:2.68','Śaṅkarācārya','gita.2.68','hi','translation','।।2.68।।यततो ह्यपि इस श्लोकसे प्रतिपादित अर्थकी अनेक प्रकारसे उपपत्ति बतलाकर उस अभिप्रायको सिद्ध करके अब उसका उपसंहार करते हैं क्योंकि इन्द्रियोंकी प्रवृत्तिमें दोष सिद्ध किया जा चुका है इसलिये हे महाबाहो जिस साधककी इन्द्रियाँ अपनेअपने शब्दादि विषयोंसे सब प्रकारसे अर्थात् मानसिक आदि भेदोंसे निगृहीत की जा चुकी हैं ( वशमें की हुई हैं ) उसकी बुद्धि प्रतिष्ठित है।'),
('shankaracharya-ht:source:2.69','Śaṅkarācārya','gita.2.69','hi','translation','।।2.69।।यह जो लौकिक और वैदिक व्यवहार है वह सबकासब अविद्याका कार्य है अतः जिसको विवेकज्ञान प्राप्त हो गया है ऐसे स्थितप्रज्ञके लिये अविद्याकी निवृत्तिके साथहीसाथ ( यह व्यवहार भी ) निवृत्त हो जाता है और अविद्याका विद्याके साथ विरोध होनेके कारण उसकी भी निवृत्ति हो जाती है। इस अभिप्रायको स्पष्ट करते हुए कहते हैं तामस स्वभावके कारण सब पदार्थोंका अविवेक करानेवाली रात्रिका नाम निशा है। सब भूतोंकी जो निशा अर्थात् रात्रि है वह ( निशा ) क्या है ( उ0 ) परमार्थतत्त्व जो कि स्थितप्रज्ञका विषय है ( ज्ञेय है )। जैसे उल्लू आदि रजनीचरोंके लिये दूसरोंका दिन भी रात होती है वैसे ही निशाचरस्थानीय जो सम्पूर्ण अज्ञानी मनुष्य हैं जिनमें परमार्थतत्त्वविषयक बुद्धि नहीं है उन सब भूतोंके लिये अज्ञात होनेके कारण यह परमार्थतत्त्व रात्रिकी भाँति रात्रि है। उस परमार्थतत्त्वरूप रात्रिमें अज्ञाननिद्रासे जगा हुआ संयमी अर्थात् जितेन्द्रिय योगी जागता है। ग्राह्यग्राहकभेदरूप जिस अविद्यारात्रिमें सोते हुए भी सब प्राणी जागते हैं ऐसे कहा जाता है अर्थात् जिस रात्रिमें सब प्राणी सोते हुए स्वप्न देखनेवालोंके सदृश जागते हैं। वह ( सारा दृश्य ) अविद्यारूप होनेके कारण परमार्थतत्त्वको जाननेवाले मुनिके लिये रात्रि है। सुतरां ( यह सिद्ध हुआ कि ) अविद्याअवस्थामें ही ( मनुष्यके लिये ) कर्मोंका विधान किया जाता है विद्यावस्थामें नहीं क्योंकि जैसे सूर्यके उदय होनेपर रात्रिसम्बन्धी अन्धकार दूर हो जाता है उसी प्रकार ज्ञान उदय होनेपर अज्ञान नष्ट हो जाता है। ज्ञानोत्पत्तिसे पहलेपहले प्रमाणबुद्धिसे ग्रहण की हुई अविद्या ही क्रिया कारक और फल आदिके भेदोंमें परिणत होकर सब कर्म करवानेका हेतु बन सकती है अप्रमाणबुद्धिसे ग्रहण की हुई ( अविद्या ) कर्म करवानेका कारण नहीं बन सकती। क्योंकि प्रमाणस्वरूप वेदने मेरे लिये अमुक कर्तव्यकर्मोंका विधान किया है ऐसा मानकर ही कर्ता कर्ममें प्रवृत्त होता है यह सब रात्रिकी भाँति अविद्यामात्र है इस तरह समझकर नहीं होता। जिसको ऐसा ज्ञान प्राप्त हो गया है कि यह सारा दृश्य रात्रिकी भाँति अविद्यामात्र ही है उस आत्मज्ञानीका तो सर्व कर्मोंके संन्यासमें ही अधिकार है प्रवृत्तिमें नहीं। इस प्रकार तद्बुद्धयस्तदात्मानः इत्यादि श्लोकोंसे उस ज्ञानीका अधिकार ज्ञाननिष्ठामें ही दिखलायेंगे। पू0 उस ज्ञाननिष्ठामें भी ( तत्त्ववेत्ताको ) प्रवृत्त करनेवाले प्रमाणका ( विधिवाक्यका ) अभाव है इसलिये उसमें भी उसकी प्रवृत्ति नहीं हो सकती। उ0 यह कहना ठीक नहीं क्योंकि आत्मज्ञान अपने स्वरूपको विषय करनेवाला है अतः अपने स्वरूपज्ञानके विषयमें प्रवृत्त करनेवाले प्रमाणकी अपेक्षा नहीं होती। वह आत्मज्ञान स्वयं आत्मा होनेके कारण स्वतःसिद्ध है और उसीमें सब प्रमाणोंके प्रमाणत्वका अन्त है अर्थात् आत्मज्ञान होनेतक ही प्रमाणोंका प्रमाणत्व है अतः आत्मस्वरूपका साक्षात् होनेके बाद प्रमाण और प्रमेयका व्यवहार नहीं बन सकता। ( आत्मज्ञानरूप ) अन्तिम प्रमाण आत्माके प्रमातापनको भी निवृत्त कर देता है। उसको निवृत्त करता हुआ वह स्वयं भी जागनेके बाद स्वप्नकालके प्रमाणकी भाँति अप्रमाणी हो जाता है अर्थात् लुप्त हो जाता है। क्योंकि व्यवहारमें भी वस्तु प्राप्त होनेके बाद कोई प्रमाण ( उस वस्तुकी प्राप्तिके लिये ) प्रवृत्तिका हेतु होता नहीं देखा जाता। इसलिये यह सिद्ध हुआ कि आत्मज्ञानीका कर्मोंमें अधिकार नहीं है।'),
('shankaracharya-ht:source:2.70','Śaṅkarācārya','gita.2.70','hi','translation','।।2.70।।जिसने तीनों एषणाओंका त्याग कर दिया है ऐसे स्थितप्रज्ञ विद्वान् संन्यासीको ही मोक्ष मिलता है भोगोंकी कामना करनेवाले असंन्यासीको नहीं। इस अभिप्रायको दृष्टान्तद्वारा प्रतिपादन करनेकी इच्छा करते हुए भगवान् कहते हैं जिस प्रकार जलसे परिपूर्ण अचल प्रतिष्ठावाले समुद्रमें अर्थात् अचल भावसे जिसकी प्रतिष्ठा स्थिति है ऐसे अपनी मर्यादामें स्थित समुद्रमें सब ओरसे गये हुए जल उसमें किसी प्रकारका विकार उत्पन्न किये बिना ही समा जाते हैं। उसीप्रकार विषयोंका सङ्ग होनेपर भी जिस पुरुषमें समस्त इच्छाएँ समुद्रमें जलकी भाँति कोई भी विकार उत्पन्न न करती हुई सब ओरसे प्रवेश कर जाती हैं अर्थात् जिसकी समस्त कामनाएँ आत्मामें लीन हो जाती हैं उसको अपने वशमें नहीं कर सकतीं उस पुरुषको शान्ति मोक्ष मिलता है दूसरेको अर्थात् भोगोंकी कामना करनेवालेको नहीं मिलता। अभिप्राय यह कि जिनको पानेके लिये इच्छा की जाती है उन भोगोंका नाम काम है उनको पानेकी इच्छा करना जिसका स्वभाव है वह कामकामी है वह उस शान्तिको कभी नहीं पाता।'),
('shankaracharya-ht:source:2.71','Śaṅkarācārya','gita.2.71','hi','translation','।।2.71।।क्योंकि ऐसा है इसलिये जो संन्यासी पुरुष सम्पूर्ण कामनाओंको और भोगोंको अशेषतः त्यागकर अर्थात् केवल जीवनमात्रके निमित्त ही चेष्टा करनेवाला होकर विचरता है। तथा जो स्पृहासे रहित हुआ है अर्थात् शरीरजीवनमात्रमें भी जिसकी लालसा नहीं है। ममतासे रहित है अर्थात् शरीरजीवनमात्रके लिये आवश्यक पदार्थोंके संग्रहमें भी यह मेरा है ऐसे भावसे रहित है। तथा अहंकारसे रहित है अर्थात् विद्वत्ता आदिके सम्बन्धसे होनेवाले आत्माभिमानसे भी रहित है। वह ऐसा स्थितप्रज्ञ ब्रह्मवेत्ता ज्ञानी संसारके सर्वदुःखोंकी निवृत्तिरूप मोक्ष नामक परम शान्तिको पाता है अर्थात् ब्रह्मरूप हो जाता है।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:2.72','Śaṅkarācārya','gita.2.72','hi','translation','।।2.72।।( अब ) उस उपर्युक्त ज्ञाननिष्ठाकी स्तुति की जाती है यह उपर्युक्त अवस्था ब्राह्मी यानी ब्रह्ममें होनेवाली स्थिति है अर्थात् सर्व कर्मोंका संन्यास करके केवल ब्रह्मरूपसे स्थित हो जाना है। हे पार्थ इस स्थितिको पाकर मनुष्य फिर मोहित नहीं होता अर्थात् मोहको प्राप्त नहीं होता। अन्तकालमें अन्तके वयमें भी इस उपर्युक्त ब्राह्मी स्थितिमें स्थित होकर मनुष्य ब्रह्ममें लीनतारूप मोक्षको लाभ करता है। फिर जो ब्रह्मचर्याश्रमसे ही संन्यास ग्रहण करके जीवनपर्यन्त ब्रह्ममें स्थित रहता है वह ब्रह्मनिर्वाणको प्राप्त होता है इसमें तो कहना ही क्या है।'),
('shankaracharya-ht:source:3.1','Śaṅkarācārya','gita.3.1','hi','translation','।।3.1।।अर्जुन बोला हे जनार्दन यदि कर्मोंकी अपेक्षा ज्ञानको आप श्रेष्ठ मानते हैं ( तो हे केशव मुझे इस हिंसारूप क्रूर कर्ममें क्यों लगाते हैं ) यदि ज्ञान और कर्म दोनोंका समुच्चय भगवान्को सम्मत होता तो फिर कल्याणका वह एक साधन कहिये कर्मोंसे ज्ञान श्रेष्ठ है इत्यादि वाक्योंद्वारा अर्जुनका ज्ञानसे कर्मोंको पृथक् करना अनुचित होता। क्योंकि ( समुच्चयपक्षमें ) कर्मकी अपेक्षा उस ( ज्ञान ) का फलके नाते श्रेष्ठ होना सम्भव नहीं। तथा भगवान्ने कर्मोंकी अपेक्षा ज्ञानको कल्याणकारक बतलाया और मुझसे ऐसा कहते हैं कि तू अकल्याणकारक कर्म ही कर इसमें क्या कारण है यह सोचकर अर्जुनने भगवान्को उलहनासा देते हुए जो ऐसा कहा कि तो फिर हे केशव मुझे इस हिंसारूप घोर क्रूर कर्ममें क्यों लगाते हैं वह भी उचित नहीं होता। यदि भगवान्ने स्मार्तकर्मके साथ ही ज्ञानका समुच्चय सबके लिये कहा होता एवं अर्जुनने भी ऐसा ही समझा होता तो उसका यह कहना कि फिर हे केशव मुझे घोर कर्ममें क्यों लगाते हैं कैसे युक्तियुक्त हो सकता।'),
('shankaracharya-ht:source:3.2','Śaṅkarācārya','gita.3.2','hi','translation','।।3.2।।तथा यद्यपि भगवान् स्पष्ट कहनेवाले हैं तो भी मुझ मन्दबुद्धिको भगवान्के वाक्य मिले हुएसे प्रतीत होते हैं उन मिले हुएसे वचनोंसे आप मानो मेरी बुद्धिको मोहित कर रहे हैं। वास्तवमें आप तो मेरी बुद्धिका मोह दूर करनेके लिये प्रवृत्त हुए हैं फिर मुझे मोहित कैसे करते इसीलिये कहता हूँ कि आप मेरी बुद्धिको मोहितसी करते हैं। आप यदि अलगअलग अधिकारियोंद्वारा किये जाने योग्य ज्ञान और कर्मका अनुष्ठान एक पुरुषद्वारा किया जाना असम्भव मानते हैं तो उन दोनोंमेंसे ज्ञान या कर्म यही एक बुद्धि शक्ति और अवस्थाके अनुसार अर्जुनके लिये योग्य है ऐसा निश्चय करके मुझसे कहिये जिस ज्ञान या कर्म किसी एकसे में कल्याणको प्राप्त कर सकूँ। यदि कर्मनिष्ठामें गौणरूपसे भी ज्ञानको भगवान्ने कहा होता तो दोनोंमेंसे एक कहिये इस प्रकार एकहीको सुननेकी अर्जुनकी इच्छा कैसे होती क्योंकि ज्ञान और कर्म इन दोनोंमेंसे मैं तुझसे एक ही कहूँगा दोनों नहीं ऐसा भगवान्ने कहीं नहीं कहा कि जिससे अर्जुन अपने लिये दोनोंकी प्राप्ति असम्भव मानकर एकके लिये ही प्रार्थना करता।'),
('shankaracharya-ht:source:3.3','Śaṅkarācārya','gita.3.3','hi','translation','।।3.3।।प्रश्नके अनुसार ही उत्तर देते हुए श्रीभगवान् बोले हे निष्पाप अर्जुन इस मनुष्यलोकमें शास्त्रोक्त कर्म और ज्ञानके जो अधिकारी हैं ऐसे तीनों वर्णवालोंके लिये ( अर्थात् ब्राह्मण क्षत्रिय और वैश्योंके लिये ) दो प्रकारकी निष्ठास्थिति अर्थात् कर्तव्य तत्परता पहलेसृष्टिके आदिकालमें प्रजाको रचकर उनकी लौकिक उन्नति और मोक्षकी प्राप्तिके साधनरूप वैदिक सम्प्रदायको आविष्कार करनेवाले मुझ सर्वज्ञ ईश्वरद्वारा कही गयी हैं। वह दो प्रकारकी निष्ठा कौनसी हैं सो कहते हैं जो आत्मअनात्मके विषयमें विवेकजन्य ज्ञानसे सम्पन्न हैं जिन्होंने ब्रह्मचर्यआश्रमसे ही संन्यास ग्रहण कर लिया है जिन्होंने वेदान्तके विज्ञानद्वारा आत्मतत्त्वका भलीभाँति निश्चय कर लिया है जो परमहंस संन्यासी हैं जो निरन्तर ब्रह्ममें स्थित हैं ऐसे सांख्ययोगियोंकी निष्ठा ज्ञानरूप योगसे कही है। तथा कर्मयोगसे कर्मयोगियोंकी अर्थात् कर्म करनेवालोंकी निष्ठा कही है। यदि एक पुरुषद्वारा एक ही प्रयोजनकी सिद्धिके लिये ज्ञान और कर्म दोनों एक साथ अनुष्ठान करने योग्य हैं ऐसा अपना अभिप्राय भगवान्द्वारा गीतामें पहले कहीं कहा गया होता या आगे कहा जानेवाला होता अथवा वेदमें कहा गया होता तो शरणमें आये हुए प्रिय अर्जुनको यहाँ भगवान् यह कैसे कहते कि ज्ञाननिष्ठा और कर्मनिष्ठा अलगअलग भिन्नभिन्न अधिकारियोंद्वारा ही अनुष्ठान की जानेयोग्य हैं। यदि भगावन्का यह अभिप्राय मान लिया जाय कि ज्ञान और कर्म दोनोंको सुनकर अर्जुन स्वयं ही दोनोंका अनुष्ठान कर लेगा दोनोंको भिन्न भिन्न पुरुषोंद्वारा अनुष्ठान करनेयोग्य तो दूसरोंके लिये कहूँगा। तब तो भगवान्को रागद्वेषयुक्त और अप्रामाणिक मानना हुआ। ऐसा मानना सर्वथा अनुचित है। इसलिये किसी भी युक्तिसे ज्ञान और कर्मका समुच्चय नहीं माना जा सकता। कर्मोंकी अपेक्षा ज्ञानकी श्रेष्ठता जो अर्जुनने कही थी वह तो सिद्ध है ही क्योंकि भगवान्ने उसका निराकरण नहीं किया। उस ज्ञाननिष्ठाके अनुष्ठानका अधिकार संन्यासियोंका ही है क्योंकि दोनों निष्ठा भिन्नभिन्न पुरुषोंद्वारा अनुष्ठान करनेयोग्य बतलायी गयी हैं। इस कारण भगवान्की यही सम्मति है। यह प्रतीत होता है। बन्धनके हेतुरूप कर्मोंमें ही भगवान् मुझे लगाते हैं ऐसा समझकर व्यथितचित्त हुए और मैं कर्म नहींकरूँगा ऐसा माननेवाले अर्जुनको देखकर भगवान् बोले न कर्मणामनारम्भात् इति। अथवा ज्ञाननिष्ठाका और कर्मनिष्ठाका परस्पर विरोध होनेके कारण एक पुरुषद्वारा एक कालमें दोनोंका अनुष्ठान नहीं किया जा सकता। इससे एक दूसरेकी अपेक्षा न रखकर दोनों अलगअलग मोक्षमें हेतु हैं ऐसा शंका होनेपर'),
('shankaracharya-ht:source:3.4','Śaṅkarācārya','gita.3.4','hi','translation','।।3.4।।यह बात स्पष्ट प्रकट करनेकी इच्छासे कि ज्ञाननिष्ठाकी प्राप्तिमें साधन होनेके कारण कर्मनिष्ठा मोक्षरूप पुरुषार्थमें हेतु है स्वतन्त्र नहीं है और कर्मनिष्ठारूप उपायसे सिद्ध होनेवाली ज्ञाननिष्ठा अन्यकी अपेक्षा न रखकर स्वतन्त्र ही मुक्तिमें हेतु है भगवान् बोले कर्मोंका आरम्भ किये बिना अर्थात् यज्ञादि कर्म जो कि इस जन्म या जन्मान्तरमें किये जाते हैं और सञ्चित पापोंका नाश करनेके द्वारा अन्तःकरणकी शुद्धिमें कारण हैं एवं पापकर्मोंका नाश होनेपर मनुष्योंके ( अन्तःकरणमें ) ज्ञान प्रकट होता है इस स्मृतिके अनुसार जो अन्तःकरणकी शुद्धिमें कारण होनेसे ज्ञाननिष्ठाके भी हेतु हैं उन यज्ञादि कर्मोंका आरम्भ किये बिना मनुष्य निष्कर्मभावको कर्मशून्य स्थितिको अर्थात् जो निष्क्रिय आत्मस्वरूपमें स्थित होनारूप ज्ञानयोगसे प्राप्त होनेवाली निष्ठा है उसको नहीं पाता। पू0 कर्मोंका आरम्भ नहीं करनेसे निष्कर्मभावको प्राप्त नहीं होता इस कथनसे यह पाया जाता है कि इसके विपरीत करनेसे अर्थात् कर्मोंका आरम्भ करनेसे मनुष्य निष्कर्मभावको पाता है सो ( इसमें ) क्या कारण है कि कर्मोंका आरम्भ किये बिना मनुष्य निष्कर्मताको प्राप्त नहीं होता उ0 क्योंकि कर्मोंका आरम्भ ही निष्कर्मताकी प्राप्तिका उपाय है और उपायके बिना उपेयकी प्राप्ति हो नहीं सकती यह प्रसिद्ध ही है। निष्कर्मतारूप ज्ञानयोगका उपाय कर्मयोग है यह बात श्रुतिमें और यहाँ गीतामें भी प्रतिपादित है। श्रुतिमें प्रस्तुत ज्ञेयरूप आत्मलोकके जाननेका उपाय बतलाते हुए उस आत्माको बाह्मण वेदाध्ययन और यज्ञसे जाननेका इच्छा करते हैं इत्यादि वचनोंसे कर्मयोगको ज्ञानयोगका उपाय बतलाया है। तथा यहाँ ( गीताशास्त्रमें ) भी हे महाबाहो बिना कर्मयोगके संन्यास प्राप्त करना कठिन है योगी लोग आसक्ति छो़ड़कर अन्तःकरणकी शुद्धिके लिये कर्म किया करते हैं यज्ञ दान और तप बुद्धिमानोंको पवित्र करनेवाले हैं इत्यादि वचनोंसे आगे प्रतिपादित करेंगे। यहाँ यह शंका होती है कि सब भूतोंको अभयदान देकर संन्यास ग्रहण करे इत्यादि वचनोंमें कर्तव्यकर्मोंके त्यागद्वारा भी निष्कर्मताकी प्राप्ति दिखलायी है और लोकमें भी कर्मोंका आरम्भ न करनेसे निष्कर्मताका प्राप्त होना अत्यन्त प्रसिद्ध है। फिर निष्कर्मता चाहनेवालेको कर्मोंके आरम्भसे क्या प्रयोजन इसपर कहते हैं केवल संन्याससे अर्थात् बिना ज्ञानके केवल कर्मपरित्यागमात्रसे मनुष्य निष्कर्मतारूप सिद्धिको अर्थात् ज्ञानयोगसे होनेंवाली स्थितको नहीं पाता।'),
('shankaracharya-ht:source:3.5','Śaṅkarācārya','gita.3.5','hi','translation','।।3.5।।बिना ज्ञानके केवल कर्मसंन्यासमात्रसे मनुष्य निष्कर्मतारूप सिद्धिको क्यों नहीं पाता इसका कारण जाननेकी इच्छा होनेपर कहते हैं कोई भी मनुष्य कभी क्षणमात्र भी कर्म किये बिना नहीं रहता क्योंकि सभी प्राणी प्रकृतिसे उत्पन्न सत्त्व रज और तमइन तीन गुणोंद्वारा परवश हुए अवश्य ही कर्मोंमें प्रवृत्त कर दिये जाते हैं। यहाँ सभी प्राणीके साथ अज्ञानी ( शब्द ) और जोड़ना चाहिये ( अर्थात् सभी अज्ञानी प्राणी ऐसे पढ़ना चाहिये ) क्योंकि आगे जो गुणोंसे विचलित नहीं किया जा सकता इस कथनसे ज्ञानियोंको अलग किया है अतः अज्ञानियोंके लिये ही कर्मयोग है ज्ञानियोंके लिये नहीं। क्योंकि जो गुणोंद्वारा विचलित नहीं किये जा सकते उन ज्ञानियोंमें स्वतः क्रियाका अभाव होनेसे उनके लिये कर्मयोग सम्भव नहीं है। ऐसे ही वेदाविनाशिनम् इस श्लोककी व्याख्यामें विस्तारपूर्वक कहा गया है।'),
('shankaracharya-ht:source:3.6','Śaṅkarācārya','gita.3.6','hi','translation','।।3.6।।जो आत्मज्ञानी न होनेपर भी शास्त्रविहित कर्म नहीं करता उसका वह कर्म न करना बुरा है यह कहते हैं जो मनुष्य हाथ पैर आदि कर्मेन्द्रियोंको रोककर इन्द्रियोंके भोगोंको मनसे चिन्तन करता रहता है वह विमूढात्मा अर्थात् मोहित अन्तःकरणवाला मिथ्याचारी ढोंगी पापाचारी कहा जाता है।'),
('shankaracharya-ht:source:3.7','Śaṅkarācārya','gita.3.7','hi','translation','।।3.7।।परंतु हे अर्जुन जो कर्मोंका अधिकारी अज्ञानी ज्ञानेन्द्रियोंको मनसे रोककर वाणी हाथ इत्यादि कर्मेन्द्रियोंसे आचरण करता है। किसका आचरण करता है सो कहते हैं आसक्तिरहित होकर कर्मयोगका आचरण करता है वह ( कर्मयोगी ) दूसरेकी अपेक्षा अर्थात् मिथ्याचारियोंकी अपेक्षा श्रेष्ठ है।'),
('shankaracharya-ht:source:3.8','Śaṅkarācārya','gita.3.8','hi','translation','।।3.8।।ऐसा होनेके कारण हे अर्जुन जो कर्म श्रुतिमें किसी फलके लिये नहीं बताया गया है ऐसे जिस कर्मका जो अधिकारी है उसके लिये वह नियत कर्म है उस नियत अर्थात् नित्य कर्मका तू आचरण कर क्योंकि कर्मोंके न करनेकी अपेक्षा कर्म करना परिणाममें बहुत श्रेष्ठ है। क्योंकि कुछ भी न करनेसे तो तेरी शरीरयात्रा भी नहीं चलेगी अर्थात् तेरे शरीरका निर्वाह भी नहीं होगा। इसलिये कर्म करने और न करनेमें जो अन्तर है वह संसारमें प्रत्यक्ष है।'),
('shankaracharya-ht:source:3.9','Śaṅkarācārya','gita.3.9','hi','translation','।।3.9।।जो तू ऐसा समझता है कि बन्धनकारक होनेसे कर्म नहीं करना चाहिये तो यह समझना भी भूल है। कैसे यज्ञ ही विष्णु है इस श्रुतिप्रमाणसे यज्ञ ईश्वर है और उसके लिये जो कर्म किया जाय वह यज्ञार्थ कर्म है उस ( ईश्वरार्थ ) कर्मको छोड़कर दूसरे कर्मोंसे कर्म करनेवाला अधिकारी मनुष्यसमुदाय कर्मबन्धनयुक्त हो जाता है पर ईश्वरार्थ किये जानेवाले कर्मसे नहीं। इसलिये हे कौन्तेय तू कर्मफल और आसक्तिसे रहित होकर ईश्वरार्थ कर्मोंका भली प्रकार आचरण कर।'),
('shankaracharya-ht:source:3.10','Śaṅkarācārya','gita.3.10','hi','translation','।।3.10।।इस आगे बतलाये जानेवाले कारणसे भी अधिकारीको कर्म करना चाहिये सृष्टिके आदिकालमें यज्ञसहित प्रजाको अर्थात् ( ब्राह्मण क्षत्रिय और वैश्य इन ) तीनों वर्णोंको रचकर जगत्के रचयिता प्रजापतिने कहा कि इस यज्ञसे तुमलोग प्रसवउत्पत्ति यानी वृद्धिलाभ करो। यह यज्ञतुमलोगोंको इष्ट कामनाओंका देनेवाला अर्थात् इच्छित फलरूप नाना भोगोंको देनेवाला हो।'),
('shankaracharya-ht:source:3.11','Śaṅkarācārya','gita.3.11','hi','translation','।।3.11।।कैसे तुमलोग इस यज्ञद्वारा इन्द्रादि देवोंको बढ़ाओ अर्थात् उनकी उन्नति करो। वे देव वृष्टि आदिद्वारा तुमलोगोंको बढ़ावें अर्थात् उन्नत करें। इस प्रकार एक दूसरेको उन्नत करते हुए ( तुमलोग ) ज्ञानप्राप्तिद्वारा मोक्षरूप परमश्रेयको प्राप्त करोगे। अथवा स्वर्गरूप परमश्रेयको ही प्राप्त करोगे।'),
('shankaracharya-ht:source:3.12','Śaṅkarācārya','gita.3.12','hi','translation','।।3.12।।दूसरी बात यह भी है कि यज्ञद्वारा बढ़ाये हुए संतुष्ट किये हुए देवता लोग तुमलोगोंको स्त्री पशु पुत्र आदि इच्छित भोग देंगे। उन देवोंद्वारा दिये हुए भोगोंको उन्हें न देकर अर्थात् उनका ऋण न चुकाकर जो खाता है केवल अपने शरीर और इन्द्रियोंको ही तृप्त करता है वह देवताओंके स्वत्वको हरण करनेवाला चोर ही है।'),
('shankaracharya-ht:source:3.13','Śaṅkarācārya','gita.3.13','hi','translation','।।3.13।।परंतु जो यज्ञशिष्ट अन्नका भोजन करनेवाले श्रेष्ठ पुरुष हैं अर्थात् देवयज्ञादि करके उससे बचे हुए अमृत नामक अन्नको भक्षण करना जिनका स्वभाव है वे सब पापोंसे अर्थात् गृहस्थमें होनेवाले चक्की चूल्हे आदिके पाँच पापोंसे और प्रमादसे होनेवाले हिंसादिजनित अन्य पापोंसे भी छूट जाते हैं। तथा जो उदरपरायण लोग केवल अपने लिये ही अन्न पकाते हैं वै स्वयं पापी हैं और पाप ही खाते हैं।'),
('shankaracharya-ht:source:3.14','Śaṅkarācārya','gita.3.14','hi','translation','।।3.14।।इसलिये भी अधिकारीको कर्म करना चाहिये क्योंकि कर्म जगत्चक्रकी प्रवृत्तिका कारण है। कैसे सो कहते हैं भक्षण किया हुआ अन्न रक्त और वीर्यके रूपमें परिणत होनेपर उससे प्रत्यक्षही प्राणी उत्पन्न होते है। पर्जन्यसे अर्थात् वृष्टिसे अन्नकी उत्पत्ति होती है और यज्ञसे वृष्टि होती है। अग्निमें विधिपूर्वक दी हुई आहुति सूर्यमें स्थित होती है सूर्यसे वृष्टि होती है वृष्टिसे अन्न होता है और अन्नसे प्रजा उत्पन्न होती है इस स्मृतिवाक्यसे भी यही बात पायी जाती है। ऋत्विक् और यजमानके व्यापारका नाम कर्म है और उस कर्मसे जिसकी उत्पत्ति होती है वह अपूर्वरूप यज्ञ कर्मसमुद्भव है अर्थात् वह अपूर्वरूप यज्ञ कर्मसे उत्पन्न होता है।'),
('shankaracharya-ht:source:3.15','Śaṅkarācārya','gita.3.15','hi','translation','।।3.15।।और उस क्रियारूप कर्मको तू वेदरूप ब्रह्मसे उत्पन्न हुआ जान अर्थात् कर्मकी उत्पत्तिका कारण वेद है ऐसे जान और वेदरूप ब्रह्म अक्षरसे उत्पन्न हुआ है अर्थात् अविनाशी परब्रह्म परमात्मा वेदकी उत्पत्तिका कारण है। वेदरूप ब्रह्म साक्षात् परमात्मा नामक अक्षरसे पुरुषके निःश्वासकी भाँति उत्पन्न हुआ है इसलिये वह सब अर्थोंको प्रकाशित करनेवाला होनेके कारण सर्वगत है। तथा यज्ञविधिमें वेदकी प्रधानता होनेके कारण वह सर्वगत होता हुआ ही सदा यज्ञमें प्रतिष्ठित है।'),
('shankaracharya-ht:source:3.16','Śaṅkarācārya','gita.3.16','hi','translation','।।3.16।।इस लोकमें जो मनुष्य कर्माधिकारी होकर इस प्रकार ईश्वरद्वारा वेद और यत्नपूर्वक चलाये हुए इस जगत्चक्रके अनुसार ( वेदाध्ययनयज्ञादि ) कर्म नहीं करता हे पार्थ वह पापायु अर्थात् पापमय जीवनवाला और इन्द्रियारामी अर्थात् इन्द्रियोंद्वारा विषयोंमें रमण करनेवाला व्यर्थ ही जीता है उस पापीका जीना व्यर्थ ही है। इसलिये इस प्रकरणका अर्थ यह हुआ कि अज्ञानी अधिकारीको कर्म अवश्य करना चाहिये। अनात्मज्ञ अधिकारी पुरुषको आत्मज्ञानकी योग्यता प्राप्त होनेके पहले ज्ञाननिष्ठाप्राप्तिके लिये कर्मयोगका अनुष्ठान अवश्य करना चाहिये यह न कर्मणामनारम्भात् यहाँसे लेकर शरीरयात्रापि च ते न प्रसिद्ध्येदकर्मणः इस श्लोकतकके वर्णनसे प्रतिपादन करके यज्ञार्थात्कर्मणोऽन्यत्र से लेकर मोघं पार्थ स जीवति तकके ग्रन्थसे भी आत्मज्ञानसे रहित कर्माधिकारीके लिये कर्मोंके अनुष्ठान करनेमें बहुतसे प्रसङ्गानुकूल कारण कहे गये तथा उन कर्मोंके न करनेमें बहुतसे दोष भी बतलाये गये। यदि ऐसा है तो क्या इस प्रकार चलाये हुए इस सृष्टिचक्रके अनुसार सभीको चलना चाहिये अथवा पूर्वोक्त कर्मयोगानुष्ठानरूप उपायसे प्राप्त होनेवाली और आत्मज्ञानी सांख्ययोगियोंद्वारा सेवन किये जाने योग्य ज्ञानयोगसे ही सिद्ध होनेवाली निष्ठाको न प्राप्त हुए अनात्मज्ञको ही इसके अनुसार बर्तना चाहिये ( या तो ) इस प्रकार अर्जुनके प्रश्नकी आशङ्का करके ( भगवान् बोले )'),
('shankaracharya-ht:source:3.17','Śaṅkarācārya','gita.3.17','hi','translation','।।3.17।।अथवा स्वयं ही भगवान् शास्त्रके अर्थको भलीभाँति समझानेके लिये यह जो प्रसिद्ध आत्मा है उसको जानकर जिनका मिथ्या ज्ञान निवृत्त हो चुका है ऐसे जो महात्मा ब्राह्मणगण अज्ञानियोंद्वारा अवश्य की जानेवाली पुत्रादिकी इच्छाओंसे रहित होकर केवल शरीरनिर्वाहके लिये भिक्षाका आचरण करते हैं उनका आत्मज्ञाननिष्ठासे अतिरिक्त अन्य कुछ भी कर्तव्य नहीं रहता ऐसा श्रुतिका तात्पर्य जो कि इस गीताशास्त्रमें प्रतिपादन करना उनको इष्ट है उस ( श्रुतिअर्थ ) को प्रकट करते हुए बोले परंतु जो आत्मज्ञाननिष्ठ सांख्ययोगी केवल आत्मामें ही रतिवाला है अर्थात् जिसका आत्मामें ही प्रेम है विषयोंमें नहीं और जो मनुष्य अर्थात् संन्यासी आत्मासे ही तृप्त है जिसकी तृप्ति अन्नरसादिके अधीन नहीं रह गयी है तथा जो आत्मामें ही संतुष्ट है बाह्य विषयोंके लाभसे तो सबको सन्तोष होता ही है पर उनकी अपेक्षा न करके जो आत्मामें ही सन्तुष्ट है अर्थात् सब ओरसे तृष्णारहित है। जो कोई ऐसा आत्मज्ञानी है उसके लिये कुछ भी कर्तव्य नहीं है।'),
('shankaracharya-ht:source:3.18','Śaṅkarācārya','gita.3.18','hi','translation','।।3.18।।क्योंकि उस परमात्मामें प्रीतिवाले पुरुषका इस लोकमें कर्म करनेसे कोई प्रयोजन ही नहीं रहता है। तो फिर कर्म न करनेसे उसको प्रत्यवायरूप अनर्थकी प्राप्ति होती होगी ( इसपर कहते हैं ) उसके न करनेसे भी उसे इस लोकमें कोई प्रत्यवायप्राप्तिरूप या आत्महानिरूप अनर्थकी प्राप्ति नहीं होती तथा ब्रह्मासे लेकर स्थावरतक सब प्राणियोंमें उसका कुछ भी अर्थव्यपाश्रय नहीं होता। किसी फलके लिये ( किसी प्राणिविशेषका ) जो क्रियासाध्य आश्रय है उसका नाम अर्थव्यपाश्रय है सो इस आत्मज्ञानीको किसी प्राणिविशेषका सहारा लेकर कोई प्रयोजन सिद्ध नहीं करना है जिससे कि उसे तदर्थक किसी क्रियाका आरम्भ करना पड़े। परन्तु तू इस सब ओरसे परिपूर्ण जलाशयस्थानीय यथार्थ ज्ञानमें स्थित नहीं है।'),
('shankaracharya-ht:source:3.19','Śaṅkarācārya','gita.3.19','hi','translation','।।3.19।।जब कि ऐसी बात है इसलिये तू आसक्तिरहित होकर कर्तव्य नित्यकर्मोंका सदा भलीभाँति आचरण किया कर। क्योंकिअनासक्त होकर कर्म करनेवाला अर्थात् ईश्वरार्थ कर्म करता हुआ पुरुष अन्तःकरणकी शुद्धिद्वारा मोक्षरूप परमपद पा लेता है।'),
('shankaracharya-ht:source:3.20','Śaṅkarācārya','gita.3.20','hi','translation','।।3.20।।एक और भी कारण है क्योंकि पहले जनकअश्वपति प्रभृति विद्वान् क्षत्रिय लोग कर्मोंद्वारा ही मोक्षप्राप्तिके लिये प्रवृत्त हुए थे। यहाँ इस श्लोककी व्याख्या इस प्रकार करनी चाहिये कि यदि वे जनकादि यथार्थ ज्ञानको प्राप्त हो चुके थे तब तो वे प्रारब्धकर्मा होनेके कारण लोकसंग्रहके लिये कर्म करते हुए ही अर्थात् संन्यास ग्रहण किये बिना ही परम सिद्धिको प्राप्त हुए और यदि वे जनकादि यथार्थ ज्ञानको प्राप्त नहीं थे तो वे अन्तःकरणकी शुद्धिके साधनरूप कर्मोंसे क्रमशः परम सिद्धिको प्राप्त हुए। यदि तू यह मानता हो कि आत्मतत्त्वको न जाननेवाले जनकादि पूर्वजोंद्वारा कर्तव्यकर्म किये गये हैं इससे यह नहीं हो सकता कि दूसरे आत्मज्ञानी कृतार्थ पुरुषोंको भी कर्म अवश्य करने चाहिये। तो भी तू प्रारब्धकर्मके अधीन है इसलिये तुझे लोकसंग्रहकी तरफ देखकर भी अर्थात् लोगोंकी उलटे मार्गमें जानेवाली प्रवृत्तिको निवारण करनारूप जो लोकसंग्रह है उस लोकसंग्रहरूप प्रयोजनको देखते हुए भी कर्म करना चाहिये।'),
('shankaracharya-ht:source:3.21','Śaṅkarācārya','gita.3.21','hi','translation','।।3.21।।लोकसंग्रह किसको करना चाहिये और किसलिये करना चाहिये सो कहते हैं श्रेष्ठ पुरुष जोजो कर्म करता है अर्थात् प्रधान मनुष्य जिसजिस कर्ममें बर्तता है दूसरे लोग उसके अनुयायी होकर उसउस कर्मका ही आचरण किया करते हैं। तथा वह श्रेष्ठ पुरुष जिसजिस लौकिक या वैदिक प्रथाको प्रामाणिक मानता है लोग उसीके अनुसार चलते हैं अर्थात् उसीको प्रमाण मानते हैं।'),
('shankaracharya-ht:source:3.22','Śaṅkarācārya','gita.3.22','hi','translation','।।3.22।।यदि इस लोकसंग्रहकी कर्तव्यतामें तुझे कुछ शंका हो तो तू मुझे क्यों नहीं देखता हे पार्थ तीनों लोकोंमें मेरा कुछ भी कर्तव्य नहीं है अर्थात् मुझे कुछ भी करना नहीं है क्योंकि मुझे कोई भी अप्राप्त वस्तु प्राप्त नहीं करनी है तो भी मैं कर्मोंमें बर्तता ही हूँ।'),
('shankaracharya-ht:source:3.23','Śaṅkarācārya','gita.3.23','hi','translation','।।3.23।।यदि मैं कदाचित् आलस्यरहित सावधान होकर कर्मोंमें न बरतूँ तो हे पार्थ ये मनुष्य सब प्रकारसे मुझ श्रेष्ठके मार्गका अनुकरण कर रहे हैं।'),
('shankaracharya-ht:source:3.24','Śaṅkarācārya','gita.3.24','hi','translation','।।3.24।।ऐसा होनेसे क्या दोष हो जायगा सो कहते हैं यदि मैं कर्म न करूँ तो लोकस्थितिके लिये किये जानेवाले कर्मोंका अभाव हो जानेसे यह सब लोक नष्ट हो जायँगे और मैं वर्णसंकरका कर्ता होऊँगा इसलिये इस प्रजाका नाश भी करूँगा अर्थात् प्रजापर अनुग्रह करनेमें लगा हुआ मैं इनका हनन करनेवाला बूनँगा। यह सब मुझ ईश्वरके अनुरूप नहीं होगा।'),
('shankaracharya-ht:source:3.25','Śaṅkarācārya','gita.3.25','hi','translation','।।3.25।।यदि मेरी तरह तू या दूसरा कोई कृतार्थबुद्धि आत्मवेत्ता हो तो उसको भी अपने लिये कर्तव्यका अभाव होनेपर भी केवल दूसरोंपर अनुग्रह ( करनेके लिये कर्म ) करना चाहिये हे भारत इस कर्मका फल मुझे मिलेगा इस प्रकार कर्मोंमें आसक्त हुए कई अज्ञानी मनुष्य जैसे कर्म करते हैं आत्मवेत्ता विद्वान्को भी आसक्तिरहित होकर उसी तरह कर्म करना चाहिये। आत्मज्ञानी उसकी तरह कर्म क्यों करता है सो सुन वह लोकसंग्रह करनेकी इच्छावाला है ( इसलिये करता है )।'),
('shankaracharya-ht:source:3.26','Śaṅkarācārya','gita.3.26','hi','translation','।।3.26।।इस प्रकार लोकसंग्रह करनेकी इच्छावाले मुझ परमात्माका या दूसरे आत्मज्ञानीका लोकसंग्रहको छोड़कर दूसरा कोई कर्तव्य नहीं रह गया है। अतः उस आत्मवेत्ताके लिये यह उपदेश किया जाता है बुद्धिको विचलित करनेका नाम बुद्धिभेद है ( ज्ञानीको चाहिये कि ) कर्मोंमें आसक्तिवाले विवेकरहित अज्ञानियोंकी बुद्धिमें भेद उत्पन्न न करे अर्थात् मेरा यह कर्तव्य है इस कर्मका फल मुझे भोगना है इस प्रकार जो उनकी निश्चितरूपा बुद्धि बनी हुई है उसको विचलित करना बुद्धिभेद करना है सो न करे। तो फिर क्या करे समाहितचित्त विद्वान् स्वयं अज्ञानियोंके ही ( सदृश ) उन कर्मोंका ( शास्त्रानुकूल ) आचरण करता हुआ उनसे सब कर्म करावे।'),
('shankaracharya-ht:source:3.27','Śaṅkarācārya','gita.3.27','hi','translation','।।3.27।।मूर्ख अज्ञानी मनुष्य कर्मोंमें किस प्रकार आसक्त होता है सो कहते हैं सत्त्व रजस् और तमस् इन तीनों गुणोंकी जो साम्यावस्था है उसका नाम प्रधान या प्रकृति है उस प्रकृतिके गुणोंसे अर्थात् कार्य और करणरूप समस्त विकारोंसे लौकिक और शास्त्रीय सम्पूर्ण कर्म सब प्रकारसे किये जाते हैं। परंतु अहंकारविमूढात्मा कार्य और करणके संघातरूप शरीरमें आत्मभावकी प्रतीतिका नाम अहंकार है उस अहंकारसे जिसका अन्तःकरण अनेक प्रकारसे मोहित हो चुका है ऐसा देहेन्द्रियके धर्मको अपना धर्म माननेवाला देहाभिमानी पुरुष अविद्यावश प्रकृतिके कर्मोंको अपनेमें मानता हुआ उनउन कर्मोंका मैं कर्ता हूँ ऐसा मान बैठता है।'),
('shankaracharya-ht:source:3.28','Śaṅkarācārya','gita.3.28','hi','translation','।।3.28।।परंतु जो ज्ञानी है हे महाबाहो वह तत्त्ववेत्ता किसका तत्त्ववेत्ता गुणकर्मविभागका अर्थात् गुणविभाग और कर्मविभागके तत्त्वको जाननेवाला ज्ञानी इन्द्रियादिरूप गुण ही विषयरूप गुणोंमें बर्त रहे हैं आत्मा नहीं बर्तता ऐसे मानकर आसक्त नहीं होता। उन कर्मोंमें प्रीति नहीं करता।'),
('shankaracharya-ht:source:3.29','Śaṅkarācārya','gita.3.29','hi','translation','।।3.29।।परंतु जो प्रकृतिके गुणोंसे अत्यन्त मोहित हुए पुरुष हम अमुक फलके लिये यह कर्म करते हैं इस प्रकार गुणोंके कर्मोंमें आसक्त होते हैं। उन पूर्णरूपसे न समझनेवाले कर्मफलमात्रको ही देखनेवाले और कर्मोंमें आसक्त मन्दबुद्धि पुरुषोंको अच्छी प्रकार समस्त तत्त्वको समझनेवाला आत्मज्ञानी पुरुष स्वयं चलायमान न करे। अभिप्राय यह कि बुद्धिभेद करना ही उनको चलायमान करना है सो न करे।'),
('shankaracharya-ht:source:3.30','Śaṅkarācārya','gita.3.30','hi','translation','।।3.30।।तो फिर कर्माधिकारी अज्ञानी मुमुक्षुको किस प्रकार कर्म करना चाहिये सो कहते हैं मुझ सर्वात्मरूप सर्वज्ञ परमेश्वर वासुदेवमें विवेकबुद्धिसे सब कर्म छोड़कर अर्थात् मैं सब कर्म ईश्वरके लिये सेवककी तरह कर रहा हूँ इस बुद्धिसे सब कर्म मुझमें अर्पण करके तथा निराशी आशारहित और निर्मम यानी जिसका मेरापन सर्वथा नष्ट हो चुका हो उसे निर्मम कहते हैं ऐसा होकर तू शोकरहित हुआ युद्ध कर अर्थात् चिन्तासंतापसे रहित हुआ युद्ध कर।'),
('shankaracharya-ht:source:3.31','Śaṅkarācārya','gita.3.31','hi','translation','।।3.31।।कर्म करने चाहिये ऐसा जो यह मत प्रमाणसहित कहा गया वह यथार्थ है ( ऐसा मानकर ) जो श्रद्धायुक्त मनुष्य गुरुस्वरूप मुझ वासुदेवमें असूया न करते हुए ( मेरे गुणोंमें दोष न देखते हुए ) मेरे इस मतके अनुसार चलते हैं वे ऐसे मनुष्य भी पुण्यपापरूप कर्मोंसे मुक्त हो जाते हैं।'),
('shankaracharya-ht:source:3.32','Śaṅkarācārya','gita.3.32','hi','translation','।।3.32।।परंतु जो उनसे विपरीत हैं मेरे इस मतको निन्दा करते हुए इस मेरे मतके अनुसार आचरण नहीं करते वे समस्त ज्ञानोंमें अनेक प्रकारसे मूढ़ हैं। सब ज्ञानोंमें मोहित हुए उन अविवेकियोंको तो तू नाशको प्राप्त हुए ही जान।'),
('shankaracharya-ht:source:3.33','Śaṅkarācārya','gita.3.33','hi','translation','।।3.33।।तो फिर वे ( लोग ) किस कारणसे आपके मतके अनुसार नहीं चलते दूसरेके धर्मका अनुष्ठान करते हैं और स्वधर्माचरण नहीं करते आपके प्रतिकूल होकर आपके शासनको उल्लङ्घन करनेके दोषसे क्यों नहीं डरते इसमें क्या कारण है इसपर कहते हैं सभी प्राणी एवं ज्ञानवान् भी अपनी प्रकृतिके अनुसार ही चेष्टा करते हैं अर्थात् जो पूर्वकृत पुण्यपाप आदिका संस्कार वर्तमान जन्मादिमें प्रकट होता है उसका नाम प्रकृति है उसके अनुसार ज्ञानवान् भी चेष्टा किया करता है। फिर मूर्खकी तो बात ही क्या है इसलिये सभी प्राणी ( अपनी ) प्रकृति अर्थात् स्वभावकी ओर जा रहे हैं इसमें मेरा या दूसरेका शासन क्या कर सकता है।'),
('shankaracharya-ht:source:3.34','Śaṅkarācārya','gita.3.34','hi','translation','।।3.34।।यदि सभी जीव अपनीअपनी प्रकृतिके अनुरूप ही चेष्टा करते हैं प्रकृतिसे रहित कोई है ही नहीं तब तो पुरुषके प्रयत्नकी आवश्यकता न रहनेसे विधिनिषेध बतलानेवाला शास्त्र निरर्थक होगा इसपर यह कहते हैं इन्द्रिय इन्द्रियके अर्थमें अर्थात् सभी इन्द्रियोंके शब्दादि विषयोंमें राग और द्वेष स्थित हैं अर्थात् इष्टमें राग और अनिष्टमें द्वेष ऐसे प्रत्येक इन्द्रियके विषयमें राग और द्वेष दोनों अवश्य रहते हैं। वहाँ पुरुषप्रयत्नकी और शास्त्रकी आवश्यकताका विषय इस प्रकार बतलाते हैं शास्त्रानुसार बर्तनेमें लगे हुए मनुष्यको चाहिये कि वह पहलेसे ही रागद्वेषके वशमें न हो। अभिप्राय यह कि मनुष्यकी जो प्रकृति है वह रागद्वेषपूर्वक ही अपने कार्यमें मनुष्यको नियुक्त करती है। तब स्वाभाविक ही स्वधर्मका त्याग और परधर्मका अनुष्ठान होता है। परंतु जब यह जीव प्रतिपक्षभावनासे रागद्वेषका संयम कर लेता है तब केवल शास्त्रदृष्टिवाला हो जाता है फिर यह प्रकृतिके वशमें नहीं रहता। इसलिये ( कहते हैं कि ) मनुष्यको रागद्वेषके वशमें नहीं होना चाहिये क्योंकि वे ( रागद्वेष ) ही इस जीवके परिपन्थी हैं अर्थात् चोरकी भाँति कल्याणमार्गमें विघ्न करनेवाले हैं।'),
('shankaracharya-ht:source:3.35','Śaṅkarācārya','gita.3.35','hi','translation','।।3.35।।रागद्वेषयुक्त मनुष्य तो शास्त्रके अर्थको भी उलटा मान लेता है और परधर्मको भी धर्म होनेके नाते अनुष्ठान करनेयोग्य मान बैठता है। परंतु उसका ऐसा मानना भूल है अच्छी प्रकार अनुष्ठान किये गये अर्थात् अंगप्रत्यंगोंसहित सम्पादन किये गये भी परधर्मकी अपेक्षा गुणरहित भी अनुष्ठान किया हुआ अपना धर्म कल्याणकर है अर्थात् अधिक प्रशंसनीय है। परधर्ममें स्थित पुरुषके जीवनकी अपेक्षा स्वधर्ममें स्थित पुरुषका मरण भी श्रेष्ठ है क्योंकि दूसरेका धर्म भयदायक है नरक आदि रूप भयका देनेवाला है।'),
('shankaracharya-ht:source:3.36','Śaṅkarācārya','gita.3.36','hi','translation','।।3.36।।अर्जुन बोला यद्यपि ध्यायतो विषयान् पुंसः रागद्वेषौ ह्यस्य परिपन्थिनौ इत्यादि प्रकरणोंमें अनर्थका मूल कारणबतलाया गया पर वह भिन्नभिन्न प्रकरणोंमें और अनिश्चितरूपसे कहा गया है। इसलिये वह अनर्थोंका कारण ठीक यही है। इस प्रकार निश्चयपूर्वक और संक्षेपसे जाननेमें आ जाय तो मैं उसके उच्छेदके लिये प्रयत्न करूँ इस विचारसे उसके जाननेकी इच्छा करता हुआ अर्जुन बोला हे वृष्णिकुलमें उत्पन्न हुए कृष्ण किस प्रधान कारणसे प्रयुक्त किया हुआ यह पुरुष स्वयं न चाहता हुआ भी राजासे प्रयुक्त किये हुए सेवककी तरह बलपूर्वक लगाया हुआसा पापकर्मका आचरण किया करता है। जिसको तू पूछता है सर्व अनर्थोंके कारणरूप उस वैरीके विषयमें सुन ( इस उद्देश्यसे ) भगवान् बोले आचार्य पहले भगवान् शब्दका अर्थ करते हैं। सम्पूर्ण ऐश्वर्य धर्म यश लक्ष्मी वैराग्य और मोक्ष इन छःका नाम भग है यह ऐश्वर्य आदि छहों गुण बिना प्रतिबन्धके सम्पूर्णतासे जिस वासुदेवमें सदा रहते हैं। तथा उत्पत्ति और प्रलयको भूतोंके आने और जानेको एवं विद्या और अविद्याको जो जानता है उसका नाम भगवान् है अतः उत्पत्ति आदि सब विषयोंको जो भलीभाँति जानते हैं वे वासुदेव भगवान् नामसे वाच्य हैं।'),
('shankaracharya-ht:source:3.37','Śaṅkarācārya','gita.3.37','hi','translation','।।3.37।।यह काम जो सब लोगोंका शत्रु है जिसके निमित्तसे जीवोंको सब अनर्थोंकी प्राप्ति होती है वहीं यह काम किसी कारणसे बाधित होनेपर क्रोधके रूपमें बदल जाता है इसलिये क्रोध भी यही है। यह काम रजोगुणसे उत्पन्न हुआ है अथवा यों समझो कि रजोगुणका उत्पादक है क्योंकि उत्पन्न हुआ काम ही रजोगुणको प्रकट करके पुरुषको कर्ममें लगाया करता है। तथा रजोगुणके कार्य सेवा आदिमें लगे हुए दुःखित मनुष्योंका ही यह प्रलाप सुना जाता है कि तृष्णा ही हमसे अमुक काम करवाती है इत्यादि। तथा यह काम बहुत खानेवाला है। इसलिये महापापी भी है क्योंकि कामसे ही प्रेरित हुआ जीव पाप किया करता है। इसलिये इस कामको ही तू इस संसारमें वैरी जान।'),
('shankaracharya-ht:source:3.38','Śaṅkarācārya','gita.3.38','hi','translation','।।3.38।।यह काम किस प्रकार वैरी है सो दृष्टान्तोंसे समझाते हैं जैसे प्रकाशस्वरूप अग्नि अपने साथ उत्पन्न हुए अन्धकाररूप धूएँसे और दर्पण जैसे मलसे आच्छादित हो जाता है तथा जैसे गर्भ अपने आवरणरूप जेरसे आच्छादित होता है वैसे ही उस कामसे यह ( ज्ञान ) ढका हुआ है।'),
('shankaracharya-ht:source:3.39','Śaṅkarācārya','gita.3.39','hi','translation','।।3.39।।जिसका ( उपर्युक्त श्लोकमें ) इदम् शब्दसे संकेत किया गया है जो कामसे आच्छादित है वह कौन है सो कहा जाता है ज्ञानीके ( विवेकीके ) इस कामरूप नित्य वैरीसे ज्ञान ढका हुआ है। ज्ञानी ही पहलेसे जानता है कि इसके द्वारा मैं अनर्थोंमें नियुक्त किया गया हूँ। इससे वह सदा दुखी भी होता है। इसलिये यह ज्ञानीका ही नित्य वैरी है मूर्खका नहीं क्योंकि वह मूर्ख तो तृष्णाके समय उसको मित्रके समान समझता है। फिर जब उसका परिणामरूप दुःख प्राप्त होता है तब समझता है कि तृष्णाके द्वारा मैं दुखी किया गया हूँ पहले नहीं जानता इसलिये यह काम ज्ञानीका ही नित्य वैरी है। कैसे कामके द्वारा ( ज्ञान आच्छादित है इसपर कहते हैं ) कामना इच्छा ही जिसका स्वरूप है जो अति कष्टसे पूर्ण होता है तथा जो अनल है भोगोंसे कभी भी तृप्त नहीं होता ऐसे कामनारूप वैरीद्वारा (ज्ञान आच्छादित है )।'),
('shankaracharya-ht:source:3.40','Śaṅkarācārya','gita.3.40','hi','translation','।।3.40।।ज्ञानको आच्छादित करनेवाला होनेके कारण जो सबका वैरी है वह काम कहाँ रहनेवाला है अर्थात् उसका आश्रय क्या है क्योंकि शत्रुके रहनेका स्थान जान लेनेपर सहजमें ही उसका नाश किया जा सकता है। इसपर कहते हैं इन्द्रियाँ मन और बुद्धि यह सब इस कामके अधिष्ठान अर्थात् रहनेके स्थान बतलाये जाते हैं। यह काम इन आश्रयभूत इन्द्रियादिके द्वारा ज्ञानको आच्छादित करके इस जीवात्माको नाना प्रकारसे मोहित किया करता है।'),
('shankaracharya-ht:source:3.41','Śaṅkarācārya','gita.3.41','hi','translation','।।3.41।।जब कि ऐसा है इसलिये हे भरतर्षभ तू पहले इन्द्रियोंको वशमें करके ज्ञान और विज्ञानके नाशक इस ऊपर बतलाये हुए वैरी पापाचारी कामका परित्याग कर। अभिप्राय यह कि शास्त्र और आचार्यके उपदेशसे जो आत्माअनात्मा और विद्याअविद्या आदि पदार्थोंका बोध होता है उसका नाम ज्ञान है एवं उसका जो विशेषरूपसे अनुभव है उसका नाम विज्ञान है अपने कल्याणकी प्राप्तिके कारणरूप उन ज्ञान और विज्ञानको यह काम नष्ट करनेवाला है इसलिये इसका परित्याग कर।'),
('shankaracharya-ht:source:3.42','Śaṅkarācārya','gita.3.42','hi','translation','।।3.42।।पहले इन्द्रियोंको वशमें करके कामरूप शत्रुका त्याग कर ऐसा कहा सो किसका आश्रय लेकर इसका त्याग करना चाहिये यह बतलाते हैं पण्डितजन बाह्य परिच्छिन्न और स्थूल देहकी अपेक्षा सूक्ष्म अन्तरस्थ और व्यापक आदि गुणोंसे युक्त होनेके कारण श्रोत्रादि पञ्च ज्ञानेन्द्रियोंको पर अर्थात् श्रेष्ठ कहते हैं। तथा इन्द्रियोंकी अपेक्षा संकल्पविकल्पात्मक मनको श्रेष्ठ कहते हैं और मनकी अपेक्षा निश्चयात्मिका बुद्धिको श्रेष्ठ बताते हैं। एवं जो बुद्धिपर्यन्त समस्त दृश्य पदार्थोंके अन्तरव्यापी है जिसके विषयमें कहा है कि उस आत्माको इन्द्रियादि आश्रयोंसे युक्त काम ज्ञानावरणद्वारा मोहित किया करता है वह बुद्धिका ( भी ) द्रष्टा परमात्मा ( सबसे श्रेष्ठ ) है।'),
('shankaracharya-ht:source:3.43','Śaṅkarācārya','gita.3.43','hi','translation','।।3.43।।इस प्रकार बुद्धिसे अति श्रेष्ठ आत्माको जानकर और आत्मासे ही आत्माको स्तम्भन करके अर्थात् शुद्ध मनसे अच्छी प्रकार आत्माको समाधिस्थ करके हे महाबाहो इस कामरूप दुर्जय शत्रुका त्याग कर अर्थात् जो दुःखसे वशमें किया जाता है उस अनेक दुर्विज्ञेय विशेषणोंसे युक्त कामका त्याग कर दे।'),
('shankaracharya-ht:source:4.1','Śaṅkarācārya','gita.4.1','hi','translation','।।4.1।।कर्मयोग जिसका उपाय है ऐसा जो यह संन्याससहित ज्ञाननिष्ठारूप योग पूर्वके दो अध्यायोंमें ( दूसरे और तीसरेमें ) कहा गया है जिसमें कि वेदका प्रवृत्तिधर्मरूप और निवृत्तिधर्मरूप दोनों प्रकारका सम्पूर्ण तात्पर्य आ जाता है आगे सारी गीतामें भी भगावन्को योग शब्दसे यही ( ज्ञानयोग ) विवक्षित है इसलिये वेदके अर्थको ( ज्ञानयोगमें ) परिसमाप्त यानी पूर्णरूपसे आ गया समझकर भगवान् वंशपरम्पराकथनसे उस ( ज्ञाननिष्ठारूप योग ) की स्तुति करते हैं श्रीभगवान् बोले जगत्प्रतिपालक क्षत्रियोंमें बल स्थापन करनेके लिये मैंने उक्त दो अध्यायोंमें कहे हुए इस योगको पहले सृष्टिके आदिकालमें सूर्यसे कहा था ( क्योंकि ) उस योगबलसे युक्त हुए क्षत्रिय ब्रह्मत्वकी रक्षा करनेमें समर्थ होते हैं तथा ब्राह्मण और क्षत्रियोंका पालन ठीक तरह हो जानेपर ये दोनों सब जगत्का पालन अनायास कर सकते हैं। इस योगका फल अविनाशी है इसलिये यह अव्यय है क्योंकि इस सम्यक् ज्ञाननिष्ठारूप योगका मोक्षरूप फल कभी नष्ट नहीं होता। उस सूर्यने यह योग अपने पुत्र मनुसे कहा और मनुने अपने पुत्र सबसे पहले राजा बननेवाले इक्ष्वाकुसे कहा।'),
('shankaracharya-ht:source:4.2','Śaṅkarācārya','gita.4.2','hi','translation','।।4.2।।इस प्रकार क्षत्रियोंकी परम्परासे प्राप्त हुए इस योगको राजर्षियोंने जो कि राजा और ऋषि दोनों थे जाना। हे परंतप ( अब ) वह योग इस मनुष्यलोकमें बहुत कालसे नष्ट हो गया है। अर्थात् उसकी सम्प्रदायपरम्परा टूट गयी है। अपने विपक्षियोंको पर कहते हैं उन्हें जो शौर्यरूप तेजकी किरणोंके द्वारा सूर्यके समान तपता है वह पपातप यानी शत्रुओंको तपानेवाला कहा जाता है।'),
('shankaracharya-ht:source:4.3','Śaṅkarācārya','gita.4.3','hi','translation','।।4.3।।अजितेन्द्रिय और दुर्बल मनुष्योंके हाथमें पड़कर यह योग नष्ट हो गया है यह देखकर और साथ ही लोगोंको पुरुषार्थरहित हुए देखकर वही यह पुराना योग यह सोचकर कि तू मेरा भक्त और मित्र है अब मैंने तुझसे कहा है क्योंकि यह ज्ञानरूप योग बड़ा ही उत्तम रहस्य है।'),
('shankaracharya-ht:source:4.4','Śaṅkarācārya','gita.4.4','hi','translation','।।4.4।।भगवान्ने असङ्गत कहा ऐसी धारणा किसीकी न हो जाय अतः उसको दूर करनेके लिये शङ्का करता हुआसा अर्जुन बोला आपका जन्म तो अर्वाचीन है अर्थात् अभी वसुदेवके घरमें हुआ है और सूर्यकी उत्पत्ति पहले सृष्टिके आदिमें हुई थी। तब मैं इस बातको अविरुद्धार्थयुक्त ( सुसङ्गत ) कैसे समझूँ कि जिन आपने इस योगको आदिकालमें कहा था वही आप मुझसे कह रहे हैं।'),
('shankaracharya-ht:source:4.5','Śaṅkarācārya','gita.4.5','hi','translation','।।4.5।।भगवान् श्रीवासुदेवके विषयमें मूर्खोंकी जो ऐसी शङ्का है कि ये ईश्वर नहीं हैं सर्वज्ञ नहीं हैं तथा जिस शङ्काको दूर करनेके लिये ही अर्जुनका यह प्रश्न है उसका निवारण करते हुए श्रीभगवान् बोले हे अर्जुन मेरे और तेरे पहले बहुत जन्म हो चुके हैं। उन सबको मैं जानता हूँ तू नहीं जानता क्योंकि पुण्यपाप आदिके संस्कारोंसे तेरी ज्ञानशक्ति आच्छादित हो रही है। परंतु मैं तो नित्यशुद्धबुद्धमुक्तस्वभाववाला हूँ इस कारण मेरी ज्ञानशक्ति आवरणरहित है इसलिये हे परन्तप मैं ( सब कुछ ) जानता हूँ।'),
('shankaracharya-ht:source:4.6','Śaṅkarācārya','gita.4.6','hi','translation','।।4.6।।तो फिर आप नित्य ईश्वरका पुण्यपापसे सम्बन्ध न होनेपर भी जन्म कैसे होता है इसपर कहा जाता है यद्यपि मैं अजन्मा जन्मरहित अव्ययात्मा अक्षीण ज्ञानशक्तिस्वभाववाला और ब्रह्मासे लेकर स्तम्बपर्यन्त सम्पूर्ण भूतोंका नियमन करनेवाला ईश्वर भी हूँ तो भी अपनी त्रिगुणात्मिका वैष्णवी मायाको जिसके वशमें सब जगत् बर्तता है और जिससे मोहित हुआ मनुष्य वासुदेवरूप अपनेआपको नहीं जानता उस अपनी प्रकृतिको अपने वशमें रखकर केवल अपनी लीलासे ही शरीरवालासा जन्म लिया हुआसा हो जाता हूँ अन्य लोगोंकी भाँति वास्तवमें जन्म नहीं लेता।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:4.7','Śaṅkarācārya','gita.4.7','hi','translation','।।4.7।।वह जन्म कब और किसलिये होता है सो कहते हैं हे भारत वर्णाश्रम आदि जिसके लक्षण हैं एवं प्राणियोंकी उन्नति और परम कल्याणका जो साधन है उस धर्मकी जबजब हानि होती है और अधर्मका अभ्युत्थान अर्थात् उन्नति होती है तबतब ही मैं मायासे अपने स्वरूपको रचता हूँ।'),
('shankaracharya-ht:source:4.8','Śaṅkarācārya','gita.4.8','hi','translation','।।4.8।।किसलिये सत्मार्गमें स्थित साधुओंका परित्राण अर्थात् ( उनकी ) रक्षा करनेके के लिये पापकर्म करनेवाले दुष्टोंका नाश करनेके लिये और धर्मकी अच्छी प्रकार स्थापना करनेके लिये मैं युगयुगमें अर्थात् प्रत्येक युगमें प्रकट हुआ करता हूँ।'),
('shankaracharya-ht:source:4.9','Śaṅkarācārya','gita.4.9','hi','translation','।।4.9।।वह मेरा मायामय जन्म और साधुरक्षण आदि कर्म दिव्य हैं अर्थात् अलौकिक हैं यानी केवल ईश्वरशक्तिसे ही होनेवाले हैं। इस प्रकार जो तत्त्वसे यथार्थ जानता है। हे अर्जुन वह इस शरीरको छोड़कर पुनर्जन्म अर्थात् पुनः उत्पत्तिको प्राप्त नहीं होता ( बल्कि ) मेरे पास आ जाता है अर्थात् मुक्त हो जाता है।'),
('shankaracharya-ht:source:4.10','Śaṅkarācārya','gita.4.10','hi','translation','।।4.10।।यह मोक्षमार्ग अभी आरम्भ हुआ है ऐसी बात नहीं किंतु पहले भी जिनके राग भय और क्रोध चले गये हैं ऐसे रागादि दोषोंसे रहित ईश्वरमें तन्मय हुए ईश्वरसे अपना अभेद समझनेवाले ब्रह्मवेत्ता और मुझ परमेश्वरके ही आश्रित केवल ज्ञाननिष्ठामें स्थित ऐसे बहुतसे महापुरुष परमात्मविषयक ज्ञानरूप तपसे परमशुद्धिको प्राप्त होकर मुझ ईश्वरके भावको मोक्षको प्राप्त हो गये हैं। ज्ञानतपसा यह विशेषण इस बातका द्योतक है कि ज्ञाननिष्ठा अन्य तपोंकी अपेक्षा नहीं रखती।'),
('shankaracharya-ht:source:4.11','Śaṅkarācārya','gita.4.11','hi','translation','।।4.11।।तब क्या आपमें रागद्वेष हैं जिससे कि आप किसीकिसीको ही आत्मभाव प्रदान करते हैं सबको नहीं करते इसपर कहते हैं जो भक्त जिस प्रकारसे जिस प्रयोजनसे जिस फलप्राप्तिकी इच्छासे मुझे भजते हैं उनको मैं उसी प्रकार भजता हूँ अर्थात् उनकी कामनाके अनुसार ही फल देकर मैं उनपर अनुग्रह करता हूँ क्योंकि उन्हेंमोक्षकी इच्छा नहीं होती। एक ही पुरुषमें मुमुक्षुत्व और फलार्थित्व ( फलकी इच्छा करना ) यह दोनों एक साथ नहीं हो सकते। इसलिये जो फलकी इच्छावाले हैं उन्हें फल देकर जो फलको न चाहते हुए शास्त्रोक्त प्रकारसे कर्म करनेवाले और मुमुक्षु हैं उनको ज्ञान देकर जो ज्ञानी संन्यासी और मुमुक्षु हैं उन्हें मोक्ष देकर तथा आर्तोंका दुःख दूर करके इस प्रकार जो जिस तरहसे मुझे भजते हैं उनको मैं भी वैसे ही भजता हूँ। रागद्वेषके कारण यह मोहके कारण तो मैं किसीको भी नहीं भजता। हे पार्थ मनुष्य सब तरहसे बर्तते हुए भी सर्वत्र स्थित मुझ ईश्वरके ही मार्गका सब प्रकारसे अनुसरण करते हैं जो जिस फलकी इच्छासे जिस कर्मके अधिकारी बने हुए ( उस कर्मके अनुरूप ) प्रयत्न करते हैं वे ही मनुष्य कहे जाते हैं।'),
('shankaracharya-ht:source:4.12','Śaṅkarācārya','gita.4.12','hi','translation','।।4.12।।यदि रागादि दोषोंका अभाव होनेके कारण सभी प्राणियोंपर आप ईश्वरकी दया समान है एवं आप सब फल देनेमें समर्थ भी हैं तो फिर सभी मनुष्य मुमुक्षु होकर यह सारा विश्व वासुदेवरूप है इस प्रकारके ज्ञानसे केवल आपको ही क्यों नहीं भजते इसका कारण सुन कर्मोंकी सिद्धि चाहनेवाले अर्थात् फलप्राप्तिकी कामना करनेवाले मनुष्य इस लोकमें इन्द्र अग्नि आदि देवोंकी पूजा किया करते हैं। श्रुतिमें कहा है कि जो अन्य देवताकी इस भावसे उपासना करता है कि वह ( देवता ) दूसरा है और मैं ( उपासक ) दूसरा हूँ वह कुछ नहीं जानता जैसे पशु होता है वैसे ही वह देवताओंका पशु है। ऐसे उन भिन्नरूपसे देवताओंका पूजन करनेवाले फलेच्छुक मनुष्योंकी इस मनुष्यलोकमें ( कर्मसे उत्पन्न हुई ) सिद्धि शीघ्र ही हो जाती है क्योंकि मनुष्यलोकमें शास्त्रका अधिकार है ( यह विशेषता है )। क्षिप्रं हि मानुषे लोके इस वाक्यमें क्षिप्र विशेषणसे भगवान् अन्य लोकोंमें भी कर्मफलकी सिद्धि दिखलाते हैं। पर मनुष्यलोकमें वर्णआश्रम आदिके कर्मोंका अधिकार है यह विशेषता है। उन वर्णाश्रम आदिमें अधिकार रखनेवालोंके कर्मोंकी कर्मजनित फलसिद्धि शीघ्र होती है।'),
('shankaracharya-ht:source:4.13','Śaṅkarācārya','gita.4.13','hi','translation','।।4.13।।मनुष्यलोकमें ही वर्णाश्रम आदिके कर्मोंका अधिकार है अन्य लोकोंमें नहीं यह नियम किस कारणसे है यह बतानेके लिये ( अगला श्लोक कहते हैं ) अथवा वर्णाश्रम आदि विभागसे युक्त हुए मनुष्य सब प्रकारसे मेरे मार्गके अनुसार बर्तते हैं ऐसा आपने कहा सो नियमपूर्वक वे आपके ही मार्गका अनुसरण क्यों करते हैं दूसरेके मार्गका क्यों नहीं करते इसपर कहते हैं ( ब्राह्मण क्षत्रिय वैश्य और शूद्र इन ) चारों वर्णोंका नाम चातुर्वर्ण्य है। सत्त्व रज तम इन तीनों गुणोंके विभागसे तथा कर्मोंके विभागसे यह चारों वर्ण मुझ ईश्वरद्वारा रचे हुए उत्पन्न किये हुए हैं। ब्राह्मण इस पुरुषका मुख हुआ इत्यादि श्रुतियोंसे यह प्रमाणित है। उनमेंसे सात्त्विक सत्त्वगुणप्रधान ब्राह्मणके शम दम तप इत्यादि कर्म हैं। जिसमें सत्त्वगुण गौण है और रजोगुण प्रधान है उस क्षत्रियके शूरवीरता तेज प्रभृति कर्म हैं। जिसमें तमोगुण गौण और रजोगुण प्रधान है ऐसे वैश्यके कृषि आदि कर्म हैं। तथा जिसमें रजोगुण गौण और तमोगुण प्रधान है उस शूद्रका केवल सेवा ही कर्म है। इस प्रकार गुण और कर्मोंके विभागसे चारों वर्ण मेरेद्वारा उत्पन्न किये गये हैं यह अभिप्राय है। ऐसी यह चार वर्णोंकी अलगअलग व्यवस्था दूसरे लोकोंमें नहीं है इसलिये ( पूर्वश्लोकमें ) मानुषे लोके यह विशेषण लगाया गया है। यदि चातुर्वर्ण्यकी रचना आदि कर्मके आप कर्ता हैं तब तो उसके फलसे भी आपका सम्बन्ध होता ही होगा इसलिये आप नित्यमुक्त और नित्यईश्वर भी नहीं हो सकते इसपर कहा जाता है यद्यपि मायिक व्यवहारसे मैं उस कर्मका कर्ता हूँ तो भी वास्तवमें मुझे तू अकर्ता ही जान तथा इसीलिये मुझे अव्यय और असंसारी ही समझ।'),
('shankaracharya-ht:source:4.14','Śaṅkarācārya','gita.4.14','hi','translation','।।4.14।।जिन कर्मोंका तू मुझे कर्ता मानता है वास्तवमें मैं उनका अकर्ता ही हूँ क्योंकि मुझमें अहंकारका अभाव है इसलिये वे कर्म देहादिकी उत्पत्तिके कारण बनकर मुझे लिप्त नहीं करते और उन कर्मोंके फलमें मेरी लालसा अर्थात् तृष्णा भी नहीं है। जिन संसारी मनुष्योंका कर्मोंमें मैं कर्ता हूँ ऐसा अभिमान रहता है एवं जिनकी उन कर्मोंमें और उनके फलोमें लालसा रहती है उनको कर्म लिप्त करते हैं यह ठीक है परंतु उन दोनोंका अभाव होनेके कारण वे ( कर्म ) मुझे लिप्त नहीं कर सकते। इस प्रकार जो कोई दूसरा भी मुझे आत्मरूपसे जान लेता है कि मैं कर्मोंका कर्ता नहीं हूँ मेरी कर्मफलमें स्पृहा भी नहीं है वह भी कर्मोंसे नहीं बँधता अर्थात् उसके भी कर्म देहादिके उत्पादक नहीं होते।'),
('shankaracharya-ht:source:4.15','Śaṅkarācārya','gita.4.15','hi','translation','।।4.15।।मैं न तो कर्मोंका कर्ता ही हूँ और न मुझे कर्मफलकी चाहना ही है ऐसा समझकर ही पूर्वकालके मुमुक्षु पुरुषोंने भी कर्म किये थे। इसलिये तू भी कर्म ही कर। तेरे लिये चुपचाप बैठ रहना या संन्यास लेना यह दोनों ही कर्तव्य नहीं है। क्योंकि पूर्वजोंने भी कर्मका आचरण किया है इसलिये यदि तू आत्मज्ञानी नहीं है तब तो अन्तःकरणकी शुद्धिके लिये और यदि तत्त्वज्ञानी है तो लोकसंग्रहके लिये जनकादि पूर्वजोंद्वारा सदासे किये हुए (प्रकारसे ही ) कर्म कर नये ढंगसे किये जानेवाले कर्म मत कर।'),
('shankaracharya-ht:source:4.16','Śaṅkarācārya','gita.4.16','hi','translation','।।4.16।।यदि कर्म ही कर्तव्य है तो मैं आपकी आज्ञासे ही करनेको तैयार हूँ फिर पूर्वैः पूर्वतरं कृतम् विशेषण देनेकी क्या आवश्यकता है इसपर कहते हैं कि कर्मके विषयमें बड़ी भारी विषमता है अर्थात् कर्मका विषय बड़ा गहन है। सो किस प्रकार कर्म क्या है और अकर्म क्या है इस कर्मादिके विषयमें बड़ेबड़े बुद्धिमान् भी मोहित हो चुके हैं इसलिये मैं तुझे वह कर्म और अकर्म बतलाऊँगा जिस कर्मादिको जानकर तू अशुभसे यानी संसारसे मुक्त हो जायगा।'),
('shankaracharya-ht:source:4.17','Śaṅkarācārya','gita.4.17','hi','translation','।।4.17।।तुझे यह नहीं समझना चाहिये कि केवल देहादिकी चेष्टाका नाम कर्म है और उसे न करके चुपचाप बैठ रहनेका नाम अकर्म है उसमें जाननेकी बात ही क्या है यह तो लोकमें प्रसिद्ध ही है। क्यों ( ऐसा नहीं समझना चाहिये ) इस पर कहते हैं कर्मकाशास्त्रविहित क्रियाका भी ( रहस्य ) जानना चाहिये विकर्मकाशास्त्रवर्जित कर्मका भी ( रहस्य ) जानना चाहिये और अकर्मका अर्थात् चुपचाप बैठ रहनेका भी ( रहस्य ) समझना चाहिये। क्योंकि कर्मोंकी अर्थात् कर्म अकर्म और विकर्मकी गति उनका यथार्थ स्वरूप तत्त्व बड़ा गहन है समझनेमें बड़ा ही कठिन है।'),
('shankaracharya-ht:source:4.18','Śaṅkarācārya','gita.4.18','hi','translation','।।4.18।।कर्मादिका वह तत्त्व क्या है जो कि जाननेयोग्य है जिसके लिये आपने यह प्रतिज्ञा की थी कि कहूँगा। इसपर कहते हैं जो कुछ किया जाय उस चेष्टामात्रका नाम कर्म है। उस कर्ममें जो अकर्म देखता है अर्थात् कर्मका अभाव देखता है तथा अकर्ममें शरीरादिकी चेष्टाके अभावमें जो कर्म देखता है। अर्थात् कर्मका करना और न करना दोनों ही कर्ताके अधीन हैं। तथा आत्मतत्त्वकी प्राप्तिसे पूर्व अज्ञानावस्थामें ही सब क्रियाकारक आदि व्यवहार है ( इसीलिये कर्मका त्याग भी कर्म ही है ) इस प्रकार जो अकर्ममें कर्म देखता है। वह मनुष्योंमें बुद्धिमान् है वह योगी है और वह समस्त कर्मोंको करनेवाला है इस प्रकार कर्ममें अकर्म और अकर्ममें कर्म देखनेवालेकी स्तुति की जाती है। पू0 जो कर्ममें अकर्म देखता है और अकर्ममें कर्म देखता है यह विरुद्ध बात किस भावसे कही जा रही है क्योंकि कर्म तो अकर्म नहीं हो सकता और अकर्म कर्म नहीं हो सकता तब देखनेवाला विरुद्ध कैसे देखे उ0 वास्तवमें जो अकर्म है वही मूढमति लोगोंको कर्मके सदृश भास रहा है और उसी तरह कर्म अकर्मके सदृश भास रहा है उसमें यथार्थ तत्त्व देखनेके लिये भगवान्ने कर्मणि अकर्म यः पश्येत् इत्यादि वाक्य कहे हैं इसलिये ( उनका कहना ) विरुद्ध नहीं है क्योंकि बुद्धिमान् आदि विशेषण भी तभी सम्भव हो सकते हैं। इसके सिवा यथार्थ ज्ञानको ही जाननेयोग्य कहा जा सकता है ( मिथ्या ज्ञानको नहीं )। तथा जिसको जानकर अशुभसे मुक्त हो जायगा। यह भी कहा है सो विपरीत ज्ञानद्वारा ( जन्ममरणरूप ) अशुभसे मुक्ति नहीं हो सकती। सुतरां प्राणियोंने जो कर्म और अकर्मको विपरीतरूपसे समझ रक्खा है उस विपरीत ज्ञानको हटानेके लिये ही भगवान्के कर्मण्यकर्म यः इत्यादि वचन हैं। यहाँ कुण्डेमें बेरोंकी तरह कर्मका आधार अकर्म नहीं है और उसी तरह अकर्मका आधार कर्म भी नहीं है क्योंकि कर्मके अभावका नाम अकर्म है। इसलिये ( यही सिद्ध हुआ कि ) मृगतृष्णामें जलकी भाँति एवं सीपमें चाँदीकी तरह लोगोंने कर्म और अकर्मको विपरीत मान रक्खा है। पू0 कर्मको सब कर्म ही मानते हैं इसमें कभी फेरफार नहीं होता। उ0 यह बात नहीं क्योंकि नाव चलते समय नौकामें बैठे हुए पुरुषको तटके अचल वृक्षोंमें प्रतिकूल गतिदीखती है अर्थात् वे वृक्ष उलटे चलते हुए दीखते हैं और जो ( नक्षत्रादि ) पदार्थ नेत्रोंके पास नहीं होते बहुत दूर होते हैं उन चलते हुए पदार्थोंमें भी गतिका अभाव दीख पड़ता है अर्थात् वे अचल दीखते हैं। इसी तरह यहाँ भी अकर्ममें ( क्रियारहित आत्मामें ) मैं करता हूँ यह कर्मका देखना और ( त्यागरूप ) कर्ममें ( मैं कुछ नहीं करता इस ) अकर्मका देखना ऐसे विपरीत देखना होता है अतः उसका निराकरण करनेके लिये कर्मणि अकर्म यः पश्येत् इत्यादि वचन भगवान् कहते हैं। यद्यपि यह विषय अनेक बार शंकासमाधानोंद्वारा सिद्ध किया जा चुका है तो भी अत्यन्त विपरीत ज्ञानकी भावनासे अत्यन्त मोहित हुए लोग अनेक बार सुने हुए तत्त्वको भी भूलकर मिथ्या प्रसंग लालाकर शंका करने लग जाते हैं इसलिये तथा आत्मतत्त्वको दुर्विज्ञेय समझकर भगवान् पुनःपुनः उत्तर देते हैं। श्रुति स्मृति और न्यायसिद्ध जो आत्मामें कर्मोंका अभाव है वह अव्यक्तोऽयमचिन्त्योऽयम् न जायते म्रियते इत्यादि श्लोकोंसे कहा जा चुका और आगे भी कहा जायगा। उस क्रियारहित आत्मामें अर्थात् अकर्ममें कर्मका देखनारूप जो विपरीत दर्शन है यह लोगोंमें अत्यन्त स्वाभाविकसा हो गया है। क्योंकि कर्म क्या है और अकर्म क्या है इस विषयमें बुद्धिमान् भी मोहित हैं। अर्थात् देहइन्द्रियादिसे होनेवाले कर्मोंका आत्मामें अध्यारोप करके मैं कर्ता हूँ मेरा यह कर्म है मुझे इसका फल भोगना है इस प्रकार ( लोग मानते हैं। ) तथा मैं चुप होकर बैठता हूँ जिससे कि परिश्रमरहित और कर्मरहित होकर सुखी हो जाऊँ इस प्रकार देहइन्द्रियोंके व्यापारकी उपरामताका और उससे होनेवाले सुखीपनका आत्मामें अध्यारोप करके मैं कुछ भी नहीं करता हूँ चुपचाप सुखसे बैठा हूँ इस प्रकार लोग मानते हैं। लोगोंके इस विपरीत ज्ञानको हटानेके लिये कर्मणि अकर्म यः पश्येत् इत्यादि वचन भगवान्ने कहे हैं। यहाँ देहेन्द्रियादिके आश्रयसे होनेवाला कर्म यद्यपि क्रियारूप है तो भी उसका लोगोंने कर्मरहित अविक्रिय आत्मामें अध्यारोप कर रक्खा है क्योंकि शास्त्रज्ञ विद्वान् भी मैं करता हूँ ऐसा मान बैठता है। अतः नदीतीरस्थ वृक्षोंमें भ्रमसे प्रतिकूल गति प्रतीत होनेकी भाँति अज्ञानसे आत्माके नित्य सम्बन्धी माने जाकर जो लोकमें कर्म नामसे प्रसिद्ध हो रहे हैं उन कर्मोंमें वस्तुतः नदीतीरस्थ वृक्षोंमें गतिका अभाव देखनेकी भाँति जो अकर्म देखता है अर्थात् कर्माभाव देखता है तथा कर्मकी भाँति आत्मामें अज्ञानसे आरोपित किये हुए शरीर इन्द्रिय आदिकी उपरामतारूप अकर्ममें अर्थात् क्रियाके त्यागमें भी मैं कुछ न करता हुआ चुपचाप सुखपूर्वक बैठा हूँ इस अहंकारका सम्बन्ध होनेके कारण जो कर्म देखता है यानी उस त्यागको भी जो कर्म समझता है। इस प्रकार जो कर्म और अकर्मके विभागको ( तत्त्वसे ) जाननेवाला है वह मनुष्योंमें बुद्धिमान् पण्डित है वह युक्त योगी है और सम्पूर्ण कर्म करनेवाला भी वही है अर्थात् वह पुण्यपापरूप अशुभसे मुक्त हुआ कृतकृत्य है। कई टीकाकार इस श्लोककी दूसरी तरहसे ही व्याख्या करते हैं। कैसे ईश्वरके लिये किये जानेवाले जो ( पञ्च महायज्ञादि ) नित्यकर्म हैं उनका फल नहीं मिलता इस कारण वे गौणी वृत्तिसे अकर्म कहे जाते हैं ( इसी प्रकार ) उन नित्यकर्मोंके न करनेका नाम अकर्म है वह भी पापरूप फलके देनेवाला होनेके कारण गौणरूपसे ही कर्म कहा जाता है। जैसे कोई गौ ब्यायी हुई होनेपर भी यदि दूधरूप फल नहीं देती तो वह अगौ कह दी जाती है वैसे ही नित्यकर्ममें उसके फलका अभाव होनेके कारण जो अकर्म देखता है और नित्यकर्मका न करनारूप जो अकर्म है उसमें कर्म देखता है क्योंकि वह नरकादि विपरीत फल देनेवाला है। यह व्याख्या ठीक नहीं है क्योंकि इस प्रकार जाननेसे अशुभसे मुक्ति नहीं हो सकती अर्थात् जन्ममरणबन्धन नहीं टूट सकता। अतः यह अर्थ मान लेनेसे भगवान्के कहे हुए ये वचन कि जिसको जानकर तू अशुभसे मुक्त हो जायगा। कट जायँगे। क्योंकि नित्यकर्मोंके अनुष्ठानसे तो शायद अशुभसे छुटकारा हो भी जाय परंतु उन नित्यकर्मोंका फल नहीं होता इस ज्ञानसे तो मोक्ष हो ही नहीं सकता। क्योंकि नित्यकर्मोंका फल नहीं होता यह ज्ञान या नित्यकर्मोंका ज्ञान अशुभसे मुक्त कर देनेवाला है ऐसा शास्त्रोंमें कहीं नहीं कहा और न भगवान्ने ही गीताशास्त्रमें कहीं ऐसा कहा है। इसी युक्तिसे ( उनके बतलाये हुए ) अकर्ममें कर्मदर्शनका भी खण्डन हो जाता है। क्योंकि यहाँ ( गीतामें ) नित्यकर्मोंके अभावरूप अकर्ममें कर्म देखनेको कहीं कर्तव्यरूपसे विधान नहीं किया केवल नित्यकर्मकी कर्तव्यताका विधान है। इसके सिवा नित्यकर्म न करनेसे पाप होता है ऐसा जान लेनेसे ही कोई फल नहीं हो सकता। और यह नित्यकर्मका न करनारूप अकर्म शास्त्रोंमें कोई जाननेयोग्य विषय भी नहीं बताया गया है। तथा इस प्रकार दूसरे टीकाकारोंके माने हुए कर्ममें अकर्म और अकर्ममें कर्मदर्शन रूप इस मिथ्यादर्शनसे अशुभसे मुक्ति बुद्धिमत्ता युक्तता सर्वकर्मकर्तृत्व इत्यादि फल भी सम्भव नहीं और ऐसे मिथ्याज्ञानकी स्तुति भी नहीं बन सकती। जब कि मिथ्याज्ञान स्वयं ही अशुभरूप है तब वह दूसरे अशुभसे किसीको कैसे मुक्त कर सकेगा क्योंकि अन्धकार ( कभी ) अन्धकारका नाशक नहीं हो सकता। पू0 यहाँ जो कर्ममें अकर्म देखना और अकर्ममें कर्म देखना ( उन टीकाकारोंने ) बतलाया है वह मिथ्याज्ञान नहीं है किंतु फलके होने और न होनेके निमित्तसे गौणरूपसे देखना है। उ0 यह कहना भी ठीक नहीं क्योंकि गौणरूपसे कर्मको अकर्म और अकर्मको कर्म जान लेनेसे भी कोई लाभ नहीं सुना गया। इसके सिवा श्रुतिसिद्ध बातको छोड़कर श्रुतिविरुद्ध बातकी कल्पना करनेमें कोई विशेषता भी नहीं दिखलायी देती। ( भगवान्को यदि यही अभीष्ट होता तो वे ) उसी प्रकारके शब्दोंसे भी स्पष्ट कह सकते थे कि नित्यकर्मोंका कोई फल नहीं है और उनके न करनेसे नरकप्राप्ति होती है। फिर इस प्रकार कर्ममें जो अकर्म देखता है इत्यादि दूसरोंको मोहित करनेवाले मायायुक्त वचन कहनेसे क्या प्रयोजन था। इस प्रकार उपर्युक्त अर्थ करनेवालोंका तो स्पष्ट ही यह मानना हुआ कि भगवान्द्वारा कहे हुए वचन संसारको मोहित करनेके लिये हैं। इसके सिवा न तो यह कहना ही उचित है कि यह नित्यकर्मअनुष्ठानरूप विषय मायायुक्त वचनोंसे गुप्त रखनेयोग्य है और न यही कहना ठीक है कि ( यह विषय बड़ा गहन है इसलिये ) बारंबार दूसरेदूसरे शब्दोंद्वारा कहनेसे सुबोध होगा। क्योंकि कर्मण्येवाधिकारस्ते इस श्लोकमें स्पष्ट कहे हुए अर्थको फिर कहनेकी आवश्यकता नहीं होती। तथा सभी जगह जो बात करनेयोग्य होती है वही प्रशसंनीय और जाननेयोग्य बतलायी जाती है। निरर्थक बातको जाननेयोग्य है ऐसा नहीं कहा जाता। मिथ्याज्ञान या उसके द्वारा स्थापित की हुई आभासमात्र वस्तु जाननेयोग्य नहीं हो सकती। इसके सिवा नित्यकर्मोंके न करनेरूप अभावसे प्रत्यवायरूप भावकी उत्पत्ति भी नहीं हो सकती। क्योंकि नासतो विद्यते भावः इत्यादि भगवान्के वाक्य हैं तथा असत्से सत् कैसे उत्पन्न हो सकता है इत्यादि श्रुतिवाक्य भी पहले दिखलाये जा चुके हैं। इस प्रकार असत्से सत्की उत्पत्तिका निषेध कर दिया जानेपर भी जो असत्से सत्की उत्पत्ति बतलाते हैं उनका तो यह कहना हुआ कि असत् तो सत् होता है और सत् असत् होता है परंतु यह सब प्रमाणोंसे विरुद्ध होनेके कारण अयुक्त है। तथा शास्त्र भी निरर्थक कर्मोंका विधान नहीं कर सकता क्योंकि सभी कर्म ( परिश्रमकी दृष्टिसे ) दुःख रूप हैं और जानबूझकर ( बिना प्रयोजन ) किसीका भी दुःखमें प्रवृत्त होना सम्भव नहीं। तथा उन नित्यकर्मोंको न करनेसे नरकप्राप्ति होती है ऐसा शास्त्रका आशय मान लेनेपर तो यह मानना हुआ कि कर्म करने और न करनेमें दोनों प्रकारसे शास्त्र अनर्थका ही कारण है अतः व्यर्थ है। इसके सिवा नित्यकर्मोंका फल नहीं है ऐसा मानकर फिर उनको मोक्षरूप फलके देनेवाला कहनेसे उन व्याख्याकारोंके मतमें स्वचोविरोध भी होता है। सुतरां कर्मणि अकर्म यः पश्येत् इत्यादि श्लोकका अर्थ जैसा ( गुरुपरम्परासे ) सुना गया है वही ठीक है और हमने भी उसीके अनुसार इस श्लोककी व्याख्या की है।'),
('shankaracharya-ht:source:4.19','Śaṅkarācārya','gita.4.19','hi','translation','।।4.19।।उपर्युक्त कर्ममें अकर्म और अकर्ममें कर्मदर्शनकी स्तुति करते हैं जिनका प्रारम्भ किया जाता है उनका नाम समारम्भ है इस व्युत्पत्तिसे सम्पूर्ण कर्मोंका नाम समारम्भ है। उपर्युक्त प्रकारसे कर्ममें अकर्म और अकर्ममें कर्म देखनेवाले जिस पुरुषके समस्त समारम्भ ( कर्म ) कामनासे और कामनाके कारणरूप संकल्पोंसे भी रहित हो जाते हैं अर्थात् जिसके द्वारा बिना ही किसी अपने प्रयोजनके यदि वह प्रवृत्तिमार्गवाला है तो लोकसंग्रहके लिये और निवृत्तिमार्गवाला है तो जीवनयात्रानिर्वाहके लिये केवल चेष्टामात्र ही क्रिया होती है तथा कर्ममें अकर्म और अकर्ममें कर्मदर्शनरूप ज्ञानाग्निसे जिसके पुण्यपापरूप सम्पूर्ण कर्म दग्ध हो गये हैं ऐसे ज्ञानाग्निदग्धकर्मा पुरुषको ब्रह्मवेत्ताजन वास्तवमें पण्डित कहते हैं। जो कर्ममें अकर्म और अकर्ममें कर्म देखनेवाला है वह यदि विवेक होनेसे पूर्व कर्मोंमें लगा हो तो भी कर्ममें अकर्म और अकर्ममें कर्मका ज्ञान हो जानेसे केवल जीवननिर्वाहमात्रके लिये चेष्टा करता हुआ कर्मरहित संन्यासी ही हो जाता है फिर उसकी कर्मोंमें प्रवृत्ति नहीं होती। अर्थात् जो पहले कर्म करनेवाला हो और पीछे जिसको आत्माका सम्यक् ज्ञान हुआ हो ऐसा पुरुष कर्मोंमें कोई प्रयोजन न देखकर साधनोंसहित कर्मोंका त्याग कर ही देता है। परंतु किसी कारणसे कर्मोंका त्याग करना असम्भव होनेपर कोई ऐसा पुरुष यदि कर्मोंमें और उनके फलमें आसक्तिरहित होकर केवल लोकसंग्रहके लिये पहलेके सदृश कर्म करता रहता है तो भी निजका प्रयोजन न रहनेके कारण ( वास्तवमें ) वह कुछ भी नहीं करता।'),
('shankaracharya-ht:source:4.20','Śaṅkarācārya','gita.4.20','hi','translation','।।4.20।।क्योंकि ज्ञानरूप अग्निद्वारा भस्मीभूत हो जानेके कारण उसके कर्म अकर्म ही हो जाते हैं। इसी आशयको दिखानेकी इच्छासे भगवान् कहते हैं उपर्युक्त ज्ञानके प्रभावसे कर्मोंमें अभिमान और फलासक्तिका त्याग करके जो नित्यतृप्त है अर्थात् विषयकामनासे रहित हो गया है तथा आश्रयसे रहित है। जिस फलका आश्रय लेकर मनुष्य पुरुषार्थ सिद्ध करनेकी इच्छा किया करता है उसका नाम आश्रय है ऐसे इस लोक और परलोकके इष्टफलसाधनरूप आश्रयसे जो रहित है उस ज्ञानीद्वारा किये हुए कर्म वास्तवमें अकर्म ही हैं क्योंकि वह निष्क्रिय आत्माके ज्ञानसे सम्पन्न है। अपना कोई प्रयोजन न रहनेके कारण ऐसे पुरुषको साधनोंसहित कर्मोंका परित्याग कर ही देना चाहिये ऐसी कर्तव्यता प्राप्त होनेपर भी उन कर्मोंसे निवृत्त होना असम्भव होनेके कारण लोकसंग्रहकी इच्छासे या श्रेष्ठ पुरुषोंद्वारा की जानेवाली निन्दाको दूर करनेकी इच्छासे यदि ( कोई ज्ञानी ) पहलेकी तरह कर्मोंमें प्रवृत्त है तो भी वह निष्क्रिय आत्माके ज्ञानसे सम्पन्न होनेके कारण वास्तवमें कुछ भी नहीं करता। परंतु जो उससे विपरीत है अर्थात् उपर्युक्त प्रकारसे कर्म करनेवाला नहीं है कर्मोंका आरम्भ करनेसे पहले ( गृहस्थी न बनकर ब्रह्मचर्य आश्रममें ) ही जिसका सबके अंदर व्यापक अन्तरात्मारूप निष्क्रिय ब्रह्ममें आत्मभाव प्रत्यक्ष हो गया है'),
('shankaracharya-ht:source:4.21','Śaṅkarācārya','gita.4.21','hi','translation','।।4.21।।वह केवल शरीरयात्राके लिये चेष्टा करनेवाला ज्ञाननिष्ठ यति इस लोक और परलोकके समस्त इच्छित भोगोंको आशासे रहित होनेके कारण इस लोक और परलोकके भोगरूप फल देनेवाले कर्मोंमें अपना कोई भी प्रयोजन न देखकर कर्मोंको और कर्मोंके साधनोंको त्यागकर मुक्त हो जाता है। इसी भावको दिखलानेके लिये ( अगला श्लोक ) कहते हैं जिसकी सम्पूर्ण आशाएँ दूर हो गयी हैं वह निराशीः है जिसने चित्त यानी अन्तःकरणको और आत्मा यानी बाह्य कार्यकरणके संघातरूप शरीरको इन दोनोंको भलीप्रकार अपने वशमें कर लिया है वह यतचित्तात्मा कहलाता है जिसने समस्त परिग्रहका अर्थात् भोगोंकी सामग्रीका सर्वथा त्याग कर दिया है वह त्यक्तसर्वपरिग्रह है। ऐसा पुरुष केवल शरीरस्थितिमात्रके लिये किये जानेवाले और अभिमानरहित कर्मोंको करता हुआ पापकोअर्थात् अनिष्टरूप पुण्य पाप दोनोंको नहीं प्राप्त होता। बन्धनकारक होनेसे धर्म भी मुमुक्षुके लिये तो पाप ही है। यहाँ शारीरं केवलं कर्म इस पदमें शरीरद्वारा होनेवाले कर्म शारीरिक कर्म माने गये हैं या शरीरनिर्वाहमात्रके लिये जानेवाले कर्म शारीरिक कर्म माने गये हैं चाहे शरीरद्वारा होनेवाले कर्म शारीरिक कर्म माने जायँ या शरीरनिर्वाहमात्रके लिये किये जानेवाले कर्म शारीरिक कर्म माने जायँ इस विवेचनसे क्या प्रयोजन है इसपर कहते हैं जो शरीरद्वारा होनेवाले कर्मोंका नाम शारीरिक कर्म मान लिया जाय तो इस लोकमें या परलोकमें फल देनेवाले निषिद्ध कर्मोंको भी शरीरद्वारा करता हुआ मनुष्य पापको प्राप्त नहीं होता ऐसा कहनेसे भगवान्के कथनमें विरुद्ध विधानका दोष आता है। और इस लोक या परलोकमें फल देनेवाले शास्त्रविहित कर्मोंको शरीरद्वारा करता हुआ मनुष्य पापको प्राप्त नहीं होता ऐसा कहनेसे भी बिना प्राप्त हुए दोषके प्रतिषेध करनेका प्रसङ्ग आ जाता है। तथा शारीरिक कर्म करता हुआ इस विशेषणसे और केवल शब्दके प्रयोगसे ( उपर्युक्त मान्यताके अनुसार ) भगवान्का यह कहना हो जाता है कि ( शरीरके सिवा ) मनवाणीद्वारा किये जानेवाले विहित और प्रतिषिद्ध कर्मोंको जो कि धर्म और अधर्म नामसे कहे जाते हैं करता हुआ मनुष्य पापको प्राप्त होता है। उसमें भी मनवाणीद्वारा विहित कर्मोंको करता हुआ पापको प्राप्त होता है यह कहना तो विरुद्ध विधान होगा और निषिद्ध कर्मोंको करता हुआ पापको प्राप्त होता है यह कहना अनुवादमात्र होनेसे व्यर्थ होगा। परंतु जब शरीरनिर्वाहमात्रके लिये किये जानेवाले कर्म शारीरिक कर्म मान लिये जायँगे तब इसका यह अर्थ हो जायगा कि इस लोक या परलोकके भोग ही जिनका प्रयोजन है जो विधिनिषेधात्मक शास्त्रोंद्वारा जाने जाते हैं जो शरीर मन या वाणीद्वारा किये जाते हैं ऐसे अन्य कर्मोंको न करता हुआ उन शरीर मन या वाणीसे केवल शरीरनिर्वाहके लिये आवश्यक कर्म लोकदृष्टिसे करता हुआ पुरुष किल्बिषको प्राप्त नहीं होता। यहाँ केवल शब्दके प्रयोगसे यह अभिप्राय है कि वह मैं करता हूँ इस अभिमानसे रहित होकर केवल लोकदृष्टिसे ही शरीर वाणी आदिकी चेष्टामात्र करता है। ऐसे पुरुषको पापरूप किल्बिष प्राप्त होना तो असम्भव है इसलिये यहाँ यह समझना चाहिये कि वह किल्बिषको यानी संसारको प्राप्त नहीं होता। ज्ञानरूप अग्निद्वारा उसके समस्त कर्मोंका नाश हो जानेके कारण वह बिना किसी प्रतिबन्धके मुक्त ही हो जाता है। यह पहले कहे हुए यथार्थ आत्मज्ञानके फलका अनुवादमात्र है। शारीरं केवलं कर्म इस वाक्यका इस प्रकार अर्थ मान लेनेसे वह अर्थ निर्दोष सिद्ध होता है।'),
('shankaracharya-ht:source:4.22','Śaṅkarācārya','gita.4.22','hi','translation','।।4.22।।जिसने समस्त संग्रहका त्याग कर दिया है ऐसे संन्यासीके पास शरीरनिर्वाहके कारणरूप अन्नादिका संग्रह नहीं होता इसलिये उसको याचनादिद्वारा शरीरनिर्वाह करनेकी योग्यता प्राप्त हुई। इसपर बिना याचना किये बिना संकल्पके अथवा बिना इच्छा किये प्राप्त हुए इत्यादि वचनोंसे जो शास्त्रमें संन्यासीके शरीरनिर्वाहके लिये अन्नादिकी प्राप्तिके द्वार बतलाये गये हैं उनको प्रकट करते हुए कहते हैं जो बिना माँगे अपनेआप मिले हुए पदार्थसे संतुष्ट है अर्थात् उसीमें जिसके मनका यह भाव हो जाता है कियही पर्याप्त है जो द्वन्द्वोंसे अतीत है अर्थात् शीतउष्ण आदि द्वन्द्वोंसे सताये जानेपर भी जिसके चित्तमें विषाद नहीं होता जो ईर्ष्यासे रहित अर्थात् निर्वैरबुद्धिवाला है और जो अपनेआप प्राप्त हुए लाभकी सिद्धिअसिद्धिमें भी सम रहता है जो ऐसा शरीरस्थितिके हेतुरूप अन्नादिके प्राप्त होने या न होनेमें भी हर्षशोकसे रहित समदर्शी है और कर्मादिमें अकर्मादि देखनेवाला यथार्थ आत्मदर्शननिष्ठ एवं शरीरस्थितिमात्रके लिये किये जानेवाले और शरीरादिद्वारा होनेवाले भिक्षाटनादि कर्मोंमें भी मैं कुछ नहीं करता गुण ही गुणोंमें बर्त रहे हैं इस प्रकार सदा देखनेवाला है वह यति अपनेमें कर्तापनका अभाव देखनेसे अर्थात् आत्माको अकर्ता समझ लेनेसे वास्तवमें भिक्षाटनादि कुछ भी कर्म नहीं करता है। ऐसा पुरुष लोकव्यवहारकी साधारण दृष्टिसे तो सांसारिक पुरुषोंद्वारा आरोपित किये हुए कर्तापनके कारण भिक्षाटनादि कर्मोंका कर्ता होता है। परंतु शास्त्रप्रमाण आदिसे उत्पन्न अपने अनुभवसे ( वस्तुतः ) वह अकर्ता ही रहता है। इस प्रकार दूसरोंद्वारा जिसपर कर्तापनका अध्यारोप किया गया है ऐसा वह पुरुष शरीरनिर्वाहमात्रके लिये किये जानेवाले भिक्षाटनादि कर्मोंको करता हुआ भी नहीं बँधता क्योंकि ज्ञानरूप अग्निद्वारा उसके ( समस्त ) बन्धनकारक कर्म हेतुसहित भस्म हो चुके हैं। यह पहले कहे हुएका ही अनुवादमात्र है।'),
('shankaracharya-ht:source:4.23','Śaṅkarācārya','gita.4.23','hi','translation','।।4.23।।जो कर्म करना प्रारम्भ कर चुका है ऐसा पुरुष जब कर्म करतेकरते इस ज्ञानसे सम्पन्न हो जाता है कि निष्क्रिय ब्रह्म ही आत्मा है तब अपने कर्ता कर्म और प्रयोजनादिका अभाव देखनेवाले उस पुरुषके लिये कर्मोंका त्याग कर देना ही उचित होता है। किंतु किसी कारणवश कर्मोंका त्याग करना असम्भव होनेपर यदि वह पहलेकी तरह उन कर्मोंमें लगा रहे तो भी वास्तवमें कुछ भी नहीं करता। इस प्रकार त्यक्त्वा कर्मंफलासङ्गम् इस श्लोकसे ( ज्ञानीके ) कर्मोंका अभाव ( अकर्मत्व ) दिखलाया जा चुका है। जिस पुरुषके कर्मोंका इस प्रकार अभाव दिखाया गया है उसीके ( विषयमें अगला श्लोक कहते हैं ) जिस पुरुषकी सब ओरसे आसक्ति निवृत्त हो चुकी है जिसके पुण्यपापरूप बन्धन छूट गये हैं जिसका चित्त निरन्तर ज्ञानमें ही स्थित है ऐसे केवल यज्ञसम्पादनके लिये ही कर्मोंका आचरण करनेवाले उस सङ्गहीन मुक्त और ज्ञानावस्थितचित्त पुरुषके समग्र कर्म विलीन हो जाते हैं। अग्र शब्द फलका वाचक है। उसके सहित कर्मोंको समग्र कर्म कहते हैं अतः यह अभिप्राय हुआ कि उसके फलसहित समस्त कर्म नष्ट हो जाते हैं।'),
('shankaracharya-ht:source:4.24','Śaṅkarācārya','gita.4.24','hi','translation','।।4.24।।किये जानेवाले कर्म अपना कार्य आरम्भ किये बिना ही ( कुछ फल दिये बिना ही ) किस कारणसे फलसहित विलीन हो जाते हैं इसपर कहते हैं ब्रह्मवेत्ता पुरुष जिस साधनद्वारा अग्निमें हवि अर्पण करता है उस साधनको ब्रह्मरूप ही देखा करता है अर्थात् आत्माके सिवा उसका अभाव देखता है। जैसे ( सीपको जाननेवाला ) सीपमें चाँदीका अभाव देखता है ब्रह्म ही अर्पण है इस पदसे भी वही बात कही जाती है। अर्थात् जैसे यह समझता है कि जो चाँदीके रूपमें दीख रही है वह सीप ही है। ( वैसे ही ब्रह्मवेत्ता भी समझता है कि जो अर्पण दीखता है वह ब्रह्म ही है ) ब्रह्म और अर्पण यह दोनों पद अलगअलग हैं। अभिप्राय यह कि संसारमें जो अर्पण माने जाते हैं वे स्रुक् स्रुव आदि सब पदार्थ उस ब्रह्मवेत्ताकी दृष्टिमें ब्रह्म ही हैं। वैसे ही जो वस्तु हविरूपसे मानी जाती है वह भी उसकी दृष्टिमें ब्रह्म ही होता है। ब्रह्माग्नौ यह पद समासयुक्त है। इसलिये यह अर्थ हुआ कि ब्रह्मरूप कर्ताद्वारा जिसमें हवन किया जाता है वह अग्नि भी ब्रह्म ही है और वह कर्ता भी ब्रह्म ही है और जो उसके द्वारा हवनरूप क्रिया की जाती है वह भी ब्रह्म ही है। उस ब्रह्मकर्ममें स्थित हुए पुरुषद्वारा प्राप्त करनेयोग्य जो फल है वह भी ब्रह्म ही है। अर्थात् ब्रह्मरूप कर्ममें जिसके चित्तका समाधान हो चुका है उस पुरुषद्वारा प्राप्त किये जानेयोग्य जो फल है वह भी ब्रह्म ही है। इस प्रकार लोकसंग्रह करना चाहनेवाले पुरुषद्वारा किये हुए कर्म भी ब्रह्मबुद्धिसे बाधित होनेके कारण अर्थात् फल उत्पन्न करनेकी शक्तिसे रहित कर दिये जानेके कारण वास्तवमें अकर्म ही हैं। ऐसा अर्थ मान लेनेपर कर्मोंको छोड़ देनेवाले कर्म संन्यासीके ज्ञानको भी यथार्थ ज्ञानकी स्तुतिके लिये यज्ञरूप समझना भली प्रकार बन सकता है अधियज्ञमें जो स्रुवादि वस्तुएँ प्रसिद्ध हैं वे सब इस यथार्थ ज्ञानी संन्यासीके ( सम्यक्ज्ञानरूप ) अध्यात्मयज्ञमें ब्रह्म ही हैं। उपर्युक्त अर्थ नहीं माननेसे वास्तवमें सब ही ब्रह्मरूप होनेके कारण केवल स्रुव आदिको ही विशेषतासे ब्रह्मरूप बतलाना व्यर्थ होगा। सुतरां यह सब कुछ ब्रह्म ही है इस प्रकार समझनेवाले ज्ञानीके लिये वास्तवमें सब कर्मोंका अभाव ही हो जाता है। तथा उसके अन्तःकरणमें ( क्रिया फल आदि ) कारकसम्बन्धी भेदबुद्धिका अभाव होनेके कारण भी यही सिद्ध होता है क्योंकि कोई भी यज्ञ नामक कर्म कारकसम्बन्धी भेदबुद्धिसे रहित नहीं देखा गया। अभिप्राय यह है कि अग्निहोत्रादि सभी कर्म ( इन्द्राय वरुणाय आदि ) शब्दोंद्वारा हवि आदि द्रव्य जिनके अर्पण किये जाते हैं उन देवताविशेषरूप सम्प्रदान आदि कारकबुद्धिवाले तथा कर्तापनके अभिमानसे और फलकी इच्छासे युक्त देखे गये हैं। जिसमेंसे क्रिया कारक और फलसम्बन्धी भेदबुद्धि नष्ट हो गयी हो तथा जो कर्तापनके अभिमानसे और फलकी इच्छासे रहित हो ऐसा यज्ञ नहीं देखा गया। परंतु यह उपर्युक्त कर्म तो ऐसा है कि जिसमें सर्वत्र ब्रह्मबुद्धि हो जानेके कारण अर्पणादि कारक क्रिया और फलसम्बन्धी भेदबुद्धि नष्ट हो गयी है। इसलिये यह अकर्म ही है। यही बात कर्मण्यकर्म यः पश्येत् कर्मण्यभिप्रवृत्तोऽपि नैव किंचित्करोति सः गुणा गुणेषु वर्तन्ते नैव किंचित्करोमीति युक्तो मन्येत तत्त्ववित् इत्यादि श्लोकोंद्वारा भी दिखलायी गयी है। और इसी प्रकार दिखलाते हुए भगवान् जगहजगह क्रिया कारक और फलसम्बन्धी भेदबुद्धिका निषेध कर रहे हैं। देखा भी गया है कि सकाम अग्निहोत्रादिमें कामना न रहनेपर वे सकाम अग्निहोत्रादि नहीं रहते। ( उनकी सकामता नष्ट हो जाती है। ) तथा यह भी देखा गया है कि जानबूझकर किये हुए और अनजानमें किये हुए कर्म भिन्नभिन्न कार्योंके आरम्भक होते हैं अर्थात् उनका फल अलगअलग होता है। वैसे ही यहाँ भी जिस पुरुषकी सर्वत्र ब्रह्मबुद्धि हो जानेसे ( स्रुव हवि आदिमें ) क्रिया कारक और फलसम्बन्धी भेदबुद्धि नष्ट हो गयी है उस ज्ञानी पुरुषके बाह्य चेष्टामात्रसे होनेवाले कर्म भी अकर्म हो जाते हैं। इसलिये कहा है कि उसके फलसहित कर्म विलीन हो जाते हैं। इस विषयमें कोईकोई टीकाकार कहते हैं कि जो ब्रह्म है वही स्रुव आदि है अर्थात् ब्रह्म ही स्रुव आदि पाँच प्रकारके कारकोंके रूपमें स्थित है और वही कर्म किया करता है ( उनके सिद्धान्तानुसार ) उपर्युक्त यज्ञमें स्रुव आदि बुद्धि निवृत्त नहीं की जाती किंतु स्रुव आदिमें ब्रह्मबुद्धि स्थापित की जाती है जैसे कि मूर्ति आदिमें विष्णु आदि देवबुद्धि या नाम आदिमें ब्रह्मबुद्धि की जाती है। ठीक है यदि यह प्रकरण ज्ञानयज्ञकी स्तुतिके लिये न होता तो यह अर्थ भी हो सकता था। परंतु इस प्रकरणमें तो यज्ञ नामसे कहे जानेवाले अलगअलग बहुतसे क्रियाभेदोंको कहकर फिर द्रव्यमय यज्ञकी अपेक्षा ज्ञानयज्ञ कल्याणकर है इस कथनद्वारा ज्ञानयज्ञ शब्दसे कथित सम्यक् दर्शनकी स्तुति करते हैं। तथा इस प्रकरणमें जो ब्रह्मार्पणम् इत्यादि वचन है यह ज्ञानको यज्ञरूपसे सम्पादन करनेमें समर्थ भी है नहीं तो वास्तवमें सब कुछ ब्रह्मरूप होनेके कारण केवल अर्पण ( स्रुव ) आदिको ही अलग करके ब्रह्मरूपसे विधान करना व्यर्थ होगा। जो ऐसा कहते हैं कि यहाँ मूर्तिमें विष्णु आदिकी दृष्टिके सदृश या नामादिमें ब्रह्मबुद्धिकी भाँति अर्पण ( स्रुव ) आदि यज्ञकी सामग्रीमें ब्रह्मबुद्धि स्थापन करायी गयी है उनकी दृष्टिसे सम्भवतः इस प्रकरणमें ब्रह्मविद्या नहीं कही गयी है क्योंकि ( उनके मतानुसार ) ज्ञानका विषय स्रुव आदि यज्ञकी सामग्री ही है ब्रह्म नहीं। इस प्रकार केवल ब्रह्मदृष्टि सम्पादनरूप ज्ञानसे मोक्षरूप फल नहीं मिल सकता और यहाँ ( स्पष्ट ही ) यह कहा है कि उसके द्वारा प्राप्त किया जानेवाला फल ब्रह्म ही है फिर बिना यथार्थ ज्ञानके मोक्षरूप फल मिलता है यह कहना सर्वथा विपरीत है। इसके सिवा ( ऐसा मान लेनेसे ) प्रकरणमें भी विरोध आता है। अभिप्राय यह है कि जो कर्ममें अकर्म देखता है इस प्रकार यहाँ आरम्भमें सम्यक् ज्ञानका ही प्रकरण है तथा उसीमें उपसंहार होनेके कारण अन्तमें भी यथार्थ ज्ञानका ही प्रकरण है। क्योंकि द्रव्यमय यज्ञकी अपेक्षा ज्ञानयज्ञ श्रेष्ठतर है ज्ञानको पाकर परम शान्तिको तुरंत ही प्राप्त हो जाता है इत्यादि वचनोंसे यथार्थ ज्ञानकी स्तुति करते हुए ही यह अध्याय समाप्त हुआ है। फिर बिना प्रकरण अकस्मात् मूर्तिमें विष्णुदृष्टिकी भाँति स्रुव आदिमें ब्रह्मदृष्टिका विधान बतलाना उपयुक्त नहीं। सुतरां जिस प्रकार इसकी व्याख्या की गयी है इस श्लोकका अर्थ वैसा ही है।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:4.25','Śaṅkarācārya','gita.4.25','hi','translation','।।4.25।।उपर्युक्त श्लोकमें यथार्थ ज्ञानको यज्ञरूपसे सम्पादन करके अब उसकी स्तुति करनेके लिये दैवम् एव इत्यादि श्लोकोंसे दूसरेदूसरे यज्ञोंका भी उल्लेख किया जाता है जिस यज्ञके द्वारा देवोंका पूजन किया जाता है वह देवसम्बन्धी यज्ञ है अन्य ( कितने ही ) योगी अर्थात् कर्म करनेवाले लोग उस दैवयज्ञका ही अनुष्ठान किया करते हैं। अन्य ( ब्रह्मवेत्ता पुरुष ) ब्रह्माग्निमें ( हवन करते हैं ) अर्थात् ब्रह्म सत्यज्ञानअनन्तस्वरूप है विज्ञान और आनन्द ही ब्रह्म है जो साक्षात् अपरोक्ष ( प्रत्यक्ष ) है वह ब्रह्म है जो सर्वान्तर आत्मा है वह ब्रह्म है इत्यादि वचनोंसे जिसका वर्णन किया गया है जो भूखप्यास आदि समस्त सांसारिक धर्मोंसे रहित है जो ऐसा नहीं ऐसा नहीं इस प्रकार वेदवाक्योंद्वारा सब विशेषणोंसे परे बतलाया गया है वह ब्रह्म शब्दसे कहा जाता है। हवनका अधिकरण बतलानेके लिये उस ब्रह्मको ही यहाँ अग्नि कह दिया है। उस ब्रह्मरूप अग्निमें कितने ही ब्रह्मवेत्ता ज्ञानी यज्ञद्वारा यज्ञको हवन करते हैं। आत्माके नामोंमें यज्ञ शब्दका पाठ होनेसे आत्माका नाम यज्ञ है जो कि वास्तवमें परब्रह्म ही है परंतु बुद्धि आदि उपाधियोंसे युक्त हुआ उपाधियोंके धर्मोंको अपनेमें मान रहा है। उस आहुतिरूप आत्माको उपर्युक्त आत्माद्वारा ही हवन करते हैं। सारांश यह कि उपाधियुक्त आत्माको जो उपाधिरहित परब्रह्मरूपसे साक्षात् करना है वही उसका उसमें हवन करना है ब्रह्म और आत्माके एकत्वज्ञानमें स्थित हुए वे संन्यासी लोग ऐसा हवन किया करते हैं। श्रेयान्द्रव्यमयाद्यज्ञाज्ज्ञानयज्ञः परंतप इत्यादि श्लोकोंसे स्तुति करनेके लिये यह सम्यग्दर्शनरूप यज्ञ ब्रह्मार्पणम् इत्यादि श्लोकोंद्वारा दैवयज्ञ आदि यज्ञोंमें सम्मिलित किया जाता है।'),
('shankaracharya-ht:source:4.26','Śaṅkarācārya','gita.4.26','hi','translation','।।4.26।।अन्य योगीजन संयमरूप अग्नियोंमें श्रोत्रादि इन्द्रियोंका हवन करते हैं। संयम ही अग्नियाँ हैं उन्हींमें हवन करते हैं अर्थात् इन्द्रियोंका संयम करते हैं। प्रत्येक इन्द्रियका संयम भिन्नभिन्न है इसलिये यहाँ बहुवचनका प्रयोग किया गया है। अन्य ( साधकलोग ) इन्द्रियरूप अग्नियोंमें शब्दादि विषयोंका हवन करते हैं। इन्द्रियाँ ही अग्नियाँ हैं उन इन्द्रियाग्नियोंमें हवन करते हैं अर्थात् उन श्रोत्रादि इन्द्रियोंद्वारा शास्त्रसम्मत विषयोंके ग्रहण करनेको ही होम मानते हैं।'),
('shankaracharya-ht:source:4.27','Śaṅkarācārya','gita.4.27','hi','translation','।।4.27।।तथा दूसरे साधक इन्द्रियोंके सम्पूर्ण कर्मोंको और शरीरके भीतर रहनेवाला वायु जो प्राण कहलाता है उसके संकुचित होने फैलने आदि कर्मोंको ज्ञानसे प्रकाशित हुई आत्मसंयमरूप योगाग्निमें हवन करते हैं। आत्मविषयक संयमका नाम आत्मसंयम है वही यहाँ योगाग्नि है। घृतादि चिकनी वस्तुसे प्रज्वलित हुई अग्निकी भाँति विवेकविज्ञानसे उज्ज्वलताको प्राप्त हुई ( धारणाध्यानसमाधिरूप ) उस आत्मसंयम योगाग्निमें ( वे प्राण और इन्द्रियोंके कर्मोंको ) विलीन कर देते हैं।'),
('shankaracharya-ht:source:4.28','Śaṅkarācārya','gita.4.28','hi','translation','।।4.28।।जो यज्ञबुद्धिसे तीर्थादिमें द्रव्य लगाते हैं वे द्रव्ययज्ञा यानी द्रव्यसम्बन्धी यज्ञ करनेवाले हैं। जो तपस्वी हैं वे तपोयज्ञा यानी तपरूप यज्ञ करनेवाले हैं। प्राणायाम प्रत्याहाररूप योग ही जिनका यज्ञ है वे योगयज्ञा यानी योगरूप यज्ञ करनेवाले हैं। वैसे ही अन्य कई स्वाध्याययज्ञ और ज्ञानयज्ञकरनेवाले भी हैं। जिनका यथाविधि ऋग्वेद आदिका अभ्यासरूप स्वाध्याय ही यज्ञ है वे स्वाध्याययज्ञ करनेवाले हैं और शास्त्रोंका अर्थ जाननारूप ज्ञान जिनका यज्ञ है वे ज्ञानयज्ञ करनेवाले हैं। इसी तरह कई यत्नशील संशित व्रतवाले हैं। जिनके व्रतनियम अच्छी प्रकार तीक्ष्ण किये हुए यानी सूक्ष्मशुद्ध किये हुए होते हैं वे पुरुष संशितव्रत कहलाते हैं।'),
('shankaracharya-ht:source:4.29','Śaṅkarācārya','gita.4.29','hi','translation','।।4.29।।तथा ( कोई ) अपानवायुमें प्राणवायुका हवन करते हैं अर्थात् पूरक नामक प्राणायाम किया करते हैं। वैसे ही अन्य कोई प्राणमें अपानका हवन करते हैं अर्थात् रेचक नामक प्राणायाम किया करते हैं। मुख और नासिकाके द्वारा वायुका बाहर निकलना प्राणकी गति है और उसके विपरीत ( पेटमें ) नीचेकी और जाना अपानकी गति है। उन प्राण और अपान दोनोंकी गतियोंको रोककर कोई अन्य लोग प्राणायामपरायण होते हैं अर्थात् प्राणायाममें तत्पर हुए वे केवल कुम्भक नामक प्राणायाम किया करते हैं।'),
('shankaracharya-ht:source:4.30','Śaṅkarācārya','gita.4.30','hi','translation','।।4.30।।तथा अन्य कितने ही नियताहारी अर्थात् जिनका आहार नियमित किया हुआ है ऐसे परिमित भोजन करनेवाले प्राणोंको यानी वायुके भिन्नभिन्न भेदोंको प्राणोंमें ही हवन किया करते हैं। भाव यह है कि वे जिसजिस वायुको जीत लेते हैं उसीमें वायुके दूसरे भेदोंको हवन कर देते हैं यानी वे सब वायुभेद उसमें विलीनसे हो जाते हैं। ये सभी पुरुष यज्ञोंको जाननेवाले और यज्ञोंद्वारा निष्पाप हो गये होते हैं अर्थात् उपर्युक्त यज्ञोंद्वारा जिनके सब पाप नष्ट हो गये हैं वे यज्ञक्षपितकल्मष कहलाते हैं।'),
('shankaracharya-ht:source:4.31','Śaṅkarācārya','gita.4.31','hi','translation','।।4.31।।इस प्रकार उपर्युक्त यज्ञोंका सम्पादन करके यज्ञोंके शेषका नाम यज्ञशिष्ट है वही अमृत है उसको जो भोगते हैं वे यज्ञशिष्ट अमृतभोजी हैं। उपर्युक्त यज्ञोंको करके उससे बचे हुए समयद्वारा यथाविधि प्राप्त अमृतरूप विहित अन्नको भक्षण करनेवाले यज्ञशिष्ट अमृतभोजी पुरुष सनातन यानी चिरन्तन ब्रह्मको प्राप्त होते हैं। यहाँ यान्ति इस गतिविषयक शब्दकी शक्तिसे यह पाया जाता है कि यदि यज्ञ करनेवाले मुमुक्षु होते हैं तो कालातिक्रमकी अपेक्षासे ( मरनेके बाद कितने ही कालतक ब्रह्मलोकमें रहकर फिर प्रलयके समय ) ब्रह्मको प्राप्त होते हैं। हे कुरुश्रेष्ठ जो मनुष्य उपर्युक्त यज्ञोंमेंसे एक भी यज्ञ नहीं करता उस यज्ञरहित पुरुषको सब प्राणियोंके लिये जो साधारण है ऐसा यह लोक भी नहीं मिलता फिर विशेष साधनोंद्वारा प्राप्त होनेवाला अन्य लोक तो मिल ही कैसे सकता है।'),
('shankaracharya-ht:source:4.32','Śaṅkarācārya','gita.4.32','hi','translation','।।4.32।।इसी प्रकार उपर्युक्त बहुत प्रकारके यज्ञ ब्रह्मके यानी वेदके मुखमें विस्तृत हैं। वेदद्वारा ही सब यज्ञ जाननेमें आते हैं इसी अभिप्रायसे ब्रह्मके मुखमें विस्तारित हैं ऐसा कहा है। जैसे हम वाणीमें ही प्राणोंको हवन करते हैं इत्यादि ( इसी तरह अन्य सब यज्ञोंका भी वेदमें विधान है )। उन सब यज्ञोंको तू कर्मजकायिक वाचिक और मानसिक क्रियाद्वारा ही होनेवाले जान वे यज्ञ आत्मासे होनेवाले नहीं हैं क्योंकि आत्मा हलनचलन आदि क्रियाओंसे रहित है। सुतरां इस प्रकार जानकर तू अशुभसे मुक्त हो जायगा अर्थात् यह सब कर्म मेरेद्वारा सम्पादित नहीं हैं मैं तो निष्क्रिय और उदासीन हूँ इस प्रकार जानकर इस सम्यक् ज्ञानके प्रभावसे तू संसारबन्धनसे मुक्त हो जायगा।'),
('shankaracharya-ht:source:4.33','Śaṅkarācārya','gita.4.33','hi','translation','।।4.33।।ब्रह्मार्पणम् इत्यादि श्लोकद्वारा यथार्थ ज्ञानको यज्ञरूपसे सम्पादन किया फिर बहुतसे यज्ञोंका वर्णन किया। अब पुरुषका इच्छित प्रयोजन जिन यज्ञोंसे सिद्ध होता है उन उपर्युक्त अन्य यज्ञोंकी अपेक्षा ज्ञानयज्ञकी स्तुति करते हैं। कैसे सो कहते हैं हे परन्तप द्रव्यमय यज्ञकी अपेक्षा अर्थात् द्रव्यरूप साधनद्वारा सिद्ध होनेवाले यज्ञकी अपेक्षा ज्ञानयज्ञ श्रेष्ठतर है। क्योंकि द्रव्यमय यज्ञ फलका आरम्भ करनेवाला है और ज्ञानयज्ञ ( जन्मादि ) फल देनेवाला नहीं है। इसलिये वह श्रेष्ठतर अर्थात् अधिक प्रशंसनीय है। क्योंकि हे पार्थ सबकेसब कर्म मोक्षसाधनरूप ज्ञानमें जो कि सब ओरसे परिपूर्ण जलाशयके समान है समाप्त हो जाते हैं अर्थात् उन सबका ज्ञानमें अन्तर्भाव हो जाता है। जैसे ( चौपड़के खेलमें कृतयुग त्रेता द्वापर और कलियुग ऐसे नामवाले जो चार पासे होते हैं उनमेंसे ) कृतयुग नामक पासेको जीत लेनेपर नीचेवाले सब पासे अपनेआप ही जीत लिये जाते हैं ऐसे ही जिसको वह रैक्व जानता है उस ब्रह्मको जो कोई भी जान लेता है प्रजा जो कुछ भी अच्छे कर्म करती है उन सबका फल उसे अपनेआप ही मिल जाता है। इस श्रुतिसे भी यही सिद्ध होता है।'),
('shankaracharya-ht:source:4.34','Śaṅkarācārya','gita.4.34','hi','translation','।।4.34।।इस प्रकारसे श्रेष्ठ बतलाया हुआ वह ज्ञान किस उपायसे मिलता है सो कहते हैं वह ज्ञान जिस विधिसे प्राप्त होता है वह तू जान यानी सुन आचार्यके समीप जाकर भलीभाँति दण्डवत् प्रणाम करनेसे एवं किस तरह बन्धन हुआ कैसे मुक्ति होगी विद्या क्या है अविद्या क्या है इस प्रकार ( निष्कपट भावसे ) प्रश्न करनेसे और गुरुकी यथायोग्य सेवा करनेसे ( वह ज्ञान प्राप्त होता है )। अभिप्राय यह कि इस प्रकार सेवा और विनय आदिसे प्रसन्न हुए तत्त्वदर्शी ज्ञानी आचार्य तुझे उपर्युक्त विशेषणोंवाले ज्ञानका उपदेश करेंगे। ज्ञानवान् भी कोईकोई ही यथार्थ तत्त्वको जाननेवाले होते हैं सब नहीं होते। इसलिये ज्ञानीके साथ तत्त्वदर्शी यह विशेषण लगाया है। इससे भगवान्का यह अभिप्राय है कि जो यथार्थ तत्त्वको जाननेवाले होते हैं उनके द्वारा उपदेश किया हुआ ही ज्ञान अपने कार्यको सिद्ध करनेमें समर्थ होता है दूसरा नहीं।'),
('shankaracharya-ht:source:4.35','Śaṅkarācārya','gita.4.35','hi','translation','।।4.35।।ऐसा होनेपर यह कहना भी ठीक है हे पांडव उनके द्वारा बतलाये हुए जिस ज्ञानको पाकर फिर तू इस प्रकार मोहको प्राप्त नहीं होगा जैसे कि अब हो रहा है। तथा जिस ज्ञानके द्वारा तू सम्पूर्णतासे सब भूतोंको अर्थात् ब्रह्मासे लेकर स्तम्बपर्यन्त समस्त प्राणियोंको यह सब भूत मुझमें स्थित हैं इस प्रकार साक्षात् अपने अन्तरात्मामें ही देखेगा और मुझ वासुदेव परमेश्वरमें भी इन सब भूतोंको देखेगा। अर्थात् सभी उपनिषदोंमें जो जीवात्मा और ईश्वरकी एकता प्रसिद्ध है उसको प्रत्यक्ष अनुभव करेगा।'),
('shankaracharya-ht:source:4.36','Śaṅkarācārya','gita.4.36','hi','translation','।।4.36।।इस ज्ञान का माहात्म्य क्या है ( सो सुन ) यदि तू पाप करने वाले सब पापियों से अधिक पाप करनेवाला अति पापी भी है तो भी ज्ञानरूप नौका द्वारा अर्थात् ज्ञान को ही नौका बनाकर समस्त पापरूप समुद्रसे अच्छी तरह पार उतर जायगा। यहाँ मुमुक्षु के लिये धर्म भी पाप ही कहा जाता है।'),
('shankaracharya-ht:source:4.37','Śaṅkarācārya','gita.4.37','hi','translation','।।4.37।।ज्ञान पापको किस प्रकार नष्ट कर देता है सो दृष्टान्तसहित कहते हैं हे अर्जुन जैसे अच्छी प्रकारसे प्रदीप्त यानी प्रज्वलित हुआ अग्नि ईंधनको अर्थात् काष्ठके समूहको भस्मरूप कर देता है वैसे ही ज्ञानरूप अग्नि सब कर्मोंको भस्मरूप कर देता है अर्थात् निर्बीज कर देता है। क्योंकि ईंधनकी भाँति ज्ञानरूप अग्नि कर्मोंको साक्षात् भस्मरूप नहीं कर सकता इसलिये इसका यही अभिप्राय है कि यथार्थ ज्ञान सब कर्मोंको निर्बीज करनेका हेतु है। जिस कर्मसे शरीर उत्पन्न हुआ है वह फल देनेके लिये प्रवृत्त हो चुका इसलिये उसका नाश तो उपभोगद्वारा ही होगा। यह युक्तिसिद्ध बात है। अतः इस जन्ममें ज्ञानकी उत्पत्तिसे पहले और ज्ञानके साथसाथ किये हुए एवं पुराने अनेक जन्मोंमें किये हुए जो कर्म अभीतक फल देनेके लिये प्रवृत्त नहीं हुए हैं उन सब कर्मोंको ही ज्ञानाग्नि भस्म करता है ( प्रारब्धकर्मोंको नहीं )।'),
('shankaracharya-ht:source:4.38','Śaṅkarācārya','gita.4.38','hi','translation','।।4.38।।क्योंकि ज्ञानका इतना प्रभाव है इसलिये ज्ञानके समान पवित्र करनेवाला शुद्ध करनेवाला इस लोकमें ( दूसरा कोई ) नहीं है। कर्मयोग या समाधियोगद्वारा बहुत कालमें भली प्रकार शुद्धान्तःकरण हुआ अर्थात् वैसी योग्यताको प्राप्त हुआ मुमुक्ष स्वयं अपने आत्मामें ही उस ज्ञानको पाता है यानी साक्षात् किया करता है।'),
('shankaracharya-ht:source:4.39','Śaṅkarācārya','gita.4.39','hi','translation','।।4.39।।जिसके द्वारा निश्चय ही ज्ञानकी प्राप्ति हो जाती है वह उपाय बतलाया जाता है श्रद्धावान् श्रद्धालु मनुष्य ज्ञान प्राप्त किया करता है। श्रद्धालु होकर भी तो कोई मन्द प्रयत्नवाला हो सकता है इसलिये कहते हैं कि तत्पर अर्थात् ज्ञानप्राप्तिके गुरुशुश्रूषादि उपायोंमें जो अच्छी प्रकार लगा हुआ हो। श्रद्धावान् और तत्पर होकर भी कोई अजितेन्द्रिय हो सकता है इसलिये कहते हैं कि संयतेन्द्रिय भी होनाचाहिये। जिसकी इन्द्रियाँ वशमें की हुई हों यानी विषयोंसे निवृत्त कर ली गयी हों वह संयतेन्द्रिय कहलाता है। जो इस प्रकार श्रद्धावान् तत्पर और संयतेन्द्रिय भी होता है वह अवश्य ही ज्ञानको प्राप्त कर लेता है। जो दण्डवत्प्रणामादि उपाय हैं वे तो बाह्य हैं और कपटी मनुष्यद्वारा भी किये जा सकते हैं इसलिये वे ( ज्ञानरूप फल उत्पन्न करनेमें ) अनिश्चित भी हो सकते हैं। परंतु श्रद्धालुता आदि उपायोंमें कपट नहीं चल सकता इसलिये ये निश्चयरूपसे ज्ञानप्राप्तिके उपाय हैं। ज्ञानप्राप्तिसे क्या होगा सो ( उत्तरार्धमें ) कहते हैं ज्ञानको प्राप्त होकर मनुष्य मोक्षरूप परम शान्तिको यानी उपरामताको बहुत शीघ्रतत्काल ही प्राप्त हो जाता है। यथार्थ ज्ञानसे तुरंत ही मोक्ष हो जाता है यह सब शास्त्रों और युक्तियोंसे सिद्ध सुनिश्चित बात है।'),
('shankaracharya-ht:source:4.40','Śaṅkarācārya','gita.4.40','hi','translation','।।4.40।।इस विषयमें संशय नहीं करना चाहिये क्योंकि संशय बड़ा पापी है। कैसे सो कहते हैं जो अज्ञ यानी आत्मज्ञानसे रहित है जो अश्रद्धालु है और जो संशयात्मा है ये तीनों नष्ट हो जाते हैं। यद्यपि अज्ञानी और अश्रद्धालु भी नष्ट होते हैं परंतु जैसा संशयात्मा नष्ट होता है वैसे नहीं क्योंकि इन सबमें संशयात्मा अधिक पापी है। अधिक पापी कैसे है ( सो कहते हैं ) संशयात्माको अर्थात् जिसके चित्तमें संशय है उस पुरुषको न तो यह साधारण मनुष्यलोक मिलता है न परलोक मिलता है और न सुख ही मिलता है क्योंकि वहाँ भी संशय होना सम्भव है इसलिये संशय नहीं करना चाहिये।'),
('shankaracharya-ht:source:4.41','Śaṅkarācārya','gita.4.41','hi','translation','।।4.41।।कैसे जिस परमार्थदर्शी पुरुषने परमार्थज्ञानरूप योगके द्वारा पुण्यपापरूप सम्पूर्ण कर्मोंका त्याग कर दिया हो वह योगसंन्यस्तकर्मा है। ( उसको कर्म नहीं बाँधते। ) वह योगसंन्यस्तकर्मा कैसे है सो कहते हैं आत्मा और ईश्वरकी एकतादर्शनरूप ज्ञानद्वारा जिसका संशय अच्छी प्रकार नष्ट हो चुका है वह ज्ञानसंछिन्नसंशय कहलाता है। ( इसलिये वह योगसंन्यस्तकर्मा है। ) जो इस प्रकार योगसंन्यस्तकर्मा है उस आत्मवान् यानी आत्मबलसे युक्त प्रमादरहित पुरुषको हे धनंजय ( गुण ही गुणोंमें बर्तते हैं इस प्रकार ) गुणोंकी चेष्टामात्रके रूपमें समझे हुए कर्म नहीं बाँधते अर्थात् इष्ट अनिष्ट और मिश्र इन तीन प्रकारके फलोंका भोग नहीं करा सकते।'),
('shankaracharya-ht:source:4.42','Śaṅkarācārya','gita.4.42','hi','translation','।।4.42।।क्योंकि कर्मयोगका अनुष्ठान करनेसे अन्तःकरणकी अशुद्धिका क्षय हो जानेपर उत्पन्न होनेवाले आत्मज्ञानसे जिसका संशय नष्ट हो गया है ऐसा पुरुष तो ज्ञानाग्निद्वारा उसके कर्म दग्ध हो जानेके कारण कर्मोंसे नहीं बँधता तथा ज्ञानयोग और कर्मयोगके अनुष्ठानमें संशय रखनेवाला नष्ट हो जाता है इसलिये अज्ञान यानी अविवेकसे उत्पन्न और अन्तःकरणमें रहनेवाले ( अपने नाशकके हेतुभूत ) इस अत्यन्तपापी अपने संशयको ज्ञानखड्गद्वारा अर्थात् शोकमोह आदि दोनोंका नाश करनेवाला यथार्थ दर्शरूप जो ज्ञान है वही खड्ग है उस स्वरूपज्ञानरूप खड्गद्वारा ( छेदन करके कर्मयोगमें स्थित हो )। यहाँ संशय आत्मविषयक है इसलिये ( उसके साथ आत्मनः विशेषण दिया गया है। ) क्योंकि एकका संशय दूसरेके द्वारा छेदन करनेकी शङ्का यहाँ प्राप्त नहीं होती जिससे कि ( ऐसी शङ्काको दूर करनेके उद्देश्यसे ) आत्मनः विशेषण दिया जावे अतः ( यही समझना चाहिये कि ) आत्मविषयक होनेसे भी अपना कहा जा सकता है। ( सुतरां संशयको अपना बतलाना असंगत नहीं है। ) अतः अपने नाशके कारणरूप इस संशयको ( उपर्युक्त प्रकारसे ) काटकर पूर्ण ज्ञानकी प्राप्तिके उपायरूप कर्मयोगमें स्थित हो और हे भारत अब युद्धके लिये खड़ा हो जा।'),
('shankaracharya-ht:source:5.1','Śaṅkarācārya','gita.5.1','hi','translation','।।5.1।।केवल संन्यास करनेमात्रसे ही सिद्धिको प्राप्त नहीं होता है इस वचनसे ज्ञानसहित संन्यासको ही सिद्धिका साधन माना है साथ ही कर्मयोगका भी विधान किया है इसलिये ज्ञानरहित संन्यास कल्याणकर हैअथवा कर्मयोग इन दोनोंकी विशेषता जाननेकी इच्छासे अर्जुन बोला आप पहले तो शास्त्रोक्त बहुत प्रकारके अनुष्ठानरूप कर्मोंका त्याग करनेके लिये कहते हैं अर्थात् उपदेश करते हैं और फिर उनके अनुष्ठानकी अवश्यकर्तव्यतारूप योगको भी बतलाते हैं। इसलिये मुझे यह शङ्का होती है कि इनमेंसे कौनसा श्रेयस्कर है। कर्मोंका अनुष्ठान करना कल्याणकर है अथवा उनका त्याग करना जो श्रेष्ठतर हो उसीका अनुष्ठान करना चाहिये इसलिये इन कर्मसंन्यास और कर्मयोगमें जो श्रेष्ठ हो अर्थात् जिसका अनुष्ठान करनेसे आप यह मानते हैं कि मुझे कल्याणकी प्राप्ति होगी उस भलीभाँति निश्चय किये हुए एक ही अभिप्रायको अलग करके कहिये क्योंकि एक पुरुषद्वारा एक साथ दोनोंका अनुष्ठान होना असम्भव है।'),
('shankaracharya-ht:source:5.2','Śaṅkarācārya','gita.5.2','hi','translation','।।5.2।।अर्जुनके प्रश्नका निर्णय करनेके लिये भगवान् अपना अभिप्राय बतलाते हुए बोले संन्यास कर्मोंका परित्याग और कर्मयोग उनका अनुष्ठान करना ये दोनों ही कल्याणकारक अर्थात् मुक्तिके देनेवाले हैं। यद्यपि ज्ञानकी उत्पत्तिमें हेतु होनेसे ये दोनोंही कल्याणकारक हैं तथापि कल्याणके उन दोनों कारणोंमें ज्ञानरहित केवल संन्यासकी अपेक्षा कर्मयोग श्रेष्ठ है। इस प्रकार भगवान् कर्मयोगकी स्तुति करते हैं।'),
('shankaracharya-ht:source:5.3','Śaṅkarācārya','gita.5.3','hi','translation','।।5.3।।( कर्मयोग श्रेष्ठ ) कैसे है इसपर कहते हैं उस कर्मयोगीको सदा संन्यासी ही समझना चाहिये कि जो न तो द्वेष करता है और न किसी वस्तुकी आकाङ्क्षा ही करता है। अर्थात् जो सुख दुःख और उनके साधनोंमें उक्त प्रकारसे रागद्वेषरहित हो गया है वह कर्ममें बर्तता हुआ भी सदा संन्यासी ही है ऐसे समझना चाहिये। क्योंकि हे महाबाहो रागद्वेषादि द्वन्द्वोंसे रहित हुआ पुरुष सुखपूर्वक अनायास ही बन्धनसे मुक्त हो जाता है।'),
('shankaracharya-ht:source:5.4','Śaṅkarācārya','gita.5.4','hi','translation','।।5.4।।भिन्न पुरुषोंद्वारा अनुष्ठान करनेयोग्य परस्परविरुद्ध कर्मसंन्यास और कर्मयोगके फलमें भी विरोध होना चाहिये दोनोंका कल्याणरूप एक ही फल कहना ठीक नहीं इस शङ्काके प्राप्त होनेपर यह कहा जाता है बालबुद्धिवाले ही सांख्य और योगइन दोनोंको अलगअलग विरुद्ध फलदायक बतलाते हैं पण्डित नहीं। ज्ञानी पण्डितजन तो दोनोंका अविरुद्ध और एक ही फल मानते हैं। क्योंकि सांख्य और योगइन दोनोंमेंसे एकका भी भलीभाँति अनुष्ठान कर लेनेवाला पुरुष दोनोंका फल पा लेता है। कारण दोनोंका वही ( एक ) कल्याणरूप ( परमपद ) फल है इसलिये फलमें विरोध नहीं है। पू0 संन्यास और कर्मयोग इन शब्दोंसे प्रकरण उठाकर फिर यहाँ प्रकरणविरुद्ध सांख्य और योगके फलकी एकता कैसे कहते हैं उ0 यह दोष नहीं है। यद्यपि अर्जुनने केवल संन्यास और कर्मयोगको पूछनेके अभिप्रायसे ही प्रश्न कियाथा परंतु भगवान्ने उसके अभिप्रायको न छोड़कर ही अपना विशेष अभिप्राय जोड़ते हुए सांख्य और योग ऐसे इन दूसरे शब्दोंसे उनका वर्णन करके उत्तर दिया है। क्योंकि वे संन्यास और कर्मयोग ही ( क्रमानुसार ) ज्ञानसे और उसके उपायरूप समबुद्धि आदि भावोंसे युक्त हो जानेपर सांख्य और योगके नामसे कहे जाते हैं यह भगवान्का मत है अतः यह वर्णन प्रकरणविरुद्ध नहीं है।'),
('shankaracharya-ht:source:5.5','Śaṅkarācārya','gita.5.5','hi','translation','।।5.5।।एकका भी भली प्रकार अनुष्ठान कर लेनेसे दोनोंका फल कैसे पा लेता है इसपर कहा जाता है सांख्योगियोंद्वारा अर्थात् ज्ञाननिष्ठायुक्त संन्यासियोंद्वारा जो मोक्ष नामक स्थान प्राप्त किया जाता है वही कर्मयोगियोंद्वारा भी ( प्राप्त किया जाता है )। जो पुरुष अपने लिये ( कर्मोंका ) फल न चाहकर सब कर्म ईश्वरमें अर्पण करके और उसे ज्ञानप्राप्तिका उपाय मानकर उनका अनुष्ठान करते हैं वे योगी हैं उनको भी परमार्थज्ञानरूप संन्यासप्राप्तिके द्वारा ( वही मोक्षरूप फल ) मिलता है। यह अभिप्राय है। इसलिये फलमें एकता होनेके कारण जो सांख्य और योगको एक देखता है वही यथार्थ देखता है। पू0 यदि ऐसा है तब तो कर्मयोगसे कर्मसंन्यास ही श्रेष्ठ है फिर यह कैसे कहा कि उन दोनोंमें कर्मसंन्यासकी अपेक्षा कर्मयोग श्रेष्ठ है उ0 उसमें जो कारण है सो सुनो तुमने केवल कर्मसंन्यास और केवल कर्मयोगके अभिप्रायसे पूछा था कि उन दोनोंमें कौनसा एक कल्याणकारक है उसीके अनुरूप मैंने यह उत्तर दिया कि ज्ञानरहित कर्मसंन्यासकी अपेक्षा तो कर्मयोग ही श्रेष्ठ है। क्योंकि ज्ञानसहित संन्यासको तो मैं सांख्य मानता हूँ और वही परमार्थयोग भी है।'),
('shankaracharya-ht:source:5.6','Śaṅkarācārya','gita.5.6','hi','translation','।।5.6।।जो वैदिक ( निष्काम ) कर्मयोग है वह तो उसी ज्ञानयोगका साधन होनेके कारण गौणरूपसे योग और संन्यास कहा जाने लगा है। वह उसीका साधन कैसे है सो कहते हैं बिना कर्मयोगके पारमार्थिक संन्यास प्राप्त होना कठिन है दुष्कर है। तथा फल न चाहकर ईश्वरसमर्पणके भावसे किये हुए वैदिक कर्मयोगसे युक्त हुआ ईश्वरके स्वरूपका मनन करनेवाला मुनि ब्रह्मको अर्थात् परमात्मज्ञाननिष्ठारूप पारमार्थिक संन्यासको शीघ्र ही प्राप्त कर लेता है इसलिये मैंने कहा कि कर्मयोग श्रेष्ठ है। परमात्मज्ञानका सूचक होनेसे प्रकरणमें वर्णित संन्यास ही ब्रह्म नामसे कहा गया है तथा संन्यास ही ब्रह्म है और ब्रह्म ही पर है इस श्रुतिसे भी यही बात सिद्ध होती है।'),
('shankaracharya-ht:source:5.7','Śaṅkarācārya','gita.5.7','hi','translation','।।5.7।।जब यह पुरुष सम्यक् ज्ञानप्राप्तिके उपायरूप योगसे युक्त विशुद्ध अन्तःकरणवाला विजितात्मा शरीरविजयी जितेन्द्रिय और सब भूतोंमें अपने आत्माको देखनेवाला अर्थात् जिसका अन्तरात्मा ब्रह्मासे लेकर स्तम्बपर्यन्त सम्पूर्ण भूतोंका आत्मरूप हो गया हो ऐसा यथार्थ ज्ञानी हो जाता है। तब इस प्रकार स्थित हुआ वह पुरुष लोकसंग्रह के लिये कर्म करता हुआ भी उनसे लिप्त नहीं होता अर्थात् कर्मोंसे नहीं बँधता। वास्तवमें वह कुछ करता भी नहीं है इसलिये आत्माके यथार्थ स्वरूपका नाम तत्त्व है उसको जाननेवाला तत्त्वज्ञानी परमार्थदर्शी समाहित होकर ऐसे माने कि मैं कुछ भी नहीं करता।'),
('shankaracharya-ht:source:5.8','Śaṅkarācārya','gita.5.8','hi','translation','।।5.8।।तत्त्वको समझकर कब और किस प्रकार ऐसे माने सो कहते हैं ( देखता सुनता छूता सूँघता खाता चलता सोता श्वास लेता बोलता त्याग करता ग्रहण करता तथा आँखोंको खोलता और मूँदता हुआ भी इन्द्रियाँ इन्द्रियोंके विषयमें बर्त रही हैं ऐसे समझकर ) ऐसे माने कि मैं कुछ भी नहीं करता। इस प्रकार इसका पहलेके आधे श्लोकसे सम्बन्ध है। जो इस प्रकार तत्त्वज्ञानी है अर्थात् सब इन्द्रियाँ और अन्तःकरणोंकी चेष्टारूप कर्मोंमें अकर्म देखनेवाला है वह अपनेमें कर्मोंका अभाव देखता है इसलिये उस यथार्थ ज्ञानीका सर्वकर्मसंन्यासमें ही अधिकार है। क्योंकि मृगतृष्णिकामें जल समझकर उसको पीनेके लिये प्रवृत्त हुआ मनुष्य उसमें जलके अभावका ज्ञान हो जानेपर फिर भी वही जल पीनेके लिये प्रवृत्त नहीं होता।'),
('shankaracharya-ht:source:5.9','Śaṅkarācārya','gita.5.9','hi','translation','।।5.9।।तत्त्वको समझकर कब और किस प्रकार ऐसे माने सो कहते हैं ( देखता सुनता छूता सूँघता खाता चलता सोता श्वास लेता बोलता त्याग करता ग्रहण करता तथा आँखोंको खोलता और मूँदता हुआ भी इन्द्रियाँ इन्द्रियोंके विषयमें बर्त रही हैं ऐसे समझकर ) ऐसे माने कि मैं कुछ भी नहीं करता। इस प्रकार इसका पहलेके आधे श्लोकसे सम्बन्ध है। जो इस प्रकार तत्त्वज्ञानी है अर्थात् सब इन्द्रियाँ और अन्तःकरणोंकी चेष्टारूप कर्मोंमें अकर्म देखनेवाला है वह अपनेमें कर्मोंका अभाव देखता है इसलिये उस यथार्थ ज्ञानीका सर्वकर्मसंन्यासमें ही अधिकार है। क्योंकि मृगतृष्णिकामें जल समझकर उसको पीनेके लिये प्रवृत्त हुआ मनुष्य उसमें जलके अभावका ज्ञान हो जानेपर फिर भी वही जल पीनेके लिये प्रवृत्त नहीं होता।'),
('shankaracharya-ht:source:5.10','Śaṅkarācārya','gita.5.10','hi','translation','।।5.10।।परंतु जो तत्त्वज्ञानी नहीं है और कर्मयोगमें लगा हुआ है ( यानी ) जो स्वामीके लिये कर्म करनेवाले नौकरकी भाँति मैं ईश्वरके लिये करता हूँ इस भावसे सब कर्मोंको ईश्वरमें अर्पण करके यहाँतक कि मोक्षरूप फलकी भी आसक्ति छोड़कर कर्म करता है। वह जैसे कमलका पत्ता जलमें रहकर भी उससे लिप्त नहीं होता वैसे ही पापोंसे लिप्त नहीं होता।'),
('shankaracharya-ht:source:5.11','Śaṅkarācārya','gita.5.11','hi','translation','।।5.11।।उसके कर्मोंका फल तो केवल अन्तःकरणकी शुद्धिमात्र ही होता है क्योंकि योगी लोग केवल यानी मैं सब कर्म ईश्वरके लिये ही करता हूँ अपने फलके लिये नहीं। इस भावसे जिनमें ममत्वबुद्धि नहीं रही है ऐसे शरीर मन बुद्धि और इन्द्रियोंसे फलविषयक आसक्तिको छोड़कर आत्मशुद्धिके लिये अर्थात् अन्तःकरणकी शुद्धिके लिये कर्म करते हैं। सभी क्रियाओंमें ममताका निषेध करनेके लिये केवल शब्दका काया आदि सभी शब्दोंके साथ सम्बन्ध है। तेरा भी उसीमें अधिकार है इसलिये तू भी कर्म ही कर।'),
('shankaracharya-ht:source:5.12','Śaṅkarācārya','gita.5.12','hi','translation','।।5.12।।क्योंकि सब कर्म ईश्वरके लिये ही हैं मेरे फलके लिये नहीं इस प्रकार निश्चयवाला योगी कर्मफलका त्याग करके ज्ञाननिष्ठामें होनेवाली मोक्षरूप परम शान्तिको प्राप्त हो जाता है। यहाँ पहले अन्तःकरणकी शुद्धि फिर ज्ञानप्राप्ति फिर सर्वकर्मसंन्यासरूप ज्ञाननिष्ठाकी प्राप्ति इस प्रकार क्रमसे परम शान्तिको प्राप्त होता है इतना वाक्य अधिक समझ लेना चाहिये। परंतु जो अयुक्त है अर्थात् उपर्युक्त निश्चयवाला नहीं है वह कामकी प्रेरणासे अपने फलके लिये यह कर्म मैं करता हूँ इस प्रकार फलमें आसक्त होकर बँधता है। इसलिये तू युक्त हो अर्थात् उपर्युक्त निश्चयवाला हो यह अभिप्राय है। करणका नाम कार है कामके करणका नाम कामकार है उसमें तृतीया विभक्ति जो़ड़नेसे कामके कारणसे अर्थात् कामकी प्रेरणासे यह अर्थ हुआ।'),
('shankaracharya-ht:source:5.13','Śaṅkarācārya','gita.5.13','hi','translation','।।5.13।।परंतु जो यथार्थ ज्ञानी है वह ( वशी जितेन्द्रिय पुरुष ) समस्त कर्मोंको मनसे छोड़कर अर्थात् नित्य नैमित्तिक काम्य और निषिद्ध इन सब कर्मोंको कर्मादिमें अकर्मदर्शनरूप विवेकबुद्धिके द्वारा त्यागकर सुखपूर्वक स्थित हो जाता है। मन वाणी और शरीरकी चेष्टाको छोड़कर परिश्रमरहित प्रसन्नचित्त और आत्मासे अतिरिक्त अन्य सब बाह्य प्रयोजनोंसे निवृत्त हुआ ( वह ) सुखपूर्वक स्थित होता है ऐसे कहा जाता है। वशी जितेन्द्रिय पुरुष कहाँ और कैसे रहता है सो कहते हैं नौ द्वारवाले पुरमें रहता है। अभिप्राय यह कि दो कान दो नेत्र दो नासिका और एक मुख शब्दादि विषयोंको उपलब्ध करनेके ये सात द्वार शरीरके ऊपरी भागमें हैं और मलमूत्रका त्याग करनेके लिये दो नीचेके अङ्गमें हैं इन नौ द्वारोंवाला शरीर पुर कहलाता है। शरीर भी एक पुरकी भाँति पुर है जिसका स्वामी आत्मा है उस आत्माके लिये ही जिनके सब प्रयोजन हैं एवं जो अनेक फल और विज्ञानके उत्पादक हैं उन इन्द्रिय मन बुद्धि और विषयरूप पुरवासियोंसे जो युक्त है उस नौ द्वारवाले पुरमें देही सब कर्मोंको छोड़कर रहता है। पू0 इस विशेषणसे क्या सिद्ध हुआ संन्यासी हो चाहे असंन्यासी सभी जीव शरीरमें ही रहते हैं। इस स्थलमें विशेषण देना व्यर्थ है। उ0 जो अज्ञानी जीव शरीर और इन्द्रियोंके संघातमात्रको आत्मा माननेवाले हैं। वे सब घरमें भूमिपर या आसनपर बैठता हूँ ऐसे ही माना करते हैं क्योंकि देहमात्रमें आत्मबुद्धियुक्त अज्ञानियोंको घरकी भाँति शरीरमें रहता हूँ यह ज्ञान होना सम्भव नहीं। परंतु देहादिसंघातसे आत्मा भिन्न है ऐसा जाननेवाले विवेकीको मैं शरीरमें रहता हूँ यह प्रतीति हो सकती है। तथा निर्लेप आत्मामें अविद्यासे आरोपित जो परकीय ( देहइन्द्रियादिके ) कर्म हैं उनका विवेकविज्ञानरूप विद्याद्वारा मनसे संन्यास होना भी सम्भव है। जिससे विवेकविज्ञान उत्पन्न हो गया है ऐसे सर्वकर्मसंन्यासीका भी घरमें रहनेकी भाँति नौ द्वारवाले शरीररूप पुरमें रहना प्रारब्धकर्मोंके अवशिष्ट संस्कारोंकी अनुवृत्तिसे बन सकता है क्योंकि शरीरमें ही प्रारब्धफलभोगका विशेष ज्ञान होना सम्भव है। अतः ज्ञानी और अज्ञानीकी प्रतीतिके भेदकी अपेक्षासे देहे एव आस्ते इस विशेषणका फल अवश्य ही है। यद्यपि कार्य करण और कर्म जो अविद्यासे आत्मामें आरोपित हैं उन्हें छोड़कर रहता है ऐसा कहा है तथापि आत्मासे नित्य सम्बन्ध रखनेवाले कर्तापन और करानेकी प्रेरकता ये दोनों भाव तो उस ( आत्मा ) में रहेंगे ही। इस शङ्कापर कहते हैं स्वयं न करता हुआ और शरीरइन्द्रियादिसे न करवाता हुआ अर्थात् उनको कर्मोंमें प्रवृत्त न करता हुआ ( रहता है )। पू0 जैसे गमन करनेवालेकी गति गमनरूप व्यापारका त्याग करनेसे नहीं रहती वैसे ही आत्मामें जो कर्तृत्व और कारयितृत्व हैं वह क्या आत्माके नित्य सम्बन्धी होते हुए ही संन्याससे नहीं रहते अथवा स्वभावसे ही आत्मामें नहीं हैं उ0 आत्मामें कर्तृत्व और कारयितृत्व स्वभावसे ही नहीं हैं क्योंकि यह आत्मा विकाररहित कहा जाता है। हे कौन्तेय यह आत्मा शरीरमें स्थित हुआ भी न करता है और न लिप्त होता है। ऐसा कह चुके हैं एवं ध्यान करता हुआसा क्रिया करता हुआसा। इस श्रुतिसे भी यही सिद्ध होता है।'),
('shankaracharya-ht:source:5.14','Śaṅkarācārya','gita.5.14','hi','translation','।।5.14।।देहादिका स्वामी आत्मा न तो तू अमुक कर्म कर इस प्रकार लोगोंके कर्तापनको उत्पन्न करता है और न रथ घट महल आदि कर्म जो अत्यन्त इष्ट हैं उनको रचता है तथा न रथादि बनानेवालेका उसके कर्मफलके साथ संयोग ही रचता है यदि यह देहादिका स्वामी आत्मा स्वयं कुछ भी नहीं करताकराता तो फिर यह सब कौन कर रहा और करा रहा है इसपर कहते हैं स्वभाव ही बर्तता है अर्थात् जो अपना भाव है अविद्या जिसका स्वरूप है जो दैवी हि इत्यादि श्लोकोंसे आगे कही जानेवाली है वह प्रकृति यानी माया ही सब कुछ कर रही है।'),
('shankaracharya-ht:source:5.15','Śaṅkarācārya','gita.5.15','hi','translation','।।5.15।।वास्तवमें तो विभु ( सर्वव्यापी परमात्मा ) किसी भक्तके पापको भी ग्रहण नहीं करता और भक्तोंद्वारा अर्पण किये हुए सुकृतको भी वह नहीं लेता। तो फिर भक्तोंद्वारा पूजा आदि अच्छे कर्म एवं यज्ञ दान होम आदि सुकृत कर्म किस लिये अर्पण किये जाते हैं इसपर कहते हैं जीवोंका विवेकविज्ञान अज्ञानसे ढका हुआ है। इस कारण अविवेकी संसारी जीव ही करता हूँ कराता हूँ खाता हूँ खिलाता हूँ इस प्रकार मोहको प्राप्त हो रहे हैं।'),
('shankaracharya-ht:source:5.16','Śaṅkarācārya','gita.5.16','hi','translation','।।5.16।।जिन जीवोंके अन्तःकरणका वह अज्ञान जिस अज्ञानसे आच्छादित हुए जीव मोहित होते हैं आत्मविषयक विवेकज्ञानद्वारा नष्ट हो जाता है उनका वह ज्ञान सूर्यकी भाँति उस परम परमार्थतत्त्वको प्रकाशित कर देता है। अर्थात् जैसे सूर्य समस्त रूपमात्रको प्रकाशित कर देता है वैसे ही उनका ज्ञान समस्त ज्ञेय वस्तुको प्रकाशित कर देता है।'),
('shankaracharya-ht:source:5.17','Śaṅkarācārya','gita.5.17','hi','translation','।।5.17।।जो प्रकाशित हुआ परमज्ञान है उस परमार्थतत्त्वमें जिनकी बुद्धि जा पहुँची है वे तद्बुद्धि हैं वह परब्रह्म ही जिनका आत्मा है वे तदात्मा हैं उस ब्रह्ममें ही जिनकी निष्ठादृढ़ आत्मभावनातत्परता है अर्थात् जो सब कर्मोंका संन्यास करके ब्रह्ममें ही स्थित हो गये हैं वे तन्निष्ठ हैं। वह परब्रह्म ही जिनका परम अयनआश्रय परमगति है अर्थात् जो केवल आत्मामें ही रत हैं वे तत्परायण हैं ( इस प्रकार ) जिनके अन्तःकरणका अज्ञान ज्ञानद्वारा नष्ट हो गया है एवं उपर्युक्त ज्ञानद्वारा संसारके कारणरूप पापादि दोष जिनके नष्ट हो चुके हैं ऐसे ज्ञाननिर्धूतकल्मष संन्यासी अपुनरावृत्तिको अर्थात् जिस अवस्थाको प्राप्त कर लेनेपर फिर देहसे सम्बन्ध होना छूट जाता है ऐसी अवस्थाको प्राप्त होते हैं।'),
('shankaracharya-ht:source:5.18','Śaṅkarācārya','gita.5.18','hi','translation','।।5.18।।जिनके आत्माका अज्ञान ज्ञानद्वारा नष्ट हो चुका है वे पण्डितजन परमार्थतत्त्वको कैसे देखते हैं सो कहते हैं विद्या और विनययुक्त ब्राह्मणमें अर्थात् विद्याआत्मबोध और विनयउपरामता इन दोनों गुणोंसे सम्पन्न जो विद्वान् और विनीत ब्राह्मण है उस ब्राह्मणमें गौमें हाथीमें कुत्ते और चाण्डालमें भी पण्डितजन समभावसे देखनेवाले ( होते हैं )। अभिप्राय यह कि उत्तम प्राणी संस्कारयुक्त विद्याविनयसम्पन्न सात्त्विक ब्राह्मणमें मध्यम प्राणीसंस्काररहित रजोगुणयुक्त गौमें और ( कनिष्ठ प्राणी ) अतिशय मूढ़ केवल तमोगुणयुक्त हाथी आदिमें सत्त्वादि गुणोंसे और उनके संस्कारोंसे तथा राजस और तामस संस्कारोंसे सर्वथा ही निर्लेप रहनेवाले सम एक निर्विकार ब्रह्मको देखना ही जिनका स्वभाव है वे पण्डित समदर्शी हैं। पू0 वे ( इस प्रकार देखनेवाले ) दोषयुक्त हैं उनका अन्न भोजन करने योग्य नहीं क्योंकि यह स्मृतिका प्रमाण है कि समान गुणशीलवालोंकी विषम पूजा करनेसे और विषम गुणशीलवालोंकी सम पूजा करनेसे ( यजमान दोषी होता है )।'),
('shankaracharya-ht:source:5.19','Śaṅkarācārya','gita.5.19','hi','translation','।।5.19।।उ0 वे दोषी नहीं हैं क्योंकि जिनका अन्तःकरण समतामें अर्थात् सब भूतोंके अन्तर्गत ब्रह्मरूप समभावमें स्थित यानी निश्चल हो गया है उन समदर्शी पण्डितोंने यहाँ जीवितावस्थामें ही सर्गको यानी जन्मको जीत लिया है अर्थात् उसे अपने अधीन कर लिया है। क्योंकि ब्रह्म निर्दोष ( और सम ) है। यद्यपि मूर्ख लोगोंको दोषयुक्त चाण्डालादिमें उनके दोषोंके कारण आत्मा दोषयुक्तसा प्रतीत होता है तो भी वास्तवमें वह ( आत्मा ) उनके दोषोंसे निर्लिप्त ही है। चेतन आत्मा निर्गुण होनेके कारण अपने गुणके भेदसे भी भिन्न नहीं है। भगवान् भी इच्छादिको क्षेत्रके ही धर्म बतलावेंगे तथा अनादि और निर्गुण होनेके कारण ( आत्मा लिप्त नहीं होता ) यह भी कहेंगे। ( वैशेषिक शास्त्रमें बतलाये हुए नित्य द्रव्यगत ) अन्त्य विशेष भी आत्मामें भेद उत्पन्न करनेवाले नहीं हैं क्योंकि प्रत्येक शरीरमें उन अन्त्य विशेषोंके होनेका कोई प्रमाण सम्भव नहीं है। अतः ( यह सिद्ध हुआ कि ) ब्रह्म सम है और एक ही है। इसलिये वे समदर्शी पुरुष ब्रह्ममें ही स्थित हैं इसी कारण उनको दोषकी गन्ध भी स्पर्श नहीं कर पाती क्योंकि उनमेंसे देहादि संघातको आत्मारूपसे देखनेका अभिमान जाता रहा है।। समासमाभ्यां विषमसमे पूजातः यह सूत्र पूजाविषयक विशेषणसे युक्त होनेके कारण देहादि संघातमें आत्मदृष्टिके अभिमानवाले पुरुषोंके विषयमें है। क्योंकि पूजा दान आदि कर्मोंमें ( भेदबुद्धिका ) कारण ब्रह्मवेत्ता छओं अङ्गोंको जाननेवाला चारों वेदोंको जाननेवाला इत्यादि विशेष गुणोंका सम्बन्ध देखा जाता है। परंतु ब्रह्म सम्पूर्ण गुणदोषोंके सम्बन्धसे रहित है इसलिये यह ( कहना ) ठीक है कि वे ब्रह्ममें स्थित हैं। इसके अतिरिक्त समासमाभ्याम् इत्यादि कथन तो कर्मियोंके विषयमें है और यह सर्वकर्माणि मनसा इस श्लोकसे लेकर अध्यायसमाप्तितक सारा प्रकरण सर्वकर्मसंन्यासी के विषयमें है।'),
('shankaracharya-ht:source:5.20','Śaṅkarācārya','gita.5.20','hi','translation','।।5.20।।क्योंकि निर्दोष और सम ब्रह्म ही आत्मा है इसलिये प्रिय वस्तुको प्राप्त करके तो हर्षित न हो अर्थात् इष्टवस्तु पाकर तो हर्ष न माने और अप्रिय अनिष्ट पदार्थके मिलनेपर उद्वेग न करे। क्योंकि देहमात्रमें आत्मबुद्धिवाले पुरुषको ही प्रियकी प्राप्ति हर्ष देनेवाली और अप्रियकी प्राप्ति शोक उत्पन्न करनेवाली हुआ करती है केवल उपाधिरहित आत्माका साक्षात् करनेवाले पुरुषको नहीं। कारण उसके लिये ( वास्तवमें ) प्रिय और अप्रियकी प्राप्ति असम्भव है। सब भूतोंमें आत्मा एक है सम है और निर्दोष है ऐसी संशयरहित बुद्धि जिसकी स्थिर हो चुकी है और जो मोह अज्ञानसे रहित है वह स्थिरबुद्धि ब्रह्मज्ञानी ब्रह्ममें ही स्थित है। अर्थात् वह कर्म न करनेवाला सर्व कर्मोंका त्यागी ही है।'),
('shankaracharya-ht:source:5.21','Śaṅkarācārya','gita.5.21','hi','translation','।।5.21।।और भी वह ब्रह्ममें स्थित हुआ पुरुष ( कैसा होता है सो बताते हैं ) जिनका इन्द्रियोंद्वारा स्पर्श ( ज्ञान ) किया जा सके वे स्पर्श हैं इस व्युत्पत्तिसे शब्दादि विषयोंका नाम स्पर्श है ( वे सब अपने भीतर नहीं हैं इसलिये बाह्य हैं ) उस बाह्य स्पर्शोंमें जिसका अन्तःकरण आसक्त नहीं है ऐसा विषयप्रीतिसे रहित पुरुष उस सुखको प्राप्त होता है जो अपने भीतर है। तथा वह ब्रह्मयोगयुक्तात्मा ब्रह्ममें जो समाधि है उसका नाम ब्रह्मयोग है उस ब्रह्मयोगसे जिसका अन्तःकरण युक्त है अच्छी प्रकार उसमें समाहित है लगा हुआ है ऐसा पुरुष अक्षय सुखको अनुभव करता है प्राप्त होता है। इसलिये अपनेआप अक्षय सुख चाहनेवाले पुरुषको चाहिये कि वह क्षणिक बाह्य विषयोंकी प्रीतिसे इन्द्रियोंको हटा ले। यह अभिप्राय है।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:5.22','Śaṅkarācārya','gita.5.22','hi','translation','।।5.22।।इसलिये भी ( इन्द्रियोंको विषयोंसे ) हटा लेना चाहिये क्योंकि विषय और इन्द्रियोंके सम्बन्धसे उत्पन्न जो भोग हैं वे सब अविद्याजन्य होनेसे केवल दुःखके ही कारण हैं क्योंकि आध्यात्मिक आदि ( तीनों प्रकारके ) दुःख उनके ही निमित्तसे होते हुए देखे जाते हैं। एव शब्दसे यह भी प्रकट होता है कि ये जैसे इस लोकमें दुःखप्रद हैं वैसे ही परलोकमें भी दुःखद हैं। संसारमें सुखकी गन्धमात्र भी नहीं है यह समझकर विषयरूप मृगतृष्णिकासे इन्द्रियोंको हटा लेना चाहिये। ये विषयभोग केवल दुःखके कारण हैं इतना ही नहीं किंतु ये आदिअन्तवाले भी हैं विषय और इन्द्रियोंका संयोग होना भोगोंका आदि है और वियोग होना ही अन्त है। इसलिये जो आदिअन्तवाले हैं वे केवल बीचके क्षणमें ही प्रतीतिवाले होनेसे अनित्य हैं। हे कौन्तेय परमार्थतत्त्वको जाननेवाला विवेकशील बुद्धिमान् पुरुष उन भोगोंमें नहीं रमा करता। क्योंकि केवल अत्यन्त मूढ़ पुरुषोंकी ही पशु आदिकी भाँति विषयोंमें प्रीति देखी जाती है। कल्याणके मार्गका प्रतिपक्षी यह ( कामक्रोधका वेगरूप ) दोष ब़ड़ा दुःखदायक है सब अनर्थोंकी प्राप्तिका कारण है और निवारण करनेमें अति कठिन भी है। इसलिये भगवान् कहते हैं कि इसको नष्ट करनेके लिये खूब प्रयत्न करना चाहिये।'),
('shankaracharya-ht:source:5.23','Śaṅkarācārya','gita.5.23','hi','translation','।।5.23।।जो मनुष्य यहाँजीवितावस्थामें ही शरीर छूटनेसे पहलेपहले अर्थात् मरणपर्यन्त ( कामक्रोधसे उत्पन्न हुए वेगको ) सहन कर सकता है अर्थात् सहन करनेका उत्साह रखता है ( वही युक्त और सुखी है )। जीवित पुरुषके अन्तःकरणमें कामक्रोधका वेग अवश्य ही होता है इसलिये मरणपर्यन्तकी सीमा की गयी है क्योंकि वह कामक्रोधजनित वेग अनेक निमित्तोंसे प्रकट होनेवाला है अतः मरनेतक उसका विश्वास न करे। ( सदैव उससे सावधान रहे ) यह अभिप्राय है। किसी अनुभव किये हुए सुखदायक इष्टविषयके इन्द्रियगोचर हो जानेपर यानी सुन जानेपर या स्मरण हो जानेपर उसको पानेकी जो लालसा तृष्णा होती है उसका नाम काम है। वैसे ही अपने प्रतिकूल दुःखदायक विषयोंके दीखने सुनायी देने या स्मरण होनेपर उनमें जो द्वेष होता है उसका नाम क्रोध है। वे काम और क्रोध जिस वेगके उत्पादक होते हैं वह कामक्रोधसे उत्पन्न हुआ वेग कहलाता है। रोमाञ्च होना मुख और नेत्रोंका प्रफुल्लित होना इत्यादि चिह्नोंवाला जो अन्तःकरणका क्षोभ है वह कामसे उत्पन्न हुआ वेग है। तथा शरीरका काँपना पसीना आ जाना होठोंको चबाने लगना नेत्रोंका लाल हो जाना इत्यादि चिह्नोंवाला वेग क्रोधसे उत्पन्न हुआ वेग है। ऐसे काम और क्रोधके वेगको जो सहन कर सकता है उसको सहन करनेका उत्साह रखता है वह मनुष्य इस संसारमें योगी है और वही सुखी है।'),
('shankaracharya-ht:source:5.24','Śaṅkarācārya','gita.5.24','hi','translation','।।5.24।।ब्रह्ममें स्थित हुआ कैसा पुरुष ब्रह्मको प्राप्त होता है सो कहते हैं जो पुरुष अन्तरात्मामें सुखवाला है जिसको अन्तरात्मामें ही सुख है वह अन्तःसुखवाला है तथा जो अन्तरात्मामें रमण करनेवाला है जिसकी क्रीड़ा ( खेल ) अन्तरात्मामें ही होती है वह अन्तरारामी है और अन्तरात्मा ही जिसकी ज्योति प्रकाश है वह अन्तर्ज्योति है। जो ऐसा योगी है वह यहाँ जीवितावस्थामें ही ब्रह्मरूप हुआ ब्रह्ममें लीन होनारूप मोक्षको प्राप्त हो जाता है।'),
('shankaracharya-ht:source:5.25','Śaṅkarācārya','gita.5.25','hi','translation','।।5.25।।और भी जिनके पापादि दोष नष्ट हो गये हैं जिनके सब संशय क्षीण हो गये हैं जो जितेन्द्रिय हैं जो सब भूतोंके हितमें अर्थात् अनुकूल आचरणमें रत हैं अर्थात् अहिंसक हैं ऐसे ऋषिजन सम्यक् ज्ञानीसंन्यासी लोग ब्रह्मनिर्वाणको अर्थात् मोक्षको प्राप्त होते हैं।'),
('shankaracharya-ht:source:5.26','Śaṅkarācārya','gita.5.26','hi','translation','।।5.26।।तथा जो काम और क्रोध इन दोनों दोषोंसे रहित हो चुके हैं जिन्होंने अन्तःकरणको अपने वशमें कर लिया है जिन्होंने आत्माको जान लिया है ऐसे आत्मज्ञानी सम्यग्दर्शी यती संन्यासियोंको दोनों ओरसे अर्थात् जीवित रहते हुए भी और मरनेके पश्चात् भी दोनों अवस्थाओंमें ब्रह्मनिर्वाण यानी मोक्ष प्राप्त रहता है। यथार्थ ज्ञानमें निष्ठावाले संन्यासियोंके लिये सद्यः ( तुरंत ही होनेवाली ) मुक्ति बतलायी गयी है तथा सब प्रकार ईश्वरार्पितभावसे पूर्ण ब्रह्म परमात्मामें सब कर्मोंका त्याग करके किया हुआ कर्मयोग भी अन्तःकरणकी शुद्धि ज्ञानप्राप्ति और सर्वकर्मसंन्यासके क्रमसे मोक्षदायक है यह बात भगवान्ने पदपदपर कही है और (आगे भी ) कहेंगे।'),
('shankaracharya-ht:source:5.27','Śaṅkarācārya','gita.5.27','hi','translation','।।5.27।।अब सम्यक् ज्ञानके अन्तरङ्ग साधनरूप ध्यानयोगको विस्तारपूर्वक कहूँगा यह विचारकर उस ध्यानयोगके सूत्रस्थानीय श्लोकोंका उपदेश करते हैं शब्दादि बाह्य विषयोंको बाहर करके यानी जो शब्दादि विषय श्रोत्रादि इन्द्रियोंद्वारा अन्तःकरणके भीतर प्रविष्ट कर लिये गये हैं उनका चिन्तन न करना ही बाह्य विषयोंको निकाल बाहर करना है इस प्रकार उनको बाहर करके एवं दोनों नेत्रों ( की दृष्टि ) को भृकुटिके मध्यस्थानमें स्थित करके तथा नासिका ( और कण्ठादि आभ्यन्तर भागों ) के भीतर विचरनेवाले प्राण और अपानको समान करके।'),
('shankaracharya-ht:source:5.28','Śaṅkarācārya','gita.5.28','hi','translation','।।5.28।।जिसके इन्द्रिय मन और बुद्धि वशमें किये हुए हैं जो ईश्वरके स्वरूपका मनन करनेसे मुनि यानी संन्यासी है जो शरीरमें रहता हुआ भी मोक्षपरायण है अर्थात् जो मोक्षको ही परम आश्रय परम गति समझनेवाला मुनि है तथा जो इच्छा भय और क्रोधसे रहित हो चुका है जिसके इच्छा भय और क्रोध चले गये हैं जो इस प्रकार बर्तता है वह संन्यासी सदा मुक्त ही है उसे कोई दूसरी मुक्ति प्राप्त नहीं करनी है।'),
('shankaracharya-ht:source:5.29','Śaṅkarācārya','gita.5.29','hi','translation','।।5.29।।इस प्रकार समाहितचित्त हुए पुरुषद्वारा जाननेयोग्य क्या है इसपर कहते हैं ( मनुष्य ) मुझ नारायणको कर्तारूपसे और देवरूपसे समस्त यज्ञों और तपोंका भोक्ता सर्वलोकमहेश्वर अर्थात् सब लोकोंका महान् ईश्वर समस्त प्राणियोंका सुहृद् प्रत्युपकार न चाहकर उनका उपकार करनेवाला सब भूतोंके हृदयमें स्थित सब कर्मोंके फलोंका स्वामी और सब संकल्पोंका साक्षी जानकर शान्तिको अर्थात् सब संसारसे उपरामताको प्राप्त हो जाता है।'),
('shankaracharya-ht:source:6.1','Śaṅkarācārya','gita.6.1','hi','translation','।।6.1।।इसी भावसे वह संन्यासी और योगी है इस प्रकार उसकी स्तुति की जाती है भगवान् श्रीकृष्ण बोले जिसने आश्रय नहीं लिया हो वह अनाश्रित है किसका कर्मफलका अर्थात् जो कर्मोंके फलका आश्रय न लेनेवाला कर्मफलकी तृष्णासे रहित है। क्योंकि जो कर्मफलकी तृष्णावाला होता है वही कर्मफलका आश्रय लेता है यह उससे विपरीत है इसलिये कर्मफलका आश्रय न लेनेवाला है। ऐसा ( कर्मफलके आश्रयसे रहित ) होकर जो पुरुष कर्तव्यकर्मोंको अर्थात् काम्यकर्मोंसे विपरीत नित्य अग्निहोत्रादि कर्मोंको पूरा करता है ऐसा जो कोई कर्मी है वह दूसरे कर्मियोंकी अपेक्षा श्रेष्ठ है इसी अभिप्रायसे यह कहा है कि वह संन्यासी भी है और योगी भी है। संन्यास नाम त्यागका है वह जिसमें हो वही संन्यासी है और चित्तके समाधानका नाम योग है वह जिसमें हो वही योगी है अतः वह कर्मयोगी भी इन गुणोंसे सम्पन्न माना जाना चाहिये। केवल अग्निरहित और क्रियारहित पुरुष ही संन्यासी और योगी है ऐसा नहीं मानना चाहिये। कर्मोंके अङ्गभूत गार्हपत्यादि अग्नि जिससे छूट गये हैं वह निरग्नि है और बिना अग्निके होनेवाली तपदानादि क्रिया भी जो नहीं करता वह अक्रिय है। पू0 जब कि निरग्नि और अक्रिय पुरुषके लिये ही श्रुति स्मृति और योगशास्त्रोंमें संन्यासित्व और योगित्व प्रसिद्ध है तब यहाँ अग्नियुक्त और क्रियायुक्त पुरुषके लिये अप्रसिद्ध संन्यासित्व और योगित्वका प्रतिपादन कैसे किया जाता है उ0 यह दोष नहीं है क्योंकि किसी एक गुणवृत्तिसे ( किसी एक गुणविशेषको लेकर ) संन्यासित्व और योगित्व इन दोनों भावोंको उसमें ( गृहस्थमें ) सम्पादन करना भगवान्को इष्ट है। पू0 वह कैसे उ0 कर्मफलके संकल्पोंका त्याग होनेसे संन्यासित्व है और योगके अङ्गरूपसे कर्मोंका अनुष्ठान होनेसे या चित्तविक्षेपके कारणरूप कर्मफलके संकल्पोंका परित्याग होनेसे योगित्व है इस प्रकार दोनों भाव ही गौणरूपसे माने गये हैं।'),
('shankaracharya-ht:source:6.2','Śaṅkarācārya','gita.6.2','hi','translation','।।6.2।।इससे मुख्य संन्यासित्व और योगित्व इष्ट नहीं है। इसी भावको दिखलानेके लिये कहते हैं श्रुतिस्मृतिके ज्ञाता पुरुष सर्वकर्म और उनके फलके त्यागरूप जिस भावको वास्तविक संन्यास कहते हैं हे पाण्डव कर्मानुष्ठानरूप योगको ( निष्काम कर्मयोगको ) भी तू वही वास्तविक संन्यास जान। प्रवृत्तिरूप कर्मयोगकी उससे विपरीत निवृत्तिरूप परमार्थसंन्यासके साथ कैसी समानता स्वीकार करके एकता कही जाती है ऐसा प्रश्न होनेपर यह कहा जाता है परमार्थसंन्यासके साथ कर्मयोगकी कर्तृविषयक समानता है क्योंकि जो परमार्थसंन्यासी है वह सब कर्मसाधनोंका त्याग कर चुकता है इसलिये सब कर्मोंका और उनके फलविषयक संकल्पोंका जो कि प्रवृत्तिहेतुक कामके कारण है त्याग करता है। और यह कर्मयोगी भी कर्म करता हुआ फलविषयक संकल्पोंका त्याग करता ही है ( इस प्रकार दोनोंकी समानता है ) इस अभिप्रायको दिखलाते हुए कहते हैं जिसने फलविषयक संकल्पोंका यानी इच्छाओंका त्याग न किया हो ऐसा कोई भी कर्मी योगी नहीं हो सकता। अर्थात् ऐसे पुरुषका चित्त समाधिस्थ होना सम्भव नहीं है क्योंकि फलका संकल्प ही चित्तके विक्षेपका कारण है। इसलिये जो कोई कर्मी फलविषयक संकल्पोंका त्याग कर देता है वही योगी होता है। अभिप्राय यह है कि चित्तविक्षेपका कारण जो फलविषयक संकल्प है उसके त्यागसे ही मनुष्य समाधानयुक्त यानी चित्तविक्षेपसे रहित योगी होता है। इस प्रकार परमार्थसंन्यासकी और कर्मयोगकी कर्त्ताके भावसे सम्बन्ध रखनेवाली जो त्यागविषयक समानता है उसकी अपेक्षासे ही कर्मयोगकी स्तुति करनेके लिये यं संन्यासमिति प्राहुर्योगं तं विद्धि पाण्डव इस श्लोकमें उसे संन्यास बतलाया है।'),
('shankaracharya-ht:source:6.3','Śaṅkarācārya','gita.6.3','hi','translation','।।6.3।।फलेच्छासे रहित जो कर्मयोग है वह ध्यानयोगका बहिरंग साधन है इस उद्देश्यसे उसकी संन्यासरूपसे स्तुति करके अब यह भाव दिखलाते हैं कि कर्मयोग ध्यानयोगका साधन है जो ध्यानयोगमें आरूढ़ नहीं ध्यानयोगमें स्थित नहीं रह सकता है ऐसे योगारूढ़ होनेकी इच्छावाले मुनि अर्थात् कर्मफलत्यागी पुरुषके लिये ध्यानयोगपर आरूढ़ होनेका साधन कर्म बतलाया गया है। तथा वही जब योगारूढ़ हो जाता है तो उसके लिये योगारूढ़ता ( ध्यानयोगमें सदा स्थित रहनेका ) साधन शम उपशम यानी सर्व कर्मोंसे निवृत्त होना बतलाया गया है। ( मनुष्य ) जितनाजितना कर्मोंसे उपरत होता जाता है उतनाउतना ही उस परिश्रमरहित जितेन्द्रिय पुरुषका चित्त समाहित होता जाता है। ऐसा होनेसे वह झटपट योगारूढ़ हो जाता है। व्यासजीने भी यही कहा है कि ब्राह्मणके लिये दूसरा ऐसा कोई धन नहीं है जैसा कि एकता समता सत्यता शील स्थिति अहिंसा आर्जव और उनउन क्रियाओंसे उपराम होना है।'),
('shankaracharya-ht:source:6.4','Śaṅkarācārya','gita.6.4','hi','translation','।।6.4।।साधक कब योगारूढ़ हो जाता है यह अब बतलाते हैं चित्तका समाधान कर लेनेवाला योगी जब इन्द्रियोंके अर्थोंमें अर्थात् इन्द्रियोंके विषय जो शब्दादि हैं उनमें एवं नित्य नैमित्तिक काम्य और निषिद्ध कर्मोंमें अपना कुछ भी प्रयोजन न देखकर आसक्त नहीं होता उनमें आसक्ति यानी ये मुझे करने चाहिये ऐसी बुद्धि नहीं करता। तब उस समय वह सब संकल्पोंका त्यागी अर्थात् इस लोक और परलोकके भोगोंकी कामनाके कारणरूप सब संकल्पोंका त्याग करना जिसका स्वभाव हो चुका है ऐसा पुरुष योगारूढ़ यानी योगको प्राप्त हो चुका है ऐसे कहा जाता है। सर्वसंकल्पसंन्यासी इस कथनका यह आशय है कि सब कामनाओंको और समस्त कर्मोंको छोड़ देना चाहिये। क्योंकि सब कामनाओंका मूल संकल्प ही है। स्मृतिमें भी कहा है कि कामका मूल कारण संकल्प ही है। समस्त यज्ञ संकल्पसे उत्पन्न होते हैं। हे काम मैं तेरे मूल कारणको जानता हूँ। तू निःसन्देह संकल्पसे ही उत्पन्न होता है। मैं तेरा संकल्प नहीं करूँगा अतः फिर तू मूझे प्राप्त नहीं होगा। सब कामनाओंके परित्यागसे ही सर्व कर्मोंका त्याग सिद्ध हो जाता है। यह बात वह जैसी कामनावालाहोता है वैसे ही निश्चयवाला होता है जैसे निश्चयवाला होता है वही कर्म करता है इत्यादि श्रुतिसे प्रमाणित है और जीव जोजो कर्म करता है वह सब कामकी ही चेष्टा है। इत्यादि स्मृतिसे भी प्रमाणित है। युक्तिसे भी यही बात सिद्ध होती है क्योंकि सब संकल्पोंका त्याग कर देनेपर तो कोई जरासा हिल भी नहीं सकता। सुतरां सर्वसंकल्पसंन्यासी कहकर भगवान् समस्त कामनाओंका और समस्त कर्मोंका त्याग कराते हैं।'),
('shankaracharya-ht:source:6.5','Śaṅkarācārya','gita.6.5','hi','translation','।।6.5।।जब मनुष्य इस प्रकार योगारूढ़ हो जाता है तब वह अनर्थोंके समूह इस संसारसमुद्रसे स्वयं अपना उद्धार कर लेता है इसलिये संसारसागरमें डूबे पड़े हुए अपनेआपको उस संसारसमुद्रसे आत्मबलके द्वारा ऊँचा उठा लेना चाहिये अर्थात् योगारूढ़ अवस्थाको प्राप्त कर लेना चाहिये। अपना अधःपतन नहीं करना चाहिये अर्थात् अपने आत्माको नीचे नहीं गिरने देना चाहिये। क्योंकि यह आप ही अपना बन्धु है। दूसरा कोई ( ऐसा ) बन्धु नहीं है जो संसारसे मुक्त करनेवाला हो। प्रेमादि भाव बन्धनके स्थान होनेके कारण सांसारिक बन्धु भी ( वास्तवमें ) मोक्षमार्गका तो विरोधी ही होता है। इसलिये निश्चयपूर्वक यह कहना ठीक ही है कि आप ही अपना बन्धु है। तथा आप ही अपना शत्रु है। जो कोई दूसरा अनिष्ट करनेवाला बाह्य शत्रु है वह भी अपना ही बनाया हुआ होता है इसलिये आप ही अपना शत्रु है इस प्रकार केवल अपनेको ही शत्रु बतलाना भी ठीक ही है।'),
('shankaracharya-ht:source:6.6','Śaṅkarācārya','gita.6.6','hi','translation','।।6.6।।आप ही अपना मित्र है और आप ही अपना शत्रु है यह बात कही गयी उसमें किन लक्षणोंवाला पुरुष तो ( आप ही ) अपना मित्र होता है और कौन ( आप ही ) अपना शत्रु होता है सो कहा जाता है उस जीवात्माका तो वही आप मित्र है कि जिसने स्वयमेव कार्यकरणके समुदाय शरीररूप आत्माको अपने वशमें कर लिया हो अर्थात् जो जितेन्द्रिय हो। जिसने ( कार्यकरणके संघात ) शरीररूप आत्माको अपने वशमें नहीं किया उसका वह आपही शत्रुकी भाँति शत्रुभावमें बर्तता है। अर्थात् जैसे दूसरा शत्रु अपना अनिष्ट करनेवाला होता है वैसे ही वह आप ही अपना अनिष्ट करनेमें लगा रहता है।'),
('shankaracharya-ht:source:6.7','Śaṅkarācārya','gita.6.7','hi','translation','।।6.7।।जिसने मन इन्द्रिय आदिके संघातरूप इस शरीरको अपने वशमें कर लिया है और जो प्रशान्त है जिसका अन्तःकरण सदा प्रसन्न रहता है उस संन्यासीको भली प्रकारसे सर्वत्र परमात्मा प्राप्त है अर्थात् साक्षात् आत्मभावसे विद्यमान है। तथा वह सर्दीगर्मी और सुखदुःखमें एवं मान और अपमानमें यानी पूजा और तिरस्कारमें भी ( सम हो जाता है )।'),
('shankaracharya-ht:source:6.8','Śaṅkarācārya','gita.6.8','hi','translation','।।6.8।।शास्त्रोक्त पदार्थोंको समझनेका नाम ज्ञान है और शास्त्रसे समझे हुए भावोंको वैसे ही अपने अन्तःकरणमें प्रत्यक्ष अनुभव करनेका नाम विज्ञान है ऐसे ज्ञान और विज्ञान से जिसका अन्तःकरण तृप्त है अर्थात् जिसके अन्तःकरणमें ऐसा विश्वास उत्पन्न हो गया है कि बस अब कुछ भी जानना बाकी नहीं है ऐसा जो ज्ञानविज्ञानसे तृप्त हुए अन्तःकरणवाला है तथा जो कूटस्थ यानी अविचल और जितेन्द्रिय हो जाता है वह युक्त यानी समाहित ( समाधिस्थ ) कहा जाता है। वह योगी मिट्टी पत्थर और सुवर्णको समान समझनेवाला होता है अर्थात् उसकी दृष्टिमें मिट्टी पत्थर और सोना सब समान हैं ( एक ब्रह्मरूप है )।'),
('shankaracharya-ht:source:6.9','Śaṅkarācārya','gita.6.9','hi','translation','।।6.9।।तथा सुहृत् शब्दसे लेकर आधा श्लोक एक पद है। सुहृत् प्रत्युपकार न चाहकर उपकार करनेवाला मित्र प्रेमी अरि शत्रु उदासीन पक्षपातरहित मध्यस्थ जो परस्पर विरोध करनेवाले दोनोंका हितैषी हो द्वेष्य अपना अप्रिय और बन्धु अपना कुटुम्बी इन सबमें तथा शास्त्रानुसार चलनेवाले श्रेष्ठ पुरुषोंमें और निषिद्ध कर्म करनेवाले पापियोंमें भी जो समबुद्धिवाला है इन सबमें कौन कैसा क्या कर रहा है ऐसे विचारमें जिसकी बुद्धि नहीं लगती है वह श्रेष्ठ है। अर्थात् ऐसा योगी सब योगारूढ़ पुरुषोंमें उत्तम है। यहाँ विशिष्यते के स्थानमें विमुच्यते ( मुक्त हो जाता है ) ऐसा पाठान्तर भी है।'),
('shankaracharya-ht:source:6.10','Śaṅkarācārya','gita.6.10','hi','translation','।।6.10।।अतः ऐसे उत्तम फलकी प्राप्तिके लिये ध्यान करनेवाला योगी अकेला किसीको साथ न लेकर पहाड़की गुफा आदि एकान्त स्थानमें स्थित हुआ निरन्तर अपने अन्तःकरणको ध्यानमें स्थिर किया करे। एकान्त स्थानमें स्थित हुआ और अकेला इन विशेषणोंसे यह भाव पाया जाता है कि संन्यास ग्रहण करके योगका साधन करे। जिसका चित्त अन्तःकरण और आत्मा शरीर ( दोनों ) जीते हुए हैं ऐसा यतचित्तात्मा निराशी तृष्णाहीन और संग्रहरहित होकर अर्थात् संन्यासी होनेपर भी सब संग्रहका त्याग करके योगका अभ्यास करे।'),
('shankaracharya-ht:source:6.11','Śaṅkarācārya','gita.6.11','hi','translation','।।6.11।।योगाभ्यास करनेवालेके लिये योगके साधनरूप आसन आहार और विहार आदिका नियम बतलाना उचित है एवं योगको प्राप्त हुए पुरुषका लक्षण और उसका फल आदि भी कहना चाहिये। इसलिये अब ( यह प्रकरण ) आरम्भ किया जाता है। उसमें पहले आसनका ही वर्णन करते हैं शुद्ध स्थानमें अर्थात् जो स्वभावसे अथवा झाड़नेबुहारने आदि संस्कारोंसे साफ किया हुआ पवित्र और एकान्त स्थान हो उसमें अपने आसनको जो न अति ऊँचा हो और न अति नीचा हो और जिसपर क्रमसे वस्त्र मृगचर्म और कुशा बिछाये गये हों अविचलभावसे स्थापन करके। यहाँ पाठक्रमसे उन वस्त्रादिका क्रम उलटा समझना चाहिये अर्थात् पहले कुशा उसपर मृगचर्म और फिर उसपर वस्त्र बिछावे।'),
('shankaracharya-ht:source:6.12','Śaṅkarācārya','gita.6.12','hi','translation','।।6.12।।( आसनको ) स्थिर स्थापन करके क्या करे ( सो कहते हैं ) उस आसनर बैठकर योगका साधन करे। कैसे करे मनको सब विषयोंसे हटाकर एकाग्र करके तथा यतचित्तेन्द्रियक्रिय यानी चित्त और इन्द्रियोंकी क्रियाओंको जीतनेवाला होकर योगका साधन करे। जिसने मन और इन्द्रियोंकी क्रियाओंका संयम कर लिया हो उसको यतचित्तेन्द्रियक्रिय कहते हैं। वह किसलिये योगका साधन करे सो कहते हैं आत्मशुद्धिके लिये अर्थात् अन्तःकरणकी शुद्धिके लिये करे।'),
('shankaracharya-ht:source:6.13','Śaṅkarācārya','gita.6.13','hi','translation','।।6.13।।बाह्य आसनका वर्णन किया अब शरीरको कैसे रखना चाहिये सो कहते हैं काया शिर और गरदनको सम और अचल भावसे धारण करके स्थिर होकर बैठे। समानभावसे धारण किये हुए कायादिका भी चलन होना सम्भव है इसलिये अचलम् यह विशेषण दिया गया है। तथा अपनी नासिकाके अग्रभागको देखता हुआ यानी मानो वह उधर ही अच्छी तरह देख रहा है। इस प्रकार दृष्टि करके। यहाँ संप्रेक्ष्य के साथ इव शब्द लुप्त समझना चाहिये क्योंकि यहाँ अपनी नासिकाके अग्रभागको देखनेका विधान करना अभिमत नहीं है। तो क्या है बस नेत्रोंकी दृष्टिको ( विषयोंकी ओरसे रोककर ) वहाँ स्थापन करना ही इष्ट है। वह ( इस तरह दृष्टिस्थापना करना ) भी अन्तःकरणके समाधानके लिये आवश्यक होनेके कारण भी अभीष्ट है। क्योंकि यदि अपनी नासिकाके अग्रभागको देखना ही विधेय माना जाय तो फिर मन वहीं स्थित होगा आत्मामें नहीं। परंतु ( आगे चलकर ) आत्मसंस्थं मनः कृत्वा इस पदसे आत्मामें ही मनको स्थित करना बतलायेंगे। इसलिये इव शब्दके लोपद्वारा नेत्रोंकी दृष्टिको नासिकाके अग्रभागपर लगाना ही संप्रेक्ष्य इस पदसे कहा गया। इस प्रकार ( नेत्रोंकी दृष्टिको नासिकाके अग्रभागपर लगाकर ) तथा अन्य दिशाओंको न देखता हुआ अर्थात् बीचबीचमें दिशाओंकी ओर दृष्टि न डालता हुआ।'),
('shankaracharya-ht:source:6.14','Śaṅkarācārya','gita.6.14','hi','translation','।।6.14।।तथा प्रशान्तात्मा अच्छी प्रकारसे शान्त हुए अन्तःकरणवाला विगतभी निर्भय और ब्रह्मचारियोंके व्रतमें स्थित हुआ अर्थात् ब्रह्मचर्य गुरुसेवा भिक्षाभोजन आदि जो ब्रह्मचारीके व्रत हैं उनमें स्थित हुआ उनका अनुष्ठान करनेवाला होकर और मनका संयम करके अर्थात् मनकी वृत्तियोंका उपसंहार करके तथा मुझमें चित्तवाला अर्थात् मुझ परमेश्वरमें ही जिसका चित्त लग गया है ऐसा मच्चित्त होकर तथा समाहितचित्त होकर और मुझे ही सर्वश्रेष्ठ माननेवाला अर्थात् मैं ही जिसके मतमें सबसे श्रेष्ठ हूँ ऐसा होकर बैठे। कोई स्त्रीप्रेमी स्त्रीमें चित्तवाला हो सकता है परंतु वह स्त्रीको सबसे श्रेष्ठ नहीं समझता। तो किसको समझता है वह राजाको या महादेवको स्त्रीकी अपेक्षा श्रेष्ठ समझता है परंतु यह साधक तो चित्त भी मुझमें ही रखता है और मुझे ही सबसे अधिक श्रेष्ठ भी समझता है।'),
('shankaracharya-ht:source:6.15','Śaṅkarācārya','gita.6.15','hi','translation','।।6.15।।अब योगका फल कहा जाता है नियत मनवाला योगी अर्थात् जिसका मन जीता हुआ है ऐसा योगी उपर्युक्त प्रकारसे सदा आत्माका समाधान करता हुआ अर्थात् मनको परमात्मामें स्थिर करताकरता मुझमें स्थित निर्वाणदायिनी शान्तिको उपरतिको पाता है अर्थात् जिस शान्तिकी परमनिष्ठा अन्तिम स्थिति मोक्ष है एवं जो मुझमें स्थित है मेरे अधीन है ऐसी शान्तिको प्राप्त होता है।'),
('shankaracharya-ht:source:6.16','Śaṅkarācārya','gita.6.16','hi','translation','।।6.16।।अब योगीके आहार आदिके नियम कहे जाते हैं अधिक खानेवालेका अर्थात् अपनी शक्तिका उल्लङ्घन करके शक्तिसे अधिक भोजन करनेवालाका योग सिद्ध नहीं होता और बिल्कुल न खानेवालेका भी योग सिद्ध नहीं होता क्योंकि यह श्रुति है कि जो अपने शरीरकी शक्तिके अनुसार अन्न खाया जाता है वह रक्षा करता है वह कष्ट नहीं देता ( बिगाड़ नहीं करता ) जो उससे अधिक होता है वह कष्ट देता है और जो प्रमाणसे कम होता है वह रक्षा नहीं करता। इसलिये योगीको चाहिये कि अपने लिये जितना उपयुक्त हो उससे कम या ज्यादा अन्न न खाय। अथवा यह अर्थ समझो कि योगीके लिये योगशास्त्रमें बतलाया हुआ जो अन्नका परिमाण है उससे अधिक खानेवालेका योग सिद्ध नहीं होता। वहाँ यह परिमाण बतलाया है कि पेटका आधा भाग अर्थात् दो हिस्से तो शाकपात आदि व्यञ्जनोंसहित भोजनसे और तीसरा हिस्सा जलसे पूर्ण करना चाहिये तथा चौथा वायुके आनेजानेके लिये खाली रखना चाहिये इत्यादि। तथा हे अर्जुन न तो बहुत सोनेवालेका ही योग सिद्ध होता है और न अधिक जागनेवालेको ही योगसिद्धि प्राप्त होती है।'),
('shankaracharya-ht:source:6.17','Śaṅkarācārya','gita.6.17','hi','translation','।।6.17।।तो फिर योग कैसे सिद्ध होता है सो कहते हैं जो खाया जाय वह आहार अर्थात् अन्न और चलनाफिरनारूप जो पैरोंकी क्रिया है वह विहार यह दोनों जिसके नियमित परिमाणसे होते हैं और कर्मोंमें जिसकी चेष्टा नियमित परमाणसे होती है जिसका सोना और जागना नियतकालमें यथायोग्य होता है ऐसे यथायोग्य आहारविहारवाले और कर्मोंमें यथायोग्य चेष्टा करनेवाले तथा यथायोग्य सोने और जागनेवाले योगीका दुःखनाशक योग सिद्ध हो जाता है। सब दुःखोंको हरनेवालेका नाम दुःखहा है। ऐसा सब संसाररूप दुःखोंका नाश करनेवाला योग ( उस योगीका ) सिद्ध होता है यह अभिप्राय है।'),
('shankaracharya-ht:source:6.18','Śaṅkarācārya','gita.6.18','hi','translation','।।6.18।।अब यह बतलाते हैं कि ( साधक पुरुष ) कब युक्त ( समाधिस्थ ) हो जाता है वशमें किया हुआ चित्त यानी विशेषरूपसे एकाग्रताको प्राप्त हुआ चित्त जब बाह्य चिन्तनको छोड़कर केवल आत्मामें ही स्थित होता है अपने स्वरूपमें स्थिति लाभ करता है। तब उस समय सब भोगोंकी लालसासे रहित हुआ योगी अर्थात् दृष्ट और अदृष्ट समस्त भोगोंसे जिसकी तृष्णा नष्ट हो गयी है ऐसा योगी युक्त है समाधिस्थ ( परमात्मामें स्थितिवाला ) है ऐसे कहा जाता है।'),
('shankaracharya-ht:source:6.19','Śaṅkarācārya','gita.6.19','hi','translation','।।6.19।।उस योगीका जो समाधिस्थ चित्त है उसकी उपमा कही जाती है जैसे वायुरहित स्थानमें रखा हुआ दीपक विचलित नहीं होता वही उपमा आत्मध्यानका अभ्यास करनेवाले समाधिमें स्थित हुए योगीके जीते हुए अन्तःकरणकी चित्तगतिको प्रत्यक्ष देखनेवाले योगवेत्ता पुरुषोंने मानी है। जिससे किसीकी समानता की जाय उसका नाम उपमा है।'),
('shankaracharya-ht:source:6.20','Śaṅkarācārya','gita.6.20','hi','translation','।।6.20।।इस प्रकार योगाभ्यासके बलसे वायुरहित स्थानमें रखे हुए दीपककी भाँति एकाग्र किया हुआ योगसाधनसे निरुद्ध किया हुआ सब ओरसे चञ्चलतारहित किया हुआ चित्त जिस समय उपरत होता है उपरतिको प्राप्त होता है। तथा जिस कालमें समाधिद्वारा अति निर्मल ( स्वच्छ ) हुए अन्तःकरणसे परम चैतन्य ज्योतिःस्वरूप आत्माका साक्षात् करता हुआ वह अपने आपमें ही संतुष्ट हो जाता है तृप्ति लाभ कर लेता है।'),
('shankaracharya-ht:source:6.21','Śaṅkarācārya','gita.6.21','hi','translation','।।6.21।।तथा जो सुख अत्यन्त यानी अन्तसे रहित अनन्त है जो इन्द्रियोंकी कुछ भी अपेक्षा न करके केवल बुद्धिसे ही ग्रहण किया जानेयोग्य है जो इन्द्रियोंकी पहुँचसे अतीत है यानी जो विषयजनित सुख नहीं है ऐसे सुखको यह योगी जिस कालमें अनुभव कर लेता है जिस कालमें अपने स्वरूपमें स्थित हुआ यह ज्ञानी उसतत्त्वसे वास्तविक स्वरूपसे चलायमान नहीं होता विचलित नहीं होता।'),
('shankaracharya-ht:source:6.22','Śaṅkarācārya','gita.6.22','hi','translation','।।6.22।।तथा जिस आत्मप्राप्तिरूप लाभको प्राप्त होकर उससे अधिक कोई दूसरा लाभ है ऐसा नहीं मानता दूसरे लाभको स्मरण भी नहीं करता। एवं जिस आत्मतत्त्वमें स्थित हुआ योगी शस्त्राघात आदि बड़े भारी दुःखोंद्वारा भी विचलित नहीं किया जा सकता।'),
('shankaracharya-ht:source:6.23','Śaṅkarācārya','gita.6.23','hi','translation','।।6.23।।यत्रोपरमते से लेकर यहाँतक समस्त विशेषणोंसे विशिष्ट आत्माका अवस्थाविशेषरूप जो योग कहा गया है उस योग नामक अवस्थाको दुःखोंके संयोगका वियोग समझना चाहिये। अभिप्राय यह कि दुःखोंसे संयोग होना दुःखसंयोग है उससे वियोग हो जाना दुःखोंके संयोगका वियोग है उस दुःखसंयोगवियोग को योग ऐसे विपरीत नामसे कहा हुआ समझना चाहिये। योगफलका उपसंहार करके अब दृढ़ निश्चयको और योगविषयक रुचिको भी योगका साधन बतानेके लिये पुनः प्रकारान्तरसे योगकी कर्तव्यता बतायी जाती है वह उपर्युक्त फलवाला योग बिना उकताये हुए चित्तसे निश्चयपूर्वक करना चाहिये। जिस चित्तमें निर्विण्णता ( उद्वेग ) न हो वह अनिर्विण्णचित्त है ऐसे अनिर्विण्ण ( न उकताये हुए ) चित्तसे निश्चयपूर्वक योगका साधन करना चाहिये यह अभिप्राय है।'),
('shankaracharya-ht:source:6.24','Śaṅkarācārya','gita.6.24','hi','translation','।।6.24।।तथा संकल्पसे उत्पन्न हुई समस्त कामनाओंको निःशेषतासे अर्थात् लेशमात्र भी शेष न रखते हुए निर्लेपभावसे छोड़कर एवं विवेकयुक्त मनसे इन्द्रियोंके समुदायको सब ओरसे रोककर अर्थात् उनका संयम करके।'),
('shankaracharya-ht:source:6.25','Śaṅkarācārya','gita.6.25','hi','translation','।।6.25।।शनैःशनैः अर्थात् सहसा नहीं क्रमक्रमसे उपरतिको प्राप्त करे। किसके द्वारा बुद्धिद्वारा। कैसी बुद्धिद्वारा धैर्यसे धारण की हुई अर्थात् धैर्ययुक्त बुद्धिद्वारा। तथा मनको आत्मामें स्थित करके अर्थात् यह सब कुछ आत्मा ही है उससे अतिरिक्त अन्य कुछ भी नहीं है इस प्रकार मनको आत्मामें अचल करके अन्य किसी वस्तुका भी चिन्तन न करे। यह योगकी परम श्रेष्ठ विधि है।'),
('shankaracharya-ht:source:6.26','Śaṅkarācārya','gita.6.26','hi','translation','।।6.26।।इस प्रकार मनको आत्मामें स्थित करनेमें लगा हुआ योगी स्वाभाविक दोषके कारण जो अत्यन्त चञ्चल है तथा इसीलिये जो अस्थिर है ऐसा मन जिसजिस शब्दादि विषयके निमित्तसे विचलित होता है बाहर जाता है उसउस शब्दादि विषयरूप निमित्तसे ( इस मनको ) रोककर एवं उसउस विषयरूप निमित्तको यथार्थ तत्त्वनिरूपणद्वारा आभासमात्र दिखाकर वैराग्यकी भावनासे इस मनका ( बारंबार ) आत्मामें ही निरोध करे अर्थात् इसे आत्माके ही वशीभूत किया करे। इस प्रकार योगाभ्यासके बलसे योगीका मन आत्मामें ही शान्त हो जाता है।'),
('shankaracharya-ht:source:6.27','Śaṅkarācārya','gita.6.27','hi','translation','।।6.27।।क्योंकि जिसका मन भलीभाँति शान्त है जिसका रजोगुण शान्त हो गया है अर्थात् जिसका मोहादि क्लेशरूप रजोगुण अच्छी प्रकार क्षीण हो चुका है जो ब्रह्मरूप जीवन्मुक्त अर्थात् यह सब कुछ ब्रह्म ही है ऐसे निश्चयवाला है एवं जो अधर्मादि दोषोंसे रहित है उस योगीको निरतिशय उत्तम सुख प्राप्तहोता है।'),
('shankaracharya-ht:source:6.28','Śaṅkarācārya','gita.6.28','hi','translation','।।6.28।।योगविषयक विघ्नोंसे रहित हुआ विगतकल्मषनिष्पाप योगी उपर्युक्त क्रमसे सदा चित्तको समाहित करता हुआ अनायास ही ब्रह्मप्राप्तिरूप निरतिशय उत्कृष्ट सुखका अनुभव करता है अर्थात् जिसका परब्रह्मसे सम्बन्ध है और जो अन्तसे अतीतअनन्त है ऐसे परम सुखको प्राप्त हो जाता है।'),
('shankaracharya-ht:source:6.29','Śaṅkarācārya','gita.6.29','hi','translation','।।6.29।।अब योगका फल जो कि समस्त संसारका विच्छेद करा देनेवाला ब्रह्मके साथ एकताका देखना है वह दिखलाया जाता है समाहित अन्तःकरणसे युक्त और सब जगह समदृष्टिवाला योगी जिसका ब्रह्म और आत्माकी एकताको विषय करनेवाला ज्ञान ब्रह्मासे लेकर स्थावरपर्यन्त समस्त विभक्त प्राणियोंमें भेदभावसे रहित सम हो चुका है ऐसा पुरुष अपने आत्माको सब भूतोंमें स्थित (देखता है ) और आत्मामें सब भूतोंको देखता है। अर्थात् ब्रह्मासे लेकर स्तम्बपर्यन्त समस्त प्राणियोंको आत्मामें एकताको प्राप्त हुए देखता है।'),
('shankaracharya-ht:source:6.30','Śaṅkarācārya','gita.6.30','hi','translation','।।6.30।।इस आत्माकी एकताके दर्शनका फल कहा जाता है जो सबके आत्मा मुझ वासुदेवको सब जगह अर्थात् सब भूतोंमें ( व्यापक ) देखता है और ब्रह्मा आदि समस्त प्राणियोंको मुझ सर्वात्मा ( परमेश्वर ) में देखता है इस प्रकार आत्माकी एकताको देखनेवाले उस ज्ञानीके लिये मैं ईश्वर कभी अदृश्य नहीं होता अर्थात् कभी अप्रत्यक्ष नहीं होता और वह ज्ञानी भी कभी मुझ वासुदेवसे अदृश्य परोक्ष नहीं होता क्योंकि उसका और मेरा स्वरूप एक ही है। निःसंदेह अपना आत्मा अपना प्रिय ही होता है और जो सर्वात्मभावसे एकताको देखनेवाला है वह मैं ही हूँ।'),
('shankaracharya-ht:source:6.31','Śaṅkarācārya','gita.6.31','hi','translation','।।6.31।।( एकत्व भावमें स्थित हुआ जो पुरुष सम्पूर्ण भूतोंमें स्थित मुझ वासुदेवको भजता है ) इस प्रकार पहले श्लोकके अर्थरूप यथार्थ ज्ञानका इस आधे श्लोकसे अनुवाद करके उसके फलस्वरूप मोक्षका विधान करते हैं। वह पूर्ण ज्ञानी योगी सब प्रकारसे बर्तता हुआ भी वैष्णव परमपदरूप मुझ परमेश्वरमें ही बर्तता है अर्थात् वह सदा मुक्त ही है उसके मोक्षको कोई भी रोक नहीं सकता।'),
('shankaracharya-ht:source:6.32','Śaṅkarācārya','gita.6.32','hi','translation','।।6.32।।तथा और भी कहते हैं आत्मा अर्थात् स्वयं आप और जिसके द्वारा उपमित किया जाय वह उपमा उस उपमाके भावको ( सादृश्यको ) औपम्य कहते हैं। हे अर्जुन उस आत्मौपम्यद्वारा अर्थात् अपनी सदृशतासे जो योगी सर्वत्र सब भूतोंमें तुल्य देखता है। वह तुल्य क्या देखता है सो कहते हैं जैसे मुझे सुख प्रिय है वैसे ही सभी प्राणियोंको सुख अनुकूल है और जैसे दुःख मुझे अप्रिय प्रतिकूल है वैसे ही वह सब प्राणियोंको अप्रिय प्रतिकूल है। इस प्रकार जो सब प्राणियोंमें अपने समान ही सुख और दुःखको तुल्यभावसे अनुकूल और प्रतिकूल देखता है किसीके भी प्रतिकूल आचरण नहीं करता यानी अहिंसक है। यहाँ वा शब्दका प्रयोग च के अर्थमें हुआ है। जो इस प्रकारका अहिंसक पुरुष पूर्ण ज्ञानमें स्थित है वह योगी अन्य सब योगियोंमें परम उत्कृष्ट माना जाता है।'),
('shankaracharya-ht:source:6.33','Śaṅkarācārya','gita.6.33','hi','translation','।।6.33।।इस उपर्युक्त पूर्णज्ञानरूप योगको कठिनतासे सम्पादन किया जानेयोग्य समझकर उसकीप्राप्तिके निश्चित उपायको सुननेकी इच्छावाला अर्जुन बोला हे मधुसूदन आपने जो यह समत्वभावरूप योग कहा है मनकी चञ्चलताके कारण मैं इस योगकी अचल स्थिति नहीं देखता हैँ यह बात प्रसिद्ध है।'),
('shankaracharya-ht:source:6.34','Śaṅkarācārya','gita.6.34','hi','translation','।।6.34।।क्योंकि हे कृष्ण यह मन बड़ा ही चञ्चल है। विलेखनके अर्थमें जो कृष धातु है उसका रूप कृष्ण है। भक्तजनोंके पापादि दोषोंको निवृत्त करनेवाले होनेके कारण भगवान्का नाम कृष्ण है। यह मन केवल अत्यन्त चञ्चल है इतना ही नही किंतु प्रमथनशील भी है अर्थात् शरीरको क्षुब्ध और इन्द्रियोंको विक्षिप्त यानी परवश कर देता है। तथा बड़ा बलवान् है किसीसे भी वशमें किया जाना अशक्य है। साथ ही यह बड़ा दृढ़ भी है। अर्थात् तन्तुनाग ( गोह ) नामक जलचर जीवकी भाँति अच्छेद्य है। ऐसे लक्षणोंवाले इस मनका विरोध करना मैं वायुकी भाँति दुष्कर मानता हूँ। अभिप्राय यह कि जैसे वायुका रोकना दुष्कर है उससे भी अधिक दुष्कर मैं मनका रोकना मानता हूँ।'),
('shankaracharya-ht:source:6.35','Śaṅkarācārya','gita.6.35','hi','translation','।।6.35।।श्रीभगवान् बोले कि जैसे तू कहता है यह ठीक ऐसा ही है हे महाबाहो मन चञ्चल और कठिनतासे वशमें होनेवाला है इसमें ( कोई ) संदेह नहीं। किंतु अभ्याससे अर्थात् किसी चित्तभूमिमें एक समान वृत्तिकी बारंबार आवृत्ति करनेसे और दृष्ट तथा अदृष्ट प्रिय भोगोंमें बारंबार दोषदर्शनके अभ्यासद्वारा उत्पन्न हुए अनिच्छारूप वैराग्यसे चित्तके विक्षेपरूप प्रचार ( चञ्चलता ) को रोका जा सकता है। अर्थात् इस प्रकार उस मनका निग्रह निरोध किया जा सकता है।'),
('shankaracharya-ht:source:6.36','Śaṅkarācārya','gita.6.36','hi','translation','।।6.36।।परंतु जिसका अन्तःकरण वशमें किया हुआ नहीं है उस मनको वशमें न करनेवाले पुरुषद्वारा अर्थात् जिसका अन्तःकरण अभ्यास और वैराग्यद्वारा संयत किया हुआ नहीं है ऐसे पुरुषद्वारा योग प्राप्त किया जाना कठिन है अर्थात् उसको योग कठिनतासे प्राप्त हो सकता है यह मेरा निश्चय है। परंतु जो स्वाधीन मनवाला है जिसका मन अभ्यासवैराग्यद्वारा वशमें किया हुआ है और जो फिर भी बारंबार यत्न करता ही जाता है ऐसे पुरुषद्वारा पूर्वोक्त उपायोंसे यह योग प्राप्त किया जा सकता है।'),
('shankaracharya-ht:source:6.37','Śaṅkarācārya','gita.6.37','hi','translation','।।6.37।।योगाभ्यासको स्वीकार करके जिसने इस लोक और परलोककी प्राप्तिके साधनरूप कर्मोंका तो त्याग कर दिया और योगसिद्धिका फल मोक्षप्राप्तिका साधन पूर्ण ज्ञान जिसको मिला नहीं ऐसे जिस योगीका चित्त अन्तकालमें योगमार्गसे विचलित हो गया हो उस योगीके नाशकी आशङ्का करके अर्जुन पूछने लगा हे कृष्ण जो साधक योगमार्गमें यत्न करनेवाला नहीं है परंतु श्रद्धासे अर्थात् आस्तिकबुद्धिसे युक्त है और अन्तकालमें जिसका मन योगसे चलायमान हो गया है वह चञ्चलचित्त भ्रष्ट स्मृतिवाला योगी योगकी सिद्धिको अर्थात् योगफलरूप पूर्ण ज्ञानको न पाकर किस गतिको प्राप्त होता है ।'),
('shankaracharya-ht:source:6.38','Śaṅkarācārya','gita.6.38','hi','translation','।।6.38।।हे महाबाहो वह आश्रयरहित और ब्रह्मप्राप्तिके मार्गमें मोहित हुआ पुरुष कर्ममार्ग और ज्ञानमार्ग दोनों ओरसे भ्रष्ट होकर क्या छिन्नभिन्न हुए बादलकी भाँति नष्ट हो जाता है अथवा नष्ट नहीं होता।'),
('shankaracharya-ht:source:6.39','Śaṅkarācārya','gita.6.39','hi','translation','।।6.39।।हे कृष्ण मेरे इस संशयको निःशेषतासे काटनेके लिये अर्थात् नष्ट करनेके लिये आप हीसमर्थ हैं क्योंकि आपको छोड़कर दूसरा कोई ऋषि या देवता इस संशयका नाश करनेवाला सम्भव नहीं है। अतः आपको ही इसका नाश करना चाहिये यह अभिप्राय है।'),
('shankaracharya-ht:source:6.40','Śaṅkarācārya','gita.6.40','hi','translation','।।6.40।।श्रीभगवान् बोले हे पार्थ उस योगभ्रष्ट पुरुषका इस लोकमें या परलोकमें कहीं भी नाश नहीं होता है। पहलेकी अपेक्षा हीनजन्मकी प्राप्तिका नाम नाश है सो ऐसी अवस्था योगभ्रष्टकी नहीं होती। क्योंकि हे तात शुभ कार्य करनेवाला कोई भी मनुष्य दुर्गतिको अर्थात् नीच गतिको नहीं पाता। पिता पुत्ररूपसे आत्माका विस्तार करता है अतः उसको तात कहते हैं तथा पिता ही पुत्ररूपसे उत्पन्न होता है अतः पुत्रको भी तात कहते हैं। शिष्य भी पुत्रके तुल्य है इसलिये उसको भी तात कहते हैं।'),
('shankaracharya-ht:source:6.41','Śaṅkarācārya','gita.6.41','hi','translation','।।6.41।।तो फिर इस योगभ्रष्टका क्या होता है योगमार्गमें लगा हुआ योगभ्रष्ट संन्यासी पुण्यकर्म करनेवालोंके अर्थात् अश्वमेध आदि यज्ञ करनेवालोंके लोकोंमें जाकर वहाँ बहुत कालतक अर्थात् अनन्त वर्षोंतक वास करके उनके भोगका क्षय होनेपर शास्त्रोक्त कर्म करनेवाले शुद्ध और श्रीमान् पुरुषोंके घरमें जन्म लेता है। प्रकरणकी सामर्थ्यसे यहाँ योगभ्रष्टका अर्थ संन्यासी लिया गया है।'),
('shankaracharya-ht:source:6.42','Śaṅkarācārya','gita.6.42','hi','translation','।।6.42।।अथवा श्रीमानोंके कुलसे अन्य जो बुद्धिमान् दरिद्र योगियोंका कुल है उसीमें जन्म ले लेता है। परंतु ऐसा जन्म अर्थात् जो उपर्युक्त दरिद्र आदि विशेषणोंसे युक्त योगियोंके कुलमें उत्पन्न होना है वह इस लोकमें पहले बतलाये हुए श्रीमानोंके कुलमें उत्पन्न होनेकी अपेक्षा अत्यन्त दुर्लभ है।'),
('shankaracharya-ht:source:6.43','Śaṅkarācārya','gita.6.43','hi','translation','।।6.43।।क्योंकि वहाँ योगियोंके कुलमें पहले शरीरमें होनेवाले उस बुद्धिके संयोगको पाता है अर्थात् योगीकुलमें जन्म लेते ही उसका पूर्वजन्ममें प्राप्त हुई बुद्धिसे सम्बन्ध हो जाता है और हे कुरुनन्दन वह उस पूर्वकृत संस्कारके बलसे पूर्ण सिद्धि प्राप्त करनेके लिये फिर और भी अधिक प्रयत्न करता है।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:6.44','Śaṅkarācārya','gita.6.44','hi','translation','।।6.44।।पहले शरीरकी बुद्धिसे उसका संयोग कैसे होता है सो कहते हैं क्योंकि वह योगभ्रष्ट पुरुष परवश हुआ भी पूर्वाभ्यासके द्वारा अर्थात् जो पहले जन्ममें किया हुआ अभ्यास है उस अति बलवान् पूर्वाभ्यासके द्वारा योगकी ओर खींच लिया जाता है। यदि योगाभ्यासके संस्कारोंकी अपेक्षा अधिक बलवान् अधर्मादि कर्म न किये हों तो वह योगाभ्यासजनित संस्कारोंसे खिंच जाता है और यदि अधिक बलवान् अधर्म किया हुआ होता है तो उससे योगजन्य संस्कार भी दब ही जाते हैं। परंतु उस पापकर्मका क्षय होनेपर योगजन्य संस्कार स्वयं ही अपना कार्य आरम्भ कर देता है। बहुत बालतक दबे रहनेपर भी उसका नाश नहीं होता। जो योगका जिज्ञासु भी है अर्थात् जो योगके स्वरूपको जाननेकी इच्छा करके योगमार्गमें लगा हुआ योगभ्रष्ट संन्यासी है वह भी शब्दब्रह्मको अर्थात् वेदमें कहे हुए कर्मफलको अतिक्रम कर जाता है फिर जो योगको जानकर उसमें स्थित हुआ अभ्यास करता है उसका तो कहना ही क्या है। यहाँ प्रसंगकी शक्तिसे जिज्ञासुका अर्थ संन्यासी किया गया है।'),
('shankaracharya-ht:source:6.45','Śaṅkarācārya','gita.6.45','hi','translation','।।6.45।।योगित्व श्रेष्ठ किस कारणसे है जो प्रयत्नपूर्वक अधिक साधनमें लगा हुआ है वह विद्वान् योगी विशुद्धकिल्बिष अर्थात् अनेक जन्मोंमें थोड़ेथोड़े संस्कारोंको एकत्रितकर उन अनेक जन्मोंके सञ्चित संस्कारोंसे पापरहित होकर सिद्ध अवस्थाको प्राप्त हुआ सम्यक् ज्ञानको प्राप्त करके परमगति मोक्षको प्राप्त होता है।'),
('shankaracharya-ht:source:6.46','Śaṅkarācārya','gita.6.46','hi','translation','।।6.46।।ऐसा होनेके कारण तपस्वियों और ज्ञानियोंसे भी योगी अधिक है। यहाँ ज्ञान शास्त्रविषयक पाण्डित्यका नाम है उससे युक्त जो ज्ञानवान् हैं उनकी अपेक्षा योगी अधिक श्रेष्ठ है। तथा अग्निहोत्रादि कर्म करनेवालोंसे भी योगी अधिक श्रेष्ठ है इसलिये हे अर्जुन तू योगी है।'),
('shankaracharya-ht:source:6.47','Śaṅkarācārya','gita.6.47','hi','translation','।।6.47।।रुद्र आदित्य आदि देवोंके ध्यानमें लगे हुए समस्त योगियोंसे भी जो योगी श्रद्धायुक्त हुआ मुझ वासुदेवमें अच्छी प्रकार स्थित किये हुए अन्तःकरणसे मुझे ही भजता है उसे मैं युक्ततम अर्थात् अतिशय श्रेष्ठ योगी मानता हूँ।'),
('shankaracharya-ht:source:7.1','Śaṅkarācārya','gita.7.1','hi','translation','।।7.1।।इस श्लोकद्वारा छठे अध्यायके अन्तमें प्रश्नके बीजकी स्थापना करके फिर स्वयं ही ऐसा मेरा तत्त्व हे इस प्रकार मुझमें स्थित अन्तरात्मावाला हो जाना चाहिये इत्यादि बातोंका वर्णन करनेकी इच्छावाले भगवान् बोले आगे कहे जानेवाले विशेषणोंसे युक्त मुझ परमेश्वरमें ही जिसका मन आसक्त हो वह मय्यासक्तमना है और मैं परमेश्वर ही जिसका ( एकमात्र ) अवलम्बन हूँ वह मदाश्रय है हे पार्थ ऐसा मय्यासक्तमना और मदाश्रय होकर तू योगका साधन करताहुआ अर्थात् मनको ध्यानमें स्थित करता हुआ ( जिस प्रकार मुझको संशयरहित समग्ररूपसे जानेगा सो सुन ) जो कोई ( धर्मादि पुरुषार्थोंमेंसे ) किसी पुरुषार्थका चाहनेवाला होता है वह उसके साधनरूप अग्निहोत्रादि कर्म तप या दानरूप किसी एक आश्रयको ग्रहण किया करता है परंतु यह योगी तो अन्य साधनोंको छोड़कर केवल मुझको ही आश्रयरूपसे ग्रहण करता है और मुझमें ही आसक्तचित्त होता है। इसलिये तू उपर्युक्त गुणोंसे सम्पन्न होकर विभूति बल ऐश्वर्य आदि गुणोंसे सम्पन्न मुझ समग्र परमेश्वरको जिस प्रकार संशयरहित जानेगा कि भगवान् निस्सन्देह ठीक ऐसा ही है वह प्रकार मैं तुझसे कहता हूँ सुन।'),
('shankaracharya-ht:source:7.2','Śaṅkarācārya','gita.7.2','hi','translation','।।7.2।।वहीं यह अपने स्वरूपका ज्ञान मैं तुझे विज्ञानके सहित अर्थात् अपने अनुभवके सहित निःशेषतःसम्पूर्णतासे कहूँगा। श्रोताको सम्मुख अर्थात् सावधान करनेके लिये जिसका वर्णन करना है उस ज्ञानकी स्तुति करते हैं। जिस ज्ञानको जान लेनेपर फिर इस जगत्में पुरुषार्थका कोई साधन जानना शेष नहीं रहता अर्थात् जो मेरे तत्त्वको जाननेवाला है वह सर्वज्ञ हो जाता है। अतः यह ज्ञान अति उत्तम फलवाला होनेके कारण दुर्लभ है।'),
('shankaracharya-ht:source:7.3','Śaṅkarācārya','gita.7.3','hi','translation','।।7.3।।यह ( दुलर्भ ) कैसे है सो कहते हैं हजारों मनुष्योंमें कोई एक ही ( मोक्षरूप ) सिद्धिके लिये प्रयत्न करता है और उन यत्न करनेवाले सिद्धोंमें भी जो मोक्षके लिये यत्न करते हैं वे ( एक तरहसे ) सिद्ध ही हैं उनमें भी कोई एक ही मुझे तत्त्वसे यथार्थ जान पाता है।'),
('shankaracharya-ht:source:7.4','Śaṅkarācārya','gita.7.4','hi','translation','।।7.4।।इस प्रकार रुचि बढ़ाकर श्रोताको सम्मुख करके कहते हैं भिन्ना प्रकृतिरष्टधा वह कथन होनेके कारण यहाँ भूमिशब्दसे पृथिवीतन्मात्रा कही जाती है स्थूल पृथ्वी नहीं वैसे ही जल आदि तत्त्व भी तन्मात्रारूपसे कहे जाते हैं। ( इस प्रकार पृथ्वी ) जल अग्नि वायु और आकाश एवं मन यहाँ मनसे उसके कारणभूत अहंकारकाग्रहण किया गया है तथा बुद्धि अर्थात् अहंकारका कारण महत्तत्त्व और अहंकार अर्थात् अविद्यायुक्त अव्यक्त मूलप्रकृति। जैसे विषयुक्त अन्न भी विष ही कहा जाता है वैसे ही अहंकार और वासनासे युक्त अव्यक्त मूलप्रकृति भी अहंकार नामसे कही जाती है क्योंकि अहंकार सबका प्रवर्तक है संसारमें अहंकार ही सबकी प्रवृत्तिका बीज देखा गया है। इस प्रकार यह उपर्युक्त प्रकृति अर्थात् मुझ ईश्वरकी मायाशक्ति आठ प्रकारसे भिन्न है विभागको प्राप्त हुई है।'),
('shankaracharya-ht:source:7.5','Śaṅkarācārya','gita.7.5','hi','translation','।।7.5।।यह ( उपर्युक्त ) मेरी अपरा प्रकृति है अर्थात् परा नहीं किंतु निकृष्ट है अशुद्ध है और अनर्थ करनेवाली है एवं संसारबन्धनरूपा है। और हे महाबाहो इस उपर्युक्त प्रकृतिमें दूसरी जीवरूपा अर्थात् प्राणधारणकी निमित्त बनी हुई जो क्षेत्रज्ञरूपा प्रकृति है अन्तरमें प्रवृष्ट हुई जिस प्रकृतिद्वारा यह समस्त जगत् धारण किया जाता है उसको तू मेरी परा प्रकृति जान अर्थात् उसे मेरी आत्मरूपा उत्तम और शुद्ध प्रकृति जान।'),
('shankaracharya-ht:source:7.6','Śaṅkarācārya','gita.7.6','hi','translation','।।7.6।।यह क्षेत्र और क्षेत्रज्ञरूप दोनों परा और अपरा प्रकृति ही जिनकी योनि कारण है ऐसे ये समस्त भूतप्राणी प्रकृतिरूप कारणसे ही उत्पन्न हुए हैं ऐसा जान। क्योंकि मेरी दोनों प्रकृतियाँ ही समस्त भूतोंकी योनि यानी कारण हैं इसलिये समस्त जगत्का प्रभव उत्पत्ति और प्रलय विनाश मैं ही हूँ अर्थात् इन दोनों प्रकृतियोंद्वारा मैं सर्वज्ञ ईश्वर ही समस्त जगत्का कारण हूँ।'),
('shankaracharya-ht:source:7.7','Śaṅkarācārya','gita.7.7','hi','translation','।।7.7।।ऐसा होनेके कारण मुझ परमेश्वरसे परतर ( अतिरिक्त ) जगत्का कारण अन्य कुछ भी नहीं है अर्थात् मैं ही जगत्का एकमात्र कारण हूँ। हे धनंजय क्योंकि ऐसा है इसलिये यह सम्पूर्ण जगत् और समस्त प्राणी मुझ परमेश्वरमें दीर्घ तन्तुओंमें वस्त्रकी भाँति तथा सूत्रमें मणियोंकी भाँति पिरोया हुआ अनुस्यूत अनुगत बिंधा हुआ गूँथा हुआ है।'),
('shankaracharya-ht:source:7.8','Śaṅkarācārya','gita.7.8','hi','translation','।।7.8।।यह समस्त जगत् किसकिस धर्मसे युक्त आपमें पिरोया हुआ है इसपर कहते हैं जलमें मैं रस हूँ अर्थात् जलका जो सार है उसका नाम रस है उस रसरूप मुझ परमात्मामें समस्त जल पिरोया हुआ है। ऐसे ही और सबमें भी समझना चाहिये। जैसे जलमें मैं रस हूँ वैसे ही चन्द्रमा और सूर्यमें मैं प्रकाश हूँ। समस्त वेदोंमें मैं ओंकार हूँ अर्थात् उस ओंकाररूप मुझ परमात्मामें सब वेद पिरोये हुए हैं। आकाशमें उसका सारभूत शब्द हूँ अर्थात् उस शब्दरूप मुझ ईश्वरमें आकाश पिरोया हुआ है। तथा पुरुषोंमें मैं पौरुष हूँ अर्थात् पुरुषोंमें जो पुरुषत्व है जिससे उनको पुरुष समझा जाता है वह मैं हूँ उस पौरूषरूप मुझ ईश्वरमें पुरुष पिरोये हुए हैं।'),
('shankaracharya-ht:source:7.9','Śaṅkarācārya','gita.7.9','hi','translation','।।7.9।।पृथिवीमें मैं पवित्र गन्ध सुगन्ध हूँ अर्थात् उस सुगन्धरूप मुझ ईश्वरमें पृथिवी पिरोयी हुई है। जल आदिमें रस आदिकी पवित्रताका लक्ष्य करानेके लिये यहाँ गन्धकी स्वाभाविक पवित्रता ही पृथिवीमें दिखलायी गयी है। गन्धरस आदिमें जो अपवित्रता आ जाती है वह तो सांसारिक पुरुषोंके अज्ञान और अधर्म आदिकी अपेक्षासे एवं भूतविशेषोंके संसर्गसे है ( वह स्वाभाविक नहीं है )। मैं अग्निमें प्रकाश हूँ तथा सब प्राणियोंमें जीवन हूँ अर्थात् जिससे सब प्राणी जीते हैं वह जीवन मैं हूँ और तपस्वियोंमें तप मैं हूँ अर्थात् उस तपरूप मुझ परमात्मामें ( सब ) तपस्वी पिरोये हुए हैं।'),
('shankaracharya-ht:source:7.10','Śaṅkarācārya','gita.7.10','hi','translation','।।7.10।।हे पार्थ मुझे तू सब भूतोंका सनातन पुरातन बीज अर्थात् उनकी उत्पत्तिका मूल कारण जान। तथा मैं ही बुद्धिमानोंकी बुद्धि अर्थात् विवेकशक्ति और तेजस्वियों अर्थात् प्रभावशाली पुरुषोंका तेज प्रभाव हूँ।'),
('shankaracharya-ht:source:7.11','Śaṅkarācārya','gita.7.11','hi','translation','।।7.11।।बलवानोंका जो कामना और आसक्तिसे रहित बल ओज सामर्थ्य है वह मैं हूँ। ( अभिप्राय यह कि ) अप्राप्त विषयोंकी जो तृष्णा है उसका नाम काम है और प्राप्त विषयोंमें जो प्रीतितन्मयता है उसका नाम राग है उन दोनोंसे रहित केवल देह आदिको धारण करनेके लिये जो बल है वह मैं हूँ। जो संसारी जीवोंका बल कामना और आसक्तिका कारण है वह मैं नहीं हूँ। तथा हे भरतश्रेष्ठ प्राणियोंमें जो धर्मसे अविरुद्ध शास्त्रानुकूल कामना है जैसे देहधारणमात्रके लिये खानेपीनेकी इच्छा आदि वह ( इच्छारूप) काम भी मैं ही हूँ।'),
('shankaracharya-ht:source:7.12','Śaṅkarācārya','gita.7.12','hi','translation','।।7.12।।तथा जो सात्त्विक सत्त्वगुणसे उत्पन्न हुए भाव पदार्थ हैं और जो राजस रजोगुणसे उत्पन्न हुए एवं तामस तमोगुणसे उत्पन्न हुए भाव पदार्थ हैं उन सबको अर्थात् प्राणियोंके अपने कर्मानुसार ये जो कुछ भी भाव उत्पन्न होते हैं उन सबको तू मुझसे ही उत्पन्न हुए जान। यद्यपि वे मुझसे उत्पन्न होते हैं तथापि मैं उनमें नहीं हूँ अर्थात् संसारी मनुष्योंकी भाँति मैं उनके वशमें नहीं हूँ परंतु वे मुझमें हैं यानी मेरे वशमें हैं मेरे अधीन हैं।'),
('shankaracharya-ht:source:7.13','Śaṅkarācārya','gita.7.13','hi','translation','।।7.13।।ऐसा जो साक्षात् परमेश्वर नित्यशुद्धबुद्धमुक्तस्वभाव एवं सब भूतोंका आत्मा गुणोंसे अतीत और संसाररूप दोषके बीजको भस्म करनेवाला मैं हूँ उसको जगत् नहीं पहचानता इस प्रकार भगवान् खेद प्रकट करते हैं और जगत्का यह अज्ञान किस कारणसे है सो बतलाते हैं गुणोंमें विकाररूप सात्त्विक राजस और तामस इन तीनों भावोंसे अर्थात् उपर्युक्त राग द्वेष और मोह आदि पदार्थोंसे यह समस्त जगत् प्राणिसमूह मोहित हो रहा है अर्थात् विवेकशून्य कर दिया गया है अतः इन उपर्युक्त गुणोंसे अतीत विलक्षण अविनाशी विनाशरहित तथा जन्मादि सम्पूर्ण भावविकारोंसे रहित मुझ परमात्माको नहीं जान पाता।'),
('shankaracharya-ht:source:7.14','Śaṅkarācārya','gita.7.14','hi','translation','।।7.14।।तो फिर इस देवसम्बन्धिनी त्रिगुणात्मिका वैष्णवी मायाको मनुष्य कैसे तरते हैं इसपर कहते हैं क्योंकि यह उपर्युक्त दैवी माया अर्थात् मुझ व्यापक ईश्वरकी निज शक्ति मेरी त्रिगुणमयी माया दुस्तर हैअर्थात् जिससे पार होना बड़ा कठिन है ऐसी है। इसलिये जो सब धर्मोंको छोड़कर अपने ही आत्मा मुझ मायापति परमेश्वरकी ही सर्वात्मभावसे शरण ग्रहण कर लेते हैं वे सब भूतोंको मोहित करनेवाली इस मायासे तर जाते हैं वे इसके पार हो जाते हैं अर्थात् संसारबन्धनसे मुक्त हो जाते हैं।'),
('shankaracharya-ht:source:7.15','Śaṅkarācārya','gita.7.15','hi','translation','।।7.15।।यदि आपके शरण हुए मनुष्य इस मायासे तर जाते हैं तो फिर सभी आपकी शरण क्यों नहीं लेते इसपर कहते हैं जो कोई पापकर्म करनेवाले मूढ़ और नराधम हैं अर्थात् मनुष्योंमें अधम नीच हैं एवं मायाद्वारा जिनका ज्ञान छीन लिया गया है वे हिंसा मिथ्याभाषण आदि आसुरी भावोंके आश्रित हुए मनुष्य मुझ परमेश्वरकी शरणमें नहीं आते।'),
('shankaracharya-ht:source:7.16','Śaṅkarācārya','gita.7.16','hi','translation','।।7.16।।परंतु जो पुण्यकर्म करनेवाले नरश्रेष्ठ हैं ( वे क्या करते हैं सो बतलाते हैं ) हे भारत आर्त अर्थात् चोर व्याघ्र रोग आदिके वशमें होकर किसी आपत्तिसे युक्त हुआ जिज्ञासु अर्थात् भगवान्का तत्त्व जाननेकी इच्छावाला अर्थार्थी यानी धनकी कामनावाला और ज्ञानी अर्थात् विष्णुके तत्त्वको जाननेवाला हे अर्जुन ये चार प्रकारके पुण्यकर्मकारी मनुष्य मेरा भजनसेवन करते हैं।'),
('shankaracharya-ht:source:7.17','Śaṅkarācārya','gita.7.17','hi','translation','।।7.17।।उन चार प्रकारके भक्तोंमें जो ज्ञानी है अर्थात् यथार्थ तत्त्वको जाननेवाला है वह तत्त्ववेत्ता होनेके कारण सदा मुझमें स्थित है और उसकी दृष्टिमें अन्य किसी भजनेयोग्य वस्तुका अस्तित्व न रहनेके कारण वह केवल एक मुझ परमात्मामें ही अनन्य भक्तिवाला होता है। इसलिये वह अनन्य प्रेमी ( ज्ञानी भक्त ) श्रेष्ठ माना जाता है। ( अन्य तीनोंकी अपेक्षा ) अधिक उच्च कोटिका समझा जाता है। क्योंकि मैं ज्ञानीका आत्मा हूँ इसलिये उसको अत्यन्त प्रिय हूँ। संसारमें यह प्रसिद्ध ही है कि आत्मा ही प्रिय होता है। इसलिये ज्ञानीका आत्मा होनेके कारण भगवान् वासुदेव उसे अत्यन्त प्रिय होता है। यह अभिप्राय है। तथा वह ज्ञानी भी मुझ वासुदेवका आत्मा ही है अतः वह मेरा अत्यन्त प्रिय है।'),
('shankaracharya-ht:source:7.18','Śaṅkarācārya','gita.7.18','hi','translation','।।7.18।।तो फिर क्या आर्त आदि तीन प्रकारके भक्त आप वासुदेवके प्रिय नहीं हैं यह बात नहीं तो क्या बात है ये सभी भक्त उदार हैं श्रेष्ठ हैं। अर्थात् वे तीनों भी मेरे प्रिय ही हैं। क्योंकि मुझ वासुदेवको अपना कोई भी भक्त अप्रिय नहीं होता परंतु ज्ञानी मुझे अत्यन्त प्रिय होता है इतनी विशेषता है। ऐसा क्यों है सो कहते हैं ज्ञानी तो मेरा स्वरूप ही है वह मुझसे अन्य नहीं है यह मेरा निश्चय है क्योंकि वह योगारूढ़ होनेके लिये प्रवृत्त हुआ ज्ञानी स्वयं मैं ही भगवान् वासुदेव हूँ दूसरा नहीं ऐसा युक्तात्मा समाहितचित्त होकर मुझ परम प्राप्तव्य गतिस्वरूप परब्रह्ममें ही आनेके लिये प्रवृत्त है।'),
('shankaracharya-ht:source:7.19','Śaṅkarācārya','gita.7.19','hi','translation','।।7.19।।फिर भी ज्ञानीकी स्तुति करते हैं ज्ञानप्राप्तिके लिये जिनमें संस्कारोंका संग्रह किया जाय ऐसे बहुतसे जन्मोंका अन्तसमाप्ति होनेपर ( अन्तिम जन्ममें ) परिपक्व ज्ञानको प्राप्त हुआ ज्ञानी अन्तरात्मारूप मुझ वासुदेवको सब कुछ वासुदेव ही है इस प्रकार प्रत्यक्षरूपसे प्राप्त होता है। जो इस प्रकार सर्वात्मरूप मुझ परमात्माको प्रत्यक्षरूपसे प्राप्त हो जाता है वह महात्मा है उसके समान याउससे अधिक और कोई नहीं है अतः कहा है कि हजारों मनुष्योंमें भी ऐसा पुरुष अत्यन्त दुर्लभ है।'),
('shankaracharya-ht:source:7.20','Śaṅkarācārya','gita.7.20','hi','translation','।।7.20।।यह सर्व जगत् आत्मस्वरूप वासुदेव ही है इस प्रकार न समझमें आनेका कारण बतलाते हैं पुत्र पशु स्वर्ग आदि भोगोंकी प्राप्तिविषयक नाना कामनाओंद्वारा जिनका विवेकविज्ञान नष्ट हो चुका है वे लोग अपनी प्रकृतिसे अर्थात् जन्मजन्मान्तरमें इकट्ठे किये हुए संस्कारोंके समुदायरूप स्वभावसे प्रेरित हुए अन्य देवताओंको अर्थात् आत्मस्वरूप मुझ वासुदेवसे भिन्न जो देवता हैं उनको उन्हींकी आराधनाके लिये जोजो नियम प्रसिद्ध हैं उनका अवलम्बन करके भजते हैं अर्थात् उनकी शरण लेते हैं।'),
('shankaracharya-ht:source:7.21','Śaṅkarācārya','gita.7.21','hi','translation','।।7.21।।उन कामी पुरुषोंमेंसे जोजो सकाम भक्त जिसजिस देवताके स्वरूपका श्रद्धा और भक्तियुक्त होकर अर्चनपूजन करना चाहता है उसउस भक्तकी देवताविषयक उस श्रद्धाको मैं अचल स्थिर कर देता हूँ। अभिप्राय यह कि जो पुरुष पहले स्वभावसे ही प्रवृत्त हुआ जिस श्रद्धाद्वारा जिस देवताके स्वरूपका पूजन करना चाहता है (उस पुरुषकी उसी श्रद्धाको मैं स्थिर कर देता हूँ )।'),
('shankaracharya-ht:source:7.22','Śaṅkarācārya','gita.7.22','hi','translation','।।7.22।।मेरे द्वारा स्थिर की हुई उस श्रद्धासे युक्त हुआ वह उसी देवताके स्वरूपकी सेवा पूजा करनेमें तत्पर होता है। और उस आराधित देवविग्रहसे कर्मफलविभागके जाननेवाले मुझ सर्वज्ञ ईश्वरद्वारा निश्चित किये हुए इष्ट भोगोंको प्राप्त करता है। वे भोग परमेश्वरद्वारा निश्चित किये होते हैं इसलिये वह उन्हें अवश्य पाता है यह अभिप्राय है। यहाँपर यदि हितान् ऐसा पदच्छेद करें तो भोगोंमे जो हितत्व है उसको औपचारिक समझना चाहिये क्योंकि वास्तवमें भोग किसीके लिये भी हितकर नहीं हो सकते।'),
('shankaracharya-ht:source:7.23','Śaṅkarācārya','gita.7.23','hi','translation','।।7.23।।क्योंकि वे कामी और अविवेकी पुरुष विनाशशील साधनकी चेष्टा करनेवाले होते हैं इसलिये उन अल्पबुद्धिवालोंका वह फल नाशवान् विनाशशील होता है। देवयाजी अर्थात् जो देवोंका पूजन करनेवाले हैं वे देवोंको पाते हैं और मेरे भक्त मुझको ही पाते हैं। अहो बड़े दुःखकी बात है कि इस प्रकार समानपरिश्रम होनेपर भी लोग अनन्त फलकी प्राप्ति के लिये केवल मुझ परमेश्वरकी ही शरणमें नहीं आते। इस प्रकार भगवान् करुणा प्रकट करते हैं।'),
('shankaracharya-ht:source:7.24','Śaṅkarācārya','gita.7.24','hi','translation','।।7.24।।वे मुझ परमेश्वरकी ही शरणमें क्यों नहीं आते सो बतलाते हैं मेरे अविनाशी निरतिशय परम भावको अर्थात् परमात्मस्वरूपको न जाननेवाले बुद्धिरहित विवेकहीन मनुष्य मुझको यद्यपि मैं नित्यप्रसिद्ध सबका ईश्वर हूँ तो भी ऐसा समझते हैं कि यह पहले प्रकट नहीं थे अब प्रकट हुए हैं। अभिप्राय यह कि मेरे वास्तविक प्रभावको न समझनेके कारण वे ऐसा मानते हैं।'),
('shankaracharya-ht:source:7.25','Śaṅkarācārya','gita.7.25','hi','translation','।।7.25।।उनका वह अज्ञान किस कारणसे है सो बतलाते हैं तीनों गुणोंके मिश्रणका नाम योग है और वही माया है उस योगमायासे आच्छादित हुआ मैं समस्त प्राणिसमुदायके लिये प्रकट नहीं रहता हूँ अभिप्राय यह कि किन्हींकिन्हीं भक्तोंके लिये ही मैं प्रकट होता हूँ। इसलिये यह मूढ़ जगत् ( प्राणिसमुदाय ) मुझ जन्मरहित अविनाशी परमात्माको नहीं जानता।'),
('shankaracharya-ht:source:7.26','Śaṅkarācārya','gita.7.26','hi','translation','।।7.26।।जिस योगमायासे छिपे हुए मुझ परमात्माको संसार नहीं जानता वह योगमाया मेरी ही होनेके कारण मुझ मायापति ईश्वरके ज्ञानका प्रतिबन्ध नहीं कर सकती जैसे कि अन्य मायावी ( बाजीगर ) पुरुषोंकी माया भी उनके ज्ञानको ( आच्छादित नहीं करती ) इसलिये हे अर्जुन जो पूर्वमें हो चुके हैं उन प्राणियोंको एवं जो वर्तमान हैं और जो भविष्यमें होनेवाले हैं उन सब भूतोंको मैं जानता हूँ। परंतु मेरे शरणागत भक्तको छोड़कर मुझे और कोई भी नहीं जानता और मेरे तत्त्वको न जाननेके कारण ही ( अन्य जन ) मुझे नहीं भजते।'),
('shankaracharya-ht:source:7.27','Śaṅkarācārya','gita.7.27','hi','translation','।।7.27।।आपका तत्त्व जाननेमें ऐसा कौन प्रतिबन्धक है जिससे मोहित हुए सभी उत्पत्तिशील प्राणी आपको नहीं जान पाते यह जाननेकी इच्छा होनेपर कहते हैं इच्छा और द्वेष इन दोनोंसे जो उत्पन्न होता है उसका नाम इच्छाद्वेषसमुत्थ है उससे ( प्राणी मोहित होते हैं। ) वह कौन है ऐसी विशेष जिज्ञासा होनेपर यह कहते हैं द्वन्द्वोंके निमित्तसे होनेवाला जो मोह है उस द्वन्द्वमोहसे ( सब मोहित होते हैं )। शीत और उष्णकी भाँति परस्परविरुद्ध ( स्वभाववाले ) और सुखदुःख तथा उनके कारणोंमें रहनेवाले वे इच्छा और द्वेष ही यथासमय सब भूतप्राणियोंसे सम्बन्धयुक्त होकर द्वन्द्व नामसे कहे जाते हैं। सो ये इच्छा और द्वेष जब इस प्रकार सुखदुःख और उनके कारणकी प्राप्ति होनेपर प्रकट होते हैं तब वे सब भूतोंकी बुद्धिको अपने वशमें करके परमार्थतत्त्वविषयक ज्ञानकी उत्पत्तिका प्रतिबन्ध करनेवाले मोहको उत्पन्न करते हैं। जिसका चित्त इच्छाद्वेषरूप दोषोंके वशमें फँस रहा है उसको बाहरी विषयोंके भी यथार्थ तत्त्वका ज्ञान प्राप्त नहीं होता फिर उन दोनोंसे जिसकी बुद्धि आच्छादित हो रही है ऐसे मूढ़ पुरुषको अनेकों प्रतिबन्धोंवाले अन्तरात्माके सम्बन्धमें ज्ञान नहीं होता इसमें तो कहना ही क्या है इसलिये हे भारत अर्थात् भरतवंशमें उत्पन्न अर्जुन उस इच्छाद्वेषजन्य द्वन्द्वनिमित्तक मोहके द्वारा मोहित हुए समस्त प्राणी हे परंतप जन्मकालमें उत्पन्न होते ही मूढ़भावमें फँस जाते हैं। अभिप्राय यह है कि उत्पत्तिशील समस्त प्राणी मोहके वशीभूत हुए ही उत्पन्न होते हैं। ऐसा होनेके कारण द्वन्द्वमोहसे जिनका ज्ञान प्रतिबद्ध हो गया है वे मोहित हुए समस्त प्राणी अपने आत्मारूप मुझ ( परमात्मा ) को नहीं जानते और इसीलिये वे आत्मभावसे मुझे नहीं भजते।'),
('shankaracharya-ht:source:7.28','Śaṅkarācārya','gita.7.28','hi','translation','।।7.28।।तो फिर इस द्वन्द्वमोहसे छूटे हुए ऐसे कौनसे मनुष्य हैं जो आपको शास्त्रोक्त प्रकारसे आत्मभावसे भजते हैं इस अपेक्षित अर्थको दिखानेके लिये कहते हैं जिन पुण्यकर्मा पुरुषोंके पापोंका लगभग अन्त हो गया होता है अर्थात् जिनके कर्म पवित्र यानी अन्तःकरणकी शुद्धिके कारण होते हैं वे पुण्यकर्मा हैं ऐसे उपर्युक्त द्वन्द्वमोहसे मुक्त हुए वे दृढ़व्रती पुरुष मुझ परमात्माको भजते हैं। परमार्थतत्त्व ठीक इसी प्रकार है दूसरी प्रकार नहीं ऐसे निश्चित विज्ञानवाले पुरुष दृढ़व्रती कहे जाते हैं।'),
('shankaracharya-ht:source:7.29','Śaṅkarācārya','gita.7.29','hi','translation','।।7.29।।वे किसलिये भजते हैं सो कहते हैं जो पुरुष जरा और मृत्युसे छूटनेके लिये मुझ परमेश्वरका आश्रय लेकर अर्थात् मुझमें चित्तको समाहित करके प्रयत्न करते हैं वे जो परब्रह्म है उसको जानते हैं एवं समस्त अध्यात्म अर्थात् अन्तरात्मविषयकवस्तुको और अखिल समस्त कर्मको भी जानते हैं।'),
('shankaracharya-ht:source:7.30','Śaṅkarācārya','gita.7.30','hi','translation','।।7.30।।( इसी प्रकार ) जो मनुष्य मुझ परमेश्वरको साधिभूताधिदैव अर्थात् अधिभूत और अधिदैवके सहित जानते हैं एवं साधियज्ञ अर्थात् अधियज्ञके सहित भी जानते हैं वे निरुद्धचित्त योगी लोग मरणकालमें भी मुझे यथावत् जानते हैं।'),
('shankaracharya-ht:source:8.1','Śaṅkarācārya','gita.8.1','hi','translation','।।8.1।। ते ब्रह्म तद्विदुः कृत्स्नम् इत्यादि वचनोंसे ( पूर्वाध्यायमें ) भगवान्ने अर्जुनके लिये प्रश्नके बीजोंका उपदेश किया था अतः उन प्रश्नोंको पूछनेके लिये अर्जुन बोला --, हे पुरुषोत्तम वह ब्रह्मतत्त्व क्या है अध्यात्म क्या है कर्म क्या है अधिभूत किसको कहते हैं अधिदैव किसको कहते हैं हे मधुसूदन इस देहमें अधियज्ञ कौन है और कैसे है तथा संयतचित्तवाले योगियोंद्वारा आप मरणकालमें किस प्रकार जाने जा सकते हैं।'),
('shankaracharya-ht:source:8.2','Śaṅkarācārya','gita.8.2','hi','translation','।।8.2।। ते ब्रह्म तद्विदुः कृत्स्नम् इत्यादि वचनोंसे ( पूर्वाध्यायमें ) भगवान्ने अर्जुनके लिये प्रश्नके बीजोंका उपदेश किया था अतः उन प्रश्नोंको पूछनेके लिये अर्जुन बोला --, हे पुरुषोत्तम वह ब्रह्मतत्त्व क्या है अध्यात्म क्या है कर्म क्या है अधिभूत किसको कहते हैं अधिदैव किसको कहते हैं हे मधुसूदन इस देहमें अधियज्ञ कौन है और कैसे है तथा संयतचित्तवाले योगियोंद्वारा आप मरणकालमें किस प्रकार जाने जा सकते हैं।'),
('shankaracharya-ht:source:8.3','Śaṅkarācārya','gita.8.3','hi','translation','।।8.3।।इन प्रश्नोंका क्रमसे निर्णय करनेके लिये श्रीभगवान् बोले --, परम अक्षर ब्रह्म है अर्थात् हे गार्गि इस अक्षरके शासनमें ही यह सूर्य और चन्द्रमा धारण किये हुए स्थित हैं इत्यादि श्रुतियोंसे जिसका वर्णन किया गया है जो कभी नष्ट नहीं होता वह परमात्मा ही ब्रह्म है। परम विशेषणसे युक्त होनेके कारण यहाँ अक्षर शब्दसे ओमित्येकाक्षरं ब्रह्म इस वाक्यमें वर्णित ओंकारका ग्रहण नहीं किया गया है क्योंकि परम वह विशेषण निरतिशय अक्षर ब्रह्ममें ही अधिक सम्भव -- युक्ितयुक्त है। उसी परब्रह्मका जो प्रत्येक शरीरमें अन्तरात्मभाव है उसका नाम स्वभाव है वह स्वभाव ही अध्यात्म कहलाता है। अभिप्राय यह कि आत्मा यानी शरीरको आश्रय बनाकर जो अन्तरात्मभावसे उसमें रहनेवाला है और परिणाममें जो परमार्थ ब्रह्म ही है वही तत्त्व स्वभाव है उसे ही अध्यात्म कहते हैं अर्थात् वही अध्यात्म नामसे कहा जाता है। भूतभावउद्भवकर अर्थात् भूतोंकी सत्ता भूतभाव है। उसका उद्भव ( उत्पत्ति ) भूतभावोद्भव है उसको करनेवाला भूतभावोद्भवकर यानी भूतवस्तुको उत्पन्न करनेवाला ऐसा जो विसर्ग अर्थात् देवोंके उद्देश्यसे चरु पुरोडाश आदि ( हवन करने योग्य ) द्रव्योंका त्याग करना है वह त्यागरूप यज्ञ कर्म नामसे कहा जाता है इस बीजरूप यज्ञसे ही वृष्टि आदिके क्रमसे स्थावरजङ्गम समस्त भूतप्राणी उत्पन्न होते हैं।'),
('shankaracharya-ht:source:8.4','Śaṅkarācārya','gita.8.4','hi','translation','।।8.4।।जो प्राणिमात्रको आश्रित किये होता है उसका नाम अधिभूत है। वह कौन है क्षर -- जो कि क्षय होता है ऐसा विनाशी भाव यानी जो कुछ भी उत्पत्तिशील पदार्थ हैं वे सबकेसब अधिभूत हैं। पुरुष अर्थात् जिससे यह सब जगत् परिपूर्ण है अथवा जो शरीररूप पुरमें रहनेवाला होनेसे पुरुष कहलाता है वह सब प्राणियोंके इन्द्रियादि करणोंका अनुग्राहक सूर्यलोकमें रहनेवाला हिरण्यगर्भ अधिदैवत है। यज्ञ ही विष्णु है इस श्रुतिके अनुसार सब यज्ञोंका अधिष्ठाता जो विष्णुनामक देवता है वह अधियज्ञ है। हे देहधारियोंमें श्रेष्ठ अर्जुन इस देहमें जो यज्ञ है उसका अधिष्ठाता वह विष्णुरूप अधियज्ञ मैं ही हूँ। यज्ञ शरीरसे ही सिद्ध होता है अतः यज्ञका शरीरसे नित्य सम्बन्ध है इसलिये वह शरीरमें रहनेवाला माना जाता है।'),
('shankaracharya-ht:source:8.5','Śaṅkarācārya','gita.8.5','hi','translation','।।8.5।।और जो पुरुष अन्तकालमें -- मरणकालमें मुझ परमेश्वर -- विष्णुका ही स्मरण करता हुआ शरीर,छोड़कर जाता है वह मेरे भावको अर्थात् विष्णुके परम तत्त्वको प्राप्त होता है। इस विषयमें प्राप्त होता है या नहीं ऐसा कोई संशय नहीं है।'),
('shankaracharya-ht:source:8.6','Śaṅkarācārya','gita.8.6','hi','translation','।।8.6।।केवल मेरे विषयमें ही यह नियम नहीं है किंतु --, हे कुन्तीपुत्र प्राणवियोगके समय ( यह जीव ) जिसजिस भी भावका अर्थात् ( जिस किसी भी ) देवताविशेषका चिन्तन करता हुआ शरीर छोड़ता है उस भावसे भावित हुआ वह पुरुष सदा उस स्मरण किये हुए भावको ही प्राप्त होता है अन्यको नहीं। उपास्य देवविषयक भावनाका नाम तद्भाव है वह जिसने भावित यानी बारंबार चिन्तन करनेके द्वारा अभ्यस्त किया हो उसका नाम तद्भावभावित है ऐसा होता हुआ ( उसीको प्राप्त होता है )।'),
('shankaracharya-ht:source:8.7','Śaṅkarācārya','gita.8.7','hi','translation','।।8.7।।क्योंकि इस प्रकार अन्तकालकी भावना ही अन्य शरीरकी प्राप्तिका कारण है --, इसलिये तू हर समय मेरा स्मरण कर और शास्त्राज्ञानुसार स्वधर्मरूप युद्ध भी कर। इस प्रकार मुझ वासुदेवमें जिसके मनबुद्धि अर्पित हैं ऐसा तू मुझमें अर्पित किये हुए मनबुद्धिवाला होकर मुझको ही अर्थात् मेरे यथाचिन्तित स्वरूपको ही प्राप्त हो जायगा इसमें संशय नहीं है।'),
('shankaracharya-ht:source:8.8','Śaṅkarācārya','gita.8.8','hi','translation','।।8.8।।तथा --, हे पार्थ अभ्यासयोगयुक्त अनन्यगामी चित्तद्वारा अर्थात् चित्तसमर्पणके आश्रयभूत मुझ एक परमात्मामें ही विजातीय प्रतीतियोंके व्यवधानसे रहित तुल्य प्रतीतिकी आवृत्तिका नाम अभ्यास है वह अभ्यास ही योग है ऐसे अभ्यासरूप योगसे युक्त उस एक ही आलम्बनमें लगा हुआ विषयान्तरमें न जानेवाला जो योगीका चित्त है उस चित्तद्वारा शास्त्र और आचार्यके उपदेशानुसार चिन्तन करता हुआ योगी परम निरतिशय -- दिव्य पुरुषको -- जो आकाशस्थ सूर्यमण्डलमें परम पुरुष है -- उसको प्राप्त होता है।'),
('shankaracharya-ht:source:8.9','Śaṅkarācārya','gita.8.9','hi','translation','।।8.9।।किन लक्षणोंसे युक्त परम पुरुषको ( योगी ) प्राप्त होता है इसपर कहते हैं --, जो पुरुष भूत भविष्यत् और वर्तमानको जाननेवाले -- सर्वज्ञ पुरातन सम्पूर्ण संसारके शासक और अणुसे भी अणु यानी सूक्ष्मसे भी सूक्ष्मतर परमात्माका जो भी सम्पूर्ण कर्मफलका विधायक अर्थात् विचित्ररूपसे विभाग करके सब प्राणियोंको उनके कर्मोंका फल देनेवाला है तथा अचिन्त्यस्वरूप अर्थात् जिसका स्वरूप नियत और विद्यमान होते हुए भी किसीके द्वारा चिन्तन न किया जा सके ऐसा है एवं सूर्यके समान वर्णवाला अर्थात् सूर्यके समान नित्य चेतनप्रकाशमय वर्णवाला है और अज्ञानरूप मोहमय अन्धकारसे सर्वथा अतीत है उसका बारम्बार स्मरण करता है। ( वह ) उसका स्मरण करता हुआ उसीको प्राप्त होता है इस प्रकार पूर्वश्लोकसे सम्बन्ध है।'),
('shankaracharya-ht:source:8.10','Śaṅkarācārya','gita.8.10','hi','translation','।।8.10।।तथा --, ( जो योगी ) अन्त समय -- मृत्युकालमें भक्ति और योगबलसे युक्त हुआ -- अर्थात् भजनका नाम भक्ति है उससे युक्त हुआ और समाधिजनित संस्कारोंके संग्रहसे उत्पन्न हुई चित्तस्थिरताका नाम योगबल है उससे भी युक्त हुआ चञ्चलतारहित -- अचल मनसे पहले हृदयकमलमें चित्तको स्थिर करके फिर ऊपरकी ओर जानेवाली नाड़ीद्वारा चित्तकी प्रत्येक भूमिको क्रमसे जय करता हुआ भ्रुकुटिके मध्यमें प्राणोंको स्थापन करके भली प्रकार सावधान हुआ ( परमात्मस्वरूपका चिन्तन करता है ) वह ऐसा बुद्धिमान् योगी कविं पुराणम् इत्यादि लक्षणोंवाले उस दिव्य -- चेतनात्मक परम पुरुषको प्राप्त होता है।'),
('shankaracharya-ht:source:8.11','Śaṅkarācārya','gita.8.11','hi','translation','।।8.11।।फिर भी भगवान् आगे बतलाये जानेवाले उपायोंसे प्राप्त होनेयोग्य और वेदविदो वदन्ति इत्यादि विशेषणोंद्वारा वर्णन किये जानेयोग्य ब्रह्मका प्रतिपादन करते हैं --, हे गार्गि ब्राह्मणलोग उसी इस अक्षरका वर्णन किया करते हैं इस श्रुतिके अनुसार वेदके परम अर्थको,जाननेवाले विद्वान् जिस अक्षरका अर्थात् जिसका कभी नाश न हो ऐसे परमात्माका वह न स्थूल है न सूक्ष्म है इस प्रकार सब विशेषोंका निराकरण करके वर्णन किया करते हैं तथा जिनकी आसक्ित नष्ट हो चुकी है ऐसे वीतराग यत्नशील संन्यासी यथार्थ ज्ञानकी प्राप्ति हो जानेपर जिसमें प्रविष्ट होते हैं। एवं जिस अक्षरको जानना चाहनेवाले ( साधक ) गुरुकुलमें ब्रह्मचर्यव्रतका पालन किया करते हैं वह अक्षरनामक पद अर्थात् प्राप्त करनेयोग्य स्थान मैं तुझे संग्रहसे -- संक्षेपसे बतलाता हूँ। संग्रह संक्षेपको कहते हैं। सत्यकामके यह पूछनेपर कि हे भगवन् मनुष्योंमेंसे वह जो कि मरणपर्यन्त ओंकारका भली प्रकार ध्यान करता रहता है वह उस साधनसे किस लोकको जीत लेता है पिप्पलाद ऋषिने कहा कि हे सत्यकाम यह ओंकार ही निःसन्देह परब्रह्म है और यही अपर ब्रह्म भी है। इस प्रकार प्रसङ्ग आरम्भ करके फिर जो कोई इस तीन मात्रावाले ओम् इस अक्षरद्वारा परम पुरुषकी उपासना करता रहता है। इत्यादि वचनोंसे ( प्रश्नोपनिषद्में ) तथा जो धर्मसे विलक्षण है और अधर्मसे भी विलक्षण है इस प्रकार प्रसङ्ग आरम्भ करके फिर समस्त वेद जिस परमपदका वर्णन कर रहे हैं समस्त तप जिसको बतला रहे हैं तथा जिस परमपदको चाहनेवाले ब्रह्मचर्यका पालन किया करते हैं वह परमपद संक्षेपसे तुझे बतलाऊँगा वह है ओम् ऐसा यह ( एक अक्षर )। इत्यादि वचनोंसे ( कठोपनिषद्में )। परब्रह्मका वाचक होनेसे एवं प्रतिमाकी भाँति उसका प्रतीक ( चिह्न ) होनेसे मन्द और मध्यम बुद्धिवाले साधकोंके लिये जो परब्रह्मपरमात्माकी प्राप्तिका साधनरूप माना गया है उस ओंकारकी कालान्तरमें मुक्तिरूप फल देनेवाली जो उपासना बतलायी गयी है,'),
('shankaracharya-ht:source:8.12','Śaṅkarācārya','gita.8.12','hi','translation','।।8.12।।यहाँ भी कविं पुराणमनुशासितारम् यदक्षरं वेदविदो वदन्ति इस प्रकार प्रतिपादन किये हुए परब्रह्मकी प्राप्तिका पूर्वोक्तरूपसे उपायभूत जो ओंकार है उसकी कालान्तरमें मुक्ितरूप फल देनेवाली वही उपासना योगधारणासहित कहनी है तथा उसके प्रसङ्ग और अनुप्रसङ्गमें आनेवाली बातें भी कहनी हैं। इसलिये आगेका ग्रन्थ आरम्भ किया जाता है --, समस्त द्वारोंका अर्थात् विषयोंकी उपलब्धिके द्वाररूप जो समस्त इन्द्रियगोलक हैं उन सबका संयम करके एवं मनको हृदयकमलमें निरुद्ध करके अर्थात् संकल्पविकल्पसे रहित करके फिर वशमें किये हुए मनके सहारेसे हृदयसे ऊपर जानेवाली नाडीद्वारा ऊपर चढ़कर अपने प्राणोंको मस्तकमें स्थापन करके योगधारणाको धारण करनेके लिये प्रवृत्त हुआ साधक ( परमगतिको प्राप्त होता है इस प्रकार अगले श्लोकसे सम्बन्ध है )।'),
('shankaracharya-ht:source:8.13','Śaṅkarācārya','gita.8.13','hi','translation','।।8.13।।उसी जगह ( प्राणोंको ) स्थिर रखते हुए --, ओम् इस एक अक्षररूप ब्रह्मका अर्थात् ब्रह्मके स्वरूपका लक्ष्य करानेवाले ओंकारका उच्चारश करता हुआ और उसके अर्थरूप मुझ ईश्वररूपका चिन्तन करता हुआ जो पुरुष शरीरको छोड़कर जाता है अर्थात् मरता है वह इस प्रकार शरीरको छोड़कर जानेवाला परम गतिको पाता है। यहाँ त्यजन्देहम् यह विशेषण मरण का लक्ष्य करानेके लिये है। अभिप्राय यह कि देहके त्यागसे ही आत्माका मरण है स्वरूपके नाशसे नहीं।'),
('shankaracharya-ht:source:8.14','Śaṅkarācārya','gita.8.14','hi','translation','।।8.14।।तथा --, अनन्यचित्तवाला अर्थात् जिसका चित्त अन्य किसी भी विषयका चिन्तन नहीं करता ऐसा जो योगी सर्वदा निरन्तर प्रतिदिन मुझ परमेश्वरका स्मरण किया करता है। यहाँ सततम् इस शब्दसे निरन्तरताका कथन है और नित्यशः इस शब्दसे दीर्घकालका कथन है अतः यह समझना चाहिये कि छः महीने या एक वर्ष ही नहीं किंतु जीवनपर्यन्त जो निरन्तर मेरा स्मरण करता है। हे पार्थ उस नित्यसमाधिस्थ योगीके लिये मैं सुलभ हूँ। अर्थात् उसको मैं अनायास प्राप्त हो जाता हूँ। जब कि यह बात है इसलिये ( मनुष्यको ) अनन्य चित्तवाला होकर सदा ही मुझमें समाहितचित्त रहना चाहिये।'),
('shankaracharya-ht:source:8.15','Śaṅkarācārya','gita.8.15','hi','translation','।।8.15।।आपके सुलभ हो जानेसे क्या होगा इसपर कहते हैं कि मेरी सुलभ प्राप्तिसे जो होता है वह सुन --, मुझ ईश्वरको पाकर अर्थात् मेरे भावको प्राप्त करके फिर ( वे महापुरुष ) पुनर्जन्मको नहीं पाते। किस प्रकारके पुनर्जन्मको नहीं पाते यह स्पष्ट करनेके लिये उसके विशेषण बतलाते हैं -- आध्यात्मिक आदि तीनों प्रकारके दुःखोंका जो स्थान -- आधार है अर्थात् समस्त दुःख जिसमें रहते हैं केवल दुःखोंका स्थान ही नहीं जो अशाश्वत भी है अर्थात् जिसका स्वरूप स्थिर नहीं है ऐसे पुनर्जन्मको मोक्षरूप परम श्रेष्ठ सिद्धिको प्राप्त हुए महात्मा -- संन्यासीगण नहीं पाते। परंतु जो मुझे प्राप्त नहीं होते वे फिर संसारमें आते हैं।'),
('shankaracharya-ht:source:8.16','Śaṅkarācārya','gita.8.16','hi','translation','।।8.16।।तो क्या आपके सिवा अन्य स्थानको प्राप्त होनेवाले पुरुष फिर संसारमें आते हैं इसपर कहा जाता है --, जिसमें प्राणी उत्पन्न होते और निवास करते हैं उसका नाम भुवन है ब्रह्मलोक ब्रह्मभुवन कहलाता है। हे अर्जुन ब्रह्मलोकपर्यन्त अर्थात् ब्रह्मलोकसहित समस्त लोक पुनरावर्ती हैं अर्थात् जिनमें जाकर फिर संसारमें जन्म लेना पड़े ऐसे हैं। परंतु हे कुन्तीपुत्र केवल एक मुझे प्राप्त होनेपर फिर पुनर्जन्म -- पुनरुत्पत्ति नहीं होती।'),
('shankaracharya-ht:source:8.17','Śaṅkarācārya','gita.8.17','hi','translation','।।8.17।।ब्रह्मलोकसहित समस्त लोक पुनरावर्ती किस कारणसे हैं कालसे परिच्छिन्न हैं इसलिये कालसे परिच्छिन्न कैसे हैं --, ब्रह्मा -- प्रजापति अर्थात् विराट्के एक दिनको एक सहस्रयुगकी अवधिवाला अर्थात् जिसका एक सहस्रयुगमें अन्त हो ऐसा समझते हैं। तथा ब्रह्माकी रात्रिको भी सहस्रयुगकी अवधिवाली अर्थात् दिनके बराबर ही समझते हैं। ऐसा कौन समझते हैं सो कहते हैं -- वे दिन और रातके तत्त्वको जाननेवाले अर्थात् कालके परिमाणको जाननेवाले योगीजन ऐसा जानते हैं। इस प्रकार कालसे परिच्छिन्न होनेके कारण वे सभी लोक पुनरावृत्तिवाले हैं।'),
('shankaracharya-ht:source:8.18','Śaṅkarācārya','gita.8.18','hi','translation','।।8.18।।प्रजापतिके दिनमें और रात्रिमें जो कुछ होता है उसका वर्णन किया जाता है --, दिनके आरम्भकालका नाम अहरागम है ब्रह्माके दिनके आरम्भकालमें अर्थात् ब्रह्माके प्रबोधकालमें अव्यक्तसे -- प्रजापतिकी निद्रावस्थासे समस्त व्यक्तियाँ -- स्थावरजङ्गमरूप समस्त प्रजाएँ उत्पन्न होती हैं -- प्रकट होती हैं। जो व्यक्तप्रकट होती है उसका नाम व्यक्ति है। तथा रात्रिके आनेपर -- ब्रह्माके शयन करनेके समस्त उस पूर्वोक्त अव्यक्त नामक प्रजापतिकी निद्रावस्थामें ही समस्त प्राणी लीन हो जाते हैं।,'),
('shankaracharya-ht:source:8.19','Śaṅkarācārya','gita.8.19','hi','translation','।।8.19।।न किये कर्मोंका फल मिलना और किये हुए कर्मोंका फल न मिलना इस दोषका परिहार करनेके लिये बन्धन और मुक्तिका मार्ग बतलानेवाले शास्त्रवाक्योंकी सफलता दिखानेके लिये और अविद्यादि पञ्चक्लेशमूलक कर्मसंस्कारोंके वशमें पड़कर पराधीन हुआ प्राणीसमुदाय बारंबार उत्पन्न होहोकर लय हो जाता है -- इस प्रकारके कथनसे संसारमें वैराग्य दिखलानेके लिये यह कहते हैं --, जो पहले कल्पमें था वही -- दूसरा नहीं -- यह स्थावरजङ्गमरूप भूतोंका समुदाय ब्रह्माके दिनके आरम्भमें बारंबार उत्पन्न होहोकर दिनकी समाप्ति और रात्रिका प्रवेश होनेपर पराधीन हुआ ही बारंबार लय होता जाता है और फिर उसी प्रकार विवश होकर दिनके प्रवेशकालमें पुनः उत्पन्न होता जाता है।'),
('shankaracharya-ht:source:8.20','Śaṅkarācārya','gita.8.20','hi','translation','।।8.20।।जिस अक्षरका पहले प्रतिपादन किया था उसकी प्राप्तिका उपाय ओमित्येकाक्षरं ब्रह्म इत्यादि कथनसे बतला दिया। अब उसी अक्षरके स्वरूपका निर्देश करनेकी इच्छासे यह बतलाया जाता है कि इस योगमार्गद्वारा अमुक वस्तु मिलती है --, तु शब्द यहाँ आगे वर्णन किये जानेवाले अक्षरकी उस पूर्वोक्त अव्यक्तसे विलक्षणता दिखलानेके लिये है। ( वह अव्यक्त ) भाव यानी अक्षरनामक परब्रह्म परमात्मा अत्यन्त भिन्न है। किससे उस पहले कहे हुए अव्यक्त से। भिन्न होनेपर भी किसी प्रकार समानता हो सकती है इस शंकाकी निवृत्तिके लिये कहते हैं कि वह इन्द्रियोंसे प्रत्यक्ष न होनेवाला अव्यक्तभाव अन्य -- दूसरा है अर्थात् सर्वथा विलक्षण है। उससे पर है ऐसा कहा सो किससे पर है वह उस पूर्वोक्त भूतसमुदायके बीजभूत अविद्यारूप अव्यक्तसे परे है। ऐसा जो सनातन भाव अर्थात् सदासे होनेवाला भाव है वह ब्रह्मादि समस्त प्राणियोंका नाश होनेपर भी नष्ट नहीं होता।'),
('shankaracharya-ht:source:8.21','Śaṅkarācārya','gita.8.21','hi','translation','।।8.21।।जो वह अव्यक्त अक्षर ऐसे कहा गया है उसी अक्षर नामक अव्यक्तभावको परम -- श्रेष्ठ गति कहते हैं। जिस परम भावको प्राप्त होकर ( मनुष्य ) फिर संसारमें नहीं लौटते वह मेरा परम श्रेष्ठ स्थान है अर्थात् मुझ विष्णुका परमपद है।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:8.22','Śaṅkarācārya','gita.8.22','hi','translation','।।8.22।।उस परमधामकी प्राप्तिका उपाय बतलाया जाता है --, शरीररूप पुरमें शयन करनेसे या सर्वत्र परिपूर्ण होनेसे परमात्माका नाम पुरुष है। हे पार्थ वह निरतिशय परमपुरुष जिससे पर ( सूक्ष्मश्रेष्ठ ) अन्य कुछ भी नहीं है जिस पुरुषके अन्तर्गत समस्त कार्यरूप भूत स्थित हैं -- क्योंकि कार्य कारणके अन्तर्वर्ती हुआ करता है -- और जिस पुरुषसे यह सारा संसार आकाशसे घट आदिकी भाँति व्याप्त है। ऐसा परमात्मा अनन्य भक्ितसे अर्थात् आत्मविषयक ज्ञानरूप भक्ितसे प्राप्त होने योग्य है।,'),
('shankaracharya-ht:source:8.23','Śaṅkarācārya','gita.8.23','hi','translation','।।8.23।।जिन्होंने ओंकारमें ब्रह्मबुद्धि सम्पादन की है जिन्हें कालान्तरमें मुक्ति मिलनेवाली है तथा यहाँ जिनका प्रकरण चल रहा है उन योगियोंकी ब्रह्मप्राप्तिके लिये आगेका मार्ग बताना चाहिये। अतः विवक्षित अर्थको बतलानेके लिये ही यत्र काले इत्यादि अगले श्लोक कहे जाते हैं। यहाँ पुनरावर्ती मार्गका वर्णन दूसरे मार्गकी स्तुति करनेके लिये किया गया है --, यत्र काले इस पदका व्यवधानयुक्त प्रयाताः इस अगले पदसे सम्बन्ध है। जिस कालमें अनावृत्तिको -- अपुनर्जन्मको और जिस कालमें आवृत्तिको -- उससे विपरीत पुनर्जन्मको योगी लोग पाते हैं। योगिनः इस पदसे कर्म करनेवाले कर्मी लोग भी योगी कहे गये हैं क्योंकि कर्मयोगेन योगिनाम् इस विशेषणसे कर्मी भी किसी गुणविशेषसे योगी हैं। तात्पर्य यह है कि अर्जुन जिस कालमें मरे हुए योगी लोग पुनर्जन्मको नहीं पाते और जिस कालमें मरे हुए लोग पुनर्जन्म पाते हैं मैं अब उस कालका वर्णन करता हूँ।'),
('shankaracharya-ht:source:8.24','Śaṅkarācārya','gita.8.24','hi','translation','।।8.24।।यहाँ अग्नि कालाभिमानी देवताका वाचक है तथा ज्योति भी कालाभिमानी देवताका ही वाचक है अथवा अग्नि और ज्योति नामवाले दोनों प्रसिद्ध वैदिक देवता ही हैं। जिस वनमें आमके पेड़ अधिक होते हैं उसको जैसे आमका वन कहते हैं उसी प्रकार यहाँ कालाभिमानी देवताओंका वर्णन अधिक होनेसे यत्र काले तं कालम् इत्यादि कालवाचक शब्दोंका प्रयोग किया गया है। ( अभिप्राय यह कि जिस मार्गमें अग्निदेवता ज्योतिदेवता ) दिनका देवता शुक्लपक्षका देवता और उत्तरायणके छः महीनोंका देवता है उस मार्गमें ( अर्थात् उपर्युक्त देवताओंके अधिकारमें ) मरकर गये हुए ब्रह्मवेत्ता यानी ब्रह्मकी उपासनामें तत्पर हुए पुरुष क्रमसे ब्रह्मको प्राप्त होते हैं। यहाँ उत्तरायण मार्ग भी देवताका ही वाचक हैं क्योंकि अन्यत्र ( ब्रह्मसूत्रमें ) भी यही न्याय माना गया है। जो पूर्ण ज्ञाननिष्ठ सद्योमुक्ितके पात्र होते हैं उनका आनाजाना कहीं नहीं होता श्रुति भी कहती है उसके प्राण निकलकर कहीं नहीं जाते। वे तो ब्रह्मसंलीनप्राण अर्थात् ब्रह्ममय -- ब्रह्मरूप ही हैं।'),
('shankaracharya-ht:source:8.25','Śaṅkarācārya','gita.8.25','hi','translation','।।8.25।।जिस मार्गमें धूम और रात्रि है अर्थात् धूमाभिमानी और रात्रिअभिमानी देवता हैं तथा कृष्णपक्ष अर्थात् कृष्णपक्षका देवता है एवं दक्षिणायनके छः महीने हैं अर्थात् पूर्ववत् दक्षिणायन मार्गाभिमानी देवता है उस मार्गमें ( उन उपर्युक्त देवताओंके अधिकारमें मरकर ) गया हुआ योगी अर्थात् इष्टपूर्त आदि कर्म करनेवाला कर्मी चन्द्रमाकी ज्योतिको अर्थात् कर्मफलको प्राप्त होकर -- भोगकर उस कर्मफलका क्षय होनेपर लौट आता है।'),
('shankaracharya-ht:source:8.26','Śaṅkarācārya','gita.8.26','hi','translation','।।8.26।।शुक्ल और कृष्ण -- ये दो मार्ग अर्थात् जिसमें ज्ञानका प्रकाश है -- वह शुक्ल और जिसमें उसका अभाव है वह कृष्ण -- ऐसे ये दोनों मार्ग जगत्के लिये नित्य -- सदासे माने गये हैं क्योंकि जगत् नित्य है। यहाँ जगत्शब्दसे जो ज्ञानी और कर्मी उपर्युक्त गतिके अधिकारी हैं उन्हींको समझना चाहिये क्योंकि सारे संसारके लिये यह गति सम्भव नहीं है। उन दोनों मार्गोंमेंसे एक -- शुक्लमार्गसे गया हुआ तो फिर लौटता नहीं है और दूसरे मार्गसे गया हुआ लौट आता है।'),
('shankaracharya-ht:source:8.27','Śaṅkarācārya','gita.8.27','hi','translation','।।8.27।।हे पार्थ इन उपर्युक्त दोनों मार्गोंको इस प्रकार जाननेवाला कि एक पुनर्जन्मरूप संसारको देनेवाला है और दूसरा मोक्षका कारण है कोई भी योगी मोहित नहीं होता। इसलिये हे अर्जुन तू सब समय योगयुक्त हो अर्थात् समाधिस्थ हो।'),
('shankaracharya-ht:source:8.28','Śaṅkarācārya','gita.8.28','hi','translation','।।8.28।।योगका माहात्म्य सुन --, इनको जानकर अर्थात् इन सात प्रश्नोंके निर्णयद्वारा कहे हुए रहस्यको यथार्थ समझकर और उसका अनुष्ठान करके योगी पुरुष भलीभाँति पढ़े हुए वेद श्रेष्ठ गुणोंसहित सम्पादन किये हुए यज्ञ भली प्रकार किये हुए तप और यथार्थ पात्रको दिये हुए दान इन सबका शास्त्रोंने जो पुण्यफल बतलाया है उस सबको अतिक्रम कर जाता है और आदिमें होनेवाले सबके कारणरूप परम श्रेष्ठ ऐश्वरपदको अर्थात् ब्रह्मको पा लेता है।'),
('shankaracharya-ht:source:9.1','Śaṅkarācārya','gita.9.1','hi','translation','।।9.1।।वहाँ (यह शङ्का होती है कि ) क्या इस प्रकार साधन करनेसे ही मोक्षप्राप्तिरूप फल मिलता है अन्य किसी प्रकारसे नहीं मिलता इस शङ्काको निवृत्त करनेकी इच्छासे श्रीभगवान् बोले --, जो ब्रह्मज्ञान आगे कहा जायगा और जो कि पूर्वके अध्यायोंमें भी कहा जा चुका है? उसको बुद्धिके सामने रखकर यहाँ इदम् शब्दका प्रयोग किया है। तु शब्द अन्यान्य ज्ञानोंसे इसे अलग करके विशेषतासे लक्ष्य करानेके लिये है। यही यथार्थ ज्ञान साक्षात् मोक्षप्राप्तिका साधन है। जो कि सब कुछ वासुदेव ही है आत्मा ही यह समस्त जगत् है ब्रह्म अद्वितीय एक ही है इत्यादि श्रुतिस्मृतियोंसे दिखलाया गया है? ( इसके अतिरिक्त ) और कोई ( मोक्षका साधन ) नहीं है। जो इससे विपरीत जानते हैं वे अपनेसे भिन्न अपना स्वामी माननेवाले मनुष्य विनाशशील लोकोंको प्राप्त होते हैं इत्यादि श्रुतियोंसे भी यही सिद्ध होता है। तुझ असूयारहित भक्तसे मैं यह अति गोपनीय विषय कहूँगा। वह क्या है ज्ञान। कैसा ज्ञान विज्ञानसहित अर्थात् अनुभवसहित ज्ञान। जिस ज्ञानको जानकर अर्थात् पाकर तू संसाररूप बन्धनसे मुक्त हो जायगा।'),
('shankaracharya-ht:source:9.2','Śaṅkarācārya','gita.9.2','hi','translation','।।9.2।।वह ज्ञान --, अतिशय प्रकाशयुक्त होनेके कारण समस्त विद्याओंका राजा है। ब्रह्मविद्या सब विद्याओंमें अतिशय देदीप्यमान है यह प्रसिद्ध ही है। तथा ( यह ज्ञान ) समस्त गुप्त रखनेयोग्य भावोंका भी राजा है। एवं यह बड़ा पवित्र और उत्तम भी है? अर्थात् सम्पूर्ण पवित्र करनेवालोंको पवित्र करनेवाला यह ब्रह्मज्ञान सबसे उत्कृष्ट है। जो अनेक सहस्र जन्मोंमें इकट्ठे हुए पुण्य पापादि कर्मोंको क्षणमात्रमें मूलसहित भस्म कर देता है उसकी पवित्रताका क्या कहना है साथ ही यह ज्ञान प्रत्यक्ष अनुभवमें आनेवाला है? अर्थात् सुख आदिकी भाँति जिसका प्रत्यक्ष अनुभव हो सके? ऐसा है। अनेक गुणोंसे युक्त वस्तुका भी धर्मसे विरोध देखा जाता है? परंतु आत्मज्ञान उनकी तरह धर्मविरोधी नहीं है बल्कि धर्म्य -- धर्ममय है अर्थात् धर्मसे युक्त है। ऐसा पदार्थ भी दुःसम्पाद्य ( प्राप्त करनेमें बड़ा कठिन ) हो सकता है। इसलिये कहते हैं कि वह ज्ञान रत्नोंके विवेकविज्ञानकी भाँति समझनेमें बड़ा सुगम है। परंतु संसारमें अल्प परिश्रमसे सुखपूर्वक सम्पन्न होनेवाले कर्मोंका अल्प फल और कठिनतासे सम्पन्न होनेवाले कर्मोंका महान् फल देखा गया है? अतः यह ज्ञान भी सुगमतासे सम्पन्न होनेवाला होनेके कारण अपने फलका क्षय होनेपर क्षीण हो जायगा? ऐसी शङ्का प्राप्त होनेपर कहते हैं -- यह ज्ञान अव्यय है अर्थात् कर्मोंकी भाँति फलनाशके द्वारा इसका नाश नहीं होता। अतः यह आत्मज्ञान श्रद्धा करने योग्य है।'),
('shankaracharya-ht:source:9.3','Śaṅkarācārya','gita.9.3','hi','translation','।।9.3।।परंतु जो --, इस आत्मज्ञानरूप धर्मकी श्रद्धासे रहित हैं? अर्थात् इसके स्वरूपमें और फलमें आस्तिक भावसे रहित हैं -- नास्तिक हैं वे असुरोंके सिद्धान्तोंका अनुवर्तन करनेवाले देहमात्रको ही आत्मा समझनेवाले एवं पापकर्म करनेवाले इन्द्रियलोलुप मनुष्य? हे परंतप मुझ परमेश्वरको प्राप्त न होकर -- मेरी प्राप्तिकी तो उनके लिये आशङ्का भी नहीं हो सकती? मेरी प्राप्तिके मार्गकी साधनरूप भेदभक्तिको भी प्राप्त न होकर निश्चय ही घूमते रहते हैं। कहाँ घूमते रहते हैं मृत्युयुक्त संसारके मार्गमें? अर्थात् जो संसार मृत्युयुक्त है उस मृत्युसंसारके नरक और पशुपक्षी आदि योनियोंकी प्राप्तिरूप मार्गमें वे बारंबार घूमते रहते हैं।'),
('shankaracharya-ht:source:9.4','Śaṅkarācārya','gita.9.4','hi','translation','।।9.4।।इस प्रकार ज्ञानकी प्रशंसाद्वारा अर्जुनको सम्मुख करके कहते हैं --, मुझ अव्यक्तरूप परमात्माद्वारा अर्थात् मेरा जो परमभाव है? जिसका स्वरूप प्रत्यक्ष नहीं है यानी मन? बुद्धि और इन्द्रियोंका विषय नहीं है? ऐसे मुझ अव्यक्तमूर्तिद्वारा यह समस्त जगत् व्याप्त है -- परिपूर्ण है। उस अव्यक्तस्वरूप मुझ परमात्मामें ब्रह्मासे लेकर स्तम्बपर्यन्त समस्त प्राणी स्थित हैं। क्योंकि कोई भी निर्जीव प्राणी व्यवहारके योग्य नहीं समझा जाता। अतः वे सब मुझमें स्थित हैं अर्थात् मुझ परमात्मासे ही आत्मवान् हो रहे हैं? इसलिये मुझमें स्थित कहे जाते हैं। उन भूतोंका वास्तविक स्वरूप मैं ही हूँ इसलिये अज्ञानियोंको ऐसी प्रतीति होती है कि मैं उनमें स्थित हूँ? अतः कहता हूँ कि मैं उन भूतोंमें स्थित नहीं हूँ। क्योंकि साकार वस्तुओंकी भाँति मुझमें संसर्गदोष नहीं है। इसलिये मैं बिना संसर्गके सूक्ष्मभावसे आकाशके भी अन्तर्व्यापी हूँ। सङ्गहीन वस्तु कहीं भी आधेयभावसे स्थित नहीं होती? यह प्रसिद्ध है।'),
('shankaracharya-ht:source:9.5','Śaṅkarācārya','gita.9.5','hi','translation','।।9.5।।मैं असंसर्गी हूँ? इसलिये --, ( वास्तवमें ) ब्रह्मादि सब प्राणी भी मुझमें स्थित नहीं हैं? तू मेरे इस ईश्वरीय योग -- युक्ति -- घटनाको देख? अर्थात् मुझ ईश्वरके योगको यानी यथार्थ आत्मतत्त्वको समझ। संसर्गरहित आत्मा कहीं भी लिप्त नहीं होता यह श्रुति भी संसर्गरहित होनेके कारण ( आत्माकी ) निर्लेपता दिखलाती है। यह और भी आश्चर्य देख कि भूतभावन मेरा आत्मा संसर्गरहित होकर भी भूतोंका भरणपोषण करता रहता है परंतु भूतोमें स्थित नहीं है। क्योंकि परमात्माका भूतोंमें स्थित होना सम्भव नहीं? यह बात उपर्युक्त न्यायसे स्पष्ट दिखलायी जा चुकी है। पू0 -- ( जब कि आत्मा अपनेसे कोई अन्य वस्तु ही नहीं है ) तो मेरा आत्मा यह कैसे कहा जाता है उ0 -- लौकिक बुद्धिका अनुकरण करते हुए देहादि संघातको आत्मासे अलग करके फिर उसमें अहंकारका अध्यारोप करके मेरा आत्मा ऐसा कहते हैं? आत्मा अपने आपसे भिन्न है ऐसा समझकर लोगोंकी भाँति अज्ञानपूर्वक ऐसा नहीं कहते। जो भूतोंको प्रकट करता है -- उत्पन्न करता है या बढ़ाता है उसको भूतभावन कहते हैं।'),
('shankaracharya-ht:source:9.6','Śaṅkarācārya','gita.9.6','hi','translation','।।9.6।।उपर्युक्त दो श्लोकोंद्वारा कहे हुए अर्थको दृष्टान्तसे सिद्ध करते हुए कहते हैं --, लोकमें जैसे ( यह प्रसिद्ध है ) सब जगह विचरनेवाला परमाणमें अति महान् वायु सदा आकाशमें ही स्थित है? वैसे ही आकाशके समान सर्वत्र परिपूर्ण मुझ परमात्मामें समस्त भूत निर्लिप्तभावसे स्थित हैं? ऐसा तू जान।'),
('shankaracharya-ht:source:9.7','Śaṅkarācārya','gita.9.7','hi','translation','।।9.7।।इस प्रकार जगत्के स्थितिकालमें? आकाशमें वायुकी भाँति? मुझमें स्थित जो समस्त भूत हैं वे --, सम्पूर्ण प्राणी? हे कुन्तीपुत्र प्रलयकालमें मेरी त्रिगुणमयी -- अपरानिकृष्ट प्रकृतिको प्राप्त हो जाते हैं और फिर कल्पके आदिमें अर्थात् उत्पत्तिकालमें मैं पहलेकी भाँति पुनः उन प्राणियोंको रचता हूँ -- उत्पन्न करता हूँ।'),
('shankaracharya-ht:source:9.8','Śaṅkarācārya','gita.9.8','hi','translation','।।9.8।।इस प्रकार अविद्यारूप --, अपनी प्रकृतिको वशमें करके? मैं प्रकृतिसे उत्पन्न हुए इस विद्यमान समग्र अस्वतन्त्र भूतसमुदायको? जो कि स्वभाववश अविद्यादि दोषोंसे परवश हो रहा है? बारंबार रचता हूँ।'),
('shankaracharya-ht:source:9.9','Śaṅkarācārya','gita.9.9','hi','translation','।।9.9।।तब तो भूतसमुदायको विषम रचनेवाले आप परमेश्वरका उस विषम रचनाजनित पुण्यपापसे भी सम्बन्ध होता ही होगा ऐसी शङ्का होनेपर भगवान् ये वचन बोले --, हे धनंजय भूतसमुदायकी विषम रचनानिमित्तक वे कर्म? मुझ ईश्वरको बन्धनमें नहीं डालते। उन कर्मोंका सम्बन्ध न होनेमें कारण बतलाते हैं -- मैं उन कर्मोंमें उदासीनकी भाँति स्थित रहता हूँ अर्थात् आत्मा निर्विकार है? इसलिये जैसे कोई उदासीन -- उपेक्षा करनेवाला स्थित हो उसीकी भाँति मैं स्थित रहता हूँ। तथा उन कर्मोंमें फलसम्बन्धी आसक्तिसे और मैं करता हूँ इस अभिमानसे भी मैं रहित हूँ ( इस कारण वे कर्म मुझे नहीं बाँधते )। इससे यह अभिप्राय समझ लेना चाहिये कि कर्तापनके अभिमानका अभाव और फलसम्बन्धी आसक्तिका अभाव दूसरोंको भी बन्धनरहित कर देनेवाला है। इसके सिवा अन्य प्रकारसे किये हुए कर्मोंद्वारा मूर्खलोग कोशकार ( रेशमके कीड़े ) की भाँति बन्धनमें पड़ते हैं।,'),
('shankaracharya-ht:source:9.10','Śaṅkarācārya','gita.9.10','hi','translation','।।9.10।।यहाँ यह शङ्का होती है कि इस भूतसमुदायको मैं रचता हूँ? तथा मैं उदासीनकी भाँति स्थित रहता हूँ यह कहना परस्पर विरुद्ध है। इस शङ्काको दूर करनेके लिये कहते हैं --, सब ओरसे द्रष्टामात्र ही जिसका स्वरूप है ऐसे निर्विकारस्वरूप मुझ अधिष्ठातासे ( प्रेरित होकर ) अविद्यारूप मेरी त्रिगुणमयी माया -- प्रकृति समस्त चराचर जगत्को उत्पन्न किया करती है। वेदमन्त्र भी यही बात कहते हैं कि समस्त भूतोंमें अदृश्यभावसे रहनेवाला एक ही देव है जो कि सर्वव्यापी और सम्पूर्ण भूतोंका अन्तरात्मा तथा कर्मोंका स्वामी? समस्त भूतोंका आधार? साक्षी? चेतन? शुद्ध और निर्गुण है। हे कुन्तीपुत्र इसी कारणसे अर्थात् मैं इसका अध्यक्ष हूँ इसीलिये चराचरसहित साकारनिराकाररूप समस्त जगत् सब अवस्थाओंमें परिवर्तित होता रहता है? क्योंकि जगत्की समस्त प्रवृत्तियाँ साक्षीचेतनके ज्ञानका विषय बननेके लिये ही हैं। मैं यह खाऊँगा? यह देखता हूँ? यह सुनता हूँ? अमुक सुखका अनुभव करता हूँ? दुःख अनुभव करता हूँ? उसके लिये अमुक कार्य करूँगा? इसके लिये अमुक कार्य करूँगा? अमुक वस्तुको जानूँगा इत्यादि जगत्की समस्त प्रवृत्तियाँ ज्ञानाधीन और ज्ञानमें ही लय हो जानेवाली हैं। जो इस जगत्का अध्यक्ष साक्षी चेतन है वह परम हृदयाकाशमें स्थित है इत्यादि मन्त्र भी यही अर्थ दिखला रहे हैं। जब कि सबका अध्यक्षरूप चैतन्यमात्र एक देव वास्तवमें समस्त भोगोंके सम्बन्धसे रहित है और उसके सिवा अन्य चेतन न होनेके कारण दूसरे भोक्ताका अभाव है तो यह सृष्टि किसके लिये है इस प्रकारका प्रश्न और उसका उत्तर -- यह दोनों ही नहीं बन सकते ( अर्थात् यह विषय अनिर्वचनीय है )। ( इसको ) साक्षात् कौन जानता है -- इस विषयमें कौन कह सकता है यह जगत् कहाँसे आया किस कारण यह रचना हुई इत्यादि मन्त्रोंसे ( यही बात कही गयी है )। इसके सिवा भगवान्ने भी कहा है कि अज्ञानसे ज्ञान आवृत हो रहा है इसलिये समस्त जीव मोहित हो रहे हैं।'),
('shankaracharya-ht:source:9.11','Śaṅkarācārya','gita.9.11','hi','translation','।।9.11।।इस प्रकार मैं यद्यपि नित्यशुद्धबुद्धमुक्तस्वभाव तथा सभी प्राणियोंका आत्मा हूँ तो भी --, मूढ़ -- अविवेकी लोग मेरे सर्व लोकोंके महान् ईश्वररूप परमभावको अर्थात् सबका अपना आत्मारूप मैं परमात्मा सब प्राणियोंका महान् ईश्वर हूँ एवं आकाशकी भाँति बल्कि आकाशकी अपेक्षा भी सूक्ष्मतर भावसे व्यापक हूँ -- इस परम परमात्मतत्त्वको न जाननेके कारण मुझ मनुष्यदेहधारी परमात्माको तुच्छ समझते हैं अर्थात् मनुष्यरूपसे लीला करते हुए मुझ परमात्माकी अवज्ञा -- अनादर करते हैं। इसलिये मुझ परमात्माके निरादरकी भावनासे वे पामर जीव ( व्यर्थ ) मारे हुए पड़े हैं।'),
('shankaracharya-ht:source:9.12','Śaṅkarācārya','gita.9.12','hi','translation','।।9.12।।क्योंकि --, वे मोघाशा -- जिनकी आशाएँ -- कामनाएँ व्यर्थ हों ऐसे व्यर्थ कामना करनेवाले और मोघकर्मा -- व्यर्थ कर्म करनेवाले होते हैं क्योंकि उनके द्वारा जो कुछ अग्निहोत्रादि कर्म किये जाते हैं वे सब अपने अन्तरात्मारूप भगवान्का अनादर करनेके कारण निष्फल हो जाते हैं। इसलिये वे मोघकर्मा होते हैं। इसके अतिरिक्त वे मोघज्ञानी -- निष्फल ज्ञानवाले होते हैं? अर्थात् उनका ज्ञान भी निष्फल ही होता है। और वे विचेता अर्थात् विवेकहीन भी होते हैं। तथा वे मोह उत्पन्न करनेवाली देहात्मवादिनी राक्षसी और आसुरी प्रकृतिका यानी राक्षसोंके और असुरोंके स्वभावका आश्रय करनेवाले हो जाते हैं। अभिप्राय यह कि तोड़ो? फोड़ो? पिओ? खाओ? दूसरोंका धन लूट लो इत्यादि वचन बोलनेवाले और बड़े क्रूरकर्मा हो जाते हैं। श्रुति भी कहती है कि वे असुरोंके रहने योग्य लोक प्रकाशहीन हैं इत्यादि।'),
('shankaracharya-ht:source:9.13','Śaṅkarācārya','gita.9.13','hi','translation','।।9.13।।परन्तु जो श्रद्धायुक्त हैं और भगवद्भक्तिरूप मोक्षमार्गमें लगे हुए हैं वे --, हे पार्थ शम? दम? दया? श्रद्धा आदि सद्गुणरूप देवोंके स्वभावका अवलम्बन करनेवाले उदारचित्त महात्मा भक्तजन? मुझ ईश्वरको सब भूतोंका अर्थात् आकाशादि पञ्चभूतोंका और समस्त प्राणियोंका भी आदिकारण जानकर? एवं अविनाशी समझकर? अनन्य मनसे युक्त हुए भजते हैं अर्थात् मेरा चिन्तन किया करते हैं।'),
('shankaracharya-ht:source:9.14','Śaṅkarācārya','gita.9.14','hi','translation','।।9.14।।किस प्रकार भजते हैं --, वे दृढ़व्रती भक्त अर्थात् जिनका निश्चय दृढ़स्थिरअचल है ऐसे वे भक्तजन सदानिरन्तर ब्रह्मस्वरूप मुझ भगवान्का कीर्तन करते हुए तथा इन्द्रियनिग्रह? शम? दम? दया और अहिंसा आदि धर्मोंसे युक्त होकर प्रयत्न करते हुए एवं हृदयमें वास करनेवाले मुझ परमात्माको भक्ितपूर्वक नमस्कार करते हुए और सदा मेरा चिन्तन करनेमें लगे रहकर? मेरी उपासना -- सेवा करते रहते हैं।'),
('shankaracharya-ht:source:9.15','Śaṅkarācārya','gita.9.15','hi','translation','।।9.15।।वे किसकिस प्रकारसे उपासना करते हैं सो कहते हैं --, कुछ ( ज्ञानीजन ) दूसरी उपासनाओंको छोड़कर भगवद्विषयक ज्ञानरूप यज्ञसे मेरा पूजन करते हुए उपसना किया करते हैं अर्थात् परमब्रह्म परमात्मा एक ही है? ऐसे एकत्वरूप परमार्थज्ञानसे पूजन करते हुए मेरी उपासना करते हैं। और कोईकोई पृथक् भावसे अर्थात् आदित्य? चन्द्रमा आदिके भेदसे इस प्रकार समझकर उपासना करते हैं कि वही भगवान् विष्णु? सूर्य आदिके रूपमें स्थित हुए हैं। तथा कितने ही भक्त ऐसा समझकर कि वही सब ओर मुखवाले विश्वमूर्ति भगवान् अनेक रूपसे स्थित हो रहे हैं। उन विश्वरूप विराट् भगवान्हीकी विविध प्रकारसे उपासना करते हैं।'),
('shankaracharya-ht:source:9.16','Śaṅkarācārya','gita.9.16','hi','translation','।।9.16।।यदि भक्तलोग बहुत प्रकारसे उपासना करते हैं तो आपकी ही उपासना कैसे करते हैं इसपर कहते हैं --, क्रतु -- श्रौतयज्ञविशेष मैं हूँ और यज्ञस्मार्तकर्मविशेष भी मैं ही हूँ। तथा जो पितरोंको दिया जाता है? वह स्वधा नामक अन्न भी मैं ही हूँ। सब प्राणियोंसे जो खायी जाती है? उसका नाम औषध है? वह औषध भी मैं ही हूँ। अथवा यों समझो कि सब प्राणियोंका साधारण अन्न स्वधा है और व्याधिका नाश करनेके लिये काममें ली जानेवाली भेषज औषध है। तथा जिसके द्वारा देव और पितरोंको हवि पहुँचायी जाती है वह मन्त्र भी मैं ही हूँ। इसके अतिरिक्त मैं ही आज्य हविघृत हूँ? जिसमें होम किया जाता है वह अग्नि भी मैं ही हूँ और मैं ही हवनरूपकर्म भी हूँ।'),
('shankaracharya-ht:source:9.17','Śaṅkarācārya','gita.9.17','hi','translation','।।9.17।।तथा --, मैं ही इस जगत्को उत्पन्न करनेवाला पिता और उसकी जन्मदात्री माता हूँ तथा मैं ही प्राणियोंके कर्मफलका विधान करनेवाला विधाता और पितामह अर्थात् पिताका पिता हूँ तथा जाननेके योग्य? पवित्र करनेवाला? ओंकार? ऋग्वेद? सामवेद और यजुर्वेद सब कुछ मैं ही हूँ।'),
('shankaracharya-ht:source:9.18','Śaṅkarācārya','gita.9.18','hi','translation','।।9.18।।तथा मैं ही --, गति -- कर्मफल? भर्ता -- सबका पोषण करनेवाला? प्रभु -- सबका स्वामी? प्राणियोंके कर्म और अकर्मका साक्षी? जिसमें प्राणी निवास करते हैं वह वासस्थान? शरण अर्थात् शरणमें आये हुए दुःखियोंका दुःख दूर करनेवाला? सुहृत् -- प्रत्युपकार न चाहकर उपकार करनेवाला? प्रभव -- जगत्की उत्पत्तिका कारण और,जिसमें सब लीन हो जाते हैं वह प्रलय भी मैं ही हूँ। तथा जिसमें सब स्थित होते हैं वह स्थान? प्राणियोंके कालान्तरमें उपभोग करनेयोग्य कर्मोंका भण्डाररूप निधान और अविनाशी बीज भी मैं ही हूँ अर्थात् उत्पत्तिशील वस्तुओंकी उत्पत्तिका अविनाशी कारण मैं ही हूँ। जबतक संसार है तबतक उसका बीज भी अवश्य रहता है? इसलिये बीजको अविनाशी कहा है क्योंकि बिना बीजके कुछ भी उत्पन्न नहीं होता और उत्पत्ति नित्य देखी जाती है? इससे यह जाना जाता है कि बीजकी परम्पराका नाश नहीं होता।'),
('shankaracharya-ht:source:9.19','Śaṅkarācārya','gita.9.19','hi','translation','।।9.19।।तथा --, मैं ही सूर्य होकर अपनी कुछ प्रखर रश्मियोंसे सबको तपाता हूँ और कुछ किरणोंसे वर्षा करता हूँ तथा वर्षा कर चुकनेपर फिर कुछ रश्मियोंद्वारा आठ महीनेतक जलका शोषण करता रहता हूँ और वर्षाकाल आनेपर फिर बरसा देता हूँ। हे अर्जुन देवोंका अमृत और मर्त्यलोकमें बसनेवालोंकी मृत्यु तथा सत् और असत् सब मैं ही हूँ अर्थात् जो जिसके सम्बन्धसे विद्यमान है वह और जो उसके विपरीत है वह भी मैं ही हूँ। परंतु ( यह ध्यानमें रखना चाहिये कि ) स्वयं भगवान् अत्यन्त असत् नहीं हैं। अथवा सत् और असत्का अर्थ यहाँ कार्य और कारण समझना चाहिये। जो ज्ञानी पहले कहे हुए क्रमानुसार एकत्वपृथक्त्व आदि विज्ञानरूप यज्ञोंसे पूजन करते हुए मेरी उपासना करते हैं वे अपने विज्ञानानुसार मुझे ही प्राप्त होते हैं।'),
('shankaracharya-ht:source:9.20','Śaṅkarācārya','gita.9.20','hi','translation','।।9.20।।परंतु जो विषयवासनायुक्त अज्ञानी --, ऋक्? यजु और साम -- इन तीनों वेदोंको जाननेवाले? सोमरसका पान करनेवाले और पापरहित हुए अर्थात् सोमरसका पान करनेसे जिनके पाप नष्ट हो गये हैं ऐसे सकाम पुरुष वसु आदि देवोंके रूपमें स्थित मुझ परमात्माका अग्निष्टोमादि यज्ञोंद्वारा पूजन करके स्वर्गप्राप्तिकी इच्छा करते हैं। वे अपने पुण्यके फलस्वरूप इन्द्रके स्थानको पाकर स्वर्गमें देवताओंके दिव्य भोगोंको भोगते हैं अर्थात् देवताओंके जो स्वर्गमें होनेवाले अप्राकृत भोग हैं उनको भोगते हैं।'),
('shankaracharya-ht:source:9.21','Śaṅkarācārya','gita.9.21','hi','translation','।।9.21।।वे उस विशाल -- विस्तृत स्वर्गलोकको भोग चुकनेपर ( उसकी प्राप्तिके कारणरूप ) पुण्योंका क्षय हो जानेपर इस मृत्युलोकमें लौट आते हैं। उपर्युक्त प्रकारसे केवल वैदिक कर्मोंका आश्रय लेनेवाले कामकामी -- विषयवासनायुक्त मनुष्य बारंबार आवागमनको ही प्राप्त होते रहते हैं अर्थात् जाते हैं और लौट आते हैं इस प्रकार बराबर आवागमनको ही प्राप्त होते हैं? कहीं भी स्वतन्त्रता लाभ नहीं करते।'),
('shankaracharya-ht:source:9.22','Śaṅkarācārya','gita.9.22','hi','translation','।।9.22।।परंतु जो निष्कामी -- पूर्ण ज्ञानी हैं --, जो संन्यासी अनन्यभावसे युक्त हुए अर्थात् परमदेव मुझ नारायणको आत्मरूपसे जानते हुए मेरा निरन्तर चिन्तन करते हुए मेरी श्रेष्ठ -- निष्काम उपासना करते हैं? निरन्तर मुझमें ही स्थित उन परमार्थज्ञानियोंका योगक्षेम मैं चलाता हूँ। अप्राप्त वस्तुकी प्राप्तिका नाम योग है और प्राप्त वस्तुकी रक्षाका नाम क्षेम है? उनके ये दोनों काम मैं स्वयं किया करता हूँ। क्योंकि ज्ञानीको तो मैं अपना आत्मा ही मानता हूँ और वह मेरा प्यारा है इसलिये वे उपर्युक्त भक्त मेरे आत्मारूप और प्रिय हैं। पू0 -- अन्य भक्तोंका योगक्षेम भी तो भगवान् ही चलाते हैं उ0 -- यह बात ठीक है? अवश्य भगवान् ही चलाते हैं किंतु उसमें यह भेद है कि जो दूसरे भक्त हैं वे स्वयं भी अपने लिये योगक्षेमसम्बन्धी चेष्टा करते हैं? पर अनन्यदर्शी भक्त अपने लिये योगक्षेमसम्बन्धी चेष्टा नहीं करते। क्योंकि वे जीने और मरनेमें भी अपनी वासना नहीं रखते? केवल भगवान् ही उनके अवलम्बन रह जाते हैं। अतः उनका योगक्षेम स्वयं भगवान् ही चलाते हैं।'),
('shankaracharya-ht:source:9.23','Śaṅkarācārya','gita.9.23','hi','translation','।।9.23।।यदि कहो कि अन्य देव भी आप ही हैं? अतः उनके भक्त भी आपहीका पूजन करते हैं तो यह बात ठीक है --, जो कोई अन्य देवोंके भक्त -- अन्य देवताओंमें भक्ित रखनेवाले? श्रद्धासे -- आस्तिकबुद्धिसे युक्त हुए (उनका ) पूजन करते हैं? हे कुन्तीपुत्र वे भी मेरा ही पूजन कहते हैं ( परंतु ) अविधिपूर्वक ( करते हैं )। अविधि अज्ञानको करते हैं? सो वे अज्ञानपूर्वक मेरा पूजन करते हैं।'),
('shankaracharya-ht:source:9.24','Śaṅkarācārya','gita.9.24','hi','translation','।।9.24।।उनका पूजन करना अविधिपूर्वक कैसे है सो कहते हैं कि --, श्रौत और स्मार्त समस्त यज्ञोंका देवतारूपसे मैं ही भोक्ता हूँ और मैं ही स्वामी हूँ। मैं ही सब यज्ञोंका स्वामी हूँ यह बात अधियज्ञोऽहमेवात्र इस श्लोकमें भी कही गयी है। परंतु वे अज्ञानी इस प्रकार यथार्थ तत्त्वसे मुझे नहीं जानते। अतः अविधिपूर्वक पूजन करके वे यज्ञके असली फलसे गिर जाते हैं अर्थात् उनका पतन हो जाता है।'),
('shankaracharya-ht:source:9.25','Śaṅkarācārya','gita.9.25','hi','translation','।।9.25।।जो भक्त अन्य देवताओंकी भक्ितके रूपमें अविधिपूर्वक भी मेरा पूजन करते हैं उनको भी यज्ञका फल अवश्य मिलता है। कैसे ( सो कहा जाता है -- ) जिनका नियम और भक्ित देवोंके लिये ही है वे देवउपासकगण देवोंको प्राप्त होते हैं। श्राद्ध आदि क्रियाके परायण हुए पितृभक्त अग्निष्वात्तादि पितरोंको पाते हैं। भूतोंकी पूजा करनेवाले विनायक? षोडशमातृकागण और चतुर्भगिनी आदि भूतगणोंको पाते हैं तथा मेरा पूजन करनेवाले वैष्णव भक्त अवश्यमेव मुझे ही पाते हैं। अभिप्राय यह कि समान परिश्रम होनेपर भी वे ( अन्यदेवोपासक ) अज्ञानके कारण केवल मुझ परमेश्वरको ही नहीं भजते इसीसे वे अल्प फलके भागी होते हैं।,'),
('shankaracharya-ht:source:9.26','Śaṅkarācārya','gita.9.26','hi','translation','।।9.26।।मेरे भक्तोंको केवल अपुनरावृत्तिरूप अनन्त फल मिलता है इतना ही नहीं? किंतु मेरी आराधना भी सुखपूर्वक की जा सकता है। कैसे ( सो कहते हैं -- ) जो भक्त मुझे पत्र? पुष्प? फल और जल आदि कुछ भी वस्तु भक्तिपूर्वक देता है? उस प्रयतात्मा -- शुद्धबुद्धि भक्तके द्वारा भक्तिपूर्वक अर्पण किये हुए वे पत्र पुष्पादि मैं ( स्वयं ) खाता हूँ अर्थात् ग्रहण करता हूँ।'),
('shankaracharya-ht:source:9.27','Śaṅkarācārya','gita.9.27','hi','translation','।।9.27।।क्योंकि यह बात है? इसलिये --, हे कुन्तीपुत्र तू जो कुछ भी स्वतःप्राप्त कर्म करता है? जो खाता? जो कुछ श्रौत या स्मार्त यज्ञरूप हवन करता है? जो कुछ सुवर्ण? अन्न? घृतादि वस्तु ब्राह्मणादि सत्पात्रोंको दान देता है और जो कुछ तपका आचरण करता है? वह सब मेरे समर्पण कर।'),
('shankaracharya-ht:source:9.28','Śaṅkarācārya','gita.9.28','hi','translation','।।9.28।।ऐसा करनेसे तुझे जो लाभ होगा वह सुन --, इस प्रकार कर्मोंको मेरे अर्पण करके तू शुभाशुभ फलयुक्त कर्मबन्धनसे अर्थात् अच्छा और बुरा जिसका फल,है ऐसे कर्मरूप बन्धनसे छूट जायगा। तथा इस प्रकार तू संन्यासयोगयुक्तात्मा होकर? -- मेरे अर्पण करके कर्म किये जानेके कारण जो संन्यास है और कर्मरूप होनेके कारण जो योग है उस संन्यासरूप योगसे जिसका अन्तःकरण युक्त है उसका नाम संन्यासयोगयुक्तात्मा है? ऐसा होकर? -- तू इस जीवितावस्थामें ही कर्मबन्धनसे मुक्त होकर इस शरीरका नाश होनेपर मुझे ही प्राप्त हो जायगा। अर्थात् मुझमें ही विलीन हो जायगा।'),
('shankaracharya-ht:source:9.29','Śaṅkarācārya','gita.9.29','hi','translation','।।9.29।।( यदि कहो कि ) तब तो भगवान् रागद्वेषसे युक्त हैं क्योंकि वे भक्तोंपर ही अनुग्रह करते हैं दूसरोंपर नहीं करते? तो यह कहना ठीक नहीं है --, मैं सभी प्राणियोंके प्रति समान हूँ? मेरा न तो ( कोई ) द्वेष्य है और न ( कोई ) प्रिय है। मैं अग्निके समान हूँ। जैसे अग्नि अपनेसे दूर रहनेवाले प्राणियोंके शीतका निवारण नहीं करता? पास आनेवालोंका ही करता है? वैसे ही मैं भक्तोंपर अनुग्रह किया करता हूँ? दूसरों पर नहीं। जो ( भक्त ) मुझ ईश्वरका प्रेमपूर्वक भजन करते हैं? वे मुझमें स्वभावसे ही स्थित हैं? कुछ मेरी आसक्तिके कारण नहीं औरमैं भी स्वभावसेही उनमें स्थित हूँ? दूसरोंमें नहीं। परन्तु इतनेहीसे यह बात नहीं है कि मेरा उनमें ( दूसरोंमें ) द्वेष है।'),
('shankaracharya-ht:source:9.30','Śaṅkarācārya','gita.9.30','hi','translation','।।9.30।।मेरी भक्तिकी महिमा सुन --, यदि कोई सुदुराचारी अर्थात् अतिशय बुरे आचरणवाला मनुष्य भी अनन्य प्रेमसे युक्त हुआ मुझ ( परमेश्वर ) को भजता है तो उसे साधु ही मानना चाहिये अर्थात् उसे यथार्थ आचरण करनेवाला ही समझना चाहिये क्योंकि यह यथार्थ निश्चययुक्त हो चुका है -- उत्तम निश्चयवाला हो गया है।'),
('shankaracharya-ht:source:9.31','Śaṅkarācārya','gita.9.31','hi','translation','।।9.31।।आन्तरिक यथार्थ निश्चयकी शक्तिसे बाहरी दुराचारिताको छोड़कर --, वह शीघ्र ही धर्मात्मा -- धार्मिक चित्तवाला बन जाता है और सदा रहनेवाली नित्य शान्ति -- उपरतिको पा लेता है। हे कुन्तीपुत्र तू यथार्थ बात सुन? तू यह निश्चित प्रतिज्ञा कर अर्थात् दृढ़ निश्चय कर ले कि जिसने मुझ परमात्मामें अपना अन्तःकरण समर्पित कर दिया है वह मेरा भक्त कभी नष्ट नहीं होता? अर्थात् उसका कभी पतन नहीं होता।'),
('shankaracharya-ht:source:9.32','Śaṅkarācārya','gita.9.32','hi','translation','।।9.32।।तथा --, क्योंकि हे पार्थ जो कोई पापयोनिवाले हैं अर्थात् जिनके जन्मका कारण पाप है ऐसे प्राणी हैं -- वे कौन हैं सो कहते हैं -- वे स्त्री? वैश्य और शूद्र भी मेरी शरणमें आकर -- मुझे ही अपना अवलम्बन बनाकर परम -- उत्तम गतिको ही पाते हैं।'),
('shankaracharya-ht:source:9.33','Śaṅkarācārya','gita.9.33','hi','translation','।।9.33।।फिर जो पुण्ययोनि ब्राह्मण और राजर्षि भक्त हैं उनका तो कहना ही क्या है जो राजा भी हों और ऋषि भी हों? वे राजर्षि कहलाते हैं। क्योंकि यह बात है? इसलिये इस अनित्य? क्षणभङ्गुर और सुखरहित मनुष्यलोकको पाकर अर्थात् परम पुरुषार्थके साधनरूप दुर्लभ मनुष्यशरीरको पाकर मुझ ईश्वरका ही भजन कर -- मेरी ही सेवा कर।'),
('shankaracharya-ht:source:9.34','Śaṅkarācārya','gita.9.34','hi','translation','।।9.34।।किस प्रकार ( भजनसेवा करें सो कहा जाता है -- ) तू मन्मना -- मुझमें ही मनवाला हो। मद्भक्त -- मेरा ही भक्त हो। मद्याजी -- मेरा ही पूजन करनेवाला हो और मुझे ही नमस्कार किया कर। इस प्रकार चित्तको मुझमें लगाकर मेरे परायण -- शरण हुआ तू मुझ,परमेश्वरको ही प्राप्त हो जायगा। अभिप्राय यह कि मैं ही सब भूतोंका आत्मा और परमगति -- परम स्थान हूँ? ऐसा जो मैं आत्मरूप हूँ उसीको तू प्राप्त हो जायगा। इस प्रकार पहलेके माम् शब्दसे आत्मानम् शब्दका सम्बन्ध है।'),
('shankaracharya-ht:source:10.1','Śaṅkarācārya','gita.10.1','hi','translation','।।10.1।।सातवें और नवें अध्यायमें भगवान्के तत्त्वका और विभूतियोंका वर्णन किया गया। अब जिनजिन भावोंमें भगवान् चिन्तन किये जाने योग्य हैं उनउन भावोंका वर्णन किया जाना चाहिये। यद्यपि भगवान्का तत्त्व पहले कहा गया है परंतु दुर्विज्ञेय होनेके कारण फिर भी उसका वर्णन होना चाहिये? इसलिये श्रीभगवान् बोले --, हे महाबाहो फिर भी तू मेरे परम उत्तम निरतिशय वस्तुको प्रकाशित करनेवाले वाक्य सुन? जो कि मैं तुझ प्रसन्न होनेवालेके हितकी इच्छासे कहूँगा। मेरे वचनोंको सुनकर तू अमृतपान करता हुआसा अत्यन्त प्रसन्न होता है? इसीलिये मैं तुझसे यह परम वाक्य कहने लगा हूँ। ,'),
('shankaracharya-ht:source:10.2','Śaṅkarācārya','gita.10.2','hi','translation','।।10.2।।मैं ( ऐसा ) किसलिये कहता हूँ सो बतलाते हैं --, ब्रह्मादि देवता मेरे प्रभवको यानी अतिशय प्रभुत्वशक्तिको अथवा प्रभव यानी मेरी उत्पत्तिको नहीं जानते और भृगु आदि महर्षि भी ( मेरे प्रभवको ) नहीं जानते। वे किस कारणसे नहीं जानते सो कहते हैं --,, क्योंकि देवोंका और महर्षियोंका सब प्रकारसे मैं ही आदि -- मूल कारण हूँ।,'),
('shankaracharya-ht:source:10.3','Śaṅkarācārya','gita.10.3','hi','translation','।।10.3।।तथा --, क्योंकि मैं महर्षियोंका और देवोंका आदिकारण हूँ? मेरा आदि दूसरा कोई नहीं है? इसलिये मैं अजन्मा और अनादि हूँ। अनादित्व ही जन्मरहित होनेमें कारण है। इस प्रकार जो मुझे जन्मरहित अनादि और लोकोंका महान् ईश्वर अर्थात् अज्ञान और उसके कार्यसे रहित ( जाग्रत? स्वप्न? सुषुप्ति -- इन तीनों अवस्थाओंसे अतीत ) चतुर्थ अवस्थायुक्त जानता है? वह ( इस प्रकार जाननेवाला ) मनुष्योंमें ज्ञानी है अर्थात् मोहसे रहित श्रेष्ठ पुरुष है और वह जानबूझकर किये हुए या बिना जाने किये हुए सभी पापोंसे मुक्त हो जाता है।'),
('shankaracharya-ht:source:10.4','Śaṅkarācārya','gita.10.4','hi','translation','।।10.4।। इसलिये भी मैं लोकोंका महान् ईश्वर हूँ --, सूक्ष्म? सूक्ष्मतर आदि पदार्थोंको समझनेवाली अन्तःकरणकी ज्ञानशक्तिका नाम बुद्धि है। उससे युक्त मनुष्यको ही बुद्धिमान् कहते हैं। ज्ञान -- आत्मा आदि पदार्थोंका बोध? असंमोह -- जाननेयोग्य पदार्थ प्राप्त होनेपर उनमें विवेकपूर्वक प्रवृत्ति? क्षमा -- किसीके द्वारा अपनी निन्दाकी जाने या ताड़ना दी जानेपर भी चित्तमें विकार न होना? सत्य -- देखने और सुननेसे जिस प्रकारका अपनेको अनुभव हुआ हो? उसको दूसरेकी बुद्धिमें पहुँचानेके लिये उसी प्रकार कही जानेवाली वाणी सत्य कहलाती है? दम -- बाह्य इन्द्रियोंको वशमें कर लेना? शम -- अन्तःकरणकी उपरति? सुख -- आह्लाद? दुःख -- सन्ताप? भव -- उत्पत्ति? अभाव -- उत्पत्तिके विपरीत ( विनाश ) तथा भय -- त्रास और अभय -- उसके विपरीत जो निर्भयता है वह भी।'),
('shankaracharya-ht:source:10.5','Śaṅkarācārya','gita.10.5','hi','translation','।।10.5।।अहिंसा -- प्राणियोंको किसी प्रकार पीड़ा न पहुँचाना? समता -- चित्तका समभाव? संतोष -- जो कुछ मिले उसीको यथेष्ट समझना? तप -- इन्द्रियसंयमपूर्वक शरीरको सुखाना? दान -- अपनी शक्तिके अनुसार धनका विभाग करना ( दूसरोंको बाँटना )? यश -- धर्मके निमित्तसे होनेवाली कीर्ति? अपयश -- अधर्मके निमित्तसे होनेवाली अपकीर्ति। इस प्रकार जो प्राणियोंके अपने अपने कर्मोंके अनुसार होनेवाले बुद्धि आदि नाना प्रकारके भाव हैं? वे सब मुझ ईश्वरसे ही होते हैं।'),
('shankaracharya-ht:source:10.6','Śaṅkarācārya','gita.10.6','hi','translation','।।10.6।।तथा --, भृगु आदि सप्त महर्षि और पहले होनेवाले चार मनु जिनका अतीत कालसे सम्बन्ध है और जो सावर्ण इस नामसे पुराणोंमें प्रसिद्ध हैं? ये सभी मुझमें भावनावाले -- ईश्वरीय सामर्थ्यसे युक्त और मेरे द्वारा मनसे उत्पन्न किये हुए हैं? जिस मनु और महर्षियोंकी रची हुई ये चर और अचररूप सब प्रजाएँ लोकमें प्रसिद्ध हैं।'),
('shankaracharya-ht:source:10.7','Śaṅkarācārya','gita.10.7','hi','translation','।।10.7।।मेरी इस उपर्युक्त विभूतिको अर्थात् विस्तारको और योग -- युक्तिको अर्थात् अपनी मायिक घटनाको? अथवा योगसे उत्पन्न हुई सर्वज्ञतारूप सामर्थ्यको जो कि योगशब्दसे कही जाती है? जो तत्त्वसे -- यथार्थ जानता है? वह पुरुष पूर्ण ज्ञानकी स्थिरतारूप निश्चल योगसे युक्त हो जाता है? इस विषयमें ( कुछ भी ) संशय नहीं है।'),
('shankaracharya-ht:source:10.8','Śaṅkarācārya','gita.10.8','hi','translation','।।10.8।।किस प्रकारके अविचल योगसे युक्त हो जाता है सो कहा जाता है --, मैं वासुदेव नामक परब्रह्म समस्त जगत्की उत्पत्तिका कारण हूँ? और मुझसे ही यह स्थिति? नाश? क्रिया और कर्मफलोपभोगरूप विकारमय सारा जगत् घुमाया जा रहा है। इस अभिप्रायको ( अच्छी प्रकार ) समझकर भावसमन्वित -- परमार्थतत्त्वकी धारणासे युक्त हुए? बुद्धिमान् -- तत्त्वज्ञानी पुरुष? मुझे भजते हैं अर्थात् मेरा चिन्तन किया करते हैं।'),
('shankaracharya-ht:source:10.9','Śaṅkarācārya','gita.10.9','hi','translation','।।10.9।।तथा --, मुझमें ही जिनका चित्त है वे मच्चित्त हैं तथा मुझमें ही जिनके चक्षु आदि इन्द्रियरूप प्राण लगे रहते हैं -- मुझमें ही जिन्होंने समस्त करणोंका उपसंहार कर दिया है वे मद्गतप्राण हैं अथवा जिन्होंने मेरे लिये ही अपना जीवन अर्पण कर दिया है वे मद्गतप्राण हैं। ऐसे मेरे भक्त आपसमें एक दूसरेको ( मेरा तत्त्व ) समझाते हुए एवं ज्ञान? बल और सामर्थ्य आदि गुणोंसे युक्त मुझ परमेश्वरके स्वरूपका वर्णन करते हुए सदा संतुष्ट रहते हैं अर्थात् संतोषको प्राप्त होते हैं और रमण करते हैं अर्थात् मानो कोई अपना अत्यन्त प्यारा मिल गया हो उसी तरह रतिको प्राप्त होते हैं।'),
('shankaracharya-ht:source:10.10','Śaṅkarācārya','gita.10.10','hi','translation','।।10.10।।जो पुरुष मुझमें प्रेम रखते हुए उपर्युक्त प्रकारसे मेरा भजन करते हैं --, उन समस्त बाह्य तृष्णाओंसे रहित निरन्तर तत्पर होकर भजन -- सेवन करनेवाले पुरुषोंको? किसी वस्तुकी इच्छा आदि कारणोंसे भजनेवालोंको नहीं? किंतु प्रीतिपूर्वक भजनेवालोंको यानी प्रेमपूर्वक मेरा भजन करनेवालोंको? मैं वह बुद्धियोग देता हूँ। मेरे तत्त्वके यथार्थ ज्ञानका नाम बुद्धि है? उससे युक्त होना ही बुद्धियोग है। वह ऐसा बुद्धियोग मैं ( उनको ) देता हूँ कि जिस पूर्णज्ञानरूप बुद्धियोगसे वे मुझ आत्मरूप परमेश्वरको आत्मरूपसे समझ लेते हैं। वे कौन हैं जो मच्चित्ताः आदि ऊपर कहे हुए प्रकारोंसे मेरा भजन करते हैं।,'),
('shankaracharya-ht:source:10.11','Śaṅkarācārya','gita.10.11','hi','translation','।।10.11।।आपकी प्राप्तिके कौनसे प्रतिबन्धके कारणका नाश करनेवाला बुद्धियोग आप उन भक्तोंको देते हैं और किसलिये देते हैं इस आकाङ्क्षापर कहते हैं --, उन ( मेरे भक्तों ) का किसी तरह भी कल्याण हो ऐसा अनुग्रह करनेके लिये ही मैं उनके आत्मभावमें स्थित हुआ अर्थात् आत्माका भाव जो अन्तःकरण है उसमें स्थित हुआ उनके अविवेकजन्य मिथ्या प्रतीतिरूप,मोहमय अन्धकारको प्रकाशमय विवेकबुद्धिरूप ज्ञानदीपकद्वारा नष्ट कर देता हूँ। अर्थात् जो भक्ितके प्रसादरूप घृतसे परिपूर्ण है और मेरे स्वरूपकी भावनाके अभिनिवेशरूप वायुकी सहायतासे प्रज्वलित हो रहा है? जिसमें ब्रह्मचर्य आदि साधनोंके संस्कारोंसे युक्त बुद्धिरूप बत्ती है? आसक्ितरहित अन्तःकरण जिसका आधार है? जो विषयोंसे हटे हुए और रागद्वेषरूप कालुष्यसे रहित हुए चित्तरूप वायुरहित अपवारकमें ( ढकनेमें ) स्थित है और जो निरन्तर अभ्यास किये हुए एकाग्रतारूप ध्यानजनित? पूर्ण ज्ञानस्वरूप प्रकाशसे युक्त है? उस ज्ञानदीपकद्वारा ( मैं उनके मोहका नाश कर देता हूँ )।'),
('shankaracharya-ht:source:10.12','Śaṅkarācārya','gita.10.12','hi','translation','।।10.12।।ऊपर कही हुई भगवान्की विभूतिको और योगको सुनकर अर्जुन बोला --, आप परमब्रह्मपरमात्मा? परमधाम -- परमतेज और परमपावन हैं तथा आप नित्य और दिव्य पुरुष हैं अर्थात् देवलोकमें रहनेवाले अलौकिक पुरुष हैं एवं आप सब देवोंसे पहले होनेवाले आदिदेव? अजन्मा और व्यापक हैं।'),
('shankaracharya-ht:source:10.13','Śaṅkarācārya','gita.10.13','hi','translation','।।10.13।।ऐसे --, आपका वसिष्ठादि सब महर्षिगण वर्णन करते हैं तथा असित? देवल? व्यास और देवर्षि नारद भी इसी प्रकार कहते हैं एवं स्वयं आप भी मुझसे ऐसा ही कह रहे हैं।');
