INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:10.14','Śaṅkarācārya','gita.10.14','hi','translation','।।10.14।।हे केशव उपर्युक्त प्रकारसे ऋषियोंद्वारा और आपके द्वारा कही हुई ये सब बातें जो कि आप मुझसे कह रहे हैं? मैं सत्य मानता हूँ क्योंकि हे भगवन् आपकी उत्पत्तिको न देवता जानते हैं और न दानव ही जानते हैं।'),
('shankaracharya-ht:source:10.15','Śaṅkarācārya','gita.10.15','hi','translation','।।10.15।।क्योंकि आप देवादिके आदि कारण हैं? इसलिये --, हे पुरुषोत्तम हे भूतप्राणियोंको उत्पन्न करनेवाले भूतभावन हे भूतेशभूतोंके ईश्वर हे देवोंके देव हे जगत्पते आप स्वयं ही अपनेद्वारा अपने आपको अर्थात् निरतिशय ज्ञान? ऐश्वर्य? सामर्थ्य आदि शक्तियोंसे युक्त ईश्वरको जानते हैं।'),
('shankaracharya-ht:source:10.16','Śaṅkarācārya','gita.10.16','hi','translation','।।10.16।।अपनी दिव्य विभूतियोंका पूर्णतया वर्णन करनेमें ( आप ही ) समर्थ हैं -- आपकी जो विभूतियाँ हैं? जिन विभूतियोंसे अर्थात् अपने माहात्म्यके विरतारसे आप इन सारे लोकोंको व्याप्त करके स्थित हो रहे हैं? उन्हें कहनेमें आप ही समर्थ हैं।'),
('shankaracharya-ht:source:10.17','Śaṅkarācārya','gita.10.17','hi','translation','।।10.17।।हे योगिन् आपका सदा चिन्तन करता हुआ मैं आपको किस प्रकार जानूँ हे भगवन् आप किनकिन भावोंमें अर्थात् वस्तुओंमें मेरे द्वारा चिन्तन किये जानेयोग्य हैं।'),
('shankaracharya-ht:source:10.18','Śaṅkarācārya','gita.10.18','hi','translation','।।10.18।।हे जनार्दन अपने योगको -- अपनी योगैश्वर्यरूप विशेष शक्तिको और विभूतिको यानी चिन्तन करनेयोग्य पदार्थोंके विस्तारको? विस्तारपूर्वक कहिये। गमन जिसका कर्म है ऐसी अर्द धातुका रूप जनार्दन है। असुरोंको यानी देवोंके प्रतिपक्षी मनुष्योंको नरकादिमें भेजनेवाले होनेसे भगवान्का नाम जनार्दन है। अथवा उन्नति और कल्याण -- ये दोनों पुरुषार्थरूप प्रयोजन सब लोगोंके द्वारा भगवान्से माँगे जाते हैं? इसलिये भगवान्का नाम जनार्दन है -- यद्यपि आप पहले कह चुके हैं तो भी फिर कहिये क्योंकि आपके मुखसे निकले हुए वाक्यरूप अमृतको सुनतेसुनते मुझे तृप्ति नहीं होती है -- संतोष नहीं होता है।'),
('shankaracharya-ht:source:10.19','Śaṅkarācārya','gita.10.19','hi','translation','।।10.19।।श्रीभगवान् बोले -- हे कुरुवंशियोंमें श्रेष्ठ अब मैं तुझे अपनी दिव्य -- देवलोकमें होनेवाली विभूतियाँ प्रधानतासे बतलाता हूँ अर्थात् मेरी जहाँजहाँपर जोजो प्रधानप्रधान विभूतियाँ हैं? उनउन प्रधान विभूतियोंका ही मैं प्रधानतासे वर्णन करता हूँ। सम्पूर्णतासे तो वे सैकड़ों वर्षोंमें भी नहीं कही जा सकतीं क्योंकि मेरे विस्तारका अर्थात् मेरी विभूतियोंका अन्त नहीं है।'),
('shankaracharya-ht:source:10.20','Śaṅkarācārya','gita.10.20','hi','translation','।।10.20।।उनमें तू पहली विभूतिको ही सुन --, गुडाका -- निद्रा उसका स्वामी यानी निद्राजयी होनेके कारण अथवा घनकेश होनेके कारण अर्जुनका नाम गुडाकेश है। हे गुडाकेश समस्त भूतोंके आशयमें यानी आन्तरिक हृदयदेशमें स्थित सबका अन्तरात्मा मैं हूँ ( ऊँचे अधिकारियोंको तो ) मेरा ध्यान सदा इस प्रकार करना चाहिये। परंतु जो ऐसा ध्यान करनेमें असमर्थ हों उन्हें आगे कहे हुए भावोंमें मेरा चिन्तन करना चाहिये? अर्थात् उनके द्वारा ( इन अगले भावोंमें ) मेरा चिन्तन किया जा सकता है क्योंकि मैं ही सब भूतोंका आदि? मध्य और अन्त हूँ अर्थात् उनकी उत्पत्ति? स्थिति और प्रलयरूप मैं ही हूँ।'),
('shankaracharya-ht:source:10.21','Śaṅkarācārya','gita.10.21','hi','translation','।।10.21।।तथा इस प्रकार भी मेरा ध्यान किया जा सकता है --, द्वादश आदित्योंमें मैं विष्णु नामक आदित्य हूँ। प्रकाश करनेवाली ज्योतियोंमें मैं किरणोंवाला सूर्य हूँ। वायुसम्बन्धी देवताओंके भेदोंमें मैं मरीचि नामक देवता हूँ और नक्षत्रोंमें मैं शशी -- चन्द्रमा हूँ।'),
('shankaracharya-ht:source:10.22','Śaṅkarācārya','gita.10.22','hi','translation','।।10.22।।मैं वेदोमें सामवेद हूँ? रुद्र? आदित्य आदि देवोंमें इन्द्र हूँ और चक्षु आदि एकादश इन्द्रियोंमें संकल्पविकल्पात्मक मन हूँ। सब प्राणियोंमें ( मैं ) चेतना हूँ। कार्यकरणके समुदायरूप शरीरमें सदा प्रकाशित रहनेवाली जो बुद्धिवृत्ति है? उसका नाम चेतना है।'),
('shankaracharya-ht:source:10.23','Śaṅkarācārya','gita.10.23','hi','translation','।।10.23।।एकादश रुद्रोंमें मैं शंकर हूँ। यक्ष और राक्षसोंमें मैं धनेश्वर कुबेर हूँ। आठ वसुओंमें मैं पावक -- अग्नि हूँ। शिखरवालोंमें ( पर्वतोंमें ) मैं सुमेरु पर्वत हूँ।'),
('shankaracharya-ht:source:10.24','Śaṅkarācārya','gita.10.24','hi','translation','।।10.24।।हे पार्थ पुरोहितोंमें यानी राजपुरोहितोंमें तू मुझे प्रधान पुरोहित बृहस्पति समझ क्योंकि वे ही इन्द्रके मुख्य पुरोहित हैं। सेनापतियोंमें मैं देवोंका सेनापति कार्तिकेय हूँ तथा सरोवरोंमें अर्थात् जो देवनिर्मित सरोवर हैं उनमें समुद्र हूँ।'),
('shankaracharya-ht:source:10.25','Śaṅkarācārya','gita.10.25','hi','translation','।।10.25।।महर्षियोंमें मैं भृगु हूँ? वाणीसम्बन्धी भेदोंमें -- पदात्मक वाक्योंमें एक अक्षर -- ओंकार हूँ? यज्ञोंमें जपयज्ञ हूँ और स्थावरोंमें अर्थात् अचल पदार्थोंमें हिमालय नामक पर्वत हूँ।'),
('shankaracharya-ht:source:10.26','Śaṅkarācārya','gita.10.26','hi','translation','।।10.26।।समस्त वृक्षोंमें पीपलका वृक्ष और देवर्षियोंमें अर्थात् जो देव होकर मन्त्रोंके द्रष्टा होनेके कारण ऋषिभावको प्राप्त हुए हैं? उनमें मैं नारद हूँ। गन्धर्वोंमें मैं चित्ररथ नामक गन्धर्व हूँ? सिद्धोंमें अर्थात् जन्मसे ही अतिशय धर्म? ज्ञान? वैराग्य और ऐश्वर्यको प्राप्त हुए पुरुषोंमें मैं कपिलमुनि हूँ।'),
('shankaracharya-ht:source:10.27','Śaṅkarācārya','gita.10.27','hi','translation','।।10.27।।घोड़ोंमें? जो अमृतप्राप्तिके निमित्त किये हुए समुद्रमन्थनसे उत्पन्न उच्चैःश्रवा नामक घोड़ा है? उसको तू मेरा स्वरूप समझ। गजेन्द्रोंमें -- मुख्य हाथियोंमें -- इरावतीका पुत्र जो ऐरावत नामक हाथी है? उसको तू मेरा स्वरूप जान और मनुष्योंमें मुझे तू राजा समझ।'),
('shankaracharya-ht:source:10.28','Śaṅkarācārya','gita.10.28','hi','translation','।।10.28।।शस्त्रोंमें मैं दधीचि ऋषिकी अस्थियोंसे बना हुआ वज्र हूँ। दूध देनेवाली गौओंमें कामधेनु -- वसिष्ठको सब कामनारूप दूध देनेवाली अथवा सामान्य भावसे जो भी कामधेनु है वह मैं हूँ। प्रजाको उत्पन्न करनेवाला कामदेव मैं हूँ और सर्पोंमें अर्थात् सर्पोके नाना भेदोंमें सर्पराज वासुकि मैं हूँ।'),
('shankaracharya-ht:source:10.29','Śaṅkarācārya','gita.10.29','hi','translation','।।10.29।।नागोंके नाना भेदोंमें मैं अनन्त हूँ अर्थात् नागराज शेष हूँ और जलसम्बन्धी देवोंमें उनका राजा वरुण मैं हूँ। मैं पितरोंमें अर्यमा नामक पितृराज हूँ और शासन करनेवालोंमें यमराज हूँ।'),
('shankaracharya-ht:source:10.30','Śaṅkarācārya','gita.10.30','hi','translation','।।10.30।।दैत्योंमें अर्थात् दितिके वंशजोंमें मैं प्रह्लाद नामक दैत्य हूँ और कलना -- गणना करनेवालोंमें मैं काल हूँ। पशुओंमें पशुओंका राजा सिंह या व्याघ्र और पक्षियोंमें विनतापुत्र -- गरुड़ मैं हूँ।'),
('shankaracharya-ht:source:10.31','Śaṅkarācārya','gita.10.31','hi','translation','।।10.31।।पवित्र करनेवालोंमें वायु और शस्त्रधारियोंमें दशरथपुत्र राम मैं हूँ? मछली आदि जलचर प्राणियोंमें मकर नामक जलचरोंकी जातिविशेष मैं हूँ? स्रोतोंमें -- नदियोंमें मैं जाह्नवी -- गङ्गा हूँ।'),
('shankaracharya-ht:source:10.32','Śaṅkarācārya','gita.10.32','hi','translation','।।10.32।।हे अर्जुन सृष्टियोंका आदि? अन्त और मध्य अर्थात् उत्पत्ति? स्थिति और प्रलय मैं हूँ। आरम्भमें तो भगवान्ने अपनेको केवल चेतनाधिष्ठित प्राणियोंका ही आदि? मध्य और अन्त बतलाया है? परन्तु यहाँ समस्त जगत्मात्रका आदि? मध्य और अन्त बतलाते हैं? यह विशेषता है। समस्त विद्याओंमें जो कि मोक्ष देनेवाली होनेके कारण प्रधान है? वह अध्यात्मविद्या मैं हूँ। शंकासमाधान करनेके समय बोले जानेवाले वाक्योंमें जो अर्थनिर्णयका हेतु होनेसे प्रधान है वह वाद नामक वाक्य मैं हूँ। यहाँ प्रवदताम् इस पदसे वक्ताद्वारा बोले जानेवाले वाद? जल्प और वितण्डा -- इन तीन प्रकारके वचनभेदोंका ही ग्रहण है ( बोलनेवालोंका नहीं )।'),
('shankaracharya-ht:source:10.33','Śaṅkarācārya','gita.10.33','hi','translation','।।10.33।।अक्षरोंमें -- वर्णोंमें अकार -- अ वर्ण मैं हूँ। समास -- समूहमें द्वन्द्व नामक समास मैं हूँ तथा मैं ही अविनाशी काल -- जो क्षणघड़ी आदि नामोंसे प्रसिद्ध है वह समय? अथवा कालका भी काल परमेश्वर हूँ और मैं ही विधाता -- सब जगत्के कर्मफलका विधान करनेवाला तथा सब ओर मुखवाला परमात्मा हूँ।'),
('shankaracharya-ht:source:10.34','Śaṅkarācārya','gita.10.34','hi','translation','।।10.34।।धनादिका नाश करनेवाला और प्राणोंका नाश करनेवाला ऐसे दो प्रकारका मृत्यु सर्वहर कहलाता है? वह सर्वहर मृत्यु मैं हूँ। अथवा परम ईश्वर प्रलयकालमें सबका नाश करनेवाला होनेसे सर्वहर है? वह मैं हूँ। भविष्यत्में जिनका कल्याण होनेवाला है अर्थात् जो उत्कर्षताप्राप्तिके योग्य हैं उनका उद्भव अर्थात् उत्कर्ष -- उन्नतिकी प्राप्तिका कारण मैं हूँ। स्त्रियोंमें जो कीर्ति? श्री? वाणी? स्मृति? बुद्धि? घृति और क्षमा ये उत्तम स्त्रियाँ हैं? जिनके आभासमात्र सम्बन्धसे भी लोग अपनेको कृतार्थ मानते हैं वे मैं हूँ।'),
('shankaracharya-ht:source:10.35','Śaṅkarācārya','gita.10.35','hi','translation','।।10.35।।तथा सामवेदके प्रकरणोंमें जो बृहत्साम नामक प्रधान प्रकरण है वह मैं हूँ। छन्दोंमें मैं गायत्री छन्द हूँ अर्थात् जो गायत्री आदि छन्दोबद्ध ऋचाएँ हैं उनमें गायत्री नामक ऋचा मैं हूँ। महीनोंमें मार्गशीर्ष नामक महीना और ऋतुओंमें बसन्त ऋतु मैं हूँ।'),
('shankaracharya-ht:source:10.36','Śaṅkarācārya','gita.10.36','hi','translation','।।10.36।।छल करनेवालोंमें जो पासोंसे खेलना आदि द्यूत है वह मैं हूँ। तेजस्वियोंका मैं तेज हूँ। जीतनेवालोंका मैं विजय हूँ। निश्चय करनेवालोंका निश्चय ( अथवा उद्यमशीलोंका उद्यम ) हूँ और सत्त्वयुक्त पुरुषोंका अर्थात् सात्त्विक पुरुषोंका मैं सत्त्वगुण हूँ।'),
('shankaracharya-ht:source:10.37','Śaṅkarācārya','gita.10.37','hi','translation','।।10.37।।वृष्णिवंशियोंमें यह तुम्हारा सखा वासुदेव मैं हूँ। पाण्डवोंमें धनंजय अर्थात् तू ही मैं हूँ। मुनियोंमें अर्थात् मनन करनेवालोंमें और सब पदार्थोंको जाननेवालोंमें भी मैं व्यास हूँ। कविवोंमें अर्थात्,त्रिकालदर्शियोंमें मैं शुक्राचार्य हूँ।'),
('shankaracharya-ht:source:10.38','Śaṅkarācārya','gita.10.38','hi','translation','।।10.38।।दमन करनेवालोंका दण्ड अर्थात् उन्मार्गमें चलनेवालोंको दमन करनेकी शक्ति मैं हूँ। विजय चाहनेवालोंका न्याय मैं हूँ। गुप्त रखने योग्य भावोंमें मौन मैं हूँ। ज्ञानवानोंका ज्ञान मैं हूँ।'),
('shankaracharya-ht:source:10.39','Śaṅkarācārya','gita.10.39','hi','translation','।।10.39।।हे अर्जुन सर्वभूतोंका जो बीज अर्थात् उत्पत्तिका कारण है? वह मैं हूँ। प्रकरणका उपसंहार करनेके लिये समस्त विभूतियोंका सार कहते हैं -- ऐसा वह चर या अचर कोई भी भूत प्राणी नहीं है जो मेरे बिना हो। क्योंकि जो मुझसे रहित होगा वह सत्तारहित -- शून्य होगा? अतः यह सिद्ध हुआ कि सब कुछ मेरा ही स्वरूप है।'),
('shankaracharya-ht:source:10.40','Śaṅkarācārya','gita.10.40','hi','translation','।।10.40।।हे परन्तप मेरी दिव्य विभूतियोंका अर्थात् विस्तारका अन्त नहीं है। क्योंकि सर्वात्मरूप ईश्वरकी दिव्य विभूतियाँ इतनी ही है इस प्रकार किसीके द्वारा भी जाना या कहा नहीं जा सकता। यह तो अपनी विभूतियोंका विस्तार मेरेद्वारा संक्षेपसे अर्थात् एक अंशसे ही कहा गया है।'),
('shankaracharya-ht:source:10.41','Śaṅkarācārya','gita.10.41','hi','translation','।।10.41।।संसारमें जोजो भी पदार्थ विभूतिमान् -- विभूतियुक्त हैं तथा श्रीमान् और ऊर्जित ( शक्तिमान् ) अर्थात् श्री -- लक्ष्मी? उससे युक्त और उत्साहयुक्त हैं उनउनको तू मुझ ईश्वरके तेजोमय अंशसे उत्पन्न हुए ही जान। अर्थात् मेरे तेजका एक अंश -- भाग ही जिनकी उत्पत्तिका कारण है? इन सब वस्तुओंको ऐसी जान।'),
('shankaracharya-ht:source:10.42','Śaṅkarācārya','gita.10.42','hi','translation','।।10.42।।अथवा हे अर्जुन इस उपर्युक्त प्रकारसे वर्णन किये हुए अधूरे विभूतिविस्तारके जाननेसे तेरा क्या ( प्रयोजन सिद्ध ) होगा? ( तू तो बस? ) यह सम्पूर्णतासे कहा जानेवाला अभिप्राय ही सुन ले -- मैं एक अंशसे अर्थात् सर्व भूतोंका आत्मरूप जो मेरा एक अवयव है उससे? इस सारे जगत्को विशेष रूपसे दृढ़तापूर्वक धारण करके स्थित हो रहा हूँ। ऐसा ही वेदमन्त्र भी कहते हैं कि समस्त भूत इस परमेश्वरका एक पाद है। इत्यादि।'),
('shankaracharya-ht:source:11.1','Śaṅkarācārya','gita.11.1','hi','translation','।।11.1।।( पूर्वाध्यायमें जो ) भगवान्की विभूतियोंका वर्णन किया गया है उसमें भगवान्से कहे हुए मैं इस सारे जगत्को एक अंशसे व्याप्त करके स्थित हूँ इन वचनोंको सुनकर ईश्वरका जो जगदात्मक आदि स्वरूप है उसका प्रत्यक्ष दर्शन करनेकी इच्छासे अर्जुन बोला --, मुझपर अनुग्रह करनेके लिये आपने जो परम -- अत्यन्त श्रेष्ठ? गुह्य -- गोपनीय? अध्यात्य नामक अर्थात् आत्माअनात्माके विवेचनविषयक वाक्य कहे हैं? उन आपके वचनोंसे मेरा यह मोह नष्ट हो गया है अर्थात् मेरी अविवेकबुद्धि नष्ट हो गयी है।,'),
('shankaracharya-ht:source:11.2','Śaṅkarācārya','gita.11.2','hi','translation','।।11.2।।तथा --, मैंने आपसे प्राणियोंके भव -- उत्पत्ति और अप्यय -- प्रलय? ये दोनों संक्षेपसे नहीं? विस्तारपूर्वक सुने हैं और हे कमलपत्राक्ष अर्थात् कमलपत्रके सदृश नेत्रोंवाले कृष्ण आपका अविनाशी -- अक्षय माहात्म्य भी मैं सुन चुका हूँ। श्रुतम् यह क्रियापद पूर्ववाक्यसे लिया गया है।'),
('shankaracharya-ht:source:11.3','Śaṅkarācārya','gita.11.3','hi','translation','।।11.3।।हे परमेश्वर आप अपनेको जिस प्रकारसे बतलाते हैं? आप ठीक वैसे ही हैं अन्यथा नहीं। तथापि हे पुरुषोत्तम ज्ञान? ऐश्वर्य? शक्ति? बल? वीर्य और तेजसे युक्त आपके ऐश्वर्यमय वैष्णवरूपको मैं देखना चाहता हूँ।'),
('shankaracharya-ht:source:11.4','Śaṅkarācārya','gita.11.4','hi','translation','।।11.4।।हे स्वामिन् यदि मुझ अर्जुनद्वारा आप अपना वह रूप देखा जाना सम्भव समझते हैं? तो हे योगेश्वर अर्थात् योगियोंके ईश्वर मैं आपके उस रूपका दर्शन करनेकी उत्कट इच्छा करता हूँ? इसलिये आप मुझे अपना वह अविनाशी स्वरूप दिखलाइये।,'),
('shankaracharya-ht:source:11.5','Śaṅkarācārya','gita.11.5','hi','translation','।।11.5।।अर्जुन इस प्रकार प्रेरित हुए श्रीभगवान् बोले --, हे पार्थ तू मेरे सैकड़ोंहजारों अर्थात् अनेकों रूपोंको देख? जो कि नाना प्रकारके भेदवाले और दिव्य अर्थात् देवलोकमें होनेवाले -- अलौकिक हैं तथा नाना प्रकारके वर्ण और आकृतिवाले हैं अर्थात् जिनके नील? पीत आदि नाना प्रकारके वर्ण और अनेक आकारवाले अवयव हैं? ऐसे रूपोंको देख।'),
('shankaracharya-ht:source:11.6','Śaṅkarācārya','gita.11.6','hi','translation','।।11.6।।हे भारत तू द्वादश आदित्योंको? आठ वसुओंको ? एकादश रुद्रोंको? दोनों अश्विनीकुमारोंको और उनचास मरुद्गणोंको देख। तथा और भी जिन्हें मनुष्यलोकमें तूने अथवा और किसीने भी कभी नहीं देखा? ऐसे बहुतसे आश्चर्यमय -- अद्भुत दृश्य देख।'),
('shankaracharya-ht:source:11.7','Śaṅkarācārya','gita.11.7','hi','translation','।।11.7।।केवल इतना ही नहीं --, हे गुडाकेश अब तू मेरे इस शरीरमें एक ही स्थानमें स्थित चराचरसहित सारे जगत्को देख ले। तथा और भी जो कुछ जयपराजय आदि दृश्य जिसके लिये तू हम उनको जीतेंगे या वे हमको जीतेंगे इस प्रकार शङ्का करता था? वह सब या अन्य जो कुछ यदि देखना चाहता हो तो देख ले।'),
('shankaracharya-ht:source:11.8','Śaṅkarācārya','gita.11.8','hi','translation','।।11.8।।किंतु --, तू मुझ विश्वरूपधारी परमेश्वरको अपने इन प्राकृत नेत्रोंसे नहीं देख सकेगा। जिन दिव्य नेत्रोंद्वारा तू मुझे देख सकेगा? वे दिव्य नेत्र ( मैं ) तुझे देता हूँ? उनके द्वारा तू मुझ ईश्वरके ऐश्वर्य और योगको अर्थात् अतिशय योगसामर्थ्यको देख।,'),
('shankaracharya-ht:source:11.9','Śaṅkarācārya','gita.11.9','hi','translation','।।11.9।।संजय बोला -- हे राजा धृतराष्ठ्र इस प्रकार कहनेके अनन्तर महायोगेश्वर श्रीहरिने यानी जो अति महान् और योगेश्वर भी हैं उन नारायणने पृथापुत्र अर्जुनको अपना ईश्वरीय परम रूप -- विराट्स्वरूप दिखलाया।'),
('shankaracharya-ht:source:11.10','Śaṅkarācārya','gita.11.10','hi','translation','।।11.10।।जो अनेक मुख और नेत्रोंवाला है अर्थात् जिस रूपमें अनेक मुख और नेत्र हैं? तथा अनेक अद्भुत दृश्योंवाला है अर्थात् जिसमें आश्चर्य उत्पन्न करनेवाले अनेक दृश्य हैं? जो अनेक दिव्य भूषणोंसे युक्त है यानी जिसमें अनेक दिव्य आभूषण हैं और जो हाथमें उठाये हुए अनेक दिव्य शस्त्रोंसे युक्त है यानी जिस रूपके हाथोंमें अनेक दिव्य शस्त्र उठाये हुए हैं? ऐसा वह रूप भगवान्ने अर्जुनको दिखलाया। इस श्लोकका पूर्वश्लोकके दर्शयामास शब्दसे सम्बन्ध है।,'),
('shankaracharya-ht:source:11.11','Śaṅkarācārya','gita.11.11','hi','translation','।।11.11।।तथा --, जिस ईश्वरने दिव्य पुष्पमालाओं और वस्त्रोंको धारण कर रक्खा है? जिसने दिव्य गन्धका अनुलेपन कर रक्खा है? जो समस्त आश्चर्यमय दृश्योंसे युक्त है? जो सब भूतोंका आत्मा होनेके कारण सब ओर मुखवाला है तथा जिसका अन्त नहीं है ऐसा अनन्त और दिव्य विराट्रूप भगवान्ने अर्जुनको दिखलाया? इस प्रकार पूर्वश्लोकसे अन्वय कर लेना चाहिये अथवा अर्जुनने ऐसा रूप देखा इस प्रकार अध्याहार कर लेना चाहिये।,'),
('shankaracharya-ht:source:11.12','Śaṅkarācārya','gita.11.12','hi','translation','।।11.12।।भगवान्के विराट्रूपकी जो प्रभा -- प्रकाश है? उसकी उपमा कहते हैं --, द्युलोकमें अर्थात् आकाशमें या तीसरे स्वर्गलोकमें एक साथ उदय हुए हजारों सूर्योंका जो एक साथ उत्पन्न हुआ प्रकाश हो? वह प्रकाश उस महात्मन् -- विश्वरूपके प्रकाशके सदृश कदाचित् हो तो हो? अथवा सम्भव है कि न भी हो अर्थात् उससे भी विश्वरूपका प्रकाश ही अधिक हो सकता है।'),
('shankaracharya-ht:source:11.13','Śaṅkarācārya','gita.11.13','hi','translation','।।11.13।। तथा --, उस समय पाण्डुपुत्र अर्जुनने देव? पितृ और मनुष्यादि भेदसे अनेक प्रकार विभक्त हुए समस्त जगत्को उस विश्वरूप देवाधिदेव हरिके शरीरमें ही एकत्र स्थित देखा।'),
('shankaracharya-ht:source:11.14','Śaṅkarācārya','gita.11.14','hi','translation','।।11.14।।फिर? उसको देखकर वह धनंजय आश्चर्ययुक्त और प्रफुल्लित रोमवाला हो गया अर्थात् उसके रोंगटे खड़े हो गये? फिर वह विश्वरूपधारी परमात्मदेवको शिरसे प्रणाम करके अर्थात् नम्रतापूर्वक भली प्रकार नमस्कार करके पुनः नमस्कारके लिये हाथ जोड़कर बोला।,'),
('shankaracharya-ht:source:11.15','Śaṅkarācārya','gita.11.15','hi','translation','।।11.15।।जो विश्वरूप आपने मुझे दिखलाया है उसे मैं किस प्रकार देख रहा हूँ -- ऐसा अपना अनुभव प्रकट करता हुआ अर्जुन बोला --, हे देव मैं आपके शरीरमें समस्त देवोंको तथा स्थावरजङ्गमरूप नाना प्रकारकी विभक्त आकृतिवाले समस्त भूतविशेषोंके समूहोंको एवं कमलासनपर विराजमान अर्थात् पृथ्वीरूप कमलमें सुमेरुरूप कर्णिकापर बैठे हुए प्रजाके शासनकर्ता चतुर्मुख ब्रह्माको? वसिष्ठादि ऋषियोंको और वासुकि प्रभृति समस्त दिव्य अर्थात् देवलोकमें होनेवाले सर्पोंको देख रहा हूँ।'),
('shankaracharya-ht:source:11.16','Śaṅkarācārya','gita.11.16','hi','translation','।।11.16।।मैं आपको अनेकों भुजा? उदर? मुख और नेत्रोंवाला अर्थात् आपके जिस स्वरूपमें अनेकों भुजा? उदर? मुख और नेत्र हैं ऐसे रूपवाला तथा सब ओरसे अनन्त रूपवाला अर्थात् जिसके सर्वत्र अनन्त रूप हैं ऐसा? देख रहा हूँ। हे विश्वेश्वर हे विश्वरूप मैं आपका न तो अन्त अर्थात् समाप्ति? न मध्य अर्थात् आदि और अन्तके बीचकी अवस्था और न आदि ही देखता हूँ? अभिप्राय यह कि मुझे आप परमात्मदेवका न अन्त दिखलायी देता है? न मध्य दीखता है और न आपका आदि ही दिखलायी देता है।'),
('shankaracharya-ht:source:11.17','Śaṅkarācārya','gita.11.17','hi','translation','।।11.17।। तथा --, शिरके भूषणविशेषका नाम किरीट है? वह जिसके शिरपर हो उसे किरीटी कहते हैं। जिसके पास गदा हो वह गदी है। जिसके हाथमें चक्र हो वह चक्री है। इस प्रकार? मैं आपको किरीटी -- किरीटयुक्त? गदीगदायुक्त? चक्रीचक्रयुक्त? तेजोराशि -- तेजका समूह और सर्वतोदीप्तिमान् -- सब ओरसे दीप्तिशाली देख रहा हूँ। तथा आपको दुर्निरीक्ष्य -- जो कठिनतासे देखा जा सके ऐसा? एवं सब ओरसे प्रज्वलित अग्नि और सूर्यके समान प्रकाशमय और बुद्धि आदिसे जिसका ग्रहण न हो सके? ऐसा अप्रमेयस्वरूप देखता हूं? प्रदीप्त यानी प्रकाशित अग्नि और अर्क यानी सूर्य इन दोनोंके समान जिसका प्रकाश -- तेज हो उसका नाम दीप्तानलार्कद्युति है।,'),
('shankaracharya-ht:source:11.18','Śaṅkarācārya','gita.11.18','hi','translation','।।11.18।।इसीलिये अर्थात् आपकी योगशक्तिको देखकर ही मैं अनुमान करता हूँ --, आप मुमुक्षु पुरुषोंद्वारा जाननेयोग्य परमअक्षर अर्थात् जिसका कभी नाश न हो ऐसे परमब्रह्म परमात्मा हैं। आप ही इस समस्त जगत्के परम उत्तम निधान हैं -- जिसमें कोई वस्तु रक्खी जाय उसे निधान कहते हैं? सो आप इस संसारके परम आश्रय हैं। इसके सिवा आप अविनाशी हैं अर्थात् आपका कभी नाश नहीं होता? इसलिये आप नाशरहित हैं और सनातनधर्मके रक्षक हैं अर्थात् जो सदासे है? ऐसे नित्यधर्मके आप रक्षक हैं और आप ही सनातन परमपुरुष हैं -- यह मेरा मत है।'),
('shankaracharya-ht:source:11.19','Śaṅkarācārya','gita.11.19','hi','translation','।।11.19।। तथा --, ( मैं ) आपको आदि? मध्य और अन्तसे रहित अर्थात् जिसका आदि? मध्य और अन्त नहीं है? ऐसे रूपवाला और अनन्तवीर्य -- अनन्त सामर्थ्यसे युक्त देखता हूँ? आपकी सामर्थ्यका अन्त नहीं है? इसलिये आप अनन्तवीर्य हैं तथा मैं आपको अनन्त भुजाओंसे युक्त? चन्द्रमा और सूर्यरूप नेत्रोंवाला? प्रज्वलित अग्निरूप मुखोंवाला और अपने तेजसे इस जगत्को तपायमान करते हुए देखता हूँ अर्थात् जिस रूपके अनन्त हाथ हों? चन्द्रमा और सूर्य ही जिसके नेत्र हों? प्रज्वलित अग्नि ही जिसका मुख हो और जो अपने तेजसे इस सारे विश्वको तपायमान करता हो? ऐसा रूप धारण किये आपको देख रहा हूँ।'),
('shankaracharya-ht:source:11.20','Śaṅkarācārya','gita.11.20','hi','translation','।।11.20।।एकमात्र आप विश्वरूपधारी परमेश्वरसे ही यह स्वर्ग और पृथिवीके बीचका सारा आकाश और समस्त दिशाएँ भी परिपूर्ण हो रही हैं। हे महात्मन् अर्थात् हे अक्षुद्र स्वभाववाले कृष्ण आपके इस अद्भुत -- आश्चर्यजनक? भयंकर -- क्रूर रूपको देखकर तीनों लोक व्यथित हो रहे हैं अर्थात् भयभीत या विचलित हो रहे हैं।,'),
('shankaracharya-ht:source:11.21','Śaṅkarācārya','gita.11.21','hi','translation','।।11.21।।अर्जुनके मनमें जो पहले ऐसा संशय था कि हम उनको जीतेंगे या वे हमको जीतेंगे उसका निर्णय करनेके लिये मैं पाण्डवोंकी निश्चित विजय दिखलाऊँगा इस भावसे प्रवृत्त हुए भगवान् अपना वैसा रूप दिखाने लगे? उस रूपको देखकर अर्जुन बोला --, यह युद्ध करनेवाले योद्धास्वरूप देवगण? यानी जो भूमिका भार उतारनेके लिये यहाँ अवतीर्ण हुए हैं? वे मनुष्योंकीसी आकृतिवाले वस्वादि देवसमुदाय आपमें ( दौड़दौड़कर ) प्रवेश कर रहे हैं अर्थात् प्रवेश करते हुए दिखलायी दे रहे है। उनमेंसे अन्य कोईकोई तो भागनेमें असमर्थ होनेके कारण भयभीत होकर हाथ जोड़े हुए आपकी स्तुति कर रहे हैं। तथा महर्षियों और सिद्धोंके समुदाय युद्ध आरम्भ होनेपर उत्पात आदि अशुभ चिह्नोंको देखकर संसारका कल्याण हो ऐसा कहकर अनेकों अर्थात् सम्पूर्ण स्तोत्रोंद्वारा आपकी स्तुति कर रहे हैं।'),
('shankaracharya-ht:source:11.22','Śaṅkarācārya','gita.11.22','hi','translation','।।11.22।।तथा और भी --, जो रुद्र? आदित्य? वसु और साध्य आदि देवगण हैं? एवं जो विश्वेदेव? दोनों अश्विनीकुमार? वायुदेव और ऊष्मपा नामक पितृगण हैं तथा जो गन्धर्व? यक्ष? असुर और सिद्धोंके समुदाय हैं यानी हाहाहूहू आदि गन्धर्व? कुबेरादि यक्ष? विरोचनादि असुर और कपिलादि सिद्ध इन सबके समुदाय हैं? वे सभी आश्चर्ययुक्त हुए आपको देख रहे हैं।,'),
('shankaracharya-ht:source:11.23','Śaṅkarācārya','gita.11.23','hi','translation','।।11.23।।क्योंकि --, हे महाबाहो आपका यह रूप अति महान् -- बहुत लंबाचौड़ा? अनेकों मुख और नेत्रोंवाला -- जिसके अनेकों मुख और नेत्र हैं ऐसा? बहुतसी भुजाओं? जंघाओं और चरणोंवाला -- जिसके बहुतसी भुजाएँ? जंघाएँ और चरण हैं ऐसा? तथा बहुतसे पेटोंवाला -- जिसके बहुतसे पेट हैं ऐसा और बहुतसी दाढ़ोंसे अति विकराल आकृतिवाला है अर्थात् बहुतसी दाढ़ोंके कारण जिसकी आकृति अति भयंकर हो गयी है? ऐसा है। आपके ऐसे ( विकट ) रूपको देखकर संसारके समस्त प्राणी भयसे व्याकुल हो रहे हैं -- काँप रहे हैं? और मैं भी उन्हींकी भाँति भयभीत हो रहा हूँ।,'),
('shankaracharya-ht:source:11.24','Śaṅkarācārya','gita.11.24','hi','translation','।।11.24।।उसमें यह कारण है कि --, आपके आकाशका स्पर्श किये हुए यानी स्वर्गतक व्याप्त? प्रदीप्त -- प्रकाशमान और अनेक वर्णोंवाले अर्थात् अनेक भयंकर आकृतियोंसे युक्त देखकर तथा फैलाये हुए मुखोंवाले -- जिस शरीरमें फैलाये हुए बहुतसे मुख हैं ऐसे और दीप्त विशाल नेत्रोंवाले -- जिसके बड़ेबड़े नेत्र प्रज्वलित हो रहे हैं ऐसे? देखकर हे विष्णो प्रव्यथितअन्तरात्मा -- अत्यन्त भयभीत अन्तःकरणवाला मैं अर्थात् जिसका मन भयसे व्याकुल हो रहा है ऐसा? मैं धैर्य और उपशमको अर्थात् मनकी तृप्तिरूप शान्तिको नहीं पा रहा हूँ।,'),
('shankaracharya-ht:source:11.25','Śaṅkarācārya','gita.11.25','hi','translation','।।11.25।।क्योंकि --, दाढ़ोंसे युक्त भयंकर -- विकराल आकृतिवाले और कालाग्निके समान अर्थात् प्रलयकालमें लोकोंको भस्मीभूत करनेवाली जो कालाग्नि है? उसके समान आपके मुखोंको देखकर मैं इन दिशाओंको पूर्व और पश्चिमके विवेकपूर्वक नहीं जानता हूँ अर्थात् मुझे दिग्भ्रम हो गया है। इसीसे ( आपके स्वरूपका दर्शन करते हुए भी ) मुझे विश्राम -- सुख नहीं मिल रहा है? सो हे देवेश हे जगन्निवास आप प्रसन्न होइये।,'),
('shankaracharya-ht:source:11.26','Śaṅkarācārya','gita.11.26','hi','translation','।।11.26।।जिन शूरवीरोंसे मुझे पहले पराजयकी आशङ्का थी? वह भी अब चली गयी क्योंकि --, ये दुर्योधन आदि धृतराष्ट्रके समस्त पुत्र अवनिपालोंके दलोंसहित -- अवनि यानी पृथ्वीका जो पालन करें उनका नाम अवनिपाल है। उनके दलोंसहित इकट्ठे होकर बड़े वेगसे आपके मुखोंमें प्रवेश कर रहे हैं। यही नहीं? किंतु भीष्म? द्रोण और यह सूतपुत्र -- कर्ण एवं हमारी ओरके भी धृष्टद्युम्नादि प्रधान योद्धाओंके सहित ( सबसेसब )।'),
('shankaracharya-ht:source:11.27','Śaṅkarācārya','gita.11.27','hi','translation','।।11.27।। तथा --, शीघ्रतासे -- बड़ी जल्दीके साथ आपके मुखोंमें प्रवेश कर रहे हैं। किस प्रकारके मुखोंमें दाढ़ोंवाले विकराल भयंकर मुखोंमें। तथा उन मुखोंमें प्रविष्ट हुए पुरुषोंमेंसे भी कितने ही विचूर्णित मस्तकोंसहित दाँतोंके बीचमें भक्षण किये हुए मांसकी भाँति चिपके हुए दीख रहे हैं।'),
('shankaracharya-ht:source:11.28','Śaṅkarācārya','gita.11.28','hi','translation','।।11.28।।वे किस प्रकार मुखोंमें प्रवेश करते हैं? सो कहते हैं --, जैसे चलती हुई नदियोंके बहुतसे जलप्रवाह बड़े वेगसे समुद्रके सम्मुख हुए ही दौड़ते हैं -- समुद्रमें ही प्रवेश करते हैं? वैसे ही यह मनुष्यलोकके शूरवीर भीष्मादि आपके प्रज्वलित प्रकाशमान मुखोंमें प्रवेश कर रहे हैं।'),
('shankaracharya-ht:source:11.29','Śaṅkarācārya','gita.11.29','hi','translation','।।11.29।।वे किसलिये और किस प्रकार प्रवेश कर रहे हैं? सो कहते हैं --, जैसे पतंग -- पक्षीगण अपने नाशके लिये दौड़दौड़कर अत्यन्त वेगसे प्रदीप्त अग्निमें प्रवेश करते हैं? वैसे ही ( ये सब ) प्राणी भी नष्ट होनेके लिये दौड़दौड़कर अत्यन्त वेगके साथ आपके मुखोंमें प्रवेश कर रहे हैं। जिनका वेग -- गति बढ़ी हुई हो? वे समृद्धवेग कहलाते हैं।,'),
('shankaracharya-ht:source:11.30','Śaṅkarācārya','gita.11.30','hi','translation','।।11.30।।और आप --, ( उन ) समस्त लोकोंको देदीप्यमान मुखोंद्वारा सब ओरसे निगलते हुए चाट रहे हैं अर्थात् उनका आस्वादन कर रहे हैं। तथा हे विष्णो -- व्यापनशील परमात्मन् आपकी उग्र -- कठोर प्रभाएँ समग्र जगत्को अर्थात् समस्त जगत्को अपने तेजसे व्याप्त करके तप रही हैं -- तेज फैला रही हैं।,'),
('shankaracharya-ht:source:11.31','Śaṅkarācārya','gita.11.31','hi','translation','।।11.31।।क्योंकि आप ऐसे उग्र स्वभाववाले हैं? इसलिये --, मुझे बतलाइये कि भयंकर आकारवाले आप कौन हैं हे देववर अर्थात् देवोंमें प्रधान आपको नमस्कार हो? आप कृपा करें। सृष्टिके आदिसे होनेवाले आप परमेश्वरको मैं भली प्रकार जानना चाहता हूँ? क्योंकि मैं आपकी प्रवृत्ति अर्थात् चेष्टाको नहीं समझ रहा हूँ।,'),
('shankaracharya-ht:source:11.32','Śaṅkarācārya','gita.11.32','hi','translation','।।11.32।।श्रीभगवान् बोले -- मैं लोकोंका नाश करनेवाला बढ़ा हुआ काल हूँ। मैं जिसलिये बढ़ा हूँ वह सुन? इस समय मैं लोकोंका संहार करनेके लिये प्रवृत्त हुआ हूँ? इससे तेरे बिना भी ( अर्थात् तेरे युद्ध न करनेपर भी ) ये सब भीष्म? द्रोण और कर्ण प्रभृति शूरवीर -- योद्धालोग जिनसे तुझे आशङ्का हो रही है एवं जो प्रतिपक्षियोंकी प्रत्येक सेनामें अलगअलग डटे हुए हैं -- नहीं रहेंगे।,'),
('shankaracharya-ht:source:11.33','Śaṅkarācārya','gita.11.33','hi','translation','।।11.33।।क्योंकि ऐसा है --, इसलिये तू खड़ा हो और देवोंसे भी न जीते जानेवाले भीष्म? द्रोण आदि महारथियोंको अर्जुनने जीत लिया ऐसे निर्मल यशको लाभ कर। ऐसा यश पुण्योंसे ही मिलता है। दुर्योधनादि शत्रुओंको जीतकर समृद्धिसम्पन्न निष्कण्टक राज्य भोग। ये सब ( शूरवीर ) मेरेद्वारा निःसन्देह पहले ही मारे हुए हैं अर्थात् प्राणविहीन किये हुए हैं। हे सव्यसाचिन् तू केवल निमित्तमात्र बन जा। बायें हाथसे भी बाण चलानेका अभ्यास होनेके कारण अर्जुन सव्यसाची कहलाता है।'),
('shankaracharya-ht:source:11.34','Śaṅkarācārya','gita.11.34','hi','translation','।।11.34।।द्रोण आदि जिनजिन शूरवीरोंसे अर्जुनको आशङ्का थी ( जिनके कारण पराजय होनेका डर था ) उनउनका नाम लेकर भगवान् कहते हैं कि तू मुझसे मारे हुओंको मार इत्यादि। उनमेंसे द्रोण और भीष्मसे भय होनेका कारण प्रसिद्ध ही है क्योंकि द्रोण तो धनुर्वेदके आचार्य दिव्य अस्त्रोंसे युक्त और विशेषरूपसे अपने सर्वोत्तम गुरु हैं तथा भीष्म सबसे बड़े स्वेच्छामृत्यु और दिव्य अस्त्रोंसे सम्पन्न हैं जो कि परशुरामजीके साथ द्वन्द्व युद्ध करनेपर भी उनसे पराजित नहीं हुए। वैसा ही जयद्रथ भी है जिसका पिता इस उद्देश्यसे तप कर रहा है कि जो कोई मेरे पुत्रका शिर भूमिपर गिरावेगा? उसका भी शिर गिर जायगा। कर्ण भी ( बड़ा शूरवीर है ) क्योंकि वह इन्द्रद्वारा दी हुई अमोघ शक्ितसे युक्त है और कन्यासे जन्मा हुआ सूर्यका पुत्र है? इसलिये उसके नामका भी निर्देश किया गया है। ( अभिप्राय यह कि द्रोण? भीष्म? जयद्रथ और कर्ण? तथा अन्यान्य शूरवीर योद्धा ) जो कि मेरेद्वारा मारे हुए,हैं? उनको तू निमित्तमात्रसे मार? उनसे भय मत कर। युद्ध कर? तू संग्राममें दुर्योधनादि शत्रुओंको जीतेगा।'),
('shankaracharya-ht:source:11.35','Śaṅkarācārya','gita.11.35','hi','translation','।।11.35।।संजय बोला -- केशवके इनउपर्युक्त वचनोंको सुनकर अर्जुन काँपता हुआ हाथ जोड़कर नमस्कार करके फिर श्रीकृष्णसे इस प्रकार गद्गद वाणीसे बोला। जब दुःख प्राप्त होनेके कारण भयभीत पुरुषके और हर्षोत्पत्तिके कारण स्नेहयुक्त पुरुषके नेत्र आँसुओंसे परिपूर्ण हो जाते हैं और कण्ठ कफसे रुक जाता है? उस समय जो वाणीमें अपटुता और शब्दमें मन्दता हो जाती है? उसका नाम गद्गद है? जो उससे युक्थ थे ऐसे सगद्गद वचन बोला। यहाँ सगद्गद शब्द बोलनारूप क्रियाका विशेषण है। इस प्रकार भयभीतभयसे बारंबार विह्वलचित्त हुआ प्रणाम करके अत्यन्त नम्र होकर बोला। यहाँपर संजयके वचन इस गूढ़ अभिप्रायसे भरे हुए हैं कि द्रोणादि चार अजेय शूरवीरोंका अर्जुनके द्वारा नाश हो जानेपर आश्रयरहित दुर्योधन तो मरा हुआ ही है? ऐसा मानकर विजयसे निराश हुआ धृतराष्ट्र सन्धि कर लेगा और उससे दोनों पक्षवालोंकी शान्ति हो जायगी। परंतु भावीके वशमें होकर धृतराष्ट्रने ऐसे वचन भी नहीं सुने।,'),
('shankaracharya-ht:source:11.36','Śaṅkarācārya','gita.11.36','hi','translation','।।11.36।।अर्जुन बोला -- यह उचित ही है। वह क्या कि हे हृषीकेश आपकी कीर्तिसे अर्थात् आपकी महिमाका कीर्तन और श्रवण करनेसे जो जगत् हर्षित हो रहा है सो उचित ही है। अथवा स्थाने यह शब्द विषयका विशेषण भी समझा जा सकता है। भगवान् हर्ष आदिके विषय हैं? यह मानना भी ठीक ही है? क्योंकि ईश्वर सबका आत्मा और सब भूतोंका सुहृद् है। यहाँ ऐसी व्याख्या करनी चाहिये कि जगत् जो भगवान्में अनुराग -- प्रेम करता है? यह उसका अनुराग करना उचित विषयमें ही है तथा राक्षसगण भयसे युक्त हुए सब दिशाओंमें भाग रहे हैं? यह भी ठीकठिकानेकी ही बात है। एवं समस्त कपिलादि सिद्धोंके समुदाय जो नमस्कार कर रहे हैं? यह भी उचित विषयमें ही है।'),
('shankaracharya-ht:source:11.37','Śaṅkarācārya','gita.11.37','hi','translation','।।11.37।।भगवान् हर्षादि भावोंके योग्य स्थान किस प्रकार हैं इसमें कारण दिखाते हैं --, हे महात्मन् आप जो अतिशय गुरुतर हैं अर्थात् सबसे बड़े हैं? उनको ये सब किसलिये नमस्कार न करें क्योंकि आप हिरण्यगर्भके भी आदिकर्ता -- कारण हैं? अतः आप आदिकर्ताको कैसे नमस्कार न करें। अभिप्राय यह कि उपर्युक्त कारणसे आप हर्षादिके और नमस्कारके योग्य पात्र हैं। हे अनन्त हे देवेश हे जगन्निवास वह परम अक्षर ( ब्रह्म ) आप ही हैं? जो वेदान्तोंमें सुना जाता है। वह क्या है सत् और असत् -- जो विद्यमान है वह सत् और जिसमें नहीं है ऐसी बुद्धि होती है वह असत् है। वे दोनों सत् और असत् जिस अक्षरकी उपाधि हैं? जिनके कारण वह ब्रह्म उपचारसे सत् और असत् कहा जाता है परंतु वास्तवमें जो सत् और असत् दोनोंसे परे है? जिसको वेदवेत्ता लोग अक्षर कहते हैं वह ब्रह्म भी आप ही हैं। अभिप्राय यह कि आपसे अतिरिक्त दूसरा कोई नहीं है।,'),
('shankaracharya-ht:source:11.38','Śaṅkarācārya','gita.11.38','hi','translation','।।11.38।।अर्जुन फिर भी स्तुति करता है --, आप जगत्के रचयिता होनेके कारण आदिदेव हैं और शरीररूप पुरमें रहनेके कारण सनातन पुरुष हैं तथा आप ही इस विश्वके परम उत्तम स्थान हैं अर्थात् महाप्रलयादिमें समस्त जगत् जिसमें स्थित होता है वह ( जगत्का आश्रय ) आप ही हैं। तथा समस्त जाननेयोग्य वस्तुओंके आप जाननेवाले हैं और जो जाननेयोग्य हैं वह भी आप ही हैं। आप ही परम धाम -- परम वैष्णवपद हैं। हे अनन्तरूप समस्त विश्व आपसे परिपूर्ण है -- व्याप्त है। आपके रूपोंका अन्त नहीं है।,'),
('shankaracharya-ht:source:11.39','Śaṅkarācārya','gita.11.39','hi','translation','।।11.39।।तथा --, आप ही वायु? यम? अग्नि? जलके राजा वरुण? चन्द्रमा और कश्यपादि प्रजापति हैं और आप ही पितामहके भी पिता प्रपितामह हैं अर्थात् ब्रह्माके भी पिता हैं। आपको हजारों बार नमस्कार हो? नमस्कार हो फिर भी बारंबार आपको नमस्कार हो? नमस्कार हो। सहस्र शब्दसे कृत्वसुच् प्रत्यय कर देनेसे अनेकोंबार नमस्कार क्रियाके अभ्यास और आवृत्तिकी गणनाका प्रतिपादन हो जाता है परंतु फिर भी पुनश्च भूयोऽपि इन शब्दोंसे अर्जुन अतिशय श्रद्धा और भक्तिके कारण नमस्कार करताकरता मैं तृप्त नहीं हुआ हूँ ऐसा अपना भाव दिखलाता है।,'),
('shankaracharya-ht:source:11.40','Śaṅkarācārya','gita.11.40','hi','translation','।।11.40।।तथा --, आपको आगसे अर्थात् पूर्वदिशामें और पीछेसे भी नमस्कार है। हे सर्वरूप आपको सब ओरसे नमस्कार है अर्थात् सर्वत्र स्थित हुए आपको सब दिशाओंमें नमस्कार है। आप अनन्तवीर्य और अपार पराक्रमवाले हैं। वीर्य सामर्थ्यको कहते हैं और विक्रम पराक्रमको। कोई व्यक्ति सामर्थ्यवान् होकर भी शस्त्रादि चलानेमें पराक्रम नहीं दिखा सकता? अथवा मन्दपराक्रमी होता है। परन्तु आप तो अनन्तवीर्य और अमित पराक्रमसे युक्त हैं। इसलिये आप अनन्तवीर्य और अमितपराक्रमी हैं। आप अपने एक स्वरूपसे सारे जगत्को व्याप्त किये हुए स्थित हैं? इसलिये आप सर्वरूप हैं? अर्थात् आपसे अतिरिक्त कुछ भी नहीं है।,'),
('shankaracharya-ht:source:11.41','Śaṅkarācārya','gita.11.41','hi','translation','।।11.41।।क्योंकि मैं आपकी महिमाको न जाननेका अपराधी रहा हूँ? इसलिये --, आपकी महिमाको अर्थात् आप ईश्वरके इस विश्वरूपको न जाननेवाले मुझ मूढ़द्वारा विपरीत बुद्धिसे आपको मित्रसमान अवस्थावाला समझकर जो अपमानपूर्वक हठसे हे कृष्ण हे यादव हे सखे इत्यादि वचन कहे गये हैं -- तव इदं महिमानम् अजानता इस पाठमें इदम् शब्द नपुंसक लिङ्ग है और महिमानम् शब्द पुंल्लिङ्ग है? अतः इनका आपसमें वैयधिकरण्यसे विशेष्यविशेषणभावसम्बन्ध है। यदि इदम् की जगह इमम् पाठ हो तो सामानाधिकरण्यसे सम्बन्ध हो सकता है। इसके सिवा प्रमादसे यानी विक्षिप्तचित्त होनेके कारण अथवा प्रणयसे भी -- स्नेहनिमित्तक विश्वासका नाम प्रणय है? उसके कारण भी मैंने जो कुछ कहा है।'),
('shankaracharya-ht:source:11.42','Śaṅkarācārya','gita.11.42','hi','translation','।।11.42।।तथा जो हँसीके लिये भी आप मुझसे असत्कृत -- अपमानित हुए हैं कहाँ विहार? शय्या? आसन और भोजनादिमें। विचरनारूप पैरोंसे चलनेफिरनेकी क्रियाका नाम विहार है? शयनका नाम शय्या है? स्थित होनेबैठनेका नाम आसन है और भक्षण करनेका नाम भोजन है। इन सब क्रियाओंके करते समय ( मुझसे ) अकेलेमें -- आपके पीछे अथवा आपके सामने आपका जो कुछ अपमान -- तिरस्कार हुआ है हे अच्युत उस समस्त अपराधोंके समुदायको मैं आप अप्रमेयसे अर्थात् प्रमाणातीत परमेश्वरसे क्षमा कराता हूँ। समक्षम् शब्दके पहलेका तत् शब्द क्रियाविशेषण है।,'),
('shankaracharya-ht:source:11.43','Śaṅkarācārya','gita.11.43','hi','translation','।।11.43।।क्योंकि आप --, इस स्थावरजंगमरूप समस्त जगत्के यानी प्राणिमात्रके उत्पन्न करनेवाले पिता हैं। केवल पिता ही नहीं? आप पूजनीय भी हैं? क्योंकि आप बड़ेसेबड़े गुरु हैं। आप कैसे गुरुतर हैं सो ( अर्जुन ) बतलाता है -- हे अप्रतिमप्रभाव सारी त्रिलोकीमें आपके समान दूसरा कोई नहीं है क्योंकि अनेक ईश्वर मान लेनेपर व्यवहार सिद्ध नहीं हो सकता। इसलिये ईश्वर दो नहीं हो सकते। जब कि सारे त्रिभुवनमें आपके समान ही दूसरा कोई नहीं है? फिर अधिक तो कोई हो ही कैसे सकता है जिससे किसी वस्तुकी समानता की जाय उसका नाम प्रतिमा है? जिन आपके प्रभावकी कोई प्रतिमा नहीं है? वह आप अप्रतिमप्रभाव हैं। इस प्रकार हे अप्रतिमप्रभाव अर्थात् हे निरतिशयप्रभाव ।,'),
('shankaracharya-ht:source:11.44','Śaṅkarācārya','gita.11.44','hi','translation','।।11.44।।जब कि यह बात है --, इसीलिये मैं अपने शरीरको भली प्रकार नीचा करके अर्थात् आपके चरणोंमें रखकर प्रणाम करके स्तुति करनेयोग्य शासनकर्ता आप ईश्वरको प्रसन्न करता हूँ। अर्थात् आपसे अनुग्रह कराता हूँ। जैसे पुत्रका समस्त अपराध पिता क्षमा करता है तथा जैसे मित्रका अपराध मित्र अथवा प्रियाका अपराध प्रिय ( पति ) क्षमा करता है -- सहन करता है? वैसे ही हे देव आपको भी ( मेरे समस्त अपराधोंको सर्वथा ) सहन करना अर्थात् क्षमा करना उचित है।'),
('shankaracharya-ht:source:11.45','Śaṅkarācārya','gita.11.45','hi','translation','।।11.45।।आपके जिस विश्वरूपको मैंने या अन्य किसीने पहले कभी नहीं देखा? ऐसे पहले न देखे हुए इस रूपको देखकर मैं हर्षित हो रहा हूँ। तथा साथ ही मेरा मन भयसे व्याकुल भी हो रहा है। इसलिये हे देव मुझे अपना वही रूप दिखलाइये जो मेरा मित्ररूप है। हे देवेश हे जगन्निवास आप प्रसन्न होइये। जगत्के निवासस्थानका नाम जगन्निवास है।'),
('shankaracharya-ht:source:11.46','Śaṅkarācārya','gita.11.46','hi','translation','।।11.46।।मैं आपको वैसे ही अर्थात् पहलेहीकी भाँति शिरपर मुकुट धारण किये? हाथोंमें गदा और चक्र लिये हुए देखना चाहता हूँ। जब कि यह बात है तो हे सहस्रबाहो हे विश्वमूर्ते अर्थात् वर्तमानविश्वरूपसे ( युक्त ) भगवन् आप उसी अपने वसुदेवपुत्ररूप चतुर्भुजस्वरूपसे युक्त होइये। अर्थात् इस विश्वरूपका उपसंहार करके आप वसुदेवपुत्र -- श्रीकृष्णके स्वरूपसे स्थित होइये।,');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:11.47','Śaṅkarācārya','gita.11.47','hi','translation','।।11.47।।अर्जुनको भयभीत देखकर? विश्वरूपका उपसंहार करके प्रिय वचनोंसे धैर्य देते हुए श्रीभगवान् बोले --, हे अर्जुन प्रसन्न हुए मुझ परमात्माने -- तुझपर जो अनुग्रहबुद्धि है उसका नाम प्रसाद है उससे युक्त मुझ परमेश्वरने -- अपने ऐश्वर्यकी सामर्थ्यसे यह परम श्रेष्ठ तेजोमय -- तेजसे परिपूर्ण अनन्त -- अन्तरहित सबसे पहले होनेवाला अनादि विश्वरूप तुझे दिखाया है? जो मेरा रूप तेरे सिवा पहले और किसीसे भी नहीं देखा गया।'),
('shankaracharya-ht:source:11.48','Śaṅkarācārya','gita.11.48','hi','translation','।।11.48।। मेरे रूपका दर्शन करके तू निःसंदेह कृतार्थ हो गया है। इस प्रकार उस रूपदर्शनकी स्तुति करते हैं --, न तो वेद और यज्ञोंके अध्ययनद्वारा अर्थात् न तो चारों वेदोंका यथावत् अध्ययन करनेसे और न यज्ञोंका अध्ययन करनेसे ही ( मैं दर्शन दे सकता हूँ )। वेदोंके अध्ययनसे ही यज्ञोंका अध्ययन सिद्ध हो सकता था? उसपर भी जो अलग यज्ञोंके अध्ययनका ग्रहण है? वह यज्ञविषयक विशेष विज्ञानके उपलक्षणके लिये है। वैसे ही न मनुष्यके बराबर तोलकर सुवर्णादि दान करनेसे? न श्रौतस्मार्तादि अग्निहोत्ररूप क्रियाओंसे और न चान्द्रायण आदि उग्र तपोंसे ही मैं अपने ऐसे रूपका दर्शन दे सकता हूँ। हे कुरुप्रवीर जैसा विश्वरूप तुझे दिखाया गया है वैसा मैं तेरे सिवा इस मनुष्यलोकमें और किसीके द्वारा नहीं देखा जा सकता।'),
('shankaracharya-ht:source:11.49','Śaṅkarācārya','gita.11.49','hi','translation','।।11.49।।जैसा पहले दिखाया जा चुका है? वैसे मेरे इस घोर रूपको देखकर तुझे भय न होना चाहिये और विमूढभाव अर्थात् चित्तकी मूढावस्था भी नहीं होनी चाहिये। तू भयरहित और प्रसन्नमन हुआ वही अपना इष्ट यह शङ्खचक्रगदाधारी चतुर्भुजरूप फिर भी देख।,'),
('shankaracharya-ht:source:11.50','Śaṅkarācārya','gita.11.50','hi','translation','।।11.50।। संजय बोला -- इस प्रकार भगवान् वासुदेवने पूर्वोक्त वचन कहकर अर्जुनको अपनावसुदेवके घरमें प्रकट हुआ रूप दिखलाया। फिर सौम्यमूर्ति होकर अर्थात् प्रसन्न देहसे युक्त होकर महात्मा कृष्णने इस भयभीत अर्जुनको पुनःपुनः धैर्य दिया।,'),
('shankaracharya-ht:source:11.51','Śaṅkarācārya','gita.11.51','hi','translation','।।11.51।।अर्जुन बोला -- हे जनार्दन अब मैं अपने मित्रकी आकृतिमें आपके इस प्रसन्नमुख सौम्य मानुषरूपको देखकर सचेता यानी प्रसन्नचित्त हुआ हूँ और अपनी प्रकृतिको -- वास्तविक स्थितिको प्राप्त हुआ हूँ।,'),
('shankaracharya-ht:source:11.52','Śaṅkarācārya','gita.11.52','hi','translation','।।11.52।।श्रीभगवान् बोले -- मेरे जिस रूपको तूने देखा है? वह बड़ा दुर्दर्श है अर्थात् जिसका दर्शन बड़ी कठिनतासे हो? ऐसा है। देवता लोग भी मेरे इस रूपका दर्शन करनेकी सदा इच्छा करते हैं। अभिप्राय यह है कि दर्शनकी इच्छा करते हुए भी उन्होंने तेरी भाँति ( मेरा रूप ) देखा नहीं है और देखेंगे भी नहीं।,'),
('shankaracharya-ht:source:11.53','Śaṅkarācārya','gita.11.53','hi','translation','।।11.53।।किस लिये --, जिस प्रकार मुझे तूने देखा है ऐसे पहले दिखलाये हुए रूपवाला मैं न तो ऋक्? यजु? साम और अथर्व आदि चारों वेदोंसे? न चान्द्रायण आदि उग्र तपोंसे? न गौ? भूमि तथा सुवर्ण आदिके दानसे और न यजनसे ही देखा जा सकता हूँ अर्थात् यज्ञ या पूजासे भी मैं ( इस प्रकार ) नहीं देखा जा सकता।'),
('shankaracharya-ht:source:11.54','Śaṅkarācārya','gita.11.54','hi','translation','।।11.54।।तो फिर आपके दर्शन किस प्रकार हो सकते हैं इस पर कहते हैं --, भक्ितसे दर्शन हो सकते हैं? सो किस प्रकारकी भक्ितसे हो सकते हैं? यह बतलाते हैं --, हे अर्जुन अनन्य भक्ितसे अर्थात् जो भगवान्को छोड़कर अन्य किसी पृथक् वस्तुमें कभी भी नहीं होती वह अनन्य भक्ति है एवं जिस भक्तिके कारण ( भक्ितमान् पुरुषको ) समस्त इन्द्रियोंद्वारा एक वासुदेव परमात्माके अतिरिक्त अन्य किसीकी भी उपलब्धि नहीं होती? वह अनन्य भक्ित है। ऐसी अनन्य भक्ितद्वारा इस प्रकारके रूपवाला अर्थात् विश्वरूपवाला मैं परमेश्वर शास्त्रोंद्वारा जाना जा सकता हूँ। केवल शास्त्रोंद्वारा जाना जा सकता हूँ इतना ही नहीं? हे परन्तप तत्त्वसे देखा भी जा सकता हूँ अर्थात् साक्षात् भी किया जा सकता हूँ और प्राप्त भी किया जा सकता हूँ अर्थात् मोक्ष भी प्राप्त करा सकता हूँ।,'),
('shankaracharya-ht:source:11.55','Śaṅkarācārya','gita.11.55','hi','translation','।।11.55।।अब समस्त गीताशास्त्रका सारभूत अर्थ संक्षेपमें कल्याणप्राप्तिके लिये कर्तव्यरूपसे बतलाया जाता है --, जो मुझ परमेश्वरके लिये कर्म करनेवाला है और मेरे ही परायण है -- सेवक स्वामीके लिये कर्म करता है परंतु मरनेके पश्चात् पानेयोग्य अपनी परमगति उसे नहीं मानता और यह तो मेरे लिये ही कर्म करनेवाला,और मुझे ही अपनी परमगति समझनेवाला होता है? इस प्रकार परमगति मैं ही हूँ ऐसा जो मत्परायण है। तथा मेरा ही भक्त है अर्थात् जो सब प्रकारसे सब इन्द्रियोंद्वारा सम्पूर्ण उत्साहसे मेरा ही भजन करता है? ऐसा मेरा भक्त है। तथा जो धन? पुत्र? मित्र? स्त्री और बन्धुवर्गमें सङ्ग -- प्रीति -- स्नेहसे रहित है। तथा सब भूतोंमें वैरभावसे रहित है अर्थात् अपना अत्यन्त अनिष्ट करनेकी चेष्टा करनेवालोंमें भी जो शत्रुभावसे रहित है। ऐसा जो मेरा भक्त है? हे पाण्डव वह मुझे पाता है अर्थात् मैं ही उसकी परमगति हूँ? उसकी दूसरी कोई गति कभी नहीं होती। यह मैंने तुझे तेरे जाननेके लिये इष्ट उपदेश दिया है।'),
('shankaracharya-ht:source:12.1','Śaṅkarācārya','gita.12.1','hi','translation','।।12.1।।तथा विश्वरूप ( एकादश ) अध्यायमें आपने उपासनाके लिये ही मुझे सम्पूर्ण ऐश्वर्ययुक्त? सबका आदि और समस्त जगत्का आत्मारूप अपना विश्वरूप भी दिखलाया है और वह रूप दिखलाकर आपने मेरे ही लिये कर्म करनेवाला हो इत्यादि वचन भी कहे हैं। इसलिये इन दोनों पक्षोंमें कौनसा पक्ष श्रेष्ठतर है? यह जाननेकी इच्छासे मैं आपसे पूछता हूँ। इस प्रकार अर्जुन बोला --, एवम् शब्दसे जिसके आदिमें मत्कर्मकृत् यह पद है? उस पासमें ही कहे हुए श्लोकके अर्थका अर्थात् एकादश अध्यायके अन्तिम श्लोकमें कहे हुए अर्थका ( अर्जुन ) निर्देश करता है। इस प्रकार निरन्तरतासे उपर्युक्त साधनोंमें अर्थात् भगवदर्थ कर्म करने आदिमें दत्तचित्त हुए -- लगे हुए जो भक्त? अनन्य भावसे शरण होकर पूर्वदर्शित विश्वरूपधारी आप परमेश्वरकी उपासना करते हैं -- उसीका ध्यान किया करते हैं। तथा दूसरे जो समस्त वासनाओंका त्याग करनेवाले? सर्वकर्मसंन्यासी ( ज्ञानीजन ) उपर्युक्त विशेषणोंसे युक्त परम अक्षर? जो समस्त उपाधियोंसे रहित होनेके कारण अव्यक्त है? ऐसे इन्द्रियादि करणोंसे अतीत ब्रह्मकी उपासना किया करते हैं। संसारमें जो इन्द्रियादि करणोंसे जाननेमें आनेवाला पदार्थ है वह व्यक्त कहा जाता है क्योंकि अञ्ज धातुका अर्थ इन्द्रियगोचर होना ही है और यह अक्षर उससे विपरीत अकरणगोचर हैं एवं महापुरुषोंद्वारा कहे हुए विशेषणोंसे युक्त हैं? ऐसे ब्रह्मकी जो उपासना करते हैं। उन दोनोंमें श्रेष्ठतर योगवेत्ता कौन हैं अर्थात् अधिकतासे योग जाननेवाले कौन हैं।'),
('shankaracharya-ht:source:12.2','Śaṅkarācārya','gita.12.2','hi','translation','।।12.2।।श्रीभगवान् बोले -- जो कामनाओंसे रहित पूर्णज्ञानी अक्षरब्रह्मके उपासक हैं उनको अभी रहने दो? उनके प्रति जो कुछ कहना है वह आगे कहेंगे? परंतु जो दूसरे हैं -- जो भक्त मुझ विश्वरूप परमेश्वरमें मनको समाधिस्थ करके सर्व योगेश्वरोंके अधीश्वर रागादि पञ्चक्लेशरूप अज्ञानदृष्टिसे रहित मुझ सर्वज्ञ परमेश्वरकी पिछले ( एकादश ) अध्यायके अन्तिम श्लोकके अर्थानुसार निरन्तर तत्पर हुए उत्तम श्रद्धासे युक्त होकर उपासना करते हैं? वे श्रेष्ठतम योगी हैं? यह मैं मानता हूँ। क्योंकि वे लगातार मुझमें ही चित्त लगाकर रातदिन व्यतीत करते हैं? अतः उनको युक्ततम कहना उचित ही है। ,'),
('shankaracharya-ht:source:12.3','Śaṅkarācārya','gita.12.3','hi','translation','Sri Shankaracharya did not comment on this sloka'),
('shankaracharya-ht:source:12.4','Śaṅkarācārya','gita.12.4','hi','translation','।।12.4।।तथा जो इन्द्रियोंके समुदायको भली प्रकार संयम करके -- उन्हें विषयोंसे रोककर? सर्वत्र -- सब समय समबुद्धिवाले होते हैं अर्थात् इष्ट और अनिष्टकी प्राप्तिमें जिनकी बुद्धि समान रहती है? ऐसे वे समस्त भूतोंके हितमें तत्पर अक्षरोपासक मुझे ही प्राप्त करते हैं। उन अक्षरउपासकोंके सम्बन्धमें वे मुझे प्राप्त होते हैं इस विषयमें तो कहना ही क्या है क्योंकि ज्ञानीको तो मैं अपना आत्मा ही समझता हूँ यह पहले ही कहा जा चुका है। जो भगवत्स्वरूप ही हैं उन संतजनोंके विषयमें युक्ततम या अयुक्ततम कुछ भी कहना नहीं बन सकता।,'),
('shankaracharya-ht:source:12.5','Śaṅkarācārya','gita.12.5','hi','translation','।।12.5।।किंतु --, ( उनको ) क्लेश अधिकतर होता है। यद्यपि मेरे ही लिये कर्मादि करनेमें लगे हुए साधकोंको भी बहुत क्लेश होता है? परंतु जिनका चित्त अव्यक्तमें आसक्त है? उन अक्षरचिन्तक परमार्थदर्शियोंको तो देहाभिमानका परित्याग करना पड़ता है? इसलिये उन्हें और भी अधिक क्लेश उठाना पड़ता है। क्योंकि जो अक्षरात्मिका अव्यक्तगति है वह देहाभिमानयुक्त पुरुषोंको बड़े कष्टसे प्राप्त होती है? अतः उनको अधिकतर क्लेश होता है। उन अक्षरोपासकोंका जैसा आचारविचारव्यवहार होता है वह आगे ( अद्वेष्टाइत्यादि श्लोकोंसे बतलायेंगे।'),
('shankaracharya-ht:source:12.6','Śaṅkarācārya','gita.12.6','hi','translation','।।12.6।।परंतु जो समस्त कर्मोंको मुझ ईश्वरके समर्पण करके मेरे परायण होकर अर्थात् मैं ही जिनकी परमगति हूँ ऐसे होकर केवल अनन्ययोगसे अर्थात् विश्वरूप आत्मदेवको छोड़कर जिसमें अन्य अवलम्बन नहीं है? ऐसे अनन्य समाधियोगसे ही मेरा चिन्तन करते हुए मेरी उपासना करते हैं।'),
('shankaracharya-ht:source:12.7','Śaṅkarācārya','gita.12.7','hi','translation','।।12.7।।उनका क्या होता है --, हे पार्थ मुझ विश्वरूप परमेश्वरमें ही जिनका चित्त समाहित है ऐसे केवल एक मुझ परमेश्वरकी उपासनामें ही लगे हुए उन भक्तोंका मैं ईश्वर उद्धार करनेवाला होता हूँ। किससे ( उनका उद्धार करते हैं ) सो कहते हैं कि मृत्युयुक्त संसारसमुद्रसे। मृत्युयुक्त संसारका नाम मृत्युसंसार है? वही पार उतरनेमें कठिन होनेके कारण सागरकी भाँति सागर है? उससे मैं उनका विलम्बसे नहीं? किंतु शीघ्र ही उद्धार कर देता हूँ।'),
('shankaracharya-ht:source:12.8','Śaṅkarācārya','gita.12.8','hi','translation','।।12.8।।जब कि यह बात है तो --, तू मुझ विश्वरूप ईश्वरमें ही अपने संकल्प विकल्पात्मक मनको स्थिर कर और मुझमें ही निश्चय करनेवाली बुद्धिको स्थिर कर -- लगा। उससे तेरा क्या ( लाभ ) होगा सो सुन -- इसके पश्चात् अर्थात् शरीरका पतन होनेके उपरान्त तू निःसन्देह एकात्मभावसे मुझमें ही निवास करेगा? इसमें कुछ भी संशय नहीं है अर्थात् इस विषयमें संशय नहीं करना चाहिये।'),
('shankaracharya-ht:source:12.9','Śaṅkarācārya','gita.12.9','hi','translation','।।12.9।।यदि इस प्रकार यानी जैसे मैंने बतलाया है उस प्रकार तू मुझमें चित्तको अचल स्थापित नहीं कर सकता? तो फिर हे धनंजय तू अभ्यासयोगके द्वारा -- चित्तको सब ओरसे खींचकर बारंबार एक अवलम्बनमें लगानेका नाम अभ्यास है उससे युक्त जो समाधानरूप योग है? ऐसे अभ्यासयोगके द्वारा -- मुझ -- विश्वरूप परमेश्वरको प्राप्त करनेकी इच्छा कर।'),
('shankaracharya-ht:source:12.10','Śaṅkarācārya','gita.12.10','hi','translation','।।12.10।।( यदि तू ) अभ्यासमें भी असमर्थ है तो मेरे लिये कर्म करनेमें तत्पर हो -- मदर्थकर्मका नाम मत्कर्म है? उसमें तत्पर हो अर्थात् मेरे लिये कर्म करनेको ही प्रधान समझनेवाला हो। अभ्यासके बिना केवल मेरे लिये कर्म करता हुआ भी तू अन्तःकरणकी शुद्धि और ज्ञानयोगकी प्राप्तिद्वारा परमसिद्धि प्राप्त कर लेगा।'),
('shankaracharya-ht:source:12.11','Śaṅkarācārya','gita.12.11','hi','translation','।।12.11।।परंतु यदि तू ऐसा करनेमें भी अर्थात् जैसा ऊपर कहा है? उस प्रकार मेरे लिये कर्म करनेके परायण होनेमें भी असमर्थ है तो फिर मद्योगके आश्रित होकर -- किये जानेवाले समस्त कर्मोंको मुझमें समर्पण करके उनका अनुष्ठान करना मद्योग है। उसके आश्रित होकरऔर संयतात्मा होकर अर्थात् वशीभूत मनवाला होकर समस्त कर्मोंके फलका त्याग कर।,'),
('shankaracharya-ht:source:12.12','Śaṅkarācārya','gita.12.12','hi','translation','।।12.12।।अब सर्व कर्मोंके फलत्यागकी स्तुति करते हैं --, निःसंन्देह ज्ञान श्रेष्ठतर है। किससे अविवेकपूर्वक किये हुए अभ्याससे उस ज्ञानसे भी ज्ञानपूर्वक ध्यान श्रेष्ठ है? और ( इसी प्रकार ) ज्ञानयुक्त ध्यानसे भी कर्मफलका त्याग अधिक श्रेष्ठ है। पहले बतलाये हुए विशेषणोंसे युक्त पुरुषको इस कर्मफलत्यागसे तुरंत ही शान्ति हो जाती है? अर्थात् हेतुसहित समस्त संसारकी निवृत्ति तत्काल ही हो जाती है। कालान्तरकी अपेक्षा नहीं रहती। कर्मोंमें लगे हुए अज्ञानीके लिये? पूर्वोक्त उपायोंका अनुष्ठान करनेमें असमर्थ होनेपर ही? सर्वकर्मोंके फलत्यागरूप कल्याणसाधनका उपदेश किया गया है? सबसे पहले नहीं। इसलिये श्रेयो हि ज्ञानमभ्यासात् इत्यादिसे उत्तरोत्तर श्रेष्ठता बतलाकर सर्वकर्मोंके फलत्यागकी स्तुति करते हैं क्योंकि उत्तम साधनोंका अनुष्ठान करनेमें असमर्थ होनेपर यह साधन भी अनुष्ठान करने योग्य माना गया है। पू0 -- कौनसी समानताके कारण यह स्तुति की गयी हैं उ0 -- जब ( इसके हृदयमें स्थित ) समस्त कामनाएँ नष्ट हो जाती हैं इस श्रुतिसे समस्त कामनाओंके नाशसे अमृतत्वकी प्राप्ति बतलायी गयी है? यह प्रसिद्ध है। समस्त श्रौतस्मार्तकर्मोंके फलोंका नाम काम है? उनके त्यागसे ज्ञाननिष्ठ विद्वान्को तुरंत ही शान्ति मिलती है।अज्ञानीके कर्मफलत्यागमें भी सर्व कामनाओंका त्याग है ही? अतः इस सर्व कामनाओंके त्यागकी समानताके कारण रुचि उत्पन्न करनेके लिये यह सर्वकर्मफलत्यागकी स्तुति की गयी। जैसे अगस्त्य ब्राह्मणने समुद्र पी लिया था इसलिये आजकलके ब्राह्मणोंके भी ब्राह्मणत्वकी समानताके कारण स्तुति की जाती है। इस प्रकार कर्मफलके त्यागसे कर्मयोगकी कल्याणसाधनता बतलायी गयी है। यहाँ आत्मा और ईश्वरके भेदको स्वीकार करके विश्वरूप ईश्वरमें चित्तका समाधान करनारूप योग कहा है और ईश्वरके लिये कर्म करने आदिका भी उपदेश किया है। परंतु अथैतदप्यशक्तोऽसि इस कथनके द्वारा ( कर्मयोगको ) अज्ञानका कार्य सूचित करते हुए भगवान् यह दिखलाते हैं कि जो अव्यक्त अक्षरकी उपासना करनेवाले अभेददर्शी हैं उनके लिये कर्मयोग सम्भव नहीं है। साथ ही कर्मयोगियोंके लिये अक्षरकी उपासना असम्भव दिखलाते हैं। इसके सिवाय ( उन्होंने ) ते प्राप्नुवन्ति मामेव इस कथनसे अक्षरकी उपासना करनेवालोंके लिये मोक्षप्राप्तिमें स्वतन्त्रता बतलाकर तेषामहं समुद्धर्ता इस कथनसे दूसरोंके लिये परतन्त्रता अर्थात् ईश्वराधीनता दिखलायी है। क्योंकि यदि वे ( कर्मयोगी भी ) ईश्वरके स्वरूप ही माने गये हैं तब तो अभेददर्शी होनेके कारण वे अक्षरस्वरूप ही हुए? फिर उनके लिये उद्धार करनेका कथन असंगत होगा। भगवान् अर्जुनके अत्यन्त ही हितैषी हैं? इसलिये उसको सम्यक्ज्ञानसे जो मिश्रित नहीं है? ऐसे भेददृष्टियुक्त केवल कर्मयोगका ही उपदेश करते हैं। ( ज्ञानकर्मके समुच्चयका नहीं )। तथा ( यह भी युक्तिसिद्ध है कि ) ईश्वरभाव और सेवकभाव परस्परविरुद्ध है इस कारण प्रमाणद्वारा आत्माको साक्षात् ईश्वररूपजान लेनेके बाद? कोई भी? किसीका सेवक बनना नहीं चाहता।,'),
('shankaracharya-ht:source:12.13','Śaṅkarācārya','gita.12.13','hi','translation','।।12.13।।इसलिये जिन्होंने समस्त इच्छाओंका त्याग कर दिया है? ऐसे अक्षरोपासक यथार्थ ज्ञाननिष्ठ संन्यासियोंका जो साक्षात् मोक्षका कारणरूप अद्वेष्टा सर्वभूतानाम् इत्यादि धर्मसमूह है उसका वर्णन करूँगा? इस उद्देश्यसे भगवान् कहना आरम्भ करते हैं --, जो सब भूतोंमें द्वेषभावसे रहित है अर्थात् अपने लिये दुःख देनेवाले भी किसी प्राणीसे द्वेष नहीं करता? समस्त भूतोंको आत्मारूपसे ही देखता है। तथा जो मित्रतासे युक्त है अर्थात् सबके साथ मित्रभावसे बर्तता है और करुणामय है -- दीनदुखियोंपर दया करना करुणा है? उससे युक्त है? अभिप्राय यह कि जो सब भूतोंको अभय देनेवाला संन्यासी है। तथा जो ममतासे रहित और अहंकारसे रहित है? एवं सुखदुःखमें सम है अर्थात् सुख और दुःख जिसके अन्तःकरणमें रागद्वेष उत्पन्न नहीं कर सकते। जो क्षमावान् है अर्थात् किसीके द्वारा गाली दी जानेपर या पीटे जानेपर भी जो विकाररहित ही रहता है।'),
('shankaracharya-ht:source:12.14','Śaṅkarācārya','gita.12.14','hi','translation','।।12.14।।तथा जो सदा ही सन्तुष्ट है अर्थात् देह स्थितिके कारणरूप पदार्थोंकी लाभ हानिमें जिसके जो कुछ होता है वही ठीक है ऐसा अलम् भाव हो गया है? इस प्रकार जो गुणयुक्त वस्तुके लाभमें और उसकी हानिमें सदा ही सन्तुष्ट रहता है। तथा जो समाहितचित्त? जीते हुए स्वभाववाला और दृढ़ निश्चयवाला है अर्थात् आत्मतत्त्वके विषयमें जिसका निश्चय स्थिर हो चुका है। तथा जो मुझमें अर्पण किये हुए मनबुद्धिवाला है अर्थात् जिस संन्यासीका संकल्प विकल्पात्मक मन और निश्चयात्मिका बुद्धि ये दोनों मुझमें समर्पित हैं -- स्थापित हैं। जो ऐसा मेरा भक्त है वह मेरा प्यारा है। ज्ञानीको मैं अत्यन्त प्यारा हूँ और वह मुझे प्रिय है इस प्रकार जो सप्तम अध्यायमें सूचित किया गया था उसीका यहाँ विस्तारपूर्वक वर्णन किया जाता है।'),
('shankaracharya-ht:source:12.15','Śaṅkarācārya','gita.12.15','hi','translation','।।12.15।।जिस संन्यासीसे संसार उद्वेगको प्राप्त नहीं होता अर्थात् संतप्त -- क्षुब्ध नहीं होता और जो स्वयं भी संसारसे उद्वेगयुक्त नहीं होता। जो हर्ष? अमर्ष? भय और उद्वेगसे रहित है -- प्रिय वस्तुके लाभसे अन्तःकरणमें जो उत्साह होता है? रोमाञ्च और अश्रुपात आदि जिसके चिह्न हैं उसका नाम हर्ष है? असहिष्णुताको अमर्ष कहते हैं? त्रासका नाम भय है और उद्विग्नता ही उद्वेग है इन सबसे जो मुक्त है वह मेरा प्यारा है।'),
('shankaracharya-ht:source:12.16','Śaṅkarācārya','gita.12.16','hi','translation','।।12.16।।जो शरीर? इन्द्रिय? विषय और उनके सम्बन्ध आदि स्पृहाके विषयोंमें अपेक्षारहित -- निःस्पृह है? बाहरभीतरकी शुद्धिसे सम्पन्न है? और चतुर अर्थात् अनेक कर्त्तव्योंके प्राप्त होनेपर उनमेंसे तुरंत ही यथार्थ कर्त्तव्यको निश्चित करनेमें समर्थ है। तथा जो उदासीन अर्थात् किसी मित्र आदिका पक्षपात न करनेवाला संन्यासी है और गतव्यथ यानी निर्भय है। तथा जो समस्त आरम्भोंका त्याग करनेवाला है -- जो आरम्भ किये जायँ उनका नाम आरम्भ है? इसके अनुसार इस लोक और परलोकके फलभोगके लिये किये जानेवाले समस्त कामनाहेतुक कर्मोंका नाम सर्वारम्भ है? उन्हें त्यागनेका जिसका स्वभाव है ऐसा जो मेरा भक्त है वह मेरा प्यारा है।'),
('shankaracharya-ht:source:12.17','Śaṅkarācārya','gita.12.17','hi','translation','।।12.17।।तथा --, जो इष्ट वस्तुकी प्राप्तिमें हर्ष नहीं मानता? अनिष्टकी प्राप्तिमें द्वेष नहीं करता? प्रिय वस्तुका वियोग होनेपर शोक नहीं करता और अप्राप्त वस्तुकी आकाङ्क्षा नहीं करता? ऐसा जो शुभ और अशुभ कर्मोंका त्याग कर देनेवाला भक्तिमान् पुरुष है वह मेरा प्यारा है।'),
('shankaracharya-ht:source:12.18','Śaṅkarācārya','gita.12.18','hi','translation','Sri Shankaracharya did not comment on this sloka'),
('shankaracharya-ht:source:12.19','Śaṅkarācārya','gita.12.19','hi','translation','।।12.19।। तथा --, जिसके लिये निन्दा और स्तुति दोनों बराबर हो गयी हैं? जो मुनि संयतवाक् है अर्थात् वाणी जिसके वशमें है तथा जो जिस किसी प्रकारसे भी शरीरस्थितिमात्रसे सन्तुष्ट है। कहा भी है कि जो जिस किसी ( अन्य ) मनुष्यद्वारा ही वस्त्रादिसे ढका जाता है? एवं जिस किसी ( दूसरे ) के द्वारा ही जिसको भोजन कराया जाता है और जो जहाँ कहीं भी सोनेवाला होता है उसको देवता लोग ब्राह्मण समझते हैं। तथा जो स्थानसे रहित है अर्थात् जिसका कोई नियत निवासस्थान नहीं है? अन्य स्मृतियोंमें भी अनागारः इत्यादि वचनोंसे यही कहा है? तथा जो स्थिरबुद्धि है -- जिसकी परमार्थविषयक बुद्धि स्थिर हो चुकी है? ऐसा भक्तिमान् पुरुष मेरा प्यारा है।'),
('shankaracharya-ht:source:12.20','Śaṅkarācārya','gita.12.20','hi','translation','।।12.20।।समस्त तृष्णासे निवृत्त हुए? परमार्थज्ञाननिष्ठ अक्षरोपासक संन्यासियोंके अद्वेष्टा सर्वभूतानाम् इस श्लोकद्वारा प्रारम्भ किये हुए धर्मसमूहका उपसंहार किया जाता है --, जो संन्यासी इस धर्ममय अमृतको अर्थात् जो धर्मसे ओतप्रोत है और अमृतत्वका हेतु होनेसे अमृत भी है ऐसे इस अद्वेष्टा सर्वभूतानाम् इत्यादि श्लोकोंद्वारा ऊपर कहे हुए ( उपदेश ) का श्रद्धालु होकर सेवन करते हैं -- उसका अनुष्ठान करते हैं? वे मेरे परायण अर्थात् मैं अक्षरस्वरूप परमात्मा ही जिनकी निरतिशय गति हूँ ऐसे? यथार्थ ज्ञानरूप उत्तम भक्तिका अवलम्बन करनेवाले मेरे भक्त? मुझे अत्यन्त प्रिय हैं। प्रियो हि ज्ञानिनोऽत्यर्थम् इस प्रकार जो विषय सूत्ररूपसे कहा गया था यहाँ उसकी व्याख्या करके भक्तास्तेऽतीव मे प्रियाः इस वचनसे उसका उपसंहार किया गया है। कहनेका अभिप्राय यह है कि इस यथोक्त धर्मयुक्त अमृतरूप उपदेशका अनुष्ठान करनेवाला मनुष्य मुझ साक्षात् परमेश्वर विष्णुभगवान्का अत्यन्त प्रिय हो जाता है? इसलिये विष्णुके प्यारे परमधामको प्राप्त करनेकी इच्छावाले मुमुक्षु पुरुषको इस धर्मयुक्त अमृतका यत्नपूर्वक अनुष्ठान करना चाहिये।'),
('shankaracharya-ht:source:13.2','Śaṅkarācārya','gita.13.1','hi','translation','।।13.2।।समस्त कार्य? करण और विषयोंके आकारमें परिणत हुई त्रिगुणात्मिका प्रकृति पुरुषके लिये भोग और अपवर्गका सम्पादन करनेके निमित्त देहइन्द्रियादिके आकारसे संहत ( मूर्तिमान् ) होती है? वह संघात ही यह शरीर है? उसका वर्णन करनेके लिये श्रीभगवान् बोले --, इदम् इस सर्वनामसे कही हुई वस्तुको शरीरम् इस विशेषणसे स्पष्ट करते हैं। हे कुन्तीपुत्र शरीरको चोट आदिसे बचाया जाता है इसलिये? या यह शनैःशनैः क्षीण -- नष्ट होता रहता है इसलिये? अथवा क्षेत्रके समान इसमें कर्मफल प्राप्त होते हैं इसलिये? यह शरीर क्षेत्र है इस प्रकार कहा जाता है। यहाँ इति शब्द एवम् शब्दके अर्थमें है। इस शरीररूप क्षेत्रको जो जानता है -- चरणोंसे लेकर मस्तकपर्यन्त ( इस शरीरको ) जो ज्ञानसे प्रत्यक्ष करता है अर्थात् स्वाभाविक या उपदेशद्वारा प्राप्त अनुभवसे विभागपूर्वक स्पष्ट जानता है उस जाननेवालेको क्षेत्रज्ञ कहते हैं। यहाँ भी इति शब्द पहलेकी भाँति एवम् शब्दके अर्थमें ही है? अतः क्षेत्रज्ञ ऐसा कहते हैं। कौन कहते हैं उनको जाननेवाले अर्थात् उन क्षेत्र और क्षेत्रज्ञ दोनोंको जो जानते हैं वे ज्ञानी पुरुष ( कहते हैं )।'),
('shankaracharya-ht:source:13.3','Śaṅkarācārya','gita.13.2','hi','translation','।।13.3।।इस प्रकार कहे हुए क्षेत्र और क्षेत्रज्ञ क्या इतने ज्ञानसे ही जाने जा सकते हैं इसपर कहते हैं कि नहीं --, तू समस्त क्षेत्रोंमें उपर्युक्त लक्षणोंसे युक्त क्षेत्रज्ञ भी मुझ असंसारी परमेश्वरको ही जान। अर्थात् समस्त शरीरोंमें जो ब्रह्मासे लेकर स्तम्बपर्यन्त अनेक शरीररूप उपाधियोंसे विभक्त हुआ क्षेत्रज्ञ है? उसको समस्त उपाधिभेदसे रहित एवं सत् और असत् आदि शब्दप्रतीतिसे जाननेमें न आनेवाला ही समझ। हे भारत जब कि क्षेत्र? क्षेत्रज्ञ और ईश्वरइनके यथार्थ स्वरूपसे अतिरिक्त अन्य कोई ज्ञानका विषय शेष नहीं रहता? इसलिये ज्ञेयस्वरूप क्षेत्र और क्षेत्रज्ञका जो ज्ञान है -- जिस ज्ञानसे क्षेत्र और क्षेत्रज्ञ प्रत्यक्ष किये,जाते हैं? वही ज्ञान यथार्थ ज्ञान है। मुझ ईश्वर -- विष्णुका यही मत -- अभिप्राय है। पू0 -- यदि समस्त शरीरोंमें एक ही ईश्वर है? उससे अतिरिक्त अन्य कोई भोक्ता नहीं है? ऐसा मानें? तो ईश्वरको संसारी मानना हुआ नहीं तो ईश्वरसे अतिरिक्त अन्य संसारीका अभाव होनेसे संसारके अभावका प्रसङ्ग आ जाता है। यह दोनों ही अनिष्ट हैं क्योंकि ऐसा मान लेनेपर बन्ध? मोक्ष और उनके कारणका प्रतिपादन करनेवाले शास्त्र व्यर्थ हो जाते हैं और प्रत्यक्षादि प्रमाणोंसे भी इस मान्यताका विरोध है। प्रत्यक्ष प्रमाणसे तो सुखदुःख और उनका कारणरूप यह संसार दीख ही रहा है। इसके सिवा जगत्की विचित्रताको देखकर पुण्यपापहेतुक संसारका होना अनुमानसे भी सिद्ध होता है? परंतु आत्मा और ईश्वरकी एकता मान लेनेपर ये सबकेसब अयुक्त ठहरते हैं। उ0 -- यह कहना ठीक नहीं क्योंकि ज्ञान और अज्ञानका भेद होनेसे यह सब सम्भव है। ( श्रुतिमें भी कहा है कि ) प्रसिद्ध जो अविद्या और विद्या हैं वे अत्यन्त विपरीत और भिन्न समझी गयी हैं तथा ( उसी जगह ) उन विद्या और अविद्याका फल भी श्रेय और प्रेय इस प्रकार परस्परविरुद्ध दिखलाया गया है? इनमें विद्याका फल श्रेय ( मोक्ष ) और अविद्याका प्रेय ( इष्ट भोगोंकी प्राप्ति ) है। वैसे ही श्रीव्यासजीने भी कहा है कि यह दोनों ही मार्ग है इत्यादि तथा यह दो ही मार्ग हैं इत्यादि और यहाँ गीताशास्त्रमें भी दो निष्ठाएँ बतलायी गयी हैं। इसके सिवा श्रुति? स्मृति और न्यायसे भी यही सिद्ध होता है कि विद्याके द्वारा कार्यसहित अविद्याका नाश करना चाहिये। इस विषयमें ये श्रुतियाँ यहाँ यदि जान लिया तो बहुत ठीक है और यदि यहाँ नहीं जाना तो बड़ी भारी हानि है उसको इस प्रकार जाननेवाला यहाँ अमृत हो जाता है परमपदकी प्राप्तिके लिये ( विद्याके सिवा ) अन्य मार्ग नहीं है विद्वान् किसीसे भी भयभीत नहीं होता। किन्तु अज्ञानीके विषयमें ( कहा है कि ) उसको भय होता है जो कि अविद्याके बीचमें ही प़ड़े हुए हैं जो ब्रह्मको जानता है वह ब्रह्म ही हो जाता है यह देव अन्य है और मैं अन्य हूँ इस प्रकार जो समझता है वह आत्मतत्त्वको नहीं जानता जैसे ( मनुष्योंका पशु होता है वैसे ही वह देवताओंका पशु है किन्तु जो आत्मज्ञानी है ( उसविषयमें ) वह यह सब कुछ हो जाता है यदि आकाशको चमक समान लपेटा जा सके इत्यादि सहस्रों श्रुतियाँ हैं। तथा ये स्मृतियाँ भी हैं -- ज्ञान अज्ञानसे ढका हुआ है? इसलिये जीव मोहित हो रहे हैं जिनका चित्त समतामें स्थित है उन्होंने यहीं संसारको जीत लिया है सर्वत्र समानभावसे देखता हुआ इत्यादि। युक्तिसे भी यह बात सिद्ध है। जैसे कहा है कि सर्प? कुशकंण्टक और तालाबको जान लेनेपर मनुष्य उनसे बच जाते हैं? किन्तु बिना जाने कई एक उनमें गिर जाते हैं? इस न्यायसे ज्ञानका जो विशेष फल है उसको समझ। इस प्रकार उपर्युक्त प्रमाणोंसे यह ज्ञान होता है कि देहादिमें आत्मबुद्धि करनेवाला अज्ञानी रागद्वेषादि दोषोंसे प्रेरित होकर धर्मअधर्मरूप कर्मोंका अनुष्ठान करता हुआ जन्मता और मरता रहता है? किंतु देहादिसे अतिरिक्त आत्माका साक्षात् करनेवाले पुरुषोंके रागद्वेषादि दोष निवृत्त हो जाते हैं? इससे उनकी धर्माधर्मविषयक प्रवृत्ति शान्त हो जानेसे वे मुक्त हो जाते हैं। इस बातका कोई भी न्यायानुसार विरोध नहीं कर सकता।अतः यह सिद्ध हुआ कि जो वास्तवमें ईश्वर ही है उस क्षेत्रज्ञको अविद्याद्वारा आरोपित उपाधिके भेदसे संसारित्व प्राप्तसा हो जाता है? जैसे कि जीवको देहादिमें आत्मबुद्धि हो जाती है क्योंकि समस्त जीवोंका जो देहादि अनात्मपदार्थोंमें आत्मभाव प्रसिद्ध है? वह निःसंदेह अविद्याकृत ही है। जैसे स्तम्भमें मनुष्यबुद्धि हो जाती है? परंतु इतनेहीसे मनुष्यके धर्म स्तम्भमें और स्तम्भके धर्म मनुष्यमें नहीं आ जाते? वैसे ही चेतनके धर्म देहमें और देहके धर्म चेतनमें नहीं आ सकते। जरा और मृत्युके समान ही अविद्याके कार्य होनेसे सुखदुःख और अज्ञान आदि भी उन्हींकी भाँति आत्माके धर्म नहीं हो सकते। पू0 -- यदि ऐसा मानें कि विषम होनेके कारण यह दृष्टान्त ठीक नहीं है अर्थात् स्तम्भ और पुरुष दोनों ज्ञेय वस्तु हैं? उनमें अविद्यावश ज्ञाताद्वारा एकमें एकका अध्यास किया गया है परंतु देह और आत्मामें तो ज्ञेय और ज्ञाताका ही एक दूसरेमें अध्यास होता है? इसलिये यह दृष्टान्त सम नहीं है? अतः यह सिद्ध होता है कि देहका ज्ञेयरूप ( सुखदुःखादि ) धर्म भी ज्ञाता -- आत्मामें होता है। उ0 -- इसमें आत्माको जड़ मानने आदिका प्रसङ्ग आ जाता है? इसलिये ऐसा मानना ठीक नहीं है क्योंकि यदि ज्ञेयरूप शरीरादि -- क्षेत्रक सुख? दुःख? मोह और इच्छादि धर्म ज्ञाता ( आत्मा ) के भी होते हैं? तो यह बतलाना चाहिये कि ज्ञेयरूप क्षेत्रके अविद्याद्वारा आरोपित कुछ धर्म तो आत्मामें होते हैं और कुछ -- जरामरणादि नहीं होते? इस विशेषताका कारण क्या है बल्कि? ऐसा अनुमान तो किया जा सकता है कि जरा आदिके समान अविद्याद्वारा आरोपित और त्याज्य तथा ग्राह्य होनेके कारण ये सुखदुःखादि ( आत्माके धर्म ) नहीं हैं। ऐसा होनेसे यह सिद्ध हुआ कि कर्तृत्वभोक्तृत्वरूप यह संसार ज्ञेय वस्तुमें स्थित हुआ ही अविद्याद्वारा ज्ञातामें अध्यारोपित है? अतः उससे ज्ञाताका कुछ भी नहीं बिगड़ता? जैसे कि मूर्खोंद्वारा अध्यारोपित तलमलिनतादिसे आकाशका ( कुछ भी नहीं बिगड़ता )। अतः सब शरीरोंमें रहते हुए भी भगवान्क्षेत्रज्ञ ईश्वरमें संसारीपनके गन्धमात्रकी भी शङ्का नहीं करनी चाहिये क्योंकि संसारमें कहीं भी अविद्याद्वारा आरोपित धर्मसे किसीका भी उपकार या अपकार होता नहीं देखा जाता। तुमने जो यह कहा था कि ( स्तम्भमें मनुष्यके भ्रमका ) दृष्टान्त सम नहीं है सो ( यह कहना ) भूल है। पू0 -- कैसे उ0अविद्याजन्य अध्यासमात्रमें ही दृष्टान्त और दार्ष्टान्तकी समानता विवक्षित है। उसमें कोई दोष नहीं आता। परंतु तुम जो यह मानते हो कि ज्ञातामें दृष्टान्त और दार्ष्टान्तकी विषमताका दोष आता है? तो उसका भी अपवाद? जरामृत्यु आदिके दृष्टान्तसे दिखला दिया गया है। पू0 -- यदि ऐसा कहें कि अविद्यायुक्त होनेसे क्षेत्रज्ञको ही संसारित्व प्राप्त हुआ? तो उ0 -- यह कहना ठीक नहीं क्योंकि अविद्या? तामस प्रत्यय है। तामस प्रत्यय? चाहे विपरीत ग्रहण करनेवाला,( विपर्यय ) हो? चाहे संशय उत्पन्न करनेवाला ( संशय ) हो और चाहे कुछ भी ग्रहण न करनेवाला हो? आवरणरूप होनेके कारण वह अविद्या ही है? क्योंकि विवेकरूप प्रकाशके होनेपर वह दूर हो जाता है तथा आवरणरूप तमोमय तिमिरादि दोषोंके रहते हुए ही अग्रहण आदिरूप तीन प्रकारकी अविद्याका अस्तित्व उपलब्ध होता है। पू0 -- यदि यह बात है तब तो अविद्या ज्ञाताका धर्म हुआ उ0 -- यह कहना ठीक नहीं क्योंकि तिमिररोगादिजन्य दोष चक्षु आदि करणोंमें ही देखे जाते हैं ( ज्ञाता आत्मामें नहीं )। जो तुम ऐसा मानते हो कि अविद्या ज्ञाताका धर्म है और अविद्यारूप धर्मसे युक्त होना ही उसका संसारित्व है? इसलिये यह कहना ठीक नहीं है कि ईश्वर ही क्षेत्रज्ञ है और वह संसारी नहीं है सो तुम्हारा ऐसा मानना युक्तियुक्त नहीं है क्योंकि नेत्ररूप करणमें विपरीत ग्राहकता आदि दोष देखे जाते हैं तो भी वे विपरीतादि ग्रहण या उनके कारणरूप तिमिरादि दोष ज्ञाताके नहीं हो जाते ( उसी प्रकार देहके धर्म भी आत्माके नहीं हो सकते )। तथा जैसे आँखका संस्कार करके तिमिरादि प्रतिबन्धको हटा देनेपर ग्रहीता पुरुषमें वे दोष नहीं देखे जाते? इसलिये वे ग्रहीता पुरुषके धर्म नहीं हैं? वैसे ही अग्रहण? विपरीतग्रहण और संशय आदि प्रत्यय तथा उनके कारणरूप तिमिरादि दोष भी सर्वत्र किसीनकिसी करणके ही हो सकते हैं -- ज्ञाता पुरुषके अर्थात् क्षेत्रज्ञके नहीं। इसके सिवा वे जाननेमें आनेवाले ( ज्ञानके विषय ) होनेसे भी दीपकके प्रकाशकी भाँति ज्ञाताके धर्म नहीं हो सकते क्योंकि वे ज्ञेय हैं? इसलिये अपनेसे अतिरिक्त किसी अन्यद्वारा जाननेमें आनेवाले हैं। सभी आत्मवादी समस्त करणोंसे आत्माका वियोग होनेके उपरान्त कैवल्य अवस्थामें आत्माको अविद्यादि दोषोंसे रहित मानते हैं? इससे भी ( उपर्युक्त सिद्धान्त ही सिद्ध होता है ) क्योंकि यदि अग्निकी उष्णताके समान ये ( सुखदुःखादि दोष ) क्षेत्रज्ञ आत्माके अपने धर्म हों तो उनसे उसका कभी वियोग नहीं हो सकेगा। इसके सिवा आकाशकी भाँति सर्वव्यापक? मूर्तिरहित? निर्विकार आत्माका किसीके साथ संयोगवियोग होना सम्भव नहीं है? इससे भी क्षेत्रज्ञकी नित्य ईश्वरता ही सिद्ध होती है। तथा अनादित्वान्िनर्गुणत्वात् इत्यादि भगवान्के वचनोंसे भी क्षेत्रज्ञका नित्य ईश्वरत्व हि सिद्ध होता है। पू0 -- ऐसा मान लेनेपर तो संसार और संसारित्वका अभाव हो जानेके कारण शास्त्रकी व्यर्थता आदि दोष उपस्थित होंगे उ0 -- नहीं क्योंकि यह दोष तो सभीने स्वीकार किया है। सभी आत्मवादियोंद्वारा स्वीकार किये हुए दोषका किसी एकके लिये ही परिहार करना आवश्यक नहीं है।, पू0 -- इसे सबने कैसे स्वीकार किया है उ0 -- सभी आत्मवादियोंने मुक्त आत्मामें संसार और संसारीपनके व्यवहारका अभाव माना है? परंतु ( इससे ) उनके मतमें शास्त्रकी अनर्थकता आदि दोषोंकी प्राप्ति नहीं मानी गयी। जैसे समस्त द्वैतवादियोंके मतसे बन्धावस्थामें ही शास्त्र आदिकी सार्थकता है मुक्तअवस्थामें नहीं? वैसे ही हमारे मतमें भी जीवोंकी ईश्वरके साथ एकता हो जानेपर यदि शास्त्रकी व्यर्थता होती हो तो हो? अविद्यावस्थामें तो उसकी सार्थकता है ही। पू0 -- हम सब द्वैतवादियोंके सिद्धान्तसे तो आत्माकी बन्धावस्था और मुक्तावस्था वास्तवमें ही सच्ची है। अतः वे हेय? उपादेय हैं और उनके सब साधन भी सत्य हैं। इस कारण शास्त्रकी सार्थकता हो सकती है। परंतु अद्वैतवादियोंके सिद्धान्तसे तो द्वैतभाव अविद्याजन्य और मिथ्या है? अतः आत्मामें बन्धावस्था भी वास्तवमें नहीं है? इसलिये शास्त्रका कोई विषय न रहनेके कारण शास्त्र आदिकी व्यर्थताका दोष आता है। उ0 -- यह कहना ठीक नहीं क्योंकि आत्माके अवस्थाभेद सिद्ध नहीं हो सकते? यदि ( आत्मामें इनका होना ) मान भी लें तो आत्माकी ये बन्ध और मुक्त दोनों अवस्थाएँ एक साथ होनी चाहिये या क्रमसे स्थिति और गतिकी भाँति परस्परविरोध होनेके कारण दोनों अवस्थाएँ एक साथ तो एकमें हो नहीं सकतीं। यदि क्रमसे होना मानें तो बिना निमित्तके बन्धावस्थाका होना माननेसे तो उससे कभी छुटकारा न होनेका प्रसङ्ग आ जायगा और किसी निमित्तसे उसका होना मानें तो स्वतः न होनेके कारण व');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:13.3','Śaṅkarācārya','gita.13.2','hi','translation','ह मिथ्या ठहरती है। ऐसा होनेपर स्वीकार किया हुआ सिद्धान्त कट जाता है। इसके सिवा बन्धावस्था और मुक्तावस्थाका आगापीछा निरूपण किया जानेपर पहले बन्धावस्थाका होना माना जायगा तथा उसे आदिरहित और अन्तयुक्त मानना पड़ेगा सो यह प्रमाणविरुद्ध है? ऐसे ही मुक्तावस्थाको भी आदियुक्त और अन्तरहित प्रमाणविरुद्ध ही मानना पड़ेगा। तथा आत्माकी अवस्थावाला और एक अवस्थासे दूसरी अवस्थामें जानेवाला मानकर उसका नित्यत्व सिद्ध करना भी सम्भव नहीं है। जब कि आत्मामें अनित्यत्वके दोषका परिहार करनेके लिये बन्धावस्था और मुक्तावस्थाके भेदकी कल्पना नहीं की जा सकती। इसलिये द्वैतवादियोंके मतसे भी शास्त्रकी व्यर्थता आदि दोष अबाध्य ही हैं। इस प्रकार दोनोंके लिये समान होनेके कारण इस दोषका परिहार केवल अद्वैतवादियोंद्वारा ही किया जाना आवश्यक नहीं है। ( हमारे मतानुसार तो वास्तवमें ) शास्त्रकी व्यर्थता है भी नहीं क्योंकि शास्त्र लोकप्रसिद्ध अज्ञानीका ही विषय है। अज्ञानियोंका ही फल और हेतुरूप अनात्मवस्तुओंमें आत्मभाव होता है? विद्वानोंका नहीं। क्योंकि विद्वान्की बुद्धिमें फल और हेतुसे आत्माका पृथक्त्व प्रत्यक्ष है? इसलिये उसका उन (अनात्मपदार्थों ) में यह मैं हूँ ऐसा आत्मभाव नहीं हो सकता। अत्यन्त मूढ़ और उन्मत्त आदि भी जल और अग्निकी? या छाया और प्रकाशकी एकता नहीं मानते? फिर विवेकीकी तो बात ही क्या है सुतरां फल और हेतुसे आत्माको भिन्न समझ लेनेवाले ज्ञानीके लिये विधिनिषेधविषयक शास्त्र नहीं है। जैसे हे देवदत्त तू अमुक कार्य कर इस प्रकार किसी कर्ममें ( देवदत्तके ) नियुक्त किये जानेपर वहीं खड़ा हुआ विष्णुमित्र उस नियुक्तिको सुनकर भी? यह नहीं समझता कि मैं नियुक्त किया गया हूँ। हाँ? नियुक्तिविषयक विवेकका स्पष्ट ग्रहण न होनेसे तो ऐसा समझना ठीक हो सकता है? इसी प्रकार फल और,हेतुमें भी ( अज्ञानियोंकी आत्मबुद्धि हो सकती है )। पू0 -- फल और हेतुसे आत्माके पृथक्त्वका ज्ञान हो जानेपर भी? स्वाभाविक सम्बन्धकी अपेक्षासे शास्त्रविषयक इतना बोध होना तो युक्तियुक्त ही है कि मैं शास्त्रद्वारा अनुकूल फल और उसके हेतुमें तो प्रवृत्त किया गया हूँ और प्रतिकूल फल और उसके हेतुसे निवृत्त किया गया हूँ? जैसे कि पितापुत्र आदिका आपसमें एक दूसरेको भिन्न समझते हुए भी एक दूसरेके लिये किये हुए नियोग और प्रतिषेधको अपने लिये समझना देखा जाता है। उ0 -- यह कहना ठीक नहीं क्योंकि आत्माके पृथक्त्वका ज्ञान होनेसे पहलेपहले ही फल और हेतुमें आत्माभिमान होना सिद्ध है। नियोग और प्रतिषेधके अभिप्रायको भली प्रकार जानकर ही मनुष्य फल और हेतुसे आत्माके पृथक्त्वको जान सकता है? उससे पहले नहीं। इससे सिद्ध हुआ कि विधिनिषेधरूप शास्त्रकेवल अज्ञानीके लिये ही है। पू0 -- (इस सिद्धान्तके अनुसार ) स्वर्गकी कामनावाला यज्ञ करे मांस भक्षण न करे इत्यादि विधिनिषेधबोधक शास्त्रवचनोंमें आत्माका पृथक्तव जाननेवालोंकी और केवल देहात्मवादियोंकी भी प्रवृत्ति न होनेसे कर्ताका अभाव हो जानेके कारण शास्त्रके व्यर्थ होनेका प्रसङ्ग आ जायगा उ0 -- यह कहना ठीक नहीं है क्योंकि प्रवृत्ति और निवृत्तिका होना लोकप्रसिद्धिसे ही प्रत्यक्ष है। ईश्वर और जीवात्माकी एकता देखनेवाला ब्रह्मवेत्ता कर्मोंमें प्रवृत्त नहीं होता तथा आत्मसत्ताको न माननेवाला देहात्मवादी भी परलोक नहीं है ऐसा समझकर शास्त्रानुसार नहीं बर्तता यह ठीक है परंतु लोकप्रसिद्धिसे यह तो हम सबको प्रत्यक्ष है ही कि विधिनिषेधबोधक शास्त्रश्रवणकी दूसरी तरह उपपत्ति न होनेके कारण जिसने आत्माके अस्तित्वका अनुमान कर लिया है? एवं जो आत्माके असली तत्त्वका ज्ञाता नहीं है जिसकी कर्मोंके फलमें तृष्णा है? ऐसा मनुष्य श्रद्धालुताके कारण ( शास्त्रानुसार कर्मोंमें ) प्रवृत्त होता है। अतः शास्त्रकी व्यर्थता नहीं है। पू0 -- विवेकशील पुरुषोंकी प्रवृत्ति न देखनेसे उनका अनुकरण करनेवालोंकी भी ( शास्त्रविहित कर्मोंमें ) प्रवृत्ति नहीं होगी? अतः शास्त्रव्यर्थ हो जायगा। उ0 -- यह कहना ठीक नहीं क्योंकि किसी एकको ही विवेकज्ञान प्राप्त होता है। अर्थात् अनेक प्राणियोंमेंसे कोई एक ही विवेकी होता है जैसा कि आजकल ( देखा जाता है )। इसके सिवा मूढ़लोग विवेकियोंका अनुकरण भी नहीं करते क्योंकि प्रवृत्ति रागादि दोषोंके अधीन हुआ करती है। ( प्रतिहिंसाके उद्देश्यसे किये जानेवाले जारणमारण आदि ) अभिचारोंमें भी लोगोंकी प्रवृत्ति देखी जाती है तथा प्रवृत्ति स्वाभाविक है। यह कहा भी है कि स्वभाव ही बर्तता है। सुतरां यह सिद्ध हुआ कि संसार अविद्यामात्र ही है और वह अज्ञानियोंका ही विषय है। केवलशुद्ध क्षेत्रज्ञमें अविद्या और उसके कार्य दोनों ही नहीं हैं। तथा मिथ्याज्ञान परमार्थवस्तुको दूषित करनेमें समर्थ भी नहीं है। क्योंकि जैसे ऊसर भूमिको मृगतृष्णिकाका जल अपनी आर्द्रतासे कीचड़युक्त नहीं कर सकता? वैसे ही अविद्या भी क्षेत्रज्ञका कुछ भी ( उपकार या अपकार ) करनेमें समर्थ नहीं है? इसीलिये क्षेत्रज्ञं चापि मां विद्धि और अज्ञानेनावृतं ज्ञानम् यह कहा है। पू0 -- तो फिर यह क्या बात है कि संसारी पुरुषोंकी भाँति पण्डितोंको भी मैं ऐसा हूँ यह वस्तु मेरी ही है ऐसी प्रतीत होती है। उ0 -- सुनो? यह पाण्डित्य बस इतना ही है जो कि क्षेत्रमें ही आत्माको देखना है परंतु यदि मनुष्य क्षेत्रज्ञको निर्विकारी समझ ले तो फिर मुझे अमुक भोग मिले या मैं अमुक कर्म करूँ ऐसी आकाङ्क्षा नहीं कर सकता? क्योंकि भोग और कर्म दोनों विकार ही तो हैं। सुतरां यह सिद्ध हुआ कि फलेच्छुक होनेके कारण अज्ञानी कर्मोंमें प्रवृत्त होता है परंतु विकाररहित आत्माका साक्षात् कर लेनेवाले ज्ञानीमें फलेच्छाका अभाव होनेके कारण? उसकी प्रवृत्ति सम्भव नहीं? अतः कार्यकरणसंघातके व्यापारकी निवृत्ति होनेपर उस ( ज्ञानी ) में निवृत्तिका उपचार किया जाता है। किसीकिसीके मतमें यह एक प्रकारकी विद्वत्ता और भी हो सकती है कि? क्षेत्रज्ञ तो ईश्वर ही है और उस क्षेत्रज्ञके ज्ञानका विषय क्षेत्र उससे अलग है तथा मैं तो ( उन दोनोंसे भिन्न ) संसारी और सुखीदुःखी भी हूँ। मुझे क्षेत्रक्षेत्रज्ञके ज्ञान और ध्यानद्वारा ईश्वररूप क्षेत्रज्ञका साक्षात् करके उसके स्वरूपमें स्थित होनारूप साधनसे संसारकी निवृत्ति करनी चाहिये। जो ऐसा समझता है या दूसरेको ऐसा समझाता है कि वह ( जीव ) क्षेत्रज्ञ ( ब्रह्म ) नहीं है तथा जो यह मानता है कि मैं ( इस प्रकारके सिद्धान्तसे ) संसार? मोक्ष और शास्त्रकी सार्थकता सिद्ध करूँगा? वह पण्डितोंमें अधम है। तथा वह आत्महत्यारा? शास्त्रके अर्थकी सम्प्रदायपरम्परासे रहित होनेके कारण? श्रुतिविहित अर्थका त्याग और वेदविरुद्ध अर्थकी कल्पना करके स्वयं मोहित हो रहा है और दूसरोंको भी मोहित करता है। सुतरां जो शास्त्रार्थकी परम्पराको जाननेवाला नहीं है? वह समस्त शास्त्रोंका ज्ञाता भी हो तो भी मूर्खोंके समान उपेक्षणीय ही है। और जो यह कहा था कि ईश्वरकी क्षेत्रज्ञके साथ एकता माननेसे तो ईश्वरमें संसारीपन आ जाता है और क्षेत्रज्ञोंकी ईश्वरके साथ एकता माननेसे कोई संसारी न रहनेके कारण संसारके अभावका प्रसङ्ग आ जाता है? सो विद्या और अविद्याकी विलक्षणताके प्रतिपादनसे इन दोनों दोषोंका ही परिहार कर दिया गया। पू -- कैसे उ0 -- अविद्याद्वारा कल्पित किये हुए दोषसे तद्विषयक पारमार्थिक ( असली ) वस्तु दूषित नहीं होती? इस कथनसे पहली शङ्काका निराकरण किया गया और वैसे ही यह दृष्टान्त भी दिखलाया कि मृगतृष्णिकाके जलसे ऊसर भूमि पङ्कयुक्त नहीं की जा सकती। तथा संसारीका अभाव होनेसे संसारके अभावके प्रसङ्गका जो दोष बतलाया था? उसका भी संसार संसारित्वकी अविद्याकल्पित उपपत्तिको स्वीकार करके निराकरण कर दिया गया। पू0 -- क्षेत्रज्ञका अविद्यायुक्त होना ही तो संसारित्वरूप दोष है? क्योंकि उससे होनेवाले दुःखित्व आदि दोष प्रत्यक्ष देखे जाते हैं। उ0 -- यह कहना ठीक नहीं? क्योंकि जो कुछ ज्ञेय है -- जाननेमें आता है? वह सब क्षेत्रका ही धर्म है? इसलिये,उसके किये हुए दोष ज्ञाता क्षेत्रज्ञके नहीं हो सकते। तू क्षेत्रज्ञपर वास्तवमें बिना हुए ही जो कुछ भी दोष लाद रहा है? वे सब ज्ञेय होनेके कारण क्षेत्रके ही धर्म हैं? क्षेत्रज्ञके नहीं। उनसे क्षेत्रज्ञ ( आत्मा ) दूषित नहीं हो सकता? क्योंकि ज्ञेयके साथ ज्ञाताका संसर्ग नहीं हो सकता। यदि उनका संसर्ग मान लिया जाय तो (ज्ञेयका) ज्ञेयत्व ही सिद्ध नहीं हो सकता। अभिप्राय यह है कि यदि अविद्यायुक्त होना और दुखी होना आदि आत्माके धर्म हैं तो वे प्रत्यक्ष कैसे दीखते हैं और वे क्षेत्रज्ञके धर्म हो भी कैसे सकते हैं क्योंकि जो कुछ भी ज्ञेय वस्तु है वह सब क्षेत्र है और क्षेत्रज्ञ ज्ञाता है? ऐसा सिद्धान्त स्थापित किये जानेपर फिर अविद्यायुक्त होना और दुखी होना आदि दोषोंको क्षेत्रज्ञके धर्म बतलाना और उनकी प्रत्यक्ष उपलब्धि भी मानना? यह सब अज्ञानमात्रके आश्रयसे केवल विरुद्ध प्रलाप करना है। पू0 -- वह अविद्या किसमें है उ0 -- जिसमें दीखती है उसीमें। पू0 -- किसमें दीखती है उ0 -- अविद्या किसमें दीखती है -- यह प्रश्न ही निरर्थक है। पू0 -- किस प्रकार उ0 -- यदि अविद्या दीखती है तो उससे जो युक्त है उसको भी तू अवश्य देखता ही होगा फिर अविद्यावान्की उपलब्धि हो जानेपर वह अविद्या किसमें है? यह पूछना ठीक नहीं है। क्योंकि गौवालेको देख लेनेपर यह गौ किसकी है यह पूछना सार्थक नहीं हो सकता। पू0 -- तुम्हारा यह दृष्टान्त विषय है। गौ और उसका स्वामी तो प्रत्यक्ष होनेके कारण उनका सम्बन्ध भी प्रत्यक्ष है इसलिये ( उनके सम्बन्धके विषयमें ) प्रश्न निरर्थक है? परंतु उनकी भाँति अविद्यावान् और अविद्या तो प्रत्यक्ष नहीं हैं? जिससे कि यह प्रश्न निरर्थक माना जाय उ0 -- अप्रत्यक्ष अविद्यावान्के साथ अविद्याका सम्बन्ध जान लेनेसे तुम्हें क्या मिलेगा पू0 -- अविद्या अनर्थकी हेतु है? इसलिये उसका त्याग किया जा सकेगा। उ0 -- जिसमें अविद्या है? वह उसका स्वयं त्याग कर देगा। पू0 -- मुझमें ही तो अविद्या है। उ0 -- तब तो तू अविद्या और उससे युक्त अपने आपको जानता है। पू0 -- जानता तो हूँ परंतु प्रत्यक्षरूपसे नहीं। उ0 -- यदि अनुमानसे जानता है तो ( तुझ ज्ञाता और अविद्याके ) सम्बन्धका ग्रहण कैसे हुआ क्योंकि उस,समय ( अविद्याको अनुमानसे जाननेके कालमें ) तुझ ज्ञाताका ज्ञेयरूप अविद्याके साथ सम्बन्ध ग्रहण नहीं किया जा सकता? कारण यह है कि ज्ञाताका विषय मानकर ही अविद्याका उपयोग किया गया है। तथा ज्ञाता और अविद्याके सम्बन्धको जो ग्रहण करनेवाला है वह तथा उस ( अविद्या और ज्ञाताके सम्बन्ध ) को विषय करनेवाला कोई दूसरा ज्ञान ये दोनों ही सम्भव नहीं हैं। क्योंकि ऐसा होनेसे अनवस्थादोष प्राप्त होता है अर्थात् यदि ज्ञाता और ज्ञेयज्ञाताका सम्बन्ध ये भी ( किसीके द्वारा ) जाने जाते हैं? ऐसा माना जाय तो उसका ज्ञाता किसी औरको मानना होगा। फिर उसका भी दूसरा और उसका भी दूसरा ज्ञाता मानना होगा? इस प्रकार यह अनवस्था अनिवार्य हो जायगी। पंरतु ज्ञेय चाहे अविद्या हो अथवा और कुछ हो? ज्ञेय ज्ञेय ही रहेगा ( ज्ञाता नहीं हो सकता ) वैसे ही ज्ञाता भी ज्ञाता ही र'),
('shankaracharya-ht:source:13.3','Śaṅkarācārya','gita.13.2','hi','translation','हेगा? ज्ञेय नहीं हो सकता? जब कि ऐसा है तो अविद्या या दुःखित्व आदि दोषोंसे ज्ञाता -- क्षेत्रज्ञका कुछ भी दूषित नहीं हो सकता। पू0 -- यही उसका दोष है जो कि वह दोषयुक्त क्षेत्रका ज्ञाता है। उ0 -- यह कहना ठीक नहीं क्योंकि आत्मा विज्ञानस्वरूप और अविक्रिय है? उसमें ( इस ) ज्ञातापनका उपचारमात्र किया जाता है? जैसे कि उष्णतामात्र स्वभाव होनेसे अग्निमें तपानेकी क्रियाका उपचार किया जाता है। जैसे भगवान्ने यहाँ ( इस प्रकरणमें ) यह दिखाया है कि आत्मामें स्वभावसे ही क्रिया? कारक और फलात्मत्वका अभाव है? केवल अविद्याद्वारा अध्यारोपित होनेके कारण क्रिया? कारक आदि आत्मामें उपचरित होते हैं? वैसे ही? जो इसे मारनेवाला जानता है प्रकृतिके गुणोंद्वारा ही सब कर्म किये जाते हैं ( वह विभु ) किसीके पापपुण्यको ग्रहण नहीं करता इत्यादि प्रकरणोंमें जगहजगह दिखाया गया है और इसी प्रकार हमने व्याख्या भी की है? तथा आगेके प्रकरणोंमें भी हम दिखलायेंगे। पू0 -- तब तो आत्मामें स्वभावसे क्रिया? कारक और फलात्मत्वका अभाव सिद्ध होनेसे तथा ये सब अविद्याद्वारा अध्यारोपित सिद्ध होनेसे यही निश्चय हुआ कि कर्म अविद्वान्को ही कर्तव्य है? विद्वान्को नहीं। उ0 -- ठीक यही सिद्ध हुआ। इसी बातको हम न हि देहभृता शक्यम् इस प्रकरणमें और सारे गीताशास्त्रके उपसंहारप्रकरणमें दिखलायेंगे। तथा सामसेनैव कौन्तेय निष्ठा ज्ञानस्य या परा इस श्लोकके अर्थमें विशेषरूपसे दिखायेंगे। बस? यहाँ अब और अधिक विस्तारकी आवश्यकता नहीं है? इसलिये उपसंहार किया जाता है।'),
('shankaracharya-ht:source:13.4','Śaṅkarācārya','gita.13.3','hi','translation','।।13.4।।इदं शरीरम् इत्यादि श्लोकोंद्वारा उपदेश किये हुए क्षेत्राध्यायके अर्थका संक्षेपरूप यह तत्क्षेत्रं यच्च इत्यादि श्लोक कहा जाता है क्योंकि जिस अर्थका विस्तारपूर्वक वर्णन करना हो? उसका संक्षेप पहले कह देना उचित ही है --, जिसका पहले इदं शरीरम् इत्यादि ( वाक्य ) से वर्णन किया गया है? यहाँ तत् शब्दसे उसीका संकेत करते हैं। यह जो पूर्वोवत क्षेत्र है वह जैसा है अर्थात् अपने धर्मोंके कारण वह जिस प्रकारका है तथा जैसे विकारोंवाला है और जिस कारणसे जो कार्य उत्पन्न होता है -- यहाँ च शब्द समुच्चयके लिये है और कार्य उत्पन्न होता है यह वाक्यशेष है। तथा जिसे क्षेत्रज्ञ कहा गया है वह भी जिस प्रभाववाला अर्थात् जिनजिन उपाधिकृत शक्तियोंवाला है? उन क्षेत्र और क्षेत्रज्ञ दोनोंका उपर्युक्त विक्षेषणोंसे युक्त यथार्थ स्वरूप तू मुझसे संक्षेपसे सुन अर्थात् सुनकर निश्चय कर।'),
('shankaracharya-ht:source:13.5','Śaṅkarācārya','gita.13.4','hi','translation','।।13.5।।श्रोताकी बुद्धिमें रुचि उत्पन्न करनेके लिये? उस कहे जानेवाले क्षेत्र और क्षेत्रज्ञके यथार्थ स्वरूपकी स्तुति करते हैं --, ( यह क्षेत्र और क्षेत्रज्ञका तत्त्व ) वसिष्ठादि ऋषियोंद्वारा बहुत प्रकारसे कहा गया है और ऋग्वेदादि नाना प्रकारके श्रुतिवाक्योंद्वारा भी पृथक्पृथक् -- विवेचनपूर्वक कहा गया है। तथा संशयरहित निश्चित ज्ञान उत्पन्न करनेवाले विनिश्चित और युक्तियुक्त ब्रह्मसूत्रके पदोंसे भी कहा गया है। जो वाक्य ब्रह्मके सूचक हैं उसका नाम ब्रह्मसूत्र है? उनके द्वारा ब्रह्म पाया जाता है -- जाना जाता है? इसलिये उनको पद कहते हैं? उनसे भी क्षेत्र और क्षेत्रज्ञका तत्त्व कहा गया है क्योंकि केवल आत्मा ही सब कुछ है ऐसी उपासना करनी चाहिये इत्यादि ब्रह्मसूचक पदोंसे ही आत्मा जाना जाता है।'),
('shankaracharya-ht:source:13.6','Śaṅkarācārya','gita.13.5','hi','translation','।।13.6।।इस प्रकार स्तुति सुनकर सम्मुख हुए अर्जुनसे भगवान् कहते हैं --, महाभूत यानी सूक्ष्मभूत? वे सब विकारोंमें व्यापक होनेके कारण महान् भी हैं और भूत भी हैं? इसलिये वे महाभूत कहे जाते हैं। स्थूल पञ्चभूत तो इन्द्रियगोचरशब्दसे कहे जायँगे? इसलिये यहाँ महाभूतशब्दसे सूक्ष्म पञ्चमहाभूतोंका ग्रहण है। महाभूतोंका कारण अहंप्रत्ययरूप अहंकार तथा अहंकारकी कारणरूपा निश्चयात्मिका बुद्धि और उसकी भी कारणरूपा अव्यक्त प्रकृति अर्थात् जो व्यक्त नहीं है ऐसी अव्यक्त नामक अव्याकृत -- ईश्वरशक्ति जो कि मम माया दुरत्यया इत्यादि वचनोंसे कही गयी है। यहाँ एव शब्द प्रकृतिको विशेषरूपसे बतलानेके लिये है और च शब्द सारे भेदका समुच्चय करनेके लिये है। अभिप्राय यह कि यही आठ प्रकारसे विभक्त हुई अपरा प्रकृति है। तथा दश इन्द्रियाँ अर्थात् श्रोत्रादि पाँच ज्ञान उत्पन्न करनेवाली होनेके कारण ज्ञानेन्द्रियाँ और वाणी आदि पाँच कर्म सम्पादन करनेवाली होनेसे कर्मेन्द्रियाँ और एक ग्यारहवाँ संकल्पविकल्पात्मक मन तथा शब्द? स्पर्श? रूप? रस और गन्धये पाँच इन्द्रियोंके विषय। इन सबको ही सांख्यमतावलम्बी चौबीस तत्त्व कहते हैं।'),
('shankaracharya-ht:source:13.7','Śaṅkarācārya','gita.13.6','hi','translation','।।13.7।।अब जिन इच्छा आदिको वैशेषिकमतावलम्बी आत्माके धर्म मानते हैं वे भी क्षेत्रके ही धर्म हैं आत्माके नहीं यह बात भगवान् कहते हैं --, इच्छा -- जिस प्रकारके सुखदायक विषयका पहले उपभोग किया हो? फिर वैसे ही पदार्थके प्राप्त होनेपर उसको सुखका कारण समझकर मनुष्य उसे लेना चाहता है? उस चाहका नाम इच्छा है? वह अन्तःकरणका धर्म है और ज्ञेय होनेके कारण क्षेत्र है। तथा द्वेष -- जिस प्रकारके पदार्थको दुःखका कारण समझकर पहले अनुभव किया हो? फिर उसी जातिके पदार्थके प्राप्त होनेपर जो उससे मनुष्य द्वेष करता है? उस भावका नाम द्वेष है? वह भी ज्ञेय होनेके कारण क्षेत्र ही है। उसी प्रकार सुख? जो कि अनुकूल? प्रसन्नतारूप और सात्त्विक है? ज्ञेय होनेके कारण क्षेत्र ही है तथा प्रतिकूलतारूप दुःख भी ज्ञेय होनेके कारण क्षेत्र ही है। देह और इन्द्रियोंका समूह संघात कहलाता है। उसमें प्रकाशित हुई जो अन्तःकरणकी वृत्ति है जो कि अग्निसे प्रज्वलित लोहपिण्डकी भाँति आत्मचैतन्यके आभासरूपसे व्याप्त है? वह चेतना भी ज्ञेय होनेके कारण क्षेत्र ही है। व्याकुल हुए शरीर और इन्द्रियादि जिससे धारण किये जाते हैं? वह धृति भी ज्ञेय होनेसे क्षेत्र ही है। अन्तःकरणके समस्त धर्मोंका संकेत करनेके लिये यहाँ इच्छादि धर्मोंका ग्रहण किया गया है। जो कुछ कहा गया है? उसका उपसंहार करते हैं -- महत्तत्त्वादि विकारोंसे सहित क्षेत्रका यह स्वरूप संक्षेपसे कहा गया। अर्थात् जिन समस्त क्षेत्रभेदोंका समूह यह शरीर क्षेत्र है ऐसा कहा गया है? महाभूतोंसे लेकर धृतिपर्यन्त भेदोंसे विभिन्न हुए उस क्षेत्रकी व्याख्या कर दी गयी। जो आगे कहे जानेवाले विशेषणोंसे युक्त क्षेत्रज्ञ है? जिस क्षेत्रज्ञको प्रभावसहित जान लेनेसे ( मनुष्य ) अमृतरूप हो जाता है? उसको भगवान् स्वयं आगे चलकर ज्ञेयं यत्तत्प्रवक्ष्यामि इत्यादि वचनोंसे विशेषणोंके सहित कहेंगे।'),
('shankaracharya-ht:source:13.8','Śaṅkarācārya','gita.13.7','hi','translation','।।13.8।।यहाँ पहले उस ( क्षेत्रज्ञ ) के जाननेका उपायरूप जो अमानित्व आदि साधनसमुदाय है? जिसके होनेसे उस ज्ञेयको जाननेके लिये मनुष्य योग्य अधिकारी बन जाता है? जिसके परायण हुआ संन्यासी ज्ञाननिष्ठ कहा जाता है और जो ज्ञानका साधन होनेके कारण ज्ञान नामसे पुकारा जाता है? उस अमानित्वादि गुणसमुदायका भगवान् विधान करते हैं --, अमानित्व -- मानीका भाव अर्थात् अपना बड़प्पन प्रकट करना जो मानित्व है? उसका अभाव अमानित्व कहलाता है। अदम्भित्व -- अपने धर्मको प्रकट करना दम्भित्व है उसका अभाव अदम्भित्व कहा जाता है। अहिंसा -- हिंसा न करना अर्थात् प्राणियोंको कष्ट न देना। क्षमा -- दूसरोंका अपने प्रति अपराध देखकर भी विकाररहित रहना। आर्जव -- सरलता? अकुटिलता। आचार्यकी उपासना -- मोक्षसाधनका उपदेश करनेवाले गुरुका शुश्रूषा आदि प्रयोगोंसे सेवन करना। शौच -- शारीरिक मलोंको मिट्टी और जल आदिसे साफ करना और अन्तःकरणके रागद्वेष आदि मलोंको प्रतिपक्षभावनासे दूर करना। स्थिरता -- स्थिरभाव? मोक्षमार्गमें ही निश्चित निष्ठा कर लेना। आत्मविनिग्रह -- आत्माका अपकार करनेवाला और आत्मा शब्दसे कहे जानेवाला? जो कार्यकरणका संघातरूप यह शरीर है? इसका निग्रह अर्थात् इसे स्वाभाविक प्रवृत्तिसे हटाकर सन्मार्गमें ही नियुक्त कर रखना।'),
('shankaracharya-ht:source:13.9','Śaṅkarācārya','gita.13.8','hi','translation','।।13.9।।तथा --, इन्द्रियोंके शब्दादि विषयोंमें वैराग्य अर्थात् ऐहिक और पारलौकिक भोगोंमें आसक्तिका अभाव और,अनहंकार -- अहंकारका अभाव। तथा जन्म? मृत्यु? जरा? रोग और दुःखोंमें अर्थात् जन्मसे लेकर दुःखपर्यन्त प्रत्येकमें अलगअलग दोषोंका देखना। जन्ममें गर्भवास और योनिद्वारा बाहर निकलनारूप जो दोष है उसको देखना -- उसपर विचार करना। वैसे ही मृत्युमें दोष देखना? एवं बुढ़ापेमें प्रज्ञाशक्ति और तेजका तिरोभाव और तिरस्काररूप दोष देखना? तथा शिरपीड़ादि रोगरूप व्याधियोंमें दोषोंका देखना? अध्यात्म? अधिभूत और अधिदैवके निमित्तसे होनेवाले तीनों प्रकारके दुःखोंमें दोष देखना। अथवा ( यह भी अर्थ किया जा सकता है कि ) दुःख ही दोष है? इस दुःखरूप दोषको पहले कहे हुए प्रकारसे जन्मादिमें देखना अर्थात् जन्म दुःखमय है? मरना दुःख है? बुढ़ापा दुःख है और सब रोग दुःख हैं -- इस प्रकार देखना? परंतु ( यह ध्यान रहे कि ) ये जन्मादि दुःखके कारण होनेसे ही दुःख हैं? स्वरूपसे दुःख नहीं हैं। इस प्रकार जन्मादिमें दुःखरूप दोषको बारंबार देखनेसे शरीर? इन्द्रिय और विषयभोगोंमें वैराग्य उत्पन्न हो जाता है। उससे मनइन्द्रियादि करणोंकी आत्मसाक्षात्कार करनेके लिये अन्तरात्मामें प्रवृत्ति हो जाती है। इस प्रकार ज्ञानका कारण होनेसे जन्मादिमें दुःखरूप दोषकी बारंबार आलोचना करना ज्ञान कहा जाता है।'),
('shankaracharya-ht:source:13.10','Śaṅkarācārya','gita.13.9','hi','translation','।।13.10।।तथा --, असक्ति -- आसत्तिनिमित्तक विषयोंमें प्रीतिमात्रका नाम सक्ति है? उसका अभाव। अनभिष्वंग -- अभिष्वगंका अभाव। मोहपूर्वक अनन्य आत्मभावनारूप जो विशेष आसक्ति है उसका नाम अभिष्वंग है। जैसे दूसरेके सुखी या दुःखी होनेपर यह मानना कि मैं ही सुखीदुःखी हूँ। अथवा किसी अन्यके जीनेमरनेपर मैं ही जीता हूँ या मर जाऊँगा? ऐसा मानना। ( ऐसा अभिष्वंग ) कहाँ होता है ( सो कहते हैं ) पुत्र? स्त्री और घर आदिमें अर्थात् पुत्रमें? स्त्रीमें? घरमें तथा आदि शब्दका ग्रहण होनेसे अन्य जो कोई दासवर्ग आदि अत्यन्त प्रिय होते हैँ उनमें भी। असक्ति और अनभिष्वंग ये दोनों ही ज्ञानके साधन हैं? इसलिये इनको भी ज्ञान कहते हैं। तथा नित्य समचित्तता अर्थात् निरन्तर चित्तकी समानता -- किसमें इष्ट अथवा अनिष्टकी प्राप्तिमें? अर्थात् प्रिय और अप्रियकी जो बारंबार प्राप्ति होती रहती है उसमें सदा ही चित्तका सम रहना। इस साधनवाला प्रियकी प्राप्तिमें हर्षित नहीं होता और अप्रियकी प्राप्तिमें क्रोधयुक्त नहीं होता। इस प्रकारकी जो चित्तकी नित्य समता है वह भी ज्ञान है।'),
('shankaracharya-ht:source:13.11','Śaṅkarācārya','gita.13.10','hi','translation','।।13.11।।तथा --, मुझ ईश्वरमें अनन्य योगसे -- एकत्वरूप समाधियोगसे अव्यभिचारिणी भक्ति। भगवान् वासुदेवसे पर अन्य कोई भी नहीं है? अतः वही हमारी परमगति है? इस प्रकारकी जो निश्चित अविचल बुद्धि है वही अनन्य योग है? उससे युक्त होकर भजन करना ही कभी विचलित न होनेवाली अव्यभिचारिणी भक्ति है? वह भी ज्ञान है। विविक्तदेशसेवित्व -- एकान्त पवित्रदेश -- सेवनका स्वभाव। जो देश स्वभावसे पवित्र हो या झाड़नेबुहारने,आदि संस्कारोंसे शुद्ध किया गया हो तथा सर्पव्याघ्र आदि जन्तुओंसे रहित हो? ऐसे वन? नदी तीर या देवालय आदि विविक्त ( एकान्तपवित्र ) देशको सेवन करनेका जिसका स्वभाव है? वह विविक्तदेशसेवी कहलाता है? उसका भाव विविक्तदेशसेवित्व है। क्योंकि निर्जनपवित्र देशमें ही चित्त प्रसन्न और स्वच्छ होता है? इसलिये विविक्तदेशमें आत्मादिकी भावना प्रकट होती है? अतः विविक्तदेश सेवन करनेके स्वभावको ज्ञान कहा जाता है। तथा जनसमुदायमें अप्रीति। यहाँ विनयभावरहित संस्कारशून्य प्राकृत पुरुषोंके समुदायका नाम ही जनसमुदाय है। विनययुक्त संस्कारसम्पन्न मनुष्योंका समुदाय जनसमुदाय नहीं है क्योंकि वह तो ज्ञानमें सहायक है। सुतरां प्राकृतजनसमुदायमें प्रीतिका अभाव ज्ञानका साधन होनेके कारण ज्ञान है।'),
('shankaracharya-ht:source:13.12','Śaṅkarācārya','gita.13.11','hi','translation','।।13.12।।तथा --, अध्यात्मज्ञाननित्यत्व आत्मादिविषयक ज्ञानका नाम अध्यात्मज्ञान है? उसमें नित्यस्थिति। तत्त्वज्ञानके अर्थकी आलोचना अर्थात् अमानित्वादि ज्ञानसाधनोंकी परिपक्व भावनासे उत्पन्न होनेवाला जो तत्त्वज्ञान है उसका अर्थ जो संसारकी उपरतिरूप मोक्ष है? उसकी आलोचना। क्योंकि तत्त्वज्ञानके फलकी आलोचना करनेसे ही उसके साधनोंमें प्रवृत्ति होगी। अमानित्व से लेकर तत्त्वज्ञानके अर्थकी आलोचनापर्यन्त कहा हुआ समस्त साधनसमुदाय ज्ञानका साधन होनेके कारण ज्ञान इस नामसे कहा गया है। इससे अर्थात् उपर्युक्त ज्ञानसाधनोंके समुदायसे विपरीत जो मानित्व? दम्भित्व? हिंसा? क्षमाका अभाव? कुटिलता इत्यादि अवगुणसमुदाय है वह संसारमें प्रवृत्त करनेका हेतु होनेसे उसे त्याग करनेके लिये अज्ञान समझना चाहिये। उपर्युक्त ज्ञानद्वारा जाननेयोग्य क्या है इस आकाङ्क्षापर ज्ञेयं यत्तत् इत्यादि श्लोक कहते हैं -- पू0 -- अमानित्व आदि गुण तो यम और नियम हैं? उनसे ज्ञेय वस्तु नहीं जानी जा सकती क्योंकि अमानित्वादि सद्गुण किसी वस्तुके ज्ञापक नहीं देखे गये हैं। सभी जगह यह देखा जाता है कि जो ज्ञान जिस वस्तुको विषय करनेवाला होता है वही उसका ज्ञापक होता है? अन्य वस्तुविषयक ज्ञानसे अन्य वस्तु नहीं जानी जाती। जैसे घटविषयक ज्ञानसे अग्नि नहीं जाना जाता।'),
('shankaracharya-ht:source:13.13','Śaṅkarācārya','gita.13.12','hi','translation','।।13.13।।उ0 -- यह दोष नहीं है। क्योंकि हम पहले ही कह चुके हैं कि यह अमानित्वादि सद्गुण ज्ञानके साधन होनेसे और उसके सहकारी कारण होनेसे ज्ञान नामसे कहे गये हैं --, जो जाननेयोग्य है उसको भली प्रकार यथार्थ रूपसे कहूँगा। वह ज्ञेय कैसे फलवाला है यह बात? श्रोतामें रुचि उत्पन्न करके उसे सम्मुख करनेके लिये कहते हैं -- जिस जाननेयोग्य ( परमात्माके स्वरूप ) को जानकर ( मनुष्य ) अमृतको अर्थात् अमरभावको लाभ कर लेता है? फिर नहीं मरता। वह ज्ञेय अनादिमत् है। जिसकी आदि हो वह आदिमत् और जो आदिमत् न हो वह अनादिमत् कहलाता है। वह कौन है वही परम -- निरतिशय ब्रह्म जो कि इस प्रकरणमें ज्ञेयरूपसे वर्णित है। यहाँ कई एक टीकाकार अनादि मत्परम् इस प्रकार पदच्छेद करते हैं। ( कारण यह बतलाते हैं कि ) बहुव्रीहि समासद्वारा बतलाये हुए अर्थमें मतुप् प्रत्ययके प्रयोगकी निरर्थकता है? अतः वह अनिष्ट है। वे ( टीकाकार ऐसा पदच्छेद करके ) अलग अर्थ भी दिखाते हैं कि मैं वासुदेव कृष्ण ही जिसकी परम शक्ति हूँ वह ज्ञेय मत्पर है। ठीक है? यदि उपर्युक्त अर्थ सम्भव होता तो ऐसा पदच्छेद करनेसे पुनरुक्तिके दोषका निवारण हो सकता था? परंतु यह अर्थ ही सम्भव नहीं है क्योंकि यहाँ ब्रह्मका स्वरूप न सत्तन्नासदुच्यते आदि वचनोंसे सर्व विशेषणोंके प्रतिषेधद्वारा ही बतलाना इष्ट है। ज्ञेयको किसी विशेष शक्तिवाला बतलाना और विशेषणोंका प्रतिषेध भी करते जाना यह परस्परविरुद्ध है। सुतरां ( यही समझना चाहिये कि ) मतुप् प्रत्ययका और बहुव्रीहि समासका समान अर्थ होनेपर भी यहाँ श्लोकपूर्तिके लिये यह प्रयोग किया गया है। जिसका फल अमृतत्व है ऐसा ज्ञेय मेरेद्वारा कहा जाता है इस कथनसे रुचि उत्पन्न कर ( अर्जुनको ) सम्मुख करके कहते हैं -- उस ज्ञेयको न सत् कहा जा सकता है और न असत् ही कहा जा सकता है। पू0 -- कटिबद्ध होकर बड़े गम्भीर स्वरसे यह घोषणा करके कि मैं ज्ञेय वस्तुको भली प्रकार बतलाऊँगा फिर यह कहना कि वह न सत् कहा जा सकता है और न असत् ही उस घोषणाके अनुरूप नहीं है। उ0 -- यह नहीं? भगवान्का कहना तो प्रतिज्ञाके अनुरूप ही है क्योंकि वाणीका विषय न होनेके कारण सब उपनिषदोंमें भी ज्ञेय ब्रह्म ऐसा नहीं? ऐसा नहीं स्थूल नहीं? सूक्ष्म नहीं इस प्रकार विशेषोंके प्रतिषेधद्वारा ही लक्ष्य कराया गया है? ऐसा नहीं कहा गया कि वह ज्ञेय अमुक है। पू0 -- जो वस्तु अस्ति शब्दसे नहीं कही जा सकती? वह है भी नहीं। यदि ज्ञेय अस्ति शब्दसे नहीं कहा जा सकता तो वह भी वास्तवमें नहीं है। फिर यह कहना अति विरुद्ध है कि वह ज्ञेय है और अस्ति शब्दसे नहीं कहा जा सकता। उ0 -- वह ( ब्रह्म ) नहीं है? सो नहीं क्योंकि वह नहीं है इस ज्ञानका भी विषय नहीं है। पू0 -- सभी ज्ञान अस्ति या नास्ति इन बुद्धियोंमेंसे ही किसी एकके अनुगत होते हैं। इसलिये ज्ञेय भी या तो अस्ति ज्ञानसे अनुगत प्रतीतिका विषय होगा या नास्ति ज्ञानसे अनुगत प्रतीतिका विषय होगा। उ0 -- यह बात नहीं है। क्योंकि वह ब्रह्म इन्द्रियोंसे अगोचर होनेके कारण दोनों प्रकारके ही ज्ञानयसे अनुगत प्रतीतिका विषय नहीं है। इन्द्रियोंद्वारा जाननेमें आनेवाले जो कोई घट आदि पदार्थ होते हैं? वे ही या तो अस्ति इस ज्ञानसे अनुगत प्रतीतिके या अस्ति इस ज्ञानसे अनुगत प्रतीतिके विषय होते हैं। परंतु यह ज्ञेय ( ब्रह्म ) इन्द्रियातीत होनेके कारण? केवल एक शब्दप्रमाणसे ही प्रमाणित हो सकता है?,इसलिये घट आदि पदार्थोंकी भाँति यह है नहीं है इन दोनों प्रकारके ही ज्ञानोंके अनुगत प्रतीतिका विषय नहीं है? सुतरां वह न तो सत् कहा जा सकता है और न असत् ही कहा जा सकता है। तथा तुमने जो यह कहा कि ज्ञेय है किंतु वह न सत् कहा जाता है और न असत् कहा जाता है? यह कहना विरुद्ध है? सो विरुद्ध नहीं है क्योंकि वह ब्रह्म जाने हुएसे और न जाने हुएसे भी अन्य है इस श्रुतिप्रमाणसे यह बात सिद्ध है। पू0 -- यदि यह श्रुति भी विरुद्ध अर्थवाली हो तो अर्थात् जैसे यज्ञके लिये यज्ञशाला बनानेका विधान करके वहाँ कहा है कि उस बातको कौन जानता है कि परलोकमें यह सब है या नहीं इस श्रुतिके समान यह श्रुति भी विरुद्धार्थयुक्त हो तो उ0 -- यह बात नहीं है क्योंकि यह जाने हुएसे और न जाने हुएसे विलक्षणत्व प्रतिपादन करनेवाली श्रुति निस्सन्देह अवश्य ही ज्ञेय पदार्थका होना प्रतिपादन करनेवाली है और यह सब परलोकमें है या नहीं इत्यादि श्रुतिवाक्य विधिके अन्तका अर्थवाद है ( अतः उसके साथ इसकी समानता नहीं हो सकती )। युक्तिसे भी यह बात सिद्ध है कि ब्रह्म सत्असत् आदि शब्दोंद्वारा नहीं कहा जा सकता क्योंकि अर्थका प्रकाश करनेके लिये वक्ताद्वारा बोले जानेवाले और श्रोताद्वारा सुने जानेवाले सभी शब्द जाति? क्रिया? गुण और सम्बन्धद्वारा संकेत ग्रहण करवाकर ही अर्थकी प्रतीति कराते हैं? अन्य प्रकारसे नहीं। कारण? अन्य प्रकारसे प्रतीति होती नहीं देखी जाती। जैसे गौ या घोड़ा यह जातिसे? पकाना या पढ़ना यह क्रियासे? सफेद या काला यह गुणसे और धनवान् या गौओंवाला यह सम्बन्धसे ( जाने जाते हैं। इसी तरह सबका ज्ञान होता है )। परंतु ब्रह्म जातिवाला नहीं है? इसलिये सत् आदि शब्दोंद्वारा नहीं कहा जा सकता निर्गुण होनेके कारण वह गुणवान् भी नहीं है? जिससे कि गुणवाचक शब्दोंसे कहा जा सके और क्रियारहित होनेके कारण क्रियावाचक शब्दोंसे भी नहीं कहा जा सकता। ब्रह्म कलारहित? क्रियारहित और शान्त है इस श्रुतिसे भी यही बात सिद्ध होती है। तथा एक? अद्वितीय? इन्द्रियोंका अविषय और आत्मरूप होनेके कारण ( वह ब्रह्म ) किसीका सम्बन्धी भी नहीं है। अतः यह कहना उचित ही है कि ब्रह्म किसी भी शब्दसे नहीं कहा जा सकता। जहाँसे वाणी निवृत्त हो जाती है इत्यादि श्रुतिप्रमाणोंसे भी यही बात सिद्ध होती है।'),
('shankaracharya-ht:source:13.14','Śaṅkarācārya','gita.13.13','hi','translation','।।13.14।।वह ज्ञेय सत् शब्दद्वारा होनेवाली प्रतीतिका विषय नहीं है? इससे उसके न होनेकी आशङ्का होनेपर उस आशङ्काकी निवृत्तिके लिये? समस्त प्राणियोंकी इन्द्रियादि उपाधियोंद्वारा उस ज्ञेयके अस्तित्वका प्रतिपादन करते हुए कहते हैं --, वह ज्ञेय सब ओर हाथपैरवाला है अर्थात् उसके हाथपैर सर्वत्र फैले हुए हैं। सब प्राणियोंकी इन्द्रियरूप उपाधियोंद्वारा क्षेत्रज्ञका अस्तित्व प्रकट होता है। क्षेत्ररूप उपाधिके कारण ही वह ज्ञेय क्षेत्रज्ञ कहा जाता है। क्षेत्ररूप उपाधि हाथ? पैर आदि भेदसे अनेक प्रकार विभक्त है। वास्तवमें? क्षेत्रकी उपाधियोंके भेदसे किये हुए समस्त भेद क्षेत्रज्ञमें मिथ्या ही हैं? अतः उनको हटाकर ज्ञेयका स्वरूप वह न सत् कहा जा सकता है और न असत् ही कहा जा सकता है ऐसे बतलाया गया है। तथा ज्ञेयका अस्तित्व समझानेके लिये उपाधिकृत मिथ्यारूपको भी उसके धर्मकी भाँति कल्पना करके उसको सब ओरसे हाथपैरवाला है? इत्यादि प्रकारसे बतलाया जाता है। सम्प्रदायपरम्पराको जाननेवालोंका भी यही कहना है कि अध्यारोप और अपवादद्वारा प्रपञ्चरहित परमात्माकी व्याख्या की जाती है। सर्वत्र अर्थात् सब शरीरोंके अंगरूपसे स्थित हाथ? पैर आदि इन्द्रियाँ? ज्ञेय शक्तिकी सत्तासे ही स्वकार्यमें समर्थ हो रही हैं? अतः ये सब ज्ञेयकी सत्ताके चिह्न होनेके कारण उपचारसे ज्ञेयके ( धर्म ) कहे जाते हैं। ऐसे ही और सबकी भी व्याख्या कर लेनी चाहिये। वह ज्ञेय सब ओर हाथपैरवाला है? तथा सब ओर नेत्र? शिर और मुखवाला है -- जिसके आँख? शिर और मुख सर्वत्र हों? वह सर्वतोऽक्षिशिरोमुख कहलाता है तथा वह सब ओर कानवाला है -- जिसके श्रुति अर्थात् श्रवणेन्द्रिय हो वह श्रुतिमत् ( कानवाला ) कहा जाता है। इस लोकमें -- समस्त प्राणिसमुदायमें वह सबको व्याप्त करके स्थित है।'),
('shankaracharya-ht:source:13.15','Śaṅkarācārya','gita.13.14','hi','translation','।।13.15।।उपाधिरूप हाथ? पैर आदि इन्द्रियोंके अध्यारोपसे किसीको ऐसी शङ्का न हो कि ज्ञेय उन उपाधियोंवाला है? इस अभिप्रायसे यह श्लोक कहते हैं --, वह ज्ञेय समस्त इन्द्रियोंके गुणोंसे अवभासित ( प्रतीत ) होनेवाला है। यहाँ श्रोत्रादि ज्ञानेन्द्रियाँ? वाक् आदि कर्मेन्द्रियाँ तथा मन और बुद्धि ये दोनों अन्तःकरण -- इन सबका सर्व इन्द्रियोंके नामसे ग्रहण है क्योंकि अन्तःकरण भी ज्ञेयकी उपाधिके रूपमें अन्य इन्द्रियोंके समान ही है? बल्कि श्रोत्रादिका भी उपाधित्व अन्तःकरणरूप उपाधिके द्वारा ही है। इसलिये यह अभिप्राय है कि उपाधिरूप अन्तःकरण और बाह्यकरण? इन सभी इन्द्रियोंके गुण जो निश्चय? संकल्प? श्रवण और भाषण आदि हैं? उनके द्वारा वह ज्ञेय प्रतिभासित होता है अर्थात् उन इन्द्रियोंकी क्रियासे वह क्रियावान्सा दिखलायी देता है। ध्यान करता हुआसा? चेष्टा करता हुआसा इस श्रुतिसे भी यही सिद्ध होता है। तो फिर उस ज्ञेयको स्वयं क्रिया करनेवाला ही क्यों नहीं मान लिया जाता इसपर कहते हैं -- वह ज्ञेय समस्त इन्द्रियोंसे रहित है अर्थात् सब करणोंसे रहित है। इसलिये वह इन्द्रियोंके व्यापारसे ( वास्तवमें ) व्यापारवाला नहीं होता। यह जो मन्त्र है कि वह ( ईश्वर ) बिना पैर और हाथके चलता और ग्रहण करता है? बिना चक्षुके देखता और बिना कानोंके सुनता है सो इस अभिप्रायको दिखानेके लिये है कि वह ज्ञेय समस्त इन्द्रियरूप उपाधियोंके गुणोंकी अनुरूपता प्राप्त करनेमें समर्थ है? उसे साक्षात् गमनादि क्रियाओँसे युक्त बतलानेके लिये यह मन्त्र नहीं है। अन्धेने मणि प्राप्त की इत्यादि मन्त्रोंके अर्थकी भाँति उस मन्त्रका अर्थ है वह ज्ञेय समस्त इन्द्रियोंसे रहित है? इसलिये संगरहित है अर्थात् सब प्रकारके सम्बन्धोंसे रहित है। यद्यपि यह बात है तो भी वह ज्ञेय सबको धारण करनेवाला है। सत्बुद्धि सर्वत्र व्याप्त है? अतः सत् ही,सबका अधिष्ठान है। मृगतृष्णिकादि मिथ्या पदार्थ भी बिना अधिष्ठानके नहीं होते? इसलिये वह ज्ञेय सबका धारण करनेवाला है। उस ज्ञेयकी सत्ताको बतलानेवाला यह दूसरा साधन भी है। वह ज्ञेय निर्गुण यानी सत्त्व? रज और तम इन तीनों गुणोंसे अतीत है तो भी गुणोंका भोक्ता है अर्थात् वह ज्ञेय सुखदुःख और मोहके रूपमें परिणत हुए तीनों गुणोंका शब्दादिद्वारा भोग करनेवाला -- उन्हें उपलब्ध करनेवाला है।'),
('shankaracharya-ht:source:13.16','Śaṅkarācārya','gita.13.15','hi','translation','।।13.16।।तथा --, अविद्याद्वारा आत्मभावसे कल्पित शरीरको त्वचापर्यन्त अवधि मानकर उसीकी अपेक्षासे ज्ञेयको उसके बाहर बतलाते हैं। वैसे ही अन्तरात्माको लक्ष्य करके तथा शरीरको ही अवधि मानकर ज्ञेयको उसके भीतर ( व्याप्त ) बतलाया जाता है। बाहर और भीतर व्याप्त है -- ऐसा कहनेसे मध्यमें उसका अभाव प्राप्त हुआ? इसलिये कहते हैं -- चर और अचररूप भी वही है अर्थात् रज्जुमें सर्पकी भाँति प्रतीत होनेवाले जो चरअचररूप शरीरके आभास हैं? वह भी उस ज्ञेयका ही स्वरूप है। यदि चर और अचररूप समस्त व्यवहारका विषय वह ज्ञेय ( परमात्मा ) ही है? तो फिर वह यह है इस प्रकार सबसे क्यों नहीं जाना जा सकता इस पर कहते हैं -- ठीक है? सारा दृश्य उसीका स्वरूप है? तो भी वह ज्ञेय आकाशकी भाँति अति सूक्ष्म है। अतः यद्यपि वह आत्मरूपसे ज्ञेय है? तो भी सूक्ष्म होनेके कारण अज्ञानियोंके लिये अविज्ञेय ही है। ज्ञानी पुरुषोंके लिये तो? यह सब कुछ आत्मा ही है यह सब कुछ ब्रह्म ही है इत्यादि प्रमाणोंसे वह सदा ही प्रत्यक्ष रहता है। वह ज्ञेय अज्ञात होनेके कारण और हजारोंकरोड़ों वर्षोंतक भी प्राप्त न हो सकनेके कारण अज्ञानियोंके लिये बहुत दूर है? किंतु ज्ञानियोंका तो वह आत्मा ही है अतः उनके निकट ही है।'),
('shankaracharya-ht:source:13.17','Śaṅkarācārya','gita.13.16','hi','translation','।।13.17।।तथा --, वह ज्ञेय प्रत्येक शरीरमें आकाशके समान अविभक्त और एक है। तो भी समस्त प्राणियोंमें विभक्त हुआसा स्थित है क्योंकि उसकी प्रतीति शरीरोंमें ही हो रही है। तथा वह ज्ञेय स्थितिकालमें भूतभर्तृ -- भूतोंका धारणपोषण करनेवाला? प्रलयकालमें ग्रसिष्णु -- सबका संहार करनेवाला और उत्पत्तिके समय प्रभविष्णु -- सबको उत्पन्न करनेवाला है? जैसे कि मिथ्याकल्पित सर्पादिके ( उत्पत्ति? स्थिति और नाशके कारण ) रज्जु आदि होते हैं।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:13.18','Śaṅkarācārya','gita.13.17','hi','translation','।।13.18।।यदि सर्वत्र विद्यमान होते हुए भी ज्ञेय प्रत्यक्ष नहीं होता? तो क्या वह अन्धकार है नहीं। तो क्या है --, वह ज्ञेय ( परमात्मा ) समस्त सूर्यादि ज्योतियोंका भी परम ज्योति है क्योंकि आत्मचैतन्यके प्रकाशसे देदीप्यमान होकर ही ये सूर्य आदि समस्त ज्योतियाँ प्रकाशित हो रही हैं। जिस तेजसे प्रदीप्त होकर सूर्य तपता है उसीके प्रकाशसे यह सब कुछ प्रकाशित है इत्यादि,श्रुतिप्रमाणोंसे और यहीं कहे हुए यदादित्यगतं तेजः इत्यादि स्मृतिवाक्योंसे भी उपर्युक्त बात ही सिद्ध होती है। तथा वह ज्ञेय अन्धकारसे -- अज्ञानसे परे अर्थात् अस्पृष्ट बतलाया जाता है। ज्ञान आदिका सम्पादन करना बहुत दुर्घट है -- ऐसी बुद्धिसे उत्साहरहित -- खिन्नचित्त हुए साधकको उत्साहित करनेके लिये कहते हैं -- ज्ञान अर्थात् अमानित्व आदि ज्ञानके साधन? ज्ञेय अर्थात् ज्ञेयं यत्तत्प्रवक्ष्यामि इत्यादि वाक्योंसे बतलाया हुआ परमात्माका स्वरूप और ज्ञानगम्य -- ज्ञेय ही जान लिया जानेपर ज्ञानका फल होनेके कारण ( पहले ) ज्ञानगम्य कहा जाता है और जब जान लिया जाता है उस अवस्थामें ज्ञेय कहलाता है। ये तीनों ही समस्त प्राणिमात्रके अन्तःकरणमें विशेषरूपसे स्थित हैं क्योंकि ये तीनों वहीं प्रकाशित होते हैं।'),
('shankaracharya-ht:source:13.19','Śaṅkarācārya','gita.13.18','hi','translation','।।13.19।।उपर्युक्त समस्त अर्थका उपसंहार करनेके लिये यह श्लोक आरम्भ किया जाता है --, इस प्रकार यह महाभूतोंसे लेकर धृतिपर्यन्त क्षेत्रका स्वरूप?अमानित्व आदिसे लेकर तत्त्वज्ञानार्थदर्शन पर्यन्त ज्ञानका स्वरूप और ज्ञेयं यत्तत् यहाँ लेकर तमसः परमुच्यते यहाँतक ज्ञेयका स्वरूप? संक्षेपसे कह दिया गया। यह सब वेदोंका और गीताका अर्थ इकट्ठा करके कहा गया है। इस यथार्थ ज्ञानका अधिकारी कौन है? सो कहा जाता है -- मेरा भक्त अर्थात् मुझ सर्वज्ञ? परमगुरु? वासुदेव परमेश्वरमें अपने सारे भावोंको जिसने अर्पण कर दिया है। जिस किसी भी वस्तुको देखता? सुनता और स्पर्श करता है? उस सबमें सब कुछ भगवान् वासुदेव ही है ऐसी निश्चित बुद्धिवाला जो मेरा भक्त है। वह उपर्युक्त यथार्थ ज्ञानको समझकर मेरे भावको अर्थात् मेरा जो परमात्मभाव है? उसको प्राप्त करनेमें समर्थ होता है? अर्थात् मोक्ष लाभ कर लेता है।'),
('shankaracharya-ht:source:13.20','Śaṅkarācārya','gita.13.19','hi','translation','।।13.20।।सातवें अध्यायमें ईश्वरकी क्षेत्र और क्षेत्रज्ञरूप अपरा और परा -- दो प्रकृतियाँ बतलायी गयी हैं तथा यह भी कहा गया है कि ये दोनों प्रकृतियाँ समस्त प्राणियोंकी योनि ( कारण ) हैं। अब यह बात बतलायी जाती है कि वे क्षेत्र और क्षेत्रज्ञरूप दोनों प्रकृतियाँ सब भूतोंकी योनि किस प्रकार हैं --, प्रकृति और पुरुष जो कि ईश्वरकी प्रकृतियाँ हैं? उन दोनोंको ही तू अनादि जान। जिनका आदि न हो उनका नाम अनादि है। ईश्वरका ईश्वरत्व नित्य होनेके कारण उसकी दोनों प्रकृतियोंका भी नित्य होना उचित ही है क्योंकि इन दोनों प्रकृतियोंसे युक्त होना ही ईश्वरकी ईश्वरता है। जिन दोनों प्रकृतियोंद्वारा ईश्वर जगत्की उत्पत्ति स्थिति और प्रलयका कारण है? वे दोनों अनादिसिद्ध ही संसारकी कारण हैं। कोईकोई टीकाकार जो आदि ( कारण ) नहीं हैं वे अनादि कहे जाते हैं? इस प्रकार यहाँ तत्पुरुषसमासका वर्णन करते हैं ( और कहते हैं कि ) इससे केवल ईश्वर ही जगत्का कारण है? यह बात,सिद्ध होती है। यदि प्रकृति और पुरुषको नित्य माना जाय तो संसार उन्हींका रचा हुआ माना जायगा? ईश्वर जगत्का कर्ता सिद्ध न होगा। किंतु ऐसा मानना ठीक नहीं क्योंकि ( यदि प्रकृति और पुरुषको नित्य न माने तो ) प्रकृति और पुरुषकी उत्पत्तिसे पूर्व शासन करने योग्य वस्तुका अभाव होनेसे ईश्वरमें अनीश्वरताका प्रसङ्ग आ जाता है। तथा संसारको बिना निमित्तके उत्पन्न हुआ माननेसे उसके अन्तके अभावका प्रसङ्ग? शास्त्रकी व्यर्थताका प्रसङ्ग और बन्धमोक्षके अभावका प्रसङ्ग प्राप्त होता है? ( इसलिये भी उपर्युक्त अर्थ ठीक नहीं है। ) परंतु ईश्वरकी इन दोनों प्रकृतियोंको नित्य मान लेनेसे यह सब व्यवस्था ठीक हो जाती है। कैसे ( सो कहते हैं -- ) विकारोंको और गुणोंको तू प्रकृतिसे उत्पन्न जान अर्थात् बुद्धिसे लेकर शरीर और इन्द्रियोंतक अगले श्लोकमें बतलाये हुए विकारोंको तथा सुखदुःख और मोह आदि वृत्तियोंके रूपमें परिणत हुए तीनों गुणोंको तू प्रकृतिसे उत्पन्न हुए जान। अभिप्राय यह है कि विकारोंकी कारणरूपा जो ईश्वरकी त्रिगुणमयी माया शक्ति है? उसका नाम प्रकृति है। वह जिन विकारों और गुणोंको उत्पन्न करनेवाली है? उन विकारों और गुणोंको तू प्रकृतिजनित -- प्रकृतिके ही परिणाम समझ।'),
('shankaracharya-ht:source:13.21','Śaṅkarācārya','gita.13.20','hi','translation','।।13.21।।प्रकृतिसे उत्पन्न हुए वे विकार और गुण कौनसे हैं --, कार्य शरीरको कहते हैं और उसमें स्थित ( मन? बुद्धि? अहंकार तथा दश इन्द्रियाँ -- ये ) तेरह कारण हैं। इनके कर्त्तापनमें ( हेतु प्रकृति है )। शरीरको उत्पन्न करनेवाले पाँच भूत और शब्द आदि पाँच विषय ये पहले कहे हुए प्रकृतिजन्य दश विकार तो यहाँ कार्यके ग्रहणसे ग्रहण किये जाते हैं और सुखदुःख? मोह आदिके रूपमें परिणत हुए प्रकृतिजन्य समस्त गुण बुद्धि आदि कारणोंके आश्रित होनेके कारण करणोंके ग्रहणसे ग्रहण किये जाते हैं। उन कार्य और करणोंका जो कर्तापन अर्थात् उनको उत्पन्न करनेका भाव है उसका नाम कार्यकरण कर्तृत्व है? उन कार्यकरणोंके कर्तृत्वमें आरम्भ करनेवाली होनेसे प्रकृति कारण कही जाती है। इस प्रकार कार्यकरणोंको उत्पन्न करनेवाली होनेसे प्रकृति संसारकी कारण है। कार्यकारणकर्तृत्वे ऐसा पाठ माननेसे भी यही अर्थ होगा कि जो जिसका परिणाम है? वह उसका कार्य अर्थात् विकार है? और कारण विकारी -- विकृत होनेवाला -- है। उन विकारी और विकाररूप कारण और कार्योंके उत्पन्न करनेमें ( प्रकृति हेतु है )। अथवा सोलह विकार तो कार्य और सात प्रकृति विकृति कारण हैं? इस प्रकार ये ( तेईस तत्त्व ) ही कार्यकारणके नामसे कहे जाते हैं। इनके कर्तापनमें प्रारम्भकत्वसे ही प्रकृति हेतु कही जाती है। पुरुष भी जिस प्रकार संसारका कारण होता है? सो कहा जाता है -- पुरुष अर्थात् जीव? क्षेत्रज्ञ? भोक्ता इत्यादि जिसके पर्याय शब्द है? वह सुखदुःख आदि भोगोंके भोक्तापनमें,अर्थात् उनका उपभोग करनेमें हेतु कहा जाता है। पू0 -- परंतु इस कार्यकरणके कर्तापनसे और सुख दुःखके भोक्तापनसे प्रकृति और पुरुष दोनोंको संसारका कारण कैसे बतलाया जाता है उ0 -- कार्यकरण और सुखदुःखादिरूप हेतु और फलके आकारमें प्रकृतिका परिणाम न होनेपर तथा चेतन पुरुषमें उन सबका भोक्तापन न होनेसे संसार कैसे सिद्ध होगा। जब कार्यकरणरूप हेतु और फलके आकारमें परिणत हुई भोग्यरूपा प्रकृतिके साथ उससे विपरीत धर्मवाले पुरुषका? भोक्ता भावसे अविद्यारूप संयोग होगा? तभी संसार ( प्रतीत ) होगा। इसलिये प्रकृतिके कार्यकरणविषयक कर्तापन और पुरुषके सुख दुःखविषयक भोक्तापनको लेकर जो उन दोनोंका संसारकारणत्व प्रतिपादन किया गया? वह उचित ही है। पू0 -- तो यह संसारनामक वस्तु क्या है उ0 -- सुख दुःखोंका भोग ही संसार है और पुरुषमें जो सुखदुःखोंका भोक्तृत्व है? यही उसका संसारित्व है।'),
('shankaracharya-ht:source:13.22','Śaṅkarācārya','gita.13.21','hi','translation','।।13.22।।यह जो कहा कि सुखदुःखोंका भोक्तृत्व ही पुरुषका संसारित्व है? सो वह उसमें किस कारणसे है यह बतलाते हैं --, क्योंकि पुरुष -- जीवात्मा प्रकृतिमें स्थित है अर्थात् कार्य और करणके रूपमें परिणत हुई अविद्यारूपा प्रकृतिमें स्थित है -- प्रकृतिको अपना स्वरूप मानता है? इसलिये वह प्रकृतिसे उत्पन्न हुए सुखदुःख और मोहरूपसे प्रकट गुणोंको मैं सुखी हूँ? दुःखी हूँ? मूढ़ हूँ? पण्डित हूँ इस प्रकार मानता हुआ भोगता है अर्थात् उनका उपभोग करता है। यद्यपि जन्मका कारण अविद्या है तो भी भोगे जाते हुए सुखदुःख और मोहरूप गुणोंमें जो आसक्त हो जाना है -- तद्रूप हो जाना है? वह जन्मरूप संसारका प्रधान कारण है। वह जैसी कामनावाला होता है वैसा ही कर्म करता है इस श्रुतिसे भी यही बात सिद्ध होती है। इसी बातको भगवान् कहते हैं कि गुणोंका सङ्ग ही अर्थात् गुणोंमें जो आसक्ति है वही इस भोक्ता पुरुषके अच्छीबुरी योनियोंमें जन्म लेनेका कारण है। अच्छी और बुरी योनियोंका नाम सदसत् योनि है? उनमें जन्मोंका होना सदसद्योनिजन्म है? इन भोग्यरूप सदसद्योनिजन्मोंका कारण गुणोंका सङ्ग ही है। अथवा संसारपदका अध्याहार करके यह अर्थ कर लेना चाहिये कि अच्छी औरबुरी योनियोंमें जन्म लेकर गुणोंका सङ्ग करना ही इस संसारका कारण है। देवादि योनियाँ सत् योनि हैं और पशु आदि योनियाँ असत् योनि हैं। प्रकरणकी सामर्थ्यसे मनुष्ययोनियोंको भी सत् असत् योनियाँ माननेमें ( किसी प्रकारका ) विरोध नहीं समझना चाहिये। कहनेका तात्पर्य यह है कि प्रकृतिमें स्थित होनारूप अविद्या और गुणोंका सङ्ग -- आसक्ति ये ही दोनों संसारके कारण हैं और वे छोड़नेके लिये ही बतलाये गये हैं। गीताशास्त्रमें इनकी निवृत्तिके साधन संन्यासके सहित ज्ञान और वैराग्य प्रसिद्ध हैं। वह क्षेत्रक्षेत्रज्ञविषयक ज्ञान पहले बतलाया ही गया है। साथ ही ( न सत्तन्नासदुच्यते इत्यादि कथनसे ) अन्यों ( धर्मों ) का निषेध करके और ( सर्वतः पाणिपादम् इत्यादि कथनसे ) अनात्म धर्मोंका अध्यारोप करके ज्ञेयके स्वरूपका भी यज्ज्ञात्वामृतमश्नुते आदि वचनोंसे प्रतिपादन किया गया है।'),
('shankaracharya-ht:source:13.23','Śaṅkarācārya','gita.13.22','hi','translation','।।13.23।।उसीका फिर साक्षात् निर्देश किया जाता है --, ( यह आत्मा ) उपद्रष्टा है अर्थात् स्वयं क्रिया न करता हुआ पासमें स्थित होकर देखनेवाला है। जैसे कोई यज्ञविद्यामें कुशल अन्य पुरुष स्वयं यज्ञ न करता हुआ? यज्ञकर्ममें लगे हुए पुरोहित और यजमानोंद्वारा किये हुए कर्मसम्बन्धी गुणदोषोंको तटस्थभावसे देखता है? उसी प्रकार कार्य और करणोंके व्यापारमें स्वयं न लगा हुआ उनसे अन्यविलक्षण आत्मा उन व्यापारयुक्त कार्य और करणोंको समीपस्थ भावसे देखनेवाला है। अथवा देह? चक्षु? मन? बुद्धि और आत्मा -- ये सभी द्रष्टा हैं? उनमें बाह्य द्रष्टा शरीर है और उससे लेकर उन सबकी अपेक्षा अन्तरतम -- समीपस्थ द्रष्टा अन्तरात्मा है। जिसकी अपेक्षा और कोई आन्तरिक द्रष्टा न हो? वह अतिशय सामीप्य भावसे देखनेवाला होनेके कारण उपद्रष्टा होता है ( अतः आत्मा उपद्रष्टा है )। अथवा ( यों समझो कि ) यज्ञके उपद्रष्टाकी भाँति सबका अनुभव करनेवाला होनेसे आत्मा उपद्रष्टा है। तथा यह अनुमन्ता है -- क्रिया करनेमें लगे हुए अन्तःकरण और इन्द्रियादिकी क्रियाओंमें सन्तोषरूप अनुमोदनका नाम अनुमनन है? उसका करनेवाला है। अथवा यह इसीलिये अनुमन्ता है कि कार्यकरणकी प्रवृत्तिमें स्वयं प्रवृत्त न होता हुआ भी उनके अनुकूल प्रवृत्त हुआ सा दीखता है। अथवा अपने व्यापारमें लगे हुए अन्तःकरण और इन्द्रियादिको उनका साक्षी होकर भी कभी निवारण नहीं करता? इसलिये अनुमन्ता है। तथा यह भर्ता है? चैतन्यस्वरूप आत्माके भोग और अपवर्गकी सिद्धिके निमित्तसे संहत हुए चेतन्यके आभासरूप शरीर? इन्द्रिय? मन और बुद्धि आदिका स्वरूप धारण करना भी भरण है और वह चैतन्यरूप आत्माका ही किया हुआ है? इसलिये आत्माको भर्ता कहते हैं। आत्मा भोक्ता है। अग्निके उष्णत्वकी भाँति नित्यचैतन्य आत्मसत्तासे समस्त विषयोंमें पृथक्पृथक् होनेवाली जो बुद्धिकी सुखदुःख और मोहरूप प्रतीतियाँ हैं? वे सब चैतन्य आत्माद्वारा ग्रस्त की हुईसी दीखती हैं? अतः आत्माको भोक्ता कहा जाता है। आत्मा महेश्वर है। वह सबका आत्मा होनेके कारण और स्वतन्त्र होनेके कारण महान् ईश्वर है? इसलिये महेश्वर है। वह परमात्मा है। अविद्याद्वारा प्रत्यक् आत्मारूप माने हुए जो शरीरसे लेकर बुद्धिपर्यन्त ( आत्मशब्दवाच्य पदार्थ ) हैं। उन सबसे उपद्रष्टा आदि लक्षणोंवाला आत्मा परम ( श्रेष्ठ ) है -- इसलिये वह परमात्मा है। श्रुतिमें भी वह भीतर व्यापक परमात्मा है इन शब्दोंसे उसका वर्णन किया गया है। ऐसा आत्मा कहाँ है वह अव्यक्तसे पर पुरुष इसी शरीरमें है जो कि उत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः इस प्रकार आगे कहा जायगा और जो क्षेत्रज्ञं चापि मां विद्धि इस प्रकार पहले कहा जा चुका है तथा जिसकी व्याख्या करके उपसंहार किया गया है।'),
('shankaracharya-ht:source:13.24','Śaṅkarācārya','gita.13.23','hi','translation','।।13.24।।इस प्रकार उस उपर्युक्त लक्षणोंसे युक्त आत्माको --, उस पुरुषको जो मनुष्य उपर्युक्त प्रकारसे अर्थात् साक्षात् आत्मभावसे कि यही मैं हूँ इस प्रकार जानता है और उपर्युक्त अविद्यारूप प्रकृतिको भी? अपने विकाररूप गुणोंके सहित? विद्याद्वारा निवृत्त की हुई -- अभावको प्राप्त की हुई जानता है। वह सब प्रकारसे बर्तता हुआ भी? इस विद्वत्शरीरके नाश होनेपर फिर दूसरे शरीरमें जन्म नहीं लेता अर्थात् दूसरे शरीरको ग्रहण नहीं करता। अपि शब्दसे यह अभिप्राय है कि अपने वर्णाश्रमधर्मके अनुकूल बर्तनेवाला पुनः उत्पन्न नहीं होता? इसमें तो कहना ही क्या है पू0 -- यद्यपि ज्ञान उत्पन्न होनेके पश्चात् पुनर्जन्मका अभाव बतलाया गया है? तथापि ज्ञान उत्पन्न होनेसे पहले किये हुए? ज्ञानोत्पत्तिके पश्चात् किये जानेवाले और अनेक भूतपूर्व जन्मोंमें किये हुए जो कर्म हैं? फल प्रदान किये बिना उनका नाश मानना युक्तियुक्त नहीं है? अतः ( ज्ञान प्राप्त होनेके बाद भी ) तीन जन्म और होने चाहिये। अभिप्राय यह है कि सभी कर्म समान हैं? उनमें कोई भेद प्रतीत नहीं होता? अतः फल देनेके लिये प्रवृत्त हुए जन्मारम्भ करनेवाले प्रारब्ध कर्मोंके समान ही किये हुए अन्य कर्मोंका भी ( बिना फल दिये ) नाश ( मानना ) उचित नहीं? सुतरां तीनों प्रकारके कर्म तीन जन्मोंका आरम्भ करेंगे अथवा सब मिलकर एक जन्मका ही आरम्भ करेंगे ( ऐसा मानना चाहिये )। नहीं तो किये हुए कर्मोंका ( बिना फल दिये ) नाश माननेसे? सर्वत्र अविश्वासका प्रसंग आ जायगा और शास्त्रकी व्यर्थता सिद्ध हो जायगी। अतः यह कहना कि वह फिर जन्म नहीं लेता ठीक नहीं है। उ0 -- यह बात नहीं क्योंकि इसके समस्त कर्म क्षय हो जाते हैं ब्रह्मको जाननेवाला ब्रह्म ही हो जाता है उसके ( मोक्षमें ) तभीतककी देर है अग्निमें तृणके अग्रभागकी भाँति उसके समस्त कर्म भस्म हो जाते हैं इत्यादि सैकड़ों श्रुतियोंद्वारा विद्वान्के सब कर्मोंका दाह होना कहा गया है। यहाँ गीताशास्त्रमें भी यथैधांसि इत्यादि श्लोकमें समस्त कर्मोंका दाह कहा गया है और आगे भी कहेंगे। युक्तिसे भी यही बात सिद्ध होती है क्योंकि अविद्या? कामना आदि क्लेशरूप बीजोंसे युक्त हुए ही कारणरूप कर्म अन्य जन्मरूप अंकुरका आरम्भ किया करते हैं। यहाँ गीताशास्त्रमें भी भगवान्ने जगहजगह कहा है कि अहंकार और फलाकाङ्क्षायुक्त कर्म ही फलका आरम्भ करनेवाले होते हैं? अन्य नहीं। तथा जैसे अग्निमें दग्ध हुए बीज फिर नहीं उगते? वैसे ही ज्ञानसे दग्ध हुए क्लेशोंद्वारा आत्मा पुनः शरीर,ग्रहण नहीं करता ऐसा भी ( शास्त्रोंका वचन है )। पू0 -- ज्ञान होनेके पश्चात् किये हुए कर्मोंका ज्ञानद्वारा दाह हो सकता है क्योंकि वे ज्ञानके साथ होते हैं। परंतु इस जन्ममें ज्ञान उत्पन्न होनेसे पहले किये हुए और भूतपूर्व अनेक जन्मोंमें किये हुए कर्मोंका? ज्ञानद्वारा नाश मानना उचित नहीं। उ0 -- यह कहना ठीक नहीं क्योंकि सारे कर्म ( दग्ध हो जाते हैं ) ऐसा विशेषण दिया गया है। पू0 -- यदि ऐसा मानें कि ज्ञानके पश्चात् होनेवाले सब कर्मोंका ही ( ज्ञानद्वारा दाह होता है तो ) उ0 -- यह बात नहीं है। क्योंकि ( इस प्रकारके ) संकोचका ( कोई ) कारण नहीं सिद्ध होता। तुमने जो कहा कि जैसे ज्ञान हो जानेपर भी? वर्तमान जन्मका आरम्भ करनेवाले? फल देनेके लिये प्रवृत्त हुए प्रारब्धकर्म नष्ट नहीं होते? वैसे ही जिनका फल आरम्भ नहीं हुआ है? उन कर्मोंका भी नाश ( मानना ) युक्तियुक्त नहीं है? सो ऐसा कहना भी ठीक नहीं। क्योंकि वे प्रारब्ध कर्म छोड़े हुए बाणकी भाँति फल देनेके लिये प्रवृत्त हो चुके हैं? इसलिये ( उनका फल अवश्य होता है? पर अन्यका नहीं )। जैसे पहले लक्ष्यका वेध करनेके लिये धनुषसे छोड़ा हुआ बाण? लक्ष्यवेध हो जानेके पश्चात् ही आरम्भ हुए वेगका नाश होनेपर गिरकर ही शान्त होता है? वैसे ही शरीरका आरम्भ करनेवाले प्रारब्ध कर्म भी? शरीरस्थितिरूप प्रयोजनके निवृत्त हो जानेपर भी? जबतक संस्कारोंका वेग क्षय नहीं हो जाता? तबतक पहलेकी भाँति बर्तते ही रहते हैं। वही बाण? जिसका प्रवृत्तिके लिये वेग आरम्भ नहीं हुआ है -- जो छोड़ा नहीं गया है? यदि धनुषपर चढ़ा भी लिया गया हो तो भी उसको रोका जा सकता है? वैसे ही जिन कर्मोंके फलका आरम्भ नहीं हुआ है? वे अपने आश्रयमें स्थित हुए ही ज्ञानद्वारा निर्बीज किये जा सकते हैं। अतः इस विद्वत्शरीरके गिरनेके पीछे वह फिर उत्पन्न नहीं होता यह कहना उचित ही है? यह बात सिद्ध हुई।'),
('shankaracharya-ht:source:13.25','Śaṅkarācārya','gita.13.24','hi','translation','।।13.25।।यहाँ आत्मदर्शनके विषयमें ये ध्यान आदि भिन्नभिन्न साधन विकल्पसे कहे जाते हैं --, शब्दादि विषयोंसे श्रोत्रादि इन्द्रियोंको हटाकर उनका मनमें निरोध करके और मनको अन्तरात्मामें ( निरोध करके ) जो एकाग्रभावसे चिन्तन करते रहना है? उसका नाम ध्यान है। तथा जैसे बगुला ध्यान करता है जैसे पृथिवी ध्यान करती है जैसे पर्वत ध्यान करते हैं इत्यादि उपमा दी जानेके कारण तैलधाराकी भाँति निरन्तर अविच्छिन्नभावसे चिन्तन करनेका नाम ध्यान है? उस ध्यानद्वारा कितने ही योगीलोग आत्मामें -- बुद्धिमें? आत्माको यानी प्रत्यक्चेतनको आत्मासे -- ध्यानाभ्यासद्वारा शुद्ध हुए अन्तःकरणसे -- देखते हैं। अन्य कई योगीजन सांख्ययोगके द्वारा ( देखते हैं ) -- सत्त्व? रज और तम -- ये तीनों गुण मुझसे देखे जानेवाले हैं और मैं उनसे भिन्न उनके व्यापारका साक्षी? उन गुणोंसे विलक्षण और नित्य ( चेतन ) आत्मा हूँ इस प्रकारके चिन्तनका नाम सांख्य है? यही योग है? ऐसे सांख्ययोगके द्वारा -- आत्मामें आत्माको देखते हैं। तथा अपर योगीजन कर्मयोगके द्वारा -- ईश्वरार्पणबुद्धिसे अनुष्ठान की हुई चेष्टाका नाम कर्म है? वही योगका साधन होनेके कारण गौणरूपसे योग कहा जाता है? उस कर्मयोगके द्वारा -- अन्तःकरणकी शुद्धि और,ज्ञानप्राप्तिके क्रमसे? ( आत्मामें आत्माको देखते हैं )।'),
('shankaracharya-ht:source:13.26','Śaṅkarācārya','gita.13.25','hi','translation','।।13.26।।अन्य कई एक साधकजन उपर्युक्त विकल्पोंमेंसे किसी एकके भी द्वारा पूर्वोक्त आत्मतत्त्वको न जानते हुए अन्य आचार्योंसे सुनकर -- उनकी ऐसी आज्ञा पाकर कि तुम इसीका चिन्तन किया करो उपासना करते हैं -- श्रद्धापूर्वक चिन्तन करते हैं। वे केवल सुननेके परायण हुए पुरुष भी अर्थात् जिनके मतमें श्रवण करना ही मोक्षमार्गसम्बन्धी प्रवृत्तिमें परम आश्रय -- गति? परम साधन है? ऐसे केवल अन्य आचार्योंके उपदेशको ही प्रमाण माननेवाले? स्वयं विवेकहीन श्रुतिपरायण पुरुष भी मृत्युको यानी मृत्युयुक्त संसारको निःसंन्देह पार कर जाते हैं। फिर प्रमाण करनेमें जो स्वतन्त्र हैं वे विवेकी पुरुष मृत्युयुक्त संसारसे तर जाते हैं? इसमें तो कहना ही क्या है यह अभिप्राय है।,'),
('shankaracharya-ht:source:13.27','Śaṅkarācārya','gita.13.26','hi','translation','।।13.27।।क्षेत्रज्ञ और ईश्वरकी एकताविषयक ज्ञान मोक्षका साधन है? यह बात यज्ज्ञात्वामृतमश्नुते इस वाक्यसे कही? परंतु वह ज्ञान किस कारणसे मोक्षका साधन है उस कारणको दिखानेके लिये यह श्लोक आरम्भ किया जाता है --, हे भरतश्रेष्ठ जो कुछ भी वस्तु उत्पन्न होती है? क्या यहाँ समानभावसे वस्तुमात्रका ग्रहण है इसपर कहते हैं कि जो कुछ स्थावरजंगम यानी चर और अचर वस्तु उत्पन्न होती है? वह सब क्षेत्र और क्षेत्रज्ञके संयोगसे ही उत्पन्न होती है? इस प्रकार तू जान। पू0 -- इस क्षेत्र और क्षेत्रज्ञके संयोगसे क्या अभिप्राय है क्योंकि क्षेत्रज्ञ? आकाशके समान अवयवरहित है? इसलिये उसका क्षेत्रके साथ रस्सीसे घड़ेके सम्बन्धकी भाँति? अवयवोंके संसर्गसे होनेवाला सम्बन्धरूप संयोग नहीं हो सकता। वैसे ही आपसमें एकदूसरेका कार्यकारणभाव न होनेसे सूत और कपड़ेकी भाँति? क्षेत्र और क्षेत्रज्ञका समवायसम्बन्धरूप संयोग भी नहीं बन सकता। उ0 -- बताया जाता है? ( सुनो )। क्षेत्र और क्षेत्रज्ञ? जो कि विषय और विषयी तथा भिन्न स्वभाववाले हैं? उनका? अन्यमें अन्यके धर्मोंका अध्यासरूप संयोग है? यह संयोग रज्जु और सीप आदिमें उनके स्वरूपसम्बन्धी ज्ञानके अभावसे अध्यारोपित सर्प और चाँदी आदिके संयोगकी भाँति? क्षेत्र और क्षेत्रज्ञके वास्तविक स्वरूपको न जाननेके कारण है। ऐसा यह अध्यासस्वरूप क्षेत्र और क्षेत्रज्ञका संयोग मिथ्या ज्ञान है। जो पुरुष शास्त्रोक्त रीतिसे क्षेत्र और क्षेत्रज्ञके लक्षण और भेदको जानकर? पहले जिसका स्वरूप दिखलाया गया है? उस क्षेत्रसे मूँजमेंसे सींक अलग करनेकी भाँति पूर्वोक्त लक्षणोंसे युक्त क्षेत्रज्ञको अलग करके देखता है अर्थात् उस ज्ञेयस्वरूप क्षेत्रज्ञको न सत्तन्नासदुच्यते इस वाक्यानुसार समस्त उपाधिरूप विशेषताओंसे अतीत ब्रह्मस्वरूपसे देख लेता है। तथा जो क्षेत्रको मायासे रचे हुए हाथी? स्वप्नमें देखी हुई वस्तु या गन्धर्वनगर आदिकी भाँति यह वास्तवमें नहीं है तो भी सत्की भाँति प्रतीत होता है? ऐसे निश्चयपूर्वक जान लेता है? उसका मिथ्याज्ञान उपर्युक्त यथार्थ ज्ञानसे विरुद्ध होनेके कारण नष्ट हो जाता है। पुनर्जन्मके कारणरूप उस मिथ्याज्ञानका अभाव हो जानेपर य एवं वेत्ति पुरुषं प्रकृतिं च गुणैः सह इस श्लोकसे जो यह कहा गया है कि विद्वान् पुनः उत्पन्न नहीं होता सो युक्तियुक्त ही है।'),
('shankaracharya-ht:source:13.28','Śaṅkarācārya','gita.13.27','hi','translation','।।13.28।। न स भूयोऽभिजायते इस कथनसे पूर्णज्ञानका फल? अविद्या आदि संसारके बीजोंकी निवृत्तिद्वारा पुनर्जन्मका अभाव बतलाया गया? तथा अविद्याजनित क्षेत्र और क्षेत्रज्ञके संयोगको जन्मका कारण बतलाया गया। इसलिये उस अविद्याको निवृत्ति करनेवाला पूर्ण ज्ञान? यद्यपि पहले कहा जा चुका है तो भी दूसरे शब्दोंमें फिर कहा जाता है --, ( जो पुरुष ) ब्रह्मासे लेकर स्थावरपर्यन्त समस्त प्राणियोंमें समभावसे स्थित -- ( व्याप्त ) हुए परमेश्वरको अर्थात् शरीर? इन्द्रिय? मन? बुद्धि अव्यक्त और आत्माकी अपेक्षा जो परम ईश्वर है? उस परमेश्वरको सब भूतोंमें समभावसे स्थित देखता है। यहाँ भूतोंसे परमेश्वरकी अत्यन्त विलक्षणता दिखलानेके निमित्त भूतोंके लिये विनाशशील और परमेश्वरके लिये अविनाशी विशेषण देते हैं। पू0 -- इससे परमेश्वरकी विलक्षणता कैसे सिद्ध होती है उ0 -- सभी भावविकारोंका जन्मरूप? भावविकार मूल है। अन्य सब भावविकार जन्मके पीछे होनेवाले और विनाशमें समाप्त होनेवाले हैं। भावका अभाव हो जानेके कारण विनाशके पश्चात् कोई भी भावविकार नहीं रहता क्योंकि धर्मीके रहते ही धर्म रहते हैं। इसलिये अन्तिम भावविकारके अभावका ( अविनश्यन्तम् इस पदके द्वारा ) अनुवाद करनेसे पहले होनेवाले? सभी भावविकारोंका कार्यके सहित प्रतिषेध हो जाता है। सुतरां ( उपर्युक्त वर्णनसे ) परमेश्वरकी सब भूतोंसे अत्यन्त ही विलक्षणता तथा निर्विशेषता और एकता भी सिद्ध होती है। अतः जो इस प्रकार उपर्युक्त भावसे परमेश्वरको देखता है वही देखता है। पू0 -- सभी लोग देखते हैं फिर वही देखता है इस विशेषणसे क्या प्रयोजन है उ0 -- ठीक है? ( अन्य सब भी ) देखते हैं परंतु विपरीत देखते हैं? इसलिये वह विशेषण दिया गया है कि वही देखता है। जैसे कोई तिमिररोगसे दूषित हुई दृष्टिवाला अनेक चन्द्रमाओंको देखता है? उसकी अपेक्षा एक चन्द्र देखनेवालेकी यह विशेषता बतलायी जाती है कि वही ठीक देखता है। वैसे ही यहाँ भी जो आत्माको उपर्युक्त प्रकारसे विभागरहित एक देखता है? उसकी अलगअलग अनेक आत्मा देखनेवाले विपरीतदर्शियोंकी अपेक्षा यह विशेषता बतलायी जाती है कि वही ठीकठीक देखता है। अभिप्राय यह है कि दूसरे सब अनेक चन्द्र देखनेवालेकी भाँति विपरीत भावसे देखनेवाले होनेके कारण? देखते हुए भी वास्तवमें नहीं देखते।'),
('shankaracharya-ht:source:13.29','Śaṅkarācārya','gita.13.28','hi','translation','।।13.29।।उपर्युक्त यथार्थ ज्ञानका फल बतलाकर उसकी स्तुति करनी चाहिये। इसलिये यह श्लोक आरम्भ किया जाता है --, क्योंकि सर्वत्र -- सब भूतोंमें समभावसे स्थित हुए ईश्वरको अर्थात् ऊपरके श्लोकमें जिसके लक्षण बतलाये गये हैं? उस ( परमेश्वर ) को सर्वत्र समान भावसे देखनेवाला पुरुष स्वयं -- अपने आप अपनी हिंसा नहीं करता? इसलिये अर्थात् अपनी हिंसा न करनेके कारण वह मोक्षरूप परम उत्तम गतिको प्राप्त होता है। पू0 -- कोई भी प्राणी स्वयं अपनी हिंसा नहीं करता फिर यह अप्राप्तका निषेध क्यों किया जाता है कि वह अपनी हिंसा नहीं करता जैसे कोई कहे कि पृथ्वीपर और अन्तरिक्षमें अग्नि नहीं जलानी चाहिये। उ0 -- यह दोष नहीं है क्योंकि अज्ञानियोंसे स्वयं अपना तिरस्कार करना बन सकता है। सभी अज्ञानी अत्यन्त प्रसिद्ध साक्षात् -- प्रत्यक्ष आत्माका तिरस्कार करके अनात्मा शरीरादिको आत्मा मानकर? फिर धर्म और अधर्मका आचरण कर? उस प्राप्त किये हुए ( शरीररूप ) आत्माका नाश करके दूसरे नये ( शरीररूप ) आत्माको प्राप्त करते हैं। फिर उसका भी इसी प्रकार नाश करके अन्यको और उसका भी वैसे ही नाश करके ( पुनः ) अन्यको पाते रहते हैं। इस प्रकार बारंबार शरीररूप आत्माको प्राप्त करके उसकी हिंसा करते जाते हैं? अतः सभी अज्ञानी आत्महत्यारे हैं। जो वास्तवमें आत्मा है वह भी अविद्याद्वारा ( अज्ञात होनेके कारण ) सदा मारा हुआसा ही रहता है क्योंकि उनके लिये उसका विद्यमान फल भी नहीं होता। सुतरां अभी अविद्वान् आत्माकी हिंसा करनेवाले ही हैं। परंतु जो इनसे अन्य उपर्युक्त आत्मस्वरूपको जाननेवाला है? वह दोनों प्रकारसे ही अपनेद्वारा अपना नाश नहीं करता है। इसलिये वह परमगति प्राप्त कर लेता है अर्थात् उसे पहले बताया हुआ ( परम गतिरूप ) फल प्राप्त होता है।'),
('shankaracharya-ht:source:13.30','Śaṅkarācārya','gita.13.29','hi','translation','।।13.30।।यह जो कहा कि ईश्वरको सब भूतोंमें सम भावसे स्थित देखता हुआ पुरुष? आत्माद्वारा आत्माका नाश नहीं करता? यह युक्तिसङ्गत नहीं है क्योंकि अपने गुण और कर्मोंकी विलक्षणतासे विभिन्न हुए जीवोंमें इस प्रकार देखना नहीं बन सकता? ऐसी शंका करके कहते हैं --, मायाको प्रकृति समझना चाहिये इत्यादि मन्त्रोंके अनुसार भगवान्की त्रिगुणात्मिका मायाका नाम प्रकृति है? जो कि महत्तत्त्व आदि कार्यकरणके आकारमें परिणत है उस प्रकृतिद्वारा ही मन? वाणी और शरीरसे होनेवाले सारे कर्म? सब प्रकारसे सम्पादन किये जाते हैं अन्य किसीसे नहीं? इस प्रकार जो देखता है। तथा आत्माकोक्षेत्रज्ञको जो समस्त उपाधियोंसे रहित अकर्ता देखता है? वही देखता है अर्थात् वही परमार्थदर्शी है क्योंकि आकाशकी भाँति निर्गुण और विशेषतारहित अकर्ता आत्मामें? भेदभावका होना प्रमाणित नहीं हो सकता। यह अभिप्राय है।'),
('shankaracharya-ht:source:13.31','Śaṅkarācārya','gita.13.30','hi','translation','।।13.31।।फिर भी? उसी यथार्थ ज्ञानकी दूसरे शब्दोंसे व्याख्या करते हैं --, जिस समय ( यह विद्वान् ) भूतोंके अलगअलग भावोंको -- भूतोंकी पृथक्ताको? एक आत्मामें ही स्थित देखता है अर्थात् शास्त्र और आचार्यके उपदेशसे मनन करके आत्माको इस प्रकार प्रत्यक्षभावसे देखता है कि यह सब कुछ आत्मा ही है। तथा उस आत्मासे ही सारा विस्तार -- सबकी उत्पत्ति -- विकास देखता है अर्थात् जिस समय आत्मासे ही प्राण? आत्मासे ही आशा? आत्मासे ही संकल्प? आत्मासे ही आकाश? आत्मासे ही तेज? आत्मासे ही जल? आत्मासे ही अन्न? आत्मासे ही सबका प्रकट और लीन होना इत्यादि प्रकारसे सारा विस्तार आत्मासे ही हुआ देखने लगता है उस समय वह ब्रह्मको प्राप्त हो जाता है -- ब्रह्मरूप ही हो जाता है।'),
('shankaracharya-ht:source:13.32','Śaṅkarācārya','gita.13.31','hi','translation','।।13.32।।एक ही आत्मा सब शरीरोंका आत्मा माना जानेसे? उसका उन सबके दोषोंसे सम्बन्ध होगा? ऐसी शंका होनेपर यह कहा जाता है --, आदि कारणको कहते हैं? जिसका कोई कारण न हो? उसका नाम अनादि है और अनादिके भावका नाम अनादित्व है यह परमात्मा अनादि होनेके कारण अव्यय है क्योंकि जो वस्तु आदिमान् होती है? वही अपने,स्वरूपसे क्षीण होती है। किंतु यह परमात्मा अनादि है? इसलिये अवयवरहित है। अतः इसका क्षय नहीं होता। तथा निर्गुण होनेके कारण भी यह अव्यय है क्योंकि जो वस्तु गुणयुक्त होती है? उसका गुणोंके क्षयसे क्षय होता है। परंतु यह ( आत्मा ) गुणरहित है? अतः इसका क्षय नहीं होता। सुतरां यह परमात्मा अव्यय है? अर्थात् इसका व्यय नहीं होता। ऐसा होनेके कारण यह आत्मा शरीरमें स्थित हुआ भीशरीरमें रहता हुआ भी कुछ नहीं करता है? तथा कुछ न करनेके कारण ही उसके फलसे भी लिप्त नहीं होता है। आत्माकी शरीरमें प्रतीति होती है? इसलिये शरीरमें स्थित कहा जाता है। क्योंकि जो कर्ता होता है वही कर्मोंके फलसे लिप्त होता है। परंतु यह अकर्ता है? इसलिये फलसे लिप्त नहीं होता? यह अभिप्राय है। पू0 -- तो फिर शरीरोंमें ऐसा कौन है जो कर्म करता है और उसके फलसे लिप्त होता है यदि यह मान लिया जाय कि? परमात्मासे भिन्न कोई शरीरी कर्म करता है और उसके फलसे लिप्त होता है तब तो क्षेत्रज्ञ भी तू मुझे ही जान इस प्रकार जो क्षेत्रज्ञ और ईश्वरकी एकता कही है? वह अयुक्त ठहरेगी। यदि यह माना जाय कि ईश्वरसे पृथक् अन्य कोई शरीरी नहीं है तो यह बतलाना चाहिये फिर कौन करता और लिप्त होता है अथवा यह कह देना चाहिये कि ( इन सबसे ) पर कोई ईश्वर ही नहीं है। ( बात तो यह है कि ) भगवान्द्वारा कहा हुआ यह उपनिषद्रूप दर्शन सर्वथा दुर्विज्ञेय और दुर्वाच्य है? इसीलिये वैशेषिक? सांख्य? जैन और बौद्धमतावलम्बियोंद्वारा यह छोड़ दिया गया है। उ0 -- इसका उत्तर स्वभाव ही बर्तता है ऐसा कहकर भगवान्ने स्वयं ही दे दिया है क्योंकि अविद्यामात्र स्वभाववाला ही करता है? और लिप्त होता है? इसीसे यह व्यवहार चल रहा है। वास्तवमें अद्वितीय परमात्मामें वे ( कर्तापन और लिप्त होना आदि ) नहीं हैं। सुतरां इस वास्तविक ज्ञानदर्शनमें स्थित हुए ज्ञाननिष्ठ? परमहंस परिव्राजक संन्यासियोंका जिन्होंने अविद्याकृत समस्त व्यवहारका तिरस्कार कर दिया है? कर्मोंमें अधिकार नहीं है -- यह बात जगहजगह भगवान्द्वारा दिखलायी गयी है।'),
('shankaracharya-ht:source:13.33','Śaṅkarācārya','gita.13.32','hi','translation','।।13.33।।परमात्मा किसीकी भाँति न करता है और न लिप्त होता है इसपर यहाँ दृष्टान्त कहते हैं --, जैसे आकाश? सर्वत्र व्याप्त हुआ भी सूक्ष्म होनेके कारण लिप्त नहीं होता -- सम्बन्धयुक्त नहीं होता? वैसे ही आत्मा भी शरीरमें सर्वत्र स्थित रहता हुआ भी ( उसके गुणदोषोंसे ) लिप्त नहीं होता।'),
('shankaracharya-ht:source:13.34','Śaṅkarācārya','gita.13.33','hi','translation','।।13.34।।तथा --, जैसे एक ही सूर्य इस समस्त लोकको प्रकाशित करता है? वैसे ही? महाभूतोंसे लेकर धृतिपर्यन्त बतलाये हुए समस्त क्षेत्रको वह एक होते हुए भी प्रकाशित करता है। कौन करता है क्षेत्रज्ञ -- परमात्मा। यहाँ आत्मामें सूर्यका दृष्टान्त दोनों प्रकारसे ही घटता है? आत्मा सूर्यकी भाँति समस्त शरीरोंमें एक है और अलिप्त भी है।'),
('shankaracharya-ht:source:13.35','Śaṅkarācārya','gita.13.34','hi','translation','।।13.35।।सारे अध्यायके अर्थका उपसंहार करनेके लिये यह श्लोक ( कहा जाता है ) --, जो पुरुष शास्त्र और आचार्यके उपदेशसे उत्पन्न आत्मसाक्षात्काररूप ज्ञाननेत्रोंद्वारा? पहले बतलाये हुए क्षेत्र और क्षेत्रज्ञके अन्तरको? -- उनकी पारस्परकि विलक्षणताको? इस पूर्वदर्शित प्रकारसे जान लेते हैं? और वैसे ही अव्यक्त नामक अविद्यारूप भूतोंकी प्रकृतिके मोक्षको? यानी उसका अभाव कर देनेको भी जानते हैं? वे परमार्थतत्त्वस्वरूप ब्रह्मको प्राप्त हो जाते हैं? पुनर्जन्म नहीं पाते।'),
('shankaracharya-ht:source:14.1','Śaṅkarācārya','gita.14.1','hi','translation','।।14.1।।तथा जो यह कहा कि प्रकृतिमें स्थित होना और गुणविषयक आसक्ति -- यही संसारका कारण है? सो किस गुणमें किस प्रकारसे आसक्ति होती है गुण कौनसे हैं वे कैसे बाँधते हैं गुणोंसे छुटकारा कैसे होता है तथा मुक्तका लक्षण क्या है यह सब बातें बतलानेके लिये भी इस अध्यायका आरम्भ किया जाता है --,श्रीभगवान् बोले -- परम् इस पदका दूरस्थ ज्ञानम् पदके साथ सम्बन्ध है। समस्त ज्ञानोंमें उत्तम परम ज्ञानको अर्थात् जो पर वस्तुविषयक होनेसे परम है और उत्तम फलयुक्त होनेके कारण समस्त ज्ञानोंमें उत्तम है? उस परम उत्तम ज्ञानको? यद्यपि पहलेके सब अध्यायोंमें बारबार कह आया हूँ? तो भी फिर भली प्रकार कहूँगा। यहाँ ज्ञानोंमेंसे इस शब्दसे अमानित्वादि ज्ञानसाधनोंका ग्रहण नहीं है। किंतु यज्ञादि ज्ञेयवस्तुविषयक ज्ञानोंका ग्रहण है। वे यज्ञादिविषयक ज्ञान मोक्षके लिये उपयुक्त नहीं हैं और यह ( जो इस अध्यायमें बतलाया जाता है वह ) मोक्षके लिये उपयुक्त है? इसलिये परम और उत्तम इन दोनों शब्दोंसे श्रोताकी बुद्धिमें रुचि उत्पन्न करनेके लिये इसकी स्तुति करते हैं। जिस ज्ञानको जानकर -- पाकर सब मननशील संन्यासीजन इस देहबन्धनसे मुक्त होनेके बाद मोक्षरूप परम सिद्धिको प्राप्त हुए हैं? ( ऐसा परम ज्ञान कहूँगा )।'),
('shankaracharya-ht:source:14.2','Śaṅkarācārya','gita.14.2','hi','translation','।।14.2।।इस ( ज्ञानद्वारा प्राप्त हुई ) सिद्धिकी अव्यभिचारिता -- नित्यता दिखलाते हैं --, इस उपर्युक्त ज्ञानका भलीभाँति आश्रय लेकर? अर्थात् ज्ञानके साधनोंका अनुष्ठान करके? मुझ परमेश्वरकी समानताको -- मेरे साथ एकरूपताको प्राप्त हुए पुरुष सृष्टिके उत्पत्तिकालमें भी? फिर उत्पन्न नहीं होते और प्रलयकालमें -- ब्रह्माके विनाशकालमें भी व्यथाको प्राप्त नहीं होते? अर्थात् गिरते नहीं। यह फलका वर्णन ज्ञानकी स्तुतिके लिये किया गया है। यहाँ साधर्म्य का अर्थ समानधर्मता नहीं है क्योंकि गीताशास्त्रमें क्षेत्रज्ञ और ईश्वरका भेद स्वीकार नहीं किया गया।'),
('shankaracharya-ht:source:14.3','Śaṅkarācārya','gita.14.3','hi','translation','।।14.3।।अब यह बतलाते हैं कि इस प्रकारका क्षेत्र और क्षेत्रज्ञका संयोग भूतोंका कारण है --, मुझ ईश्वरकी माया -- त्रिगुणमयी प्रकृति? समस्त भूतोंकी योनि अर्थात् कारण है। समस्त कार्योंसे यानी उत्पत्तिशील वस्तुओंसे बड़ी होनेके कारण और अपने विकारोंको धारण करनेवाली होनेसे प्रकृति ही महत् ब्रह्म इस विशेषणसे विशेषित की गयी है। उस महत् ब्रह्मरूप योनिमें? मैं -- क्षेत्र और क्षेत्रज्ञ इन दो प्रकृतिरूप शक्तियोंवाला ईश्वर? हिरण्यगर्भके जन्मके बीजरूप गर्भको? यानी सब भूतोंकी उत्पत्तिके कारणरूप बीजको? स्थापित किया करता हूँ। अर्थात् अविद्या? कामना? कर्म और उपाधिके स्वरूपका अनुवर्तन करनेवाले क्षेत्रको क्षेत्रज्ञसे संयुक्त किया करता हूं। हे भारत उस गर्भाधानसे हिरण्यगर्भकी उत्पत्तिद्वारा समस्त भूतोंकी उत्पत्ति होती है।'),
('shankaracharya-ht:source:14.4','Śaṅkarācārya','gita.14.4','hi','translation','।।14.4।।हे कुन्तीपुत्र देव? पितृ? मनुष्य? पशु और मृग आदि समस्त योनियोंमें जो मूर्तियाँ? अर्थात् शरीराकार अलगअलग अङ्गोंके अवयवोंकी रचनायुक्त व्यक्तियाँ उत्पन्न होती हैं? उन सब मूर्तियोंकी सब प्रकारसे स्थित महत् ब्रह्मरूप मेरी माया तो गर्भ धारण करनेवाली योनि है? और मैं ईश्वर बीज प्रदान करनेवाला अर्थात् गर्भाधान करनेवाला पिता हूँ।'),
('shankaracharya-ht:source:14.5','Śaṅkarācārya','gita.14.5','hi','translation','।।14.5।।वे गुण कौनकौनसे हैं और कैसे बाँधते हैं सो कहते हैं --, सत्त्व? रज और तम -- ऐसे नामोंवाले ये तीन गुण हैं। गुण शब्द पारिभाषिक है। यहाँ रूप? रस आदिकी भाँति किसी द्रव्यके आश्रित गुणोंका ग्रहण नहीं है? तथा गुण और गुणवान् ( प्रकृति ) का भेद भी यहाँ विवक्षित नहीं है। जैसे रूपादि गुण द्रव्यके अधीन होते हैं वैसे ही ये सत्त्वादि गुण सदा क्षेत्रज्ञके अधीन हुए ही अविद्यात्मक होनेके कारण मानो क्षेत्रज्ञको बाँध लेते हैं। उस ( क्षेत्रज्ञ ) को आश्रय बनाकर ही ( ये गुण ) अपना स्वरूप प्रकट करनेमें समर्थ होते हैं? अतः बाँधते हैं ऐसा कहा जाता है। जिसकी भुजाएँ अतिशय सामर्थ्ययुक्त और जानु ( घुटनों ) तक लंबी हों? उसका नाम महाबाहु है। हे महाबाहो भगवान्की मायासे उत्पन्न ये तीनों गुण इस शरीरमें शरीरधारी अविनाशी क्षेत्रज्ञको मानो बाँध लेते हैं। क्षेत्रज्ञका अविनाशित्व अनादित्वात् इत्यादि श्लोकमें कहा ही है। पू0 -- पहले यह कहा है कि देही -- आत्मा लिप्त नहीं होता? फिर यहाँ यह विपरीत बात कैसे कही जाती है कि उसको गुण बाँधते हैं। उ0 -- इव शब्दका अध्याहार करके हमने इस शङ्काका परिहार कर दिया है। अर्थात् वास्तवमें नहीं बाँधते? बाँधते हुएसे प्रतीत होते हैं।'),
('shankaracharya-ht:source:14.6','Śaṅkarācārya','gita.14.6','hi','translation','।।14.6।।उन सत्त्व आदि तीन गुणोंमेंसे पहले? सत्त्वगुणका लक्षण बतलाया जाता है -- सत्त्वगुण स्फटिकमणिकी भाँति निर्मल होनेके कारण? प्रकाशशील और उपद्रवरहित है ( तो भी ) वह बाँधता है। कैसे बाँधता है सुखकी आसक्तिसे। (वास्तवमें ) विषयरूप सुखका विषयी आत्माके साथ मैं सुखी हूँ इस प्रकार सम्बन्ध जो़ड़ देना यह आत्माको मिथ्या ही सुखमें नियुक्त कर देना है। यही अविद्या है। क्योंकि विषयके धर्म विषयीके ( कभी ) नहीं होते और इच्छासे लेकर धृतिपर्यन्त सब धर्म विषयरूप क्षेत्रके ही हैं -- ऐसा भगवान्ने कहा है। सुतरां यह सिद्ध हुआ कि जो आरोपितभावसे आत्माकी स्वकीय धर्मरूपा हो रही है और विषयविषयीका अज्ञान ही जिसका स्वरूप है? ऐसी अविद्याद्वारा ही सत्त्वगुण अनात्मस्वरूप सुखमें ( आत्माको ) मानो,नियुक्त -- आसक्त कर देता है? यानी जो ( वास्तवमें ) सुखके सम्बन्धसे रहित है? उसे सुखीसा कर देता है। इसी प्रकार ( यह सत्त्वगुण उसे ) ज्ञानके सङ्गसे भी ( बाँधता है )। ज्ञान भी सुखका साथी होनेके कारण? क्षेत्र अर्थात् अन्तःकरणका ही धर्म है? आत्माका नहीं -- क्योंकि आत्माका धर्म मान लेनेपर उसमें आसक्त होना और उसका बाँधना नहीं बन सकता। इसलिये हे निष्पाप अर्थात् व्यसनदोष -- रहित अर्जुन सुखकी भाँति ही ज्ञान आदिके सङ्ग को भी ( बन्धन करनेवाला ) समझना चाहिये।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:14.7','Śaṅkarācārya','gita.14.7','hi','translation','।।14.7।।अप्राप्त वस्तुकी अभिलाषाका नाम तृष्णा है और प्राप्त विषयोंमें मनकी प्रीतिरूप स्नेहका नाम आसक्ति है? इन तृष्णा और आसक्तिकी उत्पत्तिके कारणरूप रजोगुणको रागात्मक जान। अर्थात् गेरू आदि रंगोंकी भाँति ( पुरुषको विषयोंके साथ ) उनमें आसक्त करके तद्रूप करनेवाला होनेसे? इसको तू रागरूप समझ। हे कुन्तीपुत्र वह रजोगुण? इस शरीरधारी क्षेत्रज्ञको कर्मासक्तिसे बाँधता है। दृष्ट और अदृष्ट फल देनेवाले जो कर्म हैं उनमें आसक्ति -- तत्परताका नाम कर्मासक्ति है? उसके द्वारा बाँधता है।'),
('shankaracharya-ht:source:14.8','Śaṅkarācārya','gita.14.8','hi','translation','।।14.8।।और समस्त देहधारियोंको मोहित करनेवाले तमोगुणको? यानी जीवोंके अन्तःकरणमें मोह -- अविवेक उत्पन्न करनेवाले तम नामक तीसरे गुणको? तू अज्ञानसे उत्पन्न हुआ जान। हे भारत वह तमोगुण? ( जीवोंको ) प्रमाद? आलस्य और निद्राके द्वारा बाँधा करता है।'),
('shankaracharya-ht:source:14.9','Śaṅkarācārya','gita.14.9','hi','translation','।।14.9।।फिर भी उन गुणोंका व्यापार संक्षेपसे बतलाया जाता है --, हे भारत सत्त्वगुण सुखमें नियुक्त करता है और रजोगुण कर्मोंमें नियुक्त किया करता है तथा तमोगुण? सत्त्वगुणसे उत्पन्न हुए विवेकज्ञानको? अपने आवरणात्मक स्वभावसे आच्छादित करके फिर प्रमादमें नियुक्त किया करता है। प्राप्त कर्तव्यको न करनेका नाम प्रमाद है।'),
('shankaracharya-ht:source:14.10','Śaṅkarācārya','gita.14.10','hi','translation','।।14.10।।ये तीनों गुण उपर्युक्त कार्य कब करते हैं सो कहते हैं --, हे भारत रजोगुण और तमोगुण -- इन दोनोंको दबाकर जब सत्त्वगुण उन्नत होता है -- बढ़ता है? तब वह अपने स्वरूपको प्राप्त हुआ सत्त्वगुण अपने कार्यज्ञान और सुखादिका आरम्भ किया करता है। तथा सत्त्वगुण और तमोगुण -- इन दोनोंको ही दबाकर जब रजोगुण बढ़ता है तब वह कर्मोंमें तृष्णा आदि अपने कार्यका आरम्भ किया करता है। वैसे ही सत्त्वगुण और रजोगुण इन दोनोंको दबाकर जब तम नामक गुण बढ़ता है तब वह ज्ञानको आच्छादित करना आदि अपना कार्य आरम्भ किया करता है।,'),
('shankaracharya-ht:source:14.11','Śaṅkarācārya','gita.14.11','hi','translation','।।14.11।।जिस समय जो गुण बढ़ा हुआ रहता है? उस समय उसके क्या चिह्न होते हैं? सो बतलाते हैं --, जब इस शरीरके समस्त द्वारोंमें यानी आत्माकी उपलब्धिके द्वारभूत जो श्रोत्रादि सब इन्द्रियाँ हैं उनमें? प्रकाश उत्पन्न हो -- अन्तःकरण यानी बुद्धिकी वृत्तिका नाम प्रकाश है और यही ज्ञान है। यह ज्ञान नामक प्रकाश जब शरीरके समस्त द्वारोंमें उत्पन्न हो -- तब इस ज्ञानके प्रकाशरूप चिह्नसे ही समझना चाहिये कि सत्त्वगुण बढ़ा है।'),
('shankaracharya-ht:source:14.12','Śaṅkarācārya','gita.14.12','hi','translation','।।14.12।।उत्पन्न हुए रजोगुणके चिह्न ये होते हैं --, हे भरतवंशियोंमें श्रेष्ठ लोभ -- परद्रव्यको प्राप्त करनेकी इच्छा? प्रवृत्ति -- सामान्यभावसे सांसारिक चेष्टा और कर्मोंका आरम्भ तथा अशान्ति -- उपरामताका अभाव? हर्ष और रागादिका प्रवृत्त होना तथा लालसा अर्थात् सामान्यभावसे समस्त वस्तुओंमें तृष्णा -- ये सब चिह्न रजोगुणके बढ़नेपर उत्पन्न होते हैं।'),
('shankaracharya-ht:source:14.13','Śaṅkarācārya','gita.14.13','hi','translation','।।14.13।।हे कुरुनन्दन अप्रकाश अर्थात् अत्यन्त अविवेक? प्रवृत्तिका अभाव? उसका कार्य प्रमाद और मोह अर्थात् अविवेकरूप मूढ़ता -- ये सब चिह्न तमोगुणकी वृद्धि होनेपर उत्पन्न होते हैं।'),
('shankaracharya-ht:source:14.14','Śaṅkarācārya','gita.14.14','hi','translation','।।14.14।।मरणसमयकी अवस्थाके द्वारा जो फल मिलता है? वह सब भी आसक्ति और रागसे ही होनेवाला तथा गुणजन्य ही होता है? यह दिखानेके लिये कहते हैं --, जब यह शरीरधारी जीव? सत्त्वगुणकी वृद्धिमें मृत्युको प्राप्त होता है? तब उत्तम तत्त्वको जाननेवालोंके अर्थात् महत्तत्त्वादिको जाननेवालोंके निर्मल -- मलरहित लोकोंको प्राप्त होता है।'),
('shankaracharya-ht:source:14.15','Śaṅkarācārya','gita.14.15','hi','translation','।।14.15।।रजोगुणकी वृद्धिके समय मरनेपर कर्मसंगियोंमें अर्थात् कर्मोंमें आसक्त हुए मनुष्योंमें उत्पन्न होता है और वैसे ही तमोगुणके बढ़नेपर मरा हुआ मनुष्य मूढ़योनिमें अर्थात् पशु आदि योनियोंमें उत्पन्न होता है।'),
('shankaracharya-ht:source:14.16','Śaṅkarācārya','gita.14.16','hi','translation','।।14.16।।पहले कहे हुए श्लोकोंके अर्थका ही सार कहा जाता है --, श्रेष्ठ पुरुषोंने शुभ कर्मका? अर्थात् सात्त्विक कर्मका फल सात्त्विक और निर्मल ही बतलाया है? तथा राजस कर्मका फल दुःख बतलाया है? अर्थात् कर्माधिकारसे राजस कर्मका फल भी अपने कारणके अनुसार दुःखरूप राजस ही होता है ( ऐसा कहा है ) और वैसे ही? तामसरूप अधर्मका -- पापकर्मका फल अज्ञान बतलाया है।'),
('shankaracharya-ht:source:14.17','Śaṅkarācārya','gita.14.17','hi','translation','।।14.17।।गुणोंसे क्या उत्पन्न होता है ( सो कहते हैं -- ) उत्कर्षको प्राप्त हुए सत्त्वगुणसे ज्ञान उत्पन्न होता है और रजोगुणसे लोभ होता है तथा तमोगुणसे प्रमाद और मोह -- ये दोनों होते हैं और अज्ञान भी होता है।'),
('shankaracharya-ht:source:14.18','Śaṅkarācārya','gita.14.18','hi','translation','।।14.18।।तथा --, सत्त्वगुणमें यानी सात्त्विक भावोंमें स्थित पुरुष उच्च स्थानको जाते हैं अर्थात् देवलोक आदि उच्च लोकोंमें उत्पन्न होते हैं। और राजस पुरुष बीचमें रहते हैं अर्थात् मनुष्ययोनियोंमें उत्पन्न होते हैं। तथा जघन्य गुणके आचरणोंमें स्थित हुए अर्थात् जो जघन्य -- निन्दनीय गुण है? उस तमोगुणके कार्य -- निद्रा और आलस्य आदिमें स्थित हुए मूढ़ -- तामसी पुरुष नीचे गिरते हैं -- वे पशु? पक्षी आदि योनियोंमें उत्पन्न होते हैं।'),
('shankaracharya-ht:source:14.19','Śaṅkarācārya','gita.14.19','hi','translation','।।14.19।।प्रकृतिमें स्थित होनारूप मिथ्याज्ञानसे युक्त पुरुषका सुखदुःखमोहात्मक भोगरूप गुणोंमें मैं सुखी? दुखी अथवा मूढ हूँ इस प्रकारका जो सङ्ग है? वह सङ्ग ही इस पुरुषकी अच्छीबुरी योनियोंमें जन्मप्राप्तिरूप संसारका कारण है। यह बात जो पहले तेरहवें अध्यायमें संक्षेपसे कही थी? उसीको यहाँ सत्त्वं रजस्तम इति गुणाः प्रकृतिसंभवाः इस श्लोकसे लेकर ( उपर्युक्त श्लोकतक ) गुणोंका स्वरूप? गुणोंका कार्य? अपने कार्यद्वारा गुणोंका बन्धकत्व तथा गुणोंके कार्यद्वारा बँधे हुए पुरुषकी जो गति होती है? इन सब मिथ्याज्ञानरूप अज्ञानमूलक बन्धनके कारणोंको? विस्तारपूर्वक बतलाकर? अब यथार्थ ज्ञानसे मोक्ष ( कैसे होता है सो ) बतलाना चाहिये? इसलिये भगवान् बोले --, जिस समय द्रष्टा पुरुष ज्ञानी होकर? कार्य? करण और विषयोंके आकारमें परिणत हुए गुणोंसे अतिरिक्त अन्य किसीको ( भी ) कर्ता नहीं देखता है? अर्थात् यही देखता है कि समस्त अवस्थाओंमें स्थित हुए गुण ही,समस्त कर्मोंके कर्ता हैं तथा गुणोंके व्यापारके साक्षीरूप आत्माको गुणोंसे पर जानता है? तब वह द्रष्टा मेरे भावको प्राप्त होता है।'),
('shankaracharya-ht:source:14.20','Śaṅkarācārya','gita.14.20','hi','translation','।।14.20।।कैसे प्राप्त होता है सो बतलाते हैं --, देहोत्पत्तिके बीजभूत? इन मायोपाधिक पूर्वोक्त तीनों गुणोंका उल्लंघन कर? अर्थात् जीवितावस्थामें ही इनका अतिक्रम करके? यह देहधारी विद्वान् जीता हुआ ही जन्म मृत्यु? बुढ़ापे और दुःखोंसे मुक्त होकर अमृतका अनुभव करता है। अभिप्राय यह कि इस प्रकार वह मेरे भावको प्राप्त हो जाता है।'),
('shankaracharya-ht:source:14.21','Śaṅkarācārya','gita.14.21','hi','translation','।।14.21।।( शरीरधारी जीव ) जीता हुआ ही गुणोंको अतिक्रम करके अमृतका अनुभव करता है इस प्रश्नबीजको पाकर अर्जुन बोला --, हे प्रभो इन पूर्ववर्णित तीनों गुणोंसे अतीत -- पार हुआ पुरुष किनकिन लक्षणोंसे युक्त होता है और वह कैसे आचरणवाला होता है अर्थात् उसके आचरण कैसे होते हैं तथा किस प्रकारसे ( किस उपायसे ) मनुष्य इन तीनों गुणोंसे अतीत हो सकता है।'),
('shankaracharya-ht:source:14.22','Śaṅkarācārya','gita.14.22','hi','translation','।।14.22।।इस ( उपर्युक्त ) श्लोकमें अर्जुनने गुणातीतके लक्षण और गुणातीत होनेका उपाय पूछा है? उन दोनों प्रश्नोंका उत्तर देनेके लिये श्रीभगवान् बोले कि पहले गुणातीत पुरुष किनकिन लक्षणोंसे युक्त होता है उसे सुन --, सत्त्वगुणका कार्य प्रकाश? रजोगुणका कार्य प्रवृत्ति और तमोगुणका कार्य मोह? ये जब प्राप्त होते हैं अर्थात् भली प्रकार विषयभावसे उपलब्ध होते है? तब वह इनसे द्वेष नहीं किया करता। अभिप्राय यह कि मुझमें तामसभाव उत्पन्न हो गया? उससे मैं मोहित हो गया और दुःखरूप राजसी प्रवृत्ति मुझमें उत्पन्न हुई? उस राजसभावने मुझे प्रवृत्त कर दिया? इसने मुझे स्वरूपसे विचलित कर दिया? यह जो अपनी स्वरूपस्थितिसे विचलित होना है? वह मेरे लिये बड़ा भारी दुःख है तथा प्रकाशमय सात्त्विक गुण? मुझे विवेकित्व प्रदान करके और सुखमें नियुक्त करके बाँधता है? इस प्रकार साधारण मनुष्य अयथार्थदर्शी होनेके कारण उन गुणोंसे द्वेष किया करते हैं? परंतु गुणातीत पुरुष उनकी प्राप्ति होनेपर उनसे द्वेष नहीं करता। तथा जैसे सात्त्विक? राजस और तामस पुरुष? जब सात्त्विक आदि भाव अपना स्वरूप प्रत्यक्ष कराकर निवृत्त हो जाते हैं? तब ( पुनः ) उनको चाहते हैं। वैसे गुणातीत उन निवृत्त हुए गुणोंके कार्योंको नहीं चाहता यह अभिप्राय है। ( परंतु ये 2()৷৷) 2सब लक्षण दूसरोंको प्रत्यक्ष होनेवाले नहीं हैं। तो कैसे हैं अपने आपको ही प्रत्यक्ष होनेके कारण ये स्वसंवेद्य ही हैं क्योंकि अपने आपमें होनेवाले द्वेष या आकाङ्क्षाको दूसरा नहीं देख सकता।'),
('shankaracharya-ht:source:14.23','Śaṅkarācārya','gita.14.23','hi','translation','।।14.23।।अब? गुणातीत पुरुष किस प्रकारके आचरणवाला होता है? इस प्रश्नका उत्तर देते हैं --, उदासीनकी भाँति स्थित हुआ? अर्थात् जैसे उदासीन पुरुष किसीका पक्ष नहीं लेता? उसी भावसे गुणातीत होनेके उपायरूप मार्गमें स्थित हुआ जो आत्मज्ञानी -- संन्यासी? गुणोंद्वारा विवेकज्ञानकी स्थितिसे विचलित नहीं किया जा सकता। इसीको स्पष्ट करते हैं कि कार्यकरण और विषयोंके आकारमें परिणत हुए गुण ही एकमें एक बर्त रहे हैं -- जो ऐसा समझकर स्थित रहता है? चलायमान नहीं होता अर्थात् अविचलभावसे स्वरूपमें ही स्थित रहता है। यहाँ छन्दोभङ्ग होनेके भयसे आत्मनेपद ( अवतिष्ठते ) के स्थानमें परस्मैपद ( अवतिष्ठति ) का प्रयोग किया गया है अथवा योऽवतिष्ठति के स्थानमें योऽनुतिष्ठति ऐसा पाठान्तर समझना चाहिये।'),
('shankaracharya-ht:source:14.24','Śaṅkarācārya','gita.14.24','hi','translation','।।14.24।।तथा --, जो सुखदुःखमें समान है अर्थात् सुख और दुःख जिसको समान प्रतीत होते हैं? जो स्वस्थ अर्थात् अपने आत्मस्वरूपमें स्थित -- प्रसन्न है? जो समलोष्टाश्मकाञ्चन है अर्थात् मिट्टी? पत्थर और सुवर्ण जिसके ( विचारमें ) समान हो गये हैं? जो तुल्यप्रियाप्रिय है अर्थात् प्रिय और अप्रिय दोनोंहीको जो समान समझता है और जो धीर अर्थात् बुद्धिमान् है तथा जो तुल्यनिन्दात्मसंस्तुति है अर्थात् जिसके विचारमें अपनी निन्दा और स्तुति समान हो गयी है? ऐसा अपनी निन्दास्तुतिको समान समझनेवाला यति है।'),
('shankaracharya-ht:source:14.25','Śaṅkarācārya','gita.14.25','hi','translation','।।14.25।।तथा --, जो मान और अपमानमें समान अर्थात् निर्विकार रहता है तथा मित्र और शत्रुपक्षके लिये तुल्य है। यद्यपि कोईकोई पुरुष अपने विचारसे तो उदासीन होते हैं? परंतु दूसरोंकी समझसे वे मित्र या शत्रुपक्षवालेसे ही होते हैं इसलिये कहते हैं कि जो मित्र और शत्रुपक्षके लिये तुल्य है। तथा जो सारे आरम्भोंका त्याग करनेवाला है। दृष्ट और अदृष्ट फलके लिये जानेवाले कर्मोंका नाम आरम्भ है? ऐसे समस्त आरम्भोंका त्याग करनेका जिसका स्वभाव है वह सर्वारम्भपरित्यागी है अर्थात् जो केवल शरीरधारणके लिये आवश्यक कर्मोंके सिवा सारे कर्मोंका त्याग कर देनेवाला है? वह पुरुष गुणातीत कहलाता है। उदासीनवत् यहाँसे लेकर गुणातीतः स उच्यते यहाँतक जो भाव बतलाये गये हैं? वे सब जबतक प्रयत्नसे सम्पादन करनेयोग्य रहते हैं? तबतक तो मुमुक्षु -- संन्यासीके लिये अनुष्ठान करनेयोग्य गुणातीतत्वप्राप्तिके साधन हैं और जब वे स्थिर हो जाते हैं? तो गुणातीत संन्यासीके स्वसंवेद्य लक्षण बन जाते हैं।'),
('shankaracharya-ht:source:14.26','Śaṅkarācārya','gita.14.26','hi','translation','।।14.26।।मनुष्य इन तीनों गुणोंसे किस प्रकार अतीत होता है इस प्रश्नका उत्तर अब देते हैं --, जो संन्यासी या कर्मयोगी सब भूतोंके हृदयमें स्थित मुझ परमेश्वर नारायणको? कभी व्यभिचरित ( विचलित ) न होनेवाले अव्यभिचारी भक्तियोगद्वारा सेवन करता है -- भजनका नाम भक्ति है? वही योग है? उस भक्तियोगके द्वारा जो मेरी सेवा करता है -- वह इन ऊपर कहे हुए गुणोंको अतिक्रमण करके ब्रह्मलोकको पानेके लिये? अर्थात् मोक्ष प्राप्त करनेके लिये योग्य समझा जाता है? अर्थात् ( मोक्ष प्राप्त करनेमें ) समर्थ होता है।'),
('shankaracharya-ht:source:14.27','Śaṅkarācārya','gita.14.27','hi','translation','।।14.27।।ऐसा क्यों होता है सो बतलाते हैं --, क्योंकि ब्रह्म -- परमात्माकी प्रतिष्ठा मैं हूँ। जिसमें प्रतिष्ठित हो वह प्रतिष्ठा है? इस व्युत्पत्तिके अनुसार मैं अन्तरात्मा ( ब्रह्मकी ) प्रतिष्ठा हूँ। कैसे ब्रह्मकी ( सो कहते हैं -- ) जो अमृत -- अविनाशी? अव्यय -- निर्विकार? शाश्वत -- नित्य? धर्मस्वरूप -- ज्ञानयोगरूप धर्मद्वारा प्राप्तव्य और ऐकान्तिक सुखस्वरूप अर्थात् व्यभिचाररहित आनन्दमय है उस ब्रह्मकी मैं प्रतिष्ठा हूँ। अमृत आदि स्वभाववाले परमात्माकी प्रतिष्ठा अन्तरात्मा ही है क्योंकि यथार्थ ज्ञानसे वही परमात्मारूपसे निश्चित होता है। यही बात ब्रह्मभूयाय कल्पते इस पदसे कही गयी है। अभिप्राय यह है कि जिस ईश्वरीय शक्तिसे भक्तोंपर अनुग्रह आदि करनेके लिये ब्रह्म प्रवर्तित होता है? वह शक्ति? मैं ब्रह्म ही हूँ क्योंकि शक्ति और शक्तिमान्में भेद नहीं होता। अथवा ( ऐसा समझना चाहिये कि ) ब्रह्मशब्दका वाच्य होनेके कारण यहाँ सगुण ब्रह्मका ग्रहण है? उस सगुण ब्रह्मका मैं निर्विकल्प -- निर्गुण ब्रह्म ही प्रतिष्ठा -- आश्रय हूँ? दूसरा कोई नहीं। किन विशेषणोंसे युक्त सगुण ब्रह्मका जो अमृत अर्थात् मरणधर्मसे रहित है और अविनाशी अर्थात् क्षय होनेसे रहित है? उसका। तथा ज्ञाननिष्ठारूप शाश्वतनित्य धर्मका और उससे होनेवाले ऐकान्तिक एकमात्र निश्चित परम आनन्दका भी? मैं ही आश्रय हूँ। अहं प्रतिष्ठा यह पद यहाँ अनुवृत्तिसे लिया गया है।'),
('shankaracharya-ht:source:15.1','Śaṅkarācārya','gita.15.1','hi','translation','।।15.1।।यहाँ पहले वैराग्यके लिये वृक्षस्वरूपकी कल्पना करके? संसारके स्वरूपका वर्णन करते हैं क्योंकि संसारसे विरक्त हुए पुरुषको ही भगवान्का तत्त्व जाननेमें अधिकार है? अन्यको नहीं। अतः श्रीभगवान् बोले --, ( यह संसाररूप वृक्ष ) ऊर्ध्वमूलवाला है। कालकी अपेक्षा भी सूक्ष्म? सबका कारण? नित्य और महान् होनेके कारण अव्यक्तमायाशक्तियुक्त ब्रह्म सबसे ऊँचा कहा जाता है? वही इसका मूल है? इसलिये यह संसारवृक्ष ऊपरकी ओर मूलवाला है। ऊपर मूल और नीचे शाखावाला इस श्रुतिसे भी यही प्रमाणित होता है। पुराणमें भी कहा है -- अव्यक्तरूप मूलसे उत्पन्न हुआ उसीके अनुग्रहसे बढ़ा हुआ? बुद्धिरूप प्रधान शाखासे युक्त? बीचबीचमें इन्द्रियरूप कोटरोंवाला? महाभूतरूप शाखाप्रतिशाखाओंवाला? विषयरूप पत्तोंवाला? धर्म और अधर्मरूप सुन्दर पुष्पोंवाला तथा जिसमें सुख दुःखरूप फल लगे हुए हैं ऐसा यह सब भूतोंका आजीव्य सनातन ब्रह्मवृक्ष है। यही ब्रह्मवन है? इसीमें ब्रह्म सदा रहता है। ऐसे इसी ब्रह्मवृक्षका ज्ञानरूप श्रेष्ठ खड्गद्वारा छेदनभेदन करके और आत्मामें प्रीतिलाभ करके फिर वहाँसे नहीं लौटता इत्यादि। ऐसे ऊपर मूल और नीचे शाखावाले इस मायामय संसारवृक्षको? अर्थात् महत्तत्त्व? अहंकार? तन्मात्रादि? शाखाकी भाँति जिसके नीचे हैं? ऐसे इस नीचेकी ओर शाखावाले और कलतक भी न रहनेवाले इस क्षणभङ्गुर अश्वत्थ वृक्षको अव्यय कहते हैं। यह मायामय संसार? अनादि कालसे चला आ रहा है? इसीसे यह संसारवृक्ष अव्यय माना जाता है तथा यह आदिअन्तसे रहित शरीर आदिकी परम्पराका आश्रय सुप्रसिद्ध है? अतः इसको अव्यय कहते हैं। उस संसारवृक्षका ही यह अन्य विशेषण ( कहा जाता ) है। ऋक् यजु और सामरूप वेद? जिस संसारवृक्षके पत्तोंकी भाँति रक्षा करनेवाले होनेसे पत्ते हैं। जैसे पत्ते वृक्षकी रक्षा करनेवाले होते हैं? वैसे ही वेद धर्मअधर्म? उनके कारण और फलको प्रकाशित करनेवाले होनेसे? संसाररूप वृक्षकी रक्षा करनेवाले हैं। ऐसा जो यह विस्तारपूर्वक बतलाया हुआ संसारवृक्ष है? इसको जो मूलके सहित जानता है? वह वेदको जाननेवाला अर्थात् वेदके अर्थको जाननेवाला है। क्योंकि इस मूलसहित संसारवृक्षसे अतिरिक्त अन्य जाननेयोग्य वस्तु अणुमात्र भी नहीं है। सुतरां जो इस प्रकार वेदार्थको जाननेवाला है वह सर्वज्ञ है। इस प्रकार मूलसहित संसारवृक्षके ज्ञानकी स्तुति करते हैं। उसी संसारवृक्षके अन्य अङ्गोंकी कल्पना कही जाती है।'),
('shankaracharya-ht:source:15.2','Śaṅkarācārya','gita.15.2','hi','translation','।।15.2।।अपने उपादानकारणरूप सत्त्व? रज और तमइन तीनों गुणोंसे बढ़ी हुई -- स्थूलभावको प्राप्त हुई और विषयरूपी कोंपलोंवाली? उस वृक्षकी बहुतसी शाखाएँ? जो कि अपनेअपने कर्म और ज्ञानके अनुरूप -- कर्म और ज्ञानकी फलस्वरूपा योनियाँ हैं? नीचेकी ओर मनुष्योंसे लेकर स्थावरपर्यन्त और ऊपरकी ओर धर्म यानी विश्वकर्ता ब्रह्मापर्यन्त? वृक्षकी शाखाओंके समान फैली हुई हैं। कर्मफलरूप देहादि शाखाओंसे शब्दादि विषय? कोंपलोंके समान अङ्कुरितसे होते हैं? इसलिये वे शरीरादिरूप शाखाएँ विषयरूपी कोंपलोंवाली हैं। संसारवृक्षका परम मूल -- उपादानकारण पहले बतलाया जा चुका है। अब कर्मफलजनित रागद्वेष आदिकी वासनाएँ जो मूलके समान धर्माधर्मविषयक प्रवृत्तिका कारण और अवान्तरसे ( आगेपीछे ) होनेवाली हैं ( उनको कहते हैं )। वे मनुष्यलोकमें कर्मानुबन्धिनी वासनारूप मूलें देवादिकी अपेक्षा नीचे भी? अविच्छिन्नरूपसे फैली हुई हैं। पुण्यपापरूप कर्म जिनका अनुबन्ध यानी पीछेपीछे होनेवाला है? अर्थात् जिनकी उत्पत्तिका अनुवर्तन करनेवाला है? वे कर्मानुबन्धी कहलाती हैं। यहाँ मनुष्योंका ही विशेषरूपसे कर्ममें अधिकार प्रसिद्ध है ( इसलिये वे मूलें मनुष्यलोकमें कर्मानुबन्धिनी बतलायी गयी हैं )।'),
('shankaracharya-ht:source:15.3','Śaṅkarācārya','gita.15.3','hi','translation','।।15.3।।यह जो वर्णन किया हुआ संसारवृक्ष है --, इसका स्वरूप जैसा यहाँ वर्णन किया गया है? वैसा उपलब्ध नहीं होता क्योंकि यह स्वप्नकी वस्तु? मृगतृष्णाके जल और मायारचित गन्धर्वनगरके समान होनेसे? देखतेदेखते नष्ट होनेवाला है। इसी कारण इसका अन्त अर्थात् अन्तिमावस्थाअवसान या समाप्ति भी नहीं है। तथा इसका आदि भी नहीं है? अर्थात् यहाँसे आरम्भ होकर यह संसार चला है? ऐसा किसीसे नहीं जाना जा सकता और इसकी संप्रतिष्ठास्थिति भी नहीं है यानी आदि और अन्तके बीचकी अवस्था भी किसीको उपलब्ध नहीं होती। इस उपर्युक्त सुविरूढमूल यानी जिसकी मूलें -- जड़ें अत्यन्त दृढ़ हो गयी हैं -- भली प्रकार संगठित हो चुकी हैं? ऐसे संसाररूप अश्वत्थको? असङ्गशस्त्रसे छेदन करके यानी पुत्रैषणा? वित्तैषणा और लोकैषणादिसे उपराम हो जाना ही असङ्ग है? ऐसे असङ्गशस्त्रसे जो कि परमात्माके सम्मुख होनारूप निश्चयसे दृढ़ किया हुआ है और बारंबार विवेकाभ्यासरूप पत्थरपर घिसकर पैना किया हुआ है? इस संसारवृक्षको बीजसहित उखाड़कर।'),
('shankaracharya-ht:source:15.4','Śaṅkarācārya','gita.15.4','hi','translation','।।15.4।।उसके पश्चात् उस परम वैष्णवपदको खोजना चाहिये अर्थात् जानना चाहिये कि जिस पदमें पहुँचे हुए पुरुष? फिर संसारमें नहीं लौटते -- पुनर्जन्म ग्रहण नहीं करते। ( उस पदको ) कैसे खोजना चाहिये सो कहते हैं -- जो पदशब्दसे कहा गया है? उसी आदिपुरुषकी मैं शरण हूँ? इस भावसे अर्थात् उसके शरणागत होकर खोजना चाहिये। वह पुरुष कौन है? सो बतलाते हैं -- जिस पुरुषसे बाजीगरकी मायाके समान इस मायारचित संसारवृक्षकी सनातन प्रवृत्ति विस्तारको प्राप्त हुई है -- प्रकट हुई है।'),
('shankaracharya-ht:source:15.5','Śaṅkarācārya','gita.15.5','hi','translation','।।15.5।।उस परमपदको कैसे पुरुष प्राप्त करते हैं सो कहते हैं --, जो मानमोहसे मुक्त हैं -- जिनका अभिमान और अज्ञान नष्ट हो गया है? ऐसे जो मानमोह से रहित हैं? जो,जितसङ्गदोष हैं -- जिन्होंने आसक्तिरूप दोषको जीत लिया है? जो नित्य अध्यात्मविचारमें लगे हुए हैं -- सदा परमात्माके स्वरूपकी आलोचना करनेमें तत्पर हैं? जो कामनासे रहित हैं -- जिनकी समस्त कामनाएँ निर्लेपभावसे ( मूलसहित ) निवृत्त हो गयी हैं? ऐसे यति -- संन्यासी जो कि सुखदुःख नामक प्रिय और अप्रिय आदि द्वन्द्वोंसे छूटे हुए हैं? वे मोहरहित ज्ञानी? उस उपर्युक्त अविनाशी पदको पाते हैं।'),
('shankaracharya-ht:source:15.6','Śaṅkarācārya','gita.15.6','hi','translation','।।15.6।।वही पद फिर अन्य विशेषणोंसे बतलाया जाता है --, तत् शब्दका आगेवाले -- व्यवधानयुक्त धाम शब्दके साथ सम्बन्ध है। उस तेजोमय धामको यानी परमपदको? सूर्य -- आदित्य सबको प्रकाशित करनेकी शक्तिवाला होनेपर भी प्रकाशित नहीं कर सकता। वैसे ही शशाङ्क -- चन्द्रमा और पावक -- अग्नि भी प्रकाशित नहीं कर सकता। जिस परमधामको यानी वैष्णवपदको पाकर मनुष्य पीछे नहीं लौटते और जिसको सूर्यादि ज्योतियाँ प्रकाशित नहीं कर सकतीं? वह मुझ विष्णुका परमधाम -- पद है। पू0 -- जहाँ जाकर फिर नहीं लौटते यह बात कही गयी। परंतु सभी गतियाँ? अन्तमें पुनरागमनयुक्त होती हैं और सभी संयोग अन्तमें वियोगवाले होते हैं? यह बात प्रसिद्ध है। फिर यह बात कैसे कही जाती है कि उस धामको प्राप्त हुए पुरुषोंका पुनरागमन नहीं होता'),
('shankaracharya-ht:source:15.7','Śaṅkarācārya','gita.15.7','hi','translation','।।15.7।।उ0 -- उसमें जो कारण है वह सुन --, जीवलोकमें अर्थात् संसारमें? जो जीवरूप शक्ति? भोक्ता? कर्ता इत्यादि नामोंसे प्रसिद्ध है? वह मुझ परमात्माका ही सनातन अंश है? अर्थात् अंग? भाग? एकदेश जो भी कुछ कहो? एक ही अभिप्राय है। जैसे जलमें प्रतीत होनेवाला सूर्यका अंश -- प्रतिबिम्ब? जलरूप निमित्तका नाश होनेपर? सूर्यको ही प्राप्त होकर फिर नहीं लौटता? वैसे ही उस परमात्माका यह अंश भी? उस परमात्मासे ही संयुक्त हो जाता है। फिर नहीं लौटता। अथवा जैसे घट आदि उपाधिसे परिच्छिन्न घटादिका आकाश? आकाशका ही अंश है और वह घट आदि निमित्तके नाश होनेपर? आकाशको ही प्राप्त होकर फिर नहीं लौटता? वैसे ही इसके विषयमें भी समझना चाहिये। सुतरां जहाँ जाकर नहीं लौटते यह कहना उचित ही है। पू0 -- अवयवरहित परमात्माका अवयव? एकदेश अथवा अंश? कैसे हो सकता है और यदि उसे अवयवयुक्त मानें? तो उन अवयवोंका विभाग होनेसे परमात्माके नाशका प्रसङ्ग आ जायगा। उ0 -- यह दोष नहीं है क्योंकि अविद्याकृत उपाधिसे परिच्छिन्न? एकदेश ही अंशकी भाँति माना गया है। यह बात क्षेत्राध्यायमें विस्तारपूर्वकर दिखलायी गयी है। वह मेरा अंशरूप माना हुआ जीव? संसारमें कैसे आता है और कैसे शरीर छोड़कर जाता है? सो बतलाते हैं -- ( यह जीवात्मा ) मन जिनमें छठा है? ऐसी कर्णछिद्रादि अपनेअपने गोलकरूप प्रकृतियोंमें स्थित हुई? श्रोत्रादि इन्द्रियोंको आकर्षित करता है।,'),
('shankaracharya-ht:source:15.8','Śaṅkarācārya','gita.15.8','hi','translation','।।15.8।।किस कालमें ( आकर्षित करता है ) जब यह देहादिसंघातका स्वामी जीवात्मा शरीरको छोड़कर जाता है तब ( इनको ) आकर्षित करता है।,पहले और इस श्लोकके अर्थकी संगतिके वशसे श्लोकके दूसरे पादकी व्याख्या पहले की गयी है। तथा जब यह जीवात्मा? पहले शरीरसे ( निकलकर ) दूसरे शरीरको पाता है? तब मनसहित इन छः इन्द्रियोंको साथ लेकर जाता है। कैसे लेकर जाता है सो बतलाते हैं -- जैसे वायु गन्धके स्थानोंसे यानी पुष्पादिसे गन्धको लेकर जाता है? वैसे ही।'),
('shankaracharya-ht:source:15.9','Śaṅkarācārya','gita.15.9','hi','translation','।।15.9।।वे ( मनसहित छः इन्द्रियाँ ) कौनसी हैं, यह शरीरमें स्थित ( जीवात्मा ) श्रोत्र? चक्षु? त्वचा? रसना और नासिका इनमेंसे प्रत्येक इन्द्रियको और उसके छठे मनको? आश्रय बनाकर? शब्दादि विषयोंका सेवन किया करता है।'),
('shankaracharya-ht:source:15.10','Śaṅkarācārya','gita.15.10','hi','translation','।।15.10।।इस प्रकार इस देहधारी ( जीवात्मा ) को शरीरसे --, उत्क्रमण करते हुएको अर्थात् पहले प्राप्त किये शरीरको छोड़कर जाते हुएको? अथवा शरीरमें स्थित रहते हुएको? या शब्दादि विषयोंका भोग करते हुएको? या सुखदुःखमोह आदि गुणोंसे युक्त हुएको भी? यानी इस प्रकार अत्यन्त दर्शनगोचर होते हुए भी इस आत्माको मूढ़ लोग? जो कि दृष्ट और अदृष्ट विषयभोगोंकी लालसाके बलसे चित्त आकृष्ट हो जानेके कारण अनेक प्रकारसे मोहित हो रहे हैं? नहीं देखते? अहो यह बड़े दुःखकी बात है? इस प्रकार भगवान् करुणा प्रकट करते हैं। परंतु जो प्रमाणजनित ज्ञाननेत्रोंसे युक्त हैं अर्थात् विवेकदृष्टिवाले हैं? वे इसे देखते हैं।'),
('shankaracharya-ht:source:15.11','Śaṅkarācārya','gita.15.11','hi','translation','।।15.11।।और कई एक --, प्रयत्न करनेवाले? समाहितचित्त योगीजन? इस आत्माको? जिसका कि प्रकरण चल रहा है? अपने अन्तःकरणमें स्थित देखते हैं अर्थात् यही मैं हूँ इस प्रकार आत्मस्वरूपका साक्षात् किया करते हैं। परंतु जिन्होंने तप और इन्द्रियजय आदि साधनोंद्वारा अपने अन्तःकरणका संस्कार नहीं किया है? जो बुरे आचरणोंसे उपराम नहीं हुए हैं? जो अशान्त और घमण्डी हैं? वे अविवेकी पुरुष? शास्त्रादिके प्रमाणोंसे प्रयत्न करते हुए भी? इस आत्माको नहीं देख पाते।'),
('shankaracharya-ht:source:15.12','Śaṅkarācārya','gita.15.12','hi','translation','।।15.12।।सबको प्रकाशित करनेवाली अग्नि? सूर्य आदि ज्योतियाँ भी जिस परमपदको प्रकाशित नहीं कर सकतीं? जिस परमपदको प्राप्त हुए मुमुक्षुजन फिर संसारकी ओर नहीं लौटते? जैसे घट आदिके आकाश महाकाशके अंश हैं? वैसे ही उपाधिजनित भेदसे विभिन्न हुए जीव? जिस परमपदके ( कल्पितभावसे ) अंश हैं? उस परमपदका? सर्वात्मत्व और समस्त व्यवहारका आधारत्व? बतलानेकी इच्छासे भगवान् चार श्लोकोंद्वारा संक्षेपसे विभूतियोंका वर्णन करते हैं --, जो तेजदीप्ति प्रकाश? सूर्यमें स्थित हुआ अर्थात् सूर्यके आश्रित हुआ समस्त जगत्को प्रकाशित करता है? जो प्रकाश करनेवाला तेज शशाङ्क -- चन्द्रमामें स्थित है और जो अग्निमें वर्तमान है? उस तेजको तू मुझ विष्णुकी अपनी ज्योति समझ। अथवा जो तेज यानी चैतन्यमय ज्योति? सूर्यमें स्थित है? तथा जो चन्द्रमा और अग्निमें स्थित है? उस तेजको तू मुझ विष्णुकी स्वकीय ( चेतनमयी ) ज्योति समझ। पू0 -- वह चेतनमयी ज्योति तो चराचर? सभी पदार्थोंमें समानभावसे स्थित है? फिर यह विशेषता कैसे बतलायी कि जो तेज सूर्यमें स्थित है इत्यादि। उ0 -- सत्त्व -- स्वच्छताकी अधिकतासे उनमें अधिकता सम्भव होनेके कारण यह दोष नहीं है क्योंकि सूर्य आदिमें सत्त्वअत्यन्त प्रकाश अत्यन्त स्वच्छता है? अतः उनमें ही ब्रह्मज्योति अत्यन्त प्रत्यक्ष प्रतिभासित होती है? इसीसे उनकी विशेषता बतलायी गयी है। यह बात नहीं कि वहीं कुछ बह्मज्योति अधिक है। जैसे संसारमें देखा जाता है कि समान भावसे सम्मुखसामने स्थित होनेपर भी? काष्ठ या भित्ति आदिमें मुखका प्रतिबिम्ब नहीं दीखता? पर दर्पण आदि पदार्थमें? जो जितना स्वच्छ और स्वच्छतर होता है उसमें उसी तारतम्यसे? स्वच्छ और स्वच्छतर दीखता है? वैसे ही ( इस विषयमें समझो )।'),
('shankaracharya-ht:source:15.13','Śaṅkarācārya','gita.15.13','hi','translation','।।15.13।।तथा --, मैं पृथिवीमें प्रविष्ट होकर अपने उस बलसे? जो कि कामना और आसक्तिसे रहित मेरा ऐश्वर्यबल जगत्को धारण करनेके लिये पृथिवीमें प्रविष्ट है? जिस बलके कारण भारवती पृथिवी नीचे नहीं गिरती और फटती भी नहीं? सारे जगत्को धारण करता हूँ। यही बात वेदमन्त्र भी कहते हैं कि जिससे द्युलोक और भारवती पृथिवी दृढ़ है तथा वह पृथिवीको धारण करता है इत्यादि। अतः यह कहना ठीक ही है कि मैं पृथिवीमें प्रविष्ट होकर चराचर समस्त भूतप्राणियोंको धारण करता हूँ। तथा मैं ही रसस्वरूप चन्द्रमा होकर पृथिवीमें उत्पन्न होनेवाली धान? जौ आदि समस्त ओषधियोंका पोषण करता हूँ अर्थात् उनको पुष्ट और स्वादयुक्त किया करता हूँ। जो सब रसोंका आत्मा है? रस ही जिसका स्वभाव है? जो समस्त रसोंकी खानि है वह सोम है? वही अपने रसका सञ्चार करके? समस्त वनस्पतियोंका पोषण किया करता है।'),
('shankaracharya-ht:source:15.14','Śaṅkarācārya','gita.15.14','hi','translation','।।15.14।।तथा --, मैं ही? पेटमें रहनेवाला जठराग्नि होकर अर्थात् यह अग्नि वैश्वानर है जो कि पुरुषके भीतर स्थित है और जिससे यह ( खाया हुआ ) अन्न पचता है इत्यादि श्रुतियोंसे जिसका वर्णन किया गया है? वह वैश्वानर होकर? प्राणियोंके शरीरमें स्थित -- प्रविष्ट होकर प्राण और अपानवायुसे संयुक्त हुआ भक्ष्य? भोज्य? लेह्य और चोष्य -- ऐसे चार प्रकारके अन्नोंको पचाता हूँ। वैश्वानर अग्नि खानेवाला है और सोम खाया जानेवाला अन्न है। सुतरां यह सारा जगत् अग्नि और सोमस्वरूप है? इस प्रकार देखनेवाला मनुष्य अन्नके दोषसे लिप्त नहीं होता।'),
('shankaracharya-ht:source:15.15','Śaṅkarācārya','gita.15.15','hi','translation','।।15.15।।तथा --, मैं समस्त प्राणिमात्रका आत्मा होकर उनके अन्तःकरणमें स्थित हूँ। इसलिये समस्त प्राणियोंके स्मृति? ज्ञान और उनका लोप भी मुझ आत्मासे ही किया जाता है? अर्थात् जिन पुण्यकर्मा प्राणियोंको उनके पुण्यकर्मोंके अनुसार ज्ञान और स्मृति प्राप्त होते हैं तथा जिन पापाचारियोंके ज्ञान और स्मृतिका उनके पापकर्मानुसार लोप होता है ( वह मुझसे ही होता है )। समस्त वेदोंद्वारा मैं परमात्मा ही जाननेयोग्य हूँ। तथा वेदान्तका कर्ता? अर्थात् वेदान्तार्थके सम्प्रदायका कर्ता और वेदके अर्थको समझनेवाला भी मैं ही हूँ। यदादित्यगतं तेजः इत्यादि चार श्लोकोंद्वारा नारायण नामक भगवान् ईश्वरकी? विशेषउत्तम उपाधियोंसे,होनेवाली विभूतियाँ संक्षेपसे कही गयीं।'),
('shankaracharya-ht:source:15.16','Śaṅkarācārya','gita.15.16','hi','translation','।।15.16।।अब? क्षर और अक्षर -- इन दोनों उपाधियोंसे अलग बतलाकर? उसी उपाधिरहित शुद्ध परमात्माके स्वरूपका निश्चय करनेकी इच्छासे? अगले श्लोकोंका आरम्भ किया जाता है। उनमें पहलेके और आगे आनेवाले सभी अध्यायोंके समस्त अभिप्रायको तीन भेदोंमें विभक्त करके कहते हैं --, समुदायरूपसे पृथक् किये हुए ये दो भाव? संसारमें पुरुष नामसे कहे जाते हैं। इनमेंसे एक समुदाय क्षीण होनेवाला -- नाशवान् क्षर पुरुष है और दूसरा उससे विपरीत अक्षर पुरुष है? जो कि भगवान्की मायाशक्ति है? क्षर पुरुषकी उत्पत्तिका बीज है? तथा अनेक संसारी जीवोंकी कामना और कर्म आदिके संस्कारोंका आश्रय है? वह अक्षर पुरुष कहलाता है। वे दोनों पुरुष कौन हैं सो भगवान् स्वयं ही बतलाते हैं -- समस्त भूत अर्थात् प्रकृतिका सारा विकार तो क्षर पुरुष है और कूटस्थ अर्थात् जो कूट -- राशिकी भाँति स्थित है अथवा कूट नाम मायाका है जिसके वञ्चना? छल? कुटिलता आदि पर्याय हैं? उपर्युक्त माया आदि अनेक प्रकारसे जो स्थित है? वह कूटस्थ है। संसारका बीज? अन्तरहित होनेके कारण वह कूटस्थ नष्ट नहीं होता? अतः अक्षर कहा जाता है।'),
('shankaracharya-ht:source:15.17','Śaṅkarācārya','gita.15.17','hi','translation','।।15.17।।तथा जो क्षर और अक्षर -- इन दोनोंसे विलक्षण है? और क्षरअक्षररूप दोनों उपाधियोंके दोषसे रहित है वह नित्य? शुद्ध? बुद्ध और मुक्तस्वभाववाला --, उत्तमअतिशय उत्कृष्ट पुरुष तो अन्य ही है। अर्थात् इन दोनोंसे अत्यन्त विलक्षण है? जो कि परमात्मा नामसे कहा गया है। वह ईश्वर अविद्याजनित शरीरादि आत्माओंकी अपेक्षा पर है और सब प्राणियोंका आत्मा यानी अन्तरात्मा है इस कारण वैदान्तवाक्योंमें वह परमात्मा नामसे कहा गया है। उसीका विशेषरूपसे निरूपण करते हैं -- जो पृथ्वी? अन्तरिक्ष और स्वर्ग -- इन तीनों लोकोंको? अपने चैतन्यबलकी शक्तिसे उनमें प्रविष्ट होकर? केवल स्वरूपसत्तामात्रसे उनको धारण करता है और जो अविनाशी ईश्वर है? अर्थात् जिसका कभी नाश न हो? ऐसा नारायण नामक सर्वज्ञ और सबका शासन करनेवाला है।'),
('shankaracharya-ht:source:15.18','Śaṅkarācārya','gita.15.18','hi','translation','।।15.18।।उपर्युक्त ईश्वरका पुरुषोत्तम् यह नाम प्रसिद्ध है? उसका यह नाम किस कारणसे हुआ इसकी हेतुसहित उपपत्ति बतलाकर? नामकी सार्थकता दिखलाते हुए भगवान् अपने स्वरूपको प्रकट करते हैं कि मैं निरतिशय ईश्वर हूँ --, क्योंकि मैं क्षरभावसे अतीत हूँ अर्थात् अश्वत्थ नामक मायामय संसारवृक्षका अतिक्रमण किये हुए हूँ और संसारवृक्षके बीजस्वरूप अक्षरसे ( मूल प्रकृतिसे ) भी उत्तम -- अतिशय उत्कृष्ट अथवा अतिशय उच्च हूँ। इसीलिये अर्थात् क्षर और अक्षरसे उत्तम होनेके कारण? लोक और वेदमें? मैं पुरुषोत्तम नामसे विख्यात हूँ। भक्तजन मुझे इसी प्रकार जानते हैं और कविजन भी काव्यादिमें इसी नामका प्रयोग करते हैं अर्थात् पुरुषोत्तम् इसी नामसे ही मेरा वर्णन करते हैं।'),
('shankaracharya-ht:source:15.19','Śaṅkarācārya','gita.15.19','hi','translation','।।15.19।।अब इस प्रकार बतलाये हुए आत्मतत्त्वको जो जानता है उसके लिये यह फल बतलाया जाता है --, जो कोई अज्ञानसे रहित हुआ पुरुष? उपर्युक्त विशेषणोंसे युक्त मुझ पुरुषोत्तम ईश्वरको? ऊपर कहे हुए प्रकारसे यह जानता है कि यह ( पुरुषोत्तम ) मैं हूँ? वह सर्वज्ञ है -- वह सर्वात्मभावसे सबको जानता है? अतः सर्वज्ञ है और हे भारत ( वह ) सब भूतोंमें स्थित मुझ परमात्माको ही सर्वभावसे -- सबका आत्मा समझकर भजता है।'),
('shankaracharya-ht:source:15.20','Śaṅkarācārya','gita.15.20','hi','translation','।।15.20।।इस अध्यायमें मोक्षरूप फलके देनेवाले भगवत्तत्त्वज्ञानको कहकर अब उसकी स्तुति करते हैं --, यह गुह्यतम -- सबसे अधिक गोपनीय अर्थात् अत्यन्त गूढ़ रहस्य है। वह क्या है शास्त्र। यद्यपि सारी गीताका नाम ही शास्त्र कहा जाता है? परंतु यहाँ स्तुतिके लिये प्रकरणसे यह ( पंद्रहवाँ ) अध्याय ही शास्त्र नामसे कहा गया है। क्योंकि इस अध्यायमें केवल सारे गीताशास्त्रका अर्थ ही संक्षेपसे नहीं कहा गया है? किन्तु इसमें समस्त वेदोंका अर्थ भी समाप्त हो गया है। यह कहा भी है कि जो उसे जानता है वही वेदको जाननेवाला है समस्त वेदोंसे मैं ही जाननेयोग्य हूँ। हे निष्पाप अर्जुन ऐसा यह ( परम गोपनीय शास्त्र ) मैंने कहा है। हे भारत ऊपर दिखलाये हुए अर्थसे युक्त इस शास्त्रको जानकर ही? मनुष्य बुद्धिमान् और कृतकृत्य होता है? अन्य प्रकारसे नहीं। अभिप्राय यह है कि जिसने करनेयोग्य सब कुछ कर लिया हो? वह कृतकृत्य है? अतः श्रेष्ठ कुलमें जन्म लेनेवाले ब्राह्मणद्वारा जो कुछ किया जानेयोग्य है? वह सब भगवान्का तत्त्व जान लेनेपर किया हुआ हो जाता है। अन्य प्रकारसे किसीके भी कर्तव्यकी समाप्ति नहीं होती। कहा भी है कि हे पार्थ समस्त कर्मसमुदाय? ज्ञानमें सर्वथा समाप्त हो जाता है। तथा मनुका भी वचन है कि विशेषरूपसे ब्राह्मणके जन्मकी यही पूर्णता है क्योंकि इसीको प्राप्त करके द्विज कृतकृत्य होता है अन्य प्रकारसे नहीं। हे भारत क्योंकि तूने मुझसे यह परमार्थतत्त्व सुना है? इसलिये तू कृतार्थ हो गया है।'),
('shankaracharya-ht:source:16.1','Śaṅkarācārya','gita.16.1','hi','translation','।।16.1।।उन तीनोंमें दैवी प्रकृति संसारसे मुक्त करनेवाली है? तथा आसुरी और राक्षसी प्रकृतियाँ बन्धन करनेवाली हैं? अतः यहाँ दैवी प्रकृति सम्पादन करनेके लिये और दूसरी दोनों त्यागनेके लिये दिखलायी जाती हैं -- श्रीभगवान् बोले --, अभयनिर्भयता? सत्त्वसंशुद्धि -- अन्तःकरणकी शुद्धि व्यवहारमें दूसरेके साथ ठगाई? कपट और झूठ आदि अवगुणोंको छोड़कर शुद्ध भावसे आचरण करना। ज्ञान और योगमें निरन्तर स्थिति -- शास्त्र और आचार्यसे आत्मादि पदार्थोंको जानना ज्ञान है और उन जाने हुए पदार्थोंका इन्द्रियादिके निग्रहसे ( प्राप्त ) एकाग्रताद्वारा अपने आत्मामें प्रत्यक्ष अनुभव कर लेना योग है। उन ज्ञान और योग दोनोंमें स्थिति अर्थात् स्थिर हो जाना -- तन्मय हो जाना? यही प्रधान सात्त्विकी -- दैवी संपद् है। और भी जिन अधिकारियोंकी जिस विषयमें जो सात्त्विकी प्रकृति हो सकती है वह कही जाती है -- दान -- अपनी शक्तिके अनुसार अन्नादि वस्तुओंका विभाग करना। दम -- बाह्य इन्द्रियोंका संयम। अन्तःकरणकी उपरामता तो शान्तिके नामसे आगे कही जायगी। यज्ञ -- अग्निहोत्रादि श्रौतयज्ञ और देवपूजनादि स्मार्तयज्ञ। स्वाध्याय -- अदृष्टलाभके लिये ऋक् आदि वेदोंका अध्ययन करना। तप -- शारीरिक आदि तप जो आगे बतलाया जायगा और आर्जव अर्थात् सदा सरलता सीधापन।'),
('shankaracharya-ht:source:16.2','Śaṅkarācārya','gita.16.2','hi','translation','।।16.2।।तथा --, अहिंसा -- किसी भी प्राणीको कष्ट न देना? सत्यअप्रियता और असत्यसे रहित यथार्थ वचन। अक्रोध -- दूसरोंके द्वारा गाली दी जाने या ताड़ना दी जानेपर उत्पन्न हुए क्रोधको शान्त कर लेना। त्याग -- संन्यास ( दान नहीं ) क्योंकि दान पहले कहा जा चुका है। शान्ति -- अन्तःकरणका संकल्परहित होना? अपैशुन -- अपिशुनता किसी दूसरेके सामने पराये छिद्रोंको प्रकट करना पिशुनता ( चुगली ) है? उसका न होना अपिशुनता है। भूतोंपर दया -- दुखी प्राणियोंपर कृपा करना? अलोलुपता -- विषयोंके साथ संयोग होनेपर भी इन्द्रियोंमें विकार न होना? मार्दवकोमलता अर्थात् अक्रूरता। ह्री -- लज्जा और अचपलता -- बिना प्रयोजन वाणी? हाथ? पैर आदिकी व्यर्थ क्रियाओंका न करना।'),
('shankaracharya-ht:source:16.3','Śaṅkarācārya','gita.16.3','hi','translation','।।16.3।।तथा --, तेज प्रागल्भ्य ( तेजस्विता )? चमड़ीकी चमक नहीं। क्षमा -- गाली दी जाने या ताड़ना दी जानेपर भी अन्तःकरणमें विकार उत्पन्न न होना। उत्पन्न हुए विकारको शान्ति कर देना तो पहले अक्रोधके नामसे कह चुके हैं। क्षमा और अक्रोधका इतना ही भेद है। धृति शरीर और इन्द्रियादिमें थकावट उत्पन्न होनेपर? उस थकावटको हटानेवाली जो अन्तःकरणकी वृत्ति है? उसका नाम धृति है? जिसके द्वारा उत्साहित की हुई इन्द्रियाँ और शरीर कार्यमें नहीं थकते। शौच दो प्रकारकी शुद्धि? अर्थात् मिट्टी और जल आदिसे बाहरकी शुद्धि? एवं कपट और रागादिकी कालिमाका अभाव होकर मनबुद्धिकी निर्मलतारूप भीतरकी शुद्धि? इस प्रकार दो तरह की शुद्धि। अद्रोह -- दूसरेका घात करनेकी इच्छाका अभाव? यानी हिंसा न करना। अतिमानिताका अभाव अत्यन्त मानका नाम अतिमान है? वह जिसमें हो वह अतिमानी है? उसका भाव अतिमानिता है? उसका जो अभाव है वह नातिमानिता है? अर्थात् अपनेमें अतिशय पूज्य भावनाका न होना। हे भारत अभय से लेकर यहाँतकके ये सब लक्षण? सम्पत्तियुक्त उत्पन्न हुए पुरुषमें होते हैं। कैसी सम्पत्तिसे युक्त पुरुषमें होते हैं जो दैवी सम्पत्तिको साथ लेकर उत्पन्न हुआ है? अर्थात् जो देवताओंकी विभूतिका योग्य पात्र है और भविष्यमें जिसका कल्याण होना निश्चित है? उस पुरुषके ये लक्षण होते हैं।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:16.4','Śaṅkarācārya','gita.16.4','hi','translation','।।16.4।।अब आगे आसुरी सम्पत्ति कही जाती है --, दम्भ -- धर्मध्वजीपन? दर्प -- धनपरिवार आदिके निमित्तसे होनेवाला गर्व? अतिमान -- पहले कही हुई अपनेमें अतिशय पूज्य भावना तथा क्रोध और पारुष्य यानी कठोर वचन जैसे ( आक्षेपसे ) कानेको अच्छे नेत्रोंवाला? कुरूपको रूपवान् और हीन जातिवालेको उत्तम जातिवाला बतलाना इत्यादि। अज्ञान अर्थात् अविवेक -- कर्तव्य और अकर्तव्यादिके विषयमें उलटा निश्चय करना। हे पार्थ ये सब लक्षण? आसुरी सम्पत्तिको ग्रहण करके उत्पन्न हुए मनुष्यके हैं? अर्थात् जो असुरोंकी सम्पत्ति है उससे युक्त होकर उत्पन्न हुए मनुष्यके चिह्न हैं।,'),
('shankaracharya-ht:source:16.5','Śaṅkarācārya','gita.16.5','hi','translation','।।16.5।।इन दोनों सम्पत्तियोंका कार्य बतलाया जाता है --, जो दैवी सम्पत्ति है? वह तो संसारबन्धनसे मुक्त करनेके लिये है? तथा आसुरी और राक्षसी सम्पत्ति निःसन्देह बन्धनके लिये मानी गयी है। निश्चित बन्धनका नाम निबन्ध है? उसके लिये मानी गयी है। इतना कहनेके उपरान्त अर्जुनके अन्तःकरणमें यह संशययुक्त विचार उत्पन्न हुआ देखकर? कि क्या मैं आसुरी सम्पत्तिसे युक्त हूँ अथवा दैवी सम्पत्तिसे भगवान् बोले -- हे पाण्डव शोक मत कर? तू दैवी सम्पत्तिको लेकर उत्पन्न हुआ है। अर्थात् भविष्यमें तेरा कल्याण होनेवाला है।'),
('shankaracharya-ht:source:16.6','Śaṅkarācārya','gita.16.6','hi','translation','।।16.6।।इस संसारमें मनुष्योंकी दो सृष्टियाँ हैं। जिसकी रचना की जाय वह सृष्टि है? अतः दैवी,सम्पत्ति और आसुरी सम्पत्तिसे युक्त रचे हुए प्राणी ही? यहाँ भूतसृष्टिके नामसे कहे जाते हैं। प्रजापतिकी दो संतानें हैं देव और असुर इस श्रुतिसे भी यही बात सिद्ध होती है। क्योंकि इस संसारमें सभी प्राणियोंके दो प्रकार हो सकते हैं। प्राणियोंकी वे दो प्रकारकी सृष्टियाँ कौनसी हैं इसपर कहते हैं कि इस प्रकरणमें कही हुई दैवी और आसुरी। कही हुई दोनों सृष्टियोंका पुनः अनुवाद करनेका कारण बतलाते हैं -- दैवी सृष्टिका वर्णन तो अभयं सत्त्वसंशुद्धिः इत्यादि श्लोकोंद्वारा? विस्तारपूर्वक किया गया। परंतु आसुरी सृष्टिका वर्णन विस्तारसे नहीं हुआ। अतः हे पार्थ उसका त्याग करनेके लिये? उस आसुरी सृष्टिको? तू मुझसेमेरे वचनोंसे? विस्तारपूर्वक सुन? यानी सुनकर निश्चय कर।,'),
('shankaracharya-ht:source:16.7','Śaṅkarācārya','gita.16.7','hi','translation','।।16.7।।इस अध्यायकी समाप्तिपर्यन्त प्राणियोंके विशेषणोंद्वारा आसुरी सम्पत्ति दिखलायी जाती है? क्योंकि प्रत्यक्ष कर लेनेसे ही उसका त्याग करना बन सकता है --, आसुरी स्वभाववाले मनुष्य? प्रवृत्तिको अर्थात् जिस किसी पुरुषार्थके साधनरूप कर्तव्यकार्यमें प्रवृत्त होना उचित है? उसमें प्रवृत्त होनेको? और निवृत्तिको? अर्थात् उससे विपरीत जिस किसी अनर्थकारक कर्मसे निवृत्त होना उचित है? उससे निवृत्त होनेको भी? नहीं जानते। केवल प्रवृत्तिनिवृत्तिको नहीं जानते? इतना ही नहीं? उनमें न शुद्धि होती है? न सदाचार होता है? और न सत्य ही होता है। यानी आसुरी प्रकृतिके मनुष्य अशुद्ध? दुराचारी? कपटी और मिथ्यावादी ही होते हैं।'),
('shankaracharya-ht:source:16.8','Śaṅkarācārya','gita.16.8','hi','translation','।।16.8।।तथा --, वे आसुर स्वभाववाले मनुष्य कहा करते हैं कि जैसे हम झूठसे भरे हुए हैं? वैसे ही यह सारा संसार भी झूठा और प्रतिष्ठारहित है? अर्थात् धर्मअधर्म आदि इसका कोई आधार नहीं है? अतः निराधार है तथा अनीश्वर है? अर्थात् पुण्यपापकी अपेक्षासे इसका शासन करनेवाला कोई स्वामी नहीं है? अतः यह जगत् बिना ईश्वरका है। तथा कामसे प्रेरित हुए स्त्रीपुरुषोंका आपसमें संयोग हो जानेसे ही सारा जगत् उत्पन्न हुआ है? अतः इस जगत्का कारण काम ही है? दूसरा और क्या हो सकता है अर्थात् ( इसका ) धर्मअधर्मादि कोई दूसरा अदृष्ट कारण नहीं है? केवल काम ही प्राणियोंका कारण है। यह लोकायतिकों की दृष्टि है।'),
('shankaracharya-ht:source:16.9','Śaṅkarācārya','gita.16.9','hi','translation','।।16.9।।इस दृष्टिका अवलम्बन -- आश्रय लेकर जिनका स्वभाव नष्ट हो गया है? जो परलोकसाधनसे भ्रष्ट हो गये हैं? जो अल्पबुद्धि हैं -- जिनकी बुद्धि केवल भोगोंको ही विषय करनेवाली है? ऐसे वे अल्पबुद्धि? उग्रकर्मा -- क्रूर कर्म करनेवाले? हिंसापरायण संसारके शत्रु? संसारका नाश करनेके लिये ही उत्पन्न होते हैं।'),
('shankaracharya-ht:source:16.10','Śaṅkarācārya','gita.16.10','hi','translation','।।16.10।।तथा वे --, कभी पूर्ण न की जा सकनेवाली दुष्पूर कामनाका -- इच्छाविशेषका आश्रय -- अवलम्बन कर? पाखण्ड? मान और मदसे युक्त हुए? अशुद्धाचारी -- जिनके आचरण बहुत ही बुरे हैं ऐसे मनुष्य? मोहसे -- अज्ञानसे मिथ्या आग्रहोंको? अर्थात् अशुभ सिद्धान्तोंको ग्रहण करके -- स्वीकार करके संसारमें बर्तते हैं।'),
('shankaracharya-ht:source:16.11','Śaṅkarācārya','gita.16.11','hi','translation','।।16.11।।तथा --, जिसकी इयत्ता न जानी जा सके? ऐसी अपरिमेय -- अपार? प्रलयतक -- मरणपर्यन्त रहनेवाली चिन्ताके आश्रित हुए? अर्थात् सदा चिन्ताग्रस्त हुए? तथा कामोपभोगके परायण -- जिनकी कामना की जाय वे शब्दादि विषय काम हैं? उनके उपभोगमें तत्पर हुए -- तथा विषयोंका उपभोग करना? बस यही परम पुरुषार्थ है? ऐसा निश्चय रखनेवाले।'),
('shankaracharya-ht:source:16.12','Śaṅkarācārya','gita.16.12','hi','translation','।।16.12।।तथा सैकड़ों आशारूप पाशोंसे बँधे हुएजकड़े हुए? सब ओरसे खींचे जाते हुए? काम क्रोधके परायण हुए अर्थात् कामक्रोध ही जिनका परम अयन -- आश्रय है? ऐसे काम क्रोधपरायण पुरुष? धर्मके लिये नहीं? बल्कि भोग्य वस्तुओंका भोग करनेके लिये? अन्यायपूर्वक अर्थात् दूसरेका सत्त्व हरण करना आदि अनेक पापमय युक्तियोंद्वारा धनसमुदायको इकट्ठा करनेकी चेष्टा किया करते हैं।,'),
('shankaracharya-ht:source:16.13','Śaṅkarācārya','gita.16.13','hi','translation','।।16.13।।तथा उनका अभिप्राय ऐसा होता है कि --, आज इस समय तो मैंने यह द्रव्य प्राप्त किया है तथा अमुक मनोरथ -- मनको संतुष्ट करनेवाला पदार्थ और प्राप्त करूँगा। इतना धन तो मेरे पास है और यह इतना धन मेरे पास अगले वर्ष में फिर हो जायगा? उससे मैं धनवान् विख्यात हो जाऊँगा।'),
('shankaracharya-ht:source:16.14','Śaṅkarācārya','gita.16.14','hi','translation','।।16.14।।अमुक देवदत्त नामक दुर्जय शत्रु तो मेरे द्वारा मारा जा चुका? अब दूसरे पामर निर्बल शत्रुओंको भी मैं मार डालूँगा? यह बेचारे गरीब मेरा क्या करेंगे जो किसी तरह भी मेरे समान नहीं हैं। मैं ईश्वर हूँ? भोगी हूँ? सब प्रकारसे सिद्ध हूँ तथा पुत्रपौत्र और नातियोंसे सम्पन्न हूँ। मैं केवल साधारण मनुष्य ही नहीं हूँ? बल्कि बड़ा बलवान् और सुखी भी मैं ही हूँ? दूसरे सब तो भूमिपर भाररूप ही उत्पन्न हुए हैं।'),
('shankaracharya-ht:source:16.15','Śaṅkarācārya','gita.16.15','hi','translation','।।16.15।।मैं धनसे सम्पन्न हूँ और वंशकी अपेक्षासे अत्यन्त कुलीन हूँ? अर्थात् सात पीढ़ियोंसे श्रोत्रिय आदि गुणोंसे सम्पन्न हूँ। सुतरां धन और कुलमें भी मेरे समान दूसरा कौन है। अर्थात् कोई नहीं है। मैं यज्ञ करूँगा अर्थात् यज्ञद्वारा भी दूसरोंका अपमान करूँगा? नट आदिको धन दूँगा और मोद -- अतिशय हर्षको प्राप्त होऊँगा इस प्रकार वे मनुष्य अज्ञानसे मोहित अर्थात् नाना प्रकारकी अविवेकभावनासे युक्त होते हैं।'),
('shankaracharya-ht:source:16.16','Śaṅkarācārya','gita.16.16','hi','translation','।।16.16।।उपर्युक्त अनेक प्रकारके विचारोंसे भ्रान्तचित्त हुए और मोहरूप जालमें फँसे हुए? अर्थात् अविवेक ही मोह है? वह जालकी भाँति फँसानेवाला होनेसे जाल है? उसमे फँसे हुए? तथा विषय भोगोंमें अत्यन्त आसक्त हुए -- उन्हींमें गहरे डूबे हुए मनुष्य? उन भोगोंके द्वारा पापोंका सञ्चय करके? वैतरणी आदि अशुद्ध नरकोंमें गिरते हैं।'),
('shankaracharya-ht:source:16.17','Śaṅkarācārya','gita.16.17','hi','translation','।।16.17।।और वे अपने आपको सर्वगुणसम्पन्न मानकर? आप ही अपनेको बड़ा माननेवाले? साधु पुरुषोंद्वारा श्रेष्ठ न माने हुए? स्तब्ध -- विनयरहित? धनमानमदान्वित -- धनहेतुक मान और मदसे युक्त पुरुष? पाखण्डसे? अर्थात् धर्मध्वजीपनसे? अविधिपूर्वक -- विहित अंगकी कर्तव्यताके ज्ञानसे रहित केवल नाममात्रके यज्ञोंद्वारा पूजन किया करते हैं।'),
('shankaracharya-ht:source:16.18','Śaṅkarācārya','gita.16.18','hi','translation','।।16.18।।अहंकार -- हमहम करनेका नाम अहंकार है? जिसके द्वारा अपनेमें आरोपित किये हुए विद्यमान और अविद्यमान गुणोंसे अपनेको युक्त मानकर मनुष्य हम हैं ऐसा मानता है? उसे अहंकार कहते हैं। यह अविद्या नामका बड़ा कठिन दोष? समस्त दोषोंका और समस्त अनर्थमय प्रवृत्तियोंका मूल कारण है। कामना और आसक्तिसे युक्त? दूसरेका पराभव करनेके लिये होनेवाला बल? दर्प -- जिसके उत्पन्न होनेपर मनुष्य धर्मको अतिक्रमण कर जाता है? अन्तःकरणके आश्रित उस दोषविशेषका नाम दर्प है। तथा स्त्री आदिके विषयमें होनेवाला काम और किसी प्रकारका अनिष्ट होनेसे होनेवाला क्रोध? इन सब,दोषोंको तथा अन्यान्य महान् दोषोंको भी अवलम्बन करनेवाले होते हैं। इसके सिवा वे अपने और दूसरोंके शरीरमें स्थित? उनकी बुद्धि और कर्मके साक्षी? मुझ ईश्वरसे द्वेष करनेवाले होते हैं -- मेरी आज्ञाको उल्लङ्घन करके चलना ही मुझसे द्वेष करना है? वे वैसा करनेवाले हैं और सन्मार्गमें स्थित पुरुषोंके गुणोंको सहन न करके? उनकी निन्दा करनेवाले होते हैं।'),
('shankaracharya-ht:source:16.19','Śaṅkarācārya','gita.16.19','hi','translation','।।16.19।।सन्मार्गके प्रतिपक्षी और मेरे तथा साधुपुरुषोंके साथ द्वेष करनेवाले उन सब अशुभकर्मकारी क्रूर नराधमोंको? मैं बारंबार संसारमें -- नरकप्राप्तिके मार्गमें जो प्रायः क्रूर कर्म करनेवाली व्याघ्रसिंह आदि आसुरी योनियाँ हैं उनमें ही सदा गिराता हूँ क्योंकि वे पापादि दोषोंसे युक्त हैं। क्षिपामि इस क्रियापदका? योनिषु के साथ सम्बन्ध है।'),
('shankaracharya-ht:source:16.20','Śaṅkarācārya','gita.16.20','hi','translation','।।16.20।।वे मूढ -- अविवेकीजन? जन्मजन्ममें यानी प्रत्येक जन्ममें आसुरी योनिको पाते हुए अर्थात् जिनमें तमोगुणकी बहुलता है? ऐसी योनियोंमें जन्मते हुए? नीचे गिरतेगिरते मुझ ईश्वरको न पाकर? उन पूर्वप्राप्त योनियोंकी अपेक्षा भी अधिक अधमगतिको प्राप्त होते हैं। मुझे प्राप्त न होकर ऐसा कहनेका तात्पर्य यह है कि मेरे द्वारा कहे हुए श्रेष्ठ मार्गको भी न पाकर? क्योंकि मेरी प्राप्तिकी तो उनके लिये कोई आशङ्का ही नहीं है।,'),
('shankaracharya-ht:source:16.21','Śaṅkarācārya','gita.16.21','hi','translation','।।16.21।।अब यह समस्त आसुरी सम्पत्तिका संक्षेप कहा जाता है। जिन ( कामादि ) तीन भेदोंमें? आसुरी सम्पत्तिके अनन्त भेद होनेपर भी सबका अन्तर्भाव हो जाता है? जिन तीनोंका नाश करनेसे सब दोषोंका नाश करना हो जाता है और जो सब अनर्थोंके मूल कारण हैं? उनका वर्णन किया जाता है --, आत्माका नाश करनेवाले? ये तीन प्रकारके दोष? नरकप्राप्तिके द्वार हैं। इनमें प्रवेश करनेमात्रसे ही आत्मा नष्ट हो जाता है? अर्थात् किसी पुरुषार्थके योग्य नहीं रहता। इसलिये ये तीनों आत्माका नाश करनेवाले द्वार कहलाते हैं। वे कौन हैं काम? क्रोध और लोभ। सुतरां इन तीनोंका त्याग कर देना चाहिये। क्योंकि ये काम आदि तीनों नरकद्वार आत्माका नाश करनेवाले हैं? इसलिये इनका त्याग कर देना चाहिये। यह त्यागकी स्तुति है।'),
('shankaracharya-ht:source:16.22','Śaṅkarācārya','gita.16.22','hi','translation','।।16.22।।हे कुन्तीपुत्र ये काम आदि दुःख और मोहरूप अन्धकारमय नरकके द्वार हैं इन तीनों अवगुणोंसे छूटा हुआ मनुष्य आचरण करता है -- साधन करता है। क्या साधन करता है आत्मकल्याणका साधन? पहले जिन कामादिके वशमें होनेसे नहीं करता था? अब उनका नाश हो जानेसे करता है? और उस साधनसे ( वह ) परमगतिको? अर्थात् मोक्षको भी प्राप्त कर लेता है।'),
('shankaracharya-ht:source:16.23','Śaṅkarācārya','gita.16.23','hi','translation','।।16.23।।इस समस्त आसुरी सम्पत्तिके त्यागका और कल्याणमय आचरणोंका? मूल कारण शास्त्र है? शास्त्रप्रमाणसे ही दोनों किये जा सकते हैं? अन्यथा नहीं? अतः --, जो मनुष्य शास्त्रके विधानको? अर्थात् कर्तव्यअकर्तव्यके ज्ञानका कारण जो विधिनिषेधबोधक आदेश है उसको? छोड़कर कामनासे प्रयुक्त हुआ बर्तता है? वह न तो सिद्धिको -- पुरुषार्थकी योग्यताको पाता है? न इस लोकमें सुख पाता है और न परम गतिको अर्थात् स्वर्ग या मोक्षको ही पाता है।'),
('shankaracharya-ht:source:16.24','Śaṅkarācārya','gita.16.24','hi','translation','।।16.24।।सुतरां कर्तव्य और अकर्तव्यकी व्यवस्थामें तेरे लिये शास्त्र ही प्रमाण है? अर्थात् ज्ञान प्राप्त करनेका साधन है। अतः शास्त्रविधानसे कही हुई बातको समझकर यानी आज्ञाका नाम विधान है। शास्त्रद्वारा जो ऐसी आज्ञा दी जाय कि यह कार्य कर? यह मत कर वह शास्त्रविधान है? उससे बताये,हुए स्वकर्मको जानकर तुझे इस कर्मक्षेत्रमें कार्य करना उचित है। इह शब्द जिस भूमिमें कर्मोंका अधिकार है उसका लक्ष्य करवानेवाला है।'),
('shankaracharya-ht:source:17.1','Śaṅkarācārya','gita.17.1','hi','translation','।।17.1।।तस्मात् शास्त्रं प्रमाणं ते इस भगवद्वाक्यसे जिसको प्रश्नका बीज मिला है वह अर्जुन बोला --, जो कोई साधारण मनुष्य? शास्त्रविधिको -- शास्त्रकी आज्ञाको अर्थात् श्रुतिस्मृति आदि शास्त्रोंके विधानको छोड़कर श्रद्धासे अर्थात् आस्तिकबुद्धिसे युक्त यानी सम्पन्न होकर देवादिका पूजन करते हैं। यहाँ ये शास्त्रविधिमुत्सृज्य यजन्ते श्रद्धयान्विताः इस कथनसे श्रुतिरूप या स्मृतिरूप किसी भी शास्त्रके विधानको न जानकर? केवल वृद्ध व्यवहारको आदर्श मानकर? जो श्रद्धापूर्वक देवादिका पूजन करते हैं? वे ही मनुष्य ग्रहण किये गये हैं। किंतु जो मनुष्य कुछ शास्त्रविधिको जानते हुए भी? उसको छोड़कर अविधिपूर्वक देवादिका पूजन करते हैं? वे ये शास्त्रविधिमुत्सृज्य यजन्ते इस कथनसे ग्रहण नहीं किये जा सकते। पू0 -- किसलिये ( ग्रहण नहीं किये जा सकते ) उ0 -- श्रद्धासे युक्त हुए ( पूजन करते हैं ) ऐसा विशेषण दिया गया है इसलिये। क्योंकि देवादिके पूजाविषयक किसी भी शास्त्रको जानते हुए ही उसे अश्रद्धापूर्वक छोड़कर? उस शास्त्रद्वारा विधान की हुई देवादिकी पूजामें श्रद्धासे युक्त हुए बर्तते हैं? ऐसी कल्पना नहीं की जा सकती। अतः पहले बतलाये हुए मनुष्य ही ये शास्त्रविधिमुत्सृज्य यजन्ते श्रद्धयान्विताः इस कथनसे ग्रहण किये जाते हैं। हे कृष्ण इस प्रकारके उन मनुष्योंकी निष्ठा कौनसी है सात्त्विक है राजस है अथवा तामस है यानी उनकी स्थिति सात्त्विकी है या राजसी या तामसी है कहनेका अभिप्राय यह है कि उनकी जो देवादिविषयक पूजा है? वह सात्त्विकी है राजसी है अथवा तामसी है।'),
('shankaracharya-ht:source:17.2','Śaṅkarācārya','gita.17.2','hi','translation','।।17.2।।यह प्रश्न साधारण मनुष्योंके विषयमें है अतः इसका उत्तर बिना विभाग किये देना उचित नहीं? इस अभिप्रायसे श्रीभगवान् बोले --, जिस निष्ठाके विषयमें तू पूछता है? मनुष्योंकी वह स्वभावजन्य श्रद्धा अर्थात् जन्मान्तरमें किये हुए धर्मअधर्म आदिके जो संस्कार मृत्युके समय प्रकट हुआ करते हैं उनके समुदायका नाम स्वभाव है? उससे उत्पन्न हुई श्रद्धातीन प्रकारकी होती है। सत्त्वगुणसे उत्पन्न हुई देवपूजादिविषयक श्रद्धा सात्त्विकी है? रजोगुणसे उत्पन्न हुई यक्षराक्षसादिकी पूजाविषयक श्रद्धा राजसी है और तमोगुणसे उत्पन्न हुई प्रेतपिशाच आदिकी पूजाविषयक श्रद्धा तामसी है। ऐसे तीन प्रकारकी श्रद्धा होती है। उस आगे कही जानेवाली ( तीन प्रकारकी ) श्रद्धाको तू सुन।'),
('shankaracharya-ht:source:17.3','Śaṅkarācārya','gita.17.3','hi','translation','।।17.3।।वह श्रद्धा इस तरह तीन प्रकारकी होती है --, हे भारत सभी प्राणियोंकी श्रद्धा ( उनके ) भिन्नभिन्न संस्कारोंसे युक्त अन्तःकरणके अनुरूप होती है। यदि ऐसा है तो उससे क्या होगा इसपर कहते हैं -- यह पुरुष अर्थात् संसारी जीव श्रद्धामय है क्योंकि जो जिस श्रद्धावाला है अर्थात् जिस जीवकी जैसी श्रद्धा है? वह स्वयं भी वही है? अर्थात् उस श्रद्धाके अनुरूप ही है।'),
('shankaracharya-ht:source:17.4','Śaṅkarācārya','gita.17.4','hi','translation','।।17.4।।इसलिये कार्यरूप चिह्नसे अर्थात् ( उन श्रद्धाओंके कारण होनेवाली ) देवादिकी पूजासे?,सात्त्विक आदि निष्ठाओंका अनुमान कर लेना चाहिये? यह कहते हैं --, सात्त्विक निष्ठावाले पुरुष देवोंका पूजन करते हैं? राजसी पुरुष यक्ष और राक्षसोंका तथा अन्य जो तामसी मनुष हैं? वे प्रेतों और सप्तमातृकादि भूतगणोंका पूजन किया करते हैं।'),
('shankaracharya-ht:source:17.5','Śaṅkarācārya','gita.17.5','hi','translation','।।17.5।।इस प्रकार कार्यसे जिनकी सात्त्विकादि निष्ठाओंका निर्णय किया गया है उन ( स्वाभाविक श्रद्धावाले ) हजारों मनुष्योंमें कोई एक ही शास्त्रविधिका त्याग होनेपर देवपूजादिके परायण? सात्त्विक निष्ठायुक्त होता है। अधिकांश मनुष्य तो राजसी और तामसी निष्ठावाले ही होते हैं। कैसे ( सो कहा जाता है -- ) जो मनुष्य? शास्त्रमें जिसका विधान नहीं है ऐसा? अशास्त्रविहित और घोर अर्थात् अन्य प्राणियोंको और अपने शरीरको भी पीड़ा पहुँचानेवाला? तप? दम्भ और अहंकार -- इन दोनोंसे युक्त होकर तथा कामना और आसक्तिजनित बलसे युक्त होकर? अथवा कामना? आसक्ति और बलसे युक्त होकर तपते हैं।'),
('shankaracharya-ht:source:17.6','Śaṅkarācārya','gita.17.6','hi','translation','।।17.6।।वे अविवेकी मनुष्य? शरीरमें स्थित इन्द्रियादि करणोंके रूपमें परिणत भूतसमुदायको और शरीरके भीतर अन्तरात्मारूपसे स्थित? उनके कर्म और बुद्धिके साक्षी? मुझ ईश्वरको भी? कृश ( तंग ) करते हुए -- मेरी आज्ञाको न मानना ही मुझे कृश करना है? इस प्रकार मुझे कृश करते हुए ( घोर तप करते हैं ) उनको तू आसुरी निश्चयवाले जान। जिनका असुरोंकासा निश्चय हो? वे आसुरी निश्चयवाले कहलाते हैं। उनका सङ्ग त्याग करनेके लिये तू उनको जान? यह उपदेश है।'),
('shankaracharya-ht:source:17.7','Śaṅkarācārya','gita.17.7','hi','translation','।।17.7।।रसयुक्त और स्निग्ध आदि भोजनोंमें? अपनी रुचिकी अधिकतारूप लक्षणसे अपना सात्त्विकत्व? राजसत्व और तामसत्व जानकर? राजस और तामस चिह्नोंवाले आहारका त्याग और सात्त्विक चिह्नयुक्त आहारका ग्रहण करनेके लिये? यहाँ रस्यस्निग्ध आदि ( वाक्योंद्वारा वर्णित ) तीन वर्गोंमें विभक्त हुए आहारमें? क्रमसे सात्त्विक? राजस और तामस पुरुषोंकी ( पृथक्पृथक् ) रुचि दिखलायी जाती है। वैसे ही सात्त्विक आदि गुणोंके भेदसे यज्ञादिके भेदोंका प्रतिपादन भी यहाँ इसीलिये किया जाता है कि राजस और तामस यज्ञादिको जानकर किसी प्रकार लोग उनका त्याग कर दें और सात्त्विक यज्ञादिका अनुष्ठान किया करें --, भोजन करनेवाले सभी मनुष्योंको तीन प्रकारके आहार प्रियरुचिकर होते हैं। वैसे ही यज्ञ? तप और दान भी ( तीनतीन प्रकारके होते हैं ) उन आहारादिका यह आगे कहा जानेवाला भेद सुन।'),
('shankaracharya-ht:source:17.8','Śaṅkarācārya','gita.17.8','hi','translation','।।17.8।।आयु? बुद्धि? बल? आरोग्यता? सुख और प्रीति? इन सबको बढ़ानेवाले तथा रस्यरसयुक्त? स्निग्ध -- चिकने? स्थिर -- शरीरमें बहुत कालतक ( साररूपसे ) रहनेवाले और हृद्य -- हृदयको प्रिय लगनेवाले ऐसे आहार ((৷৷) भोजन करनेके पदार्थ ) सात्त्विक पुरुषको प्रिय -- इष्ट होते हैं।'),
('shankaracharya-ht:source:17.9','Śaṅkarācārya','gita.17.9','hi','translation','।।17.9।।कड़वे? खट्टे? लवणयुक्त? आति उष्ण? तीक्ष्ण? रूखे और दाहकारक? एवं दुःख? चिन्ता और रोगोंको उत्पन्न करनेवाले अर्थात् जो दुःख? शोक और रोगोंको उत्पन्न करते हों? ऐसे आहार राजस पुरुषको प्रिय होते हैं। यहाँ अति शब्द सबके साथ जो़ड़ना चाहिये? जैसे अति कड़वे? अत्यन्त खट्टे? अति तीक्ष्ण इत्यादि।'),
('shankaracharya-ht:source:17.10','Śaṅkarācārya','gita.17.10','hi','translation','।।17.10।।यातयाम -- अधपका? गतरस -- रसरहित? पूति -- दुर्गन्धयुक्त और बासी अर्थात् जिसको पके हुए एक रात बीत गयी हो? तथा उच्छिष्ट -- खानेके पश्चात् बचा हुआ और अमेध्य -- जो यज्ञके योग्य न हो? ऐसा भोजन तामसी मनुष्योंको प्रिय होता है। यहाँ? यातयामका अर्थ अधपका किया गया है क्योंकि निर्वीर्य ( सारहीन भोजनको गतरस शब्दसे कहा गया है।'),
('shankaracharya-ht:source:17.11','Śaṅkarācārya','gita.17.11','hi','translation','।।17.11।।अब तीन प्रकारके यज्ञ बतलाये जाते हैं --, फलकी इच्छा न करनेवाले पुरुषोंद्वारा? शास्त्रविधिसे नियत किये हुए जिस यज्ञका अनुष्ठान किया जाता है?,तथा यज्ञ करना ही यानी यज्ञके स्वरूपका सम्पादन करना ही कर्तव्य है इस प्रकार मनका समाधान करके अर्थात् इससे मुझे कोई पुरुषार्थ सिद्ध नहीं करना है ऐसा निश्चय करके जो यज्ञ किया जाता है? वह सात्त्विक कहलाता है।'),
('shankaracharya-ht:source:17.12','Śaṅkarācārya','gita.17.12','hi','translation','।।17.12।।हे भरतकुलमें श्रेष्ठ अर्जुन जो यज्ञ फलके उद्देश्यसे और पाखण्ड करनेके लिये किया जाता है? उस यज्ञको तू राजसी समझ।'),
('shankaracharya-ht:source:17.13','Śaṅkarācārya','gita.17.13','hi','translation','।।17.13।।जो यज्ञ शास्त्रविधिसे रहित -- शास्त्रोक्त प्रकारसे विपरीत और असृष्टान्न होता है अर्थात् जिस यज्ञमें ब्राह्मणोंको अन्न नहीं दिया जाता तथा जो मन्त्रहीन -- मन्त्र? स्वर और वर्णसे रहित? एवं बतलायी हुई दक्षिणा और श्रद्धासे भी रहित होता है? उस यज्ञको ( श्रेष्ठ पुरुष ) तामसी -- तमोगुणसे किया हुआ बतलाते हैं।'),
('shankaracharya-ht:source:17.14','Śaṅkarācārya','gita.17.14','hi','translation','।।17.14।।अब तीन प्रकारका तप कहा जाता है --, देव? ब्राह्मण? गुरु और बुद्धिमान्ज्ञानी इन सबका पूजन? शौच -- पवित्रता? आर्जव -- सरलता? ब्रह्मचर्य और अहिंसा यह सब शरीरसम्बन्धी -- शरीरद्वारा किये जानेवाले तप कहे जाते हैं अर्थात् शरीर जिनमें प्रधान है? ऐसे समस्त कार्य और करणोंसे जो कर्ताद्वारा किये जायँ वे शरीरसम्बन्धी तप कहलाते हैं। आगे यह कहेंगे भी कि उन ( सबकर्मों ) के ये पाँच कारण हैं इत्यादि।'),
('shankaracharya-ht:source:17.15','Śaṅkarācārya','gita.17.15','hi','translation','।।17.15।।जो वचन किसी प्राणीके अन्तःकरणमें उद्वेगदुःख उत्पन्न करनेवाले नहीं हैं? तथा जो सत्य? प्रिय और हितकारक हैं अर्थात् इस लोक और परलोकमें सर्वत्र हित करनेवाले हैं? यहाँ उद्वेग न करनेवाले इत्यादि लक्षणोंसे वाक्यको विशेषित किया गया है और च शब्द सब लक्षणोंका समुच्चय बतलानेके लिये है ( अतः समझना चाहिये कि ) दूसरेको किसी बातका बोध करानेके लिये कहे हुए वाक्यमें यदि सत्यता? प्रियता? हितकारिता और अनुद्विग्नता -- इन सबका अथवा इनमेंसे किसी एक? दो या तीनका अभाव हो तो वह वाणीसम्बन्धी तप नहीं है। जैसे सत्य वाक्य यदि अन्य एक? दो या तीन गुणोंसे हीन हो तो वह वाणीका तप नहीं है? वैसे ही प्रिय वचन भी यदि अन्य एक? दो या तीन गुणोंसे हीन हो तो वह वाणीसम्बन्धी तप नहीं है? तथा हितकारक वचन भी यदि अन्य एक? दो या तीन गुणोंसे हीन हो तो वह वाणीका तप नहीं है। पू0 -- तो फिर वह वाणीका तप कौनसा है उ0 -- जो वचन सत्य हो और उद्वेग करनेवाला न हो तथा प्रिय और हितकर भी हो? वह वाणीसम्बन्धी परम तप है। जैसे? हे वत्स तू शान्त हो स्वाध्याय और योगमें स्थित हो? इससे तेरा कल्याण होगा इत्यादि वचन हैं तथा यथाविधि स्वाध्यायका अभ्यास करना भी वाणीसम्बन्धी तप कहा जाता है।'),
('shankaracharya-ht:source:17.16','Śaṅkarācārya','gita.17.16','hi','translation','।।17.16।।मनका प्रसाद अर्थात् मनकी परम शान्ति -- स्वच्छता सम्पादन कर लेना? सौम्यता -- जिसको सुमनसता कहते हैं वह मुखादिको प्रसन्न करनेवाली अन्तःकरणकी शुद्धवृत्ति? मौन -- अन्तःकरणका संयम? क्योंकि वाणीका संयम भी मनःसंयमपूर्वक ही होता है? अतः कार्यसे कारण कहा जाता है? मनका निरोध अर्थात् सब ओरसे साधारणभावसे मनका निग्रह और भली प्रकार भावकी शुद्धि अर्थात् दूसरोंके साथ व्यवहार करनेमें छलकपटसे रहित होना? यह मानसिक तप कहलाता है। केवल वाणीविषयक मनके संयमका नाम मौन है और सामान्यभावसे संयम करनेका नाम आत्मनिग्रह है -- यह भेद है।'),
('shankaracharya-ht:source:17.17','Śaṅkarācārya','gita.17.17','hi','translation','।।17.17।।उपर्युक्त कायिक? वाचिक और मानसिक तप मनुष्योंद्वारा किये जानेपर? सात्त्विक आदि भेदोंसे,तीन प्रकारके कैसे होते हैं सो बतलाते हैं --, जिसका प्रकरण चल रहा है वह? तीन प्रकारका कायिक? वाचिक और मानसिक तप? जो फलाकाङ्क्षारहित और समाहितचित्त पुरुषोंद्वारा उत्तम श्रद्धापूर्वक -- आस्तिकबुद्धिपूर्वक किया जाता है? ऐसे उस तपको श्रेष्ठ पुरुष सात्त्विक -- सत्त्वगुणजनित कहते हैं।'),
('shankaracharya-ht:source:17.18','Śaṅkarācārya','gita.17.18','hi','translation','।।17.18।।जो तप सत्कार? मान और पूजाके लिये किया जाता है -- यह बड़ा श्रेष्ठ पुरुष है? तपस्वी है? ब्राह्मण है। इस प्रकार जो बड़ाई की जाती है उसका नाम सत्कार है। ( आते देखकर ) खड़े हो जाना तथा प्रणाम आदि करना -- ऐसे सम्मानका नाम मान है। पैर धोना? अर्चन करना? भोजन कराना इत्यादिका नाम पूजा है। इन सबके लिये जो तप किया जाता है और जो दम्भसे किया जाता है? वह तप यहाँ राजसी कहा गया है। तथा अनिश्चित फलवाला होनेसे नाशवान् और अनित्य भी कहा गया है।'),
('shankaracharya-ht:source:17.19','Śaṅkarācārya','gita.17.19','hi','translation','।।17.19।।जो तप अपने शरीरको पीड़ा पहुँचाकर या दूसरेका बुरा करनेके लिये मूढ़तापूर्वक आग्रहसे अर्थात् अज्ञानपूर्वक निश्चयसे किया जाता है? वह तामसी तप कहा गया है।'),
('shankaracharya-ht:source:17.20','Śaṅkarācārya','gita.17.20','hi','translation','।।17.20।।अब दानके भेद कहे जाते हैं --, जो दान देना ही उचित है मनमें ऐसा विचार करके अनुपकारीको? जो कि प्रत्युपकार करनेमें समर्थ न हो? यदि समर्थ हो तो भी जिससे प्रत्युपकार चाहा न गया हो? ऐसे अधिकारीको दिया जाता है तथा जो कुरुक्षेत्र आदि पुण्यभूमिमें? संक्रान्ति आदि पुण्यकालमें और छहों अङ्गोंके सहित वेदको जाननेवाले ब्राह्मण आदि श्रेष्ठ पात्रको दिया जाता है वह दान सात्त्विक कहा गया है।'),
('shankaracharya-ht:source:17.21','Śaṅkarācārya','gita.17.21','hi','translation','।।17.21।।जो दान प्रत्युपकारके लिये अर्थात् कालान्तरमें यह मेरा प्रत्युपकार करेगा? इस अभिप्रायसे अथवा इस दानसे मुझे परलोकमें फल मिलेगा ऐसे उद्देश्यसे क्लेश -- खेदपूर्वक दिया जाता है? वह राजस कहा गया है।'),
('shankaracharya-ht:source:17.22','Śaṅkarācārya','gita.17.22','hi','translation','।।17.22।।जो दान अयोग्य देशकालमें अर्थात् अशुद्ध वस्तुओं और म्लेच्छादिसे युक्त पापमय देशमें? तथा पुण्यके हेतु बतलाये हुए संक्रान्ति आदि विशेषतासे रहित कालमें और मूर्ख? चोर आदि अपात्रोंको दिया जाता है तथा जो अच्छे देशकालादिमें भी बिना सत्कार किये -- प्रिय वचन? पादप्रक्षालन और पूजादि सम्मानसे रहित तथा पात्रका अपमान करते हुए दिया जाता है? वह तामस कहा गया हैं।'),
('shankaracharya-ht:source:17.23','Śaṅkarācārya','gita.17.23','hi','translation','।।17.23।।यज्ञ? दान और तप आदिको सद्गुणसम्पन्न बनानेके लिये यह उपदेश दिया जाता है --, ओम् तत् सत् -- यह तीन प्रकारका ब्रह्मका निर्देश है। जिससे कोई वस्तु बतलायी जाय उसका नाम निर्देश है? अतः यह ब्रह्मका तीन प्रकारका नाम है? ऐसा वेदान्तमें ब्रह्मज्ञानियोंद्वारा माना गया है। पूर्वकालमें इस तीन प्रकारके नामसे ही ब्राह्मण? वेद और यज्ञये सब रचे गये हैं। यह ब्रह्मके नामकी स्तुति करनेके लिये कहा जाता है।'),
('shankaracharya-ht:source:17.24','Śaṅkarācārya','gita.17.24','hi','translation','।।17.24।।इसलिये वेदका प्रवचन -- पाठ करनेवाले ब्राह्मणोंकी शास्त्रविधिसे कही हुई यज्ञ? दान और तपरूप क्रियाएँ ब्रह्मके ओम् इस नामका उच्चारण करके ही सर्वदा आरम्भ की जाती हैं।'),
('shankaracharya-ht:source:17.25','Śaṅkarācārya','gita.17.25','hi','translation','।।17.25।।तत् ऐसे इस ब्रह्मके नामका उच्चारण करके और कर्मोंके फलको न चाहकर नाना प्रकारकी यज्ञ और तपरूप तथा दान अर्थात् भूमि? सोना आदिका दान करनारूप क्रियाएँ मोक्षको चाहनेवाले मुमुक्षु पुरुषोंद्वारा की जाती हैं।'),
('shankaracharya-ht:source:17.26','Śaṅkarācārya','gita.17.26','hi','translation','।।17.26।।ओम् और तत्शब्दका प्रयोग तो कहा गया अब सत्शब्दका प्रयोग कहा जाता है --, अविद्यमान वस्तुके सद्भावमें यानी जैसे अविद्यमान पुत्रादिके उत्पन्न होनेमें? तथा साधुभावमें अर्थात् बुरे आचरणोंवाले असाधु पुरुषका जो सदाचारयुक्त हो जाना है? उसमें? सत् ऐसे इस ब्रह्मके नामका प्रयोग किया जाता है अर्थात् वहाँ सत् शब्द कहा जाता है तथा हे पार्थ विवाह आदि माङ्गलिक कर्मोंमें भी सत् शब्द प्रयुक्त होता अर्थात् ( उनमें भी ) सत् शब्दका प्रयोग किया जाता है।'),
('shankaracharya-ht:source:17.27','Śaṅkarācārya','gita.17.27','hi','translation','।।17.27।।जो यज्ञकर्ममें स्थिति है? जो तपमें स्थिति है और जो दानमें स्थिति है? वह भी सत् है ऐसा विद्वानोंद्वारा कहा जाता है। तथा उन यज्ञादिके लिये जो कर्म है अथवा जिसके तीन नामोंका प्रकरण चल रहा है? उस ईश्वरके लिये जो कर्म है? वह भी सत् है यही कहा जाता है। इस प्रकार किये हुए यज्ञ और तप आदि कर्म? यदि असात्त्विक और विगुण हों तो भी श्रद्धापूर्वक परमात्माके तीनों नामोंके प्रयोगसे सगुण और सात्त्विक बना लिये जाते हैं।'),
('shankaracharya-ht:source:17.28','Śaṅkarācārya','gita.17.28','hi','translation','।।17.28।।क्योंकि सभी जगह श्रद्धाकी प्रधानतासे ही सब कुछ किया जाता है? इसलिये --, बिना श्रद्धाके किया हुआ हवन? बिना श्रद्धाके ब्राह्मणोंको दिया हुआ दान? तपा हुआ तप तथा और भी जो कुछ बिना श्रद्धाके किया हुआ स्तुति -- नमस्कारादि कर्म है वह सब? हे पार्थ मेरी प्राप्तिके साधनमार्गसे बाह्य होनेके कारण असत् है? ऐसा कहा जाता है। क्योंकि वह बहुत परिश्रमयुक्त होनेपर भी साधु पुरुषोंद्वारा निन्दित होनेके कारण न तो मरनेके पश्चात् फल देनेवाला होता है और न इस लोकमें ही सुखदायक होता है।'),
('shankaracharya-ht:source:18.1','Śaṅkarācārya','gita.18.1','hi','translation','।।18.1।।इस अध्यायमें पहलेके सभी अध्यायोंमें कहा हुआ अभिप्राय मिलता है। तथापि अर्जुन केवल संन्यास और त्याग -- इन दो शब्दोंके अर्थोंका भेद जाननेकी इच्छासे ही प्रश्न करता है --,अर्जुन बोला -- हे महाबाहो हे हृषीकेश हे केशिनिषूदन मैं संन्यासका अर्थात् संन्यासशब्दके अर्थका और त्यागका अर्थात् त्यागशब्दके अर्थका तत्त्व -- यथार्थ स्वरूप अलगअलग विभागपूर्वक जानना चाहता हूँ। भगवान् वासुदेवने छलसे घोड़ेका रूप धारण करनेवाले केशि नामक असुरको मारा था? इसलिये वे उस,( केशिनिषूदन ) नामसे अर्जुनद्वारा सम्बोधित किये गये हैं।,'),
('shankaracharya-ht:source:18.2','Śaṅkarācārya','gita.18.2','hi','translation','Hindi Translation Of Sri Shankaracharya''s Sanskrit Commentary By Sri Harikrishnadas Goenka।।18.2।।पहले अध्यायोंमें जिनका जगहजगह निर्देश किया गया है? वे संन्यास और त्याग -- दोनों शब्द स्पष्टार्थयुक्त नहीं हैं? इसलिये ( उनका स्पष्ट अर्थ जाननेकी इच्छासे ) पूछनेवाले अर्जुनको उनका निर्णय सुनानेके लिये श्रीभगवान् बोले --, कितने ही बुद्धिमान -- पण्डित लोग? अश्वमेधादि सकाम कर्मोंके त्यागको संन्यास समझते हैं अर्थात् कर्तव्यरूपसे प्राप्त ( शास्त्रविहित ) सकाम कर्मोंके न करनेको संन्यास शब्दका अर्थ समझते हैं। कुछ विचक्षण पण्डितजन अनुष्ठान किये जानेवाले नित्यनैमित्तिक सम्पूर्ण कर्मोंके? अपनेसे सम्बन्ध रखनेवाले फलका परित्याग करनारूप जो सर्वकर्मफलत्याग है? उसे ही त्याग कहते हैं? अर्थात् त्याग शब्दका वे ऐसा अभिप्राय बतलाते हैं। कहनेका अभिप्राय? चाहे काम्य कर्मोंका ( स्वरूपसे ) त्याग करना हो और चाहे समस्त कर्मोंका फल छोड़ना ही हो? सभी प्रकारसे संन्यास और त्याग इन दोनों शब्दोंका अर्थ तो? एकमात्र त्याग ही है। ये दोनों शब्द घड़ा और वस्त्र आदि शब्दोंकी भाँति भिन्न जातीय अर्थके बोधक नहीं हैं। पू0 -- जब ऐसा कहा जाता है? कि नित्य और नैमित्तिक कर्मोंका तो फल ही नहीं होता? फिर यहां वन्ध्याके पुत्रत्यागकी भाँति? उनके फलका त्याग करनेके लिये कैसे कहा जाता है उ0 -- नित्यकर्मोंका भी फल होता है -- यह बात भगवान्को इष्ट है? इसलिये यह दोष नहीं है। क्योंकि भगवान् स्वयं कहेंगे कि मरनेके बाद कर्मोंका अच्छाबुरा और मिला हुआ फल असंन्यासियोंको होता है?,संन्यासियोंको नहीं इस प्रकार वहाँ केवल संन्यासियोंके लिये कर्मफलकी अभाव दिखाकर? असंन्यासियोंके लिये कर्मफलकी प्राप्ति अवश्यम्भावी दिखलायेंगे।'),
('shankaracharya-ht:source:18.3','Śaṅkarācārya','gita.18.3','hi','translation','।।18.3।।कितने ही सांख्यादि मतावलम्बी पण्डितजन कहते हैं कि जिसमें दोष हो वह दोषवत् है। वह क्या है कि बन्धनके हेतु होनेके कारण सभी कर्म दोषयुक्त हैं? इसलिये कर्म करनेवाले कर्माधिकारी मनुष्योंके लिये भी वे त्याज्य हैं? अथवा जैसे रागद्वेष आदि दोष त्यागे जाते हैं? वैसे ही समस्त कर्म भी त्याज्य हैं। इसी विषयमें दूसरे विद्वान कहते हैं कि यज्ञ? दान और तपरूप कर्म त्याग करनेयोग्य नहीं हैं। ये सब विकल्प? कर्म करनेवाले कर्माधिकारियोंको लक्ष्य करके ही किये गये हैं। समस्त भोगोंसे विरक्त ज्ञाननिष्ट? संन्यासियोंको लक्ष्य करके नहीं। ( अभिप्राय यह कि ) सांख्ययोगियोंकी निष्ठा ज्ञानयोगके द्वारा मैं पहले कह चुका हूँ इस प्रकार जो,( संन्यासी ) कर्माधिकारसे अलग कर दिये गये हैं उनके विषयमें यहाँ कोई विचार नहीं करना है। पू0 -- कर्मयोगियोंकी निष्ठा कर्मयोगसे कही गयी है इस कथनसे जिनकी निष्ठाका विभाग पहले किया जा चुका है? उन कर्माधिकारियोंके सम्बन्धमें जिस प्रकार यहाँ गीताशास्त्रके उपसंहारप्रकरणमें फिर विचार किया जाता है? वैसे ही? सांख्यनिष्ठावाले संन्यासियोंके विषयमें भी तो किया जाना उचित ही है। उ0 -- नहीं? क्योंकि उनका त्याग मोह या दुःखके निमित्तसे होनेवाला नहीं हो सकता। ( भगवान्ने क्षेत्राध्यायमें ) इच्छा और द्वेष आदिको शरीरके ही धर्म बतलाया है इसलिये सांख्यनिष्ठ संन्यासी शारीरिक पीड़ाके निमित्तसे होनेवाले दुःखोंको आत्मामें नहीं देखते। अतः वे शारीरिक क्लेशजन्य दुःखके भयसे कर्म नहीं छोड़ते। तथा वे आत्मामें कर्मोंका अस्तित्त्व भी नहीं देखते? जिससे कि उनके द्वारा मोहसे नियत कर्मोंका परित्याग किया जा सकता हो। सारे कर्म गुणोंके हैं? मैं कुछ भी नहीं करता ऐसा समझकर ही वे कर्मसंन्यास करते हैं? क्योंकि सब कर्मोंको मनसे त्यागकर इत्यादि वाक्योंद्वारा तत्त्वज्ञानियोंके संन्यासका प्रकार ( ऐसा ही ) बतलाया गया है। अतः जो अन्य आत्मज्ञानरहित कर्माधिकारी मनुष्य हैं जिनके द्वारा मोहपूर्वक या शारीरिक क्लेशके भयसे कर्मोंका त्याग किया जाना सम्भव है? वे ही तामस और राजस त्यागी हैं। ऐसा कहकर? आत्मज्ञानरहित कर्माधिकारियोंके कर्मफलत्यागकी स्तुति करनेके लिये? उन राजसतामस त्यागियोंकी निन्दा की जाती है। क्योंकि सर्वारम्भपरित्यागी मौनी संतुष्टो येन केनचित् अनिकेतः स्थिरमतिः इत्यादि विशेषणोंसे ( बारहवें अध्यायमें ) और गुणातीतके लक्षणोंमें भी यथार्थ संन्यासीको पृथक् करके कहा गया है? तथा,ज्ञानकी जो परानिष्ठा है इस प्रकरणमें भी यही बात कहेंगे? इसलिये यहाँ यह विवेचन ज्ञाननिष्ठ संन्यासियोंके विषयमें नहीं है। कर्मफलत्याग ( रूपसंन्यास ) ही सात्त्विकतारूप गुणसे युक्त होनेके कारण यहाँ तामसराजस त्यागकी अपेक्षा गौणरूपसे संन्यास कहा जाता है। यह ( सात्त्विक त्याग ) सर्वकर्मसंन्यासरूप मुख्य संन्यास नहीं,है। पू0 -- न हि देहभृता इत्यादि हेतुयुक्त कथनसे यह पाया जाता है कि स्वरूपसे सर्वकर्मोंका संन्यास असम्भव है? अतः कर्मफलत्याग ही मुख्य संन्यास है। उ0 -- यह कहना ठीक नहीं? क्योंकि यह हेतुयुक्त कथन कर्मफलत्यागकी स्तुतिके लिये है। जिस प्रकार पूर्वोक्त अनेक साधनोंका अनुष्ठान करनेमें असमर्थ और आत्मज्ञानरहित अर्जुनके लिये विहित होनेके कारण,त्यागाच्छान्तिरनन्तरम् यह कहना कर्मफलत्यागकी स्तुतिमात्र है। वैसे ही न हि देहभृता शक्यम् यह कहना भी कर्मफलत्यागकी स्तुतिके लिये ही है। क्योंकि सब कर्मोंको मनसे छो़ड़कर न करता हुआ और न कराता हुआ रहता है इस पक्षका अपवाद? किसीके द्वारा भी दिखलाया जाना सम्भव नहीं है। सुतरां यह संन्यास और त्यागसम्बन्धी विकल्प? कर्माधिकारियोंके विषयमें ही है। जो यथार्थ ज्ञानी सांख्ययोगी हैं? उनका केवल सर्वकर्मसंन्यासरूप ज्ञाननिष्ठामें ही अधिकार है? अन्यत्र नहीं? अतः वे विकल्पके पात्र नहीं हैं। यही सिद्धान्त हमने वेदाविनाशिनम् इस श्लोककी व्याख्यामें और तीसरे अध्यायके आरम्भमें सिद्ध किया है।'),
('shankaracharya-ht:source:18.4','Śaṅkarācārya','gita.18.4','hi','translation','।।18.4।।इन विकल्पभेदोंमें --, हे भरतवंशियोंमें श्रेष्ठतम अर्जुन उस पूर्वदर्शित त्यागके विषयमें? अर्थात् त्यागसंन्यास सम्बन्धी विकल्पोंके विषयमें? तू मेरा निश्चय सुन? अर्थात् मेरे वचनोंसे कहा हुआ तत्त्व भली प्रकार समझ। त्याग और संन्यासशब्दका जो वाच्यार्थ है वह एक ही है? इस अभिप्रायसे केवल त्यागके नामसे ही,( प्रश्नका ) उत्तर देते हैं। हे पुरुषसिंह ( उस ) त्यागका शास्त्रोंमें तामस आदि तीन प्रकारके भेदोंसे भली प्रकार निरूपण किया गया है। जिससे कि आत्मज्ञानरहित कर्माधिकारी -- कर्मी पुरुषका ही त्यागसंन्यासशब्दका वाच्यार्थ ( संन्यास ) तामस आदि भेदोंसे तीन प्रकारका होना सम्भव है? परमार्थज्ञानी नहीं यह अभिप्राय समझमें आना बड़ा कठिन है? इसलिये इस विषयमें यथार्थ तत्त्व बतलानेको दूसरा कोई समर्थ नहीं है? अतः तू मुझ ईश्वरका शास्त्रोंके यथार्थ अभिप्रायसे युक्त निश्चय सुन।'),
('shankaracharya-ht:source:18.5','Śaṅkarācārya','gita.18.5','hi','translation','।।18.5।।वह निश्चय क्या है इसपर कहते हैं --, यज्ञ? दान और तप? ये तीन प्रकारके कर्म त्यागनेयोग्य नहीं हैं अर्थात् इन तीनोंका त्याग करना उचित नहीं है? इन्हें तो करना ही चाहिये क्योंकि यज्ञ? दान और तप ये तीनों बुद्धिमानोंको अर्थात् फलकामनारहित पुरुषोंको? पवित्र करनेवाले हैं।');
