INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:18.6','Śaṅkarācārya','gita.18.6','hi','translation','।।18.6।।जो पवित्र करनेवाले बतलाये गये हैं? ऐसे ये यज्ञ? दान और तपरूप कर्म भी तद्विषयक आसक्ति और फलका त्याग करके ही किये जाने चाहिये? अर्थात् आसक्ति और फलके त्यागपूर्वक ही इनका अनुष्ठान करना उचित है। यह मेरा निश्चय किया हुआ उत्तम मत है। इस विषयमें मेरा निश्चय सुन इस प्रकार प्रतिज्ञा करके और ( उनकी कर्तव्यतामें ) पावनत्वरूप हेतु बतलाकर जो ऐसा कहना है कि? ये कर्म किये जाने चाहिये यह मेरा निश्चित उत्तम मत है यह प्रतिज्ञा किये हुए विषयका उपसंहार ही है? किसी अपूर्व विषयका वर्णन नहीं है क्योंकि एतानि शब्दका आशय प्रकरणमें अत्यन्त निकटवर्ती विषयको ही लक्ष्य कराना होता है। आसक्तियुक्त और फलेच्छुक मनुष्योंके लिये यद्यपि ये ( यज्ञ? दान और तपरूप ) कर्म बन्धनके कारण हैं? तो भी मुमुक्षुको ( फलआसक्तिसे रहित होकर ) करने चाहिये? यही अपि शब्दका अभिप्राय है। यहाँ,( यज्ञ? दान और तपसे अतिरिक्त ) अन्य ( काम्य ) कर्मोंको लक्ष्य करके एतानि के साथ अपि शब्दका,प्रयोग नहीं है। कुछ अन्य टीकाकार कहते हैं कि नित्यकर्मोंके फलका अभाव होनेके कारण उनको फल और आसक्ति छोड़कर कर्तव्य बतलाना नहीं बन सकता? ( अतः ) एतान्यपि इस पदका अभिप्राय यह है कि जो नित्यकर्मोंसे अतिरिक्त काम्य कर्म है वे भी करने चाहिये? फिर यज्ञ? दान और तपरूप नित्यकर्मोंके विषयमें तो कहना ही क्या है। यह अर्थ ( करना ) ठीक नहीं क्योंकि यज्ञो दानं तपश्चैव पावनानि इत्यादि वचनोंसे नित्यकर्मोंका भी फल होता है यह सिद्ध किया गया है। नित्यकर्मोंको भी बन्धनकारक होनेकी आशङ्कासे छोड़नेकी इच्छा रखनेवाले मुमुक्षुकी प्रवृत्ति काम्यकर्मोंमें कैसे हो सकती है इसके सिवा सकाम कर्म अत्यन्त निकृष्ट हैं इस कथनमें काम्यकर्मोंकी निन्दा की जानेके कारण और,यथार्थ कर्मके अतिरिक्त अन्य कर्म बन्धन कारक हैं इस कथनसे काम्यकर्म बन्धनकारक माने जानेके कारण? एवं वेद त्रिगुणात्मक (संसार) को विषय करनेवाले हैं तीनों वेदोंको जाननेवाले सोमरस पीनेवाले पुण्य क्षीण होनेपर मृत्युलोकमें आ जाते हैं ऐसा कहा जानेके कारण और साथ ही काम्यकर्मोंका विषय बहुत दूर व्यवधानयुक्त होनेके कारण भी ( यह सिद्ध होता है कि ) एतान्यपि यह कथन काम्यकर्मोंके विषयमें नहीं है।'),
('shankaracharya-ht:source:18.7','Śaṅkarācārya','gita.18.7','hi','translation','।।18.7।।अतः आत्मज्ञानरहित कर्माधिकारी मुमुक्षुके लिये --, विहित -- नित्यकर्मोंका संन्यास यानी परित्याग करना नहीं बन सकता? क्योंकि अज्ञानीके लिये नित्यकर्म शुद्धिके हेतु माने गये हैं। अतः मोहसे अज्ञानपूर्वक ( किया हुआ ) उन नित्यकर्मोंका परित्याग ( तामस कहा गया है )। नियत अवश्य कर्तव्यको कहते हैं? फिर उसका त्याग किया जाना अत्यन्त विरुद्ध है? अतः यह मोहनिमित्तक त्याग तामस कहा गया है। मोह ही तम है? यह प्रसिद्ध है।'),
('shankaracharya-ht:source:18.8','Śaṅkarācārya','gita.18.8','hi','translation','।।18.8।।तथा --, समस्त कर्म दुःखरूप हैं? ऐसा मानकर जो कोई शारीरिक क्लेशके भयसे कर्मोंको छोड़ बैठता है? वह,( ऐसा ) राजस त्याग करके? त्यागका फल अर्थात् ज्ञानपूर्वक किये हुए सर्वकर्मसंन्यासका मोक्षरूप फल? नहीं पाता।'),
('shankaracharya-ht:source:18.9','Śaṅkarācārya','gita.18.9','hi','translation','।।18.9।।तो फिर सात्त्विक त्याग कौनसा है हे अर्जुन करना चाहिये -- कर्तव्य है? ऐसा समझकर? जो नित्यकर्म आसक्ति और फल छोड़कर सम्पादन किये जाते हैं। नित्यकर्मोंका फल होता है? इस विषयमें पहले भगवान्के वचनोंका प्रमाण दे चुके हैं। अथवा यों समझो कि यद्यपि नित्यकर्मोंका फल नहीं सुना जाता है? तो भी अज्ञ मनुष्य ऐसी कल्पना कर ही लेता है कि किया हुआ नित्यकर्म अन्तःकरणकी शुद्धि या प्रत्यवायकी निवृत्तिरूप फल देता है? सुतरां फलं त्यक्त्वा इस कथनसे ऐसा कल्पनाका भी निषेध करते हैं। अतः सङ्गं त्यक्त्वा फलं च यह कहना बहुत ही उचित है। वह त्याग अर्थात् नित्यकर्मोंमें आसक्ति और फलका त्याग सात्त्विक -- सत्त्वगुणसे किया हुआ त्याग माना गया,है। पू0 -- तीन प्रकारका कर्मपरित्याग संन्यास है? यह प्रकरण है। उसमें तामस और राजस तो त्याग बतलाये गये? परंतु तीसरे ( सात्त्विक ) त्यागकी जगह ( कर्मोंका त्याग न कहकर ) आसक्ति और फलका त्याग कैसे कहते हैं जैसे कोई कहे कि तीन ब्राह्मण आये हैं? उनमें दो तो वेदके छहों अङ्गोंको जाननेवाले हैं और तीसरा क्षत्रिय है? उसीके समान यह कथन भी प्रकरणविरुद्ध है। उ0 -- यह दोष नहीं है क्योंकि त्यागमात्रकी समानतासे कर्मफलत्यागकी स्तुतिके लिये ऐसा कहा है। कर्मसंन्यासकी और फलासक्तिके त्यागकी? त्यागमात्रमें तो समानता है ही। उनमें ( स्वरूपसे ) कर्मोंके त्यागको राजस और तामस त्याग बतलाकर उसकी निन्दा करके? स त्यागः सात्त्विको मतः इस कथनसे कर्मफल और आसक्तिके त्यागको सात्त्विक त्याग बतलाकर उसकी स्तुति की जाती है। जो अधिकारी? आसक्ति और फलवासना छोड़कर नित्यकर्म करता है? उसका फलासक्ति आदि दोषोंसे दूषित न किया हुआ अन्तःकरण? नित्यकर्मोंके अनुष्ठानद्वारा संस्कृत होकर विशुद्ध हो जाता है।'),
('shankaracharya-ht:source:18.10','Śaṅkarācārya','gita.18.10','hi','translation','।।18.10।।विशुद्ध और प्रसन्न अन्तःकरण ही आध्यात्मिक विषयकी आलोचनामें समर्थ होता है। अतः इस प्रकार नित्यकर्मोंके अनुष्ठानसे जिसका अन्तःकरण विशुद्ध हो गया है एवं जो आत्मज्ञानके अभिमुख है? उसकी उस आत्मज्ञानमें जिस प्रकार क्रमसे स्थिति होती है? वह कहनी है? इसलिये कहते हैं --, अकुशल -- काम्यकर्मोंसे ( वह ) द्वेष नहीं करता अर्थात् काम्यकर्म पुनर्जन्म देनेवाले होनेके कारण संसारके कारण हैं? इनसे मुझे क्या प्रयोजन है? इस प्रकार उससे द्वेष नहीं करता। कुशलशुभनित्यकर्मोंमें आसक्त नहीं होता। अर्थात् अन्तःकरणकी शुद्धि? ज्ञानकी उत्पत्ति और उसमें स्थितिके हेतु होनेसे नित्यकर्म मोक्षके कारण हैं? इस प्रकार उनमें आसक्त नहीं होता। यानी उनमें भी अपना कोई प्रयोजन न देखकर प्रीति नहीं करता। वह कौन है त्यागी? जो कि पूर्वोक्त आसक्ति और फलके त्यागसे सम्पन्न है अर्थात् कर्मोंमें आसक्ति और उनका फल छोड़कर नित्यकर्मोंका अनुष्ठान करनेवाला है? ऐसा त्यागी। ऐसा पुरुष किस अवस्थामें? काम्यकर्मोंसे द्वेष नहीं करता और नित्यकर्मोंमें आसक्त नहीं होता सो कहते हैं -- जब कि वह सात्त्विक भावसे युक्त होता है। अर्थात् आत्मअनात्मविषयक विवेकज्ञानके हेतुस्वरूप सत्त्वगुणसे भरपूर -- भली प्रकार व्याप्त होता है। इसीलिये वह मेधावी है अर्थात् आत्मज्ञानरूप बुद्धिसे युक्त है। मेधावी होनेके कारण ही छिन्नसंशय है -- अविद्याजनित संशयसे रहित है। अर्थात् आत्मस्वरूपमें स्थित हो जाना ही परम कल्याणका साधन है? और कुछ नहीं? इस निश्चयके कारण संशयरहित हो चुका है। जो अधिकारी पुरुष? पूर्वोंक्त प्रकारसे कर्मयोगके अनुष्ठानद्वारा क्रमसे विशुद्धान्तःकरण होकर? जन्मादि विकारोंसे रहित और क्रियारहित आत्माको भली प्रकार अपना स्वरूप समझ गया है? वह समस्त कर्मोंको मनसे त्यागकर न कुछ करता और न कराता हुआ रहनेवाला ( आत्मज्ञानी ) निष्कर्मतारूप ज्ञाननिष्ठाको भोगता है। इस प्रकार इस श्लोकद्वारा यह पूर्वोक्त कर्मयोगका फल बतलाया गया है।'),
('shankaracharya-ht:source:18.11','Śaṅkarācārya','gita.18.11','hi','translation','।।18.11।।परंतु जो पुरुष कर्माधिकारी है और शरीरमें आत्माभिमान रखनेवाला होनेके कारण देहधारी अज्ञानी है? आत्मविषयक कर्तृत्वज्ञान नष्ट न होनेके कारण जो मैं करता हूँ ऐसी निश्चित बुद्धिवाला है उससे कर्मका अशेष त्याग होना असम्भव होनेके कारण? उसका कर्मफलत्यागके सहित विहित कर्मोंके अनुष्ठानमें ही अधिकार है? उनके त्यागमें नहीं। यह अभिप्राय दिखलानेके लिये कहते हैं --, देहधारीदेहको धारण करे सो देहधारी? इस व्युत्पत्तिके अनुसार शरीरमें आत्माभिमान रखनेवाला देहभृत् कहा जाता है? विवेकी नहीं। क्योंकि वेदाविनाशिनम् इत्यादि श्लोकोंसे वह ( विवेकी ) कर्तापनके अधिकारसे अलग कर दिया गया है। अतः ( यह अभिप्राय समझना चाहिये कि ) जिस कारण उस देहधारीअज्ञानीसे समस्त कर्मोंका पूर्णतया त्याग किया जाना सम्भव नहीं है? इसलिये जो तत्त्वज्ञानरहित अधिकारी? नित्यकर्मोंका अनुष्ठान करता हुआ उन कर्मोंके फलका त्यागी है? अर्थात् कर्मफलकी वासनामात्रको छोड़नेवाला है? वह कर्म करनेवाला होनेपर भी स्तुतिके अभिप्रायसे त्यागी कहा जाता है। सुतरां यह सिद्ध हुआ कि देहात्माभिमानसे रहित परमार्थज्ञानीके द्वारा ही निःशेषभावसे कर्मसंन्यास किया जा सकता है।'),
('shankaracharya-ht:source:18.12','Śaṅkarācārya','gita.18.12','hi','translation','।।18.12।।सर्व कर्मोंका त्याग करनेसे जो फल होता है? वह क्या है इसपर कहते हैं? --, अनिष्ट -- नरक और पशुपक्षी आदि योनिरूप इष्ट -- देवयोनिरूप तथा मिश्र -- इष्ट और अनिष्टमिश्रित मनुष्ययोनिरूप? इस प्रकार यह पुण्यपापरूप कर्मोंका फल तीन प्रकारका होता है। जो पदार्थ बाह्य कर्ता? कर्म? क्रिया आदि अनेक कारकोंद्वारा निष्पन्न हुआ हो और बाजीगरकी मायाके समान? अविद्याजनित? महामोहकारक हो? एवं जीवात्माके आश्रितसा प्रतीत होता हो और साररहित होनेके कारण तत्काल ही लय -- नष्ट हो जाताहो? उसका नाम फल है। यह फल शब्दकी व्याख्या है। ऐसा यह तीन प्रकारका फल? अत्यागियोंको अर्थात् परमार्थसंन्यास न करनेवाले कर्मनिष्ठ अज्ञानियोंको ही? मरनेके पीछे मिलता है। केवल ज्ञाननिष्ठामें स्थित परमहंसपरिव्राजक वास्तविक संन्यासियोंको? कभी नहीं मिलता। क्योंकि ( वे ) केवल सम्यग्ज्ञाननिष्ठ पुरुष? संसारके बीजरूप अविद्यादि दोषोंका मूलोच्छेद नहीं करते? ऐसा कभी नहीं हो सकता।'),
('shankaracharya-ht:source:18.13','Śaṅkarācārya','gita.18.13','hi','translation','।।18.13।।इसलिये क्रिया? कारक और फल आदि आत्मामें अविद्यासे आरोपित होनेके कारण परमार्थदर्शी,( आत्मज्ञानी ) ही सम्पूर्ण कर्मोंका अशेषतः त्यागी हो सकता है। कर्म करनेवाले अधिष्ठान ( शरीर ) कर्ताक्रिया आदि कारकोंको? आत्मभावसे देखनेवाला अज्ञानी? सम्पूर्ण कर्मोंका अशेषतः त्याग नहीं कर सकता। यह बात अगले श्लोकसे दिखलाते हैं -- हे महाबाहो इनआगे कहे जानेवाले पाँच कारणोंको अर्थात् कर्मके साधनोंको? तू मुझसे जान। अगले उपदेशमें अर्जुनके चित्तको लगानेके लिये और अधिष्ठानादिके ज्ञानकी कठिनता दिखानेके लिये? उन पाँचों कारणोंको जाननेयोग्य बतलाकर? उनकी स्तुति करते हैं। जिस शास्त्रमें जाननेयोग्य पदार्थोंकी संख्या ( गणना ) की जाय उसका नाम सांख्य अर्थात् वेदान्त है। कृतान्त भी उसीका विशेषण है। कृत कर्मको कहते हैं ? जहाँ उसका अन्त अर्थात् जहाँ कर्मोंकी समाप्ति हो जाती है वह कृतान्त है -- यानी कर्मोंका अन्त है। यावानर्थ उदपाने सर्व कर्माखिलं पार्थ ज्ञाने,परिसमाप्यते इत्यादि वचन भी आत्मज्ञान उत्पन्न होनेपर समस्त कर्मोंकी निवृत्ति दिखलाते हैं। इसलिये ( कहते हैं कि ) उस आत्मज्ञानप्रद कृतान्त -- सांख्यमें यानी वेदान्तशास्त्रमें समस्त कर्मोंकी सिद्धिके लिये कहे हुए ( उन पाँच कारणोंको तू मुझसे सुन )।,'),
('shankaracharya-ht:source:18.14','Śaṅkarācārya','gita.18.14','hi','translation','।।18.14।।वे ( पाँच कारण ) कौनसे हैं सो बतलाते हैं --, अधिष्ठान -- इच्छाद्वेष? सुखदुःख और ज्ञान आदिकी अभिव्यक्तिका आश्रय शरीर? कर्ता -- उपाधिस्वरूप भोक्ता जीव? भिन्नभिन्न प्रकारके कारण -- शब्दादि विषयोंको ग्रहण करनेवाले श्रोत्रादि अलगअलग बारह करण? नाना प्रकारकी चेष्टाएँ -- श्वासप्रश्वास आदि अलगअलग वायुसम्बन्धी क्रियाएँ और इन चारोंके साथ पाँचवाँ -- पाँचकी संख्याको पूर्ण करनेवाला कारण दैव है। अर्थात् चक्षु आदि इन्द्रियोंके अनुग्राहक सूर्यादि देव हैं।'),
('shankaracharya-ht:source:18.15','Śaṅkarācārya','gita.18.15','hi','translation','।।18.15।।मन? वाणी और शरीरसे अर्थात् इन तीनोंके द्वारा मनुष्य जो कुछ न्याययुक्त -- धर्ममयशास्त्रीय अथवा धर्मविरुद्ध -- अशास्त्रीय कर्म करता है? उन सबके ये उपर्युक्त पाँच हेतु यानी कारण हैं। जीवनके लिये जो कुछ आँख खोलनेमूँदने आदिकी भी चेष्टाएँ की जाती हैं? वे भी? पहले किये हुए पुण्य और पापका ही परिणाम हैं। अतः न्याय और विपरीत ( अन्याय ) के ग्रहणसे ऐसी समस्त चेष्टाओंका भी ग्रहण हो जाता,है। पू0 -- जब कि अधिष्ठानादि ही समस्त कर्मोंके कारण हैं? तब यह कैसे कहा जाता है कि मन? वाणी और शरीरसे कर्म करता है उ0 -- यह दोष नहीं है। विहित और निषेधरूप सारे कर्म शरीर? वाणी और मन इन्हीं तीनोंकी प्रधानतासे होनेवाले हैं? तथा देखनासुनना आदि जीवननिमित्तक चेष्टाएँ भी उन्हीं कर्मोंकी अङ्गभूत हैं? इसलिये समस्त कर्मोंको तीन भागोंमें बाँटकर ऐसा कहते हैं कि जो कुछ भी शरीर आदिद्वारा कर्म करता है ( क्योंकि ) फलभोगके समय भी शरीर आदि प्रधान कारणोंद्वारा ही फल भोगा जाता है। सुतरां उपर्युक्त अधिष्ठानादि पाँच कारणोंकी हेतुता ठीक है? इसमें विरोध नहीं है।'),
('shankaracharya-ht:source:18.16','Śaṅkarācārya','gita.18.16','hi','translation','।।18.16।।तत्र शब्द प्रकरणसे सम्बन्ध जोड़ता है। ऐसा होनेसे? यानी पहले बतलाये हुए पाँच कारणोंद्वारा ही समस्त कर्म सिद्ध होते हैं? इसलिये? जो अज्ञानी पुरुष? वेदान्त और आचार्यके उपदेशद्वारा तथा तर्कद्वारा संस्कृतबुद्धि न होनेके कारण? उन अधिष्ठानादि पाँचों कारणोंके साथ अविद्यासे आत्माकी एकता मानकर? उनके द्वारा किये हुए कर्मोंका मैं ही कर्ता हूं इस प्रकार केवलशुद्ध आत्माको ( उन कर्मोंका ) कर्ता समझता है? ( वह वास्तवमें कुछ भी नहीं समझता )। तथा आत्माको शरीरादिसे अलग माननेवाला भी? जो शरीरादिसे अलग केवल आत्माको ही कर्ता समझता है? वह भी अकृतबुद्धि ही है। अतः असंस्कृतबुद्धि होनेके कारण वह भी वास्तवमें आत्माका या कर्मका तत्त्व नहीं समझता? यह अभिप्राय है। इसलिये वह दुर्बुद्धि है। जिसकी बुद्धि कुत्सित? विपरीत? दुष्ट और बारम्बार जन्ममरण देनेमें कारणरूप हो उसे दुर्बुद्धि कहते हैं ऐसा मनुष्य देखता हुआ भी वास्तवमें नहीं देखता। जैसे तिमिररोगवाला अनेक चन्द्र देखता है? या जैसे बालक दौड़ते हुए बादलोंमें चन्द्रमाको दौड़ता हुआ देखता है? अथवा जैसे ( पालकी आदि ) किसी सवारीपर चढ़ा हुआ मनुष्य दूसरोंके चलनेमें अपना चलना समझता है ( वैसे ही उसका समझना है )।'),
('shankaracharya-ht:source:18.17','Śaṅkarācārya','gita.18.17','hi','translation','।।18.17।।तो फिर जो वास्तवमें देखता है ( ऐसा ) सुबुद्धि कौन है इसपर कहते हैं --, शास्त्र और आचार्यके उपदेशसे तथा न्यायसे जिसका अन्तःकरण भली प्रकार शुद्धसंस्कृत हो गया है? ऐसे जिस पुरुषके अन्तःकरणमें मैं कर्ता हूँ इस प्रकारकी भावनाप्रतीति नहीं होती? जो ऐसा समझता है कि,अविद्यासे आत्मामें अध्यारोपित? ये अधिष्ठानादि पाँच हेतु ही समस्त कर्मोंके कर्ता हैं? मैं नहीं हूँ? मैं तो केवल उनके व्यापारोंका साक्षीमात्र प्राणोंसे रहित? मनसे रहित? शुद्ध श्रेष्ठ? अक्षरसे भी पर केवल और अक्रिय आत्मस्वरूप हूँ। तथा जिसकी बुद्धि यानी आत्माका उपाधिस्वरूप अन्तःकरण? लिप्त नहीं होता -- अनुताप नहीं करता? यानी,मैंने अमुक कार्य किया है उससे मुझे नरकमें जाना पड़ेगा इस प्रकार जिसकी बुद्धि लिप्त नहीं होती वह सुबुद्धि है वही वास्तवमें देखता है। ऐसा ज्ञानी इन समस्त लोकोंको अर्थात् सब प्राणियोंको मारकर भी ( वास्तवमें ) नहीं मारता अर्थात् हननक्रिया नहीं करता और उसके परिणामसे अर्थात् पापके फलसे भी नहीं बँधता। पू0 -- यद्यपि यह ( ज्ञानकी ) स्तुति है? तो भी यह कहना सर्वथा विपरीत है कि मारकर भी नहीं मारता,। उ0 -- यह दोष नहीं है? क्योंकि लौकिक और पारमार्थिक इन दो दृष्टियोंकी अपेक्षासे ऐसा कहना बन सकता है। शरीर आदिमें आत्मबुद्धि करके मैं मारनेवाला हूँ ऐसा माननेवाले लौकिक मनुष्योंकी दृष्टिका आश्रय लेकर मारकर भी यह कहा है और पूर्वोक्त पारमार्थिक दृष्टिका आश्रय लेकर न मारता है और न बँधता है यह कहा है। इस प्रकार ये दोनों कथन बन सकते हैं। पू0 -- कर्तारमात्मानं केवलं तु इस कथनमें केवलशब्दका प्रयोग होनेसे यह पाया जाता है कि आत्मा,( अकेला कर्म नहीं करता? पर ) अधिष्ठान आदि अन्य हेतुओंके साथ सम्मिलित होकर निःसंदेह कर्म करता है। उ0 -- यह दोष नहीं है? क्योंकि अविक्रियस्वभाववाला होनेके कारण? आत्माका अधिष्ठानादिसे संयुक्त होना नहीं बन सकता। विकारवान् वस्तुका ही अन्य पदार्थोंके साथ संघात हो सकता है और विकारी पदार्थ ही संहत होकर कर्ता बन सकता है। निर्विकार आत्माका? न तो किसीके साथ संयोग हो सकता है और न संयुक्त होकर उसका कर्तृत्व ही बन सकता है। इसलिये ( यह समझना चाहिये कि ) आत्माका केवलत्व स्वाभाविक है? अतः यहाँ केवल शब्दका अनुवादमात्र किया गया है। आत्माका अविक्रियत्व श्रुतिस्मृति और न्यायसे प्रसिद्ध है। गीतामें भी यह विकाररहित कहलाता है,सब कर्म गुणोंसे ही किये जाते हैं आत्मा शरीरमें स्थित हुआ भी नहीं करता इत्यादि वाक्योंद्वारा अनेक बार प्रतिपादित है और मानो ध्यान करता है? मानो चेष्टा करता है इस प्रकारकी श्रुतियोंमें भी प्रतिपादित है। तथा न्यायसे भी यही सिद्ध होता है? क्योंकि आत्मतत्त्व अवयवरहित? स्वतन्त्र और विकाररहित है। ऐसा मानना ही राजमार्ग है। यदि आत्माको विकारवान् मानें तो भी इसका स्वकीय विकार ही अपना हो सकता है। अधिष्ठानादिके किये हुए कर्म आत्मकर्तृक नहीं हो सकते क्योंकि अन्यके कर्मोंको बिना किये ही अन्यके पल्ले बाँध देना उचित नहीं है। जो अविद्यासे आरोपित किये जाते हैं? वे वास्तवमें उसके नहीं होते। जैसे सीपमें आरोपित चाँदीपन सीपका नहीं होता एवं जैसे मूर्खोंद्वारा आकाशमें आरोपित की हुई तलमलीनता आकाशकी नहीं हो सकती? वैसे ही अधिष्ठानादि पाँच हेतुओंके विकार भी उनके ही हैं? आत्माके नहीं। सुतरां यह ठीक ही कहा है कि मैं कर्ता हूँ ऐसी भावनाका और बुद्धिके लेपका अभाव होनेके कारण? पूर्ण ज्ञानी न मारता है और न बँधता है। दूसरे अध्यायमें यह आत्मा न मारता है और न मारा जाता है इस प्रकार प्रतिज्ञा करके? न जायते इत्यादि हेतुयुक्त वचनोंसे आत्माका अविक्रियत्व बतलाकर? फिर वेदाविनाशिनम् इस श्लोकसे उपदेशके आदिमें विद्वान्के लिये संक्षेपमें कर्माधिकारकी निवृत्ति कहकर? जगहजगह? प्रसङ्ग लाकर बीचबीचमें जिसका विस्तार किया गया है? ऐसी कर्माधिकारकी निवृत्तिका? अब शास्त्रके अर्थका संग्रह करनेके लिये विद्वान् न मारता है और न बँधता है इस कथनसे उपसंहार करते हैं। सुतरां यह सिद्ध हुआ कि विद्वान्में देहधारीपनका अभिमान न होनेके कारण उसके अविद्याकर्तृक समस्त कर्मोंका संन्यास हो सकता है? इसलिये संन्यासियोंको अनिष्ट आदि तीन प्रकारके कर्मफल नहीं मिलते। साथ ही यह भी अनिवार्य है कि दूसरे ( कर्माधिकारी ) इससे विपरीत होते हैं। इस कारण उनको तीन प्रकारके कर्मफल ( अवश्य ) मिलते हैं। इस प्रकार यह गीताशास्त्रके अर्थका उपसंहार किया गया। ऐसा यह समस्त वेदोंके अर्थका सार? निपुणबुद्धिवाले पण्डितोंद्वारा विचारपूर्वक धारण किया जाने योग्य है। इस विचारसे हमने जगहजगह प्रकरणोंका विभाग करके? शास्त्रन्यायानुसार इस तत्त्वको दिखलाया है।।17।।'),
('shankaracharya-ht:source:18.18','Śaṅkarācārya','gita.18.18','hi','translation','।।18.18।।इस प्रकार शास्त्रके आशयका उपसंहार करके अब कर्मोंका प्रवर्तक बतलाया जाता है --, ज्ञान -- जिसके द्वारा कोई पदार्थ जाना जाय। यहाँ ज्ञान शब्दसे सामान्यभावसे सर्व पदार्थविषयक ज्ञान कहा गया है। वैसे ही ज्ञेय अर्थात् जाननेमें आनेवाला पदार्थ? यह भी सामान्य भावसे समस्तका ही वर्णन है। तथा परिज्ञाता अर्थात् उपाधियुक्त अविद्याकल्पित भोक्ता? इस प्रकार जो यह इन तीनोंका समुदाय है? यही सामान्यभावसे समस्त कर्मोंकी प्रवर्तक तीन प्रकारकी कर्मचोदना है। क्योंकि उक्त ज्ञान आदि तीनोंके सम्मिलित होनेपर ही त्याग और ग्रहण आदि जिनके प्रयोजन हैं? ऐसे समस्त कर्मोंका आरम्भ होता है। अब अधिष्ठानादि पाँच हेतुओंसे जिसकी उत्पत्ति है तथा मन? वाणी और शरीररूप आश्रयोंके भेदसे जिसके तीन वर्ग किये गये हैं? ऐसे समस्त कर्म? करण आदि तीन कारकोंमें संगृहीत हैं। यह बात बतलायी जाती है -- करण -- जिसके द्वारा कर्म किया जाय? अर्थात् श्रोत्रादि दस बाह्य इन्द्रियाँ और बुद्धि आदि चार,अन्तःकरण। कर्म -- जो कर्ताका अत्यन्त इष्ट हो और क्रियाद्वारा सम्पादन किया जाय। कर्ता -- श्रोत्रादि करणोंको अपनेअपने व्यापारमें नियुक्त करनेवाला उपाधिस्वरूप जीव। इस प्रकार यह त्रिविध कर्मसंग्रह है। जिनमें कुछ संगृहीत किया जाय उसका नाम संग्रह है? अतः कर्मोंके संग्रहका नाम कर्मसंग्रह है क्योंकि इन तीन कारकोंमें ही कर्म संगृहीत है। इसलिये यह तीन प्रकारका कर्मसंग्रह है।'),
('shankaracharya-ht:source:18.19','Śaṅkarācārya','gita.18.19','hi','translation','।।18.19।।क्रिया? कारक और फल सभी त्रिगुणात्मक हैं? अतः सत्त्व? रज और तम इन तीनों गुणोंके भेदसे उन सबका त्रिविध भेद बतलाना है। सो आरम्भ करते हैं --, यहाँ कर्म शब्दका अर्थ क्रिया है? कर्ताका अत्यन्त इष्ट पारिभाषिक शब्द कारकरूप कर्म नहीं। ज्ञान? कर्म और कर्ता अर्थात् क्रिया करनेवाला -- ये तीनों ही? गुणोंकी संख्या करनेवाले शास्त्रोंमें अर्थात् कपिलमुनिप्रणीत शास्त्रमें गुणोंके भेदसे यानी सात्त्विक आदि भेदसे? प्रत्येक तीनतीन प्रकारके बतलाये गये हैं। यहाँ त्रिधाके साथ एव शब्द जोड़कर यह आशय प्रकट किया गया है? कि उक्त तीनों पदार्थ गुणोंसे अतिरिक्त अन्य जातिके नहीं हैं। वह गुणोंकी संख्या करनेवाला कापिलशास्त्र यद्यपि परमार्थब्रह्मकी एकताके विषयमें (भगवान्के सिद्धान्तसे) विरुद्ध है तो भी गुणोंके भोक्ता ( जीव ) के विषयमें तो प्रमाण है ही। वे कापिलसांख्यके अनुयायी? गुण और गुणके व्यापारका निरूपण करनेमें निपुण हैं। इसलिये उनका शास्त्र भी आगे कहे हुए अभिप्रायकी स्तुति करनेके लिये प्रमाणरूपसे ग्रहण किया जाता है? सुतरां कोई विरोध नहीं है। उनको अर्थात् ज्ञान? कर्म और कर्ताको तथा गुणोंके अनुसार किये हुए उनके सात्त्विक आदि समस्त भेदोंको? तू यथावत् -- जैसा शास्त्रमें न्यायानुसार कहा है उसी प्रकार सुन अर्थात् आगे कही जानेवाली बातमें चित्त लगा।'),
('shankaracharya-ht:source:18.20','Śaṅkarācārya','gita.18.20','hi','translation','।।18.20।।पहले ( तीन श्लोकोंद्वारा ) ज्ञानके तीन भेद कहे जाते हैं। जिस ज्ञानके द्वारा मनुष्य? अव्यक्तसे लेकर स्थावरपर्यन्त समस्त भूतोंमें एकभाव -- एक आत्मवस्तु? जो कि अपने स्वरूपसे या धर्मसे कभी क्षय नहीं होता? ऐसा अविनाशी और कूटस्थ नित्यतत्त्व देखता है। यहाँ भाव शब्द वस्तुवाचक है। तथा ( जिस ज्ञानके द्वारा ) उस आत्मतत्त्वको अलगअलग प्रत्येक शरीरमें विभागरहित अर्थात् आकाशके समान समभावसे स्थित देखता है? उस ज्ञानको अर्थात् अद्वैतभावसे आत्मसाक्षात्कार कर लेनेको तू सात्त्विक ज्ञान पूर्ण ज्ञान जान। जो द्वैतदर्शनरूप अयथार्थ ज्ञान है? वे राजसतामस हैं? अतः वे संसारका उच्छेद करनेमें साक्षात् हेतु नहीं हैं।'),
('shankaracharya-ht:source:18.21','Śaṅkarācārya','gita.18.21','hi','translation','।।18.21।।और जो ज्ञान? सम्पूर्ण भूतोंमें भिन्नभिन्न प्रकारके भिन्नभिन्न भावोंको? आत्मासे अलग विलक्षण पृथक्रूपसे देखता है? अर्थात् प्रत्येक शरीरमें अलगअलग अपनेसे दूसरा आत्मा समझता है? उस ज्ञानको तू राजस यानी रजोगुणसे उत्पन्न हुआ जान। ज्ञानमें कर्तापन होना असम्भव है? इसलिये जो ज्ञान देखता है इसका आशय यह है कि जिस ज्ञानके द्वारा मनुष्य देखता है।'),
('shankaracharya-ht:source:18.22','Śaṅkarācārya','gita.18.22','hi','translation','।।18.22।।जो ज्ञान? किसी एक कार्यमें? शरीरमें या शरीरसे बाहर प्रतिमादिमें? सर्ववस्तुविषयक सम्पूर्ण ज्ञानकी भाँति आसक्त है? अर्थात् ( यह समझता है कि ) यह आत्मा या ईश्वर इतना ही है इससे परे और कुछ भी नहीं है? जैसे दिगम्बर जैनियोंका ( माना हुआ ) आत्मा शरीरमें रहनेवाला और शरीरके बराबर है और पत्थर या काष्ठ ( की प्रतिमा ) मात्र ही ईश्वर है? इसी प्रकार जो ज्ञान किसी एक कार्यमें ही आसक्त है। तता जो हेतुरहित -- युक्तिरहित और तत्त्वार्थसे भी रहित है। यथार्थ अर्थका नाम तत्त्वार्थ है? ऐसा तत्त्वार्थ जिस ज्ञानका ज्ञेय हो? वह ज्ञान तत्त्वार्थयुक्त होता है और जो तत्त्वार्थयुक्त न हो वह अतत्त्वार्थवत् अर्थात् तत्त्वार्थसे रहित होता है। एवं जो हेतुरहित होनेके कारण ही अल्प है अथवा अल्पविषयक होनेसे या अल्प फलवाला होनेसे अल्प है? वह ज्ञान तामस कहा गया है क्योंकि अविवेकी तामसी प्राणियोंमें ही ऐसा ज्ञान देखा जाता है।।'),
('shankaracharya-ht:source:18.23','Śaṅkarācārya','gita.18.23','hi','translation','।।18.23।।अब कर्मके तीन भेद कहे जाते हैं --, जो कर्म नियत -- नित्य है तथा सङ्ग -- आसक्तिसे रहित है और फल न चाहनेवाले पुरुषद्वारा बिना रागद्वेषके किया गया है? वह सात्त्विक कहा जाता है। जो कर्म रागसे या द्वेषसे प्रेरित होकर किया जाता है? वह रागद्वेषसे किया हुआ कहलाता है और जो उससे विपरीत है वह बिना रागद्वेषके किया हुआ है। जो कर्ता कर्मफलको चाहता है? वह कर्मफलप्रेप्सु अर्थात् कर्मफलकी तृष्णावाला होता है और जो उससे विपरीत है वह कर्मफलको न चाहनेवाला है।'),
('shankaracharya-ht:source:18.24','Śaṅkarācārya','gita.18.24','hi','translation','।।18.24।।जो कर्म? भोगरूप फलकी इच्छावाले पुरुषद्वारा या अहंकारयुक्त पुरुषद्वारा ( किया जाता है )। इस श्लोकमें साहंकारेण पद तत्त्वज्ञानकी अपेक्षासे नहीं है। तो क्या है वेदशास्त्रको जाननेवाले लौकिक निरहंकारीकी अपेक्षासे है क्योंकि जो वास्तविक निरहंकारी आत्मवेत्ता है? उसमें तो फलेच्छुकता और बहुत परिश्रमयुक्त कर्तृत्वकी आशंका ही नहीं हो सकती। सात्त्विक कर्मका भी कर्ता? आत्मतत्त्वको न जाननेवाला अहंकारयुक्त मनुष्य ही होता है? फिर राजसतामस कर्मोंके कर्ताकी तो बात ही क्या है संसारमें आत्मतत्त्वको न जाननेवाला भी? वेदशास्त्रका ज्ञाता पुरुष निरहंकारी कहा जाता है। जैसे अमुक ब्राह्मण निरहंकारी है ऐसा प्रयोग होता है। सुतरां ऐसे पुरुषकी अपेक्षासे ही इस श्लोकमें साहंकारेण वा यह वचन कहा गया है। पुनः शब्द पादपूर्ण करनेके लिये है। तथा जो कर्म बहुत परिश्रमसे युक्त है? अर्थात् करनेवाला जिसको बहुत परिश्रमसे कर पाता है? वह कर्म राजस कहा गया है।'),
('shankaracharya-ht:source:18.25','Śaṅkarācārya','gita.18.25','hi','translation','।।18.25।।अनुबन्धको -- अन्तमें होनेवाला जो परिणाम है उसे अनुबन्ध कहते हैं? उसको? क्षयकोकर्मके करनेमें जो शक्तिका या धनका क्षय होता है उसको? हिंसाकोप्राणियोंकी पीड़ाको और पौरुषको -- अमुक कर्मको मैं समाप्त कर सकता हूँ ऐसी अपनी सामर्थ्यको? इस प्रकार अनुबन्धसे लेकर पौरुषतकके इन समस्त भावोंकी अपेक्षा न करके -- इनकी परवा न करके? जो धर्म मोहसे -- अज्ञानसे आरम्भ किया जाता है? वह तामस -- तमोगुणपूर्वक किया हुआ कहा जाता है।'),
('shankaracharya-ht:source:18.26','Śaṅkarācārya','gita.18.26','hi','translation','।।18.26।।जो कर्ता मुक्तसङ्ग है -- जिसने आसक्तिका त्याग कर दिया है? जो निरहंवादी है -- जिसका मैं कर्ता हूँ ऐसे कहनेका स्वभाव नहीं रह गया है? जो धृति और उत्साहसे युक्त है -- धृति यानी धारणाशक्ति,और उत्साह यानी उद्यम -- इन दोनोंसे जो युक्त है? तथा जो किये हुए कर्मके फलकी सिद्धि होने या न होनेमें निर्विकार है। जो ऐसा कर्ता है? वह सात्त्विक कहा जाता है। जो केवल शास्त्रप्रमाणसे ही कर्ममें प्रयुक्त होता है? फलेच्छा या आसक्ति आदिसे नहीं? वह निर्विकार कहा जाता है।'),
('shankaracharya-ht:source:18.27','Śaṅkarācārya','gita.18.27','hi','translation','।।18.27।।जो कर्ता रागी है -- जिसमें राग यानी आसक्ति विद्यमान है? जो कर्मफलको चाहनेवाला है -- कर्मफलकी इच्छा रखता है? जो लोभी यानी दूसरोंके धनमें तृष्णा रखनेवाला है और तीर्थादि ( उपर्युक्त देशकाल ) में भी अपने धनको खर्च करनेवाला नहीं है। तथा जो हिंसात्मक -- दूसरोंको कष्ट पहुँचानेके स्वभाववाला? अशुचि -- बाहरी और भीतरी दोनों प्रकारका शुद्धिसे रहित और हर्षशोकसे लिप्त यानी इष्ट पदार्थकी प्राप्तिमें हर्ष एवं अनिष्टकी प्राप्ति और इष्टके वियोगमें होनेवाला शोक -- इन दोनों प्रकारके भावोंसे युक्त है? -- ऐसे पुरुषको ही कर्मोंकी सिद्धिअसिद्धिमें हर्षशोक हुआ करते हैं? अतः जो कर्ता उन दोनोंसे युक्त है? वह राजस कहा जाता है।'),
('shankaracharya-ht:source:18.28','Śaṅkarācārya','gita.18.28','hi','translation','।।18.28।।जो कर्ता अयुक्त है -- जिसका चित्त समाहित नहीं है? जो बालकके समान प्राकृत -- अत्यन्त संस्कारहीन बुद्धिवाला है? जो स्तब्ध है -- दण्डकी भाँति किसीके सामने नहीं झुकता? जो शठ अर्थात् अपनी सामर्थ्यको गुप्त रखनेवाला कपटी है? जो नैष्कृतिक -- दूसरोंकी वृत्तिका छेदन करनेमें तत्पर और आलसी है -- जिसका कर्तव्यकार्यमें भी प्रवृत्त होनेका स्वभाव नहीं है? जो विषादी -- सदा शोकयुक्त स्वभाववाला और दीर्घसूत्री है -- कर्तव्यमें बहुत विलम्ब करनेवाला है अर्थात् आज या कल कर लेनेयोग्य कार्यको महीनेभरमें भी समाप्त नहीं कर पाता? जो ऐसा कर्ता है वह तामस कहा जाता है।'),
('shankaracharya-ht:source:18.29','Śaṅkarācārya','gita.18.29','hi','translation','।।18.29।।हे धनञ्जय बुद्धिके और धृतिके भी सत्त्वादि गुणोंके अनुसार तीनतीन प्रकारके भेद तू विभागपूर्वक सम्पूर्णतासे यथावत् कहे हुए सुन। यह सूत्ररूपसे कहना है। दिग्विजयके समय अर्जुनने मनुष्योंका और देवोंका बहुतसा धन जीता था? इसलिये उसका नाम धनञ्जय हुआ।'),
('shankaracharya-ht:source:18.30','Śaṅkarācārya','gita.18.30','hi','translation','।।18.30।।जो बुद्धि? प्रवृत्तिको -- बन्धनके हेतुरूप कर्ममार्गको और निवृत्तिको -- मोक्षके हेतुरूप संन्यासमार्गको जानती है। बन्ध और मोक्षके साथ प्रवृत्ति और निवृत्तिकी समानवाक्यता है? इससे यह निश्चय होता है कि प्रवृत्ति और निवृत्तिका अर्थ कर्म मार्ग और संन्यासमार्ग ही है। तथा कर्तव्य और अकर्तव्यको -- विधि और प्रतिषेधको? यानी करनेयोग्य और न करनेयोग्यको ( भी जानती है )। यह कहना किसके सम्बन्धमें है देशकाल आदिकी अपेक्षासे जिनके दृष्ट और अदृष्ट फल होते हैं? उन कर्मोंके सम्बन्धमें। तथा जो बुद्धि भय और अभयको(जानती है )। जिससे मनुष्य भयभीत होता है? उसका नाम भय है और उससे विपरीतका नाम अभय है उन दोनोंको? यानी दृष्टादृष्टविषयक जो भय और अभय हैं उन दोनोंके कारणोंको जानता है? एवं हेतुसहित बन्धन और मोक्षको भी जानती है? हे पार्थ वह बुद्धि सात्त्विकी है। पहले जो ज्ञान कहा गया है? वह बुद्धिकी एक वृत्तिविशेष है और बुद्धि वृत्तिवाला है। धृति भी बुद्धिकी वृत्तिविशेष ही है।'),
('shankaracharya-ht:source:18.31','Śaṅkarācārya','gita.18.31','hi','translation','।।18.31।।हे पार्थ जिस बुद्धिके द्वारा मनुष्य शास्त्रविहित धर्मको और शास्त्रप्रतिषिद्ध अधर्मको? एवं पूर्वोक्त कर्तव्य और अकर्तव्यको? यथार्थरूपसे -- सर्वतोभावसे निर्णयपूर्वक? नहीं जानता? वह बुद्धि राजसी है।'),
('shankaracharya-ht:source:18.32','Śaṅkarācārya','gita.18.32','hi','translation','।।18.32।।हे पार्थ जो तमोगुणसे आवृत हुई बुद्धि अधर्मको -- निषिद्ध कार्यको? धर्म मान लेती है? यानी शास्त्रविहित मान लेती है? तथा जाननेयोग्य अन्यान्य समस्त पदार्थोंको भी? जो विपरीत ही समझती है? वह तामसी है।'),
('shankaracharya-ht:source:18.33','Śaṅkarācārya','gita.18.33','hi','translation','।।18.33।।धृति शब्दके साथ दूर पड़े हुए अव्यभिचारिणी शब्दका सम्बन्ध है। जिस अव्यभिचारिणी धृतिके द्वारा? अर्थात् सदा समाधिमें लगी हुईजिस धारणाके द्वारा? समाधियोगसे मन? प्राण और इन्द्रियोंकी सब क्रियाएँ धारण की जाती हैं? अर्थात् मन? प्राण और इन्द्रियोंकी सब चेष्टाएँ जिसके द्वारा शास्त्रविरुद्ध प्रवृत्तिसे रोकी जाती हैं? ( वह धृति सात्त्विकी है )। ( सात्त्विकी ) धृतिद्वारा धारण की हुई ( इन्द्रियाँ ) ही शास्त्रविरुद्ध विषयमें प्रवृत्त नहीं होतीं। कहनेका तात्पर्य यह है कि धारण करनेवाला मनुष्य? जिस अव्यभिचारिणी धृतिके द्वारा समाधियोगसे मन? प्राण और इन्द्रियोंकी चेष्टाओंको धारण किया करता है? हे पार्थ वह इस प्रकारकी धृति सात्त्विकी है।'),
('shankaracharya-ht:source:18.34','Śaṅkarācārya','gita.18.34','hi','translation','।।18.34।।हे अर्जुन जिस धृतिके द्वारा मनुष्य धर्म? काम और अर्थोंको धारण करता है? अर्थात् जिस धृतिद्वारा मनुष्य इन सबको मनमें अवश्यकर्तव्यरूपसे निश्चय किया करता है। तथा जिसजिस धर्म? अर्थ आदिके धारण करनेका प्रसङ्ग आता है? उसउस प्रसङ्गसे ही जो मनुष्य फल चाहनेवाला है? हे पार्थ उसकी जो धृति है वह राजसी होती है।'),
('shankaracharya-ht:source:18.35','Śaṅkarācārya','gita.18.35','hi','translation','।।18.35।।जिस धृतिके द्वारा मनुष्य स्वप्न -- निद्रा? भय -- त्रास? शोक -- दुःख और मदको नहीं छोड़ता। अर्थात् विषयसेवनको ही अपने लिये बहुत बड़ा पुरुषार्थ मानकर उन्मत्तकी भाँति मदको ही मनमें सदा कर्तव्यरूपसे समझता हुआ जो कुत्सित बुद्धिवाला मनुष्य इन सबको नहीं छोड़ता। यानी धारण ही किये रहता है। उसकी जो धृति है? वह तामसी मानी गयी है।'),
('shankaracharya-ht:source:18.36','Śaṅkarācārya','gita.18.36','hi','translation','।।18.36।।गुणभेदके अनुसार क्रियाओं और कारकोंके तीनतीन प्रकारके भेद कहे अब फलस्वरूप सुखके तीन तरहके भेद कहे जाते हैं --, हे भरतर्षभ अब तू मुझसे तीन तरहके सुखको भी सुन? अर्थात् सुननेके लिये चित्तको समाहित कर। जिस सुखमें मनुष्य अभ्याससे रमता है अर्थात् जिस सुखके अनुभवमें बारम्बार आवृत्ति करनेसे मनुष्यका प्रेम हुआ करता है और जहाँ मनुष्य ( अपने ) दुःखोंका अन्त पाता है अर्थात् जहाँ उसके सारे दुःखोंकी निःसन्देह निवृत्ति हो जाया करती है।'),
('shankaracharya-ht:source:18.37','Śaṅkarācārya','gita.18.37','hi','translation','।।18.37।।जो ऐसा सुख है? वह पहलेपहल -- ज्ञान? वैराग्य? ध्यान और समाधिके आरम्भकालमें? अत्यन्त श्रमसाध्य होनेके कारण? विषके सदृश -- दुःखात्मक होता है। परंतु परिणाममें वह ज्ञानवैराग्यादिके परिपाकसे उत्पन्न हुआ सुख? अमृतके समान है। वह आत्मबुद्धिके प्रसादसे उत्पन्न हुआ सुख? विद्वानोंद्वारा सात्त्विक बतलाया गया है। अपनी बुद्धिका नाम आत्मबुद्धि है? उसका जो जलकी भाँति स्वच्छ निर्मल हो जाना है? वह आत्मबुद्धिप्रसाद है? उससे उत्पन्न हुआ सुख आत्मबुद्धिप्रसादजन्य सुख है। अथवा? आत्मविषयक या आत्माको अवलम्बन करनेवाली बुद्धिका नाम आत्मबुद्धि है? उसके प्रसादकी अधिकतासे उत्पन्न सुख आत्मबुद्धिप्रसादसे उत्पन्न है? इसीलिये वह सात्त्विक है।'),
('shankaracharya-ht:source:18.38','Śaṅkarācārya','gita.18.38','hi','translation','।।18.38।।जो सुख विषय और इन्द्रियोंके संयोगसे उत्पन्न होता है? वह पहले -- प्रथम क्षणमें? अमृतके सदृश होता है? परंतु परिणाममें विषके समान है। अभिप्राय यह है कि बल? वीर्य? रूप? बुद्धि? मेधा? धन और उत्साहकी हानिका कारण होनेसे? तथा अधर्म और उससे उत्पन्न नरकादिका हेतु होनेसे? वह परिणाममें -- अपने उपभोगका अन्त होनेके पश्चात्? विषके सदृश होता है अतः ऐसा सुख राजस माना गया है।'),
('shankaracharya-ht:source:18.39','Śaṅkarācārya','gita.18.39','hi','translation','।।18.39।।जो सुख आरम्भमें और परिणाममें भी अर्थात् उपभोगके पीछे भी? आत्माको मोहित करनेवाला होता है तथा निद्रा? आलस्य और प्रमादसे उत्पन्न हुआ है? अर्थात् जो निद्रा? आलस्य और प्रमाद इन तीनोंसे उत्पन्न होता है? वह सुख तामस कहा गया है।'),
('shankaracharya-ht:source:18.40','Śaṅkarācārya','gita.18.40','hi','translation','।।18.40।।इसके उपरान्त अब प्रकरणका उपसंहार करनेवाला श्लोक कहा जाता है --, ऐसा कोई सत्त्व? अर्थात् मनुष्यादि प्राणी या अन्य कोई भी प्राणरहित वस्तुमात्र? पृथिवीमें? स्वर्गमें अथवा देवताओंमें भी नहीं है? जो कि इन प्रकृतिसे उत्पन्न हुए सत्त्वादि तीनों गुणोंसे मुक्त अर्थात् रहित हो। ऐसा कोई नहीं है इस पूर्वके पदसे इस वाक्यका सम्बन्ध है। क्रिया? कारक और फल ही जिसका स्वरूप है? ऐसा यह सारा संसार सत्त्व? रज और तम -- इन तीनों गुणोंका ही विस्तार है? अविद्यासे कल्पित है और अनर्थरूप है? ( पंद्रहवें अध्यायमें ) वृक्षरूपकी कल्पना करके ऊर्ध्वमूलम् इत्यादि वाक्योंद्वारा मूलसहित इसका वर्णन किया गया है। तथा यह भी कहा है कि उसको दृढ़ असङ्गशस्त्रद्वारा छेदन करके उसके पश्चात् उस परम पदको खोजना चाहिये। उसमें यह शङका होती है कि तब तो सब कुछ तीनों गुणोंका ही कार्य होनेसे संसारके कारणकी निवृत्ति नहीं हो सकती। इसलिये जिस उपायसे उसकी निवृत्ति हो? वह बतलाना चाहिये।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:18.41','Śaṅkarācārya','gita.18.41','hi','translation','।।18.41।।तथा सम्पूर्ण गीताशास्त्रका इस प्रकार उपसंहार भी किया जाना चाहिये कि परम पुरुषार्थकी सिद्धि चाहनेवालोंके द्वारा अनुष्ठान किये जानेयोग्य यह इतना ही समस्त वेद और स्मृतियोंका अभिप्राय है अतः इस अभिप्रायसे ये ब्राह्मणक्षत्रियविशाम् इत्यादि श्लोक आरम्भ किये जाते हैं --, हे परन्तप ब्राह्मण? क्षत्रिय और वैश्य -- इन तीनोंके और शूद्रोंके भी कर्म विभक्त किये हुए हैं अर्थात् परस्पर विभागपूर्वक निश्चित किये हुए हैं। ब्राह्मणादिके साथ शूद्रोंको मिलाकरसमास करके न कहनेका अभिप्राय यह है कि शूद्र द्विज न होनेके कारण वेदपठनमें उनका अधिकार नहीं है। किसके द्वारा विभक्त किये गये हैं स्वभावसे उत्पन्न हुए गुणोंके द्वारा। स्वभाव यानी ईश्वरकी प्रकृति -- त्रिगुणात्मिका माया? वह माया जिन गुणोंके प्रभवका यानी उत्पत्तिका कारण है? ऐसे स्वभावप्रभव गुणोंके द्वारा ब्राह्मणादिके? शम आदि कर्म विभक्त किये गये हैं। अथवा यों समझो कि ब्राह्मणस्वभावका कारण सत्त्वगुण है? वैसे ही क्षत्रियस्वभावका कारण सत्त्वमिश्रित रजोगुण है? वैश्यस्वभावका कारण तमोमिश्रित रजोगुण है और शूद्रस्वभावका कारण रजोमिश्रित तमोगुण है। क्योंकि उपर्युक्त चारों वर्णोंमें ( गुणोंके अनुसार ) क्रमसे शान्ति? ऐश्वर्य? चेष्टा और मूढ़ता -- ये अलगअलग स्वभाव देखे जाते हैं। अथवा यों समझो कि प्राणियोंके जन्मान्तरमें किये हुए कर्मोंके संस्कार? जो वर्तमान जन्ममें अपने कार्यके अभिमुख होकर व्यक्त हुए हैं? उनका नाम स्वभाव है। ऐसा स्वभाव जिन गुणोंकी उत्पत्तिका कारण है? वे,स्वभावप्रभव गुण हैं। गुणोंका प्रादुर्भाव बिना कारणके नहीं बन सकता। इसलिये स्वभाव उनकी उत्पत्तिका कारण है यह कहकर कारणविशेषका प्रतिपादन किया गया है। इस प्रकार स्वभावसे उत्पन्न हुए अर्थात् प्रकृतिसे उत्पन्न हुए सत्त्व? रज और तम -- इन तीनों गुणोंद्वारा अपनेअपने कार्यके अनुरूप शमादि कर्म विभक्त किये गये हैं। पू0 -- ब्राह्मणादि वर्णोंके शम आदि कर्म तो शास्त्रद्वारा विभक्त हैं? अर्थात् शास्त्रद्वारा निश्चित किये गये हैं फिर यह कैसे कहा जाता है? कि सत्त्व आदि तीनों गुणोंद्वारा विभक्त किये गये हैं उ0 -- यह दोष नहीं है? क्योंकि शास्त्रद्वारा भी ब्राह्मणादिके शमादि कर्म सत्त्वादि गुणभेदोंकी अपेक्षासे ही विभक्त किये गये हैं? बिना गुणोंकी अपेक्षासे नहीं। अतः शास्त्रद्वारा विभक्त किये हुए भी कर्म? गुणोंद्वारा विभक्त किये गये हैं? ऐसा कहा जाता है।'),
('shankaracharya-ht:source:18.42','Śaṅkarācārya','gita.18.42','hi','translation','।।18.42।।वे कर्म कौनसे हैं यह बतलाया जाता है --, जिनके अर्थकी व्याख्या पहले की जा चुकी है वे शम और दम तथा पहले कहा हुआ शारीरिकादिभेदसे तीन प्रकारका तप? एवं पूर्वोक्त ( दो प्रकारका ) शौच? क्षान्तिक्षमा? आर्जवअन्तःकरणकी सरलता तथा ज्ञान? विज्ञान और आस्तिकता अर्थात् शास्त्रके वचनोंमें श्रद्धा विश्वास -- ये सब ब्राह्मणके स्वाभाविक कर्म हैं अर्थात् ब्राह्मणजातिके कर्म हैं। जो बात स्वभावजन्य गुणोंसे कर्म विभक्त किये गये हैं इस वाक्यसे कही थी? वही यहाँ स्वभावजम् पदसे कही गयी है।'),
('shankaracharya-ht:source:18.43','Śaṅkarācārya','gita.18.43','hi','translation','।।18.43।।शौर्यशूरवीरता? तेज दूसरोंसे न दबनेका स्वभाव? धृति -- धारणाशक्ति? जिस शक्तिसे उत्साहित हुए मनुष्यका सभी अवस्थाओंमें अनवसाद ( नाश या शोकका अभाव ) होता है? दक्षता -- सहसा प्राप्त हुए बहुतसे कार्योंमें बिना घबड़ाहटके प्रवृत्त होनेका स्वभाव तथा युद्धमें न भागनाशत्रुको पीठ न दिखानेका भाव। दान -- देनेयोग्य पदार्थोंको खुले हाथ देनेका स्वभाव और ईश्वरभाव यानी जिनका शासन करना है? उनके प्रति प्रभुत्व प्रकट करना। ये सब क्षत्रियोंके कर्म अर्थात् क्षत्रियजातिके लिये विहित उनके स्वाभाविक कर्म हैं।'),
('shankaracharya-ht:source:18.44','Śaṅkarācārya','gita.18.44','hi','translation','।।18.44।।कृषि? गोरक्षा और वाणिज्य -- भूमिमें हल चलानेका नाम कृषि है? गौओंकी रक्षा करनेवाला गोरक्ष है? उसका भाव गौरक्ष्य यानी पशुओंको पालना है तथा क्रयविक्रयरूप वणिक् कर्मका नाम वाणिज्य है ये तीनों वैश्यकर्म हैं अर्थात् वैश्यजातिके स्वाभाविक कर्म हैं। वैसे ही शूद्रका भी? परिचर्यात्मक अर्थात् सेवारूप कर्म? स्वाभाविक है। जातिके उद्देश्यसे कहे हुए इन कर्मोंका भलीप्रकार अनुष्ठान किये जानेपर स्वर्गकी प्राप्तिरूप स्वाभाविक फल होता है। क्योंकि अपने कर्मोंमें तत्पर हुए वर्णाश्रमावलम्बी मरकर? परलोकमें कर्मोंका फल भोगकर? बचे हुए कर्मफलके अनुसार श्रेष्ठ देश? काल? जाति? कुल? धर्म? आयु? विद्या? आचार? धन? सुख और मेधा आदिसे युक्त? जन्म ग्रहण करते हैं इत्यादि स्मृतिवचन हैं और पुराणमें भी वर्णाश्रमियोंके लिये अलगअलग लोकप्राप्तिरूप फलभेद बतलाया गया है।'),
('shankaracharya-ht:source:18.45','Śaṅkarācārya','gita.18.45','hi','translation','।।5.10।।परंतु जो तत्त्वज्ञानी नहीं है और कर्मयोगमें लगा हुआ है ( यानी ) जो स्वामीके लिये कर्म करनेवाले नौकरकी भाँति मैं ईश्वरके लिये करता हूँ इस भावसे सब कर्मोंको ईश्वरमें अर्पण करके यहाँतक कि मोक्षरूप फलकी भी आसक्ति छोड़कर कर्म करता है। वह जैसे कमलका पत्ता जलमें रहकर भी उससे लिप्त नहीं होता वैसे ही पापोंसे लिप्त नहीं होता।'),
('shankaracharya-ht:source:18.46','Śaṅkarācārya','gita.18.46','hi','translation','।।18.46।।जिस अन्तर्यामी ईश्वरसे समस्त प्राणियोंकी प्रवृत्ति यानी उत्पत्ति या चेष्टा होती है और जिस ईश्वरसे यह सारा जगत् व्याप्त है? उस ईश्वरको प्रत्येक वर्णके लिये पहले बतलाये हुए अपने कर्मोंद्वारा पूजकर -- उसकी आराधना करके मनुष्य केवल ज्ञाननिष्ठाकी योग्यतारूप सिद्धि प्राप्त कर लेता है।'),
('shankaracharya-ht:source:18.47','Śaṅkarācārya','gita.18.47','hi','translation','।।18.47।।ऐसा होनेके कारण --, अपना गुणरहित भी धर्म? दूसरेके भली प्रकार अनुष्ठान किये हुए धर्मसे श्रेष्ठतर है। जैसे विषमें उत्पन्न हुए कीड़ेके लिये विष दोषकारक नहीं होता? उसी प्रकार स्वभावसे नियत किये हुए कर्मोंको करता हुआ मनुष्य पापको प्राप्त नहीं होता। जो बात पहले स्वभावजम् इस पदसे कही थी? वही यहाँ स्वभावनियतम् इस पदसे कही गयी है। स्वभावसे नियत कर्मका नाम स्वभावनियत है।'),
('shankaracharya-ht:source:18.48','Śaṅkarācārya','gita.18.48','hi','translation','।।18.48।।उपर्युक्त श्लोकमें यह बात कही कि स्वभावनियत कर्मोंको करनेवाला मनुष्य? विषमें जन्मे हुए कीड़ेकी भाँति पापको प्राप्त नहीं होता? तथा ( तीसरे अध्यायमें ) यह भी कहा है कि दूसरेका धर्म भयावह है और कोई भी अज्ञानी बिना कर्म किये क्षणभर भी नहीं रह सकता। इसलिये --, जो जन्मके साथ उत्पन्न हो उसका नाम सहज है। वह क्या है कर्म। हे कौन्तेय त्रिगुणमय होनेके कारण जो दोषयुक्त है? ऐसे दोषयुक्त भी अपने सहजकर्मको नहीं छोड़ना चाहिये। क्योंकि सभी आरम्भजो आरम्भ किये जाते हैं उनका नाम आरम्भ है? अतः यहाँ प्रकरणके अनुसार सर्वारम्भका तात्पर्य समस्त कर्म है। सा स्वधर्म या परधर्मरूप जो कुछ भी कर्म है? वे सभी तीनों गुणोंके कार्य हैं। अतः त्रिगुणात्मक होनेके कारण? साथ जन्मे हुए धुएँसे अग्निकी भाँति दोषसे आवृत हैं। अभिप्राय यह है कि स्वधर्म नामक सहजकर्मका परित्याग करनेसे और परधर्मका ग्रहण करनेसे भी? दोषसे छुटकारा नहीं हो सकता और परधर्म भयावह भी है तथा अज्ञानीद्वारा सम्पूर्ण कर्मोंका पूर्णतया त्याग होना सम्भव भी नहीं है सुतरां सहजकर्मको नहीं छोड़ना चाहिये। ( यहाँ यह विचार करना चाहिये कि ) क्या कर्मोंका अशेषतः त्याग होना असम्भव है? इसलिये उनका त्याग नहीं करना चाहिये? अथवा सहज कर्मका त्याग करनेमें दोष है इसलिये पू0 -- इसमें क्या सिद्ध होगा उ0 -- यदि यह बात हो कि अशेषतः त्याग होना अशक्य है? इसलिये सहजकर्मोंका त्याग नहीं करना चाहिये? तब तो यही सिद्ध होगा कि कर्मोंका अशेषतः त्याग करनेमें गुण ही है। पू0 -- यह ठीक है? परंतु यदि कर्मोंका पूर्णतया त्याग हो ही नहीं सकता ( तो फिर गुणदोषकी बात ही क्या है ) उ0 -- तो क्या सांख्यवादियोंके गुणोंकी भाँति आत्मा सदा चलनस्वभाववाला है अथवा बौद्धमतावलम्बियोंके प्रतिक्षणमें नष्ट होनेवाले ( रूप? वेदना? विज्ञान? संज्ञा और संस्काररूप ) पञ्च स्कन्धोंकी भाँति क्रिया ही कारक है इन दोनों ही प्रकारोंसे कर्मोंका अशेषतः त्याग नहीं हो सकता। हाँ? तीसरा एक पक्ष और भी है कि जब आत्मा कर्म करता है तब तो वह सक्रिय होता है और जब कर्म नहीं करता? तब वही निष्क्रिय होता है? ऐसा मान लेनेसे कर्मोंका अशेषतः त्याग भी हो सकता है। इस तीसरे पक्षमें यह विशेषता है? कि न तो आत्मा नित्य चलनस्वभाववाला माना गया है? और न क्रियाको ही कारक माना गया है? तो फिर क्या है? कि अपने स्वरूपमें स्थित द्रव्यमें ही अविद्यमान क्रिया उत्पन्न हो जाती है और विद्यमान क्रियाका नाश हो जाता है शुद्ध द्रव्य? क्रियाकी शक्तिसे युक्त होकर स्थित रहता है और वही कारक है। इस प्रकार वैशेषिकमतावलम्बी कहते हैं। पू0 -- इस पक्षमें क्या दोष है उ0 -- इसमें प्रधान दोष तो यही है कि यह मत भगवान्को मान्य नहीं है। पू0 -- यह कैसे जाना जाता है। उ0 -- इसीलिये कि भगवान् तो असत् वस्तुका कभी भाव नहीं होता इत्यादि वचन कहते हैं और वैशेषिकमतवादी असत्का भाव और सत्का अभाव मानते हैं। पू0 -- भगवान्का मत न होनेपर भी यदि न्याययुक्त हो तो इसमें क्या दोष है उ0 -- बतलाते हैं ( सुनो ) सब प्रमाणोंसे इस मतका विरोध होनेके कारण भी यह मत दोषयुक्त है। पू0 -- किस प्रकार उ0 -- यदि यह माना जाय कि द्व्यणुक आदि द्रव्य उत्पत्तिसे पहले अत्यन्त असत् हुए ही उत्पन्न हो जाते हैं और किञ्चित् काल स्थित रहकर फिर अत्यन्त ही असत् भावको प्राप्त हो जाते हैं? तब तो यही मानना हुआ कि असत् ही सत् हो जाता है अर्थात् अभाव भाव हो जाता है और भाव अभाव हो जाता है। अर्थात् ( यह मानना हुआ कि ) उत्पन्न होनेवाला अभाव? उत्पत्तिसे पहले शश -- श्रृङ्गकी भाँति सर्वथा असत् होता हुआ ही? समवायि? असमवायि और निमित्त नामक तीन कारणोंकी सहायतासे उत्पन्न होता है। परंतु अभाव इस प्रकार उत्पन्न होता है अथवा कारणकी अपेक्षा रखता है -- यह कहना नहीं बनता क्योंकि खरगोशके सींग आदि असत् वस्तुओंमें ऐसा नहीं देखा जाता। हाँ? यदि यह माना जाय कि उत्पन्न होनेवाले घटादि भावरूप हैं और वे अभिव्यक्तिके किसी कारणकी सहायतासे उत्पन्न होते हैं? तो यह माना जा सकता है। तथा असत्का सत् और सत्का असत् होना मान लेनेपर तो किसीका प्रमाणप्रमेयव्यवहारमें कहीं विश्वास ही नहीं रहेगा क्योंकि ऐसा मान लेनेसे फिर यह निश्चय नहीं होगा कि सत् सत् ही है और असत् असत् ही है। इसके सिवा वे उत्पन्न होता है इस वाक्यसे द्व्यणुक आदि द्रव्यका अपने कारण और सत्तासे सम्बन्ध होना बतलाते हैं अर्थात् उत्पत्तिसे पहले कार्य असत् होता है? फिर अपने कारणके व्यापारकी अपेक्षासे,( सहायतासे ) अपने कारणरूप परमाणुओंसे और सत्तासे समवायरूप सम्बन्धके द्वारा संगठित हो जाता है और संगठित होकर कारणसे मिलकर सत् हो जाता है। इसपर उनको बतलाना चाहिये कि असत्का कारण सत् कैसे हो सकता है और असत्का किसीके साथ सम्बन्ध भी कैसे हो सकता है क्योंकि वन्ध्यापुत्रकी सत्ता? उसका किसी सत् पदार्थके साथ सम्बन्ध अथवा उसका कारण? किसीके भी द्वारा प्रमाणपूर्वक सिद्ध नहीं किया जा सकता। पू0 -- वैशेषिकमतवादी अभावका सम्बन्ध नहीं मानते। वे तो भावरूप द्व्यणुक आदि द्रव्योंका ही अपने कारणके साथ समवायरूप सम्बन्ध बतलाते हैं। उ0 -- यह बात नहीं है क्योंकि ( उनके मतमें ) कार्यकारणका सम्बन्ध होनेसे पहले कार्यकी सत्ता नहीं मानी गयी। अर्थात् वैशेषिकमतावलम्बी कुम्हार और दण्डचक्र आदिकी क्रिया आरम्भ होनेसे पहले घट आदिका अस्तित्व नहीं मानते और यह भी नहीं मानते कि मिट्टीको ही घटादिके आकारकी प्राप्ति हुई है। इसलिये अन्तमें असत्का ही सम्बन्ध मानना सिद्ध होता है। पू0 -- असत्का भी समवायरूप सम्बन्ध होना विरुद्ध नहीं है। उ0 -- यह कहना ठीक नहीं क्योंकि वन्ध्यापुत्र आदिका किसीके साथ सम्बन्ध नहीं देखा जाता। अभावकी समानता होनेपर भी यदि कहो कि घटादिके प्रागभावका ही अपने कारणके साथ सम्बन्ध होता है? वन्ध्यापुत्रादिके अभावका नहीं? तो इनके अभावोंका भेद बतलाना चाहिये। एकका अभाव? दोका अभाव? सबका अभाव? प्रागभाव? प्रध्वंसाभाव? अन्योन्याभाव? अत्यन्ताभाव इन लक्षणोंसे कोई भी अभावकी विशेषता नहीं दिखला सकता। फिर किसी प्रकारकी विशेषता न होते हुए भी यह कहना कि घटका प्रागभाव ही कुम्हार आदिके द्वारा घटभावको प्राप्त होता है तथा उसका कपालनामक अपने कारणरूप भावसे सम्बन्ध होता है और वह सब व्यवहारके योग्य भी होता है। परंतु उसी घटका जो प्रध्वंसाभाव है? वह अभावत्वमें समान होनेपर भी सम्बन्धित नहीं होता। इस तरह प्रध्वंसादि अभावोंको किसी भी अवस्थामें व्यवहारके योग्य न मानना और केवल द्व्यणुक आदि द्रव्यनामक प्रागभावको ही उत्पत्ति आदि व्यवहारके योग्य मानना? असमञ्जसरूप ही है क्योंकि अत्यन्ताभाव और प्रध्वंसाभावके समान ही प्रागभावका भी अभावत्व है? उसमें कोई विशेषता नहीं है। पू0 -- हमने प्रागभावका भावरूप होना नहीं बतलाया है। उ0 -- तब तो तुमने भावका ही भावरूप हो जाना कहा है? जैसे घटका घटरूप हो जाना वस्त्रका वस्त्ररूप हो जाना परंतु यह भी अभावके भावरूप होनेकी भाँति ही प्रमाणविरुद्ध है। सांख्यमतावलम्बियोंका जो परिणामवाद है? उसमें अपूर्व धर्मकी उत्पत्ति और विनाश स्वीकार किया जानेके कारण? वह भी ( इस विषयमें ) वैशेषिकमतसे कुछ विशेषता नहीं रखता। अभिव्यक्ति ( प्रकट होना ) और तिरोभाव ( छिप जाना ) स्वीकार करनेसे भी? अभिव्यक्ति और तिरोभावकी विद्यमानता और अविद्यमानताका निरूपण करनेमें? पहलेकी भाँति ही प्रमाणसे विरोध होगा। इस विवेचनसे कारणका कार्यरूपमें स्थित होना ही उत्पत्ति आदि हैं ऐसा निरूपण करनेवाले मतका भी खण्डन हो जाता है। इन सब मतोंका खण्डन हो जानेपर अन्तमें यही सिद्ध होता है कि एक ही सत्य तत्त्व ( आत्मा ) अविद्याद्वारा नटकी भाँति उत्पत्ति? विनाश आदि धर्मोंसे अनेक रूपमें कल्पित होता है। यही भगवान्का अभिप्राय नासतो विद्यते भावः इस श्लोकमें बतलाया गया है क्योंकि सत्प्रत्ययका व्यभिचार नहीं होता और अन्य ( असत् ) प्रत्ययोंका व्यभिचार होता है ( अतः सत् ही एकमात्र तत्त्व है )। पू0 -- यदि ( भगवान्के मतमें ) आत्मा निर्विकार है तो ( वे ) यह कैसे कहते हैं कि अशेषतः कर्मोंका त्याग नहीं हो सकता उ0 -- शरीरइन्द्रियादिरूप गुण चाहे सत्य वस्तु हों? चाहे अविद्याकल्पित हों? जब कर्म उन्हींका धर्म है? तब आत्मामें तो वह अविद्याध्यारोपित ही है। इस कारण कोई भी अज्ञानी अशेषतः कर्मोंका त्याग क्षणभर भी नहीं कर सकता यह कहा गया है। परंतु विद्याद्वारा अविद्या निवृत्त हो जानेपर ज्ञानी तो कर्मोंका अशेषतः त्याग कर ही सकता है क्योंकि अविद्या नष्ट होनेके उपरान्त? अविद्यासे अध्यारोपित वस्तुका अंश बाकी नहीं रह सकता। ( यह प्रत्यक्ष ही है कि ) तिमिररोगसे विकृत हुई दृष्टिद्वारा अध्यारोपित दो चन्द्रमा आदिका कुछ भी अंश? तिमिररोग नष्ट हो जानेपर? शेष नहीं रहता। सुतरां सब कर्मोंको मनसे छोड़कर इत्यादि कथन ठीक ही हैं। तथा अपनेअपने कर्मोंमें लगे हुए मनुष्य संसिद्धिको प्राप्त होते हैं मनुष्य अपने कर्मोंसे उसकी पूजा करके सिद्धि प्राप्त करता है -- ये कथन भी ठीक हैं।'),
('shankaracharya-ht:source:18.49','Śaṅkarācārya','gita.18.49','hi','translation','।।18.49।।ज्ञाननिष्ठाकी योग्यताप्राप्तिरूप जो कर्मजनित सिद्धि कही गयी है? उसकी फलभूत ज्ञाननिष्ठारूप नैष्कर्म्यसिद्धि भी कही जानी चाहिये। इसलिये अगला श्लोक आरम्भ किया जाता है --, जो सर्वत्र असक्तबुद्धि है -- पुत्र? स्त्री आदि जो आसक्तिके स्थान हैं? उन सबमें जिसका अन्तःकरण आसक्तिसे -- प्रीतिसे रहित हो चुका है। जो जितात्मा है -- जिसका आत्मा यानी अन्तःकरण जीता हुआ है अर्थात् वशमें किया हुआ है। जो स्पृहारहित है -- शरीर? जीवन और भोगोंमें भी जिसकी स्पृहा -- तृष्णा नष्ट हो गयी है। जो ऐसा आत्मज्ञानी है? वह परम नैष्कर्म्यसिद्धिको ( प्राप्त करता है )। निष्क्रिय ब्रह्म ही आत्मा है यह ज्ञान होनेके कारण जिसके सर्वकर्म निवृत्त हो गये हैं वह निष्कर्मा है। उसके भावका नाम नैष्कर्म्य है और निष्कर्मतारूप सिद्धिका नाम नैष्कर्म्यसिद्धि है। अथवा निष्क्रिय आत्मस्वरूपसे स्थित होनारूप निष्कर्मताका सिद्ध होना ही नैष्कर्म्यसिद्धि है। ऐसी जो कर्मजनित सिद्धिसे विलक्षण और सद्योमुक्तिमें स्थित होनारूप उत्तम सिद्धि है? उसको संन्यासके द्वारा? यानी यथार्थ ज्ञानसे अथवा ज्ञानपूर्वक सर्वकर्मसंन्यासके द्वारा? लाभ करता है ऐसा ही कहा भी है कि सब कर्मोंको मनसे छोड़कर न करता हुआ और न करवाता हुआ रहता है।'),
('shankaracharya-ht:source:18.50','Śaṅkarācārya','gita.18.50','hi','translation','।।18.50।।पूर्वोक्त स्वधर्मानुष्ठानद्वारा ईश्वरार्चनरूप साधनसे उत्पन्न हुई? ज्ञाननिष्ठाप्राप्तिकी योग्यतारूप सिद्धिको? जो प्राप्त कर चुका है और जिसमें आत्मविषयक विवेकज्ञान उत्पन्न हो गया है? उस पुरुषको? जिस क्रमसे केवल आत्मज्ञाननिष्ठारूप नैष्कर्म्यसिद्धि मिलती है? वह ( क्रम ) बतलाना है? अतः कहते हैं --, सिद्धिको प्राप्त हुआ? अर्थात् अपने कर्मोंद्वारा ईश्वरकी पूजा करके? उसकी कृपासे उत्पन्न हुई शरीर और इन्द्रियोंकी ज्ञाननिष्ठाप्राप्तिका योग्यतारूप सिद्धिको प्राप्त हुआ पुरुष -- यह पुनरुक्ति आगे कहे जानेवाले वचनोंके साथ सम्बन्ध जो़ड़नेके लिये है। वे आगे कहे जानेवाले वचन कौनसे हैं जिनके लिये पुनरुक्ति है सो बतलाते हैं -- जिस ज्ञाननिष्ठारूप प्रकारसे ( साधक ब्रह्मको) -- परमात्माको पाता है? उस प्रकारको ? यानी ज्ञाननिष्ठाप्राप्तिके क्रमको? तू मेरे वचनोंसे निश्चयपूर्वक समझ। क्या ( उसका ) विस्तारपूर्वक ( वर्णन करेंगे ) इसपर कहते हैं कि नहीं। हे कौन्तेय समाससे अर्थात् संक्षेपसे ही? जिस क्रमसे ब्रह्मको प्राप्त होता है? उसे समझ। इस वाक्यसे जिस ब्रह्मप्राप्तिके लिये प्रतिज्ञा की थी? उसे इदंरूपसे ( स्पष्ट ) दिखानेके लिये कहते हैं कि ज्ञानकी जो परानिष्ठा है उसको सुन। अन्तिम अवधिपरिसमाप्तिका नाम निष्ठा है। ऐसी जो ब्रह्मज्ञानकी परमावधि है ( उसको सुन )। वह ( ब्रह्मज्ञानकी निष्ठा ) कैसी है जैसा कि आत्मज्ञान है। वह कैसा है जैसा आत्मा है। वह,( आत्मा ) कैसा है जैसा भगवान्ने बतलाया है तथा जैसा उपनिषद्वाक्योंद्वारा कहा गया है और जैसा न्यायसे सिद्ध है। पू0 -- ज्ञान विषयाकार होता है? परंतु आत्मा न तो कहीं भी विषय माना जाता है और न आकारवान् ही। उ0 -- किंतु आदित्यवर्ण प्रकाशस्वरूप स्वयंज्योति इस तरह आत्माका आकारवान् होना तो श्रुतिमें कहा है। पू0 -- यह कहना ठीक नहीं क्योंकि वे वाक्य तमःस्वरूपत्वका निषेध करनेके लिये कहे गये हैं। अर्थात् आत्मामें द्रव्यगुण आदिके आकारका प्रतिषेध करनेपर जो आत्माके अन्धकाररूप माने जानेकी आशङ्का होती है? उसका प्रतिषेध करनेके लिये ही आदित्यवर्णम् इत्यादि वाक्य हैं क्योंकि अरूपम् आदि वाक्योंसे विशेषतः रूपका प्रतिषेध किया गया है और इसका ( आत्माका ) रूप इन्द्रियोंके सामने नहीं ठहरता? इसको ( आत्माको ) कोई भी आंखोंसे नहीं देख सकता यह अशब्द है? अस्पर्श है इत्यादि वचनोंसे भी आत्मा किसीका विषय नहीं है? यह बात कही गयी है। सुतरां जैसा आत्मा है वैसा ही ज्ञान है यह कहना युक्तियुक्त नहीं है। तब फिर आत्माका ज्ञान कैसे होता है क्योंकि सभी ज्ञान? जिसको विषय करते हैं उसीके आकारवाले होते हैं और आत्मा निराकार है ऐसा कहा है। फिर ज्ञान और आत्मा दोनों निराकार होनेसे उसमें भावना और निष्ठा कैसे हो सकती है उ0 -- यह कहना ठीक नहीं क्योंकि आत्माका अत्यन्त निर्मलत्व? स्वच्छत्व और सूक्ष्मत्व सिद्ध है और बुद्धिका भी आत्माके सदृश निर्मलत्व आदि सिद्ध है? इसलिये उसका आत्मचैतन्यके आकारसे आभासित होना बन सकता है। बुद्धिसे आभासित मन? मनसे आभासित इन्द्रियाँ और इन्द्रियोंसे आभासित स्थूल शरीर है। इसलिये सांसारिक मनुष्य देहमात्रमें ही आत्मदृष्टि करते हैं। देहात्मवादी लोकायतिक? चेतनाविशिष्ट शरीर ही आत्मा है ऐसा कहते हैं? दूसरे? इन्द्रियोंको चेतन कहनेवाले हैं तथा कोई मनको और कोई बुद्धिको चेतन कहनेवाले हैं। कितने ही? उस बुद्धिके भी भीतर व्याप्त? अव्यक्तकोअव्याकृतसंज्ञक अविद्यावस्थ ( चिदाभास ) को आत्मरूपसे समझनेवाले हैं। बुद्धिसे लेकर शरीरपर्यन्त सभी जगह आत्मचैतन्यका आभास ही उनमें आत्माकी भ्रान्तिका कारण है। अतः ( यह सिद्ध हुआ कि ) आत्मविषयक ज्ञान विधेय नहीं है। तो क्या विधेय है नामरूप आदि अनात्मा वस्तुओंका जो आत्मामें अध्यारोप है उसकी निवृत्ति ही कर्तव्य है। आत्मचैतन्यका विज्ञान प्राप्त करना नहीं है क्योंकि ज्ञान? अविद्याद्वारा आरोपित समस्त पदार्थोंके आकारमें ही विशेषरूपसे ग्रहण किया हुआ है। यही कारण है कि विज्ञानवादी बौद्ध विज्ञानसे अतिरिक्त अन्य कोई वस्तु ही नहीं है इस प्रकार मानते हैं और उस ज्ञानको स्वसंवेद्य माननेके कारण प्रमाणान्तरकी आवश्यकता नहीं मानते। सुतरां ब्रह्ममें जो अविद्याद्वारा अध्यारोप किया गया है? उसका निराकरणमात्र कर्तव्य है। ब्रह्मज्ञानके लिये प्रयत्न कर्तव्य नहीं है क्योंकि ब्रह्म तो अत्यन्त प्रसिद्ध ही है। ब्रह्म यद्यपि अत्यन्त प्रसिद्ध? सुविज्ञेय? अति समीप और आत्मस्वरूप है तो भी वह विवेकरहित मनुष्योंको? अविद्याकल्पित नामरूपके भेदसे उनकी बुद्धि भ्रमित हो जानेके कारण? अप्रसिद्ध? दुर्विज्ञेय? अति दूर और दूसरासा प्रतीत हो रहा है। परंतु जिनकी बाह्याकार बुद्धि निवृत्त हो गयी है? जिन्होंने गुरु और आत्माकी कृपा लाभ कर ली है? उनके लिये इससे अधिक सुप्रसिद्ध? सुविज्ञेय? सुखस्वरूप और अपने समीप कुछ भी नहीं है। प्रत्यक्षउपलब्ध धर्ममय इत्यादि वाक्योंसे भी यही बात कही गयी है। कितने ही अपनेको पण्डित माननेवाले यों कहते हैं कि आत्मतत्त्व निराकार होनेके कारण उसको बुद्धि नहीं पा सकती अतः सम्यक् ज्ञाननिष्ठा दुःसाध्य है। ठीक है? जो गुरुपरम्परासे रहित हैं? जिन्होंने वेदान्तवाक्योंको ( विधिपूर्वक ) नहीं सुना है? जिनकी बुद्धि सांसारिक विषयोंमें अत्यन्त आसक्त हो रही है? जिन्होंने यथार्थ ज्ञान करानेवाले प्रमाणोंमें परिश्रम नहीं किया है? उनके लिये यही बात है। परंतु जो उनसे विपरीत हैं? उनके लिये तो? लौकिक ग्राह्यग्राहक भेदयुक्त,वस्तुओंमें सद्भाव सम्पादन करना ( इनको सत्य समझना ) अत्यन्त कठिन है क्योंकि उनको आत्मचैतन्यसे अतिरिक्त दूसरी वस्तुकी उपलब्धि ही नहीं होती। यह ठीक इसी तरह है? अन्यथा नहीं है। यह बात हम पहले सिद्ध कर आये हैं और भगवान्ने भी कहा है कि जिसमें सब प्राणी जागते हैं? ज्ञानी मुनिकी वही रात्रि है इत्यादि। सुतरां आत्मस्वरूपके अवलम्बनमें? बाह्य नानाकार भेदबुद्धिकी निवृत्ति ही कारण है क्योंकि आत्मा कभी किसीके भी लिये अप्रसिद्ध? प्राप्तव्य? त्याज्य या उपादेय नहीं हो सकता। आत्माको अप्रसिद्ध मान लेनेपर तो सभी प्रवृत्तियोंको निरर्थक मानना सिद्ध होगा। इसके सिवा न तो यह कल्पना की जा सकती है कि अचेतन शरीरादिके लिये ( सब कर्म किये जाते हैं ) और न यही कि सुखके लिये सुख है या दुःखके लिये दुःख है क्योंकि सारे व्यवहारका प्रयोजन अन्तमें आत्माके ज्ञानका विषय बन जाना है। इसलिये? जैसे अपने शरीरको जाननेके लिये अन्य प्रमाणकी अपेक्षा नहीं है? वैसे ही आत्मा उससे भी अधिक अन्तरतम होनेके कारण आत्माको जाननेके लिये प्रमाणान्तरकी आवश्यकता नहीं है अतः यह सिद्ध हुआ कि विवेकियोंके लिये आत्मज्ञाननिष्ठा सुप्रसिद्ध है। जिनके मतमें ज्ञान निराकार और अप्रत्यक्ष है उनको भी? ज्ञेयका बोध ( अनुभव ) ज्ञानके ही अधीन होनेके कारण? सुखादिकी तरह ही ज्ञान अत्यन्त प्रसिद्ध है? यह मान लेना चाहिये। तथा ज्ञानको जाननेके लिये जिज्ञासा नहीं होती इसलिये भी ( यह मान लेना चाहिये कि ज्ञान प्रत्यक्ष है ) यदि ज्ञान अप्रत्यक्ष होता? तो अन्य ज्ञेय वस्तुओंकी तरह उसको भी जाननेके लिये इच्छा की जाती? अर्थात् जैसे ज्ञाता ( पुरुष ) घटादिरूप ज्ञेय पदार्थोंका ज्ञानके द्वारा अनुभव करना चाहता है? उसी तरह उस ज्ञानको भी अन्य ज्ञानके द्वारा जाननेकी इच्छा करता? परंतु यह बात नहीं है। सुतरां ज्ञान अत्यन्त प्रत्यक्ष है और इसीलिये ज्ञाता भी अत्यन्त ही प्रत्यक्ष है। अतः ज्ञानके लिये प्रयत्न कर्तव्य नहीं है? किंतु अनात्मबुद्धिकी निवृत्तिके लिये ही कर्तव्य है इसीलिये ज्ञाननिष्ठा सुसंपाद्य है।।50।।'),
('shankaracharya-ht:source:18.51','Śaṅkarācārya','gita.18.51','hi','translation','।।18.51।।वह ज्ञानकी परा निष्ठा किस प्रकार करनी चाहिये सो कहते हैं --, विशुद्ध -- कपटरहित निश्चयात्मिका बुद्धिसे संपन्न पुरुष? धैर्यसे कार्यकरणके संघातरूप आत्माको,( शरीरको ) संयम करके -- वशमें करके शब्दादि विषयोंको? अर्थात् शब्द जिनका आदि है ऐसे सभी विषयोंको छोड़कर? प्रकरणके अनुसार यहाँ यह अभिप्राय है कि केवल शरीरस्थितिमात्रके लिये जिन विषयोंकी आवश्यकता है? उनसे अतिरिक्त सुखभोगके लिये जो अधिक विषय हैं? उन सबको छोड़कर तथा शरीरस्थितिके निमित्त प्राप्त हुए विषयोंमें भी? रागद्वेषका अभाव करकेत्याग करके।'),
('shankaracharya-ht:source:18.52','Śaṅkarācārya','gita.18.52','hi','translation','।।18.52।।उसके बाद --, विविक्त देशका सेवन करनेवालाअर्थात् वन? नदीतीर? पहाड़की गुफा आदि एकान्त देशका सेवन करना ही जिसका स्वभाव है ऐसा? और हलका आहार करनेवाला होकर? एकान्तसेवन और हलका भोजन यह दोनों निद्रादि दोषोंके निवर्तक होनेसे चित्तकी स्वच्छतामें हेतु हैं? इसलिये इनका ग्रहण किया गया है। तथा मन? वाणी और शरीरको वशमें करनेवाला होकर? अर्थात् जिस ज्ञाननिष्ठ यतिके काया? मन और वाणी तीनों जीते हुए होते हैं? वह यतवाक्कायमानस होता है -- इस प्रकार सब इन्द्रियोंको कर्मोंसे उपराम करके? तथा नित्य ध्यानयोगके परायण रहता हुआ आत्मस्वरूपचिन्तनका नाम ध्यान है और आत्मामें चित्तको एकाग्र करनेका नाम योग है? यह दोनों प्रधानरूपसे जिसके कर्तव्य हों उसका नाम ध्यानयोगपरायण है? उसके साथ नित्य पदका ग्रहण मन्त्रजप आदि अन्य कर्तव्योंका अभाव दिखानेके लिये किया गया है। तथा इस लोक और परलोकके भोगोंमें तृष्णाका अभावरूप जो वैराग्य है? उसके आश्रित होकर अर्थात् सदा वैराग्यसम्पन्न होकर।'),
('shankaracharya-ht:source:18.53','Śaṅkarācārya','gita.18.53','hi','translation','।।18.53।।तथा --, अहंकार? बल और दर्पको छोड़कर शरीरइन्द्रियादिमें अहंभाव करनेका नाम अहंकार है। कामना और आसक्तिसे युक्त जो सामर्थ्य है उसका नाम बल है यहाँ शरीरादिकी साधारण सामर्थ्यका नाम बल नहीं है? क्योंकि वह स्वाभाविक है इसलिये उसका त्याग अशक्य है? हर्षके साथ होनेवाला और धर्मउल्लङ्घनका कारण जो गर्व है उसका नाम दर्प है क्योंकि स्मृतिमें कहा है कि हर्षयुक्त पुरुष दर्प करता है? दर्प करनेवाला धर्मका उल्लङ्घन किया करता है इत्यादि। तथा इच्छाका नाम काम है? द्वेषका नाम क्रोध है? इनका और परिग्रहका भी त्याग करके अर्थात् इन्द्रिय और मनमें रहनेवाले दोषोंका त्याग करनेके पश्चात् भी? शरीरधारणके प्रसङ्गसे या धर्मानुष्ठानके निमित्तसे जो बाह्य संग्रहकी प्राप्ति होती है उसका भी परित्याग करके? तथा परमहंस परिव्राजक ( संन्यासी ) होकर? एवं देहजीवनमात्रमें भी ममतारहित और इसीलिये जो शान्त -- उपरतियुक्त है? ऐसा जो सब परिश्रमोंसे रहित ज्ञाननिष्ठ यति है? वह ब्रह्मरूप होनेके योग्य होता है।'),
('shankaracharya-ht:source:18.54','Śaṅkarācārya','gita.18.54','hi','translation','।।18.54।।इस क्रमसे --, ब्रह्मको प्राप्त हुआ? प्रसन्नात्मा अर्थात् जिसको अध्यात्मप्रसाद लाभ हो चुका है ऐसा पुरुष? न शोक करता है और न आकाङ्क्षा ही करता है। अर्थात् न तो किसी पदार्थकी हानिके? या निजसम्बन्धी विगुणताके उद्देश्यसे सन्ताप करता है और न किसी वस्तुको चाहता ही है। न शोचति न काङ्क्षति इस कथनसे ब्रह्मभूत पुरुषके स्वभावका अनुवादमात्र किया गया है। क्योंकि ब्रह्मवेत्तामें अप्राप्त विषयोंकी आकाङ्क्षा बन ही नहीं सकती। अथवा न काङ्क्षति की जगह,न हृष्यति ऐसा पाठ समझना चाहिये। तथा जो सब भूतोंमें सम है अर्थात् अपने सदृश सब भूतोंमें सुख और दुःखको जो समान देखता है। इस वाक्यमें आत्माको समभावसे देखना नहीं कहा है क्योंकि वह तो भक्त्या मामभिजानाति इस पदसे आगे कहा जायगा। ऐसा ज्ञाननिष्ठ पुरुष? मुझ परमेश्वरकी भजनरूप पराभक्तिको पाता है? अर्थात् चतुर्विधा भजन्ते माम् इसमें जो चतुर्थ भक्ति कही गयी है उसको पाता है।'),
('shankaracharya-ht:source:18.55','Śaṅkarācārya','gita.18.55','hi','translation','।।18.55।।उसके बाद उस ज्ञानलक्षणा --, भक्तिसे मैं जितना हूँ और जो हूँ? उसको तत्त्वसे जान लेता है। अभिप्राय यह है कि मैं जितना हूँ? यानी उपाधिकृत विस्तारभेदसे जितना हूँ और जो हूँ? यानी वास्तवमें समस्त उपाधिभेदसे रहित? उत्तमपुरुष और आकाशकी तरह ( व्याप्त ) जो मैं हूँ? उस अद्वैत? अजर? अमर? अभय और निधनरहित मुझको तत्त्वसे जान,लेता है। फिर मुझे इस तरह तत्त्वसे जानकर तत्काल मुझमें ही प्रवेश कर जाता है। यहाँ ज्ञात्वा विशते तदनन्तरम् इस कथनसे ज्ञान और उसके अनन्तर प्रवेशक्रिया? यह दोनों भिन्नभिन्न विवक्षित नहीं हैं। तो क्या है फलान्तरके अभावका ज्ञानमात्र ही विवक्षित है क्योंकि क्षेत्रज्ञ भी तू मुझे ही समझ ऐसे कहा गया है। पू0 -- यह कहना विरुद्ध है कि ज्ञानकी जो परा निष्ठा है उससे मुझे जानता है। यदि कहो कि विरुद्ध कैसे है तो बतलाते हैं? जब ज्ञाताको जिस विषयका ज्ञान होता है? वह उसी समय उस विषयको जान लेता है? ज्ञानकी बारम्बार आवृत्ति करनारूप ज्ञाननिष्ठाकी अपेक्षा नहीं करता। इसलिये वह ( ज्ञेय पदार्थको ) ज्ञानसे नहीं जानता? ज्ञानावृत्तिरूप ज्ञाननिष्ठासे जानता है यह कहना विरुद्ध है। उ0 -- यह दोष नहीं है क्योंकि अपनी उत्पत्ति और परिपाकके हेतुओंसे युक्त एवं विरोधरहित ज्ञानका जो अपने स्वरूपानुभवमें निश्चयरूपसे पर्यवसान -- स्थित हो जाना है? उसीको निष्ठा शब्दसे कहा गया है। अभिप्राय यह है कि ज्ञानकी उत्पत्ति और परिपाकके हेतु? जो विशुद्धबुद्धि आदि और अमानित्वादि सहकारी कारण हैं? उनकी सहायतासे? शास्त्र और आचार्यके उपदेशसे उत्पन्न हुआ? जो मैं कर्ता हूँ? मेरा यह कर्म है इत्यादि कारकभेदबुद्धिजनित समस्त कर्मोंके संन्याससहित क्षेत्रज्ञ और ईश्वरकी एकताका ज्ञान है? उसका जो अपने स्वरूपके अनुभवमें निश्चयरूपसे स्थित रहना है? उसे परा ज्ञाननिष्ठा कहते हैं। वही यह ज्ञाननिष्ठा आर्त आदि तीन भक्तियोंकी अपेक्षासे चतुर्थ परा भक्ति कही गयी है। उस,( ज्ञाननिष्ठारूप ) परा भक्तिसे भगवान्को तत्त्वसे जानता है जिससे उसी समय ईश्वर और क्षेत्रज्ञविषयक भेदबुद्धि पूर्णरूपसे निवृत्त हो जाती है। इसलिये ज्ञाननिष्ठारूप भक्तिसे मुझे जानता है यह कहना विरुद्ध नहीं होता। ऐसा मान लेनेसे वेदान्त? इतिहास? पुराण और स्मृतिरूप समस्त निवृत्तिविधायक शास्त्र? सार्थक हो जाते हैं अर्थात् उन सबका अभिप्राय सिद्ध हो जाता है। आत्माको जानकर ( तीनों तरहकी एषणाओंसे ) विरक्त होकर फिर भिक्षाचरण करते हैं? पुरुषार्थका अन्तरंग साधन होनेके कारण संन्यास ही इन सब तपोंमें अधिक कहा गया है? अकेला संन्यास ही उन सबको उल्लंघन कर जाता है? कर्मोंके त्यागका नाम संन्यास है? वेदोंको तथा इस लोक और परलोकको परित्याग करके? धर्मअधर्मको छोड़ इत्यादि शास्त्रवाक्य हैं। तथा यहाँ भी ( संन्यासपरक ) बहुतसे वचन दिखाये गये हैं। उन सब वचनोंको व्यर्थ मानना उचित नहीं और अर्थवादरूप मानना भी ठीक नहीं क्योंकि वे अपने प्रकरणमें स्थित हैं। इसके सिवा अन्तरात्माके अविक्रियस्वरूपमें निश्चयरूपसे स्थित हो जाना ही मोक्ष है। इसलिये भी,( पूर्वोक्त बात ही सिद्ध होती है ) क्योंकि पूर्वसमुद्रपर जानेकी इच्छावालेका उसके प्रतिकूल पश्चिमसमुद्रपर जानेकी इच्छावालेके साथ समान मार्ग नहीं हो सकता। अन्तरात्मविषयक प्रतीतिका निरन्तरता रखनेके आग्रहका नाम ज्ञाननिष्ठा है। उसका कर्मोंके साथ रहना,( पूर्वकी ओर जानेकी इच्छावालेके लिये ) पश्चिमसमुद्रकी ओर जानेकी मार्गकी भाँति विरुद्ध है। प्रमाणवेत्ताओने उनका पर्वत और राईके समान भेद निश्चित किया है। सुतरां यह सिद्ध हुआ कि सर्वकर्मसंन्यासपूर्वक ही ज्ञाननिष्ठा करनी चाहिये।'),
('shankaracharya-ht:source:18.56','Śaṅkarācārya','gita.18.56','hi','translation','।।18.56।।अपने कर्मोंद्वारा भगवान्की पूजा करनारूप भक्तियोगकी सिद्धि? अर्थात् फल? ज्ञाननिष्ठाकी योग्यता है। जिस ( भक्तियोग ) से होनेवाली ज्ञाननिष्ठा? अन्तमें मोक्षरूप फल देनेवाली होती है? उस भगवद्भक्तियोगकी अब शास्त्राभिप्रायके उपसंहारप्रकरणमें? शास्त्रअभिप्रायके निश्चयको दृढ़ करनेके लिये स्तुति की जाती है --, सदा सब कर्मोंको करनेवाला अर्थात् निषिद्ध कर्मोंको भी करनेवाला जो मद्व्यपाश्रय भक्त है -- जिसका मैं वासुदेव ही पूर्ण आश्रय हूँ? ऐसा मुझे ही अपना सब कुछ अर्पण कर देनेवाला जो भक्त है? वह भी मुझ ईश्वरके अनुग्रहसे? विष्णुके शाश्वत -- नित्य -- अविनाशी पदको प्राप्त कर लेता है।'),
('shankaracharya-ht:source:18.57','Śaṅkarācārya','gita.18.57','hi','translation','।।18.57।।जब कि यह बात है इसलिये --, तू दृष्ट और अदृष्ट फलवाले समस्त कर्मोंको विवेकबुद्धिसे अर्थात् यत्करोषि यदश्नासि इस श्लोकमें बतलाये हुए भावसे? मुझ ईश्वरमें समर्पण करके तथा मेरे परायण होकर? अर्थात् मैं वासुदेव ही जिसका पर,( परमगति ) हूँ ऐसा होकर? मुझमें बुद्धिको स्थिर करनारूप बुद्धियोगका आश्रय लेकर -- बुद्धियोगके अनन्यशरण होकर? निरन्तर मुझमें चित्तवाला हो? अर्थात् जिसका निरन्तर मुझमें ही चित्त रहे? ऐसा हो।'),
('shankaracharya-ht:source:18.58','Śaṅkarācārya','gita.18.58','hi','translation','।।18.58।।मुझमें चित्तवाला होकर तू समस्त कठिनाइयोंको अर्थात् जन्ममरणरूप संसारके समस्त कारणोंको मेरे अनुग्रहसे तर जायगा -- सबसे पार हो जायगा। परंतु यदि तू मेरे कहे हुए वचनोंको अहंकारसे मैं पण्डित हूँ ऐसा समझकर? नहीं सुनेगाग्रहण नहीं करेगा? तो नष्ट हो जायगा -- नाशको प्राप्त हो जायगा।'),
('shankaracharya-ht:source:18.59','Śaṅkarācārya','gita.18.59','hi','translation','।।18.59।।तुझे यह भी नहीं समझना चाहिये कि मैं स्वतन्त्र हूँ? दूसरेका कहना क्यों करूँ --, जो तू अहंकारका आश्रय लेकर यह मान रहा है -- ऐसा निश्चय कर रहा है कि मैं युद्ध नहीं करूँगा सो यह तेरा निश्चय मिथ्या है क्योंकि तेरी प्रकृति -- तेरा क्षत्रियस्वभाव तुझे युद्धमें नियुक्त कर देगा।'),
('shankaracharya-ht:source:18.60','Śaṅkarācārya','gita.18.60','hi','translation','।।18.60।।क्योंकि --, हे कौन्तेय तू उपर्युक्त शूरवीरता आदि अपने स्वाभाविक कर्मोंद्वारा निबद्ध हुआ -- दृढ़तासे बँधा हुआ है? इसलिये जो कर्म तू मोहसे -- अविवेकके कारण नहीं करना चाहता है? वही कर्म विवश होकर करेगा।'),
('shankaracharya-ht:source:18.61','Śaṅkarācārya','gita.18.61','hi','translation','।।18.61।।क्योंकि --, हे अर्जुन ईश्वर अर्थात् सबका शासन करनेवाला नारायण समस्त प्राणियोंके हृदयदेशमें स्थित है। जो शुक्ल स्वच्छशुद्ध अन्तरात्मास्वभाववाला हो अर्थात् पवित्र अन्तःकरणयुक्त हो उसका नाम अर्जुन है क्योंकि,अहश्च कृष्णमहरर्जुनं च इस कथनमें अर्जुनशब्द शुद्धताका वाचक देखा गया है। वह ( ईश्वर ) कैसे स्थित है सो कहते हैं -- समस्त प्राणियोंको? यन्त्रपर आरूढ़ हुईचढ़ी हुई कठपुतलियोंकी भाँति? भ्रमाता हुआ -- भ्रमण कराता हुआ स्थित है। यहाँ इव ( भाँति ) शब्द अधिक समझना चाहिये? अर्थात् जैसे यन्त्रपर आरूढ़ कठपुतली आदिको ( खिलाड़ी ) मायासे भ्रमाता हुआ स्थित रहता है? उसी तरह ईश्वर सबके हृदयमें स्थित है? इस प्रकार इसका सम्बन्ध है।'),
('shankaracharya-ht:source:18.62','Śaṅkarācārya','gita.18.62','hi','translation','।।18.62।।हे भारत तू सर्वभावसे उस ईश्वरकी ही शरणमें जा अर्थात् संसारके समस्त क्लेशोंका नाश करनेके लिये मन? वाणी और शरीरद्वारा सब प्रकारसे उस ईश्वरका ही आश्रय ग्रहण कर। फिर उस ईश्वरके अनुग्रहसे परम -- उत्तम शान्तिको? अर्थात् उपरतिको और शाश्वत स्थानको अर्थात् मुझ विष्णुके परम नित्यधामको प्राप्त करेगा।'),
('shankaracharya-ht:source:18.63','Śaṅkarācārya','gita.18.63','hi','translation','।।18.63।।मुझ सर्वज्ञ ईश्वरने तुझसे यह गुह्यसे भी गुह्य अत्यन्त गोपनीय रहस्ययुक्त ज्ञान कहा है। इस उपर्युक्त शास्त्रको? अर्थात् ऊपर कहे हुए समस्त अर्थको पूर्णरूपसे विचारकरइसके विषयमें भलीप्रकार आलोचना करके? तेरी जैसी इच्छा हो वैसे ही कर।'),
('shankaracharya-ht:source:18.64','Śaṅkarācārya','gita.18.64','hi','translation','।।18.64।।फिर भी मैं जो कुछ कहता हूँ उसे सुन --, सर्व गुह्योंमें अत्यन्त गुह्य -- रहस्ययुक्त मेरे परम उत्तम वचन तू फिर भी सुन अर्थात् जो वचन मैंने पहले अनेक बार कहे हैं उनको तू फिरसे सुन। मैं ( जो कुछ कहूँगा वह ) भयसे अथवा स्वार्थके लिये नहीं कहूँगा किंतु तू मेरा दृढ़ ऐकान्तिक प्रिय है? यह समझकर -- केवल इसी कारणसे तेरे हितकी बात अर्थात् परम ज्ञानप्राप्तिका साधन कहूँगा क्योंकि यही साधन सब हितोंमें उत्तम हित है।'),
('shankaracharya-ht:source:18.65','Śaṅkarācārya','gita.18.65','hi','translation','।।18.65।।वे वचन कौनसे हैं सो कहते हैं --, तू मुझमें मनवाला अर्थात् मुझमें चित्तवाला हो? मेरा भक्त अर्थात् मेरा ही भजन करनेवाला हो और मेरा ही पूजन करनेवाला हो? तथा मुझे ही नमस्कार कर? अर्थात् नमस्कार भी मुझे ही किया कर। इस प्रकार करता हुआ? अर्थात् मुझ वासुदेवमें ही ( अपने ) समस्त साध्य? साधन और प्रयोजनको समर्पण करके तू मुझे ही प्राप्त होगा। इस विषयमें मैं तुझसे सत्य प्रतिज्ञा करता हूँ क्योंकि तू मेरा प्रिय है। कहनेका अभिप्राय यह है कि इस प्रकार भगवान्को सत्यप्रतिज्ञ जानकर तथा भगवान्की भक्तिका फल निःसन्देह -- ऐकान्तिक मोक्ष है -- यह समझकर? मनुष्यको केवल एकमात्र भगवान्की शरणमें ही तत्पर हो जाना चाहिये।');
--> statement-breakpoint
INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:18.66','Śaṅkarācārya','gita.18.66','hi','translation','।।18.66।।कर्मयोगनिष्ठाके परम रहस्य ईश्वरशरणागतिका उपसंहार करके? उसके पश्चात् अब कर्मयोगनिष्ठाका फलस्वरूप? समस्त वेदान्तोंमें कहा हुआ यथार्थ ज्ञान कहना है? इसलिये ( भगवान् ) बोले --, समस्त धर्मोंको? अर्थात् जितने भी धर्म हैं उन सबको? यहाँ नैष्कर्म्य ( कर्माभाव ) का प्रतिपादन करना है? इसलिये धर्म शब्दसे अधर्मका भी ग्रहण किया जाता है। जो बुरे चरित्रोंसे विरक्त नहीं हुआ धर्म और अधर्म दोनोंको छोड़ इत्यादि श्रुतिस्मृतियोंसे भी यही सिद्ध होता है। सब धर्मोंको छोड़कर -- सर्व कर्मोंका संन्यास करके? मुझ एककी शरणमें आ? अर्थात् मैं जो कि सबका आत्मा? समभावसे सर्व भूतोंमें स्थित? ईश्वर? अच्युत तथा गर्भ? जन्म? जरा और मरणसे रहित हूँ? उस एकके इस प्रकार शरण हो। अभिप्राय यह कि मुझ परमेश्वरसे अन्य कुछ है ही नहीं ऐसा निश्चय कर। तुझ इस प्रकार निश्चयवालेको मैं अपना स्वरूप प्रत्यक्ष कराके? समस्त धर्माधर्मबन्धनरूप पापोंसे मुक्त कर दूँगा। पहले कहा भी है कि -- मैं हृदयमें स्थित हुआ प्रकाशमय ज्ञानदीपकसे (अज्ञानजनित अन्धकारका) नाश करता हूँ इसलिये तू शोक न कर अर्थात् चिन्ता मत कर।( शास्त्रके उपसंहारका प्रकरण ), यह विचार करना चाहिये कि इस गीताशास्त्रमें निश्चय किया हुआ? परम कल्याण ( मोक्ष ) का साधन ज्ञान है या कर्म? अथवा दोनों पू0 -- यह सन्देह क्यों होता है उ0 -- जिसको जानकर अमरता प्राप्त कर लेता है तदनन्तर मुझे तत्त्वसे जानकर मुझमें ही प्रविष्ट हो जाता है इत्यादि वाक्य तो केवल ज्ञानसे मोक्षकी प्राप्ति दिखला रहे हैं तथा तेरा कर्ममें ही अधिकार है तू कर्म ही कर इत्यादि वाक्य कर्मोंकी अवश्यकर्तव्यता दिखला रहे हैं। इस प्रकार ज्ञान और कर्म दोनोंकी कर्तव्यताका उपदेश होनेसे ऐसा संशय भी हो सकता है कि सम्भवतः दोनों समुच्चित ( मिलकर ) ही मोक्षके साधन होंगे। पू0 -- परंतु इस मीमांसाका फल क्या होगा उ0 -- यही कि इन तीनोंमेंसे किसी एकको ही परम कल्याणका साधन निश्चय करना। अतः इसकी विस्तारपूर्वक मीमांसा कर लेनी चाहिये।( सिद्धान्तका प्रतिपादन ), केवल आत्मज्ञान ही परम कल्याण ( मोक्ष ) का हेतु ( साधन ) है क्योंकि भेदप्रतीतिका निवर्तक होनेके कारण? कैवल्य ( मोक्ष ) की प्राप्ति ही उसकी अवधि है। आत्मामें क्रिया? कारक और फलविषयक भेदबुद्धि अविद्याके कारण सदासे प्रवृत्त हो रही है। कर्म मेरे हैं? मैं उनका कर्त्ता हूँ? मैं अमुक फलके लिये यह कर्म करता हूँ यह अविद्या अनादिकालसे प्रवृत्त हो रही है। यह केवल? ( एकमात्र ) अकर्ता? क्रियारहित और फलसे रहित आत्मा मैं हूँ? मुझसे भिन्न और कोई भी नहीं है ऐसा आत्मविषयक ज्ञान इस अविद्याका नाशक है क्योंकि यह उत्पन्न होते ही? कर्मप्रवृत्तिकी हेतुरूप भेदबुद्धिका नाश करनेवाला है। उपर्युक्त वाक्यमें तु शब्द दोनों पक्षोंकी निवृत्तिके लिये है अर्थात् मोक्ष न तो केवल कर्मसे मिलता है और न ज्ञानकर्मके समुच्चयसे ही। इस प्रकार तु शब्द दोनों पक्षोंका खण्डन करता है। मोक्ष अकार्य अर्थात् स्वतःसिद्ध है? इसलिये कर्मोंको उसका साधन मानना नहीं बन सकता क्योंकि कोई भी नित्य ( स्वतःसिद्ध ) वस्तु कर्म या ज्ञानसे उत्पन्न नहीं की जाती।, पू0 -- तब तो केवल ज्ञान भी व्यर्थ ही है उ0 -- यह बात नहीं है क्योंकि अविद्याका नाशक होनेके कारण उसकी मोक्षप्राप्तिरूप फलपर्यन्तता प्रत्यक्ष है। अर्थात् जैसे दीपकके प्रकाशका? रज्जु आदि वस्तुओंमें होनेवाली सर्पादिकी भ्रान्तिको और अन्धकारको? नष्ट कर देना ही फल है और जैसे उस प्रकाशका फल सर्पविषयक विकल्पको हटाकर? केवल रज्जुको प्रत्यक्ष कराके? समाप्त हो जाता है? वैसे ही अविद्यारूप अन्धकारके नाशक आत्मज्ञानका भी फल? केवल,आत्मस्वरूपको प्रत्यक्ष कराके ही समाप्त होता देखा गया है। जिनका फल प्रत्यक्ष है? ऐसी जो लकड़ीको चीरना अथवा अरणीमन्थनद्वारा अग्नि उत्पन्न करना आदि क्रियाएँ हैं? उनमें लगे हुए कर्ता आदि कारकोंकी? जैसे अलगअलग टुकड़े हो जाना? अथवा अग्नि प्रज्वलित हो जाना आदि फलसे अतिरिक्त किसी अन्य फल देनेवाले कर्ममें प्रवृत्ति नहीं हो सकती? वैसे ही जिसका फल प्रत्यक्ष है? ऐसी ज्ञाननिष्ठारूप क्रियामें लगे हुए ज्ञाता आदि कारकोंकी भी आत्मकैवल्यरूप फलसे अतिरिक्त फलवाले किसी अन्य कर्ममें प्रवृत्ति नहीं हो सकती। अतः ज्ञाननिष्ठा कर्मसहित नहीं हो सकती। यदि कहो कि भोजन और अग्निहोत्र आदि क्रियाओंके समान ( इसमें भी समुच्चय ) हो सकता है तो ऐसा कहना ठीक नहीं क्योंकि जिसका फल कैवल्य ( मोक्ष ) है? उस ज्ञानके प्राप्त होनेके पश्चात् कर्मफलकी इच्छा नहीं रह सकती? जैसे सब ओरसे परिपूर्ण जलाशयके प्राप्त हो जानेपर कूपतालाब आदिकी जलके लिये चाह नहीं रहता? उसी प्रकार मोक्ष जिसका फल है? ऐसे ज्ञानकी प्राप्ति होनेके बाद क्षणिक सुखरूप फलान्तरकी या उसकी साधनभूत क्रियाकी इच्छुकता नहीं रह सकती। क्योंकि जो मनुष्य राज्य प्राप्त करा देनेवाले कर्ममें लगा हुआ है उसकी प्रवृत्ति? क्षेत्रप्राप्ति ही जिसका फल है ऐसे कर्ममें नहीं होती और उस कर्मके फलकी इच्छा भी नहीं होता। सुतरां यह सिद्ध हुआ कि परम कल्याणका साधन न तो कर्म है और न ज्ञानकर्मका समुच्चय ही है तथा कैवल्य ( मोक्ष ) ही जिसका फल है? ऐसे ज्ञानको कर्मोंकी सहायता भी अपेक्षित नहीं है क्योंकि ज्ञान अविद्याका नाशक है इसलिये उसका कर्मोंसे विरोध है। यह प्रसिद्ध ही है कि अन्धकारका नाशक अन्धकार नहीं हो सकता। इसलिये केवल ज्ञान ही परम कल्याणका साधन है। पू0 -- यह सिद्धान्त ठीक नहीं क्योंकि नित्यकर्मोंके न करनेसे प्रत्यवाय होता है और मोक्ष नित्य है। भाव यह कि -- पहले जो यह कहा गया कि केवल ज्ञानसे ही मोक्ष मिलता है? ठीक नहीं क्योंकि वेदशास्त्रमें कहे हुए नित्यकर्मोंके न करनेसे नरकादिकी प्राप्तिरूप प्रत्यवाय होगा। यदि कहो कि ऐसा होनेसे तो कर्मोंसे छुटकारा ही न होगा? अतः मोक्षके अभावका प्रसङ्ग आ जायगा? तो ऐसा दोष नहीं है क्योंकि मोक्ष नित्यसिद्ध है। नित्यकर्मोंका आचरण करनेसे तो प्रत्यवाय न होगा? निषिद्ध कर्मोंका सर्वथा त्याग कर देनेसे अनिष्ट ( बुरे ) शरीरोंकी प्राप्ति न होगी? काम्यकर्मोंका त्याग कर देनेके कारण इष्ट ( अच्छे ) शरीरोंकी प्राप्ति न होगी तथा वर्तमान शरीरको उत्पन्न करनेवाले कर्मोंका? फलके उपभोगसे क्षय हो जानेपर? इस शरीरका नाश हो जानेके पश्चात्? दूसरे शरीरकी उत्पत्तिका कोई कारण नहीं रहनेसे तथा शरीरसम्बन्धी आसक्ति आदिके न करनेसे? जो स्वरूपमें स्थित हो जाना है वही कैवल्य है? अतः बिना प्रयत्नके ही कैवल्य सिद्ध हो जायगा। उ0 -- किंतु भूतपूर्व अनेक जन्मोंके किये हुए जो स्वर्गनरक आदिकी प्राप्तिरूप फल देनेवाले अनेक अनारब्धफल -- सञ्चित कर्म हैं? उनके फलका उपभोग न होनेके कारण? उनका तो नाश नहीं होगा -- ऐसा कहें तो पू0 -- यह बात नहीं है क्योंकि नित्यकर्मके अनुष्ठानमें होनेवाले परिश्रमरूप दुःखभोगको? उस कर्मोंके फलका उपभोग माना जा सकता है। अथवा प्रायश्चित्तकी भाँति नित्य कर्म भी पूर्वकृत पापका नाश करनेवाले मान लिये जायँगे तथा प्रारब्धकर्मका फलभोगसे नाश हो जायगा? फिर नये कर्मोंका आरम्भ न करनेसे कैवल्य,बिना यज्ञके सिद्ध हो जायगा। उ0 -- यह सिद्धान्त ठीक नहीं है क्योंकि उस ( परमात्मा ) को जानकर ही मनुष्य मृत्युसे तरता है मोक्षप्राप्तिके लिये दूसरा मार्ग नहीं है इस प्रकार मोक्षके लिये विद्याके अतिरिक्त अन्य मार्गका अभाव बतलानेवाली श्रुति है तथा जैसे चमड़ेकी भाँति आकाशको लपेटना असम्भव है? उसी प्रकार अज्ञानीकी मुक्ति असम्भव बतलानेवाली भी श्रुति है? एवं पुराण और स्मृतियोंमें भी यही कहा गया है कि ज्ञानसे ही कैवल्यकी प्राप्ति होती है। इसके सिवा ( उस सिद्धान्तमें ) जिनका फल मिलना आरम्भ नहीं हुआ ऐसे पूर्वकृत पुण्योंके नाशकी उत्पत्ति न होनेसे भी? यह पक्ष ठीक नहीं है। अर्थात् जिस प्रकार पूर्वकृत सञ्चित पुण्योंका होना सम्भव है? उसी प्रकार सञ्चित पापोंका होना भी सम्भव है ही अतः देहान्तरको उत्पन्न किये बिना उनका क्षय सम्भव न होनेसे ( इस पक्षके अनुसार ) मोक्ष सिद्ध नहीं हो सकेगा। इसके सिवा? पुण्यपापके कारणरूप राग? द्वेष और मोह आदि दोषोंका? बिना आत्मज्ञानके मूलोच्छेद होना सम्भव न होनेके कारण भी? पुण्यपापका उच्छेद होना सम्भव नहीं। तथा श्रुतिमें नित्यकर्मोंका पुण्यलोककी प्राप्तिरूप फल बतलाया जानेके कारण और अपने कर्मोंमें स्थित वर्णाश्रमावलम्बी इत्यादि स्मृतिवाक्योंद्वारा भी यही बात कही जानेके कारण भी कर्मोंका क्षय ( मानना ) सिद्ध नहीं होता। तथा जो यह कहते हैं कि नित्यकर्म दुःखरूप होनेके कारण पूर्वकृत पापोंका फल ही है? उनका अपने स्वरूपसे अतिरिक्त और कोई फल नहीं है क्योंकि श्रुतिमें उनका कोई फल नहीं बतलाया गया तथा उनका,विधान जीवननिर्वाह आदिके लिये किया गया है। उनका कहना ठीक नहीं है क्योंकि जो कर्म फल देनेके लिये प्रवृत्त नहीं हुए? उनका फल होना असम्भव है और नित्यकर्मके अनुष्ठानका परिश्रम? अन्य कर्मका फलविशेष है यह बात भी सिद्ध नहीं की जा सकेगी। तुमने जो यह कहा? कि पूर्वजन्मकृत पापकर्मोंका फल? नित्यकर्मोंके अनुष्ठानमें होनेवाले परिश्रमरूप दुःखके द्वारा भोगा जाता है? सो ठीक नहीं क्योंकि मरनेके समय जो कर्म भविष्यमें फल देनेके लिये अङ्कुरित नहीं हुए उनका फल दूसरे कर्मोंद्वारा उत्पन्न हुए शरीरमें भोगा जाता है? यह कहना युक्तियुक्त नहीं है। यदि ऐसा न हो तो स्वर्गरूप फलका भोग करनेके लिये अग्निहोत्रादि कर्मोंसे उत्पन्न हुए जन्ममें? नरकके कारणभूत कर्मोंका फल भोगा जाना भी? युक्तिविरुद्ध नहीं होगा। इसके सिवा यह ( नित्यकर्मके अनुष्ठानमें होनेवाला परिश्रमरूप दुःख ) पापोंकी फलरूप दुःखविशेष सिद्ध न हो सकनेके कारण भी तुम्हारा कहना ठीक नहीं है क्योंकि भिन्नभिन्न प्रकारके दुःखसाधनरूप फल देनेवाले? अनेक ( सञ्चित) पापोंके होनेकी सम्भावना होते हुए भी? नित्यकर्म अनुष्ठानके परिश्रममात्रको ही उन सबका फल मान लेनेपर? शीतोष्णादि द्वन्द्वोंकी अथवा रोगादिकी पीड़ासे होनेवाले दुःखोंको पापोंका फल नहीं माना जा सकेगा तथा यह हो भी कैसे सकता है कि नित्यकर्मके अनुष्ठानका परिश्रम ही पूर्वकृत पापोंका फल है? सिरपर पत्थर आदि ढोनेका दुःख उसका फल नहीं इसके सिवा? नित्यकर्मोंके अनुष्ठानसे होनेवाला परिश्रमरूप दुःख पूर्वकृत पापोंका फल है? यह कहना प्रकरणविरुद्ध भी है। पू0 -- कैसे उ0 -- जो पूर्वकृत पाप? फल देनेके लिये अङ्कुरित नहीं हुए हैं? उनका क्षय नहीं हो सकता ऐसा प्रकरण है? उसमें तुमने? फल देनेके लिये प्रस्तुत हुए पूर्वकृत पापोंका ही फल? नित्यकर्मोंके अनुष्ठानसे होनेवाला परिश्रमरूप दुःख बतलाया है? जो कर्म फल देनेके लिये प्रस्तुत नहीं हुए हैं उनका फल नहीं बतलाया। यदि तुम यह मानते हो? कि पूर्वकृत सभी पाप कर्म? फल देनेके लिये प्रवृत्त हो चुके हैं? तो फिर नित्यकर्मोंके अनुष्ठानका परिश्रमरूप दुःख ही उनका फल है? यह विशेषण देना अयुक्त ठहरता है। और नित्यकर्मविधायक शास्त्रको भी व्यर्थ माननेका प्रसङ्ग आ जाता है। क्योंकि फल देनेके लिये अङ्कुरित हुए पापोंका तो उपभोगसे ही क्षय हो जायगा ( उनके लिये नित्यकर्मोंकी क्या आवश्यकत'),
('shankaracharya-ht:source:18.66','Śaṅkarācārya','gita.18.66','hi','translation','ा है )। इसके सिवा ( वास्तवमें ) वेदविहित नित्यकर्मोंसे होनेवाला परिश्रमरूप दुःख यदि कर्मका फल हो तो वह उन ( विहित नित्यकर्मों ) का ही फल होना चाहिये क्योंकि वह व्यायाम आदिकी भाँति? उनके ही अनुष्ठानसे होता हुआ दिखलायी देता है? अतः यह कल्पना करना कि वह किसी अन्य कर्मका फल है युक्तियुक्त नहीं है। नित्यकर्मोंका विधान जीवनादिके लिये किया गया है इसलिये भी नित्यकर्मोंको प्रायश्चित्तकी भाँति पूर्वकृत पापोंका फल मानना युक्तियुक्त नहीं है। जिस पापकर्मके लिये जो प्रायश्चित विहित है? वह उस पापका फल नहीं है। तथापि यदि ऐसा मानें? कि प्रायश्चित्तरूप दुःख ( जिसके लिये प्रायश्चित्त किया जाय ) उस पापरूप निमित्तका ही फल होता है? तो जीवनादिके लिये किये जानेवाले नित्यकर्मोंका परिश्रमरूप दुःख भी? जीवन आदि हेतुओंका ही फल सिद्ध होगा क्योंकि नित्य और प्रायश्चित्त ये दोनों ही किसीनकिसी निमित्तसे किये जानेवाले हैं? इनमें कोई भेद नहीं है। इसके सिवा दूसरा दोष यह भी है कि नित्यकर्मके परिश्रमकी और काम्यअग्निहोत्रादि कर्मके परिश्रमकी समानता होनेके कारण? नित्यकर्मका परिश्रम ही पूर्वकृत पापका फल है? काम्यकर्मानुष्ठानका परिश्रमरूप दुःख उसका फल नहीं है? ऐसा माननेके लिये कोई विशेष कारण नहीं है? अतः वह काम्यकर्मका परिश्रमरूप दुःख भी? पूर्वकृत पापका ही फल माना जायगा। ऐसा होनेसे नित्यकर्मोंका फल नहीं बतलाया गया है और उनके अनुष्ठानका विधान किया गया है? उस विधानकी अन्य प्रकारसे उपपत्ति न होनेके कारण? नित्यकर्मोंके अनुष्ठानसे होनेवाला दुःख? पूर्वकृत पापोंका ही फल है? इस प्रकारकी जो अर्थापत्तिकी कल्पना की गयी थी? उसका खण्डन हो गया। इस तरह प्रकारान्तरसे नित्यकर्मोंके विधानकी अनुपपत्ति होनेसे और नित्यकर्मोंका अनुष्ठानसम्बन्धी परिश्रमरूप दुःखके सिवा दूसरा फल होता है? ऐसा अनुमान होनेसे भी ( यह पक्ष खण्डित हो जाता है )। इसके सिवा ऐसा माननेमें विरोध होनेके कारण भी ( यह पक्ष कट जाता है )। नित्यकर्मोंका अनुष्ठान करते हुए दूसरे कर्मोंका फल भोगा जाता है? ऐसा मान लेनेसे यह कहना होता है कि वह उपभोग ही नित्यकर्मका फल है। और साथ ही यह भी प्रतिपादन करते जाते हो कि नित्यकर्मका फल नहीं है अतः यह कथन परस्पर विरुद्ध होता है। इसके अतिरिक्त ( तुम्हारे मतानुसार ) काम्यअग्निहोत्रादिका अनुष्ठान करते हुए तन्त्रसे नित्यअग्निहोत्रादि भी उन्हींके साथ अनुष्ठित हो जाते हैं। अतः उस परिश्रमरूप दुःखभोगसे ही काम्यअग्निहोत्रादिका फल भी क्षीण हो जायगा क्योंकि वह उसके अधीन है। यदि ऐसा मानें कि काम्यअग्निहोत्रादिका स्वर्गादि प्राप्तिरूप दूसरा ही फल होता है तो उनके अनुष्ठानमें होनेवाले परिश्रमरूप दुःखको भी नित्यकर्मके परिश्रमसे भिन्न मानना आवश्यक होगा। परंतु प्रत्यक्ष प्रमाणसे विरुद्ध होनेके कारण यह नहीं हो सकता। क्योंकि काम्यकर्मोंके अनुष्ठानसे होनेवाले परिश्रमरूप दुःखसे? केवल नित्यकर्मअनुष्ठानमें होनेवाले परिश्रमरूप दुःखका भेद नहीं है। इसके सिवा दूसरी बात यह भी है कि जो कर्म न विहित हो और न प्रतिषिद्ध हो? वही तत्काल फल देनेवाला होता है? शास्त्रविहित या प्रतिषिद्ध कर्म तत्काल फल देनेवाला नहीं होता। यदि ऐसा होता तो स्वर्ग आदि लोकोंका प्रतिपादन करनेमें और अदृष्ट फलोंके बतलानेमें शास्त्रकी प्रवृत्ति नहीं होती। कर्मत्वमें किसी प्रकारका भेद न होनेपर तथा अंग और इतिकर्तव्यता आदिकी कोई विशेषता न होनेपर भी? केवल नित्यअग्निहोत्रादिका फल तो अनुष्ठानजनित परिश्रमरूप दुःखके उपभोगसे क्षय हो जाता है और फलेच्छुकतामात्रकी अधिकतासे काम्यअग्निहोत्रादिका स्वर्गादि महाफल होता है? ऐसी कल्पना नहीं की जा सकती। सुतरां नित्यकर्मोंका अदृष्ट फल नहीं होता यह बात कभी भी सिद्ध नहीं हो सकती। इसलिये यह सिद्ध हुआ कि अविद्यापूर्वक होनेवाले सभी शुभाशुभ कर्मोंका? अशेषतः नाश करनेवाला हेतु? विद्या ( ज्ञान ) ही है? नित्यकर्मका अनुष्ठान नहीं। क्योंकि सभी कर्म अविद्या और कामनामूलक हैं। ऐसा ही हमने सिद्ध किया है? कि अज्ञानीका विषय कर्म है और ज्ञानीका विषय सर्वकर्मसंन्यासपूर्वक ज्ञाननिष्ठा है। उभौ तौ न विजानीतः वेदाविनाशिनं नित्यम् ज्ञानयोगेन सांख्यानां कर्मयोगेन योगिनाम् अज्ञानां कर्मसङ्गिनाम् तत्त्ववित्तु गुणा गुणेषु वर्तन्त इति मत्वा न सज्जते सर्वकर्माणि मनसा संन्यस्यास्ते, नैव किंचित् करोमीति युक्तो मन्येत तत्त्ववित् इत्यादि वाक्योंके अर्थसे यही सिद्ध होता है? कि अज्ञानी ही,मैं कर्म करता हूँ ऐसा मानता है ( ज्ञानी नहीं )। आरुरुक्षुके लिये कर्म कर्तव्य बतलाये हैं और आरूढके लिये अर्थात् योगस्थ पुरुषके लिये उपशम कर्तव्य बतलाया है। तथा ( ऐसा भी कहा है कि ) तीनों प्रकारके अज्ञानी भक्त भी उदार हैं? पर ज्ञानी तो मेरा स्वरूप ही है? ऐसा मैं मानता हूँ। कर्म करनेवाले सकाम अज्ञानी लोग आवागमनको प्राप्त होते हैं और अनन्य भक्त नित्ययुक्त होकर चिन्तन करते हुए आत्मस्वरूप? आकाशके सदृश? मुझ निष्पाप परमात्माकी उपासना किया करते हैं। उनको मैं वह बुद्धियोग देता हैं जिससे वे मुझे प्राप्त हो जाते हैं इससे यह सिद्ध होता है कि कर्म करनेवाले अज्ञानी भगवान्को प्राप्त नहीं होते। भगवदर्थ कर्म करनेवाले जो युक्ततम होनेपर भी कर्मी होनेके नाते अज्ञानी हैं? वे चित्तसमाधानसे लेकर कर्मफलत्यागपर्यन्त उत्तरोत्तर हीन बतलाये हुए साधनोंसे युक्त होते हैं। तथा जो अनिर्देश्य अक्षरके उपासक हैं वे अद्वेष्टा सर्वभूतानाम् आदिसे लेकर? बारहवें अध्यायकी समाप्तिपर्यन्त बतलाये हुए साधनोंसे सम्पन्न और तेरहवें अध्यायसे लेकर तीन अध्यायोंमें बतलाये हुए ज्ञानसाधनोंसे भी युक्त होते हैं। अधिष्ठानादि पाँच जिसके कारण हैं? ऐसे समस्त कर्मोंका जो संन्यास करनेवाले हैं? जो आत्माके एकत्व और अकर्तृत्वको जाननेवाले हैं? जो ज्ञानकी परानिष्ठामें स्थित हो गये हैं? जो भगवत्स्वरूप और आत्माके एकत्वज्ञानकी शरण हो चुके हैं ऐसे भगवान्के तत्त्वको जाननेवाले परमहंस परिव्राजकोंको इष्टअनिष्ट और मिश्र -- ऐसा त्रिविध कर्मफल नहीं मिलता। इनसे अन्य जो संन्यास न करनेवाले कर्म परायण अज्ञानी हैं उनको कर्मका फल अवश्य भोगना पड़ता है यही गीताशास्त्रमें कहे हुए कर्तव्य और अकर्तव्यका विभाग है। पू0 -- सभी कर्मोंको अविद्यामूलक मानना युक्तिसङ्गत नहीं है। उ0 -- नहीं? ब्रह्महत्यादि निषिद्ध कर्मोंकी भाँति ( सभी कर्म अविद्यामलूक हैं ) नित्यकर्म यद्यपि शास्त्रप्रतिपादित हैं तो भी वे अविद्यायुक्त पुरुषके ही कर्म हैं। जैसे प्रतिषेधशास्त्रसे कहे हुए भी अनर्थके कारणरूप ब्रह्महत्यादि निषिद्ध कर्म अविद्या और कामनादि दोषोंसे युक्त पुरुषके द्वारा ही हो सकते हैं क्योंकि दूसरी तरह उनमें प्रवृत्ति नहीं हो सकती। उसी प्रकार नित्यनैमित्तिक और काम्य आदि कर्म भी? अविद्या और कामनासे युक्त मनुष्यसे ही हो सकते हैं। पू0 -- परंतु आत्माको शरीरसे पृथक् समझे बिना नित्यनैमित्तिक आदि कर्मोंमें प्रवृत्तिका होना असम्भव है। उ0 -- यह कहना ठीक नहीं? क्योंकि आत्मा जिसका कर्ता नहीं है ऐसे चलनरूप कर्ममें ( अज्ञानियोंकी ) मैं करता हूँ ऐसी प्रवृत्ति देखी जाती है। यदि कहो कि शरीर आदिमें जो अहंभाव है वह गौण है? मिथ्या नहीं है। तो ऐसा कहना ठीक नहीं? क्योंकि ऐसा माननेसे उनके कार्यमें भी गौणता सिद्ध होगी। पू0 -- जैसे हे पुत्र तू मेरा आत्मा ही है इस श्रुतिवाक्यके अनुसार? अपने पुत्रमें अहंभाव होता है तथा संसारमें भी जैसे यह गौ मेरा प्राण ही है इस प्रकार प्रिय वस्तुमें अहंभाव होता देखा जाता है? उसी प्रकार अपने शरीरादि संघातमें भी अहंभाव गौण ही है। यह प्रतीति मिथ्या नहीं है। मिथ्या प्रतीति तो वह है कि जो स्थाणु और पुरुषके भेदको न जानकर स्थाणुमें पुरुषकी प्रतीति होती है। उ0 -- ( यह कहना ठीक नहीं? क्योंकि ) गौण प्रयोग लुप्तोपमा शब्दद्वारा अधिकरणकी स्तुति करनेके लिये होता है? इसलिये गौण प्रतीतिसे मुख्यके कार्यकी सिद्धि नहीं होती। जैसे कोई कहे कि देवदत्त सिंह है? या बालक अग्नि है? तो उसका यह कहना? देवदत्त सिंहके सदृश क्रूर और बालक अग्निके समान पिङ्गल ( गौर ) वर्ण? इस प्रकारकी समानताके कारण देवदत्त और बालकरूप अधिष्ठानकी स्तुतिके लिये ही है। क्योंकि गौण शब्द या गौण ज्ञानसे कोई सिंहका कार्य ( किसीको भक्षण कर जाना ) या अग्निका कार्य ( किसीको जला डालना ) सिद्ध नहीं किया जा सकता। परंतु मिथ्या प्रत्ययका कार्य ( जन्ममरणरूप ) अनर्थ? ( मनुष्य ) अनुभव कर रहा है। इसके सिवा गौण प्रतीतिके विषयको मनुष्य ऐसा जानता भी है कि वास्तवमें यह देवदत्त सिंह नहीं है और यह बालक अग्नि नहीं है। ( यदि उपर्युक्त प्रकारसे शरीरादि संघातमें भी आत्मभाव गौण होता तो ) शरीरादिके संघातरूप गौण आत्माद्वारा किये हुए कर्म? अहंभावके मुख्य विषय आत्माके किये हुए नहीं माने जाते। क्योंकि गौण सिंह,( देवदत्त ) और गौण अग्नि ( बालक ) द्वारा किये हुए कर्म मुख्य सिंह और अग्निके नहीं माने जाते। तथा उस क्रूरता और पिङ्गलताद्वारा कोई मुख्य सिंह और मुख्य अग्निका कार्य नहीं किया जा सकता? क्योंकि वे केवल स्तुतिके लिये कहे हुए होनेसे हीनशक्ति हैं। जिनकी स्तुति की जाती है वे ( देवदत्त और बालक ) भी यह जानते हैं कि मैं सिंह नहीं हूँ? मैं अग्नि नहीं हूँ तथा सिंहका कर्म मेरा नहीं है? अग्निका कर्म मेरा नहीं है। इसी प्रकार ( यदि शरीर आदिमें गौण भावना होती तो ) संघातके कर्म मुझ मुख्य आत्माके नहीं हैं -- ऐसी ही प्रतीति होनी चाहिये थी? ऐसी नहीं कि मैं कर्ता हूँ? मेरे कर्म हैं ( सुतरां यह सिद्ध हुआ कि शरीरमें आत्मभाव गौण नहीं? मिथ्या है )। जो ऐसा कहते हैं कि अपने स्मृति? इच्छा और प्रयत्न इन कर्महेतुओंके द्वारा आत्मा कर्म किया करता है? उनका कथन ठीक नहीं क्योंकि ये सब मिथ्या प्रतीतिपूर्वक ही होनेवाले हैं। अर्थात् स्मृति? इच्छा और प्रयत्न आदि सब मिथ्या प्रतीतिसे होनेवाले? इष्टअनिष्टरूप अनुभूत कर्मफलजनित संस्कारोंको? लेकर ही होते हैं। जिस प्रकार इस वर्तमान जन्ममें धर्म? अधर्म और उनके फलोंका अनुभव ( सुखदुःख ) शरीरादि संघातमें आत्मबुद्धि और रागद्वेषादिद्वारा किये हुए होते हैं? वैसे ही भूतपूर्व जन्ममें और उससे पहलेके जन्मोंमें भी थे।इस न्यायसे यह अनुमान करना चाहिये कि यह बीता हुआ और आगे होनेवाला ( जन्ममरणरूप ) संसार अनादि एवं अविद्याकर्तृक ही है। इससे यह सिद्ध होता है? कि ज्ञाननिष्ठामें सर्वकर्मोंके संन्याससे संसारकी आत्यन्तिक निवृत्ति हो जाती है क्योंकि देहाभिमान अविद्यारूप है अतः उसकी निवृत्ति हो जानेपर शरीरान्तरकी प्राप्ति न होनेके कारण,( जन्ममरणरूप ) संसारकी प्राप्ति नहीं हो सकती। शरीरादि संघातमें जो आत्माभिमान है वह अविद्यारूप है क्योंकि संसारमें भी मैं गौ आदिसे अन्य हूँ और गौ आदि वस्तुएँ मुझसे अन्य हैं ऐसा जाननेवाला कोई भी मनुष्य उनमें ऐसी बुद्धि नहीं करता कि यह मैं हूँ। न जाननेवाला ही स्थाणुमें पुरुषकी भ्रान्तिके समान अविवेकके कारण? शरीरादि संघातमें मैं हूँ ऐसा आत्मभाव कर सकता है पर विवेकपूर्वक जानने'),
('shankaracharya-ht:source:18.66','Śaṅkarācārya','gita.18.66','hi','translation','वाला नहीं कर सकता। तथा पुत्रमें जो हे पुत्र तू मेरा आत्मा ही है ऐसी आत्मबुद्धि है? वह जन्यजनकसम्बन्धके कारण होनेवाली गौण बुद्धि है? उस गौण आत्मा ( पुत्र ) से भोजन आदिकी भाँति कोई मुख्य कार्य नहीं किया जा सकता। जैसे कि गौण सिंह और गौण अग्निरूप देवदत्त और बालकद्वारा? मुख्य सिंह और मुख्य अग्निका कार्य नहीं किया जा सकता। पू0 -- स्वर्गादि अदृष्ट पदार्थोंके लिये कर्मोंका विधान करनेवाली श्रुतिका प्रमाणत्व होनेसे? यह सिद्ध होता है कि शरीरइन्द्रिय आदि गौण आत्माओंके द्वारा मुख्य आत्माके कार्य किये जाते हैं। उ0 -- ऐसा कहना ठीक नहीं? क्योंकि उनका आत्मत्व अविद्याकर्तृक है। अर्थात् शरीर? इन्द्रिय आदि गौण आत्मा नहीं हैं ( किंतु मिथ्या हैं )। पू0 -- तो फिर ( इनमें आत्मभाव ) कैसे होता है उ0 -- मिथ्या प्रतीतिसे ही सङ्गरहित आत्माकी सङ्गति मानकर? इनसे आत्मभाव किया जाता है क्योंकि उस मिथ्याप्रतीतिके रहते हुए ही उनमें आत्मभावकी सत्ता है? उसके अभावसे आत्मभावनाका भी अभाव हो जाता है। अभिप्राय यह कि मूर्ख अज्ञानियोंका ही अज्ञानकालमें मैं बड़ा हूँ ? मैं गौर हूँ इस प्रकार शरीरइन्द्रिय आदिके संघातमें आत्माभिमान देखा जाता है। परंतु मैं शरीरादि संघातसे अलग हूँ ऐसा समझनेवाले विवेकशीलोंकी? उस समय शरीरादि संघातमें अहंबुद्धि नहीं होती। सुतरां? मिथ्याप्रतीतिके अभावसे देहात्मबुद्धिका अभाव हो जानेके कारण? यह सिद्ध होता है कि शरीरादिमें आत्मबुद्धि अविद्याकृत ही है? गौण नहीं। जिनकी समानता और विशेषता अलगअलग समझ ली गयी है? ऐसे सिंह और देवदत्तमें या अग्नि और बालक आदिमें ही गौण प्रतीति या गौण शब्दका प्रयोग हो सकता है जिनकी समानता और विशेषता नहीं समझी गयी उनमें नहीं। तुमने जो कहा कि श्रुतिको प्रमाणरूप माननेसे यह पक्ष सिद्ध होता है कि वह भी ठीक नहीं क्योंकि उसकी प्रमाणता अदृष्टविषयक है। अर्थात् प्रत्यक्षादि प्रमाणोंसे उपलब्ध न होनेवाले अग्निहोत्रादिके? साध्य? साधन और सम्बन्धके विषयमें ही श्रुतिकी प्रमाणता है प्रत्यक्षादि प्रमाणोंसे उपलब्ध हो जानेवालेविषयोंमें नहीं। क्योंकि श्रुतिकी प्रमाणता अदृष्ट विषयको दिखलानेके लिये ही है ( अर्थात् अप्रत्यक्ष विषयको बतलाना ही उसका काम है )। सुतरां देहादिसंघातमें? प्रत्यक्ष ही मिथ्या ज्ञानसे होनेवाली अहंप्रतीतिको? गौण मानना नहीं बन सकता। क्योंकि अग्नि ठण्डा है या अप्रकाशक है ऐसा कहनेवाली सैकड़ों श्रुतियाँ भी प्रमाणरूप नहीं मानी जा सकतीं। यदि श्रुति ऐसा कहे कि अग्नि ठण्डा है अथवा अप्रकाशक है तो ऐसा मान लेना चाहिये कि श्रुतिको कोई और ही अर्थ अभीष्ट है। क्योंकि अन्य प्रकारसे उसकी प्रामाणिकता सिद्ध नहीं हो सकती। परंतु प्रत्यक्षादि अन्य प्रमाणोंके विरुद्ध या श्रुतिके अपने वचनोंके विरुद्ध श्रुतिके अर्थकी कल्पना करना उचित नहीं। पू0 -- कर्म मिथ्या ज्ञानयुक्त पुरुषद्वारा ही किये जानेवाले हैं? ऐसा माननेसे वास्तवमें कर्ताका अभाव हो जानेके कारण श्रुतिकी अप्रमाणता ( अनर्थकता ) ही सिद्ध होती है ऐसा कहें तो उ0 -- नहीं? क्योंकि ब्रह्मविद्यामें उसकी सार्थकता सिद्ध होती है। पू0 -- कर्मविधायक श्रुतिकी भाँति ब्रह्मविद्याविधायक श्रुतिकी अप्रमाणताका प्रसङ्ग आ जायगा? ऐसा माने तो उ0 -- यह ठीक नहीं? क्योंकि उसका कोई बाधक प्रत्यय नहीं हो सकता। अर्थात् जैसे ब्रह्मविद्याविधायक श्रुतिद्वारा आत्मसाक्षात्कार हो जानेपर? देहादि संघातमें आत्मबुद्धि बाधित हो जाती है? वैसे आत्मामें ही होनेवाला आत्मभावका बोध किसीके द्वारा किसी भी कालमें किसी प्रकार भी बाधित नहीं किया जा सकता। क्योंकि वह आत्मज्ञान स्वयं ही फल है? उससे भिन्न किसी अन्यफलकी प्राप्ति नहीं है? जैसे अग्नि उष्ण और प्रकाशस्वरूप है। इसके सिवा ( वास्तवमें ) कर्मविधायक श्रुति भी अप्रामाणिक नहीं है? क्योंकि वह पूर्वपूर्व ( स्वाभाविक ) प्रवृत्तियोंको रोकरोककर उत्तरोत्तर नयीनयी ( शास्त्रीय ) प्रवृत्तिको उत्पन्न करती हुई ( अन्तमें अन्तःकरणकी शुद्धिद्वारा साधकको ) अन्तरात्माके सम्मुख करनेवाली प्रवृत्ति उत्पन्न करती है। अतः उपाय मिथ्या होते हुए भी? उपेयकी सत्यतासे? उसकी सत्यता ही है जैसे कि विधिवाक्यके अन्तमें कहे जानेवाले अर्थवादवाक्योंकी सत्यता मानी जाती है। लोकव्यवहारमें भी ( देखा जाता है कि ) उन्मत्त और बालक आदिको दूध आदि पिलानेके लिये चोटी बढ़ने आदिकी बात कही जाती है। तथा आत्मज्ञान होनेसे पहले? देहाभिमाननिमित्तक प्रत्यक्षादि प्रमाणोंके प्रमाणत्वकी भाँति प्रकारान्तरमें स्थित,( कर्मविधायक ) श्रुतियोंकी साक्षात् प्रमाणता भी सिद्ध होती है। तुम जो यह मानते हो? कि आत्मा स्वयं क्रिया न करता हुआ भी सन्निधिमात्रसे कर्म करता है? यही आत्माका मुख्य कर्तापन है। जैसे राजा स्वयं युद्ध न करते हुए भी सन्निधिमात्रसे ही अन्य योद्धाओंके युद्ध करनेसे राजा युद्ध करता है ऐसे कहा जाता है तथा वह जीत गया? हार गया ऐसे भी कहा जाता है। इसी प्रकार सेनापति भी केवल वाणीसे ही आज्ञा करता है। फिर भी राजा और सेनापतिका उस क्रियाके फलसे सम्बन्ध होता देखा जाता है। तथा जैसे ऋत्विक्के कर्म यजमानके माने जाते हैं? वैसे ही देहादि संघातके कर्म आत्मकृत हो सकते हैं? क्योंकि उनका फल आत्माको ही मिलता है। तथा जैसे भ्रामक ( भ्रमण करानेवाला चुम्बक ) स्वयं क्रिया नहीं करता? तो भी वह लोहेका चलानेवाला है? इसलिये उसीका मुख्य कर्तापन है? वैसे ही आत्माका मुख्य कर्तापन है। ऐसा मानना ठीक नहीं? क्योंकि ऐसा माननेसे न करनेवालेको कारक माननेका प्रसङ्ग आ जायगा। यदि कहो कि कारक तो अनेक प्रकारके होते हैं? तो भी तुम्हारा कहना ठीक नहीं क्योंकि राजा आदिका मुख्य कर्तापन भी देखा जाता है। अर्थात् राजा अपने निजी व्यापारद्वारा भी युद्ध करता है। तथा योद्धाओंसे युद्ध कराने और उन्हें धन देनेसे भी निःसन्देह उसका मुख्य कर्तापन है? उसी प्रकार जयपराजय आदि फलभोगोंमें भी उसकी मुख्यता है। वैसे ही यजमानका भी प्रधान आहुति स्वयं देनेके कारण और दक्षिणा देनेके कारण निःसन्देह मुख्य कर्तृत्व है। इससे यह निश्चित होता है कि क्रियारहित वस्तुमें जो कर्तापनका उपचार है वह गौण है। यदि राजा और यजमान आदिमें स्वव्यापाररूप मुख्य कर्तापन न पाया जाता तो उनका सन्निधिमात्रसे भी मुख्य कर्तापन माना जा सकता था? जैसे कि लोहेको चलानेमें चुम्बकका सन्निधिमात्रसे मुख्य कर्तापन माना जाता है? परंतु चुम्बककी भाँति राजा और यजमानका स्वव्यापार उपलब्ध न होता होऐसी बात नहीं है। सुतरां सन्निधिमात्रसे जो कर्तापन है वह भी गौण ही है। ऐसा होनेसे उसके फलका सम्बन्ध भी गौण ही होगा? क्योंकि गौण कर्ताद्वारा मुख्य कार्य नहीं किया जा सकता। अतः यह मिथ्या ही कहा जाता है कि निष्क्रिय आत्मा देहादिकी क्रियासे कर्ताभोक्ता हो जाता है। परंतु भ्रान्तिके कारण सब कुछ हो सकता है। जैसे कि स्वप्न और मायामें होता है। परंतु शरीरादिमें,आत्मबुद्धिरूप अज्ञानसन्ततिका विच्छेद हो जानेपर? सुषुप्ति और समाधि आदि अवस्थाओंमें कर्तृत्व? भोक्तृत्व आदि अनर्थ उपलब्ध नहीं होता। इससे यह सिद्ध हुआ? कि यह संसारभ्रम मिथ्या ज्ञाननिमित्तक ही है? वास्तविक नहीं? अतः पूर्ण तत्त्वज्ञानसे उसकी आत्यन्तिक निवृत्ति हो जाती है।'),
('shankaracharya-ht:source:18.67','Śaṅkarācārya','gita.18.67','hi','translation','।।18.67।।इस अठारहवें अध्यायमें समस्त गीताशास्त्रके अर्थका उपसंहार करके फिर विशेषरूपसे इस अन्तिम श्लोकमें शास्त्रके अभिप्रायको दृढ़ करनेके लिये संक्षेपसे उपसंहार करके? अब शास्त्रसम्प्रदायकी विधि बतलाते हैं। तेरे हितके लिये अर्थात् संसारका उच्छेद करनेके लिये? कहा हुआ यह शास्त्र? तपरहित मनुष्यको नहीं सुनाना चाहिये। इस प्रकार वाच्यम् इस व्यवधानयुक्त पदसे न का सम्बन्ध है। तपस्वी होनेपर भी जो अभक्त हो अर्थात् गुरु या देवतामें भक्ति रखनेवाला न हो उसे कभीकिसी अवस्थामें भी नहीं सुनाना चाहिये। भक्त और तपस्वी होकर भी जो शुश्रूषु ( सुननेका इच्छुक ) न हो उसे भी नहीं सुनाना चाहिये। तथा जो मुझ वासुदेवको प्राकृत मनुष्य मानकर? मुझमें दोषदृष्टि करता हो? मुझे ईश्वर न जाननेसे? मुझमें आत्मप्रशंसादि दोषोंका अध्यारोप करके? मेरे ईश्वरत्वको सहन न कर सकता हो वह भी अयोग्य है? उसे भी,( यह शास्त्र ) नहीं सुनाना चाहिये। अथपित्तिसे यह निश्चय होता है कि यह शास्त्र भगवान्में भक्ति रखनेवाले? तपस्वी? शुश्रूषायुक्त और दोषदृष्टिरहित पुरुषको ही सुनाना चाहिये। अन्य स्मृतियोंमें मेधावीको या तपस्वीको? इस प्रकार इन दोनोंका विकल्प देखा जाता है? इसलिये यह समझना चाहिये कि शुश्रूषा और भक्तियुक्त तपस्वीको अथवा इन तीनों गुणोंसे युक्त मेधावीको यह शास्त्र सुनाना चाहिये। शुश्रूषा और भक्तिसे रहित तपस्वी या मेधावी किसीको भी नहीं सुनाना चाहिये। भगवान्में दोषदृष्टि रखनेवाला तो यदि सर्वगुणसम्पन्न हो? तो भी उसे नहीं सुनाना चाहिये। गुरु शुश्रूषा और भक्तियुक्त पुरुषको ही सुनाना चाहिये। इस प्रकार यह शास्त्रसम्प्रदायकी विधि है।,'),
('shankaracharya-ht:source:18.68','Śaṅkarācārya','gita.18.68','hi','translation','।।18.68।।अब इस शास्त्रपरम्पराको चलानेवालोंके लिये फल बतलाते हैं --, जो मनुष्य? परम कल्याण जिसका फल है ऐसे इस उपर्युक्त कृष्णार्जुनसंवादरूप अत्यन्त गोप्य गीताग्रन्थको मुझमें भक्ति रखनेवाले भक्तोंमें सुनावेगा -- ग्रन्थरूपसे या अर्थरूपसे स्थापित करेगा? अर्थात् जैसे मैंने तुझे सुनाया है वैसे ही सुनावेगा -- यहाँ भक्तिका पुनः ग्रहण होनेसे यह पाया जाता है कि मनुष्य केवल भगवान्की भक्तिसे ही शास्त्र प्रदानका पात्र हो जाता है। कैसे सुनावेगा सो बतलाते हैं। मुझमें पराभक्ति करके? अर्थात् परमगुरु भगवान्की मैं यह सेवा करता हूँ ऐसा समझकर? ( जो इसे सुनावेगा ) उसका यह फल है कि वह मुझे ही प्राप्त हो जायगा अर्थात् निःसंदेह मुक्त हो जायगा -- इसमें संशय नहीं,करना चाहिये।'),
('shankaracharya-ht:source:18.69','Śaṅkarācārya','gita.18.69','hi','translation','।।18.69।।तथा --, उस गीताशास्त्रकी परम्परा चलानेवाले भक्तसे बढ़कर? मेरा अधिक प्रिय कार्य करनेवाला? मनुष्योंमें? कोई भी नहीं है। अर्थात् वह मेरा अतिशय प्रिय करनेवाला है? वर्तमान मनुष्योंमें उससे बढ़कर प्रियतम कार्य करनेवाला और कोई नहीं है? तथा भविष्यमें भी इस भूलोकमें उससे बढ़कर प्रियतर कोई दूसरा नहीं होगा।'),
('shankaracharya-ht:source:18.70','Śaṅkarācārya','gita.18.70','hi','translation','।।18.70।।जो भी कोई --, जो मनुष्य? हम दोनोंके संवादरूप इस धर्मयुक्त गीताग्रन्थको पढ़ेगा? उसके द्वारा यह होगा कि मैं ज्ञानयज्ञसे ( पूजित होऊँगा )? विधियज्ञ? जपयज्ञ? उपांशुयज्ञ और मानसयज्ञ -- इन चार यज्ञोंमें ज्ञानयज्ञ मानस है इसलिये श्रेष्ठतम है। अतः उस ज्ञानयज्ञकी समानतासे गीताशास्त्रके अध्ययनकी स्तुति करते हैं। अथवा यों समझो कि यह फलविधि है यानी इसका फल देवतादिविषयक ज्ञानयज्ञके समान होता है। उस अध्ययनसे मैं ( ज्ञानयज्ञद्वारा ) पूजित होता हूँ? ऐसा मेरा निश्चय है।,'),
('shankaracharya-ht:source:18.71','Śaṅkarācārya','gita.18.71','hi','translation','।।18.71।।तथा श्रोताको यह ( आगे बतलाया जानेवाला ) फल मिलता है --, जो मनुष्य? इस ग्रन्थको श्रद्धायुक्त और दोषदृष्टिरहित होकर केवल सुनता ही है? वह भी पापोंसे मुक्त होकर? पुण्यकारियोंके अर्थात् अग्निहोत्रादि श्रेष्ठकर्म करनेवालोंके? शुभ लोकोंको प्राप्त हो जाता है। अपिशब्दसे यह पाया जाता है कि अर्थ समझनेवालेकी तो बात ही क्या है। शिष्यने शास्त्रका अभिप्राय ग्रहण किया या नहीं यह विवेचन करनेके लिये भगवान् पूछते हैं। इसमें पूछनेवालेका यह अभिप्राय है कि शास्त्रका अभिप्राय श्रोताने ग्रहण नहीं किया है -- यह मालूम होनेपर? फिर किसी और उपायसे ग्रहण कराऊँगा।'),
('shankaracharya-ht:source:18.72','Śaṅkarācārya','gita.18.72','hi','translation','।।18.72।।इसके द्वारा आचार्यका या कर्तव्य प्रदर्शित किया जाता है? कि दूसरे उपायको स्वीकार करके किसी भी प्रकारसे? शिष्यको कृतार्थ करना चाहिये --, हे पार्थ क्या तूने मुझसे कहे हुए इस शास्त्रको एकाग्रचित्तसे सुना सुनकर बुद्धिमें स्थिर किया अथवा सुनाअनसुना कर दिया हे धनंजय क्या तेरा अज्ञानजनित मोह -- स्वाभाविक अविवेकताचित्तका मूढ़भाव सर्वथा नष्ट हो गया? जिसके लिये कि तेरा यह शास्त्रश्रवणविषयक परिश्रम और मेरा वक्तृत्वविषयक परिश्रम हुआ है।'),
('shankaracharya-ht:source:18.73','Śaṅkarācārya','gita.18.73','hi','translation','।।18.73।।अर्जुन बोला -- हे अच्युत मेरा अज्ञानजन्य मोह? जो कि समस्त संसाररूप अनर्थका कारण था और समुद्रकी भाँति दुस्तर था? नष्ट हो गया है। और हे अच्युत आपकी कृपाके आश्रित होकर मैंने आपकी कृपासे आत्मविषयक ऐसी स्मृति भी प्राप्त कर ली है कि जिसके प्राप्त होनेसे समस्त ग्रन्थियाँ -- संशय विच्छिन्न हो जाते हैं। इस मोहनाशविषयक प्रश्नोत्तरसे यह बात निश्चितरूपसे दिखलायी गयी है कि जो यह अज्ञानजनित मोहका नाश और आत्मविषयक स्मृतिका लाभ है? बस? इतना ही समस्त शास्त्रोंके अर्थज्ञानका फल है। इसी तरह ( छान्दोग्य ) श्रुतिमें भी मैं आत्माको न जाननेवाला शोक करता हूँ इस प्रकार प्रकरण उठाकर आत्मज्ञान होनेपर समस्त ग्रन्थियोंका विच्छेद बतलाया है। तथा हृदयकी ग्रन्थि विच्छिन्न हो जाती है वहाँ एकताका अनुभव करनेवालेको कैसा मोह और कैसा शोक इत्यादि मन्त्रवर्ण भी हैं। अब मैं संशयरहित हुआ आपकी आज्ञाके अधीन खड़ा हूँ। मैं आपका कहना करूँगा। अभिप्राय यह है कि मैं आपकी कृपासे कृतार्थ हो गया हूँ ( अब ) मेरा कोई कर्तव्य शेष नहीं है।'),
('shankaracharya-ht:source:18.74','Śaṅkarācārya','gita.18.74','hi','translation','।।18.74।।शास्त्रका अभिप्राय समाप्त हो चुका। अब कथाका सम्बन्ध दिखलानेके लिये संजय बोला --, इस प्रकार मैंने यह उपर्युक्त अद्भुत -- अत्यन्त विस्मयकारक रोमाञ्च करनेवाला श्रीवासुदेव भगवान् और महात्मा अर्जुनका संवाद सुना।'),
('shankaracharya-ht:source:18.75','Śaṅkarācārya','gita.18.75','hi','translation','।।18.75।।और इसे --, मैंने ( भगवान् ) व्यासजीकी कृपासे उनसे दिव्यचक्षु पाकर इस परम गुह्य संवादको और परम योगको,( सुना ) अथवा ( यों समझो कि ) योगविषयक होनेसे यह संवाद ही योग है? अतः इस संवादरूप योगको मैंने योगेश्वर भगवान् श्रीकृष्णसे? साक्षात् स्वयं कहते हुए सुना है? परम्परासे नहीं।'),
('shankaracharya-ht:source:18.76','Śaṅkarācārya','gita.18.76','hi','translation','।।18.76।।हे राजन् धृतराष्ट्र केशव और अर्जुनके इस ( परम ) पवित्र -- सुननेमात्रसे पापोंका नाश करनेवाले? अद्भुत संवादको सुनकर और बारम्बार स्मरण करके? मैं प्रतिक्षण बारम्बार हर्षित हो रहा हूँ।'),
('shankaracharya-ht:source:18.77','Śaṅkarācārya','gita.18.77','hi','translation','।।18.77।।तथा हे राजन् हरिके उस अति अद्भुत विश्वरूपको भी बारम्बार याद करके? मुझे बड़ा आश्चर्य हो रहा है और मैं बारम्बार हर्षित हो रहा हूँ।');
