INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('shankaracharya-ht:source:18.78','Śaṅkarācārya','gita.18.78','hi','translation','।।18.78।।बहुत कहनेसे क्या समस्त योग और उनके बीज उन्हींसे उत्पन्न हुए हैं? अतः भगवान् योगेश्वर हैं। जिस पक्षमें ( वे ) सब योगोंके ईश्वर श्रीकृष्ण हैं तथा जिस पक्षमें गाण्डीव धनुर्धारी पृथापुत्र अर्जुन है? उस पाण्डवोंके पक्षमें ही श्री? उसीमें विजय? उसीमें विभूति अर्थात् लक्ष्मीका विशेष विस्तार और वहीं अचल नीति है -- ऐसा मेरा मत है।'),
